"""
Shared TSP engine.

Holds the IntersectionController and CorridorCoordinator classes plus every
AAPI callback implementation (AAPILoad, AAPIInit, AAPIManage, ...), used by
both kg/ and logan_road_new/. This is the code that was previously
copy-pasted between the two corridors' intersection_controller.py files and
kept drifting out of sync.

Each corridor's own intersection_controller.py still defines its own config
constants (CONTROL_MODE, logging flags, reward weights, etc. -- the things
batch_runner.py regex-patches in place before each run) and does its own
imports (AAPI, numpy, intersection_configs, ...). It then calls
bind_config(globals()) once, which copies all of that into this module's
globals so the classes/functions below see them as their own module-level
names -- the same "propagate into globals()" pattern AAPIInit already used
for run_config.py-sourced flags, just extended one level further.

Aimsun's "API script" setting can point at EITHER a corridor's own
intersection_controller.py (which does the bind_config() call itself, as
described above) OR at this file directly. In the second case nothing has
called bind_config() yet, so AAPILoad() below self-bootstraps: it detects
which corridor is currently active (see _detect_corridor_dir) and executes
that corridor's intersection_controller.py itself, which reaches its own
"import shared_tsp_engine.engine; bind_config(globals())" footer exactly as
if Aimsun had loaded it directly. Either script path works for both corridors.
"""

import os
import sys
import glob
import importlib.util as _importlib_util

# Bump this stamp whenever engine.py is edited so a full-Aimsun-restart reload
# can be verified from the [LOAD] line in the run log. If the log shows an older
# stamp than this, Aimsun is running a CACHED copy of the module (re-running the
# script alone does NOT reload it — the whole Aimsun process must be quit).
ENGINE_BUILD = "2026-10-01T16:00-opp-offset-push"
try:
    from AAPI import *
except Exception:
    pass  # not running inside Aimsun (e.g. static analysis / py_compile)
try:
    from . import specialized_modes as _spm
except ImportError:
    import specialized_modes as _spm

try:
    try:
        from .milp_mpc_controller import (
            BusState as _MPCBusState,
            MPCPrediction as _MPCPrediction,
            create_milp_mpc_controller,
        )
        _mpc_module = sys.modules.get('shared_tsp_engine.milp_mpc_controller')
    except Exception:
        # Aimsun can execute this file as a script, without package context.
        # Resolve the sibling file directly instead of relying on a bare import
        # whose result depends on Aimsun's working directory.
        _mpc_path = os.path.join(
            os.path.dirname(os.path.abspath(__file__)), 'milp_mpc_controller.py')
        _mpc_spec = _importlib_util.spec_from_file_location(
            'shared_tsp_engine.milp_mpc_controller', _mpc_path)
        if _mpc_spec is None or _mpc_spec.loader is None:
            raise ImportError(f'cannot load MPC controller from {_mpc_path}')
        _mpc_module = _importlib_util.module_from_spec(_mpc_spec)
        sys.modules['shared_tsp_engine.milp_mpc_controller'] = _mpc_module
        _mpc_spec.loader.exec_module(_mpc_module)
        _MPCBusState = _mpc_module.BusState
        _MPCPrediction = _mpc_module.MPCPrediction
        create_milp_mpc_controller = _mpc_module.create_milp_mpc_controller

    # Keep compatibility with older cached integration code that imports the
    # sibling as a top-level module.
    if _mpc_module is not None:
        sys.modules['milp_mpc_controller'] = _mpc_module
    _MILP_MPC_AVAILABLE = True
    _MILP_MPC_IMPORT_ERROR = ''
except Exception as _milp_mpc_import_error:
    _MILP_MPC_AVAILABLE = False
    _MILP_MPC_IMPORT_ERROR = str(_milp_mpc_import_error)


_CONFIG_BOUND = False
_milp_mpc_controller = None
_milp_mpc_last_step = -1

MILP_MPC_HORIZON_S = 300.0
MILP_MPC_REPLAN_S = 30.0
MILP_MPC_TIME_LIMIT_S = 1.5
MILP_MPC_EPSILON_LATE_S = 60.0
MILP_MPC_EPSILON_Z4_S = 90.0
MILP_MPC_Z4_BASELINE = 380.0
MILP_MPC_ACTION_S = 10.0

# Typed config keys that external patchers sometimes write as STRING literals
# ('False' / '0.0'). A str is always truthy, so MARK_DETECTION_POINTS='False'
# silently re-enabled per-run plotting, and STATUS_DASHBOARD_INTERVAL_S='0.0'
# crashed AAPIPostManage on its first str>int comparison (2026-08-24, KG).
# bind_config coerces these to their proper types after binding.
_TYPED_CONFIG_KEYS = {
    'BXT_FREEZE_ON_EVAL': bool,
    'STATUS_DASHBOARD_INTERVAL_S': float,
    'MARK_DETECTION_POINTS': bool,
    'TRACK_BUS_POSITIONS': bool,
    'OVERLAY_DETECTIONS_ON_MAP': bool,
}


def _coerce_typed_config():
    """Repair stringified boolean/numeric config values in module globals."""
    g = globals()
    for _k, _t in _TYPED_CONFIG_KEYS.items():
        _v = g.get(_k)
        if isinstance(_v, str):
            try:
                g[_k] = (float(_v) if _t is float
                         else (_v.strip().lower() == 'true'))
            except Exception:
                pass


def bind_config(ns: dict):
    """Copy the calling corridor module's globals into this module's globals.

    Call once, after the corridor file has defined its config constants and
    done its imports, before Aimsun invokes any AAPI callback re-exported
    from this module. ns must include '_CORRIDOR_DIR' (the corridor's own
    directory) -- functions below that used to resolve paths via __file__
    now use _CORRIDOR_DIR instead, since __file__ here would otherwise
    resolve to this shared module's own location, not the corridor's.

    Dunder keys (__name__, __file__, __spec__, ...) are skipped so binding a
    whole module namespace doesn't overwrite this module's own identity.
    """
    globals().update({
        k: v for k, v in ns.items()
        if not (k.startswith('__') and k.endswith('__'))
    })
    globals()['_CONFIG_BOUND'] = True
    _coerce_typed_config()


def _detect_corridor_dir():
    """
    Figure out which corridor folder (kg/ or logan_road_new/) is the currently
    active Aimsun model, for when this file is loaded directly instead of via
    a corridor's own intersection_controller.py.

    Primary signal: each corridor folder holds its own .ang/.sang model, and
    Aimsun keeps a *.ang.lck / *.sang.lck lock file next to it while that
    model is open -- the same convention _preflight_model_db_health() already
    relies on to pick "the active companion DB" over stale leftovers. Whichever
    corridor folder has the most recently modified lock file wins.

    Fallback: match the current working directory against a corridor folder,
    in case Aimsun didn't leave a lock file behind in this run mode.
    """
    _repo_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    _corridors = ("kg", "logan_road_new")

    _locked = []
    for _c in _corridors:
        _dir = os.path.join(_repo_root, _c)
        _locks = glob.glob(os.path.join(_dir, "*.ang.lck")) + glob.glob(os.path.join(_dir, "*.sang.lck"))
        if _locks:
            _locked.append((_dir, max(os.path.getmtime(_p) for _p in _locks)))
    if _locked:
        _locked.sort(key=lambda t: t[1], reverse=True)
        return _locked[0][0]

    _cwd = os.path.abspath(os.getcwd())
    for _c in _corridors:
        _dir = os.path.join(_repo_root, _c)
        if os.path.normcase(_cwd) == os.path.normcase(os.path.abspath(_dir)):
            return _dir

    return None


def _register_module_aliases():
    """
    Make sure sys.modules['shared_tsp_engine.engine'] refers to THIS module
    instance before the corridor shim is exec'd.

    When Aimsun loads engine.py directly (API script pointed at this file),
    the module Aimsun holds is NOT registered under the canonical package
    name. The corridor shim's footer then runs
    `import shared_tsp_engine.engine as _engine` -- without this alias that
    import builds a SECOND engine module and bind_config() configures the
    wrong copy, leaving the copy Aimsun actually calls with no VERBOSE /
    datetime / _bus_type_needs_recheck / ... in its globals (NameError storm
    at runtime). Aliasing first guarantees the shim's import and its
    bind_config(globals()) land on this exact instance.
    """
    import types
    _g = globals()
    _this = sys.modules.get(__name__)
    if _this is None or getattr(_this, "__dict__", None) is not _g:
        # Aimsun exec'd this file without a proper sys.modules entry -- build
        # a proxy module whose attribute lookups read this module's globals,
        # so both `import ... as _engine` and `from ... import AAPILoad` work.
        class _EngineAlias(types.ModuleType):
            def __getattr__(self, _k):
                try:
                    return _g[_k]
                except KeyError:
                    raise AttributeError(_k)
        _this = _EngineAlias("shared_tsp_engine.engine")
    _pkg = sys.modules.get("shared_tsp_engine")
    if _pkg is None:
        _pkg = types.ModuleType("shared_tsp_engine")
        _pkg.__path__ = [os.path.dirname(os.path.abspath(__file__))]
        sys.modules["shared_tsp_engine"] = _pkg
    _pkg.engine = _this
    sys.modules["shared_tsp_engine.engine"] = _this


def _self_bootstrap_from_direct_load():
    """
    Called from AAPILoad() the first time, only if bind_config() has not
    already been called by a corridor's own intersection_controller.py.
    Detects the active corridor and executes its intersection_controller.py
    (config constants + imports + its own bind_config(globals()) footer),
    which populates this module's globals exactly as the normal load path does.
    """
    _corridor_dir = _detect_corridor_dir()
    if not _corridor_dir:
        AKIPrintString(
            "[ENGINE] FATAL: shared_tsp_engine/engine.py was loaded directly but "
            "could not detect which corridor (kg/ or logan_road_new/) is active "
            "-- no *.ang.lck/*.sang.lck found under either, and cwd matches neither. "
            "Cannot self-configure."
        )
        raise RuntimeError("shared_tsp_engine.engine: corridor auto-detection failed")

    # The shim's `import shared_tsp_engine.engine` must resolve to THIS module
    # instance, not a fresh second copy (see _register_module_aliases).
    _register_module_aliases()

    # The shim imports its corridor-local siblings (Simulation_Stats,
    # intersection_configs, dynaropac_controller) by bare name. When Aimsun
    # loads the shim itself those resolve because the script's own directory
    # is on sys.path -- replicate that here since the script Aimsun loaded is
    # this file, in a different directory.
    if _corridor_dir not in sys.path:
        sys.path.insert(0, _corridor_dir)

    _cfg_path = os.path.join(_corridor_dir, "intersection_controller.py")
    AKIPrintString(f"[ENGINE] Direct load detected -- self-configuring from {_cfg_path}")
    with open(_cfg_path, "r", encoding="utf-8") as _f:
        _cfg_src = _f.read()
    _ns = {"__file__": _cfg_path, "__name__": "intersection_controller"}
    exec(compile(_cfg_src, _cfg_path, "exec"), _ns)
    # The shim's own footer calls bind_config(globals()) with _ns, which
    # (thanks to the aliasing above) updates *this* module's globals. Fallback:
    # if a stale shim without the footer was exec'd, bind its namespace here.
    if not _CONFIG_BOUND:
        AKIPrintString(
            "[ENGINE] WARNING: corridor shim did not call bind_config() -- "
            "binding its namespace directly."
        )
        bind_config(_ns)


# Defaults for knobs that only one corridor's file declares today
# (kg/intersection_controller.py patches REWARD_TSP_ENABLE_GE/INS via
# batch_runner.py's set_reward_weights() and sets TSP_COOLDOWN_OVERRIDE_S;
# logan_road_new/intersection_controller.py doesn't declare them). bind_config
# overrides these when a corridor's own globals include the name; corridors
# that don't declare it keep the behaviour they already had (both actions
# enabled, no cooldown override).
REWARD_TSP_ENABLE_GE = True
REWARD_TSP_ENABLE_INS = True
TSP_COOLDOWN_OVERRIDE_S = None

# =============================================================================
# PARETO-BASED ACTION SELECTION (weight-free) + Z4 THROUGHPUT CONSTRAINT
#
# Replaces the weighted-sum scalarisation
#     R(a) = alpha*bus_saved - beta*other_inc - gamma*side_inc
# with dominance-based selection over the measured per-candidate objective
# vector, so no preference weights (REWARD_ALPHA/BETA/GAMMA, WOBJ_*) are
# needed at decision time:
#
#   1. Z4 feasibility gate (hard constraint, epsilon-constraint method):
#      an action is feasible only if its net corridor vehicle-time impact
#      (bus veh-s saved minus main+side veh-s added) is >= -Z4_TOLERANCE_VEH_S.
#      Rationale: Z4 (total corridor travel time == vehicles serviced within
#      the horizon) is held as a constraint, never traded away -- we do not
#      minimise Z1/Z2/Z3 if doing so cuts off total vehicles serviced.
#      NO_ACTION has a zero impact vector, so the feasible set is never empty.
#   2. Pareto filtering: among feasible candidates, keep the non-dominated
#      set under (bus_saved max, other_inc min, side_inc min).
#   3. Weight-free pick from the front: all components share the same unit
#      (pax-s), so the physical net total  other_inc + side_inc - bus_saved
#      (the Z1 delta) orders the front without any preference weighting.
#      NO_ACTION nets exactly 0, so TSP fires only when strictly
#      net-beneficial in total pax-s -- the paper's balance-gate principle
#      generalised to the whole non-dominated set.
#
# Refs (shared_tsp_engine/*.pdf): Cherukuri & Lala 2025 (Pareto-optimal
# vector rewards, dominance/front recovery instead of scalar reduction);
# Siddique, Li & Cao, RLJ 2025 (multi-policy MORL: dominance-filtered
# selection over vector Q-values / convex coverage sets).
#
# TODO(phase-timings-as-actions): extend the candidate set beyond GE/INS to
# full per-phase TIMING actions -- re-splitting green durations across the
# cycle (each phase's duration as a continuous decision variable, cf. the
# paper's "Variable Phase Action and Phase Skipping" section) -- so the
# Pareto front is built over phase-timing plans, not just bus-phase
# extensions/insertions. Requires: per-phase delay estimates from the same
# D/D/1 kinematics used by _reward_evaluate_ge, plus a cycle-conservation
# check (sum of re-split greens == cycle - lost time).
# =============================================================================
PARETO_SELECTION_MODE = True    # weight-free Pareto selection (all strategies)
Z4_CONSTRAINT_MODE    = True    # epsilon-constraint ON (passenger-seconds;
                                # protection now lives inside the reward
                                # (anticipation penalty + cost UCB + adherence
                                # weights). Flag kept for ablation runs.
# Tolerance is now in PASSENGER-seconds (net = bus_saved - other_inc -
# side_inc; occupancies already baked in upstream, including the schedule-
# adherence multiplier on bus benefits). The old veh-s key still works as a
# fallback so existing run_configs keep running. Rationale for the change:
# veh-s divided out occupancy, so Z4 vetoed exactly the passenger-favourable
# trades the objective exists to make (400 pax-s bus saved vs 180 pax-s car
# cost scored -140 veh-s and died). Same numbers now live in the objective's
# own currency.
Z4_TOLERANCE_PAX_S    = None    # None -> fall back to Z4_TOLERANCE_VEH_S value
Z4_TOLERANCE_VEH_S    = 90.0

# Adaptive epsilon-bound: every Z4_REFRESH_S the tolerance multiplier is
# re-fitted to observed veto pressure -- if most interventions are being
# gated, the bound relaxes (TSP is being strangled); if almost none are, it
# tightens back toward 1.0.  The bound therefore tracks corridor conditions
# instead of being a fixed constant.
Z4_ADAPTIVE_BOUND   = True
Z4_REFRESH_S        = 60.0
Z4_BOUND_MULT       = 1.0     # effective multiplier on the base tolerance
_Z4_EVALS = [0, 0]            # [evaluated, gated] since last refresh

# =============================================================================
# Two-way through-band floors (paper Eqs prog_in/band_*) — online mirror.
# The MILP designs the stagger for both directions with directional through-
# bands b+/- floored at B+/-min. Online there are no phase-offset clocks, so
# this mirrors the constraint in TSP-induced relative terms: per-junction
# accumulated clock shifts (GE/INS +1 s per active step, ER -1, GR/NA 0 —
# paper offset_state) are tracked per signal cycle, and the worst neighbour-
# pair relative shift prices both directional bands as b = G^b - |shift|.
# An action whose shift would newly push either band below its floor is
# vetoed to NO_ACTION at the execution funnel.
# Documented limits: (1) the background fixed-time plan is the design, i.e.
# baseline relative mismatch is 0 and only TSP-induced shifts are policed;
# absolute two-way design quality stays an offline problem. (2) Lags cancel
# in relative terms, so no spacing/speed data is needed. (3) Consequence:
# b+ == b- always here; the two floors remain separately tunable policy.
# (4) Accumulators are estimates reset each signal cycle; drift from
# late-vetoed actions is bounded by the reset. (5) Phase-based
# IntersectionController funnel only; GroupBased controllers decide
# elsewhere (extension point). OFF by default: zero behaviour change unless
# TWOWAY_BAND_MODE is set in run_config.
# =============================================================================
TWOWAY_BAND_MODE = False
B_PLUS_MIN       = 0.0
B_MINUS_MIN      = 0.0
TWOWAY_GREEN_S   = 35.0
_twoway_shift = {}   # iid -> [accumulated clock-shift s, epoch index]


def _twoway_cycle_s():
    try:
        _c = float(globals().get('TSP_CYCLE_LENGTH_OVERRIDE_S') or 135.0)
        return _c if _c > 0 else 135.0
    except Exception:
        return 135.0


def _twoway_accum(iid, epoch):
    _e = _twoway_shift.get(iid)
    if _e is None or _e[1] != epoch:
        _e = [0.0, epoch]
        _twoway_shift[iid] = _e
    return _e


def _twoway_wrap(x, C):
    try:
        return ((float(x) + C / 2.0) % C) - C / 2.0
    except Exception:
        return 0.0


def _twoway_band_check(iid, shift_s, time_s):
    """Two-way through-band floors, online mirror of paper Eqs prog_in/band_*.

    Returns (allow, detail). Fail-open True on any internal error so a
    diagnostics feature can never wedge control.
    """
    try:
        if not bool(globals().get('TWOWAY_BAND_MODE', False)):
            return True, ""
        C = _twoway_cycle_s()
        try:
            G = float(globals().get('TWOWAY_GREEN_S', 35.0) or 35.0)
        except Exception:
            G = 35.0
        if not (G > 0):
            return True, ""
        try:
            f_plus = float(globals().get('B_PLUS_MIN', 0.0) or 0.0)
            f_minus = float(globals().get('B_MINUS_MIN', 0.0) or 0.0)
        except Exception:
            f_plus, f_minus = 0.0, 0.0
        try:
            epoch = int(float(time_s or 0.0) // C)
        except Exception:
            epoch = 0
        try:
            _trial = _twoway_accum(iid, epoch)[0] + float(shift_s or 0.0)
        except Exception:
            return True, ""

        def _acc(_j):
            _e = _twoway_shift.get(_j)
            return _e[0] if (_e is not None and _e[1] == epoch) else 0.0

        _worst_now, _worst_new, _wpair = 0.0, 0.0, None
        try:
            _coords = list(globals().get('corridor_coordinators', []) or [])
        except Exception:
            _coords = []
        for _cc in _coords:
            try:
                _route = list(getattr(_cc, 'route_inter_ids', []) or [])
            except Exception:
                continue
            for _a, _b in zip(_route, _route[1:]):
                try:
                    _va, _vb = _acc(_a), _acc(_b)
                    _m_now = abs(_twoway_wrap(_vb - _va, C))
                    _ta = _trial if _a == iid else _va
                    _tb = _trial if _b == iid else _vb
                    _m_new = abs(_twoway_wrap(_tb - _ta, C))
                except Exception:
                    continue
                if _m_now > _worst_now:
                    _worst_now = _m_now
                if _m_new > _worst_new:
                    _worst_new = _m_new
                    _wpair = (_a, _b)
        _b_new = G - _worst_new
        # Veto only actions that NEWLY breach (or deepen a breach):
        # pre-existing divergence is not this action's fault.
        if (_b_new < f_plus or _b_new < f_minus) and \
                _worst_new > _worst_now + 1e-9:
            return False, ("band+=%.1f/%.1f band-=%.1f/%.1f worst-pair=%s shift=%+.1fs"
                           % (_b_new, f_plus, _b_new, f_minus,
                              _wpair, float(shift_s or 0.0)))
        return True, ""
    except Exception:
        return True, ""


def _z4_base_tol():
    v = globals().get("Z4_TOLERANCE_PAX_S")
    if v is not None:
        return float(v)
    return float(globals().get("Z4_TOLERANCE_VEH_S", 90.0) or 90.0)


def _z4_eff_tol():
    return max(0.0, _z4_base_tol() * Z4_BOUND_MULT)


def _pareto_select_candidates(cands, bus_occ, car_occ):
    """
    Genuinely multi-objective Pareto selection (ideal-point compromise)
    with Z4 throughput constraint.

    Objectives (all minimised):
      Z1 = net passenger delay at THIS junction, pax-s
              = other_inc + side_inc - bus_saved
      Z2 = downstream-junction impact, pax-s  (coordination; negative = benefit)
      Z3 = residual bus lateness, seconds      (schedule deviation after action)

    These are genuinely different quantities (passenger-seconds here,
    passenger-seconds at the NEXT junction, and schedule-deviation seconds),
    so the non-dominated front is NOT degenerate: an action that saves delay
    here but pushes the bus into a downstream red, or clears bus lateness at a
    small delay cost, is a real trade-off rather than a linear combination.

    cands: list of dicts with keys
        action    -- token, e.g. "NO_ACTION", "GE_10", "INS_15"
        bus_saved -- pax-s bus benefit vs NO_ACTION   (maximise)
        other_inc -- pax-s cost to other main traffic (minimise)
        side_inc  -- pax-s cost to side-street traffic (minimise)
        downstream-- pax-s impact at the next managed junction (minimise;
                     negative = coordination benefit). Optional; default 0.
        sigma_out -- residual bus lateness in seconds after the action
                     (minimise). Optional; default = incoming lateness.
    NO_ACTION must be present with a (0, 0, 0, sigma_in) vector.

    Selection: filter the non-dominated front over (Z1, Z2, Z3), normalise
    each objective by its range across the front, then pick the candidate with
    the smallest weighted distance to the ideal point (weights WOBJ_ALPHA /
    WOBJ_BETA / WOBJ_GAMMA from the controller file: 1.0 / 1.0 / 0.1, i.e.
    pure passenger delay with a small schedule term). Ties break on Z1
    (net pax-s).
    The Z4 throughput constraint is applied to the FINAL choice only (the
    closest Z4-feasible front candidate; NO_ACTION is always feasible), the
    same balance-gate semantics as the scalar path — it never pre-filters the
    candidate pool.

    Returns (chosen_cand_dict, info_str).
    """
    if not cands:
        return None, "no candidates"
    _bus_occ = max(float(bus_occ or 0.0), 1.0)
    _car_occ = max(float(car_occ or 0.0), 1.0)

    #     -- 1. Z4 net corridor PASSENGER-time (pax-s) marked on every candidate --
    # Z4 is NOT used to pre-filter the pool: pre-filtering removed the high-
    # benefit / high-disruption candidates (e.g. CELLQLEARN-DP insertions) that
    # the specialised modes contribute, collapsing every strategy onto the same
    # conservative standard candidates.  Instead the front is computed over ALL
    # candidates and the Z4 gate is applied to the FINAL choice (step 3), the
    # same balance-gate semantics as the scalar (non-Pareto) path.
    #
    # UNITS REFORMULATION (paper-aligned): Z4 was previously net VEHICLE-seconds
    # (occupancy divided out), which let it veto passenger-favourable trades --
    # e.g. save 400 pax-s of bus delay at 180 pax-s of car cost scored
    # 10-150 = -140 veh-s and died. All candidate quantities are ALREADY in
    # pax-s (occupancies baked in upstream, including schedule-adherence
    # scaling of bus benefits), so the constraint now stays in the objective's
    # own currency: net = bus_saved - other_inc - side_inc, compared against
    # Z4_TOLERANCE_PAX_S (falls back to the legacy VEH_S number when absent).
    for c in cands:
        z4_net_pax_s = (float(c.get("bus_saved", 0.0))
                        - float(c.get("other_inc", 0.0))
                        - float(c.get("side_inc", 0.0)))
        c["_z4_net_pax_s"] = z4_net_pax_s

    _z4_ok = lambda c: (not Z4_CONSTRAINT_MODE) or c["action"] == "NO_ACTION" \
        or c.get("_z4_net_pax_s", 0.0) >= -_z4_eff_tol()
    n_gated = sum(1 for c in cands if not _z4_ok(c))

    # -- 2. Objective vector (all minimise) ---------------------------------
    def _vec(c):
        return (float(c.get("other_inc", 0.0)) + float(c.get("side_inc", 0.0))
                - float(c.get("bus_saved", 0.0)),   # Z1 net pax-s
                float(c.get("downstream", 0.0)),    # Z2 downstream pax-s
                float(c.get("sigma_out", 0.0)))     # Z3 lateness s

    def _dominates(u, v):
        return all(a <= b for a, b in zip(u, v)) and any(a < b for a, b in zip(u, v))

    front = [c for c in cands
             if not any(_dominates(_vec(o), _vec(c)) for o in cands if o is not c)]
    if not front:                      # defensive; cannot happen with NO_ACTION present
        front = list(cands)

    # -- 3. Z4-feasibility gate applied to the final choice -------------------
    # Ideal-point compromise over the front; the Z4 hard constraint then
    # selects the closest Z4-feasible front candidate (NO_ACTION is always
    # feasible).  This is the same gate semantics as the scalar path: the
    # constraint never shapes the candidate pool, only the final decision.
    _ideal = [min(_vec(c)[k] for c in front) for k in range(3)]
    _rng = [max(_vec(c)[k] for c in front) - _ideal[k] for k in range(3)]
    _w = [float(globals().get('WOBJ_ALPHA', 1.0)),
          float(globals().get('WOBJ_BETA', 1.0)),
          float(globals().get('WOBJ_GAMMA', 1.0))]
    if sum(_w) <= 0.0:
        _w = [1.0, 1.0, 1.0]
    # WOBJ_Zk_SCALE normalise the raw objective magnitudes (Z1 pax·s vs Z2
    # downstream pax·s vs Z3 lateness s) so the weights act on comparable
    # units.  Default 1.0 (no-op) preserves legacy behaviour.
    _wsc = [float(globals().get('WOBJ_Z1_SCALE', 1.0) or 1.0),
            float(globals().get('WOBJ_Z2_SCALE', 1.0) or 1.0),
            float(globals().get('WOBJ_Z3_SCALE', 1.0) or 1.0)]

    def _dist(c):
        v = _vec(c)
        d = 0.0
        for k in range(3):
            if _rng[k] > 1e-9:
                d += _w[k] * (v[k] - _ideal[k]) / _rng[k] / max(_wsc[k], 1e-9)
        return d

    feasible_front = [c for c in front if _z4_ok(c)]
    if feasible_front:
        chosen = min(feasible_front, key=lambda c: (_dist(c), _vec(c)[0]))
    else:
        chosen = min(front, key=lambda c: (_dist(c), _vec(c)[0]))

    info = (f"pareto: {len(cands)} cands, {n_gated} Z4-gated, "
            f"front={len(front)} -> {chosen['action']} "
            f"(net={_vec(chosen)[0]:+.1f} pax-s, "
            f"down={_vec(chosen)[1]:+.1f} pax-s, "
            f"sigma_out={_vec(chosen)[2]:+.1f} s, "
            f"z4_net={chosen.get('_z4_net_pax_s', 0.0):+.1f} pax-s)")
    return chosen, info


# =============================================================================
# SHARED UTILITY / HELPER FUNCTIONS
# Moved here from kg/ and logan_road_new/ intersection_controller.py (were byte-
# identical copy-pasted duplicates in both files before this migration). They
# reference corridor-specific globals (LOG_DIR, _DET_CSV, VERBOSE, etc.) by name,
# already available here via bind_config(), the same as every other function in
# this module.
# =============================================================================

def _finite_xy(x_val, y_val):
    try:
        x_f = float(x_val)
        y_f = float(y_val)
    except (TypeError, ValueError):
        return None
    if not (math.isfinite(x_f) and math.isfinite(y_f)):
        return None
    if x_f == 0.0 and y_f == 0.0:
        return None
    return (x_f, y_f)

def _extract_xy_from_point_like(obj):
    if obj is None:
        return None
    if isinstance(obj, (tuple, list)) and len(obj) >= 2:
        return _finite_xy(obj[0], obj[1])

    for _x_attr, _y_attr in (
        ('x', 'y'),
        ('getX', 'getY'),
        ('xCoord', 'yCoord'),
        ('getx', 'gety'),
    ):
        _x = getattr(obj, _x_attr, None)
        _y = getattr(obj, _y_attr, None)
        if _x is None or _y is None:
            continue
        try:
            _x = _x() if callable(_x) else _x
            _y = _y() if callable(_y) else _y
        except Exception:
            continue
        _xy = _finite_xy(_x, _y)
        if _xy is not None:
            return _xy
    return None

def _extract_xy_from_section_info(sec_info):
    if sec_info is None:
        return None
    for _x_attr, _y_attr in (
        ('xSection', 'ySection'),
        ('xSectionTo', 'ySectionTo'),
        ('xcoordTo', 'ycoordTo'),
        ('xTo', 'yTo'),
        ('xDestination', 'yDestination'),
        ('xEnd', 'yEnd'),
        ('x', 'y'),
    ):
        _xy = _finite_xy(getattr(sec_info, _x_attr, None), getattr(sec_info, _y_attr, None))
        if _xy is not None:
            return _xy
    return None

def _extract_xy_from_catalog_object(obj):
    if obj is None:
        return None

    for _meth in ('getPosition', 'getCenter', 'getCentroid', 'center', 'centroid'):
        _fn = getattr(obj, _meth, None)
        if not callable(_fn):
            continue
        try:
            _xy = _extract_xy_from_point_like(_fn())
        except Exception:
            _xy = None
        if _xy is not None:
            return _xy

    _xy = _extract_xy_from_point_like(obj)
    if _xy is not None:
        return _xy

    for _child_meth in ('getNodes', 'getChildNodes', 'getInternalNodes', 'getSubNodes'):
        _fn = getattr(obj, _child_meth, None)
        if not callable(_fn):
            continue
        try:
            _children = list(_fn() or [])
        except Exception:
            continue
        _pts = []
        for _child in _children:
            _cxy = _extract_xy_from_catalog_object(_child)
            if _cxy is not None:
                _pts.append(_cxy)
        if _pts:
            return (
                sum(_p[0] for _p in _pts) / len(_pts),
                sum(_p[1] for _p in _pts) / len(_pts),
            )

    return None

def _resolve_junction_xy_from_model(node_id: int, incoming_sections=None):
    try:
        from PyANGKernel import GKSystem as _GKS
        _model = _GKS.getSystem().getActiveModel()
        if _model is None:
            return None
        _catalog = _model.getCatalog()
        _candidate_ids = []
        if node_id and node_id > 0:
            _candidate_ids.append(int(node_id))
        for _sec_id in incoming_sections or []:
            try:
                _si = AKIInfNetGetSectionANGInf(int(_sec_id))
                _node_to = int(getattr(_si, 'idNodeTo', 0) or 0)
                if _node_to > 0 and _node_to not in _candidate_ids:
                    _candidate_ids.append(_node_to)
            except Exception:
                continue

        for _cid in _candidate_ids:
            try:
                _obj = _catalog.find(_cid)
            except Exception:
                _obj = None
            _xy = _extract_xy_from_catalog_object(_obj)
            if _xy is not None:
                return _xy
    except Exception:
        return None
    return None

def _network_stats_section_ids():
    global _net_stats_sections_cache
    if _net_stats_sections_cache is not None:
        return list(_net_stats_sections_cache)

    _secs: set = set()
    try:
        _n_secs = int(AKIInfNetNbSectionsANG())
        for _si in range(_n_secs):
            _sid = int(AKIInfNetGetSectionANGId(_si))
            if _sid > 0:
                _secs.add(_sid)
    except Exception:
        pass

    if not _secs:
        for _iid_data in getattr(stats, '_inter', {}).values():
            for _sec in _iid_data.get('main_sections', []):
                if isinstance(_sec, int) and _sec > 0:
                    _secs.add(_sec)
            for _sec in _iid_data.get('side_sections', []):
                if isinstance(_sec, int) and _sec > 0:
                    _secs.add(_sec)
        for _ctrl in controllers.values():
            for _sec in getattr(_ctrl, 'incoming_sections', []):
                if _sec and _sec > 0:
                    _secs.add(int(_sec))

    _net_stats_sections_cache = _secs
    return list(_secs)

def _mark_detection_point(junction_id: int, veh_id: int, x: float, y: float,
                          sim_time: float, tier: str, meta: dict = None):
    """
    Record the first detection event for this (junction, vehicle) pair.

    1. Writes a row to detection_points.csv immediately (includes signal_phase
       and bus_phase so the green-wave plot can show green/red status).
    2. Appends a GeoJSON feature (flushed to .geojson in AAPIFinish).
    3. Attempts to colour the vehicle bright red in the Aimsun animation.
       The colour API may not exist in all Aimsun builds — failure is silent.
    """
    global _mark_calls_total, _mark_calls_written
    _mark_calls_total += 1

    if not MARK_DETECTION_POINTS:
        return
    meta = dict(meta or {})
    key = (junction_id, veh_id)
    _last_t = _marked_detections.get(key, -9999.0)
    if not meta.get("force_write") and sim_time - _last_t < _MARK_DET_REARM_S:
        return
    _marked_detections[key] = sim_time
    _mark_calls_written += 1

    # ── Capture current signal phase and configured bus phase ─────────────────
    _signal_phase = -1
    try:
        _signal_phase = ECIGetCurrentPhase(junction_id)
    except Exception:
        pass
    _bus_phase = -1
    try:
        _cfg = INTERSECTIONS_CONFIG.get(junction_id, {})
        _bus_phase = int(_cfg.get("BusPhase", -1) or -1)
    except Exception:
        pass
    _phase_start_t = -1.0
    try:
        _phase_start_t = float(ECIGetStartingTimePhase(junction_id))
    except Exception:
        pass

    meta = dict(meta or {})
    _prearm_status = str(meta.get("prearm_status", "") or "")
    _prearm_eta_s = meta.get("prearm_eta_s", "")
    _prearm_eta_abs_s = meta.get("prearm_eta_abs_s", "")
    _prearm_fired_t = meta.get("prearm_fired_t", "")
    _prearm_resolved_t = meta.get("prearm_resolved_t", "")
    _prearm_note = str(meta.get("prearm_note", "") or "")
    _focus_role = "none"
    _focus_active = 1 if _focus_bus_id > 0 else 0
    if _focus_active:
        _focus_role = "focused_bus" if veh_id == _focus_bus_id else "blocked_by_focus"
    if str(tier).startswith("focus_acquire"):
        _focus_role = "focus_acquire"
    elif str(tier).startswith("focus_suppress"):
        _focus_role = "focus_suppress"
    _focus_held_s = (
        max(0.0, float(sim_time) - float(_focus_start_t))
        if _focus_active and _focus_start_t >= 0.0 else 0.0
    )

    # ── 1. CSV ────────────────────────────────────────────────────────────────
    # Look up the junction centroid so the map can overlay intersection markers.
    _jct_entry = (_jct_xy_cache or {}).get(junction_id)
    _jct_cx = f"{_jct_entry[0]:.3f}" if _jct_entry else ""
    _jct_cy = f"{_jct_entry[1]:.3f}" if _jct_entry else ""
    write_header = not os.path.isfile(_DET_CSV)
    try:
        with open(_DET_CSV, "a", newline="", encoding="utf-8") as f:
            w = csv.writer(f)
            if write_header:
                w.writerow(["sim_time_s", "junction_id", "veh_id",
                             "x", "y", "tier", "signal_phase", "bus_phase",
                             "phase_start_t", "jct_x", "jct_y",
                             "prearm_status", "prearm_eta_s",
                             "prearm_eta_abs_s", "prearm_fired_t",
                             "prearm_resolved_t", "prearm_note",
                             "focus_active", "focus_bus_id", "focus_jct_id",
                             "focus_start_t", "focus_held_s", "focus_role"])
            w.writerow([f"{sim_time:.1f}", junction_id, veh_id,
                        f"{x:.3f}", f"{y:.3f}", tier, _signal_phase, _bus_phase,
                        f"{_phase_start_t:.1f}", _jct_cx, _jct_cy,
                        _prearm_status, _prearm_eta_s, _prearm_eta_abs_s,
                        _prearm_fired_t, _prearm_resolved_t, _prearm_note,
                        _focus_active, _focus_bus_id, _focus_jct_id,
                        f"{_focus_start_t:.1f}", f"{_focus_held_s:.1f}",
                        _focus_role])
    except Exception as _e:
        log_to_file(f"[MARK] CSV write failed: {_e}", force=True)

    # ── 2. GeoJSON feature accumulation ───────────────────────────────────────
    _geojson_features.append({
        "type": "Feature",
        "geometry": {"type": "Point", "coordinates": [x, y]},
        "properties": {
            "junction_id": junction_id,
            "veh_id":      veh_id,
            "sim_time_s":  round(sim_time, 1),
            "tier":        tier,
            "prearm_status": _prearm_status,
            "focus_role": _focus_role,
        },
    })

    # ── 3. Colour vehicle red in Aimsun animation ─────────────────────────────
    # AKIVehSetVehicleColor(veh_id, R, G, B) is available in Aimsun Next ≥22.
    # Looked up via globals() so static analysis doesn't flag an undefined name
    # (it arrives via `from AAPI import *`).  Falls back silently if absent.
    try:
        _color_fn = globals().get("AKIVehSetVehicleColor")
        if _color_fn is not None:
            _color_fn(veh_id, 255, 0, 0)   # bright red
    except Exception:
        pass

    log_to_file(
        f"[MARK] jct={junction_id} v={veh_id} tier={tier} "
        f"xy=({x:.1f},{y:.1f}) t={sim_time:.1f}s"
    )

def _record_wave_event(time_s: float, group_name: str, event: str,
                       source_jct: int = -1, target_jct: int = -1,
                       veh_id: int = -1, eta_s: float = -1.0,
                       lead_s: float = -1.0, note: str = "", **extra):
    """Append a structured coordinator event row for post-run diagnostics."""
    _row = {
        "sim_time_s": round(float(time_s), 1),
        "group": str(group_name),
        "event": str(event),
        "source_jct": int(source_jct),
        "target_jct": int(target_jct),
        "veh_id": int(veh_id),
        "eta_s": round(float(eta_s), 1) if eta_s is not None else -1.0,
        "lead_s": round(float(lead_s), 1) if lead_s is not None else -1.0,
        "note": str(note),
    }
    for _k, _v in extra.items():
        if _v is None:
            continue
        if isinstance(_v, bool):
            _row[str(_k)] = int(_v)
            continue
        try:
            _fv = float(_v)
            _row[str(_k)] = round(_fv, 4)
        except Exception:
            _row[str(_k)] = str(_v)
    _wave_events.append(_row)

def _record_objective_trace(row: dict):
    """Append one objective-evaluation trace row for GE/INS diagnostics."""
    global _objective_trace_header_written
    _fields = [
        "sim_time_s", "junction_id", "veh_id",
        "mode", "decision", "reason",
        "current_phase", "bus_phase",
        "bus_eta_s", "time_to_bp_s", "natural_end_s", "next_red_s",
        "ge_lb_s", "ge_ub_s", "opt_ge_s",
        "bp_lb_s", "bp_ub_s", "opt_bp_s",
        "wave_active", "focus_bus_id", "note",
    ]
    _row = {}
    for _f in _fields:
        _row[_f] = row.get(_f, "")
    try:
        _write_header = (not _objective_trace_header_written) and (not os.path.isfile(_OBJECTIVE_TRACE_CSV))
        with open(_OBJECTIVE_TRACE_CSV, "a", newline="", encoding="utf-8") as _f_obj:
            _w = csv.DictWriter(_f_obj, fieldnames=_fields)
            if _write_header:
                _w.writeheader()
                _objective_trace_header_written = True
            _w.writerow(_row)
    except Exception as _e:
        log_to_file(f"[OBJ TRACE] write failed: {_e}")

def _track_all_bus_positions(time: float, jct_xy: dict):
    """
    Log every PT-line bus position every _BUS_TRACK_INTERVAL_S seconds.

    Writes: sim_time_s, veh_id, x, y, nearest_jct, dist_m, in_zone, zone_radius_m, event

    event column: 'track' (normal), 'zone_enter' (first time inside zone),
                  'zone_exit' (left zone).

    jct_xy: {junction_id: (x, y, detection_zone_m)} — pre-built from controllers.
    If empty, still records raw bus positions with nearest_jct=-1.
    """
    global _bus_track_last_t, _bus_track_header_written, _presence_snapshot_header_written
    global _bus_zone_state
    global _bus_seen_ids, _bus_last_nearest_jct, _bus_line_id
    global _tracking_zone_presence, _bus_observed_jcts
    global _active_corridor_bus_count
    global _bus_xy   # module-level persistent dict — coordinator reads this
    if time - _bus_track_last_t < _BUS_TRACK_INTERVAL_S:
        return
    _bus_track_last_t = time
    # Rebuild the live zone-presence snapshot from scratch each interval
    _tracking_zone_presence.clear()

    rows = []
    _bus_xy = {}  # veh_id -> (x,y) — replaces module-level dict each scan
    active_veh_ids = set()
    try:
        n_lines = AKIPTGetNumberLines()
        for li in range(n_lines):
            line_id = AKIPTGetIdLine(li)
            n_veh = AKIGetNbVehiclesFollowingPTLine(line_id)
            for vi in range(n_veh):
                veh_id = AKIGetVehicleFollowingPTLine(line_id, vi)
                try:
                    inf = AKIPTVehGetInf(veh_id)
                    if getattr(inf, 'report', -1) < 0:
                        continue
                    bx = float(getattr(inf, 'xCurrentPos', 0.0) or 0.0)
                    by = float(getattr(inf, 'yCurrentPos', 0.0) or 0.0)
                    if bx == 0.0 and by == 0.0:
                        continue
                    bspd = float(getattr(inf, 'CurrentSpeed', 40.0) or 40.0)
                except Exception:
                    continue

                active_veh_ids.add(veh_id)
                _bus_xy[veh_id] = (bx, by)
                # Record which PT line this bus is currently following
                _bus_line_id[veh_id] = line_id

                # ── Section-based detection ───────────────────────────────────
                # If the bus is on a section that feeds a corridor junction,
                # fire an auto-detection even if it hasn't entered the spatial zone.
                # Only mark the NEAREST mapped junction to avoid simultaneous
                # detections at multiple junctions from a shared section.
                try:
                    _bus_sec = int(getattr(inf, 'idSection', -1))
                    if _bus_sec > 0 and _bus_sec in _sec_to_corridor_jct:
                        _sec_jcts = _sec_to_corridor_jct[_bus_sec]
                        _eligible_sec_jcts = []
                        for _jid in _sec_jcts:
                            if _jid in _bus_observed_jcts.get(veh_id, set()):
                                continue
                            _zst = _bus_zone_state.get((veh_id, _jid), "out")
                            if _zst != "out":
                                continue
                            _eligible_sec_jcts.append(_jid)

                        if len(_eligible_sec_jcts) == 1:
                            _mark_detection_point(_eligible_sec_jcts[0], veh_id, bx, by, time, "track-section")
                        elif len(_eligible_sec_jcts) > 1 and jct_xy:
                            _nearest_sec_jct = min(
                                _eligible_sec_jcts,
                                key=lambda _j: math.sqrt(
                                    (bx - jct_xy[_j][0])**2 + (by - jct_xy[_j][1])**2
                                ) if _j in jct_xy else 1e9
                            )
                            _mark_detection_point(_nearest_sec_jct, veh_id, bx, by, time, "track-section")
                        elif len(_eligible_sec_jcts) > 1:
                            _mark_detection_point(_eligible_sec_jcts[0], veh_id, bx, by, time, "track-section")
                except Exception:
                    pass

                if jct_xy:
                    # ── Pre-scan: find the nearest junction newly entering zone ──
                    # When junction detection zones overlap (junctions ~300 m apart,
                    # zones 250 m radius), a single bus can transition from out→in for
                    # multiple junctions in the same scan step.  Restrict zone_enter
                    # events (detection-point marking, route tracking, bus-TT entry)
                    # to the NEAREST newly-entered junction so the bus appears at one
                    # junction at a time and journey charts don't show teleportation.
                    _new_zone_entries_this_step = []
                    _dist_cache_this_bus = {}
                    for _jid_pre, (_jx_pre, _jy_pre, _zr_pre) in jct_xy.items():
                        _d_pre = math.sqrt((bx - _jx_pre)**2 + (by - _jy_pre)**2)
                        _dist_cache_this_bus[_jid_pre] = _d_pre
                        if _d_pre <= _zr_pre and not _bus_zone_state.get((veh_id, _jid_pre), False):
                            _new_zone_entries_this_step.append((_d_pre, _jid_pre))
                    _nearest_new_entry_jct = (
                        min(_new_zone_entries_this_step, key=lambda _x: _x[0])[1]
                        if _new_zone_entries_this_step else None
                    )

                    # Check zone status for EVERY junction (not just nearest)
                    for jid, (jx, jy, zr) in jct_xy.items():
                        d = _dist_cache_this_bus.get(jid) or math.sqrt((bx - jx)**2 + (by - jy)**2)
                        now_in = d <= zr
                        zkey = (veh_id, jid)
                        was_in = _bus_zone_state.get(zkey, False)
                        event = "track"
                        
                        # ── Zone occupancy timeout (120s maximum per bus per junction) ──
                        # Prevents buses from staying "near jct" indefinitely if they slow
                        # down or loop within the detection zone.
                        _ZONE_OCCUPANCY_TIMEOUT_S = 120.0
                        zone_entry_t = _bus_zone_entry_time.get(zkey)
                        if zone_entry_t is not None and time - zone_entry_t > _ZONE_OCCUPANCY_TIMEOUT_S:
                            # Force zone exit if bus has been in zone too long
                            now_in = False
                        
                        if now_in:
                            # Keep live zone-presence snapshot current so that
                            # detect_bus / _detect_bus can use it as Tier 0.
                            _tracking_zone_presence.setdefault(jid, {})[veh_id] = (bx, by, bspd)
                        if now_in and not was_in:
                            _bus_zone_state[zkey] = True
                            _bus_zone_entry_time[zkey] = time  # Record entry time for timeout
                            # Only fire zone_enter events for the nearest newly-entered
                            # junction.  Other overlapping zones are marked in-state so
                            # they don't re-fire, but their events are suppressed so the
                            # bus appears sequentially on the journey chart.
                            if jid == _nearest_new_entry_jct:
                                event = "zone_enter"
                                # ── Record observed corridor-junction route ───────
                                try:
                                    obs = _bus_observed_jcts.setdefault(veh_id, [])
                                    if not obs or obs[-1] != jid:
                                        obs.append(jid)
                                except Exception:
                                    pass
                                # ── Auto-detection point ──────────────────────────
                                try:
                                    _mark_detection_point(jid, veh_id, bx, by, time, "track-zone")
                                except Exception:
                                    pass
                                # ── Bus TT zone-entry ─────────────────────────────
                                try:
                                    stats.record_pt_bus_detection(jid, veh_id, time)
                                except Exception:
                                    pass
                        elif not now_in and was_in:
                            event = "zone_exit"
                            _bus_zone_state[zkey] = False
                            # Clear zone entry time on exit
                            if zkey in _bus_zone_entry_time:
                                del _bus_zone_entry_time[zkey]
                            # ── Bus TT zone-exit ──────────────────────────────
                            try:
                                stats.record_pt_bus_exit(jid, veh_id, time)
                            except Exception:
                                pass
                        # Only log zone events for non-nearest junctions
                        # Always log one row per bus for nearest junction
                        if event != "track":
                            rows.append((
                                f"{time:.1f}", veh_id,
                                f"{bx:.1f}", f"{by:.1f}",
                                jid, f"{d:.0f}",
                                1 if now_in else 0, f"{zr:.0f}", event,
                            ))

                    # Find nearest junction for the main tracking row
                    best_jct = -1
                    best_dist = 1e9
                    best_zone = 0.0
                    for jid, (jx, jy, zr) in jct_xy.items():
                        d = math.sqrt((bx - jx)**2 + (by - jy)**2)
                        if d < best_dist:
                            best_dist = d
                            best_jct = jid
                            best_zone = zr
                    in_zone = 1 if best_dist <= best_zone else 0
                else:
                    best_jct = -1
                    best_dist = -1.0
                    best_zone = 0.0
                    in_zone = 0
                rows.append((
                    f"{time:.1f}", veh_id,
                    f"{bx:.1f}", f"{by:.1f}",
                    best_jct, f"{best_dist:.0f}",
                    in_zone, f"{best_zone:.0f}", "track",
                ))
    except Exception:
        pass

    # Supplement/fallback: some models do not expose PT-line followers reliably,
    # or may omit injected buses from PT APIs. Scan live section vehicles by
    # inferred bus type to capture missing buses.
    if BUS_TRACK_SUPPLEMENT_NETWORK_SCAN or not rows:
        try:
            _bus_type_pos = int(getattr(stats, '_bus_pos', -1) or -1)
        except Exception:
            _bus_type_pos = -1
        if _bus_type_pos > 0:
            _scan_secs = set()
            try:
                _scan_secs.update(int(_s) for _s in _network_stats_section_ids() if int(_s) > 0)
            except Exception:
                pass
            if not _scan_secs:
                for _ctrl in controllers.values():
                    for _s in getattr(_ctrl, 'incoming_sections', []):
                        if _s and _s > 0:
                            _scan_secs.add(int(_s))
                try:
                    for _d in getattr(stats, '_inter', {}).values():
                        for _s in _d.get('all_sections', []):
                            if _s and _s > 0:
                                _scan_secs.add(int(_s))
                except Exception:
                    pass

            seen_fallback = set()
            _supplement_only_missing = bool(rows)
            for _sec in _scan_secs:
                try:
                    _n = max(int(AKIVehStateGetNbVehiclesSection(_sec, True)), 0)
                except Exception:
                    _n = 0
                for _i in range(_n):
                    try:
                        _inf = AKIVehStateGetVehicleInfSection(_sec, _i)
                        _vid = int(getattr(_inf, 'idVeh', -1) or -1)
                        _typ = int(getattr(_inf, 'type', -1) or -1)
                        if _vid <= 0 or _typ != _bus_type_pos or _vid in seen_fallback:
                            continue
                        if _supplement_only_missing and _vid in _bus_xy:
                            continue
                        _bx = float(getattr(_inf, 'xCurrentPos', 0.0) or 0.0)
                        _by = float(getattr(_inf, 'yCurrentPos', 0.0) or 0.0)
                        if _bx == 0.0 and _by == 0.0:
                            continue
                        seen_fallback.add(_vid)
                        active_veh_ids.add(_vid)
                        _bus_xy[_vid] = (_bx, _by)

                        if jct_xy:
                            _best_j = -1
                            _best_d = 1e9
                            _best_z = 0.0
                            for _jid, (_jx, _jy, _zr) in jct_xy.items():
                                _d = math.sqrt((_bx - _jx)**2 + (_by - _jy)**2)
                                if _d < _best_d:
                                    _best_d = _d
                                    _best_j = _jid
                                    _best_z = _zr
                                # Also update zone-presence for supplement buses
                                # so detect_bus Tier 0 can use them
                                if _d <= _zr:
                                    _tracking_zone_presence.setdefault(_jid, {})[_vid] = (_bx, _by, float(getattr(_inf, 'CurrentSpeed', 40.0) or 40.0))
                            _inz = 1 if _best_d <= _best_z else 0
                        else:
                            _best_j = -1
                            _best_d = -1.0
                            _best_z = 0.0
                            _inz = 0

                        rows.append((
                            f"{time:.1f}", _vid,
                            f"{_bx:.1f}", f"{_by:.1f}",
                            _best_j, f"{_best_d:.0f}",
                            _inz, f"{_best_z:.0f}", "track",
                        ))
                    except Exception:
                        continue

    # Update live corridor bus count for queue snapshot
    _active_corridor_bus_count = len(active_veh_ids)

    # Clean up zone state for vehicles no longer on the network
    stale_keys = [k for k in _bus_zone_state if k[0] not in active_veh_ids]
    for k in stale_keys:
        del _bus_zone_state[k]
        # Also clear zone entry times for stale vehicles
        if k in _bus_zone_entry_time:
            del _bus_zone_entry_time[k]

    # Add lifecycle events: first time seen in network and nearest-junction change
    if rows:
        for _r in list(rows):
            _vid = int(_r[1])
            _jid = int(_r[4])
            _bx = _r[2]
            _by = _r[3]
            _dist = _r[5]
            _inz = _r[6]
            _zr = _r[7]
            if _vid not in _bus_seen_ids:
                _bus_seen_ids.add(_vid)
                rows.append((
                    f"{time:.1f}", _vid, _bx, _by,
                    _jid, _dist, _inz, _zr, "enter_system",
                ))
            _prev_j = _bus_last_nearest_jct.get(_vid)
            if _prev_j is not None and _jid != _prev_j and _jid > 0:
                rows.append((
                    f"{time:.1f}", _vid, _bx, _by,
                    _jid, _dist, _inz, _zr, "nearest_jct_change",
                ))
            _bus_last_nearest_jct[_vid] = _jid

    if not rows:
        return
    try:
        write_header = not _bus_track_header_written
        with open(_BUS_TRACKING_CSV, "a", newline="", encoding="utf-8") as f:
            w = csv.writer(f)
            if write_header:
                w.writerow(["sim_time_s", "veh_id", "x", "y",
                            "nearest_jct", "dist_m", "in_zone", "zone_radius_m",
                            "event"])
                _bus_track_header_written = True
            w.writerows(rows)
    except Exception as _e:
        log_to_file(f"[BUS_TRACK] CSV write failed: {_e}")

    # Write a separate 1-second presence snapshot for diagnostics.
    # This keeps event-style detection_points compact while giving
    # continuous per-bus/per-junction state for strategy inspection.
    try:
        if jct_xy and _bus_xy:
            _presence_rows = []
            for _vid, (_bx, _by) in _bus_xy.items():
                _line_id = int(_bus_line_id.get(_vid, -1) or -1)
                _seen_jcts = set()

                _best_j = -1
                _best_d = 1e12
                _best_z = 0.0
                for _jid, (_jx, _jy, _zr) in jct_xy.items():
                    _d = math.sqrt((_bx - _jx) ** 2 + (_by - _jy) ** 2)
                    if _d < _best_d:
                        _best_d = _d
                        _best_j = int(_jid)
                        _best_z = float(_zr)

                if _best_j > 0:
                    _presence_rows.append((
                        f"{time:.1f}", int(_vid), _line_id, _best_j,
                        f"{_best_d:.1f}", f"{_best_z:.1f}",
                        1 if _best_d <= _best_z else 0,
                        "nearest",
                        f"{_bx:.1f}", f"{_by:.1f}",
                    ))
                    _seen_jcts.add(_best_j)

                for _jid, _veh_map in _tracking_zone_presence.items():
                    if int(_jid) in _seen_jcts or _vid not in _veh_map:
                        continue
                    _jxy = jct_xy.get(_jid)
                    if not _jxy:
                        continue
                    _jx, _jy, _zr = _jxy
                    _d = math.sqrt((_bx - _jx) ** 2 + (_by - _jy) ** 2)
                    _presence_rows.append((
                        f"{time:.1f}", int(_vid), _line_id, int(_jid),
                        f"{_d:.1f}", f"{float(_zr):.1f}",
                        1,
                        "in_zone",
                        f"{_bx:.1f}", f"{_by:.1f}",
                    ))

            if _presence_rows:
                _hdr = not _presence_snapshot_header_written
                with open(_PRESENCE_SNAPSHOT_CSV, "a", newline="", encoding="utf-8") as _pf:
                    _pw = csv.writer(_pf)
                    if _hdr:
                        _pw.writerow([
                            "sim_time_s", "veh_id", "line_id", "junction_id",
                            "dist_m", "zone_radius_m", "in_zone", "scope", "x", "y",
                        ])
                        _presence_snapshot_header_written = True
                    _pw.writerows(_presence_rows)
    except Exception as _pe:
        log_to_file(f"[PRESENCE_SNAPSHOT] CSV write failed: {_pe}")

def _write_queue_snapshot(time: float):
    """
    Write per-intersection queue-length snapshot every _QUEUE_SNAP_INTERVAL_S.

    Columns:
        sim_time_s    — simulation time (s)
        junction_id   — intersection ID
        buses_in_zone — distinct buses in detection zone whose PT line serves this junction
        queue_main    — queued vehicles (<5 km/h) on main (bus) approach sections
        queue_side    — queued vehicles (<5 km/h) on side-street sections
        queue_total   — queue_main + queue_side
        tsp_state     — current TSP state string ('IDLE' / 'GE' / 'INS' / 'NORMAL')
        current_phase — current Aimsun phase number at this junction
        delay_total_s — cumulative pax-seconds of total delay at this junction (running total)
        delay_bus_s   — cumulative pax-seconds of bus delay at this junction (running total)
        delay_car_s   — cumulative pax-seconds of car delay at this junction (running total)

    Written to: logs/queue_snapshot_<EXPERIMENT>_<timestamp>.csv
    """
    global _queue_snap_last_t, _queue_snap_header_written

    if time - _queue_snap_last_t < _QUEUE_SNAP_INTERVAL_S:
        return
    _queue_snap_last_t = time

    rows = []
    for iid, ctrl in controllers.items():
        try:
            # Count buses in detection zone, filtered to buses whose PT line serves this junction.
            # Raw zone presence includes ALL PT vehicles within radius — buses on parallel/cross
            # routes inflate the count.  Filter: include bus if its line's route contains iid.
            # Fallback for unknown routes: use _bus_observed_jcts (actual corridor route observed
            # during this simulation).  Only include if the bus has been observed near corridor
            # junctions — prevents cross-route buses from inflating the count.
            raw_zone = _tracking_zone_presence.get(iid, {})
            buses_in_zone = 0
            for _vid in raw_zone:
                _line_id = _bus_line_id.get(_vid, -1)
                _route_jcts = _pt_line_jct_route.get(_line_id) if _line_id > 0 else None
                if _route_jcts is not None:
                    if iid in _route_jcts:
                        buses_in_zone += 1
                else:
                    # Route unknown — fall back to observed junction sequence.
                    # Include only if this bus has been observed specifically entering
                    # THIS junction's zone (recorded in _bus_observed_jcts during the
                    # nearest-zone zone_enter pass).  This prevents cross-route buses
                    # from being counted just because they happen to be physically nearby.
                    _obs = _bus_observed_jcts.get(_vid)
                    if _obs and iid in _obs:
                        buses_in_zone += 1

            # Queue per section (vehicles moving < 5 km/h).
            # Prefer SimulationStats topology-derived main/side sections —
            # they include side-street sections that the controller doesn't
            # hold in incoming_sections (which covers only bus approaches).
            q_main = 0
            q_side = 0
            main_secs: set = set()
            side_secs: set = set()
            try:
                _inter_d = stats._inter.get(iid, {})
                main_secs = set(_inter_d.get('main_sections', []))
                side_secs = set(_inter_d.get('side_sections', []))
            except Exception:
                pass
            # Prefer controller's live resolved side sections (may differ from
            # the config-stored connector sections in stats._inter).
            _ctrl_side = set(getattr(ctrl, '_cached_side_sections', None) or [])
            if _ctrl_side:
                side_secs = _ctrl_side
            if not main_secs and not side_secs:
                main_secs = set(getattr(ctrl, 'incoming_sections', []))
            all_secs = main_secs | side_secs

            for sec in all_secs:
                if not sec or sec <= 0:
                    continue
                try:
                    n = max(int(AKIVehStateGetNbVehiclesSection(sec, False)), 0)
                    for vi in range(n):
                        vinf = AKIVehStateGetVehicleInfSection(sec, vi)
                        spd = float(getattr(vinf, 'CurrentSpeed', 0.0) or 0.0)
                        if spd < 5.0:
                            if sec in main_secs:
                                q_main += 1
                            else:
                                q_side += 1
                except Exception:
                    continue

            # TSP state string
            # Prefer explicit local phase-based action flag when active
            # so Harmony GE/INS does not appear as IDLE in diagnostics.
            tsp_state = "NORMAL"
            _flag = int(getattr(ctrl, 'flag', 0) or 0)
            _flag_state = {1: 'GE', 2: 'INS'}.get(_flag, None)
            gb = getattr(ctrl, 'gb', None)
            if gb is not None:
                ts = int(getattr(gb, 'tsp_strategy', 0) or 0)
                if ts in (1, 2, 3):
                    tsp_state = {1: 'GE', 2: 'INS_COMPAT', 3: 'INS_FORCED'}[ts]
                elif _flag_state is not None:
                    tsp_state = _flag_state
                elif getattr(ctrl, '_harmony_prearm', None) is not None:
                    tsp_state = 'PREARM'
                else:
                    tsp_state = 'IDLE'
            elif _flag_state is not None:
                tsp_state = _flag_state

            try:
                cur_phase = ECIGetCurrentPhase(getattr(ctrl, 'node_id', -1))
            except Exception:
                cur_phase = -1

            # Cumulative delay from stats (person-seconds, running total)
            delay_total_s = 0.0
            delay_bus_s   = 0.0
            delay_car_s   = 0.0
            try:
                _id = stats._inter.get(iid, {})
                delay_total_s = float(_id.get('delay_total', 0.0) or 0.0)
                delay_bus_s   = float(_id.get('delay_bus',   0.0) or 0.0)
                delay_car_s   = float(_id.get('delay_car',   0.0) or 0.0)
            except Exception:
                pass

            # ── Shockwave queue estimation ──────────────────────────────────
            # Strategy 1: snapshot physical vehicle count (q_main/q_side above)
            # Strategy 2: shockwave calc from approach flow + red duration
            sw_q_main    = float(q_main)
            sw_q_side    = float(q_side)
            sw_flow_main = 0.0
            sw_den_main  = 0.0
            sw_red_s     = 0.0
            sw_flow_side = 0.0
            sw_strat_main = "snapshot"
            sw_strat_side = "snapshot"
            # Turning-level flow (flag-gated): authoritative per-turn flow summed
            # over the bus-phase turnings (MAIN) vs conflicting turnings (SIDE) --
            # node flow = sum of turning flows. Seeds the shockwave flow before the
            # section-based estimate below, which only fills in where turning gave 0.
            _tf_main = 0.0; _tf_side = 0.0
            if bool(globals().get('SHOCKWAVE_TURNING_FLOW', False)):
                try:
                    _tf_main, _tf_side, _tnm, _tns = ctrl._turning_main_side_flow(None)
                except Exception:
                    _tf_main = _tf_side = 0.0
            try:
                _k_jam = float(getattr(ctrl, 'JamDensity', 200))
                _k_sat = float(getattr(ctrl, 'SaturationDensity', 35))
                _q_sat = float(getattr(ctrl, 'SaturationFlow', 1800))
                _upf = np.asarray(getattr(ctrl, 'UpFlowList', []), dtype=float)
                _upd = np.asarray(getattr(ctrl, 'UpDenList',  []), dtype=float)
                _rdt = np.asarray(getattr(ctrl, 'RedDurationList', []), dtype=float)
                if _upf.size > 0 and _rdt.size > 0:
                    _flow_vals = _upf.ravel()
                    _den_vals  = _upd.ravel()
                    _red_vals  = _rdt.ravel()
                    _pos_mask  = _flow_vals > 0
                    if _pos_mask.any():
                        sw_flow_main = (_tf_main if _tf_main > 0.0
                                        else float(np.mean(_flow_vals[_pos_mask])))
                        sw_strat_main = ("turning" if _tf_main > 0.0 else sw_strat_main)
                        sw_den_main  = float(np.mean(_den_vals[_pos_mask]))
                        sw_red_s     = float(np.max(_red_vals))
                        _k_diff  = max(_k_jam - sw_den_main, 1.0)
                        _w_back_kms = (sw_flow_main / 3600.0) / _k_diff
                        _sw_q = (_w_back_kms * sw_red_s) * _k_jam  # q_km * k_jam = n_veh
                        if _sw_q > sw_q_main:
                            sw_q_main    = _sw_q
                            sw_strat_main = "shockwave"
                _suf = np.asarray(getattr(ctrl, 'SideUpFlowList', []), dtype=float)
                if _tf_side > 0.0:
                    sw_flow_side = _tf_side
                    sw_strat_side = "turning"
                elif _suf.size > 0:
                    _side_pos = _suf[_suf > 0.0]
                    sw_flow_side = float(np.mean(_side_pos)) if _side_pos.size > 0 else 400.0
                    sw_strat_side = "SideUpFlow" if _side_pos.size > 0 else "default400"
                # Side shockwave queue from whichever flow source (turning or section)
                if sw_red_s > 0 and sw_flow_side > 0:
                    _k_arr_s  = sw_flow_side * _k_sat / max(_q_sat, 1.0)
                    _k_diff_s = max(_k_jam - _k_arr_s, 1.0)
                    _sw_qs = (sw_flow_side / 3600.0 / _k_diff_s) * sw_red_s * _k_jam
                    if _sw_qs > sw_q_side:
                        sw_q_side  = _sw_qs
                        sw_strat_side = "shockwave"
            except Exception:
                pass

            # ── Directional queue columns (NB/SB/EB/WB) ───────────────────────
            # Use section centroid Y to split main into NB/SB, X to split side into EB/WB.
            # Cache is built lazily on first snapshot per section.
            global _sec_y_cache, _sec_x_cache
            if '_sec_y_cache' not in globals():
                _sec_y_cache = {}
            if '_sec_x_cache' not in globals():
                _sec_x_cache = {}
            q_main_nb = q_main_sb = q_side_eb = q_side_wb = 0
            try:
                # Lazy-fill section centroids for all sections involved
                for _sec in all_secs:
                    if _sec not in _sec_y_cache:
                        try:
                            _si = AKIInfNetGetSectionANGInf(_sec)
                            _sec_y_cache[_sec] = float(getattr(_si, 'centroidY', 0) or 0)
                            _sec_x_cache[_sec] = float(getattr(_si, 'centroidX', 0) or 0)
                        except Exception:
                            _sec_y_cache[_sec] = 0.0
                            _sec_x_cache[_sec] = 0.0
                main_y = [_sec_y_cache.get(s, 0) for s in main_secs if s in _sec_y_cache]
                side_x = [_sec_x_cache.get(s, 0) for s in side_secs if s in _sec_x_cache]
                mid_y = sorted(main_y)[len(main_y)//2] if main_y else 0.0
                mid_x = sorted(side_x)[len(side_x)//2] if side_x else 0.0
                for sec in main_secs:
                    if sec <= 0:
                        continue
                    try:
                        n = max(int(AKIVehStateGetNbVehiclesSection(sec, False)), 0)
                        if _sec_y_cache.get(sec, 0) >= mid_y:
                            q_main_nb += n
                        else:
                            q_main_sb += n
                    except Exception:
                        continue
                for sec in side_secs:
                    if sec <= 0:
                        continue
                    try:
                        n = max(int(AKIVehStateGetNbVehiclesSection(sec, False)), 0)
                        if _sec_x_cache.get(sec, 0) >= mid_x:
                            q_side_eb += n
                        else:
                            q_side_wb += n
                    except Exception:
                        continue
            except Exception:
                pass

            rows.append((
                f"{time:.1f}", iid, buses_in_zone,
                q_main, q_side, q_main + q_side,
                q_main_nb, q_main_sb, q_side_eb, q_side_wb,
                tsp_state, cur_phase, _active_corridor_bus_count,
                f"{delay_total_s:.1f}", f"{delay_bus_s:.1f}", f"{delay_car_s:.1f}",
                f"{sw_q_main:.1f}", f"{sw_q_side:.1f}",
                f"{sw_flow_main:.0f}", f"{sw_den_main:.2f}", f"{sw_red_s:.1f}",
                f"{sw_flow_side:.0f}", sw_strat_main, sw_strat_side,
            ))
        except Exception:
            continue

    if not rows:
        return
    try:
        write_header = not _queue_snap_header_written
        with open(_QUEUE_SNAPSHOT_CSV, "a", newline="", encoding="utf-8") as f:
            w = csv.writer(f)
            if write_header:
                w.writerow([
                    "sim_time_s", "junction_id", "buses_in_zone",
                    "queue_main", "queue_side", "queue_total",
                    "queue_main_nb", "queue_main_sb", "queue_side_eb", "queue_side_wb",
                    "tsp_state", "current_phase", "corridor_bus_count",
                    "delay_total_s", "delay_bus_s", "delay_car_s",
                    "sw_q_main", "sw_q_side",
                    "sw_flow_main", "sw_density_main", "sw_red_s",
                    "sw_flow_side", "sw_strat_main", "sw_strat_side",
                ])
                _queue_snap_header_written = True
            w.writerows(rows)
    except Exception as _e:
        log_to_file(f"[QUEUE_SNAP] write failed: {_e}")

def resolve_vehicle_type_positions():
    """
    Dynamically detect vehicle type internal positions.
    Works with Car, Truck, Bus or any custom naming.
    """
    car_pos = -1
    bus_pos = -1
    truck_pos = -1

    n_types = AKIVehGetNbVehTypes()

    for pos in range(1, n_types + 1):
        raw = AKIVehGetVehTypeName(pos)
        try:
            name = AKIConvertToAsciiString(raw, True).lower()
        except:
            name = str(raw).lower()
        '''
        _vprint(f"[VEH DETECT] pos={pos} name={name}")
        '''
        if "bus" in name:
            bus_pos = pos
        elif "truck" in name:
            truck_pos = pos
        elif "car" in name:
            car_pos = pos

    return car_pos, bus_pos, truck_pos

def log_to_file(message, force=False):
    """
    Write message to log file.  Only print to the Aimsun console when
    VERBOSE=True OR force=True (used for critical errors that must always show).
    """
    full_msg = f"{datetime.datetime.now().strftime('%H:%M:%S')} | {message}"
    if VERBOSE or force:
        AKIPrintString(full_msg)
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as f:
            f.write(full_msg + "\n")
    except Exception as _log_err:
        AKIPrintString(f"[LOG] file write failed ({LOG_FILE}): {_log_err}")

def _preflight_model_db_health() -> bool:
    """
    Read-only integrity preflight for model companion SQLite files.

    Returns True if all checked files look healthy or preflight is disabled.
    Returns False when corruption is detected in strict mode.
    """
    if not ENABLE_MODEL_DB_PREFLIGHT:
        return True

    try:
        _base = _CORRIDOR_DIR
    except NameError:
        _base = os.getcwd()

    _all_sqlite = sorted(
        [p for p in glob.glob(os.path.join(_base, "*.sqlite")) if os.path.isfile(p)],
        key=os.path.getmtime,
        reverse=True,
    )

    if not _all_sqlite:
        log_to_file("[PREFLIGHT] No companion .sqlite files found; skipping DB check", force=True)
        return True

    # Choose the active companion DB instead of scanning every stale file in
    # the folder.  Scanning all *.sqlite can fail a valid recovered run when an
    # unrelated historical model DB is corrupted.
    _candidate_files = []
    _lock_stems = set()
    for _lk in glob.glob(os.path.join(_base, "*.ang.lck")) + glob.glob(os.path.join(_base, "*.sang.lck")):
        try:
            _lock_stems.add(os.path.splitext(os.path.splitext(os.path.basename(_lk))[0])[0])
        except Exception:
            pass
    if _lock_stems:
        for _st in sorted(_lock_stems):
            _p = os.path.join(_base, f"{_st}.sqlite")
            if os.path.isfile(_p):
                _candidate_files.append(_p)

    if not _candidate_files:
        _recover_sqlite = [p for p in _all_sqlite if "_RECOVER" in os.path.basename(p).upper()]
        if _recover_sqlite:
            _candidate_files = [_recover_sqlite[0]]
        else:
            _candidate_files = [_all_sqlite[0]]

    _chosen_names = ", ".join(os.path.basename(_p) for _p in _candidate_files)
    log_to_file(f"[PREFLIGHT] Checking active companion DB(s): {_chosen_names}", force=True)

    _bad = []
    for _p in _candidate_files:
        try:
            _conn = sqlite3.connect(f"file:{_p}?mode=ro", uri=True)
            try:
                _row = _conn.execute("PRAGMA quick_check(1)").fetchone()
            finally:
                _conn.close()
            _msg = str(_row[0]) if _row else "unknown"
            if _msg.lower() == "ok":
                log_to_file(f"[PREFLIGHT] DB OK: {os.path.basename(_p)}", force=True)
            else:
                _bad.append((_p, _msg))
        except Exception as _e:
            _bad.append((_p, f"check_failed: {_e}"))

    if _bad:
        for _p, _why in _bad:
            log_to_file(
                f"[PREFLIGHT] DB CORRUPT: {os.path.basename(_p)} :: {_why}",
                force=True,
            )
        if MODEL_DB_PREFLIGHT_STRICT:
            log_to_file(
                "[FATAL] Model DB preflight failed. Open a recovered .ang/.sang copy and rerun. "
                "Aborting AAPIInit to prevent running on corrupted storage.",
                force=True,
            )
            return False

    return True

def _plot_schedule_recovery():
    """
    Generate a schedule-recovery chart from _ge_events.

    Each row in _ge_events is (sim_time, intersection_id, ge_s, recovery_s).
    The chart shows:
      • Blue bars  — GE granted (seconds stolen from the cycle)
      • Green bars — recovery trimmed from subsequent phases
      • Red bars   — residual (GE - recovery, i.e. unrecovered drift)

    Saved as logs/schedule_recovery_<timestamp>.png
    """
    if not _ge_events:
        log_to_file("[SCHED] No GE events recorded — skipping recovery plot")
        return

    out_path = os.path.join(LOG_DIR,
                            f"schedule_recovery_{_CURRENT_EXPERIMENT}_{timestamp}.png")

    times    = [e[0] for e in _ge_events]
    ge_vals  = [e[2] for e in _ge_events]
    rec_vals = [e[3] for e in _ge_events]
    res_vals = [max(0.0, g - r) for g, r in zip(ge_vals, rec_vals)]
    iids     = [e[1] for e in _ge_events]

    x = list(range(len(_ge_events)))
    labels = [f"t={t:.0f}s\njct{iid}" for t, iid in zip(times, iids)]

    fig, axes = plt.subplots(2, 1, figsize=(max(8, len(x) * 0.6 + 2), 8))

    # Top panel: per-event bar chart
    ax = axes[0]
    w = 0.28
    ax.bar([xi - w for xi in x], ge_vals,  width=w, color='#29b6f6', label='GE granted (s)')
    ax.bar([xi      for xi in x], rec_vals, width=w, color='#00e676', label='Recovered (s)')
    ax.bar([xi + w for xi in x], res_vals,  width=w, color='#ff5252', label='Residual drift (s)')
    ax.set_xticks(x)
    ax.set_xticklabels(labels, fontsize=7, rotation=45, ha='right')
    ax.set_ylabel('seconds')
    ax.set_title(f'Schedule Recovery per GE Event — {_CURRENT_EXPERIMENT} ({CONTROL_MODE})')
    ax.legend(fontsize=8)
    ax.grid(axis='y', alpha=0.3)

    # Bottom panel: cumulative drift over time
    ax2 = axes[1]
    cum_drift = []
    running = 0.0
    for g, r in zip(ge_vals, rec_vals):
        running += max(0.0, g - r)
        cum_drift.append(running)
    ax2.plot(times, cum_drift, color='#ff5252', marker='o', markersize=4, linewidth=1.5,
             label='Cumulative unrecovered drift (s)')
    ax2.axhline(0, color='#00e676', linewidth=0.8, linestyle='--')
    ax2.set_xlabel('simulation time (s)')
    ax2.set_ylabel('cumulative seconds behind schedule')
    ax2.set_title('Cumulative Timing Drift Over Simulation')
    ax2.legend(fontsize=8)
    ax2.grid(alpha=0.3)

    plt.tight_layout()
    plt.savefig(out_path, dpi=120, bbox_inches='tight')
    plt.close(fig)
    log_to_file(f"[SCHED] Schedule recovery plot → {out_path} "
                f"({len(_ge_events)} GE events, "
                f"total_ge={sum(ge_vals):.1f}s "
                f"total_rec={sum(rec_vals):.1f}s "
                f"residual={sum(res_vals):.1f}s)")

def _write_run_summary():
    try:
        g = stats._global_kpis() if hasattr(stats, '_global_kpis') else {}
        with open(_RUN_SUMMARY_TXT, 'w', encoding='utf-8') as f:
            f.write('TSP RUN SUMMARY\n')
            f.write('=' * 80 + '\n')
            f.write(f'Timestamp: {datetime.datetime.now().isoformat()}\n')
            f.write(f'LOG_FILE: {LOG_FILE}\n')
            f.write(f'CONTROL_MODE: {CONTROL_MODE}\n')
            # ACTIVE_TSP_MODE: the specialised decider flag that is ACTUALLY on in
            # _spm this run (not what run_config asked for). This is the ground
            # truth champion_search checks declared-vs-actual against, so an arm
            # that silently fell through to the generic DRL_DENSITY path (mode
            # flag never propagated / no decider) can never masquerade as its
            # named strategy again.
            _active_mode = 'GENERIC'
            for _fl, _nm in (
                ('BXT_MODE', 'BXT'), ('CPDQL_MODE', 'CPDQL'),
                ('DCTSP_ZIG_MODE', 'ZIG'),
                ('MP_ECTM_MODE', 'MP_ECTM'), ('MP_ECTM_DP_MODE', 'MP_ECTM_DP'),
                ('BARGAIN_SPM_MODE', 'BARGAIN'), ('NASH_GATE_MODE', 'NASH_GATE'),
                ('NASH_BARGAIN_MODE', 'NASH_BARGAIN'),
                ('MILP_TSP_MODE', 'MILP_TSP'), ('CELLQLEARN_DP_MODE', 'CELLQLEARN_DP'),
                ('MAXPRESSURE_FIX_MODE', 'MAXPRESSURE_FIX'),
                ('MAXPRESSURE_FLEX_MODE', 'MAXPRESSURE_FLEX'),
                ('CENTRALIZED_MODE', 'CENTRALIZED')):
                if bool(getattr(_spm, _fl, False)):
                    _active_mode = _nm
                    break
            f.write(f'ACTIVE_TSP_MODE: {_active_mode}\n')
            f.write(f'COORDINATED_TSP: {COORDINATED_TSP}\n')
            f.write(f'COORDINATION_ALGO: {COORDINATION_ALGO}\n')
            f.write(f'VERBose: {VERBOSE}\n')
            f.write('\n')
            f.write('[GLOBAL KPIS]\n')
            if g:
                for key, value in sorted(g.items()):
                    f.write(f'  {key}: {value}\n')
            else:
                f.write('  No global KPIs available\n')
            f.write('\n')
            f.write('[CONTROLLER STATUS]\n')
            for iid, ctrl in controllers.items():
                _gb = getattr(ctrl, 'gb', None)
                f.write(f'  Intersection {iid}: node_id={getattr(ctrl, "node_id", None)}')
                if _gb is not None:
                    f.write(
                        f' | bus_sg={getattr(_gb, "bus_sg", None)}'
                        f' | bus_request={getattr(_gb, "bus_request", None)}'
                        f' | external_control={getattr(_gb, "_external_control", None)}'
                        f' | bus_req_count={getattr(_gb, "_gb_bus_request_count", 0)}'
                        f' | activations={getattr(_gb, "_gb_bus_activation_count", 0)}'
                        f' | forced_terminations={getattr(_gb, "_gb_forced_termination_count", 0)}'
                        f' | phase_groups={len(getattr(_gb, "phase_groups", []))}'
                        f' | bus_phase={getattr(_gb, "_bus_aimsun_phase", None)}'
                    )
                f.write('\n')
            f.write('\n')
            f.write('[CORRIDOR SUMMARY]\n')
            if corridor_coordinators:
                for coord in corridor_coordinators:
                    f.write(f'  {coord.summary()}\n')
            else:
                f.write('  No corridor coordinators configured.\n')

            # ── Bus Trip Time Statistics ──────────────────────────────────────
            if corridor_coordinators:
                for coord in corridor_coordinators:
                    if hasattr(coord, '_bus_trip_times') and coord._bus_trip_times:
                        import numpy as np
                        _trips = np.array(coord._bus_trip_times)
                        _mean = float(np.mean(_trips))
                        _std = float(np.std(_trips))
                        _min = float(np.min(_trips))
                        _max = float(np.max(_trips))
                        _count = len(_trips)
                        f.write(f'\n  [BUS TRIP TIME STATS]\n')
                        f.write(f'    Count: {_count}\n')
                        f.write(f'    Mean: {_mean:.1f} s\n')
                        f.write(f'    Std Dev: {_std:.1f} s\n')
                        f.write(f'    Min: {_min:.1f} s\n')
                        f.write(f'    Max: {_max:.1f} s\n')
                        f.write(f'    CV: {(_std/_mean*100):.1f}%\n' if _mean > 0 else '    CV: N/A\n')

    except Exception as e:
        log_to_file(f"[SUMMARY] run summary write failed: {e}", force=True)

def _write_algorithm_explanation_tex():  # noqa: C901
    """Write a multi-page TikZ flowchart document (one page per TSP strategy)."""
    # ------------------------------------------------------------------
    # Shared TikZ preamble
    # ------------------------------------------------------------------
    PREAMBLE = r'''\documentclass[a4paper,10pt]{article}
\usepackage[margin=15mm]{geometry}
\usepackage{tikz}
\usetikzlibrary{shapes.geometric,arrows.meta,positioning,fit,backgrounds,calc}
\usepackage{amsmath}
\usepackage{xcolor}

%% ── Node style palette ──────────────────────────────────────────────────────
\tikzstyle{start}   = [rounded rectangle, draw=black!70, fill=green!25,
                        minimum width=28mm, minimum height=8mm, align=center,
                        font=\small\bfseries]
\tikzstyle{stop}    = [rounded rectangle, draw=black!70, fill=red!25,
                        minimum width=28mm, minimum height=8mm, align=center,
                        font=\small\bfseries]
\tikzstyle{proc}    = [rectangle, draw=black!60, fill=blue!8,
                        minimum width=38mm, minimum height=9mm, align=center,
                        font=\small]
\tikzstyle{procB}   = [rectangle, draw=black!60, fill=blue!18,
                        minimum width=38mm, minimum height=9mm, align=center,
                        font=\small\bfseries]
\tikzstyle{dec}     = [diamond, aspect=2.2, draw=black!70, fill=orange!18,
                        minimum width=44mm, align=center, font=\small]
\tikzstyle{coord}   = [rectangle, draw=teal!70, fill=teal!10,
                        minimum width=38mm, minimum height=9mm, align=center,
                        font=\small\itshape]
\tikzstyle{result}  = [rectangle, rounded corners=3pt, draw=gray!60,
                        fill=gray!12, minimum width=34mm, minimum height=8mm,
                        align=center, font=\small]
\tikzstyle{arr}     = [-{Stealth[scale=1.1]}, thick, black!70]
\tikzstyle{yes}     = [draw=green!50!black, text=green!50!black]
\tikzstyle{no}      = [draw=red!60!black,   text=red!60!black]
\newcommand\YN[2]{\node[font=\tiny, #1] at (#2) {\textbf{#1}};}
\begin{document}
'''
    FOOTER = r'\end{document}' + '\n'

    # ------------------------------------------------------------------
    # Helper: wrap a page in a tikzpicture
    # ------------------------------------------------------------------
    def page(title: str, body: str, caption: str = "") -> str:
        cap = (r'\medskip{\footnotesize\textit{' + caption + r'}}') if caption else ""
        return (
            r'\newpage' + '\n' +
            r'\begin{center}{\large\bfseries ' + title + r'}\end{center}' + '\n' +
            r'\begin{tikzpicture}[node distance=9mm and 16mm, >=Stealth]' + '\n' +
            body + '\n' +
            r'\end{tikzpicture}' + '\n' +
            cap + '\n'
        )

    # ------------------------------------------------------------------
    # Page 1 — NORMAL (no TSP)
    # ------------------------------------------------------------------
    P_NORMAL = r'''
\node[start]  (start)                          {Simulation step};
\node[proc]   (plan)  [below=of start]         {Execute fixed signal plan\\(Aimsun timing tables)};
\node[proc]   (stats) [below=of plan]          {Collect section statistics\\(flow, density, speed)};
\node[stop]   (done)  [below=of stats]         {End of step};
\draw[arr] (start)--(plan);
\draw[arr] (plan) --(stats);
\draw[arr] (stats)--(done);
'''

    # ------------------------------------------------------------------
    # Page 2 — HARMONY_INDEP (local TSP, no coordination)
    # ------------------------------------------------------------------
    P_INDEP = r'''
\node[start]  (start)                          {Simulation step\\(check\_bus\_priority)};
\node[dec]    (det)   [below=of start]         {Bus detected\\on approach?};
\node[proc]   (eta)   [below=of det]           {Compute ETA to stop-line\\(Kalman position + speed)};
\node[dec]    (phase) [below=of eta]           {Current phase\\= Bus phase?};
\node[dec]    (nat)   [right=30mm of phase]    {Bus arrives on\\natural green?};
\node[result] (skip)  [right=22mm of nat]      {No action\\(natural green)};
\node[dec]    (geok)  [below=of phase]         {GE needed\\$\le$ MAX\_GE?};
\node[proc]   (ge)    [below=of geok]          {ECIChangeTimingPhase\\GE = min($\eta$+5,MAX\_GE)};
\node[dec]    (ins)   [right=30mm of geok]     {Bus misses\\natural bus phase?};
\node[proc]   (ins2)  [below=of ins]           {ECIChangeDirectPhase\\INS = min($\eta$+5,MAX\_INS)};
\node[stop]   (done)  [below=22mm of ge]       {Return / next step};
%% edges
\draw[arr] (start)--(det);
\draw[arr] (det)--node[right,font=\tiny\bfseries]{Yes}(eta);
\draw[arr] (det.east)--++(14mm,0)--++(0,-44mm)node[right,font=\tiny\bfseries]{No}
           --++(0,-4mm)--(done.north east);
\draw[arr] (eta)--(phase);
\draw[arr] (phase)--node[right,font=\tiny\bfseries]{Yes}(geok);
\draw[arr] (phase.east)--node[above,font=\tiny\bfseries]{No}(nat);
\draw[arr] (nat.east)--node[above,font=\tiny\bfseries]{Yes}(skip);
\draw[arr] (nat.south)--node[right,font=\tiny\bfseries]{No}(ins);
\draw[arr] (ins)--(ins2);
\draw[arr] (geok)--node[right,font=\tiny\bfseries]{Yes}(ge);
\draw[arr] (geok.east)--node[above,font=\tiny\bfseries]{No -- skip}++(18mm,0);
\draw[arr] (ge)--(done);
\draw[arr] (ins2.south)--++(0,-4mm)-|(done.east);
'''

    # ------------------------------------------------------------------
    # Page 3 — HARMONY_COORD overview (applies to all COORD sub-algos)
    # ------------------------------------------------------------------
    P_COORD_OVERVIEW = r'''
\node[start]   (det)                          {Bus detected at\\junction $j$};
\node[proc]    (kalman) [below=of det]        {Kalman update:\\position $\hat{x}$, speed $\hat{v}$};
\node[proc]    (pred)   [below=of kalman]     {Predict position continuously:\\$\hat{x}_{t+\Delta t}=\hat{x}_t+\hat{v}\Delta t$};
\node[coord]   (coord)  [below=of pred]       {CorridorCoordinator.\\notify\_bus\_at\_junction()};
\node[proc]    (eta_j)  [below=of coord]      {Compute ETAs to all\\downstream junctions $j+1\ldots n$};
\node[coord]   (prearm) [below=of eta_j]      {Set \_harmony\_prearm\\at each downstream IC};
\node[dec]     (fire)   [below=12mm of prearm]{$\eta_{\mathrm{from now}} \in$\\$[0, \eta_{\max}]$?};
\node[proc]    (tsp)    [below=of fire]       {Execute GE or INS\\(coord path)};
\node[proc]    (offset) [below=of tsp]        {Log GREEN\_GRANT + offset\\to green\_offsets\_*.csv};
\node[stop]    (done)   [below=of offset]     {Propagate to next\\junction};
%% right branch — hold
\node[result]  (hold)   [right=28mm of fire]  {Hold prearm\\(check next step)};
%% edges
\draw[arr] (det)--(kalman);
\draw[arr] (kalman)--(pred);
\draw[arr] (pred)--(coord);
\draw[arr] (coord)--(eta_j);
\draw[arr] (eta_j)--(prearm);
\draw[arr] (prearm)--(fire);
\draw[arr] (fire)--node[right,font=\tiny\bfseries]{Yes}(tsp);
\draw[arr] (fire.east)--node[above,font=\tiny\bfseries]{No}(hold);
\draw[arr] (tsp)--(offset);
\draw[arr] (offset)--(done);
'''

    # ------------------------------------------------------------------
    # Page 4 — KALMAN detail
    # ------------------------------------------------------------------
    P_KALMAN = r'''
\node[start]  (obs)                           {New bus position $z_t$\\from section detector};
\node[proc]   (pred)  [below=of obs]          {Kalman predict:\\$\hat{x}^-_{t}=F\hat{x}_{t-1}$\\$P^-_t=FP_{t-1}F^\top+Q$};
\node[proc]   (upd)   [below=of pred]         {Kalman update:\\$K=P^-H^\top(HP^-H^\top+R)^{-1}$\\$\hat{x}_t=\hat{x}^-_t+K(z_t-H\hat{x}^-_t)$};
\node[proc]   (eta_k) [below=of upd]          {ETA to target:\\$\eta=(\tilde{x}_{\rm target}-\hat{x}_t)/\hat{v}_t$};
\node[dec]    (sigma) [below=of eta_k]        {$\sigma(\eta)\le$\\$\max(60,\;0.5\,\eta)$\,s?};
\node[proc]   (prearm)[below=of sigma]        {Issue pre-arm\\with $\eta$ to downstream IC};
\node[result] (skip)  [right=28mm of sigma]   {Uncertainty too high\\--- skip pre-arm};
%% Continuous advance (runs every step)
\node[coord]  (adv)   [right=30mm of pred]    {step(): advance all\\trackers by $\Delta t$\\(even without detection)};
\draw[arr] (obs)--(pred);
\draw[arr] (pred)--(upd);
\draw[arr] (upd)--(eta_k);
\draw[arr] (eta_k)--(sigma);
\draw[arr] (sigma)--node[right,font=\tiny\bfseries]{Yes}(prearm);
\draw[arr] (sigma.east)--node[above,font=\tiny\bfseries]{No}(skip);
\draw[arr] (pred.east)--++(4mm,0)--(adv.west);
'''

    # ------------------------------------------------------------------
    # Page 5 — SHOCKWAVE ETA correction
    # ------------------------------------------------------------------
    P_SHOCKWAVE = r'''
\node[proc]   (eta0)                          {Kalman ETA = $\eta_0$};
\node[proc]   (q)     [below=of eta0]         {Read upstream queue $Q_u$\\and flow $q_{\rm up}$ at junction $j$};
\node[proc]   (sw1)   [below=of q]            {Shockwave 1 (front of queue):\\$w_1 = Q_{\rm SAT}\cdot(K_{\rm SAT}-K_u)^{-1}$};
\node[proc]   (sw2)   [below=of sw1]          {Shockwave 2 (queue discharge):\\$w_2 = Q_{\rm SAT}\cdot(K_{\rm SAT}-K_{\rm JAM})^{-1}$};
\node[proc]   (tcl)   [below=of sw2]          {Queue clearance time:\\$t_{\rm clear}=Q_u / (Q_{\rm SAT}-q_{\rm up})$};
\node[dec]    (comp)  [below=of tcl]          {$\eta_0 < t_{\rm clear}$?};
\node[proc]   (adj)   [below=of comp]         {$\eta_{\rm adj}=\eta_0+t_{\rm clear}-\eta_0$\\(bus must wait for clearance)};
\node[result] (pass)  [right=28mm of comp]    {$\eta_{\rm adj}=\eta_0$\\(bus clears queue)};
\node[proc]   (pre)   [below=of adj]          {Issue pre-arm with $\eta_{\rm adj}$};
\draw[arr] (eta0)--(q);
\draw[arr] (q)--(sw1);
\draw[arr] (sw1)--(sw2);
\draw[arr] (sw2)--(tcl);
\draw[arr] (tcl)--(comp);
\draw[arr] (comp)--node[right,font=\tiny\bfseries]{Yes}(adj);
\draw[arr] (comp.east)--node[above,font=\tiny\bfseries]{No}(pass);
\draw[arr] (adj)--(pre);
'''

    # ------------------------------------------------------------------
    # Page 6 — ADAPTIVE lead time
    # ------------------------------------------------------------------
    P_ADAPTIVE = r'''
\node[proc]   (eta0)                          {Kalman ETA = $\eta_0$};
\node[proc]   (shw)   [below=of eta0]         {Apply SHOCKWAVE correction\\$\eta_{\rm sw}$};
\node[proc]   (adp)   [below=of shw]          {Adaptive lead time:\\$L=\min\!\bigl(\max(L_{\min},\;\eta_{\rm sw}\cdot\alpha),\;L_{\max}\bigr)$\\$\alpha=$ congestion factor from queue model};
\node[proc]   (parm)  [below=of adp]          {Pre-arm issued at\\$T_{\rm issue}=T_{\rm now}+\eta_{\rm sw}-L$};
\node[dec]    (rdy)   [below=of parm]         {$T_{\rm now}\ge T_{\rm issue}$?};
\node[proc]   (fire)  [below=of rdy]          {Fire TSP action\\(GE or INS)};
\node[result] (wait)  [right=28mm of rdy]     {Wait — re-evaluate\\next step (ETA refresh)};
\draw[arr] (eta0)--(shw);
\draw[arr] (shw)--(adp);
\draw[arr] (adp)--(parm);
\draw[arr] (parm)--(rdy);
\draw[arr] (rdy)--node[right,font=\tiny\bfseries]{Yes}(fire);
\draw[arr] (rdy.east)--node[above,font=\tiny\bfseries]{No}(wait);
'''

    # ------------------------------------------------------------------
    # Page 7 — OBJECTIVE function
    # ------------------------------------------------------------------
    P_OBJECTIVE = r'''
\node[proc]   (eta0)                          {Kalman ETA = $\eta_0$,\\shockwave correction applied};
\node[proc]   (cands)[below=of eta0]          {Enumerate candidate lead times:\\$L \in \{L_{\min}, \ldots, L_{\max}\}$ (1\,s steps)};
\node[proc]   (obj)  [below=of cands]         {For each $L$, evaluate:\\$J(L)=\alpha\cdot B_{\rm saved}-\beta\cdot C_{\rm displaced}$\\$B$=bus persons, $C$=car persons};
\node[proc]   (best) [below=of obj]           {Select $L^*=\arg\max J(L)$};
\node[dec]    (rdy)  [below=of best]          {$T_{\rm now}\ge T_{\rm issue}(L^*)$?};
\node[proc]   (fire) [below=of rdy]           {Fire TSP action\\(GE or INS) at $L^*$};
\node[result] (wait) [right=28mm of rdy]      {Hold --- re-evaluate\\next step};
\draw[arr] (eta0)--(cands);
\draw[arr] (cands)--(obj);
\draw[arr] (obj)--(best);
\draw[arr] (best)--(rdy);
\draw[arr] (rdy)--node[right,font=\tiny\bfseries]{Yes}(fire);
\draw[arr] (rdy.east)--node[above,font=\tiny\bfseries]{No}(wait);
'''

    # ------------------------------------------------------------------
    # Page 8 — What coordination adds (comparison)
    # ------------------------------------------------------------------
    P_COMPARISON = r'''
%% Independent column
\node[procB]  (ind_det)                       {Independent TSP:\\bus detected at $j$};
\node[proc]   (ind_eta) [below=of ind_det]    {Local ETA computed\\(single junction)};
\node[proc]   (ind_act) [below=of ind_eta]    {GE / INS fired locally\\if bus in window};
\node[result] (ind_r)   [below=of ind_act]    {Downstream junctions\\unaware of bus};

%% Coordinated column
\node[procB]  (co_det)  [right=48mm of ind_det]{Coordinated TSP:\\bus detected at $j$};
\node[coord]  (co_kal)  [below=of co_det]     {Kalman tracker update\\(continuous prediction)};
\node[coord]  (co_cor)  [below=of co_kal]     {CorridorCoordinator:\\ETAs to $j+1\ldots n$};
\node[coord]  (co_pre)  [below=of co_cor]     {Pre-arms issued\\at downstream ICs};
\node[proc]   (co_act)  [below=of co_pre]     {GE / INS fired at\\each junction on arrival};
\node[result] (co_r)    [below=of co_act]     {Green wave propagates\\through corridor};

%% divider
\draw[dashed, gray!50] ($(ind_det.north east)!0.5!(co_det.north west)$)
  -- ($(ind_r.south east)!0.5!(co_r.south west)$);

%% arrows independent
\draw[arr] (ind_det)--(ind_eta);
\draw[arr] (ind_eta)--(ind_act);
\draw[arr] (ind_act)--(ind_r);

%% arrows coordinated
\draw[arr] (co_det)--(co_kal);
\draw[arr] (co_kal)--(co_cor);
\draw[arr] (co_cor)--(co_pre);
\draw[arr] (co_pre)--(co_act);
\draw[arr] (co_act)--(co_r);
'''

    # ------------------------------------------------------------------
    # Assemble document
    # ------------------------------------------------------------------
    body = (
        PREAMBLE
        + r'\begin{center}{\LARGE\bfseries Logan Road Corridor --- TSP Strategy Flowcharts}'
          r'\\\medskip{\normalsize Generated by intersection\_controller.py'
          r' \texttt{\_write\_algorithm\_explanation\_tex()}}\end{center}' + '\n'
        + r'\tableofcontents' + '\n'
        + r'\addcontentsline{toc}{section}{NORMAL (no TSP)}'
        + page(r'Strategy: NORMAL (no TSP)', P_NORMAL,
               r'Fixed Aimsun signal plans run without intervention.')
        + r'\addcontentsline{toc}{section}{HARMONY\_INDEP (local TSP)}'
        + page(r'Strategy: HARMONY\_INDEP (local TSP only)', P_INDEP,
               r'Each intersection detects buses and acts locally. '
               r'No downstream coordination.')
        + r'\addcontentsline{toc}{section}{HARMONY\_COORD (overview)}'
        + page(r'Strategy: HARMONY\_COORD --- coordination overview', P_COORD_OVERVIEW,
               r'Applies to all COORD sub-algorithms (KALMAN / SHOCKWAVE / ADAPTIVE / OBJECTIVE). '
               r'The CorridorCoordinator pre-arms downstream intersections when a bus is detected.')
        + r'\addcontentsline{toc}{section}{KALMAN ETA detail}'
        + page(r'KALMAN --- ETA estimation detail', P_KALMAN,
               r'1-D constant-velocity Kalman filter. '
               r'$F=[1,\Delta t; 0,1]$, $Q=\mathrm{diag}(3,0.5)$, $R=900\,\mathrm{m}^2$. '
               r'Sigma gate: $\sigma \le \max(60, 0.5\,\eta)$ seconds.')
        + r'\addcontentsline{toc}{section}{SHOCKWAVE ETA correction}'
        + page(r'SHOCKWAVE --- queue-clearance ETA correction', P_SHOCKWAVE,
               r'LWR triangular model: $K_{\rm JAM}=150$, $K_{\rm SAT}=45$, '
               r'$Q_{\rm SAT}=1800$\,veh/h. Added on top of KALMAN ETA.')
        + r'\addcontentsline{toc}{section}{ADAPTIVE lead time}'
        + page(r'ADAPTIVE --- dynamic lead time', P_ADAPTIVE,
               r'Lead time $L$ scales with current queue density. '
               r'Combines shockwave correction with a congestion scaling factor $\alpha$.')
        + r'\addcontentsline{toc}{section}{OBJECTIVE function maximisation}'
        + page(r'OBJECTIVE --- person-level benefit maximisation', P_OBJECTIVE,
               r'$J = \alpha B_{\rm saved} - \beta C_{\rm displaced}$. '
               r'Weights: $\alpha=$\texttt{COORD\_OBJ\_ALPHA}, '
               r'$\beta=$\texttt{COORD\_OBJ\_BETA}.')
        + r'\addcontentsline{toc}{section}{Coordination vs.\ independent comparison}'
        + page(r'What coordination adds (independent vs.\ coordinated)', P_COMPARISON,
               r'Left: independent TSP --- each junction acts alone. '
               r'Right: coordinated TSP --- a single bus detection pre-arms the entire corridor.')
        + FOOTER
    )

    try:
        with open(_ALGORITHM_EXPLANATION_TEX, 'w', encoding='utf-8') as f:
            f.write(body)
        log_to_file(
            f"[SUMMARY] TikZ strategy flowcharts written → {_ALGORITHM_EXPLANATION_TEX}",
            force=True)
    except Exception as e:
        log_to_file(f"[SUMMARY] algorithm explanation write failed: {e}", force=True)

def _vprint(msg):
    """
    Verbose-gated console print.
    Calls AKIPrintString only when VERBOSE=True.
    Use this instead of bare AKIPrintString for all non-critical output so
    that setting VERBOSE=False silences everything in one place.
    """
    if VERBOSE:
        AKIPrintString(msg)

def _acquire_focus(veh_id: int, jct_id: int, time: float):
    """Claim global focus for this bus. Returns True if acquired."""
    global _focus_bus_id, _focus_jct_id, _focus_start_t, _focus_passed_jcts
    # Same bus or no current focus → grant
    if _focus_bus_id <= 0 or _focus_bus_id == veh_id:
        prev = _focus_bus_id
        if _focus_bus_id == veh_id and _focus_jct_id >= 0 and _focus_jct_id != jct_id:
            # Focus bus advancing to a new junction — mark the old one as passed
            _focus_passed_jcts.add(_focus_jct_id)
        elif prev != veh_id:
            # New bus taking focus — reset passed set
            _focus_passed_jcts.clear()
        _focus_bus_id  = veh_id
        _focus_jct_id  = jct_id
        _focus_start_t = time
        if prev != veh_id:
            log_to_file(
                f"[BUS_FOCUS] t={time:.1f} ACQUIRE bus={veh_id} jct={jct_id}",
                )
            _mark_detection_point(jct_id, veh_id, 0.0, 0.0, time, "focus_acquire")
        return True
    # Timeout — force release of stale focus
    if time - _focus_start_t > _FOCUS_TIMEOUT_S:
        _release_focus(time, "timeout")
        _focus_passed_jcts.clear()
        _focus_bus_id  = veh_id
        _focus_jct_id  = jct_id
        _focus_start_t = time
        log_to_file(
            f"[BUS_FOCUS] t={time:.1f} ACQUIRE (after timeout) bus={veh_id} jct={jct_id}",
            )
        _mark_detection_point(jct_id, veh_id, 0.0, 0.0, time, "focus_acquire")
        return True
    # Different bus has focus — suppress, UNLESS this bus is late enough
    # (adherence mult >= 1.2) to preempt: schedule fidelity outranks FCFS.
    tr = _ETA_TRACK.get(int(veh_id)) if BUS_ETA_BIAS_LEARN else None
    if tr and float(tr.get("mult", 1.0)) >= 1.20:
        _release_focus(time, "preempted_by_late_bus")
        _focus_passed_jcts.clear()
        _focus_bus_id  = veh_id
        _focus_jct_id  = jct_id
        _focus_start_t = time
        log_to_file(
            f"[BUS_FOCUS] t={time:.1f} PREEMPT late bus={veh_id} jct={jct_id} "
            f"mult={tr.get('mult', 1.0):.2f}", force=True)
        _mark_detection_point(jct_id, veh_id, 0.0, 0.0, time, "focus_preempt")
        return True
    return False

def _release_focus(time: float, outcome: str = "completed"):
    """Release global bus focus."""
    global _focus_bus_id, _focus_jct_id, _focus_start_t, _focus_passed_jcts
    if _focus_bus_id > 0:
        _focus_history.append((
            _focus_start_t, time, _focus_bus_id, _focus_jct_id, outcome))
        log_to_file(
            f"[BUS_FOCUS] t={time:.1f} RELEASE bus={_focus_bus_id} "
            f"jct={_focus_jct_id} outcome={outcome} "
            f"held={time - _focus_start_t:.1f}s",
            )
    _focus_bus_id  = -1
    _focus_jct_id  = -1
    _focus_start_t = -1.0
    _focus_passed_jcts.clear()

def _is_focus_blocked(veh_id: int, jct_id: int, time: float) -> bool:
    """Return True if this bus should be suppressed due to focus priority.

    Only blocks junctions the focus bus has not yet passed through.
    Once the focus bus clears a junction, other buses are free to use it.

    Schedule-adherence override (paper objective): a bus running LATE against
    its calibrated headway (_cur_sched_mult >= 1.2, i.e. >15 s behind) breaks
    through the gate and is served CONCURRENTLY -- first-come-first-served
    serialization must not silence the buses the fidelity objective cares
    about most. On-time/early buses still defer exactly as before.
    """
    if _focus_bus_id <= 0:
        return False
    if _focus_bus_id == veh_id:
        return False  # same bus is always allowed
    if time - _focus_start_t > _FOCUS_TIMEOUT_S:
        _release_focus(time, "timeout")
        return False  # timed out and released
    # Allow intersections the focus bus has already been served at
    if jct_id in _focus_passed_jcts:
        return False
    # ── Adherence breakthrough ────────────────────────────────────────────
    tr = _ETA_TRACK.get(int(veh_id)) if BUS_ETA_BIAS_LEARN else None
    if tr and float(tr.get("mult", 1.0)) >= 1.20:
        return False
    # ── Spatial scope (2026-09-28) ────────────────────────────────────────
    # Legacy focus was GLOBAL: any bus anywhere suppressed every other bus's
    # TSP. With R10 (per-window arbitration) and R11 (convoy coupling) handling
    # true conflicts, only buses SPATIALLY CO-LOCATED with the focus bus need
    # serialising -- buses far apart act concurrently. The buses themselves
    # stay in the network either way; focus only gates whose action fires.
    try:
        _r = float(globals().get('FOCUS_SCOPE_RADIUS_M', 800.0) or 800.0)
        if _r > 0.0:
            _xy = _bus_xy.get(int(veh_id))
            _fxy = _bus_xy.get(int(_focus_bus_id))
            if _xy and _fxy:
                _d = ((_xy[0] - _fxy[0]) ** 2 + (_xy[1] - _fxy[1]) ** 2) ** 0.5
                if _d > _r:
                    return False
    except Exception:
        pass
    return True

def GetPhaseDuration(IntersectionID, PhaseID, timeSta):
    normalDurationP = doublep()
    maxDurationP    = doublep()
    minDurationP    = doublep()
    ECIGetDurationsPhase(IntersectionID, PhaseID, timeSta,
                         normalDurationP, maxDurationP, minDurationP)
    return normalDurationP.value()

def ShockwaveSpeed1(UpFlow, JamDen, ArrDen):
    den = JamDen - ArrDen
    return (0 - UpFlow) / den * 1000 / 3600 if abs(den) > 1e-6 else 0.0

def ShockwaveSpeed2(SaturationFlow, SaturationDen, JamDen):
    den = SaturationDen - JamDen
    return (SaturationFlow - 0) / den * 1000 / 3600 if abs(den) > 1e-6 else 0.0

def ShockwaveSpeed3(SaturationFlow, UpFlow, SaturationDen, UpDen):
    den = SaturationDen - UpDen
    return (SaturationFlow - UpFlow) / (den if abs(den) > 1e-6 else 1e-6) * 1000 / 3600

def ShockwaveSpeed4(SaturationFlow, JamDen, SaturationDen):
    den = JamDen - SaturationDen
    return (0 - SaturationFlow) / den * 1000 / 3600 if abs(den) > 1e-6 else 0.0

def safe_float(value, default=0.0):
    try:
        result = float(value)
    except (TypeError, ValueError):
        return default
    if not math.isfinite(result):
        return default
    return result

def harmony_search(objective_function, lower_bound, upper_bound,
                   max_iterations, harmony_memory_size, hmcr, par, bandwidth, time):
    """
    Harmony search optimization with INTEGER values only.
    All candidate solutions are rounded to integer seconds.
    """
    # Convert bounds to integers
    lb_int = int(math.ceil(lower_bound))
    ub_int = int(math.floor(upper_bound))
    if lb_int > ub_int:
        return lb_int  # Edge case: return lower bound
    
    # Initialize harmony memory with integer values
    harmony_memory = [random.randint(lb_int, ub_int)
                      for _ in range(harmony_memory_size)]
    fitness_values = [objective_function(h, time) for h in harmony_memory]

    for _ in range(max_iterations):
        if random.uniform(0, 1) < hmcr:
            new_harmony = random.choice(harmony_memory)
            if random.uniform(0, 1) < par:
                # Pitch adjustment: add integer offset
                new_harmony += random.randint(-int(bandwidth), int(bandwidth))
        else:
            new_harmony = random.randint(lb_int, ub_int)

        # Clamp to integer bounds
        new_harmony = max(lb_int, min(ub_int, new_harmony))
        new_fitness = objective_function(new_harmony, time)
        worst_index = int(np.argmax(fitness_values))

        if new_fitness < fitness_values[worst_index]:
            harmony_memory[worst_index] = new_harmony
            fitness_values[worst_index] = new_fitness

    return harmony_memory[int(np.argmin(fitness_values))]


def golden_section_search(objective_function, lb, ub, time, tol=0.5, max_evals=18):
    """Deterministic 1-D minimiser for a (near-)unimodal objective on [lb, ub].

    Replaces harmony_search for solving action DURATIONS: the total-pax-delay vs
    duration curve is U-shaped (bus benefit falls, cross cost rises), so golden-
    section converges in ~log steps -- ~8-10 evals vs harmony's 20 stochastic
    ones -- AND is DETERMINISTIC (harmony's randomness put seed-noise into the
    timing, which hurt cross-seed consistency).  Robust to mild non-unimodality
    via a coarse grid pre-scan that seeds the bracket around the grid minimum.
    """
    import math as _m
    a, b = float(lb), float(ub)
    if b <= a + tol:
        return a
    # ── coarse grid pre-scan: bracket the region of the minimum ──
    n_grid = max(3, min(6, int((b - a) / 4.0) + 2))
    xs = [a + (b - a) * i / (n_grid - 1) for i in range(n_grid)]
    fs = [objective_function(x, time) for x in xs]
    _k = int(np.argmin(fs))
    a = xs[max(0, _k - 1)]
    b = xs[min(n_grid - 1, _k + 1)]
    # ── golden-section refine within the bracket ──
    gr = (_m.sqrt(5.0) - 1.0) / 2.0
    c = b - gr * (b - a); d = a + gr * (b - a)
    fc = objective_function(c, time); fd = objective_function(d, time)
    evals = n_grid + 2
    while (b - a) > tol and evals < max_evals:
        if fc < fd:
            b, d, fd = d, c, fc
            c = b - gr * (b - a); fc = objective_function(c, time)
        else:
            a, c, fc = c, d, fd
            d = a + gr * (b - a); fd = objective_function(d, time)
        evals += 1
    return 0.5 * (a + b)


def differential_evolution_search(objective_function, lb, ub, time,
                                  pop_size=10, max_generations=6,
                                  F=0.7, CR=0.9, seed=12345):
    """DE/rand/1/bin (Storn & Price 1997) on the INTEGER-second lattice.

    Signal timings commit in whole seconds (ECIChangeTimingPhase takes integer
    durations): optimising in continuous time and rounding afterwards can land
    off-optimum, and harmony_search's global-`random` draws inject seed-noise
    into committed timings (documented cross-seed inconsistency). This solver
    searches whole seconds in [ceil(lb), floor(ub)] directly -- rand/1
    mutation rounded to int + clamp, binomial crossover, greedy selection --
    with its OWN random.Random(seed) instance, so identical traffic states
    always commit identical timings regardless of whatever else consumed the
    global stream. (In 1-D, crossover's forced dimension always fires, so the
    trial IS the mutant; CR is kept for API shape.) Pure stdlib+numpy: scipy
    is unloadable in-sim. Fail-safe: objective exceptions/NaN score +inf;
    total failure returns float(lb) and callers clamp.
    """
    import random as _rnd_mod
    try:
        lo = int(math.ceil(float(lb)))
        hi = int(math.floor(float(ub)))
    except Exception:
        return float(lb)
    if hi <= lo:
        return float(lo)
    try:
        _pop = max(4, int(pop_size))
        _gens = max(0, int(max_generations))
        _F = min(1.0, max(0.0, float(F)))
        _CR = min(1.0, max(0.0, float(CR)))
    except Exception:
        return float(lo)
    # Adaptive hyperparameters (2026-09-27): fixed pop/gens waste evals on
    # tiny lattices and starve wide ones. Scale the population to the domain
    # width (the init already covers the lattice exhaustively when it fits),
    # so the eval budget follows the problem size on any corridor. Gens stay
    # as configured (solution quality knob); pop is the efficiency knob.
    try:
        _pop = min(_pop, max(4, int(hi - lo + 1)))
    except Exception:
        pass
    _rnd = _rnd_mod.Random(int(seed))

    def _cost(_x):
        try:
            _v = float(objective_function(int(_x), time))
        except Exception:
            return float('inf')
        if _v != _v:  # NaN
            return float('inf')
        return _v

    try:
        # Init: cover the lattice (exhaustive when the domain fits in the
        # population), deterministically shuffled so identical landscapes
        # replay identically.
        _lattice = list(range(lo, hi + 1))
        _rnd.shuffle(_lattice)
        _pop_x = [_lattice[i % len(_lattice)] for i in range(_pop)]
        _pop_f = [_cost(_x) for _x in _pop_x]
        _best_i = int(np.argmin(_pop_f))
        _best, _best_f = int(_pop_x[_best_i]), float(_pop_f[_best_i])
        for _g in range(_gens):
            for _i in range(_pop):
                _pool = [j for j in range(_pop) if j != _i]
                _r1, _r2, _r3 = _rnd.sample(_pool, 3)
                _mut = _pop_x[_r1] + _F * (_pop_x[_r2] - _pop_x[_r3])
                _mut = max(lo, min(hi, int(round(_mut))))
                # 1-D binomial crossover: the single dimension is always the
                # forced one, so the trial is the mutant (CR retained for shape).
                _trial = _mut if _rnd.random() < _CR else _pop_x[_i]
                _tf = _cost(_trial)
                if _tf <= _pop_f[_i]:
                    _pop_x[_i], _pop_f[_i] = int(_trial), float(_tf)
                    if _tf < _best_f:
                        _best, _best_f = int(_trial), float(_tf)
        return float(_best)
    except Exception:
        return float(lo)


def _solve_timing_min(self, objective_function, lb, ub, time):
    """Pick the timing solver: 'harmony' (legacy stochastic integer search),
    'golden' (deterministic golden-section, CONTINUOUS output), 'de'
    (deterministic differential evolution on the INTEGER lattice -- the only
    solver that is both global and discrete-time; recommended for GE/ER and
    all committed timing magnitudes), or 'exact' (exhaustive integer-lattice
    argmin -- the true global optimum on tiny timing domains, deterministic
    and cheaper than DE).  NOTE: all three optimise the shockwave
    objective, which is DEGENERATE for stopped buses (~0 bus delay) -- the
    real fix is BXT_SOLVER='deficit' (closed-form bus deficit), handled
    directly in dctsp_bxt, which never calls this."""
    _solver = str(globals().get('BXT_SOLVER', 'harmony')).lower()
    if _solver == 'exact':
        # Exact on the integer lattice: timing domains are tiny (GE 3..15 =
        # 13 integers), so exhaustive argmin IS the global optimum --
        # deterministic, no metaheuristic noise, fewer evals than DE. NaN /
        # raising points score +inf (same convention as DE).
        try:
            _lo = int(math.ceil(float(lb))); _hi = int(math.floor(float(ub)))
        except Exception:
            return float(lb)
        if _hi <= _lo:
            return float(_lo)
        _best_x, _best_f = _lo, float('inf')
        for _x in range(_lo, _hi + 1):
            try:
                _v = float(objective_function(int(_x), time))
            except Exception:
                continue
            if _v == _v and _v < _best_f:
                _best_x, _best_f = int(_x), float(_v)
        return float(_best_x)
    if _solver == 'de':
        return differential_evolution_search(
            objective_function, lb, ub, time,
            pop_size=int(globals().get('TIMING_DE_POP', 10)),
            max_generations=int(globals().get('TIMING_DE_GENS', 6)),
            F=float(globals().get('TIMING_DE_F', 0.7)),
            CR=float(globals().get('TIMING_DE_CR', 0.9)),
            seed=int(globals().get('TIMING_DE_SEED', 12345)))
    if _solver == 'harmony':
        return harmony_search(
            objective_function, lb, ub,
            int(getattr(self, 'max_iterations', 20)),
            int(getattr(self, 'harmony_memory_size', 10)),
            float(getattr(self, 'hmcr', 0.9)),
            float(getattr(self, 'par', 0.3)), 5, time)
    return golden_section_search(objective_function, lb, ub, time)


def stop_simulation(reason=""):
    """Immediately halt simulation. Always prints regardless of VERBOSE flag."""
    AKIPrintString(f"[STOP] ========== SIMULATION HALTED ==========")
    AKIPrintString(f"[STOP] Reason: {reason}")
    AKIPrintString(f"[STOP] =========================================")
    log_to_file(f"[STOP] {reason}")
    try:
        AKISimulationStop()
    except Exception:
        try:
            AKISetSimulationStopped()
        except Exception:
            pass


class DemandMonitor:
    """Print OD demand breakdown per vehicle type and slice."""

    def __init__(self):
        self.centroids = [
            AKIInfNetGetCentroidId(i)
            for i in range(AKIInfNetNbCentroids())
        ]

    def print_demand(self, label=""):
        n_types = AKIVehGetNbVehTypes()
        totals  = {}
        for vt in range(0, n_types + 1):
            num_slices = AKIODDemandGetNumSlicesOD(vt)
            if num_slices <= 0:
                continue
            vt_total = 0.0
            for sl in range(num_slices):
                for orig in self.centroids:
                    for dest in self.centroids:
                        if orig == dest:
                            continue
                        d = AKIODDemandGetDemandODPair(orig, dest, vt, sl)
                        if d > 0:
                            vt_total += d
            totals[vt] = vt_total

        _vprint(f"===== OD DEMAND {label} =====")
        _vprint(f"  vt=0 (ALL types) : {totals.get(0, 0):.1f}")
        for vt in range(1, n_types + 1):
            _vprint(f"  vt={vt}            : {totals.get(vt, 0):.1f}")
        _vprint(f"  centroids={len(self.centroids)}")









