BUS_FREQUENCY_MULTIPLIER = 1        # 2 = double buses, 3 = triple, etc.
TARGET_PT_LINE_IDS       = []       # [] = all lines, or e.g. [101, 102]

# ── ADD THIS FUNCTION ─────────────────────────────────────────────────────

def _vehicle_type_name(pos):
    """
    Return the lowercase name string for vehicle type at position pos.

    Aimsun versions differ in what AKIVehGetVehTypeName returns:
      - Newer SDK  : a Python str directly
      - Older SDK  : an opaque SWIG 'unsigned short *' object that needs
                     AKIConvertToAsciiString to decode
      - Some builds: AKIConvertToAsciiString itself returns another SWIG
                     object (the bug seen in the log: '<swig object...>')

    We try every known decoding path and fall back to an empty string rather
    than letting a '<swig object…>' leak into the keyword matching.
    """
    try:
        raw = AKIVehGetVehTypeName(pos)
    except Exception:
        return ""

    # AAPILoad can fire before the API is ready: raw is None, and str(None)
    # would leak out as the fake name "none" (seen in logs). Fail cleanly.
    if raw is None:
        return ""

    # Path 1 — raw is already a plain Python string
    if isinstance(raw, str):
        return raw.lower()

    # Path 2 — boolp() pointer for the 3rd (bool*) argument (PROVEN on 26:
    # 2-arg form throws TypeError 'missing anyNonAsciiChar'; 3-arg with a
    # plain bool throws 'argument 3 of type bool *'; SWIG boolp helpers ARE
    # exposed, per in-sim probe 2026-09-06).
    try:
        _boolp_fn = globals().get('boolp', None)
        _conv_fn = globals().get('AKIConvertToAsciiString', None)
        if _boolp_fn is not None and _conv_fn is not None and not isinstance(raw, str):
            for _del, _any in ((True, False), (False, False), (True, True)):
                try:
                    _bp = _boolp_fn()
                    try:
                        _bp.assign(True)
                    except Exception:
                        pass
                    _c = _conv_fn(raw, _del, _bp)
                    if isinstance(_c, str) and _c:
                        return _c.lower()
                    _s = str(_c)
                    if _s and "<swig" not in _s and _s.lower() != "none":
                        return _s.lower()
                except Exception:
                    continue
    except Exception:
        pass

    # Path 2 — AKIConvertToAsciiString returns a plain string
    try:
        converted = AKIConvertToAsciiString(raw, True)
        if isinstance(converted, str):
            return converted.lower()
        # converted is also a SWIG object — try str() on it and check
        s = str(converted)
        if "<swig" not in s:
            return s.lower()
    except Exception:
        pass

    # Path 3 — try AKIConvertToAsciiString with False flag (some versions differ)
    try:
        converted2 = AKIConvertToAsciiString(raw, False)
        if isinstance(converted2, str):
            return converted2.lower()
        s2 = str(converted2)
        if "<swig" not in s2:
            return s2.lower()
    except Exception:
        pass

    # Path 4 — try direct str() on the raw object
    s_raw = str(raw)
    if "<swig" not in s_raw:
        return s_raw.lower()

    # Path 5 — ctypes.wstring_at for UTF-16 (unsigned short* on Windows)
    # AKIVehGetVehTypeName returns unsigned short* which is UTF-16LE on Windows.
    try:
        import ctypes
        ptr_str = str(raw)
        if "0x" in ptr_str:
            ptr_val = int(ptr_str.split("0x")[1].rstrip(">").strip(), 16)
            name_w = ctypes.wstring_at(ptr_val)
            if name_w:
                return name_w.lower()
    except Exception:
        pass

    # Path 6 — ctypes.string_at for narrow (char*) encoding
    try:
        import ctypes
        ptr_str = str(raw)
        if "0x" in ptr_str:
            ptr_val = int(ptr_str.split("0x")[1].rstrip(">").strip(), 16)
            name_b = ctypes.string_at(ptr_val, 64)  # max 64 bytes
            name_decoded = name_b.decode("utf-16-le", errors="replace").split("\x00")[0]
            if name_decoded.isprintable() and len(name_decoded) > 0:
                return name_decoded.lower()
            name_decoded2 = name_b.decode("utf-8", errors="replace").split("\x00")[0]
            if name_decoded2.isprintable() and len(name_decoded2) > 0:
                return name_decoded2.lower()
    except Exception:
        pass

    # All paths failed — return empty; caller will rely on PT-line inference
    return ""


def _scan_named_vehicle_type_positions():
    car_pos = -1
    bus_pos = -1
    truck_pos = -1
    # Confirmed per-corridor mapping wins over fragile name decoding
    # (see VEH_TYPE_POS_OVERRIDE rationale above).
    try:
        _corr = os.path.basename(globals().get('_CORRIDOR_DIR', '') or '')
        _ovr = (globals().get('VEH_TYPE_POS_OVERRIDE', {}) or {}).get(_corr, {})
        if _ovr:
            return (int(_ovr.get('car', -1)), int(_ovr.get('bus', -1)),
                    int(_ovr.get('truck', -1)))
    except Exception:
        pass
    nb_types = AKIVehGetNbVehTypes()
    # Always log type names to file so we can diagnose non-English/coded type names
    log_to_file(f"[VEH SCAN] Total vehicle types: {nb_types}")
    for pos in range(1, nb_types + 1):
        name_str = _vehicle_type_name(pos)
        log_to_file(f"[VEH SCAN]   type pos={pos} name='{name_str}'")
        if not name_str:
            log_to_file(
                f"[VEH SCAN]   WARNING pos={pos} name unresolvable — "
                f"will rely on PT-line inference for bus type"
            )
        if bus_pos <= 0 and any(x in name_str for x in ("bus", "transit", "pt", "autobus", "ligne", "omnibus")):
            bus_pos = pos
        elif truck_pos <= 0 and any(x in name_str for x in ("truck", "heavy", "hgv", "lgv", "goods", "freight")):
            truck_pos = pos
        elif car_pos <= 0 and any(x in name_str for x in ("car", "pv", "private", "auto", "vehicle", "voiture", "pkw")):
            car_pos = pos
    return car_pos, bus_pos, truck_pos


# ── Demand-rated flow profile (pre-computed MILP parameters) ──────────────────
# The exact clairvoyant program consumes pre-computed parameters q_{i,p,t}
# (arrival flow per phase per step) and q_{ij,t} (link flow).  These are
# DEMAND-derived constants at the operating point, not runtime measurements --
# the microsimulation's own warm-up ramp (flow = 0 at t=0) says nothing about
# them.  Aimsun's GKTrafficDemand matrices carry the OD demand directly, so the
# rated corridor flow is known BEFORE the first vehicle enters:
#     q_rated = sum(OD matrix totals) * demand_factor / window_hrs
# This loader reads it once per run and stores it in:
#   _demand_flow_profile = {demand_name: {veh_type: vehicles}}   (raw OD totals)
#   _demand_rated_flow_vph = total vehicle-hours demand per hour (veh/h)
# plus a per-section share for the online estimators, see
# _seed_flow_estimators_from_demand().
_demand_flow_profile: dict = {}
_demand_rated_flow_vph: float = 0.0
_demand_profile_loaded: bool = False
# Baseline OD demand captured ONCE per session (unscaled), so every scalar is
# applied to the BASELINE (b*scalar) instead of the current (already-scaled)
# value. Without this the sweep compounded / froze after the first run, and the
# scalar==1.0 no-op left the previous run's scaling in place. {(vt,sl,o,d): base}.
_od_demand_baseline = None

# ── In-engine OD scaling: DISABLED (2026-09-05 audit) ────────────────────────
# _apply_od_demand_scalar() provably scaled 0 OD pairs in EVERY run to date
# (see kg/logs demand lines: "Applied Nx to 0 OD pairs"):
#   (a) AAPILoad fires before Aimsun loads OD demand (vt_with_demand == []), and
#   (b) the per-replication AAPIInit call cannot work -- AKIODDemandSetDemandODPair
#       is restricted to AAPILoad by the Aimsun API.
# The authoritative demand mechanism is console-side GKODMatrix.multiply() via
# batch_runner.scale_od_matrices_multiply(), applied BEFORE each replication is
# executed. Keep this flag False so a future fix of (a)/(b) cannot silently
# DOUBLE-scale (scalar^2) on top of the console mechanism. Set True only while
# deliberately testing the in-engine path, with the console scaler disabled.
OD_SCALE_IN_ENGINE_ENABLED = False

# ── Vehicle-type position overrides, by corridor ─────────────────────────────
# AKI vehicle-type name resolution fails on KG (SWIG pointer objects), so the
# name scan below returns (-1, -1, -1) and the OD scaler falls back to
# non-PT/all types. Fill the corridor entry once the mapping is confirmed --
# e.g. VEH_TYPE_POS_OVERRIDE = {"kg": {"car": 1, "truck": 2, "bus": 3}} --
# and _scan_named_vehicle_type_positions() will use it verbatim.
# HOW TO CONFIRM (one Aimsun-console run, corridor model open):
#   from batch_runner import probe_vehicle_types  # corridor's batch_runner
#   probe_vehicle_types()
# It prints every AKI type position with its decoded name AND which positions
# actually carry OD demand. The bus position must additionally agree with the
# PT-line inference ([VEH TYPES] pt_inferred_bus=... log line). NEVER guess:
# a wrong bus entry would scale transit demand.
#
# RESOLVED 2026-09-05 from campaign evidence (no guessing): every run folder's
# per-intersection CSV records the controller's live resolution
# (CarTypePos/BusTypePos/TruckTypePos, via the stats resolver chain:
# name scan -> ANGConnGetObjectIdByType -> PT-line inference -> run_config
# IDs). audit_intersections.py verified them stable across the whole history:
# KG (1,4,3) in 1442/1442 folders, Logan (1,3,2) in 253/253 folders, zero
# collisions, zero non-positive. These entries only win over fragile name
# decoding; an explicit run_config VEH_TYPE_ID_* still overrides everything.
VEH_TYPE_POS_OVERRIDE = {
    "kg": {"car": 1, "truck": 3, "bus": 4},
    "logan_road_new": {"car": 1, "truck": 2, "bus": 3},
}


def _apply_od_demand_scalar(scalar):
    """Scale car/truck OD demand pairs by *scalar* via AKIODDemandSetDemandODPair.

    KG's model defines demand through centroid-based OD demand (AKIODDemand)
    rather than GKTrafficDemand schedule factors.  The batch_runner's
    set_demand_scalar() modifies GKTrafficDemand factors, which has no effect
    on the actual OD demand that enters the simulation.  This function directly
    scales the OD demand values the simulation reads, so the demand sweep axis
    is actually live.

    Only car and truck vehicle types are scaled (matching batch_runner's
    set_demand_scalar), leaving PT demand untouched.

    HISTORIC ONLY -- gated by OD_SCALE_IN_ENGINE_ENABLED (False). Do not call
    from AAPIInit/AAPILoad unless deliberately testing this path with the
    console-side scaler disabled.
    """
    global _od_demand_baseline
    # Identify car/truck vehicle type positions (names differ per corridor, e.g.
    # KG 'PV -Car'/'Truck' vs Logan's classes). If none resolve, fall back to
    # every NON-PT type (exclude the bus position) rather than "all types", so we
    # never scale transit demand.
    try:
        scan_car_pos, scan_bus_pos, scan_truck_pos = _scan_named_vehicle_type_positions()
    except Exception:
        scan_car_pos, scan_bus_pos, scan_truck_pos = -1, -1, -1
    scalable_types = set()
    if scan_car_pos > 0:
        scalable_types.add(scan_car_pos)
    if scan_truck_pos > 0:
        scalable_types.add(scan_truck_pos)
    n_scaled = 0
    centroids = []
    n_types = 0
    vt_with_demand = []
    fallback_mode = not scalable_types
    try:
        centroids = [
            AKIInfNetGetCentroidId(i)
            for i in range(AKIInfNetNbCentroids())
        ]
        n_types = AKIVehGetNbVehTypes()
        fallback_mode = not scalable_types
        if _od_demand_baseline is None:
            _od_demand_baseline = {}
        # ── Which vehicle types actually have LOADED OD demand right now? ──
        # AAPILoad can fire BEFORE Aimsun loads the OD demand (sample==0). If we
        # captured a baseline then, it would be all zeros and poison every later
        # call. So probe first, and if NOTHING is loaded yet, do nothing (leave the
        # baseline untouched) -- a later AAPILoad, with demand present, captures it.
        for vt in range(0, n_types + 1):
            if fallback_mode:
                if scan_bus_pos > 0 and vt == scan_bus_pos:
                    continue                       # never scale PT/bus demand
            elif vt not in scalable_types:
                continue
            if AKIODDemandGetNumSlicesOD(vt) <= 0:
                continue
            if len(centroids) >= 2:
                for _o in range(min(len(centroids), 8)):
                    for _d in range(min(len(centroids), 8)):
                        if _o == _d:
                            continue
                        if AKIODDemandGetDemandODPair(
                                centroids[_o], centroids[_d], vt, 0) > 0:
                            vt_with_demand.append(vt)
                            break
                    if vt in vt_with_demand:
                        break
        if vt_with_demand:
            for vt in vt_with_demand:
                num_slices = AKIODDemandGetNumSlicesOD(vt)
                for sl in range(num_slices):
                    for orig in centroids:
                        for dest in centroids:
                            if orig == dest:
                                continue
                            key = (vt, sl, orig, dest)
                            try:
                                if key not in _od_demand_baseline:
                                    # Lazily capture the UNSCALED baseline the FIRST
                                    # time demand is present for this pair (sweep runs
                                    # 1.0 first / demand reloads unscaled per rep).
                                    _od_demand_baseline[key] = AKIODDemandGetDemandODPair(
                                        orig, dest, vt, sl)
                                _b = _od_demand_baseline.get(key, 0.0)
                                if _b > 0.0:
                                    # Always scale from BASELINE (1.0 -> restores it).
                                    # anewdemand is an INT trip count per the API docs.
                                    AKIODDemandSetDemandODPair(
                                        orig, dest, vt, sl, int(round(_b * scalar)))
                                    n_scaled += 1
                            except Exception:
                                pass
    except Exception as _ods_err:
        log_to_file(f"[DEMAND SCALAR] OD scaling error: {_ods_err!r}", force=True)
    log_to_file(
        f"[DEMAND SCALAR] Applied {scalar}x to {n_scaled} OD pairs from baseline "
        f"(centroid AKIODDemand path) car_pos={scan_car_pos} bus_pos={scan_bus_pos} "
        f"truck_pos={scan_truck_pos} baseline_pairs={len(_od_demand_baseline or {})}"
        f" vt_with_demand={vt_with_demand} n_types={n_types} n_centroids={len(centroids)}"
        f"{' [NON-PT FALLBACK]' if fallback_mode else ''}",
        force=True)


def _reset_demand_profile_flag():
    """Reset the demand-flow-profile loaded flag so the profile is re-read.

    The engine module is loaded once per Aimsun session and reused across
    replications.  _load_demand_flow_profile() sets a flag after its first
    call to avoid re-reading.  When the demand scalar changes between
    replications (Phase-3 sweep), the profile must be reloaded to reflect
    the new scaled demand totals.
    """
    global _demand_profile_loaded
    _demand_profile_loaded = False


def _load_demand_flow_profile():
    """Read OD demand totals from the active model's GKTrafficDemand objects.

    Mirrors kg/batch_runner.set_demand_scalar() naming rules (car/truck
    matrices, PT excluded) so the same matrices the batch scales are the ones
    profiled.  Populates module globals; safe to call multiple times (a flag
    guards re-reading).  Returns veh/h rated corridor flow (0 if demand
    unreadable -- callers fall back to runtime measurement).
    """
    global _demand_flow_profile, _demand_rated_flow_vph, _demand_profile_loaded
    if _demand_profile_loaded:
        return _demand_rated_flow_vph
    _demand_flow_profile = {}
    _demand_rated_flow_vph = 0.0
    try:
        # AUTHORITATIVE SOURCE: Aimsun's per-slice OD demand API (same one
        # DemandMonitor uses).  Unlike GKTrafficDemand totals this gives the
        # true demand that will enter over the window, slice by slice, and is
        # the value the demand scaler was applied to.
        centroids = [
            AKIInfNetGetCentroidId(i)
            for i in range(AKIInfNetNbCentroids())
        ]
        n_types = AKIVehGetNbVehTypes()
        for vt in range(0, n_types + 1):
            num_slices = AKIODDemandGetNumSlicesOD(vt)
            if num_slices <= 0:
                continue
            vt_total = 0.0
            for sl in range(num_slices):
                for orig in centroids:
                    for dest in centroids:
                        if orig == dest:
                            continue
                        d = AKIODDemandGetDemandODPair(orig, dest, vt, sl)
                        if d > 0:
                            vt_total += d
            if vt_total > 0.0:
                _demand_flow_profile["vehicle_type_%d" % vt] = vt_total
        _demand_rated_flow_vph = sum(_demand_flow_profile.values())
    except Exception as _dfe:
        _demand_rated_flow_vph = 0.0
        log_to_file(f"[DEMAND FLOW] profile load error: {_dfe!r}", force=True)
    _demand_profile_loaded = True
    return _demand_rated_flow_vph


def _infer_bus_type_pos_from_pt():
    """
    Infer the bus vehicle-type position by counting vehicle types on PT lines.
    Also tries AKIPTGetVehTypeOfLine (faster; available in some SDK versions).
    Returns the most common type position seen on PT lines, or -1 if none found.
    """
    counts = collections.Counter()

    try:
        n_lines = AKIPTGetNumberLines()
    except Exception:
        n_lines = 0

    for li in range(n_lines):
        try:
            line_id = AKIPTGetIdLine(li)
        except Exception:
            continue

        # Fast path: ask the line directly for its vehicle type (SDK 22+)
        # Wrapped in getattr so it fails silently if this API isn't available.
        try:
            _fn = globals().get("AKIPTGetVehTypeOfLine")
            if _fn is not None:
                vt = _fn(line_id)
                if vt > 0:
                    counts[int(vt)] += 10   # weight fast-path hits
                    continue
        except Exception:
            pass

        # Slow path: iterate vehicles on the line
        try:
            n_veh = AKIGetNbVehiclesFollowingPTLine(line_id)
        except Exception:
            continue
        for vi in range(n_veh):
            try:
                veh_id = AKIGetVehicleFollowingPTLine(line_id, vi)
                inf = AKIPTVehGetInf(veh_id)
                if getattr(inf, 'report', -1) >= 0 and getattr(inf, 'type', -1) > 0:
                    counts[int(inf.type)] += 1
            except Exception:
                continue

    return counts.most_common(1)[0][0] if counts else -1


def _build_pt_line_corridor_routes():
    """
    Build route-aware maps so coordination only targets junctions a bus will
    actually visit, using its filed PT plan from the Aimsun model.

    Populates four module-level dicts:
      _corridor_jct_incoming  {jct_id: set(section_ids)}  ← approach sections per junction
      _sec_to_corridor_jct    {section_id: [jct_id, ...]} ← reverse map
      _pt_line_section_set    {line_id: set(section_ids)}  ← every section on that PT line
      _pt_line_jct_route      {line_id: [jct_id, ...]}    ← ordered corridor junctions the
                                                              line passes through

    Called once from AAPISimulationReady after corridor positions are set.
    """
    global _corridor_jct_incoming, _sec_to_corridor_jct, _pt_line_section_set, _pt_line_jct_route

    # ── Step 1: build junction → incoming-section map from live controllers ───
    jct_incoming: dict = {}
    for jct_id, ctrl in controllers.items():
        secs = set()
        # primary approach sections (main corridor + topology fallback)
        for s in getattr(ctrl, 'incoming_sections', []):
            if isinstance(s, int) and s > 0:
                secs.add(s)
        # also include side sections so a bus using a side approach is caught
        for s in getattr(ctrl, 'side_sections', []):
            if isinstance(s, int) and s > 0:
                secs.add(s)
        if secs:
            jct_incoming[jct_id] = secs

    _corridor_jct_incoming = jct_incoming

    # ── Step 2: reverse map — section → which corridor junctions it feeds ─────
    sec_to_jct: dict = {}
    for jct_id, secs in jct_incoming.items():
        for sec_id in secs:
            sec_to_jct.setdefault(sec_id, []).append(jct_id)

    _sec_to_corridor_jct = sec_to_jct

    # ── Step 3: iterate every PT line, build section set + ordered jct list ───
    line_section_set: dict = {}
    line_jct_route: dict = {}

    try:
        n_lines = int(AKIPTGetNumberLines())
    except Exception:
        n_lines = 0

    for li in range(n_lines):
        try:
            line_id = AKIPTGetIdLine(li)
        except Exception:
            continue
        if line_id <= 0:
            continue

        try:
            n_secs = int(AKIPTGetNumberSectionsInLine(line_id))
        except Exception:
            n_secs = 0

        secs_on_line: list = []
        for si in range(n_secs):
            try:
                sec_id = int(AKIPTGetIdSectionInLine(line_id, si))
                if sec_id > 0:
                    secs_on_line.append(sec_id)
            except Exception:
                continue

        line_section_set[line_id] = set(secs_on_line)

        # Walk sections in route order; record the first time each corridor
        # junction is encountered (avoids double-counting loops)
        seen_jcts: set = set()
        ordered_jcts: list = []
        for sec_id in secs_on_line:
            for jct_id in sec_to_jct.get(sec_id, []):
                if jct_id not in seen_jcts:
                    seen_jcts.add(jct_id)
                    ordered_jcts.append(jct_id)

        if ordered_jcts:
            line_jct_route[line_id] = ordered_jcts

    _pt_line_section_set = line_section_set
    _pt_line_jct_route   = line_jct_route

    total_lines  = len(line_jct_route)
    total_routes = sum(len(v) for v in line_jct_route.values())
    log_to_file(
        f"[PT-ROUTE] Built corridor route map: {total_lines} PT lines cross "
        f"corridor junctions | {total_routes} (line,jct) pairs | "
        f"corridor junctions covered: "
        + str(sorted(jct_incoming.keys()))
    )


def _log_startup_bus_demand_snapshot(label: str = "init"):
    """
    Log a single startup snapshot of PT-line bus demand visibility.

    Includes:
      - PT line count
      - total PT-line vehicle entries
      - unique PT vehicle ids
      - unique vehicles matching inferred bus type
    """
    try:
        _n_lines = int(AKIPTGetNumberLines())
    except Exception:
        _n_lines = 0

    _all_ids = set()
    _bus_ids = set()
    _entries = 0

    _bus_type = int(getattr(stats, '_bus_pos', -1) or -1)
    if _bus_type <= 0:
        try:
            _bus_type = int(_infer_bus_type_pos_from_pt() or -1)
        except Exception:
            _bus_type = -1

    for _li in range(_n_lines):
        try:
            _line_id = AKIPTGetIdLine(_li)
            _n = int(AKIGetNbVehiclesFollowingPTLine(_line_id))
        except Exception:
            continue
        _entries += max(_n, 0)
        for _vi in range(max(_n, 0)):
            try:
                _vid = int(AKIGetVehicleFollowingPTLine(_line_id, _vi))
                if _vid <= 0:
                    continue
                _all_ids.add(_vid)
                _inf = AKIPTVehGetInf(_vid)
                _typ = int(getattr(_inf, 'type', -1) or -1)
                if _bus_type > 0 and _typ == _bus_type:
                    _bus_ids.add(_vid)
            except Exception:
                continue

    log_to_file(
        f"[DEMAND] startup snapshot ({label}) | pt_lines={_n_lines} "
        f"pt_entries={_entries} unique_pt_veh={len(_all_ids)} "
        f"bus_type_pos={_bus_type} unique_bus_veh={len(_bus_ids)}",
        force=True,
    )


def _choose_car_type_pos(bus_pos, truck_pos, preferred_pos=-1):
    nb_types = AKIVehGetNbVehTypes()
    exclude = {p for p in (bus_pos, truck_pos) if p and p > 0}
    if preferred_pos > 0 and preferred_pos not in exclude:
        return preferred_pos
    for pos in range(1, nb_types + 1):
        if pos in exclude:
            continue
        name_str = _vehicle_type_name(pos)
        if any(x in name_str for x in ("car", "pv", "private", "auto")):
            return pos
    for pos in range(1, nb_types + 1):
        if pos not in exclude:
            return pos
    return -1




class BusKalmanTracker:
    """
    State vector: [position_m, speed_m_s]
    Transition:   constant-velocity model  (F = [[1, dt], [0, 1]])
    Observation:  position only            (H = [1, 0])
    """

    DEFAULT_SPEED_MS = 11.0   # ≈ 40 km/h initial speed prior
    # Realistic ETA ceiling (2026-09-28): a bus farther out than this is "too
    # far to act on" -- anything beyond reads as effectively unactionable and
    # only pollutes decision math (reachability vetoes fire anyway). Keeps the
    # away-case 99999 and the dist/speed blow-up (crawling bus) from leaking
    # into pred_bus / pre-arm leads / corridor projections.
    ETA_MAX_S = 300.0
    # Plausible urban-bus speed band for the filter. The FLOOR must be low enough
    # to represent a queued/crawling bus -- a 4 m/s (14 km/h) floor forced every
    # congested bus to look free-flowing, making downstream ETAs too optimistic
    # and mistiming the green wave (bus arrives after the pre-armed green closes).
    # 0.5 m/s lets the filter say "this bus is basically stopped", so its ETA
    # correctly blows out and the coordinator won't pre-arm a far junction for it.
    MIN_SPEED_MS = 0.5
    MAX_SPEED_MS = 20.0

    def __init__(self, initial_pos_m: float = 0.0):
        self.x = np.array([initial_pos_m, self.DEFAULT_SPEED_MS], dtype=float)
        self.P = np.diag([400.0, 16.0])     # initial state covariance (pos±20m, spd±4m/s)
        # Process noise: Q scales with dt inside predict().
        # q_pos=3 m²/s (bus can jerk, stop at lights), q_spd=0.5 m²/s³ (acceleration noise)
        self.Q = np.diag([3.0, 0.5])
        # Observation noise: std≈30 m accounts for detector placement uncertainty
        # A larger R makes predictions less sensitive to individual position fixes
        # and keeps speed estimates smooth across multiple junctions.
        self.R = 900.0
        self.last_t: float = None
        # Track the corridor-group index of the last junction this bus was seen at.
        # Used by the coordinator to determine travel direction.
        self._prev_inter_idx: int = -1

    def predict(self, dt: float):
        dt = max(dt, 0.0)
        F  = np.array([[1.0, dt], [0.0, 1.0]])
        self.x = F @ self.x
        self.P = F @ self.P @ F.T + self.Q * dt

    def update(self, obs_pos_m: float):
        H    = np.array([1.0, 0.0])
        innov = obs_pos_m - self.x[0]
        S    = float(H @ self.P @ H) + self.R
        K    = self.P @ H / S
        self.x = self.x + K * innov
        self.P = (np.eye(2) - np.outer(K, H)) @ self.P
        # Clamp speed to plausible urban bus range [4, 20] m/s (14–72 km/h)
        # A tighter clamp prevents numerical drift and keeps ETAs realistic.
        self.x[1] = max(self.MIN_SPEED_MS, min(self.MAX_SPEED_MS, abs(self.x[1]))) * (1.0 if self.x[1] >= 0 else -1.0)

    def update_speed_from_travel(self, prev_pos_m: float, curr_pos_m: float,
                                  elapsed_s: float):
        """
        When a bus reaches a new junction we have a direct measurement of
        average speed over the inter-junction segment.  Fuse that observation
        into the state as a second Kalman update step.

        This is far more informative than position-only updates because it
        corrects the velocity component directly, leading to better ETAs at
        the next downstream junction.
        """
        if elapsed_s < 5.0:
            return   # avoid division by near-zero if timestamps are too close
        actual_speed = (curr_pos_m - prev_pos_m) / elapsed_s   # signed m/s
        # Clamp to plausible range before fusing
        actual_speed = max(self.MIN_SPEED_MS, min(self.MAX_SPEED_MS, abs(actual_speed))) * (1.0 if actual_speed >= 0 else -1.0)
        # Kalman update for speed observation:  H_v = [0, 1]
        H_v   = np.array([0.0, 1.0])
        R_v   = 4.0                                # speed obs noise var (std ≈ 2 m/s)
        innov = actual_speed - self.x[1]
        S_v   = float(H_v @ self.P @ H_v) + R_v
        K_v   = self.P @ H_v / S_v
        self.x = self.x + K_v * innov
        self.P = (np.eye(2) - np.outer(K_v, H_v)) @ self.P
        # Re-clamp after speed update
        self.x[1] = max(self.MIN_SPEED_MS, min(self.MAX_SPEED_MS, abs(self.x[1]))) * (1.0 if self.x[1] >= 0 else -1.0)

    def eta(self, target_pos_m: float, current_time: float) -> float:
        """
        Estimated arrival time (sim seconds) at target_pos_m.
        Handles both northbound (velocity > 0) and southbound (velocity < 0).
        Returns a very large number if the bus is moving away from the target.
        """
        dist  = target_pos_m - self.x[0]   # positive = target is ahead (north)
        speed = self.x[1]                   # positive = northbound
        try:
            _eta_max = float(getattr(self, 'ETA_MAX_S', 300.0) or 300.0)
        except Exception:
            _eta_max = 300.0
        if abs(dist) < 1.0:
            return current_time             # already at target
        if speed > 0 and dist > 0:          # northbound, target ahead
            _t = current_time + dist / speed
        elif speed < 0 and dist < 0:        # southbound, target behind
            _t = current_time + abs(dist) / abs(speed)
        else:
            # Bus heading away from target — effectively unreachable.
            # Cap, don't emit 99999: an exploding value would leak into
            # decision math, but the caller only needs "too far to act on".
            _t = current_time + _eta_max
        # Realistic ceiling: never read farther than ETA_MAX_S ahead.
        _t = max(float(current_time), float(_t))
        return min(float(_t), float(current_time) + _eta_max)

    def uncertainty_s(self, target_pos_m: float) -> float:
        """1-sigma arrival-time uncertainty (seconds)."""
        dist  = abs(target_pos_m - self.x[0])
        speed = max(abs(self.x[1]), 1.0)
        # propagate position and speed variance to time variance
        var_t = self.P[0, 0] / speed**2 + self.P[1, 1] * (dist / speed**2)**2
        return math.sqrt(max(var_t, 0.0))

    def uncertainty_for_remaining(self, remaining_m: float) -> float:
        """1-sigma arrival-time uncertainty given remaining distance to the
        stop line (no absolute-position bookkeeping needed by callers)."""
        speed = max(abs(float(self.x[1])), 1.0)
        rem = max(0.0, float(remaining_m))
        var_t = float(self.P[0, 0]) / speed**2 \
            + float(self.P[1, 1]) * (rem / speed**2) ** 2
        return math.sqrt(max(var_t, 0.0))


def _eta_s_for(trackers, corridor_pos, veh_id, target_jct_id, time,
               fallback_s=None):
    """Systematic adaptive-Kalman bus ETA (2026-09-28).

    ONE estimator for every decision path: seconds-from-now arrival of
    veh_id at target_jct_id, backed by the 1-D constant-velocity Kalman
    tracker when it exists (position+speed state, uncertainty propagated),
    else a clamped distance/speed fallback. Always capped at
    BUS_ETA_MAX_S (realistic ceiling -- a bus farther out is unactionable),
    never negative, and always returns the 1-sigma so callers can act on
    confidence (adaptive lead, reachability tolerance). Returns
    (eta_s | None, sigma_s | None, source) where source in
    {'kalman', 'fallback', 'none'}.
    """
    try:
        _emx = float(globals().get('BUS_ETA_MAX_S', 300.0) or 300.0)
    except Exception:
        _emx = 300.0
    try:
        _trk = (trackers or {}).get(int(veh_id))
    except Exception:
        _trk = None
    try:
        _pos = (corridor_pos or {}).get(target_jct_id)
    except Exception:
        _pos = None
    if _trk is not None and _pos is not None:
        try:
            _eta_t = float(_trk.eta(float(_pos), float(time)))
            _sigma = float(_trk.uncertainty_s(float(_pos)))
            _eta = max(0.0, _eta_t - float(time))
            return min(_eta, _emx), min(max(_sigma, 0.0), _emx), "kalman"
        except Exception:
            pass
    if fallback_s is not None and float(fallback_s) > 0.0:
        return min(float(fallback_s), _emx), 12.0, "fallback"
    return None, None, "none"


# =============================================================================
# CORRIDOR COORDINATOR
#
# When COORDINATED_TSP=False (default): pure state-sync logging only.
# When COORDINATED_TSP=True: Kalman-filter prediction arms downstream
#   intersections before the bus arrives, creating a rolling green wave.
#
# Coordination flow (COORDINATED_TSP=True):
#   1. Bus gets priority at intersection[i]  →  GroupBasedController calls
#      coordinator.notify_bus_granted(veh_id, jct_i, time, bus_sg)
#   2. Coordinator updates the Kalman tracker for that vehicle and predicts
#      arrival ETA at jct[i+1], [i+2], [i+3]
#   3. Each step(), when (ETA - current_time) ≤ PRE_GREEN_LEAD_S, the
#      coordinator fires bus_request on that downstream controller so it
#      has a green phase ready on arrival.
# =============================================================================

class CorridorCoordinator:
    """
    Corridor Coordinator (CC) — links junctions along a bus route so that
    a priority grant at junction[i] automatically pre-arms junction[i+1..n].

    How it works
    ------------
    1. Bus detected at junction[i] → CC is notified via notify_bus_at_junction().
    2. CC computes an ETA for each downstream junction using the configured
       COORDINATION_ALGO (KALMAN / SHOCKWAVE / OBJECTIVE / ADAPTIVE).
    3. When ETA - PRE_GREEN_LEAD_S is reached, CC fires a pre-arm request on
       the downstream junction's GroupBasedController (or sets _harmony_prearm
       on a phase-based IntersectionController).
    4. The downstream junction holds its bus phase ready so the bus arrives
       into green rather than red.
    5. Pre-arm requests expire after PRE_REQ_TIMEOUT_S if the bus is delayed
       or diverts; the junction then returns to its normal cycle.
    """

    LOG_CORRIDOR_INTERVAL = 30.0   # seconds between periodic state dumps
    # ── Pre-arm lead time ─────────────────────────────────────────────────────
    # How many seconds before estimated bus arrival to fire the pre-arm request.
    # Must be large enough for the downstream junction to:
    #   (a) finish its current phase (worst-case ~50 s for long cycles)
    #   (b) execute intergreen (~5 s)
    #   (c) ramp up its bus phase before the bus reaches the stop line
    # 25 s was too short — a junction mid-phase routinely has 30–50 s remaining,
    # so the bus arrived before the phase could be set up, defeating coordination.
    # 50 s covers worst-case phase-remaining + intergreen for all Logan Rd junctions.
    PRE_GREEN_LEAD_S          = 50.0
    MIN_EFFECTIVE_PREARM_LEAD_S = 10.0  # discard prearm if bus is already this close
    MAX_PRE_ARM               = 1      # pre-arm only the immediately next junction
    PRE_REQ_TIMEOUT_S         = 90.0   # stale pre-request expiry
    MIN_UNMANAGED_DELAY_S = 10.0   # delay buffer per unmanaged in-system junction
    MAX_UNMANAGED_DELAY_S = 25.0

    def __init__(self, group_name: str, inter_ids: list, controllers_map: dict):
        self.name = group_name
        # Pass-gate hold diagnostics (2026-09-28): per-target-junction counters
        # so a junction persistently held by the 25 m source-clearance gate
        # (starvation) is visible in the log vs. one that clears each bus.
        self._pass_hold_n = {}       # target jid -> times held
        self._pass_hold_t0 = {}      # (veh, target) -> first-hold sim time
        self._pass_cleared = {}      # target jid -> held-then-fired
        self._pass_starved = {}      # target jid -> held-then-expired/discarded
        self._last_pass_summary = -1e9
        # GB controllers (GROUP_BASED_* modes) — full coordination support.
        self.inter_ids = [
            iid for iid in inter_ids
            if iid in controllers_map and controllers_map[iid].gb is not None
        ]
        self._ctrl_map = {iid: controllers_map[iid].gb for iid in self.inter_ids}

        # HARMONY IntersectionControllers — simplified coordination support.
        # Indexed by inter_id → IntersectionController (no gb attribute).
        # pre-arm sets _harmony_prearm on the controller; check_bus_priority handles it.
        self._ic_map: dict = {
            iid: controllers_map[iid]
            for iid in inter_ids
            if iid in controllers_map and controllers_map[iid].gb is None
        }
        # Merged inter_ids includes both GB and IC intersections
        self.inter_ids = list(dict.fromkeys(self.inter_ids + list(self._ic_map.keys())))
        route_ids = list(CORRIDOR_ROUTE_GROUPS.get(group_name, inter_ids))
        self.route_inter_ids = []
        for iid in route_ids:
            if iid in INTERSECTIONS_CONFIG or iid in self.inter_ids:
                self.route_inter_ids.append(iid)
        for iid in self.inter_ids:
            if iid not in self.route_inter_ids:
                self.route_inter_ids.append(iid)
        self._route_index = {iid: idx for idx, iid in enumerate(self.route_inter_ids)}
        # Controllers for EVERY route junction (members AND non-members), so the
        # cascade's downstream-cell lookup can reach non-member route junctions
        # (Logan route has 8 but only 4 are managed members). Values are
        # IntersectionControllers (same type as _ic_map).
        self._route_ctrl_map = {iid: controllers_map[iid]
                                for iid in self.route_inter_ids
                                if iid in controllers_map}
        self._last_log_t   = -self.LOG_CORRIDOR_INTERVAL
        self._last_sync_t  = -999.0
        self._sync_count   = 0

        # Kalman tracking state
        # {veh_id: BusKalmanTracker}
        self._trackers: dict = {}
        # Corridor positions along the route (metres from first intersection)
        # Populated by set_corridor_positions() in AAPISimulationReady.
        self.corridor_pos: dict = {}
        # Pre-green requests: {inter_id: (veh_id, eta_t, bus_sg, issued_t, source_jct)}
        self._pre_requests: dict = {}
        self._pre_arm_count: int = 0

        # ── Coord-prearm outcome statistics ───────────────────────────────────
        # Answers "did the coordinator actually deliver a green wave?"
        # Key metrics:
        #   fired    — pre-arm request was set on downstream gb.bus_request
        #   success  — bus physically arrived at that junction during green phase
        #              (logged by GroupBasedController when it activates a coord-sourced request)
        #   missed   — pre-arm fired but bus was still in red on arrival
        #              (this happens when ETA is off or phase didn't have time to cycle)
        #   expired  — pre-request timed out (bus took a different route or was delayed > PRE_REQ_TIMEOUT_S)
        #   discarded— pre-arm fired but GB discarded it (cooldown, no bus_sg, wrong state)
        #   eta_errors_s — list of (actual_arrival − predicted_eta) values, for calibration
        #                  positive = bus arrived later than predicted
        #                  negative = bus arrived earlier than predicted
        self._prearm_stats: dict = {
            "fired":        0,
            "revised":      0,
            "cancelled_adherence": 0,
            "skipped_early_bus": 0,
            "success":      0,
            "missed":       0,
            "expired":      0,
            "discarded":    0,
            "late_success": 0,
            "late_success_delay_s": 0.0,
            "eta_errors_s": [],
            "too_far": 0,
            "too_late_to_act": 0,
            "revalidation_skip": 0,
            "skipped_cooldown": 0,
        }
        # Revisable pre-arm plans: (veh_id, inter_id) -> plan dict.  A pre-arm
        # is a STATEMENT ABOUT THE FUTURE and must be revisable: the tick
        # re-evaluates each plan against the latest adherence multiplier and
        # cancels/downgrades when fidelity says the bus no longer deserves
        # priority (early/on-time buses are better held at red).
        self._prearm_plans: dict = {}
        # Tracking: {(inter_id, veh_id): (eta_t, fired_at_t)} for outcome reporting
        self._fired_prearms: dict = {}
        # Lightweight diagnostics to confirm whether algorithm variants are
        # changing queue ETA and pre-arm lead decisions in practice.
        self._algo_diag: dict = {
            "queued": 0,
            "sw_adj_count": 0,
            "sw_adj_total_s": 0.0,
            "sw_adj_max_s": 0.0,
            "adaptive_fire_count": 0,
            "adaptive_dynamic_count": 0,
            "adaptive_lead_total_s": 0.0,
            "adaptive_lead_min_s": 1e9,
            "adaptive_lead_max_s": 0.0,
        }

        # ── Coordination wave state ───────────────────────────────────────────
        # When a bus is granted priority at any corridor junction a "wave" begins.
        # During the wave ALL other junctions block INDEPENDENT bus detections;
        # only coordinator-fired (pre-armed) requests are allowed through.
        # The ban lifts once all pre-requests for that wave vehicle have resolved.
        #
        # _wave_active     : True while a green-wave is in progress
        # _wave_veh_id     : vehicle that triggered the wave
        # _wave_origin     : junction ID where the wave started
        # _wave_served_ids : junctions that have already been pre-armed this wave
        #                    (once served, ban lifts individually for that junction)
        self._wave_active:     bool  = False
        self._wave_veh_id:     int   = -1
        self._wave_origin:     int   = -1
        self._wave_served_ids: set   = set()
        # Junctions where sigma was too high to pre-arm — wave ban is lifted so
        # they can run independent detection instead of waiting for a stale prearm.
        self._wave_uncertain_jcts: set = set()
        # Logged once per (from_jct, target_jct) pair when sigma or horizon gate
        # blocks a pre-arm.  Prevents log spam while keeping diagnostics visible.
        self._prearm_skip_logged_jcts: set = set()
        # Live ETA predictions per (target_jct, veh_id), overwritten on each
        # prearm_queued revision so the stored entry is always the latest
        # prediction: [(remaining s at queue time), (queue sim-time s)].
        # Popped by _record_prearm_success so a reused vehicle ID can never
        # match a stale prediction.  Feeds the qeta_* calibration columns.
        self._queued_etas: dict = {}

        log_to_file(
            f"[CORRIDOR] group={self.name} members={self.inter_ids} "
            f"route={self.route_inter_ids} "
            f"(GB={len(self._ctrl_map)} IC-HARMONY={len(self._ic_map)} "
            f"of {len(inter_ids)} configured) "
            f"coordinated_tsp={COORDINATED_TSP}"
        )

        # Wire back-reference into each GB controller so it can call
        # notify_bus_granted() without needing the global list.
        for gb in self._ctrl_map.values():
            gb._corridor_coord = self
        # Wire back-reference into HARMONY IntersectionControllers too.
        for ic in self._ic_map.values():
            ic._corridor_coord = self
        # Also wire the back-reference into the controllers of ROUTE junctions
        # that are NOT managed members (GB/IC). The downstream CASCADE cost only
        # needs self._corridor_coord to reach the route index -> locate downstream
        # cells; without this, a route junction that runs TSP but isn't a member
        # (e.g. Logan 17308/17498/17628/18044 -- 4 of the 8-junction route) had
        # _corridor_coord=None -> [CASCADE_ZERO] reason=no_corridor_coord ->
        # cascade inert for half the corridor (2026-09-16). This does NOT make
        # them managed: the coordinator still only pre-arms members; it only lets
        # their local decider price the network cascade.
        for _riid in self.route_inter_ids:
            _rc = controllers_map.get(_riid)
            if _rc is None:
                continue
            if getattr(_rc, '_corridor_coord', None) is None:
                _rc._corridor_coord = self
            _rgb = getattr(_rc, 'gb', None)
            if _rgb is not None and getattr(_rgb, '_corridor_coord', None) is None:
                _rgb._corridor_coord = self

        # ── Per-bus grant time tracker (for offset computation) ──────────────────────
        # {veh_id: {jct_id: sim_time_s}} — updated in notify_bus_granted.
        self._grant_times: dict = {}
        # {(veh_id, jct_id): last_logged_time_s} — suppress duplicate log rows
        self._last_offset_logged: dict = {}
        # {(veh_id, jct_id): last_notify_t} — debounce repeated grant callbacks
        # from the same junction while a bus is still in the same detection zone.
        self._last_grant_notify_t: dict = {}

    # ------------------------------------------------------------------
    def _shockwave_eta_adjust(self, next_gb, next_bus_sg, eta: float, next_ic=None):
        """
        Queue-aware ETA correction using shockwave discharge logic.

        Uses the PREDICTED peak queue from the intersection's own shockwave
        model (MaxQueueLength, already computed from UpFlowList + shockwave
        speeds) rather than the live vehicle count.  The live count is always
        0 at pre-arm time (the bus hasn't arrived yet), which is why the old
        implementation never produced a non-zero correction.

        Falls back to live queue count if the model has no estimate yet.
        For HARMONY intersections (next_gb=None, next_ic set), uses live
        vehicle counts on approach sections as a queue proxy.

        Returns
        -------
        (eta_adj, queue_len_veh, eta_delta, sw_diag)
        """
        # Default parameters
        sat_flow  = 1800.0
        jam_den   = 150.0
        sat_den   = 45.0
        headway_s = 2.0
        n_lanes = 1
        sw_diag = {
            "sat_flow_vph": sat_flow,
            "jam_den_vpkm": jam_den,
            "sat_den_vpkm": sat_den,
            "headway_s": headway_s,
            "queue_len_veh": 0.0,
            "queue_clearance_s": 0.0,
            "wave_delay_s": 0.0,
            "shockwave_w4_ms": 0.0,
            "queue_len_m": 0.0,
        }

        if next_gb is not None:
            try:
                sat_flow = max(getattr(next_gb, 'SaturationFlow', 1800.0), 100.0)
                jam_den  = max(getattr(next_gb, 'JamDensity',     150.0),  10.0)
                sat_den  = max(getattr(next_gb, 'SaturationDensity', 45.0), 5.0)
                n_lanes  = max(getattr(next_gb, 'NumberOfLanes',    1),       1)
                headway_s = max(1.2, 3600.0 / sat_flow)
                sw_diag.update({
                    "sat_flow_vph": sat_flow,
                    "jam_den_vpkm": jam_den,
                    "sat_den_vpkm": sat_den,
                    "headway_s": headway_s,
                    "n_lanes": float(n_lanes),
                })

                bus_phase = getattr(next_gb, 'bus_phase', None)
                phase_idx = 0
                if bus_phase is not None and hasattr(next_gb, 'PhaseIndex'):
                    phase_idx = next_gb.PhaseIndex.get(bus_phase, 0)

                mql = getattr(next_gb, 'MaxQueueLength', None)
                queue_len = 0
                if mql is not None and phase_idx < len(mql) and len(mql[phase_idx]) > 0:
                    max_queue_m = float(mql[phase_idx][0])
                    if max_queue_m > 0.5:
                        queue_len = max(1, int(max_queue_m * jam_den / 1000.0 * n_lanes))

                if queue_len <= 0:
                    q = next_gb._compute_queue()
                    queue_len = max(int(q.get(next_bus_sg, 0)), 0)

                if queue_len <= 0:
                    try:
                        q_all = next_gb._compute_queue()
                        queue_len = max((int(v or 0) for v in q_all.values()), default=0)
                    except Exception:
                        queue_len = 0
            except Exception:
                queue_len = 0

        elif next_ic is not None:
            # HARMONY IntersectionController — no GB, use section vehicle counts
            try:
                queue_len = 0
                headway_s = 2.0
                # Count stopped/slow vehicles on approach sections as queue proxy
                for sec_id in getattr(next_ic, 'incoming_sections', []):
                    try:
                        n_veh = max(int(AKIVehStateGetNbVehiclesSection(sec_id, True)), 0)
                        stopped = 0
                        for vi in range(n_veh):
                            try:
                                vinf = AKIVehStateGetVehicleInfSection(sec_id, vi)
                                spd = float(getattr(vinf, 'CurrentSpeed', 0.0) or 0.0)
                                if spd < 5.0:  # km/h — effectively queued
                                    stopped += 1
                            except Exception:
                                continue
                        queue_len += stopped
                    except Exception:
                        continue
            except Exception:
                queue_len = 0
        else:
            return eta, 0, 0.0, sw_diag

        if queue_len <= 0:
            return eta, 0, 0.0, sw_diag

        try:
            # queue_clearance_s: time for all queued vehicles to pass the stopline
            # at saturation flow (simple headway model).
            queue_clearance_s = queue_len * headway_s

            # wave_delay_s: time for the discharge wave to travel back through
            # the entire queue to the bus.
            #   queue_distance_m = queue_len / jam_den_per_m
            #   discharge_wave_speed_ms = ShockwaveSpeed4 (m/s)
            # NOTE: ShockwaveSpeed4 already returns m/s (not km/h), so no
            # extra unit conversion is needed.  The old formula
            # "queue_len / w4 / (jam_den-sat_den) * 1000" was wrong — it
            # double-divided by density and produced the same value as
            # queue_clearance_s, giving an artificially large sw_adj.
            w4 = abs(ShockwaveSpeed4(sat_flow, jam_den, sat_den))  # m/s
            queue_m = queue_len * 1000.0 / max(jam_den, 1.0)       # m
            wave_delay_s = queue_m / max(w4, 0.001)                 # s

            # Use the smaller of the two estimates; cap at 30 s so a single
            # pre-arm event cannot create an excessively long insertion.
            eta_delta = min(queue_clearance_s, wave_delay_s, 30.0)
            sw_diag.update({
                "queue_len_veh": float(queue_len),
                "queue_clearance_s": float(queue_clearance_s),
                "wave_delay_s": float(wave_delay_s),
                "shockwave_w4_ms": float(w4),
                "queue_len_m": float(queue_m),
            })
            return eta + eta_delta, queue_len, eta_delta, sw_diag
        except Exception:
            return eta, 0, 0.0, sw_diag

    # ------------------------------------------------------------------
    def _pass_gate_starve(self, inter_id: int, veh_id: int, reason: str):
        """A request that was held by the source-clearance gate and then died
        (expired/discarded/too-far) never fired: record the starvation."""
        if (veh_id, inter_id) in self._pass_hold_t0:
            self._pass_hold_t0.pop((veh_id, inter_id), None)
            self._pass_starved[inter_id] = int(self._pass_starved.get(inter_id, 0)) + 1
            if LOG_CORRIDOR:
                log_to_file(
                    f"[PASSGATE] jct={inter_id} bus={veh_id} "
                    f"STARVED ({reason}) -- held then died without firing"
                )

    def _record_prearm_fired(self, inter_id: int, veh_id: int, eta_t: float,
                             fired_at_t: float, source_jct: int = -1,
                             algo: str = "", lead_reason: str = ""):
        # Do NOT overwrite an existing active prearm entry.  Once a prearm has
        # been fired for a (junction, bus) pair, keep the original eta/fired_t
        # so that _record_prearm_success (which pops the entry) only logs
        # ONE success per logical prearm event.  Re-overwriting here would let
        # the coordinator re-populate the entry every management step, causing
        # prearm_success to fire on every subsequent notify_bus_granted call.
        key = (inter_id, veh_id)
        # Pass-gate clear bookkeeping: a request that was held by the source-
        # clearance gate and now fires is CLEARED (the starved-path inverse).
        _t0 = self._pass_hold_t0.pop(key, None)
        if _t0 is not None:
            self._pass_cleared[inter_id] = int(self._pass_cleared.get(inter_id, 0)) + 1
            if LOG_CORRIDOR:
                log_to_file(
                    f"[PASSGATE] jct={inter_id} bus={veh_id} "
                    f"CLEARED after {float(time) - float(_t0):.1f}s hold"
                )
        # ── Revisable plan registry: a repeated fire for the SAME pair with a
        # materially different ETA is a REVISION of the intention, not a new
        # event.  Track it so the paper can report plan churn honestly.
        _plan = self._prearm_plans.get(key)
        if _plan is not None and abs(float(eta_t) - float(_plan["eta_t"])) > 2.0:
            self._prearm_stats["revised"] += 1
            _plan["eta_t"] = float(eta_t)
            _plan["revisions"] = _plan.get("revisions", 0) + 1
            _plan["mult"] = float(
                (_ETA_TRACK.get(int(veh_id)) or {}).get("mult", 1.0))
        if key in self._fired_prearms:
            return  # already pending — skip (deduplication)
        self._prearm_stats["fired"] += 1
        trk = _ETA_TRACK.get(int(veh_id)) or {}
        self._prearm_plans[key] = {
            "eta_t": float(eta_t), "created": float(fired_at_t),
            "mult": float(trk.get("mult", 1.0)), "revisions": 0,
            "status": "armed",
        }
        self._fired_prearms[key] = (
            float(eta_t), float(fired_at_t), int(source_jct),
            str(algo or COORDINATION_ALGO), str(lead_reason or "fixed")
        )
        # Lift the wave ban for this junction as soon as its prearm is committed.
        # Without this the junction stays banned until notify_bus_granted fires,
        # which may never happen if the coordinator never re-arms it.
        self._wave_served_ids.add(inter_id)
        # Deduplicate: only write a wave event if no recent prearm_fired was written
        # for this (veh_id, inter_id) pair within 60 s.  Prevents wave-event CSV spam
        # when the coordinator re-evaluates ETA on every step while a bus is in transit.
        if not hasattr(self, '_prearm_fired_log_t'):
            self._prearm_fired_log_t = {}
        _fire_key = (veh_id, inter_id)
        _last_log = self._prearm_fired_log_t.get(_fire_key, -999.0)
        if fired_at_t - _last_log < 60.0:
            return   # suppress duplicate within 60 s window
        self._prearm_fired_log_t[_fire_key] = fired_at_t
        _src = int(source_jct) if int(source_jct) > 0 else int(self._wave_origin)
        _algo = str(algo or COORDINATION_ALGO)
        _record_wave_event(
            fired_at_t, self.name, "prearm_fired",
            source_jct=_src,
            target_jct=inter_id,
            veh_id=veh_id,
            eta_s=max(0.0, float(eta_t) - float(fired_at_t)),
            note=str(lead_reason or "fixed"),
            algo=_algo,
        )

    # ------------------------------------------------------------------
    def _record_prearm_discarded(self, inter_id: int):
        self._prearm_stats["discarded"] += 1
        _record_wave_event(
            AKIGetCurrentSimulationTime(), self.name, "prearm_discarded",
            source_jct=self._wave_origin,
            target_jct=inter_id,
            veh_id=self._wave_veh_id,
        )

    # ------------------------------------------------------------------
    def _record_prearm_success(self, inter_id: int, veh_id: int, actual_t: float):
        key = (inter_id, veh_id)
        rec = self._fired_prearms.pop(key, None)
        if rec is None:
            return
        eta_t = float(rec[0])
        _fired_t = float(rec[1])
        _source_jct = int(rec[2]) if len(rec) >= 3 else int(self._wave_origin)
        _algo = str(rec[3]) if len(rec) >= 4 else str(COORDINATION_ALGO)
        self._prearm_stats["success"] += 1
        eta_err_s = float(actual_t) - float(eta_t)
        self._prearm_stats["eta_errors_s"].append(eta_err_s)
        if eta_err_s > 0.0:
            self._prearm_stats["late_success"] += 1
            self._prearm_stats["late_success_delay_s"] += eta_err_s
        # Pair the live queued prediction with this actual arrival for
        # Kalman calibration: qeta_err_s = actual − (queued ETA). Popped so
        # a reused vehicle ID can never match a stale prediction.
        _qeta_extra = {}
        try:
            _qkey = (int(inter_id), int(veh_id))
            _qrec = self._queued_etas.pop(_qkey, None)
            if _qrec is not None:
                _qeta_final = float(_qrec[0])
                _qeta_t = float(_qrec[1])
                _qeta_extra["qeta_final_s"] = _qeta_final
                _qeta_extra["qeta_age_s"] = float(actual_t) - _qeta_t
                _qeta_extra["qeta_err_s"] = \
                    float(actual_t) - (_qeta_t + _qeta_final)
        except Exception:
            _qeta_extra = {}
        _record_wave_event(
            actual_t, self.name, "prearm_success",
            source_jct=_source_jct,
            target_jct=inter_id,
            veh_id=veh_id,
            eta_s=eta_err_s,
            note=("late" if eta_err_s > 0.0 else "on_time_or_early"),
            algo=_algo,
            **_qeta_extra,
        )
        _xy = (_jct_xy_cache or {}).get(inter_id, (0.0, 0.0))
        _mark_detection_point(
            inter_id, veh_id, _xy[0], _xy[1], actual_t,
            f"coord-prearm-success/{COORDINATION_ALGO}",
            {
                "force_write": True,
                "prearm_status": "success",
                "prearm_eta_s": round(max(0.0, float(eta_t) - float(_fired_t)), 1),
                "prearm_eta_abs_s": round(float(eta_t), 1),
                "prearm_fired_t": round(float(_fired_t), 1),
                "prearm_resolved_t": round(float(actual_t), 1),
                "prearm_note": (
                    f"{_algo}:late" if eta_err_s > 0.0 else f"{_algo}:on_time_or_early"
                ),
            },
        )

    # ------------------------------------------------------------------
    def _expire_fired_prearms(self, time: float):
        """Close unresolved fired pre-arms as misses after ETA grace period."""
        grace_s = 30.0
        stale = []
        for key, rec in self._fired_prearms.items():
            eta_t = float(rec[0])
            _fired_t = float(rec[1])
            _source_jct = int(rec[2]) if len(rec) >= 3 else int(self._wave_origin)
            _algo = str(rec[3]) if len(rec) >= 4 else str(COORDINATION_ALGO)
            if time > eta_t + grace_s:
                stale.append((key, eta_t, _source_jct, _algo))
        for key, eta_t, _source_jct, _algo in stale:
            inter_id, veh_id = key
            self._fired_prearms.pop(key, None)
            self._prearm_stats["missed"] = int(self._prearm_stats.get("missed", 0)) + 1
            _record_wave_event(
                time, self.name, "prearm_missed",
                source_jct=_source_jct,
                target_jct=inter_id,
                veh_id=veh_id,
                note="arrival_after_eta_grace",
                algo=_algo,
            )
            _xy = (_jct_xy_cache or {}).get(inter_id, (0.0, 0.0))
            _mark_detection_point(
                inter_id, veh_id, _xy[0], _xy[1], time,
                f"coord-prearm-missed/{COORDINATION_ALGO}",
                {
                    "force_write": True,
                    "prearm_status": "missed",
                    "prearm_eta_abs_s": round(float(eta_t), 1),
                    "prearm_resolved_t": round(float(time), 1),
                    "prearm_note": f"{_algo}:arrival_after_eta_grace",
                },
            )

    # ------------------------------------------------------------------
    def set_corridor_positions(self, pos_map: dict):
        """
        Set corridor positions (metres from first intersection) for each member.
        Called from AAPISimulationReady once junction XY is available.
        pos_map: {inter_id: float}
        """
        self.corridor_pos = dict(pos_map)
        log_to_file(
            f"[CORRIDOR] group={self.name} corridor positions set: "
            + ", ".join(f"{iid}:{pos:.0f}m" for iid, pos in sorted(pos_map.items()))
        )

    def _compute_plan_offsets(self, bus_speed_ms=None):
        """Green-wave OFFSETS (s) for the bus direction: the cumulative bus travel
        time from the first route junction, so the bus/platoon rides progressive
        greens (Eq.~offset in the plan-design MP). offset_j = sum of inter-junction
        travel times up to j at the corridor bus speed. Cached in self._plan_offsets
        {jid: offset_s}. One-directional (the bus band); the reverse band is the
        classic offset tradeoff and is left to the online recourse."""
        _v = float(bus_speed_ms or globals().get('PLAN_BUS_SPEED_MS', 11.0)) or 11.0
        _off = {}
        _cum = 0.0
        _prev = None
        for _iid in (self.route_inter_ids or []):
            _p = self.corridor_pos.get(int(_iid))
            if _p is None:
                _off[int(_iid)] = _cum
                continue
            if _prev is not None:
                _cum += max(0.0, abs(float(_p) - float(_prev))) / max(_v, 1.0)
            _prev = _p
            _off[int(_iid)] = _cum
        self._plan_offsets = _off
        try:
            log_to_file("[PLAN_OFFSET] group=%s green-wave offsets(s): %s"
                        % (self.name, {k: round(v, 1) for k, v in _off.items()}),
                        force=True)
        except Exception:
            pass
        return _off

    # ------------------------------------------------------------------
    def _iter_managed_targets(self, at_inter_id: int, is_northbound: bool,
                              veh_id: int = -1) -> list:
        """
          Return the immediate next managed intersection in corridor route order
          that this bus will actually visit.

        Priority:
          1. Bus's filed PT route (from _pt_line_jct_route via _bus_line_id).
                 Only the next managed junction explicitly in the bus's route is
                 returned — so a bus not stopping at junction X won't trigger a
                 pre-arm there, and long-range predictions are avoided.
          2. Geographic corridor order (_route_index / inter_ids) — fallback
             when the bus's PT route is unknown.
        """
        managed = set(self.inter_ids)

        # ── Attempt PT-route-aware targeting ─────────────────────────────────
        if veh_id > 0:
            line_id = _bus_line_id.get(veh_id, -1)
            if line_id > 0:
                route_jcts = _pt_line_jct_route.get(line_id)  # [jct_id, ...] in route order
                if route_jcts:
                    # Find this junction in the bus's route
                    try:
                        my_route_pos = route_jcts.index(at_inter_id)
                    except ValueError:
                        my_route_pos = -1

                    if my_route_pos >= 0:
                        # Slice ahead (direction already known from route order)
                        ahead = route_jcts[my_route_pos + 1:]
                        targets = [j for j in ahead if j in managed][:1]
                        if LOG_CORRIDOR and targets:
                            log_to_file(
                                f"[PT-ROUTE TARGETS] bus={veh_id} line={line_id} "
                                f"jct={at_inter_id} → {targets} (from PT route)"
                            )
                        return targets
                    # Bus line is known but this junction is not on that route.
                    # Do NOT fall back to geographic targets, otherwise prearms can
                    # jump to unrelated intersections.
                    if LOG_CORRIDOR:
                        log_to_file(
                            f"[PT-ROUTE MISMATCH] bus={veh_id} line={line_id} "
                            f"jct={at_inter_id} not in route — suppress prearm"
                        )
                    return []

        # ── Fallback tier 2: observed-route targeting ─────────────────────────
        # Use the per-bus zone-enter history (_bus_observed_jcts) to determine
        # which corridor junctions this bus has already passed through.
        # If we can confirm which managed junctions are ALREADY BEHIND the bus,
        # we can safely pre-arm the next N in the same direction without risking
        # arming junctions the bus won't visit.
        #
        # Logic:
        #  • Collect all observed junctions for this bus in entry order.
        #  • Find at_inter_id in the observed sequence.
        #  • All junctions after it (in route_inter_ids order that match the
        #    observed direction) are candidate targets, but only the immediate
        #    next managed junction is returned.
        if veh_id > 0:
            observed = _bus_observed_jcts.get(veh_id, [])
            if len(observed) >= 1:
                # Build the corridor-position of each observed junction.
                obs_in_route = [j for j in observed if j in self._route_index]
                if obs_in_route:
                    # Determine direction from the sequence of observed junctions.
                    obs_route_indices = [self._route_index[j] for j in obs_in_route]
                    if len(obs_route_indices) >= 2:
                        # Direction is determined by the trend of route indices.
                        nb_votes = sum(1 for a, b in zip(obs_route_indices, obs_route_indices[1:]) if b > a)
                        sb_votes = len(obs_route_indices) - 1 - nb_votes
                        observed_is_nb = (nb_votes >= sb_votes)
                    else:
                        observed_is_nb = is_northbound  # trust caller when only 1 observed

                    at_route_idx = self._route_index.get(at_inter_id)
                    if at_route_idx is not None:
                        step = 1 if observed_is_nb else -1
                        idx = at_route_idx + step
                        targets = []
                        while 0 <= idx < len(self.route_inter_ids) and len(targets) < 1:
                            iid = self.route_inter_ids[idx]
                            if iid in managed:
                                targets.append(iid)
                            idx += step
                        if targets:
                            if LOG_CORRIDOR:
                                log_to_file(
                                    f"[OBS-ROUTE TARGETS] bus={veh_id} "
                                    f"observed={obs_in_route} dir={'NB' if observed_is_nb else 'SB'} "
                                    f"jct={at_inter_id} → {targets} (from observed route)"
                                )
                            return targets

        # ── Fallback tier 3: geographic corridor order (direction only) ───────
        # Last resort when neither PT route nor observed history is available.
        # Restrict to the IMMEDIATE next junction only to avoid arming junctions
        # the bus won't reach.  Once that junction grants and calls
        # notify_bus_granted, the next pre-arm will be queued with updated info.
        route_idx = self._route_index.get(at_inter_id)
        if route_idx is None:
            try:
                my_idx = self.inter_ids.index(at_inter_id)
            except ValueError:
                return []
            if is_northbound:
                return self.inter_ids[my_idx + 1:my_idx + 2]
            lo = max(0, my_idx - 1)
            return list(reversed(self.inter_ids[lo:my_idx]))

        step = 1 if is_northbound else -1
        idx = route_idx + step
        targets = []
        while 0 <= idx < len(self.route_inter_ids) and len(targets) < 1:
            iid = self.route_inter_ids[idx]
            if iid in managed:
                targets.append(iid)
            idx += step
        return targets

    # ------------------------------------------------------------------
    def _downstream_bus_red_wait(self, node_id: int, ctrl, arr_time: float,
                                 time: float, timeSta: float) -> float:
        """Seconds of red a bus would wait at `node_id` if it arrived at
        `arr_time`, using that controller's live phase schedule.

        Mirrors IntersectionController._reward_estimate_no_action but is
        parameterised by an absolute arrival time instead of bus_eta_s, and
        reads phase config (BusPhase / BusPhaseDuration / phase_list /
        cycle_len_s) from the DOWNSTREAM controller rather than self."""
        try:
            cycle = float(getattr(ctrl, 'cycle_len_s', 135.0) or 135.0)
            # Live bus-green length first: _live_bus_phase_dur is refreshed
            # from ECI on the tick after any plan rewrite (see deferred
            # refresh); BusPhaseDuration is the nominal and goes stale after
            # commits -- the old code coordinated against the pre-commit plan.
            bpd = float(getattr(ctrl, '_live_bus_phase_dur', None)
                        or getattr(ctrl, 'BusPhaseDuration', 20.0) or 20.0)
            # Pushed post-change plan wins over both (downstream direction):
            # same-tick commits are visible without waiting for ECI polling.
            try:
                _pp = (getattr(self, '_plan_push', None) or {}).get(
                    int(getattr(ctrl, 'id', -1)))
                if isinstance(_pp, dict) and float(
                        _pp.get("bus_phase_dur", 0.0)) > 0.0:
                    bpd = float(_pp["bus_phase_dur"])
                    if float(_pp.get("cycle_s", 0.0)) > 0.0:
                        cycle = float(_pp["cycle_s"])
            except Exception:
                pass
            bp = int(getattr(ctrl, 'BusPhase', 2))
            _max_delay = max(cycle - bpd, 0.0)
            cur = int(ECIGetCurrentPhase(node_id))
            dt = max(0.0, float(arr_time) - float(time))
            if cur == bp:
                _ps = float(ECIGetStartingTimePhase(node_id))
                _pd = float(GetPhaseDuration(node_id, cur, timeSta))
                _remain = max(0.0, _pd - (float(time) - _ps))
                if dt <= _remain:
                    return 0.0
                return min(_max_delay, dt - _remain)
            _ps_now = float(ECIGetStartingTimePhase(node_id))
            _elapsed = max(0.0, float(time) - _ps_now)
            _rem_cur = max(0.0, float(GetPhaseDuration(node_id, cur, timeSta)) - _elapsed)
            _time_to_bp = _rem_cur
            phs = list(getattr(ctrl, 'phase_list', None) or [])
            try:
                _ci = phs.index(cur); _bi = phs.index(bp); _n = len(phs)
                _steps = (_bi - _ci) % _n
                for _k in range(1, _steps):
                    _ph = phs[(_ci + _k) % _n]
                    _time_to_bp += float(_dur_or_live(node_id, _ph, timeSta))
            except Exception:
                _time_to_bp = cycle
            if dt <= _time_to_bp + bpd:
                return max(0.0, _time_to_bp - dt)
            return min(_max_delay, max(0.0, _time_to_bp + cycle - dt))
        except Exception:
            return 0.0

    def project_downstream_delay_paxs(self, at_inter_id: int, veh_id: int,
                                      time: float, timeSta: float,
                                      bus_eta_s: float, bus_saved_s: float,
                                      bus_occ: float) -> float:
        """Project the pax·s bus-delay change at the NEXT managed downstream
        junction caused by saving `bus_saved_s` seconds at THIS junction.

        Positive = coordination COST (the saved time shifts the bus into a
        worse red at the downstream junction); negative = coordination BENEFIT
        (the saved time lands the bus into the downstream green). Returns 0.0
        when no corridor / next junction / bus data is available."""
        try:
            if float(bus_saved_s) <= 0.0:
                return 0.0
            trk = self._trackers.get(int(veh_id))
            is_nb = True if trk is None else (float(trk.x[1]) >= 0.0)
            nxt_list = self._iter_managed_targets(int(at_inter_id), is_nb,
                                                  veh_id=int(veh_id))
            if not nxt_list:
                return 0.0
            nxt = int(nxt_list[0])
            down = self._ic_map.get(nxt) or self._ctrl_map.get(nxt)
            if down is None:
                return 0.0
            dnode = int(getattr(down, 'node_id', nxt))
            travel_s = 25.0
            try:
                p_cur = self.corridor_pos.get(int(at_inter_id))
                p_nxt = self.corridor_pos.get(nxt)
                if p_cur is not None and p_nxt is not None:
                    dist = abs(float(p_nxt) - float(p_cur))
                    spd = abs(float(trk.x[1])) if trk is not None else 11.0
                    travel_s = max(5.0, dist / max(spd, 1.0))
            except Exception:
                travel_s = 25.0
            arr_no = float(time) + max(0.0, float(bus_eta_s)) + travel_s
            arr_act = arr_no - max(0.0, float(bus_saved_s))
            w_no = self._downstream_bus_red_wait(dnode, down, arr_no, time, timeSta)
            w_act = self._downstream_bus_red_wait(dnode, down, arr_act, time, timeSta)
            return (float(w_act) - float(w_no)) * max(float(bus_occ or 0.0), 1.0)
        except Exception:
            return 0.0

    def project_chain_delay_paxs(self, at_inter_id: int, veh_id: int,
                                 time: float, timeSta: float,
                                 bus_eta_s: float, bus_saved_s: float,
                                 bus_occ: float, horizon=None,
                                 force_is_nb=None) -> float:
        """Project the pax·s bus-delay change over the bus's REMAINING corridor
        route caused by saving `bus_saved_s` seconds at THIS junction.

        This is the enabling piece of GLOBAL_REWARD aggregation: the sum of
        per-leg (w_act − w_no)×occ over every downstream managed junction in
        the bus's forward slice, with kinematic chaining (each leg's arrival
        includes the previous legs' waits + inter-junction travel, exactly as
        the next-only projector does for its single leg -- the first leg here
        reproduces project_downstream_delay_paxs bit-for-bit).

        Downstream junctions are assumed fixed-time (their own future TSP is
        unknowable at decision time). Sign convention identical to the
        next-only projector: positive = coordination COST, negative = BENEFIT.
        horizon<=0 (or missing route data) degrades to the next-only
        projector; any other missing data returns 0.0. horizon defaults to
        GLOBAL_REWARD_CHAIN_HORIZON (3 downstream junctions)."""
        try:
            if float(bus_saved_s) <= 0.0:
                return 0.0
            _h = (int(horizon) if horizon is not None
                  else int(globals().get('GLOBAL_REWARD_CHAIN_HORIZON', 3) or 0))
            _h = max(0, min(int(_h), 6))
            trk = self._trackers.get(int(veh_id))
            # force_is_nb overrides the tracker-derived heading -- used by the
            # bus-free general-traffic coupling to project the through-platoon in a
            # CHOSEN direction (so the same junction's downstream landing can be
            # scored for BOTH arterial directions, not just the bus's heading).
            if force_is_nb is not None:
                is_nb = bool(force_is_nb)
            else:
                is_nb = True if trk is None else (float(trk.x[1]) >= 0.0)
            _slice = self._nash_forward_slice(int(at_inter_id), int(veh_id),
                                              is_nb, 1 + max(_h, 1))
            if len(_slice) < 2:
                # No route data -- fall back to the next-only projector so a
                # missing route index never silences the downstream term.
                return float(self.project_downstream_delay_paxs(
                    int(at_inter_id), int(veh_id), float(time), float(timeSta),
                    float(bus_eta_s), float(bus_saved_s), float(bus_occ)))
            _occ = max(float(bus_occ or 0.0), 1.0)
            _spd = abs(float(trk.x[1])) if trk is not None else 11.0
            _spd = max(float(_spd), 1.0)
            _arr_no = float(time) + max(0.0, float(bus_eta_s))
            _arr_act = _arr_no - max(0.0, float(bus_saved_s))
            _prev_pos = self.corridor_pos.get(int(at_inter_id))
            _total = 0.0
            _meas_floor = 0.0        # measured-queue downstream re-delay floor
            for _iid in _slice[1:1 + max(_h, 1)]:
                _down = self._ic_map.get(int(_iid)) or self._ctrl_map.get(int(_iid))
                if _down is None:
                    break
                _dnode = int(getattr(_down, 'node_id', int(_iid)))
                _travel = 25.0
                try:
                    _p = self.corridor_pos.get(int(_iid))
                    if _prev_pos is not None and _p is not None:
                        _travel = max(5.0, abs(float(_p) - float(_prev_pos)) / _spd)
                    _prev_pos = _p
                except Exception:
                    pass
                _arr_no += _travel
                _arr_act += _travel
                _w_no = float(self._downstream_bus_red_wait(
                    _dnode, _down, _arr_no, float(time), float(timeSta)))
                _w_act = float(self._downstream_bus_red_wait(
                    _dnode, _down, _arr_act, float(time), float(timeSta)))
                _total += (_w_act - _w_no) * _occ
                _arr_no += _w_no
                _arr_act += _w_act
                # ── MEASURED-QUEUE grounding (2026-09-29) ────────────────────
                # The signal-only wait above returns 0 whenever the bus lands in a
                # downstream GREEN, so on a coordinated corridor it under-reports
                # the re-delay and the local saving looks like it survives (KG:
                # predicted bus saving 27x the realized). But a standing MEASURED
                # main queue at the downstream junction blocks the bus behind it
                # REGARDLESS of signal: arriving `bus_saved_s` earlier into an
                # un-cleared queue costs up to that head-start back. Price the
                # queue-discharge wait (Q / sat_flow) capped by the local saving,
                # take the worst downstream junction, and floor the chain cost by
                # it so a congested corridor cancels the local bus credit.
                try:
                    _qd = _down._measured_main_queue_veh()
                    if _qd is not None and float(_qd) > 0.0:
                        _sf = max(float(getattr(_down, 'SaturationFlow', 1800.0)
                                        or 1800.0) / 3600.0, 0.1)
                        _rd = min(max(0.0, float(bus_saved_s)), float(_qd) / _sf)
                        _meas_floor = max(_meas_floor, _rd * _occ)
                except Exception:
                    pass
            return max(float(_total), float(_meas_floor))
        except Exception:
            return 0.0

    # ------------------------------------------------------------------
    def _nash_forward_slice(self, at_inter_id, veh_id, is_nb, horizon):
        """The managed junctions this bus will traverse, this one first, up to
        `horizon` junctions ahead in the travel direction. Route order preferred;
        empty tail is fine (degrades to a single-junction solve)."""
        slice_ids = [int(at_inter_id)]
        try:
            idx = self._route_index.get(int(at_inter_id))
            if idx is None:
                return slice_ids
            managed = set(self._ic_map.keys()) | set(self._ctrl_map.keys())
            step = 1 if is_nb else -1
            j = idx + step
            while 0 <= j < len(self.route_inter_ids) and len(slice_ids) < horizon:
                iid = int(self.route_inter_ids[j])
                if iid in managed and iid not in slice_ids:
                    slice_ids.append(iid)
                j += step
        except Exception:
            pass
        return slice_ids

    def _nash_junction_frontier(self, inter_id, veh_id, time, timeSta, eta_s,
                                sigma_in, occ):
        """Real (bps, cpc, s) frontier for a managed junction via
        _spm._dctsp_eval_action over its phase-appropriate actions. Returns a
        list of (at, ap, bps, cpc, s_saved) or [] if it can't be evaluated."""
        ctrl = self._ic_map.get(int(inter_id)) or self._ctrl_map.get(int(inter_id))
        if ctrl is None:
            return []
        node_id = int(getattr(ctrl, 'node_id', inter_id))
        try:
            cur = int(ECIGetCurrentPhase(node_id))
        except Exception:
            return []
        bus_phase = int(getattr(ctrl, 'BusPhase', 2))
        wrong_phase = (cur != bus_phase)
        try:
            arr = float(time) + max(0.0, float(eta_s))
            no_act_delay = float(self._downstream_bus_red_wait(
                node_id, ctrl, arr, time, timeSta))
        except Exception:
            no_act_delay = 0.0
        frontier = []
        for (_at, _ap) in _spm.DCTSP_RL_ACTION_SPACE:
            if _at == 'NO_ACTION':
                continue
            if _at == 'GE' and wrong_phase:
                continue
            if _at in ('INS', 'EARLY_RED') and not wrong_phase:
                continue
            try:
                _r, _so, _tp, _bps, _cpc, _nsd, _std = _spm._dctsp_eval_action(
                    ctrl, _at, _ap, float(sigma_in), no_act_delay, float(eta_s),
                    wrong_phase=wrong_phase, remaining_red_s=no_act_delay)
            except Exception:
                continue
            _bps = max(0.0, float(_bps)); _cpc = max(0.0, float(_cpc))
            # Bargaining payoff = FULL bus-phase benefit (bus + mainline through
            # traffic) so the corridor surplus is the TOTAL passenger-delay
            # change. The green-wave hand-off seconds (slot 5) must stay BUS-only
            # -- derive them from the original bus pax, never the phase total.
            _s_bus = _bps / max(occ, 1.0)
            _bps_tot = _spm._nash_phase_total_bps(ctrl, _at, _ap, _bps)
            frontier.append((_at, _ap, _bps_tot, _cpc, _s_bus))
        return frontier

    def nash_corridor_bestresponse(self, ctrl, veh_id, time, timeSta, bus_eta_s,
                                   bus_occ, cand, p_T=1.0, p_C=1.0):
        """Tier 2 -- corridor Nash EQUILIBRIUM selection for one junction.

        `cand` = [(at, ap, bps, cpc), ...] for THIS junction (real, from the
        caller). Returns the index into `cand` of the corridor-equilibrium action
        for this junction, or None if that equilibrium is NO_ACTION.

        Builds the forward slice of managed junctions the bus will traverse and
        solves a Gauss-Seidel best-response game: each junction picks the Nash-
        bargaining action (`_spm._nash_bargain_pick`) whose transit gain is its
        LOCAL benefit minus the downstream landing cost of the seconds it saves
        (`project_downstream_delay_paxs`, weighted by NASH_NEIGHBOR_WEIGHT),
        CREDITED by the downstream junction's own currently-planned saving
        (green-wave hand-off: occ*min(s_self, s_down)). Because each junction's
        coupling depends on its neighbour's saving, the profile is iterated up to
        NASH_MAX_ITER until the savings stabilise (max |Δs| < NASH_CONVERGENCE_TOL).
        Downstream junctions that can't be evaluated are dropped, degrading to a
        shorter slice (a single-junction slice = local bargain plus its own
        downstream coupling)."""
        occ = max(float(bus_occ), 1.0)
        w_nb = float(getattr(_spm, 'NASH_NEIGHBOR_WEIGHT', 0.5))
        max_iter = max(1, int(getattr(_spm, 'NASH_MAX_ITER', 10)))
        tol = float(getattr(_spm, 'NASH_CONVERGENCE_TOL', 0.01))
        at_id = int(getattr(ctrl, 'id', getattr(ctrl, 'node_id', -1)))
        trk = self._trackers.get(int(veh_id))
        is_nb = True if trk is None else (float(trk.x[1]) >= 0.0)

        slice_ids = self._nash_forward_slice(at_id, veh_id, is_nb, horizon=4)

        # per-junction frontier + eta; current junction uses the caller's `cand`
        frontier = {}
        eta = {}
        # slot 3 = FULL bus-phase benefit (bus + mainline through traffic) for the
        # bargaining surplus; slot 5 = green-wave seconds, kept BUS-only (b/occ),
        # since `b` from the caller is bus pax*s. See _spm._nash_phase_total_bps.
        frontier[at_id] = [
            (a, p, _spm._nash_phase_total_bps(ctrl, a, p, float(b)),
             float(c), float(b) / occ)
            for (a, p, b, c) in cand]
        eta[at_id] = float(bus_eta_s)
        for m in slice_ids[1:]:
            _eta_m = None
            try:
                _pos = self.corridor_pos.get(int(m))
                if _pos is not None and trk is not None:
                    _eta_m = float(trk.eta(_pos, time)) - float(time)
            except Exception:
                _eta_m = None
            if _eta_m is None or _eta_m < 0.0:
                continue
            fr = self._nash_junction_frontier(m, veh_id, time, timeSta, _eta_m,
                                              0.0, occ)
            if fr:
                frontier[m] = fr
                eta[m] = _eta_m
        order = [m for m in slice_ids if m in frontier]

        def _project(jid, eta_j, s):
            return self.project_downstream_delay_paxs(
                int(jid), int(veh_id), time, timeSta, float(eta_j), float(s), occ)

        chosen = _spm._nash_corridor_solve(
            order, frontier, eta, _project, occ,
            w_nb=w_nb, max_iter=max_iter, tol=tol, p_T=p_T, p_C=p_C)
        return chosen.get(at_id)

    # ------------------------------------------------------------------
    def _estimate_unmanaged_delay_s(self, inter_id: int) -> float:
        """Estimate expected delay at an unmanaged system junction."""
        cfg = INTERSECTIONS_CONFIG.get(inter_id, {}) or {}
        phase_durs = cfg.get("GreenPhaseDuration") or []
        cycle_s = 0.0
        try:
            cycle_s = sum(float(x) for x in phase_durs if x not in (None, ""))
        except Exception:
            cycle_s = 0.0

        bus_green_s = None
        try:
            bus_green_s = float(cfg.get("BusPhaseDuration"))
        except Exception:
            bus_green_s = None
        if bus_green_s in (None, 0.0) and phase_durs:
            try:
                bus_phase = int(cfg.get("BusPhase", 1) or 1)
                if 1 <= bus_phase <= len(phase_durs):
                    bus_green_s = float(phase_durs[bus_phase - 1])
            except Exception:
                bus_green_s = None

        if cycle_s > 0.0 and bus_green_s is not None:
            red_s = max(cycle_s - max(bus_green_s, 0.0), 0.0)
            return min(
                self.MAX_UNMANAGED_DELAY_S,
                max(self.MIN_UNMANAGED_DELAY_S, 0.35 * red_s),
            )

        return self.MIN_UNMANAGED_DELAY_S

    # ------------------------------------------------------------------
    def _route_gap_delay_s(self, from_inter_id: int, to_inter_id: int) -> float:
        """Return ETA slack for unmanaged intersections between two managed nodes."""
        from_idx = self._route_index.get(from_inter_id)
        to_idx = self._route_index.get(to_inter_id)
        if from_idx is None or to_idx is None or from_idx == to_idx:
            return 0.0

        lo, hi = sorted((from_idx, to_idx))
        managed = set(self.inter_ids)
        gap_delay_s = 0.0
        for iid in self.route_inter_ids[lo + 1:hi]:
            if iid in managed:
                continue
            gap_delay_s += self._estimate_unmanaged_delay_s(iid)
        return gap_delay_s

    # ------------------------------------------------------------------
    def is_wave_banned(self, inter_id: int) -> bool:
        """
        Return True if junction inter_id should block independent bus detections.

        A junction is banned when:
          • A coordination wave is active (COORDINATED_TSP=True)
          • The junction is not yet in _wave_served_ids
            (served = the coordinator has already pre-armed it this wave)

        Once the coordinator pre-arms junction[j] and the pre-request fires,
        junction[j] is added to _wave_served_ids and its ban is lifted so it
        can react normally to the pre-armed request.
        """
        if not COORDINATED_TSP or not self._wave_active:
            return False
        if inter_id in self._wave_uncertain_jcts:
            return False   # sigma too high to pre-arm — let independent detection run
        if inter_id in self._wave_served_ids:
            return False   # already served — ban lifted
        # Only ban the immediately queued next junction.
        # All other corridor junctions run independent TSP detection.
        return inter_id in self._pre_requests

    # ------------------------------------------------------------------
    def notify_timing_changed(self, inter_id: int, action: str,
                              magnitude_s: float, time: float, why: str = "",
                              plan: dict = None):
        """A junction rewrote its own plan (commit / restore / recovery).

        Stores the published post-change plan (bus green length, cycle) so
        BOTH directions -- downstream delay projections and upstream
        green-window checks -- read the new values same-tick instead of
        polling ECI or running on pre-commit snapshots. Drops pre-arms
        targeting the junction (their windows were computed against the old
        plan). Commits are rare, restores at most once per cycle: no flood.
        """
        try:
            _vers = getattr(self, '_plan_version', None)
            if not isinstance(_vers, dict):
                _vers = {}
                self._plan_version = _vers
            _vers[int(inter_id)] = int(_vers.get(int(inter_id), 0)) + 1
        except Exception:
            pass
        try:
            if isinstance(plan, dict) and plan.get("bus_phase_dur"):
                _store = getattr(self, '_plan_push', None)
                if not isinstance(_store, dict):
                    _store = {}
                    self._plan_push = _store
                _store[int(inter_id)] = {
                    "version": int(getattr(self, '_plan_version', {}).get(
                        int(inter_id), 0)),
                    "bus_phase_dur": float(plan.get("bus_phase_dur")),
                    "cycle_s": float(plan.get("cycle_s", 0.0) or 0.0),
                    "phase": int(plan.get("phase", -1)),
                    "t": float(time),
                    "action": str(action),
                }
        except Exception:
            pass
        try:
            if int(inter_id) in getattr(self, '_pre_requests', {}):
                self._pre_requests.pop(int(inter_id), None)
                log_to_file(
                    f"[COORD_TIMING] jct={inter_id} {action} "
                    f"{float(magnitude_s):.1f}s ({why}) t={float(time):.0f} "
                    f"-> pre-arm dropped (stale green window)")
        except Exception:
            pass

    def get_pushed_plan(self, inter_id: int):
        """Latest published post-change plan for a junction (or None)."""
        try:
            _store = getattr(self, '_plan_push', None) or {}
            _p = _store.get(int(inter_id))
            if isinstance(_p, dict) and float(_p.get("bus_phase_dur", 0.0)) > 0.0:
                return _p
        except Exception:
            pass
        return None

    def notify_bus_granted(self, veh_id: int, at_inter_id: int,
                           time: float, bus_sg=None):
        """
        Called by GroupBasedController._activate_for_bus when bus priority
        is activated at at_inter_id.  Updates the Kalman tracker and
        schedules pre-green requests at downstream intersections.
        Only active when COORDINATED_TSP=True and corridor positions are set.
        """
        if not COORDINATED_TSP or not self.corridor_pos:
            return

        at_pos = self.corridor_pos.get(at_inter_id)
        if at_pos is None:
            return

        # If this junction had an active pre-arm record for this bus, mark outcome.
        self._record_prearm_success(at_inter_id, veh_id, time)

        # Debounce grant spam from repeated natural-green checks at the same
        # junction. Without this, the same bus can retrigger notify_bus_granted()
        # every step and create contradictory direction flips + out-of-order
        # downstream pre-arms in the dashboard.
        _notify_key = (int(veh_id), int(at_inter_id))
        _last_notify_t = self._last_grant_notify_t.get(_notify_key, -9999.0)
        if (time - _last_notify_t) < 8.0:
            if LOG_CORRIDOR:
                log_to_file(
                    f"[CORRIDOR DEDUP] suppress notify bus={veh_id} jct={at_inter_id} "
                    f"dt={time - _last_notify_t:.1f}s"
                )
            return
        self._last_grant_notify_t[_notify_key] = float(time)

        # ── Compute and log green-wave offset from previous junction ────────────────
        _bus_grants = self._grant_times.setdefault(veh_id, {})
        _at_idx = self._route_index.get(at_inter_id, -1)
        _prev_candidates = [
            (self._route_index.get(j, -1), j, t)
            for j, t in _bus_grants.items()
            if self._route_index.get(j, -1) >= 0 and self._route_index.get(j, -1) < _at_idx
        ]
        if _prev_candidates:
            _, _prev_jct, _prev_t = max(_prev_candidates, key=lambda x: x[0])
            _offset_s  = time - _prev_t
            # Fix: corridor_pos for the first junction is 0.0 (falsy), so use
            # an explicit None-check instead of `or at_pos`.
            _prev_pos = self.corridor_pos.get(_prev_jct)
            _dist_m   = abs(at_pos - (_prev_pos if _prev_pos is not None else at_pos))
            # Speed sanity: if implied speed >25 m/s (90 km/h) or offset <5 s,
            # this is almost certainly a wave/pre-arm grant, not an actual traversal.
            # offset<1s means the two junctions were granted essentially
            # SIMULTANEOUSLY (a pre-arm burst, not a real traversal) -- dividing by
            # it produced absurd "speeds" (up to 15000 m/s) that polluted the log
            # and the offset CSV. Report the implied speed as 0 (undefined) rather
            # than a division artifact; the 'wave/pre-arm' quality tag already
            # flags it.  NOTE: 503/1516 offsets were <1s here -- the pre-arm is
            # firing consecutive-junction grants in bursts instead of timing each
            # to the bus arrival (see the far-ETA GE issue).
            _speed_est = (_dist_m / _offset_s) if _offset_s >= 1.0 else 0.0
            _quality   = ("wave/pre-arm" if (_offset_s < 5.0 or _speed_est > 25.0)
                          else "observed")
            # Suppress duplicate log rows: only log if grant time changed since last log.
            _log_key = (veh_id, at_inter_id)
            _last_logged_t = self._last_offset_logged.get(_log_key, -999.0)
            _should_log = (abs(time - _last_logged_t) > 1.0)
            if _should_log:
                self._last_offset_logged[_log_key] = time
                log_to_file(
                    f"[GREEN_OFFSET] bus={veh_id} "
                    f"jct{_prev_jct}->{at_inter_id} "
                    f"offset={_offset_s:.1f}s dist={_dist_m:.0f}m "
                    f"speed={_speed_est:.1f}m/s [{_quality}] "
                    f"(grant_prev={_prev_t:.1f}s grant_now={time:.1f}s)",
                    )
                # Append to offset CSV
                try:
                    global _offset_header_written
                    import csv as _csv_mod
                    _row_off = {
                        'sim_time_s': round(time, 1),
                        'experiment': _CURRENT_EXPERIMENT,
                        'group':      self.name,
                        'veh_id':     veh_id,
                        'from_jct':   _prev_jct,
                        'to_jct':     at_inter_id,
                        'offset_s':   round(_offset_s, 2),
                        'dist_m':     round(_dist_m, 1),
                        'speed_est_ms': round(_speed_est, 2),
                        'quality':    _quality,
                        'grant_from_t': round(_prev_t, 1),
                        'grant_to_t':   round(time, 1),
                    }
                    _write_hdr = not _offset_header_written
                    with open(_OFFSET_CSV, 'a', newline='') as _f_off:
                        _w = _csv_mod.DictWriter(_f_off, fieldnames=list(_row_off.keys()))
                        if _write_hdr:
                            _w.writeheader()
                            _offset_header_written = True
                        _w.writerow(_row_off)
                except Exception as _oe:
                    log_to_file(f"[OFFSET CSV] write failed: {_oe}")
        _bus_grants[at_inter_id] = time

        # ── Physical-bus discontinuity check (veh_id reuse) ──────────────────
        # Aimsun recycles vehicle ids: a grant can arrive for a DIFFERENT
        # physical bus that happens to reuse the same id.  Detect it from the
        # implied speed between consecutive grants of this id: if the bus
        # "jumped" from the previous grant junction to this one at a speed no
        # real bus can sustain, it is a different vehicle.  Reset the tracker
        # and start a fresh wave so the two buses never merge into one
        # bouncing green wave.
        _phys_discontinuity = False
        if (COORDINATED_TSP and self._wave_active
                and int(veh_id) == int(self._wave_veh_id)):
            _prev_g_jct, _prev_g_t = -1, -1.0
            for _gj, _gt in _bus_grants.items():
                if _gj == at_inter_id:
                    continue
                if _gt > _prev_g_t:
                    _prev_g_t, _prev_g_jct = float(_gt), _gj
            if _prev_g_jct > 0 and _prev_g_t > 0.0 and _prev_g_t < time:
                _prev_g_pos = self.corridor_pos.get(_prev_g_jct)
                if _prev_g_pos is not None:
                    _dt_g = max(time - _prev_g_t, 0.1)
                    _impl_speed = abs(at_pos - float(_prev_g_pos)) / _dt_g
                    _reuse_speed_thr = float(globals().get('ID_REUSE_SPEED_MS', 30.0) or 30.0)
                    if _impl_speed > _reuse_speed_thr:
                        _phys_discontinuity = True
                        if LOG_CORRIDOR:
                            log_to_file(
                                f"[ID-REUSE DETECTED] bus={veh_id} t={time:.1f} "
                                f"jct{_prev_g_jct}({_prev_g_pos:.0f}m)@{_prev_g_t:.0f}s "
                                f"-> jct{at_inter_id}({at_pos:.0f}m)@{time:.0f}s "
                                f"implied_speed={_impl_speed:.0f}m/s>{_reuse_speed_thr:.0f} "
                                f"— different physical bus, resetting wave",
                                force=True
                            )
                        _record_wave_event(
                            time, self.name, "id_reuse_reset",
                            source_jct=at_inter_id,
                            target_jct=at_inter_id,
                            veh_id=veh_id,
                            note=f"implied_speed={_impl_speed:.0f}m/s",
                        )
                        # Wipe grant history so the new physical bus starts fresh
                        _bus_grants.clear()
                        _bus_grants[at_inter_id] = float(time)

        # Update (or create) Kalman tracker for this vehicle
        tracker = self._trackers.get(veh_id)
        _tracker_is_new = (tracker is None)
        if _phys_discontinuity:
            # Different physical bus reusing this id — drop the old bus's state
            # and start a fresh tracker at the current position so downstream
            # ETAs come from the correct vehicle.
            tracker = BusKalmanTracker(initial_pos_m=at_pos)
            self._trackers[veh_id] = tracker
            _tracker_is_new = True
        elif tracker is None:
            tracker = BusKalmanTracker(initial_pos_m=at_pos)
            self._trackers[veh_id] = tracker
        else:
            prev_pos = tracker.x[0]
            prev_t   = tracker.last_t
            if prev_t is not None:
                tracker.predict(max(time - prev_t, 0.0))
            tracker.update(at_pos)
            # Fuse direct speed measurement from inter-junction travel time
            if prev_t is not None and prev_t < time:
                tracker.update_speed_from_travel(prev_pos, at_pos, time - prev_t)
        tracker.last_t = time

        # ── Determine travel direction from junction-sequence history ──────────
        my_idx = self._route_index.get(at_inter_id, -1)
        if my_idx < 0:
            return

        prev_idx = tracker._prev_inter_idx
        if _phys_discontinuity:
            # Reused veh_id: this is a DIFFERENT physical bus, so its junction
            # history is not ours.  Derive direction from the bus's filed PT
            # route (which junction follows at_inter_id) instead of assuming NB.
            is_northbound = (tracker.x[1] >= 0)
            _line_id_rd = _bus_line_id.get(int(veh_id), -1)
            _route_rd = _pt_line_jct_route.get(_line_id_rd) if _line_id_rd > 0 else None
            if _route_rd and at_inter_id in _route_rd:
                _pos_rd = _route_rd.index(at_inter_id)
                if _pos_rd + 1 < len(_route_rd):
                    _nxt_rd = _route_rd[_pos_rd + 1]
                    _nxt_pos_rd = self.corridor_pos.get(_nxt_rd)
                    if _nxt_pos_rd is not None:
                        is_northbound = float(_nxt_pos_rd) > float(at_pos)
                        spd = abs(tracker.x[1])
                        tracker.x[1] = spd if is_northbound else -spd
        elif prev_idx >= 0 and prev_idx != my_idx:
            # We know which junction the bus came from → reliable direction
            is_northbound = (my_idx > prev_idx)
            # Align Kalman velocity sign with observed direction
            spd = abs(tracker.x[1])
            tracker.x[1] = spd if is_northbound else -spd
        else:
            # First detection in this corridor — assume northbound (positive velocity)
            is_northbound = (tracker.x[1] >= 0)
        tracker._prev_inter_idx = my_idx

        # ── Prearm pass-gate: only queue downstream prearms if bus speed is healthy ──────────
        # When notify_bus_granted() is called, the bus has just ARRIVED at at_inter_id
        # (it won the green wave, received TSP, or got natural green). At this moment,
        # the bus might still be accelerating from the stop line.  If we immediately
        # queue prearms for junction[next] based on kinematic ETA, the prearm fires
        # before the bus has left junction[at_inter_id], creating a "too early" prearm.
        #
        # Gate: Only queue prearms if:
        #   1. This is NOT the first time we see this bus (tracker existed before), OR
        #   2. The tracker's speed estimate is > 4 m/s (bus actively traveling, not stopped)
        #
        # This ensures prearms queue only after the bus has demonstrated movement.
        _bus_speed_ms = abs(tracker.x[1])
        _should_queue_prearms = (not _tracker_is_new) or (_bus_speed_ms > 4.0)
        if not _should_queue_prearms and LOG_CORRIDOR:
            log_to_file(
                f"[PREARM GATE] bus={veh_id} jct={at_inter_id} speed={_bus_speed_ms:.1f}m/s — "
                f"skip queuing prearms (bus still accelerating at stop line)"
            )

        if LOG_CORRIDOR:
            _dir_tag = "NB" if is_northbound else "SB"
            _vprint(
                f"[CORRIDOR KF] t={time:.1f} bus={veh_id} granted "
                f"jct={at_inter_id} pos={at_pos:.0f}m "
                f"spd={tracker.x[1]:.1f}m/s ({tracker.x[1]*3.6:.0f}km/h) dir={_dir_tag}"
            )
        _record_wave_event(
            time, self.name, "grant",
            source_jct=at_inter_id,
            target_jct=at_inter_id,
            veh_id=veh_id,
            note=("northbound" if is_northbound else "southbound"),
        )

        # Start (or refresh) a coordination wave.
        # All other junctions get a ban on independent bus detection until
        # each of them is individually pre-armed and served.
        if COORDINATED_TSP:
            _wave_is_new = (veh_id != self._wave_veh_id) or _phys_discontinuity
            if _wave_is_new:
                # R10 opposing-direction arbitration (2026-09-28): a junction
                # serves one bus-phase window per cycle. If a different bus
                # already owns an active wave, the MORE-LATE bus wins; the
                # loser defers its corridor pre-arms to the next window (its
                # local detection still works -- only corridor coordination
                # is deferred, and R11's convoy coupling still covers a
                # following bus within headway).
                if (self._wave_active and self._wave_veh_id > 0
                        and self._wave_veh_id != veh_id):
                    try:
                        _old_late = float(_bus_lateness.get(
                            int(self._wave_veh_id), 0.0) or 0.0)
                    except Exception:
                        _old_late = 0.0
                    try:
                        _new_late = float(_bus_lateness.get(
                            int(veh_id), 0.0) or 0.0)
                    except Exception:
                        _new_late = 0.0
                    if _new_late < _old_late:
                        if LOG_CORRIDOR:
                            log_to_file(
                                f"[ARBITRATE] jct={at_inter_id} t={time:.1f} "
                                f"bus={veh_id} late={_new_late:.0f}s < "
                                f"incumbent bus={self._wave_veh_id} "
                                f"late={_old_late:.0f}s -- incumbent keeps "
                                f"the wave (loser defers corridor pre-arm)")
                        return
                # New bus wins the wave -- fully reset wave state so served-set
                # doesn't carry over
                self._wave_served_ids     = {at_inter_id}
                self._wave_uncertain_jcts = set()
            else:
                # Same bus continuing down corridor — accumulate served junctions
                # (resetting here was the root cause of repeated pre-arm spam:
                # each downstream grant cleared upstream junctions from served_ids,
                # making them eligible for another pre-arm on the next eval step)
                self._wave_served_ids.add(at_inter_id)
            self._wave_active  = True
            self._wave_veh_id  = veh_id
            self._wave_origin  = at_inter_id
            if LOG_CORRIDOR:
                _vprint(
                    f"[CORRIDOR WAVE] t={time:.1f} WAVE {'START' if _wave_is_new else 'CONTINUE'} bus={veh_id} "
                    f"origin=jct{at_inter_id} dir={'NB' if is_northbound else 'SB'} — "
                    f"served={self._wave_served_ids}"
                )

        _allowed_targets = set(self._iter_managed_targets(at_inter_id, is_northbound, veh_id=veh_id)[:1])

        # ── COORD_PREARM_ENABLED gate (2026-10-01) ─────────────────────────────
        # Coordinate WITHOUT pushing downstream pre-greens. When a run sets
        # COORD_PREARM_ENABLED=False the coordinator stays fully alive (corridor
        # positions, neighbour reward coupling, Nash Tier-2 best-response, POG /
        # progression awareness all still feed each junction's DECISION) but it
        # never queues a downstream pre-arm request. This isolates whether the
        # corridor coupling helps on its own, with the pre-arm push -- the part
        # the attribution blamed for the -26.9% gridlock -- removed. Clearing the
        # allowed set here means the cleanup loop below also drops any stale
        # pre-arm already queued for this bus, so nothing fires in _process_pre_requests.
        if not bool(globals().get('COORD_PREARM_ENABLED', True)):
            _allowed_targets = set()

        # ── Strict guard: ensure only the immediate next junction gets prearms ──
        # CRITICAL: Prearms should ONLY be queued for the immediate next managed junction.
        # If somehow more than one target is selected, this is a bug and must be logged.
        if len(_allowed_targets) > 1:
            log_to_file(
                f"[PREARM GUARD ERROR] bus={veh_id} from_jct={at_inter_id} "
                f"_allowed_targets has {len(_allowed_targets)} targets: {_allowed_targets} "
                f"— should be exactly 1 or 0. Limiting to first target only.",
                force=True
            )
            _allowed_targets = set(list(_allowed_targets)[:1])
        
        if self._pre_requests:
            _removed_targets = []
            for _tid, _req in list(self._pre_requests.items()):
                try:
                    _r_veh = int(_req[0])
                except Exception:
                    _r_veh = -1
                if _r_veh != int(veh_id):
                    continue
                if _tid in _allowed_targets:
                    continue
                self._pre_requests.pop(_tid, None)
                _removed_targets.append(int(_tid))

            for _old_tid in _removed_targets:
                _record_wave_event(
                    time, self.name, "prearm_superseded",
                    source_jct=at_inter_id,
                    target_jct=_old_tid,
                    veh_id=veh_id,
                    note="grant advanced to immediate next target",
                )

        for next_id in _allowed_targets:
            next_pos = self.corridor_pos.get(next_id)
            # Sanity check: target must be in direction of travel
            if next_pos is None:
                continue
            if is_northbound and next_pos <= at_pos:
                continue   # next junction must be north (larger pos)
            if not is_northbound and next_pos >= at_pos:
                continue   # next junction must be south (smaller pos)
            
            # ── Apply prearm pass-gate ───────────────────────────────────
            # Skip queuing prearms if bus speed indicates it hasn't cleared the stop line.
            # This prevents prearms from firing before the bus has actually entered the corridor.
            if not _should_queue_prearms:
                if LOG_CORRIDOR:
                    log_to_file(
                        f"[PREARM GATE SKIP] bus={veh_id} from={at_inter_id} to={next_id} "
                        f"speed={_bus_speed_ms:.1f}m/s ≤ 4.0 threshold"
                    )
                continue
            
            # Signal-aware ETA: chains through intermediate junctions, adding
            # kinematic travel + expected red-wait at each signal encountered
            # before the target.  Falls back to pure kinematic when position data
            # is unavailable for intermediates.
            _eta_kinematic  = tracker.eta(next_pos, time)
            eta             = self._signal_aware_eta(at_inter_id, next_id, tracker, time)
            # Bail if ETA is unreachable (bus heading wrong way — shouldn't happen)
            if eta > time + 99000:
                continue
            _signal_delay_contrib = max(0.0, eta - _eta_kinematic)
            gap_delay_s = 0.0   # now folded into signal_aware_eta
            sigma = tracker.uncertainty_s(next_pos)
            next_gb  = self._ctrl_map.get(next_id)
            next_ic  = self._ic_map.get(next_id)
            next_bus_sg = next_gb.bus_sg if next_gb else None

            # ── Prearm quality gate ───────────────────────────────────────
            # Skip queuing if the ETA prediction is too uncertain (sigma above threshold)
            # or the remaining travel time is so long that GE would exceed the
            # hard cap. This prevents wasted prearms that are likely to miss.
            _eta_from_now = eta - time
            # Proportional sigma gate: the arrival-time uncertainty (sigma) naturally
            # scales with inter-junction distance.  A fixed 35 s threshold blocks ALL
            # pre-arms beyond ~900 m.  Allow sigma up to 50 % of ETA (capped at 60 s
            # floor) so that uncertainty is judged relative to the prediction horizon.
            _PREARM_SIGMA_FLOOR = float(globals().get('PREARM_MAX_SIGMA_S', 120.0) or 120.0)
            _PREARM_MAX_SIGMA = max(_PREARM_SIGMA_FLOOR, 0.80 * max(_eta_from_now, 0.0))
            if sigma > _PREARM_MAX_SIGMA:
                # Lift the wave ban for this junction so it can run its own
                # independent detection rather than wait for a stale prearm.
                self._wave_uncertain_jcts.add(next_id)
                _skip_key_sigma = (at_inter_id, next_id, "sigma")
                if _skip_key_sigma not in self._prearm_skip_logged_jcts:
                    self._prearm_skip_logged_jcts.add(_skip_key_sigma)
                    log_to_file(
                        f"[PREARM SKIP SIGMA] group={self.name} "
                        f"from=jct{at_inter_id} to=jct{next_id} "
                        f"sigma={sigma:.1f}s > {_PREARM_MAX_SIGMA:.0f}s — "
                        f"prediction too uncertain (dist={(abs(next_pos - at_pos)):.0f}m) "
                        f"→ jct{next_id} added to _wave_uncertain_jcts"
                    )
                elif LOG_CORRIDOR:
                    log_to_file(
                        f"[CORRIDOR SKIP QUEUE] jct={next_id} bus={veh_id} "
                        f"sigma={sigma:.1f}s > {_PREARM_MAX_SIGMA:.0f}s — prediction too uncertain"
                    )
                continue
            # Don't queue prearms where the bus is more than ~90 s away —
            # beyond that the ETA is too stale and produces prearms that fire
            # at junctions the bus won't reach for 6+ minutes.
            # Use MAX_PREARM_HORIZON_S global if set, otherwise default to 90 s
            # (same cap used in _process_pre_requests).
            _max_prearm_horizon_s = float(
                getattr(self, '_max_prearm_horizon_s', float(globals().get('MAX_PREARM_HORIZON_S', 135.0) or 135.0))
            )
            # Route-order guard: refuse to prearm a junction that the bus has
            # already passed.  Compare the target's route-index against the
            # highest route-index seen in the bus's observed-junction history.
            # If next_id's index ≤ last observed index the bus is heading away
            # from it (or already served it) — skip.
            _next_route_idx = self._route_index.get(next_id, -1)
            if _next_route_idx >= 0:
                _obs_jcts = _bus_observed_jcts.get(veh_id, [])
                if _obs_jcts:
                    _obs_indices = [self._route_index[j] for j in _obs_jcts if j in self._route_index]
                    if _obs_indices:
                        _max_obs_idx = max(_obs_indices)
                        _min_obs_idx = min(_obs_indices)
                        # Determine direction from observed history
                        if is_northbound and _next_route_idx <= _max_obs_idx:
                            if LOG_CORRIDOR:
                                log_to_file(
                                    f"[PREARM SKIP OBS] bus={veh_id} next_id={next_id} "
                                    f"route_idx={_next_route_idx} <= max_observed={_max_obs_idx} "
                                    "— bus has already passed this junction, skipping prearm"
                                )
                            continue
                        if not is_northbound and _next_route_idx >= _min_obs_idx:
                            if LOG_CORRIDOR:
                                log_to_file(
                                    f"[PREARM SKIP OBS] bus={veh_id} next_id={next_id} "
                                    f"route_idx={_next_route_idx} >= min_observed={_min_obs_idx} "
                                    "— bus has already passed this junction (SB), skipping prearm"
                                )
                            continue
            if _eta_from_now > _max_prearm_horizon_s:
                _skip_key_horizon = (at_inter_id, next_id, "horizon")
                if _skip_key_horizon not in self._prearm_skip_logged_jcts:
                    self._prearm_skip_logged_jcts.add(_skip_key_horizon)
                    log_to_file(
                        f"[PREARM SKIP HORIZON] group={self.name} "
                        f"from=jct{at_inter_id} to=jct{next_id} "
                        f"eta_in={_eta_from_now:.0f}s > horizon={_max_prearm_horizon_s:.0f}s — "
                        f"junction too far ahead (dist={(abs(next_pos - at_pos)):.0f}m)"
                    )
                elif LOG_CORRIDOR:
                    log_to_file(
                        f"[CORRIDOR SKIP QUEUE] jct={next_id} bus={veh_id} "
                        f"eta_in={_eta_from_now:.0f}s > horizon={_max_prearm_horizon_s:.0f}s"
                    )
                continue

            eta_base = eta
            queue_len = 0
            eta_delta = 0.0
            eta_adj = eta
            sw_diag = {}

            # Queue-aware ETA correction in SHOCKWAVE and ADAPTIVE modes.
            if COORDINATION_ALGO in ("SHOCKWAVE", "ADAPTIVE"):
                eta_adj, queue_len, eta_delta, sw_diag = self._shockwave_eta_adjust(
                    next_gb, next_bus_sg, eta, next_ic=next_ic)
                if LOG_CORRIDOR and eta_delta > 0.0:
                    log_to_file(
                        f"[CORRIDOR SW] jct={next_id} queue={queue_len}veh "
                        f"ETA_base={eta:.1f}s wave_adj=+{eta_delta:.1f}s ETA_adj={eta_adj:.1f}s"
                    )
                eta = eta_adj

            if LOG_CORRIDOR and _signal_delay_contrib > 0.5:
                _vprint(
                    f"[CORRIDOR SIG] from=jct{at_inter_id} to=jct{next_id} "
                    f"signal_delay=+{_signal_delay_contrib:.1f}s "
                    f"(kinematic={_eta_kinematic - time:.0f}s + sig={_signal_delay_contrib:.0f}s)"
                )

            # ── Deduplication: skip re-queuing if this (junction, bus) was already
            # fired recently.  Without this, every upstream grant re-queues the
            # same downstream junctions causing prearm spam in the wave events CSV.
            _prev_fire = self._fired_prearms.get((next_id, veh_id))
            if _prev_fire is not None:
                _prev_fire_t = float(_prev_fire[1])
                if time - _prev_fire_t < 150.0:  # 150 s cooldown per (junction, bus)
                    if LOG_CORRIDOR:
                        log_to_file(
                            f"[CORRIDOR DEDUP] skipping re-queue jct={next_id} "
                            f"bus={veh_id} — already fired {time - _prev_fire_t:.0f}s ago"
                        )
                    continue

            self._pre_requests[next_id] = (veh_id, eta, next_bus_sg, time, at_inter_id)
            self._pre_arm_count += 1
            self._algo_diag["queued"] = int(self._algo_diag.get("queued", 0) or 0) + 1
            if COORDINATION_ALGO in ("SHOCKWAVE", "ADAPTIVE") and eta_delta > 0.0:
                self._algo_diag["sw_adj_count"] = int(self._algo_diag.get("sw_adj_count", 0) or 0) + 1
                self._algo_diag["sw_adj_total_s"] = float(self._algo_diag.get("sw_adj_total_s", 0.0) or 0.0) + float(eta_delta)
                self._algo_diag["sw_adj_max_s"] = max(
                    float(self._algo_diag.get("sw_adj_max_s", 0.0) or 0.0),
                    float(eta_delta),
                )
            if LOG_CORRIDOR:
                _algo_tag = f"[{COORDINATION_ALGO}]"
                log_to_file(
                    f"[CORRIDOR {_algo_tag}] Pre-arm jct={next_id} bus={veh_id} "
                    f"SG={next_bus_sg} ETA={eta:.1f}s "
                    f"(+{eta - time:.0f}s ±{sigma:.0f}s) dist={next_pos - at_pos:.0f}m"
                )
                log_to_file(
                    f"[CORRIDOR DECISION] algo={COORDINATION_ALGO} stage=queue "
                    f"from={at_inter_id} to={next_id} bus={veh_id} "
                    f"eta_base={eta_base:.1f} eta_final={eta:.1f} eta_delta={eta_delta:.1f} "
                    f"sig_delay={_signal_delay_contrib:.1f} queue={queue_len} sigma={sigma:.1f}"
                )
            _record_wave_event(
                time, self.name, "prearm_queued",
                source_jct=at_inter_id,
                target_jct=next_id,
                veh_id=veh_id,
                eta_s=max(0.0, eta - time),
                note=COORDINATION_ALGO,
                algo=COORDINATION_ALGO,
                sigma_s=sigma,
                signal_delay_s=_signal_delay_contrib,
                eta_base_s=max(0.0, eta_base - time),
                eta_final_s=max(0.0, eta - time),
                eta_delta_s=eta_delta,
                **sw_diag,
            )
            # Remember the live prediction for calibration at success time.
            # Latest revision wins (closest to arrival); fail-open.
            try:
                self._queued_etas[(int(next_id), int(veh_id))] = [
                    max(0.0, float(eta) - float(time)), float(time)]
            except Exception:
                pass

    # ------------------------------------------------------------------
    def _signal_delay_at_s(self, inter_id: int, arrive_t: float, time: float) -> float:
        """
        Estimate how long (seconds) a bus will wait at junction inter_id
        if it arrives at absolute simulation time arrive_t.

        Queries the live Aimsun phase state at the current sim-time and
        projects the phase sequence forward to arrive_t, returning the
        gap between arrive_t and the start of the next green window for
        the bus direction.

        Falls back to _estimate_unmanaged_delay_s when phase data is
        unavailable (e.g., junctions not under Aimsun external control).
        """
        gb = self._ctrl_map.get(inter_id)
        cfg = INTERSECTIONS_CONFIG.get(inter_id, {}) or {}

        # Which Aimsun phase carries the bus at this junction?
        bus_phase_num: int = 1
        if gb is not None:
            bp = getattr(gb, '_bus_aimsun_phase', None)
            if bp is not None:
                bus_phase_num = int(bp)
            jct_id = gb.junction_id
        else:
            try:
                bus_phase_num = int(cfg.get("BusPhase", 1) or 1)
            except Exception:
                bus_phase_num = 1
            jct_id = inter_id

        try:
            n_phases = int(ECIGetNumberPhases(jct_id))
            if n_phases <= 0:
                return self._estimate_unmanaged_delay_s(inter_id)

            current_phase = int(ECIGetCurrentPhase(jct_id))
            phase_start_t = float(ECIGetStartingTimePhase(jct_id))
            phase_elapsed = max(0.0, time - phase_start_t)

            # Walk one full cycle from the current position, building the
            # absolute timeline for each phase.
            # cycle_timeline: [(phase_num, abs_start, abs_end), ...]
            cycle_timeline = []
            t_cursor = time
            for step in range(n_phases):
                ph = ((current_phase - 1 + step) % n_phases) + 1
                # Subsequent phases read the GLOBAL plan-state tracker first
                # (committed plan, push-aware) and fall back to live ECI --
                # so a just-taken action at this junction is priced into the
                # forward delay projection immediately, not after ECI settles.
                _tdur = _global_plan_dur(jct_id, ph)
                raw_dur = float(_tdur) if _tdur is not None else float(
                    GetPhaseDuration(jct_id, ph, 0.0))
                dur = max(raw_dur, 1.0)   # guard against zero-duration phases
                if step == 0:
                    # Current phase: already partially elapsed
                    remaining = max(0.0, dur - phase_elapsed)
                    t_start = phase_start_t
                    t_end   = time + remaining
                else:
                    t_start = t_cursor
                    t_end   = t_cursor + dur
                cycle_timeline.append((ph, t_start, t_end))
                t_cursor = t_end

            cycle_len = t_cursor - time   # total remaining cycle duration

            # First occurrence of the bus phase in this cycle
            green_start = None
            green_end   = None
            for ph, t_s, t_e in cycle_timeline:
                if ph == bus_phase_num:
                    green_start = t_s
                    green_end   = t_e
                    break

            if green_start is None or cycle_len <= 0:
                return self._estimate_unmanaged_delay_s(inter_id)

            if arrive_t >= green_start and arrive_t < green_end:
                return 0.0    # arrives during green — no wait

            if arrive_t < green_start:
                return green_start - arrive_t   # wait until green opens

            # Bus arrives after this cycle's green — project forward by full cycles
            cycles_ahead = math.ceil((arrive_t - green_end) / cycle_len)
            next_green_start = green_start + cycles_ahead * cycle_len
            return max(0.0, next_green_start - arrive_t)

        except Exception:
            return self._estimate_unmanaged_delay_s(inter_id)

    # ------------------------------------------------------------------
    def _bus_lateness_for(self, veh_id):
        """Schedule-lateness-adjusted urgency for a bus (0 = on time)."""
        try:
            _l = float(_bus_lateness.get(int(veh_id), 0.0) or 0.0)
        except Exception:
            _l = 0.0
        try:
            _tr = _ETA_TRACK.get(int(veh_id)) or {}
            _m = float(_tr.get("mult", 1.0) or 1.0)
        except Exception:
            _m = 1.0
        return max(float(_l), (_m - 1.0) * 60.0)

    def _bus_dir(self, veh_id):
        """+1 northbound / -1 southbound from the Kalman tracker velocity sign."""
        try:
            _tr = self._trackers.get(int(veh_id))
            if _tr is not None:
                return 1 if float(_tr.x[1]) >= 0.0 else -1
        except Exception:
            pass
        return 0

    def _eta_at_j(self, veh_id, jct_id, time):
        """Seconds from now for a bus to reach jct_id (tracker eta, capped)."""
        try:
            _p = self.corridor_pos.get(jct_id)
            _tr = self._trackers.get(int(veh_id))
            if _p is not None and _tr is not None:
                return max(0.0, float(_tr.eta(float(_p), float(time))) - float(time))
        except Exception:
            pass
        return None

    def _runner_up(self, jct_id, time, exclude):
        """Second-best oncoming bus at jct_id after `exclude` (or None)."""
        try:
            _cs = self.oncoming_buses(jct_id, time, max_eta_s=180.0)
        except Exception:
            _cs = []
        _best = None
        for (_v, _e, _o) in _cs:
            if int(_v) == int(exclude):
                continue
            _s = max(float(_o or 40.0), 1.0) * (
                1.0 + max(0.0, self._bus_lateness_for(_v)) / 60.0)
            if _best is None or _s > _best[1]:
                _best = (int(_v), _s)
        return (_best[0] if _best else None)

    def optimize_network(self, time):
        """Corridor-wide joint bus assignment (MULTIBUS_NETWORK).

        Assigns ONE bus per junction (R10 window exclusivity) from the
        per-junction reward-optimal choice, then arbitrates OPPOSING-direction
        buses at ADJACENT junctions whose ETA windows collide: the higher
        combined-score configuration wins and the other junction is demoted to
        its runner-up. This is the decision a per-junction selector cannot
        make alone -- it stops the two-direction offset fight that diffusive
        losses came from. Returns {jct: veh_id}.
        """
        _assign = {}
        try:
            for _j in self.inter_ids:
                try:
                    _b, _s, _n = self.best_bus_for(int(_j), time)
                    if _b is not None:
                        _assign[int(_j)] = (int(_b), float(_s))
                except Exception:
                    continue
            # Adjacent opposing-bus arbitration along the corridor spine.
            try:
                _ids = [int(j) for j in self.inter_ids if j in self.corridor_pos]
                _ids.sort(key=lambda j: float(self.corridor_pos.get(j, 0.0)))
                _win_s = float(globals().get('MULTIBUS_CONFLICT_S', 60.0) or 60.0)
                for _a, _bj in zip(_ids, _ids[1:]):
                    _pa = _assign.get(_a)
                    _pb = _assign.get(_bj)
                    if not _pa or not _pb or _pa[0] == _pb[0]:
                        continue
                    _da = self._bus_dir(_pa[0])
                    _db = self._bus_dir(_pb[0])
                    if _da == 0 or _db == 0 or _da == _db:
                        continue
                    _ea = self._eta_at_j(_pa[0], _a, time)
                    _eb = self._eta_at_j(_pb[0], _bj, time)
                    if _ea is None or _eb is None or abs(_ea - _eb) >= _win_s:
                        continue
                    if _pa[1] >= _pb[1]:
                        _rb = self._runner_up(_bj, time, _pb[0])
                        if _rb is not None:
                            _assign[_bj] = (_rb, 0.0)
                    else:
                        _rb = self._runner_up(_a, time, _pa[0])
                        if _rb is not None:
                            _assign[_a] = (_rb, 0.0)
            except Exception:
                pass
            _out = {}
            for _j, (_b, _s) in _assign.items():
                _out[_j] = _b
            return _out
        except Exception:
            return {}

    def best_bus_for(self, jct_id, time):
        """Reward-optimal bus to serve at jct_id right now (MULTIBUS_JOINT)."""
        # MULTIBUS_NETWORK: consult the corridor-wide joint assignment (cached
        # ~5 s) so per-junction selection follows the network-arbitrated plan.
        try:
            if bool(getattr(_spm, 'MULTIBUS_NETWORK', False)):
                _na = getattr(self, '_net_assign', None)
                _nt = getattr(self, '_net_assign_t', -1e9)
                if _na is None or float(time) - float(_nt) > 5.0:
                    _na = self.optimize_network(float(time))
                    self._net_assign = _na
                    self._net_assign_t = float(time)
                _b = _na.get(int(jct_id))
                if _b is not None:
                    try:
                        _s = 0.0
                        for (_v, _e, _o) in self.oncoming_buses(
                                int(jct_id), float(time)):
                            if int(_v) == int(_b):
                                _s = max(float(_o or 40.0), 1.0) * (
                                    1.0 + max(0.0,
                                              self._bus_lateness_for(_v)) / 60.0)
                        return int(_b), _s, len(self.oncoming_buses(
                            int(jct_id), float(time), 180.0))
                    except Exception:
                        return int(_b), 0.0, 1
        except Exception:
            pass
        try:
            _cands = self.oncoming_buses(jct_id, time, max_eta_s=180.0)
        except Exception:
            _cands = []
        if not _cands:
            return None, 0.0, 0
        _best, _best_s = None, -1.0
        for (_v, _e, _o) in _cands:
            _occ = max(float(_o or 40.0), 1.0)
            _l = self._bus_lateness_for(_v)
            _s = _occ * (1.0 + max(0.0, _l) / 60.0)
            if _s > _best_s:
                _best, _best_s = _v, _s
        # Focus/co-located stability: keep the incumbent unless dominated.
        if (_best is not None and _focus_bus_id > 0 and _best != _focus_bus_id
                and not _is_focus_blocked(_best, jct_id, time)):
            try:
                _foc_s = 0.0
                for (_v, _e, _o) in _cands:
                    if _v == _focus_bus_id:
                        _foc_s = max(float(_o or 40.0), 1.0) * (
                            1.0 + max(0.0, self._bus_lateness_for(_v)) / 60.0)
                if _foc_s > _best_s * 0.9:
                    _best = _focus_bus_id
            except Exception:
                pass
        return _best, _best_s, len(_cands)

    def oncoming_buses(self, jct_id, time, max_eta_s=180.0):
        """Every bus APPROACHING jct_id, as [(veh_id, eta_s, occ)] sorted by eta.

        Lets a junction consider ALL oncoming buses (and how far each is) when it
        decides -- not just the one that happened to be detected. Uses each live
        Kalman tracker (now continuously position-corrected, §50) so the ETAs are
        current. Returns nearest-first; empty if none within max_eta_s.
        """
        _tp = self.corridor_pos.get(jct_id)
        if _tp is None:
            return []
        out = []
        for _vid, _trk in list(self._trackers.items()):
            try:
                _eta_s = _trk.eta(_tp, time) - time
            except Exception:
                continue
            if 0.0 <= _eta_s <= max_eta_s:
                _occ = float(_bus_occupancy.get(_vid, 40.0)) if '_bus_occupancy' in globals() else 40.0
                out.append((int(_vid), float(_eta_s), _occ))
        out.sort(key=lambda t: t[1])
        return out

    def _signal_aware_eta(self, from_id: int, to_id: int,
                          tracker: 'BusKalmanTracker', time: float) -> float:
        """
        Signal-aware estimated arrival time (sim-seconds) at to_id.

        Rather than pure distance/speed, walks every junction in
        route_inter_ids between from_id and to_id, computing at each step:
          1. Kinematic travel time from the last known position to this junction
          2. Expected red wait at this junction (_signal_delay_at_s)

        The accumulated position+time is used as input to the next kinematic
        leg. Falls back to tracker.eta() when route position data is
        unavailable for intermediate junctions.

        The Kalman tracker state is read but never modified here; regular
        tracker.update() behaviour is undisturbed.
        """
        from_idx = self._route_index.get(from_id)
        to_idx   = self._route_index.get(to_id)
        to_pos   = self.corridor_pos.get(to_id)
        try:
            _eta_max = float(getattr(self, 'ETA_MAX_S', 300.0) or 300.0)
        except Exception:
            _eta_max = 300.0

        def _cap(_t):
            _t = max(float(time), float(_t))
            return min(float(_t), float(time) + _eta_max)

        if from_idx is None or to_idx is None or to_pos is None:
            return (_cap(tracker.eta(to_pos, time))
                    if to_pos is not None else _cap(time + _eta_max))

        lo, hi = sorted((from_idx, to_idx))
        intermediates = self.route_inter_ids[lo + 1: hi]  # exclusive of endpoints

        if not intermediates:
            return _cap(tracker.eta(to_pos, time))

        # Propagate at current tracker speed; fall back to default if stalled
        spd = abs(tracker.x[1])
        if spd < 0.5:
            spd = BusKalmanTracker.DEFAULT_SPEED_MS

        # Walk intermediates in route direction
        is_northbound = (to_idx > from_idx)
        step_jcts = intermediates if is_northbound else list(reversed(intermediates))

        t_cursor   = time
        pos_cursor = tracker.x[0]  # current bus position along corridor (m)

        for jct_id in step_jcts:
            jct_pos = self.corridor_pos.get(jct_id)
            if jct_pos is None:
                # No corridor position — add fixed delay estimate and continue
                t_cursor += self._estimate_unmanaged_delay_s(jct_id)
                continue

            dist_m   = abs(jct_pos - pos_cursor)
            t_arrive = t_cursor + dist_m / spd
            t_cursor = t_arrive + self._signal_delay_at_s(jct_id, t_arrive, time)
            pos_cursor = jct_pos

        # Final kinematic leg from last intermediate to target junction
        dist_final = abs(to_pos - pos_cursor)
        t_cursor += dist_final / spd
        return _cap(t_cursor)

    # ------------------------------------------------------------------
    def _objective_lead_time(self, gb, bus_sg, eta_t: float, time: float,
                              tracker) -> float:
        """
        OBJECTIVE mode: compute the pre-arm lead time that maximises:
          J = COORD_OBJ_ALPHA * bus_delay_saved_persons
            - COORD_OBJ_BETA  * normal_throughput_displaced_persons

        This avoids the perverse incentive of pure delay minimisation
        (fewer vehicles served → lower total delay) by explicitly including
        a throughput benefit term.  Lead times from 5 to 60 s are evaluated;
        the one with the highest J is returned.

        Parameters
        ----------
        gb       : GroupBasedController at the downstream intersection
        bus_sg   : signal group for bus at that intersection
        eta_t    : estimated arrival time (absolute sim seconds)
        time     : current sim time
        tracker  : BusKalmanTracker for this vehicle
        """
        BUS_OCC     = getattr(gb, 'BusOcc',   40.0)
        NORMAL_OCC  = getattr(gb, 'CarOcc',    1.5)
        MAX_RED_WAIT = getattr(gb, '_eta_max_s', 60.0)   # typical max red wait

        try:
            queue    = gb._compute_queue()
            q_bus_sg = queue.get(bus_sg, 0)
        except Exception:
            q_bus_sg = 0

        # Arrival time uncertainty: 1-sigma from Kalman tracker
        try:
            target_pos = self.corridor_pos.get(
                next(iid for iid, c in self._ctrl_map.items() if c is gb), None)
            sigma = tracker.uncertainty_s(target_pos) if target_pos else 15.0
        except Exception:
            sigma = 15.0

        best_J    = -1e9
        best_lead = self.PRE_GREEN_LEAD_S   # fallback to fixed default

        for lead in range(5, 65, 5):
            eta_in = eta_t - time   # seconds until bus arrives
            # P[bus arrives during green] grows as lead / (2*sigma)
            p_green = min(1.0, max(0.0, lead / (2.0 * sigma + 1.0)))

            # Delay saved for bus: avoided red wait × occupancy
            # Maximum possible red wait capped at MAX_RED_WAIT
            delay_saved = min(eta_in, MAX_RED_WAIT) * p_green * BUS_OCC

            # Normal-traffic cost: pre-arming disrupts normal phases for ~lead s.
            # Queue at downstream * occupancy * fractional green lost.
            green_fraction_lost = lead / max(self.PRE_GREEN_LEAD_S * 2, 30.0)
            throughput_lost = q_bus_sg * NORMAL_OCC * green_fraction_lost

            J = COORD_OBJ_ALPHA * delay_saved - COORD_OBJ_BETA * throughput_lost
            if J > best_J:
                best_J    = J
                best_lead = float(lead)

        if LOG_CORRIDOR:
            _vprint(
                f"[CORRIDOR OBJ] Optimal lead={best_lead:.0f}s "
                f"J={best_J:.1f} sigma={sigma:.1f}s q={q_bus_sg}"
            )
        return best_lead

    # ------------------------------------------------------------------
    def _next_managed_target_from_tracker(self, veh_id: int) -> int:
        """
        Infer the immediate next managed junction from current Kalman state
        (position + direction) while preserving corridor-wide route knowledge.
        """
        trk = self._trackers.get(veh_id)
        if trk is None or not self.corridor_pos:
            return -1

        try:
            pos_m = float(trk.x[0])
            vel_ms = float(trk.x[1])
        except Exception:
            return -1

        is_nb = vel_ms >= 0.0
        managed = set(self.inter_ids)

        ordered = []
        for iid in self.route_inter_ids:
            p = self.corridor_pos.get(iid)
            if p is not None:
                ordered.append((iid, float(p)))
        if not ordered:
            return -1

        nearest_iid = min(ordered, key=lambda t: abs(t[1] - pos_m))[0]
        base_idx = self._route_index.get(nearest_iid)
        if base_idx is None:
            return -1

        step = 1 if is_nb else -1
        idx = base_idx + step
        while 0 <= idx < len(self.route_inter_ids):
            iid = self.route_inter_ids[idx]
            if iid in managed:
                return int(iid)
            idx += step
        return -1

    # ------------------------------------------------------------------
    def _has_passed_source_jct(self, veh_id: int, source_jct: int,
                               is_northbound: bool, min_pass_m: float = 25.0) -> bool:
        """True when tracker position is at least min_pass_m past source_jct."""
        trk = self._trackers.get(veh_id)
        src_pos = self.corridor_pos.get(source_jct)
        if trk is None or src_pos is None:
            return False
        try:
            pos_m = float(trk.x[0])
            pass_m = max(5.0, float(min_pass_m))
        except Exception:
            return False
        if is_northbound:
            return pos_m >= (float(src_pos) + pass_m)
        return pos_m <= (float(src_pos) - pass_m)

    # ------------------------------------------------------------------
    def _corridor_xy(self):
        """Cache {jct: (x,y)} for every corridor junction (from its controller)."""
        c = getattr(self, '_corridor_xy_cache', None)
        if c is not None:
            return c
        c = {}
        for _jid in self.corridor_pos:
            _ctrl = self._ctrl_map.get(_jid)
            try:
                _xy = _ctrl._get_junction_xy() if _ctrl is not None else None
            except Exception:
                _xy = None
            if _xy and len(_xy) >= 2:
                c[_jid] = (float(_xy[0]), float(_xy[1]))
        self._corridor_xy_cache = c
        return c

    def _project_to_corridor(self, veh_id):
        """Project a bus's LIVE (x,y) onto the corridor as a 1D position (m), so
        the Kalman filter can be corrected every second instead of running open-
        loop between junctions.  Interpolates between the two nearest corridor
        junctions by inverse distance.  Returns None when geometry is missing or
        the bus is clearly off-corridor (so the caller keeps predict-only)."""
        _xy = _bus_xy.get(veh_id)
        if not _xy:
            return None
        _jxy = self._corridor_xy()
        if len(_jxy) < 2:
            return None
        _ds = sorted((( (float(_xy[0]) - _c[0]) ** 2 + (float(_xy[1]) - _c[1]) ** 2) ** 0.5, _j)
                     for _j, _c in _jxy.items())
        (_da, _ja), (_db, _jb) = _ds[0], _ds[1]
        _pa = self.corridor_pos.get(_ja); _pb = self.corridor_pos.get(_jb)
        if _pa is None or _pb is None:
            return None
        # Off-corridor guard: nearest junction improbably far -> don't trust it.
        if _da > 1200.0:
            return None
        _tot = _da + _db
        return _pa if _tot < 1e-6 else (_pa + (_pb - _pa) * (_da / _tot))

    def _process_pre_requests(self, time: float, timeSta: float):
        """Fire pre-green requests when the bus is within the algorithm's lead time."""
        # COORD_PREARM_ENABLED=False: coordinate the decision but never fire a
        # downstream pre-green. notify_bus_granted already stops queuing, so this
        # is defensive (and clears anything queued before the flag flipped).
        if not bool(globals().get('COORD_PREARM_ENABLED', True)):
            if self._pre_requests:
                self._pre_requests.clear()
            return
        for inter_id, req in list(self._pre_requests.items()):
            if len(req) >= 5:
                veh_id, eta_t, bus_sg, issued_t, source_jct = req
            else:
                veh_id, eta_t, bus_sg, issued_t = req
                source_jct = -1

            # Enforce that prearms always retain a valid source junction context.
            # Requests without source are unsafe to retarget/fire and can jump route.
            if source_jct <= 0:
                if LOG_CORRIDOR:
                    log_to_file(
                        f"[PREARM DROP] jct={inter_id} bus={veh_id} "
                        f"missing source_jct (legacy/invalid request)"
                    )
                self._pre_requests.pop(inter_id, None)
                continue

            # If PT line is known, ensure source_jct belongs to that line route.
            _line_id = _bus_line_id.get(veh_id, -1)
            _line_route = _pt_line_jct_route.get(_line_id) if _line_id > 0 else None
            if _line_route and source_jct not in _line_route:
                if LOG_CORRIDOR:
                    log_to_file(
                        f"[PREARM DROP] jct={inter_id} bus={veh_id} src={source_jct} "
                        f"not on PT route line={_line_id}"
                    )
                self._pre_requests.pop(inter_id, None)
                continue

            _tracker_live = self._trackers.get(veh_id)
            _is_nb = True
            if _tracker_live is not None:
                try:
                    _is_nb = float(_tracker_live.x[1]) >= 0.0
                except Exception:
                    _is_nb = True

            # Re-evaluate immediate-next target at fire time using intended
            # route first (PT route / observed route), then tracker fallback.
            expected_next = -1
            if source_jct > 0:
                _intended = self._iter_managed_targets(source_jct, _is_nb, veh_id=veh_id)
                if _intended:
                    expected_next = int(_intended[0])
            if expected_next <= 0:
                expected_next = self._next_managed_target_from_tracker(veh_id)

            # Hard gate: do not fire downstream prearm until the bus has physically
            # moved past the source junction that queued this request.
            _pass_gate_m = float(globals().get('PREARM_SOURCE_PASS_M', 25.0) or 25.0)
            if source_jct > 0 and _tracker_live is not None:
                if not self._has_passed_source_jct(veh_id, source_jct, _is_nb, _pass_gate_m):
                    # Pass-gate hold bookkeeping: count + first-hold time so we
                    # can tell a junction that clears each bus from one that
                    # never clears (starvation).
                    self._pass_hold_n[inter_id] = int(self._pass_hold_n.get(inter_id, 0)) + 1
                    self._pass_hold_t0.setdefault((veh_id, inter_id), float(time))
                    if LOG_CORRIDOR:
                        log_to_file(
                            f"[PREARM HOLD] bus={veh_id} src={source_jct} tgt={inter_id} "
                            f"waiting_pass>{_pass_gate_m:.0f}m before fire"
                        )
                    continue

            if expected_next > 0 and expected_next != inter_id:
                if LOG_CORRIDOR:
                    log_to_file(
                        f"[CORRIDOR RETARGET] bus={veh_id} queued_jct={inter_id} "
                        f"expected_next={expected_next} source={source_jct}"
                    )
                _target_pos = self.corridor_pos.get(expected_next)
                _tracker_live = self._trackers.get(veh_id)
                if _target_pos is not None and _tracker_live is not None:
                    try:
                        eta_new = float(_tracker_live.eta(_target_pos, time))
                    except Exception:
                        eta_new = float(eta_t)
                else:
                    eta_new = float(eta_t)

                _new_gb = self._ctrl_map.get(expected_next)
                new_bus_sg = _new_gb.bus_sg if _new_gb is not None else bus_sg
                self._pre_requests[expected_next] = (
                    veh_id, eta_new, new_bus_sg, time,
                    source_jct if source_jct > 0 else inter_id,
                )
                self._pre_requests.pop(inter_id, None)
                _record_wave_event(
                    time, self.name, "prearm_retarget",
                    source_jct=self._wave_origin,
                    target_jct=expected_next,
                    veh_id=veh_id,
                    eta_s=max(0.0, eta_new - time),
                    note=f"old={inter_id}",
                    old_target_jct=inter_id,
                    expected_target_jct=expected_next,
                )
                continue

            _max_prearm_horizon_s = float(
                getattr(self, '_max_prearm_horizon_s', float(globals().get('MAX_PREARM_HORIZON_S', 135.0) or 135.0))
            )
            if (eta_t - time) > _max_prearm_horizon_s:
                self._pre_requests.pop(inter_id, None)
                self._record_prearm_discarded(inter_id)
                _record_wave_event(
                    time, self.name, "prearm_discarded",
                    source_jct=self._wave_origin,
                    target_jct=inter_id,
                    veh_id=veh_id,
                    eta_s=max(0.0, eta_t - time),
                    note=f"over_horizon>{_max_prearm_horizon_s:.0f}s",
                )
                continue

            # Stale: bus never arrived or took a different route
            if time - issued_t > self.PRE_REQ_TIMEOUT_S or eta_t - time < -30.0:
                self._pass_gate_starve(inter_id, veh_id, "expired")
                self._pre_requests.pop(inter_id, None)
                self._prearm_stats["expired"] = int(self._prearm_stats.get("expired", 0)) + 1
                log_to_file(
                    f"[CORRIDOR PREARM] EXPIRED jct={inter_id} bus={veh_id} "
                    f"age={time - issued_t:.0f}s ETA_was={eta_t:.1f}s now={time:.1f}s"
                )
                _record_wave_event(
                    time, self.name, "prearm_expired",
                    source_jct=self._wave_origin,
                    target_jct=inter_id,
                    veh_id=veh_id,
                    eta_s=eta_t - time,
                )
                continue

            # ── Dynamic lead time computation ─────────────────────────────────
            # Standard fixed-lead fires PRE_GREEN_LEAD_S seconds before ETA.
            # OBJECTIVE algo computes a bus-delay-vs-throughput optimal lead.
            # In addition, we add "phase_lead" — the minimum time the downstream
            # junction needs to finish its current phase and enter intergreen so
            # that the bus phase is ready on arrival.  This prevents the bus from
            # arriving before the pre-armed phase even starts.
            gb = self._ctrl_map.get(inter_id)
            lead_reason = "fixed"
            lead_sigma = None
            phase_lead = 0.0
            if COORDINATION_ALGO == "OBJECTIVE" and gb is not None and bus_sg is not None:
                _tracker = self._trackers.get(veh_id)
                if _tracker is not None:
                    lead_s = self._objective_lead_time(gb, bus_sg, eta_t, time, _tracker)
                    lead_reason = "objective"
                else:
                    lead_s = self.PRE_GREEN_LEAD_S
                    lead_reason = "objective-fallback"
            else:
                # Systematic adaptive lead (2026-09-28): uncertainty-scaled for
                # EVERY coordination algo, not just ADAPTIVE -- a confident
                # prediction (low sigma) pre-arms short, a noisy one long, so
                # the green window tracks the Kalman confidence rather than a
                # fixed lead. base 15 s + 3×sigma, clamped [20, 75].
                lead_s = self.PRE_GREEN_LEAD_S
                lead_reason = "adaptive-base"
                _tracker = self._trackers.get(veh_id)
                if _tracker is not None:
                    try:
                        _target = self.corridor_pos.get(inter_id)
                        _sigma = _tracker.uncertainty_s(_target) if _target is not None else 12.0
                    except Exception:
                        _sigma = 12.0
                    lead_sigma = _sigma
                    _adaptive_lead = max(20.0, min(75.0, 15.0 + 3.0 * _sigma))
                    lead_s = _adaptive_lead
                    lead_reason = "adaptive-sigma"

            # Add phase-transition overhead if the downstream junction exposes it
            if gb is not None:
                phase_lead = getattr(gb, '_min_lead_for_phase_change_s', 0.0)
                lead_s = max(lead_s, phase_lead)

            if LOG_CORRIDOR:
                _sigma_txt = f"{lead_sigma:.1f}" if lead_sigma is not None else "na"
                log_to_file(
                    f"[CORRIDOR DECISION] algo={COORDINATION_ALGO} stage=fire "
                    f"jct={inter_id} bus={veh_id} eta_in={eta_t - time:.1f} "
                    f"lead={lead_s:.1f} phase_lead={phase_lead:.1f} "
                    f"base_lead={self.PRE_GREEN_LEAD_S:.1f} sigma={_sigma_txt} reason={lead_reason}"
                )

            if lead_reason in ("adaptive-sigma", "adaptive-base"):
                self._algo_diag["adaptive_fire_count"] = int(self._algo_diag.get("adaptive_fire_count", 0) or 0) + 1
                self._algo_diag["adaptive_lead_total_s"] = float(self._algo_diag.get("adaptive_lead_total_s", 0.0) or 0.0) + float(lead_s)
                self._algo_diag["adaptive_lead_min_s"] = min(
                    float(self._algo_diag.get("adaptive_lead_min_s", 1e9) or 1e9),
                    float(lead_s),
                )
                self._algo_diag["adaptive_lead_max_s"] = max(
                    float(self._algo_diag.get("adaptive_lead_max_s", 0.0) or 0.0),
                    float(lead_s),
                )
                if abs(float(lead_s) - float(self.PRE_GREEN_LEAD_S)) > 0.1:
                    self._algo_diag["adaptive_dynamic_count"] = int(self._algo_diag.get("adaptive_dynamic_count", 0) or 0) + 1

            # ── Refresh ETA from live Kalman before fire check ─────────────
            # The stored eta_t was computed at queue time.  If the tracker has
            # been updated since then, use its current estimate so the fire
            # condition reacts to the bus's actual progress.  This prevents
            # prearms firing when the bus is already at (or past) the target.
            _tracker_live_pre = self._trackers.get(veh_id)
            _target_pos_pre   = self.corridor_pos.get(inter_id)
            if _tracker_live_pre is not None and _target_pos_pre is not None:
                try:
                    _refreshed_eta = _tracker_live_pre.eta(_target_pos_pre, time)
                    if _refreshed_eta is not None:
                        _prev_eta_t = float(eta_t)
                        eta_t = float(_refreshed_eta)
                        # Keep queued request ETA aligned to the latest tracker
                        # estimate so fire/horizon checks don't act on stale ETA.
                        if abs(eta_t - _prev_eta_t) > 0.5 and inter_id in self._pre_requests:
                            self._pre_requests[inter_id] = (
                                veh_id, eta_t, bus_sg, issued_t, source_jct
                            )
                            if LOG_CORRIDOR:
                                log_to_file(
                                    f"[PREARM ETA REFRESH] jct={inter_id} bus={veh_id} "
                                    f"eta_in {_prev_eta_t - time:.1f}s -> {eta_t - time:.1f}s"
                                )
                except Exception:
                    pass

            # ── Realistic prediction horizon: never pre-arm for a junction
            # farther than PREARM_MAX_DIST_M along the route — beyond that,
            # ETAs are dominated by stops/signals and nothing actionable
            # exists now.
            _trk_d = self._trackers.get(veh_id)
            _tp_d = self.corridor_pos.get(inter_id)
            if _trk_d is not None and _tp_d is not None:
                try:
                    _dist_m = abs(float(_tp_d) - float(_trk_d.x[0]))
                except Exception:
                    _dist_m = None
                if _dist_m is not None and _dist_m > float(
                        globals().get('PREARM_MAX_DIST_M', 2000.0)):
                    self._pass_gate_starve(inter_id, veh_id, "too_far")
                    self._pre_requests.pop(inter_id, None)
                    self._prearm_stats.setdefault('too_far', 0)
                    self._prearm_stats['too_far'] += 1
                    continue

            # Re-apply horizon gate after ETA refresh so requests that moved far
            # out in time do not fire too early with stale queue-time ETA.
            if (eta_t - time) > _max_prearm_horizon_s:
                self._pass_gate_starve(inter_id, veh_id, "over_horizon_refresh")
                self._pre_requests.pop(inter_id, None)
                self._record_prearm_discarded(inter_id)
                _record_wave_event(
                    time, self.name, "prearm_discarded",
                    source_jct=source_jct,
                    target_jct=inter_id,
                    veh_id=veh_id,
                    eta_s=max(0.0, eta_t - time),
                    note=f"over_horizon_refreshed>{_max_prearm_horizon_s:.0f}s",
                )
                continue

            # Discard prearm if the bus is already too close to benefit.
            # With < MIN_PREARM_LEAD_S lead time the downstream signal cannot
            # finish its current phase and enter the bus phase in time.
            _min_prearm_lead_s = float(
                getattr(self, 'MIN_EFFECTIVE_PREARM_LEAD_S',
                        globals().get('MIN_EFFECTIVE_PREARM_LEAD_S', 10.0) or 10.0)
            )
            if eta_t - time < _min_prearm_lead_s:
                self._pre_requests.pop(inter_id, None)
                self._prearm_stats.setdefault("too_late_to_act", 0)
                self._prearm_stats["too_late_to_act"] += 1
                _record_wave_event(
                    time, self.name, "prearm_discarded",
                    source_jct=source_jct,
                    target_jct=inter_id,
                    veh_id=veh_id,
                    eta_s=max(0.0, eta_t - time),
                    note="too_late_to_act",
                )
                if LOG_CORRIDOR:
                    log_to_file(
                        f"[PREARM TOO LATE] jct={inter_id} bus={veh_id} "
                        f"eta_in={eta_t - time:.1f}s < min={_min_prearm_lead_s:.0f}s — discarded"
                    )
                continue

            if eta_t - time <= lead_s:
                # ── Revalidate ETA with current Kalman state ──────────
                # The prearm was queued earlier — recheck that the tracker
                # still predicts a reasonable arrival.  If the live ETA
                # now exceeds the original by more than 30 s the bus may
                # have been delayed or diverted; skip the fire.
                _tracker_live = self._trackers.get(veh_id)
                _target_pos   = self.corridor_pos.get(inter_id)
                if _tracker_live is not None and _target_pos is not None:
                    try:
                        _live_eta = _tracker_live.eta(_target_pos, time)
                        if _live_eta is not None and _live_eta > eta_t + 30.0:
                            if LOG_CORRIDOR:
                                log_to_file(
                                    f"[CORRIDOR SKIP FIRE] jct={inter_id} bus={veh_id} "
                                    f"live_eta={_live_eta:.1f}s vs queued_eta={eta_t:.1f}s "
                                    f"— bus delayed, skipping prearm fire"
                                )
                            self._pre_requests.pop(inter_id, None)
                            self._prearm_stats.setdefault("revalidation_skip", 0)
                            self._prearm_stats["revalidation_skip"] += 1
                            continue
                    except Exception:
                        pass

                if gb is not None and bus_sg is not None and gb.bus_request is None:
                    # Respect the per-vehicle cooldown at the target junction
                    cooldown_ok = not (
                        veh_id == getattr(gb, '_last_served_veh_id', None)
                        and time - getattr(gb, '_last_served_time', -9999.0)
                        < getattr(gb, '_served_veh_timeout', 120.0)
                    )
                    if not cooldown_ok:
                        # Cooldown active — bus recently served at this junction.
                        # Record as prearm_skipped so the dashboard coord-flow can
                        # show that the coordinator saw the bus but chose not to act.
                        _record_wave_event(
                            time, self.name, "prearm_skipped",
                            source_jct=self._wave_origin,
                            target_jct=inter_id,
                            veh_id=veh_id,
                            eta_s=max(0.0, eta_t - time),
                            note="cooldown",
                        )
                        self._pre_requests.pop(inter_id, None)
                        self._prearm_stats.setdefault("skipped_cooldown", 0)
                        self._prearm_stats["skipped_cooldown"] += 1
                        continue
                    if cooldown_ok:
                        # Adherence gate FIRST: an early/on-time bus gets NO
                        # priority preparation -- holding restores schedule.
                        if not _prearm_allow(veh_id):
                            stats._prearm_stats['skipped_early_bus'] = \
                                stats._prearm_stats.get('skipped_early_bus', 0) + 1
                            self._pre_requests.pop(inter_id, None)
                            continue
                        gb.bus_request = bus_sg
                        gb._active_bus_veh_id = veh_id
                        gb._bus_eta = max(0.0, eta_t - time)
                        gb._bus_det_time = time
                        # Mark as coordinator-sourced so the detection suppression
                        # logic in _detect_bus/_detect_bus_urtsp knows to let it through.
                        gb._coord_sourced_request = True
                        # Lift the wave ban for this junction: it is now reacting
                        # to coordination, not acting independently.
                        self._wave_served_ids.add(inter_id)
                        self._record_prearm_fired(
                            inter_id, veh_id, eta_t, time,
                            source_jct=source_jct,
                            algo=COORDINATION_ALGO,
                            lead_reason=lead_reason,
                        )
                        # Use the bus's live position (from position tracker) so
                        # prearm marks show WHERE the bus was when the prearm
                        # fired, not where the downstream junction is.  This
                        # prevents all coord-prearm dots from piling up on the
                        # junction centroid when many buses are served.
                        _bus_live_xy = _bus_xy.get(veh_id)
                        _prearm_x = _bus_live_xy[0] if _bus_live_xy else 0.0
                        _prearm_y = _bus_live_xy[1] if _bus_live_xy else 0.0
                        if not _bus_live_xy:
                            _junc_xy_fb = getattr(gb, '_junction_xy_cache', None)
                            if _junc_xy_fb:
                                _prearm_x, _prearm_y = _junc_xy_fb
                        _mark_detection_point(
                            inter_id, veh_id, _prearm_x, _prearm_y,
                            time, f"coord-prearm/{COORDINATION_ALGO}",
                            {
                                "force_write": True,
                                "prearm_status": "fired",
                                "prearm_eta_s": round(max(0.0, eta_t - time), 1),
                                "prearm_eta_abs_s": round(float(eta_t), 1),
                                "prearm_fired_t": round(float(time), 1),
                                "prearm_note": lead_reason,
                            },
                        )
                        if LOG_CORRIDOR:
                            _vprint(
                                f"[CORRIDOR {COORDINATION_ALGO}] Pre-green FIRED "
                                f"jct={inter_id} bus={veh_id} SG={bus_sg} "
                                f"ETA_in={eta_t - time:.1f}s lead={lead_s:.0f}s "
                                f"— ban lifted for jct{inter_id}"
                            )
                elif inter_id in self._ic_map:
                    # HARMONY intersection — set _harmony_prearm so check_bus_priority
                    # applies TSP immediately using the Kalman ETA.
                    ic = self._ic_map[inter_id]
                    if ic._harmony_prearm is None:
                        # Adherence gate BEFORE any state mutation.
                        if not _prearm_allow(veh_id):
                            stats._prearm_stats['skipped_early_bus'] = \
                                stats._prearm_stats.get('skipped_early_bus', 0) + 1
                            self._pre_requests.pop(inter_id, None)
                            continue
                        # Directional payload (2026-09-26): route direction of this
                        # bus (+1/-1 along route_index) travels with the prearm
                        # so the downstream junction knows which corridor
                        # direction is arriving (the GB path already carries
                        # this implicitly via bus_sg).
                        try:
                            _ri = self._route_index or {}
                            _rs = int(_ri.get(source_jct, -1))
                            _rt = int(_ri.get(inter_id, -1))
                            _pdir = 1 if _rt > _rs else (-1 if _rt < _rs else 0)
                        except Exception:
                            _pdir = 0
                        ic._harmony_prearm = (veh_id, eta_t, time, _pdir,
                                              source_jct)
                        self._wave_served_ids.add(inter_id)
                        self._record_prearm_fired(
                            inter_id, veh_id, eta_t, time,
                            source_jct=source_jct,
                            algo=COORDINATION_ALGO,
                            lead_reason=lead_reason,
                        )
                        # Same as GB path: mark bus's live position, not junction.
                        _bus_live_xy_h = _bus_xy.get(veh_id)
                        _prearm_hx = _bus_live_xy_h[0] if _bus_live_xy_h else 0.0
                        _prearm_hy = _bus_live_xy_h[1] if _bus_live_xy_h else 0.0
                        if not _bus_live_xy_h:
                            try:
                                _junc_xy_h = ic._get_junction_xy()
                                if _junc_xy_h:
                                    _prearm_hx, _prearm_hy = _junc_xy_h
                            except Exception:
                                pass
                        _mark_detection_point(
                            inter_id, veh_id, _prearm_hx, _prearm_hy,
                            time, f"coord-prearm-harmony/{COORDINATION_ALGO}",
                            {
                                "force_write": True,
                                "prearm_status": "fired",
                                "prearm_eta_s": round(max(0.0, eta_t - time), 1),
                                "prearm_eta_abs_s": round(float(eta_t), 1),
                                "prearm_fired_t": round(float(time), 1),
                                "prearm_note": lead_reason,
                            },
                        )
                        if LOG_CORRIDOR:
                            _vprint(
                                f"[CORRIDOR {COORDINATION_ALGO}] HARMONY Pre-arm FIRED "
                                f"jct={inter_id} bus={veh_id} "
                                f"ETA_in={eta_t - time:.1f}s lead={lead_s:.0f}s"
                            )
                self._pre_requests.pop(inter_id, None)

    # ------------------------------------------------------------------
    def _check_wave_complete(self, time: float):
        """
        Lift the corridor wave ban once all pre-requests for the current wave
        have been resolved (fired or expired) AND every pre-armed junction has
        cleared its coordinated bus phase (bus_request is None).

        Also expires a wave that has been running for > 2 × PRE_REQ_TIMEOUT_S
        as a safety net against buses that never arrive.
        """
        if not self._wave_active:
            return

        # Safety expiry
        # (we store wave start time lazily — use issued_t of the last stale check)
        # Simple heuristic: if no pre_requests remain and all served junctions
        # have cleared their bus_request, the wave is done.
        pending = bool(self._pre_requests)
        any_coord_pending = any(
            getattr(self._ctrl_map.get(iid), 'bus_request', None) is not None
            and getattr(self._ctrl_map.get(iid), '_coord_sourced_request', False)
            for iid in self._wave_served_ids
            if iid != self._wave_origin
        )
        # Also check HARMONY intersections: wave is pending while _harmony_prearm is set
        any_harmony_pending = any(
            getattr(self._ic_map.get(iid), '_harmony_prearm', None) is not None
            for iid in self._wave_served_ids
            if iid != self._wave_origin
        )

        if not pending and not any_coord_pending and not any_harmony_pending:
            self._wave_active     = False
            self._wave_veh_id     = -1
            self._wave_origin     = -1
            self._wave_served_ids = set()
            if LOG_CORRIDOR:
                _vprint(
                    f"[CORRIDOR WAVE] t={time:.1f} WAVE COMPLETE — "
                    f"independent TSP ban fully lifted for all corridor junctions"
                )
            _record_wave_event(
                time, self.name, "wave_complete",
                source_jct=-1,
                target_jct=-1,
                veh_id=-1,
            )

    # ------------------------------------------------------------------
    def step(self, time: float, timeSta: float):
        """Called every simulation step from AAPIPostManage."""
        if not self._ctrl_map and not self._ic_map:
            return

        # Process Kalman pre-green requests first (works for both GB and HARMONY modes)
        if COORDINATED_TSP:
            self._process_pre_requests(time, timeSta)
            self._expire_fired_prearms(time)
            self._check_wave_complete(time)

        # ── Keep Kalman trackers current between junction detections ────────────────
        # Advance each tracker by the elapsed time so that ETA queries always
        # reflect the bus's CURRENT estimated position, not its state at the
        # last junction.  Without this, a bus detected at position=0 would
        # always return an ETA based on position=0, not position=speed*dt.
        for _trk_vid, _trk in self._trackers.items():
            if _trk.last_t is not None and time > _trk.last_t + 0.5:
                _trk.predict(time - _trk.last_t)
                # CONTINUOUS CORRECTION: fuse the bus's live per-step position so
                # the filter tracks it down to the second instead of drifting
                # open-loop between junctions (the source of unreliable ETAs).
                # The buses ARE tracked continuously (_bus_xy); this feeds that
                # into the Kalman update so pre-arm ETAs stay accurate.
                if bool(globals().get('COORD_FUSE_LIVE_POS', True)):
                    try:
                        _live_pos = self._project_to_corridor(_trk_vid)
                        if _live_pos is not None:
                            _trk.update(float(_live_pos))
                    except Exception:
                        pass
                _trk.last_t = time

        # ── Bus trip time tracking ────────────────────────────────────────────────
        # Track bus entry/exit times to compute std dev of trip times
        try:
            if not hasattr(self, '_bus_trip_times'):
                self._bus_trip_times = []          # completed trip times (seconds)
            if not hasattr(self, '_bus_entry_times'):
                self._bus_entry_times = {}         # veh_id -> entry_time
            
            # Get all currently tracked bus IDs
            _current_bus_ids = set(self._trackers.keys())
            _previous_bus_ids = getattr(self, '_previous_bus_ids', set())
            
            # New buses entering the network
            _new_buses = _current_bus_ids - _previous_bus_ids
            for _vid in _new_buses:
                self._bus_entry_times[_vid] = time
            
            # Buses that left the network
            _departed_buses = _previous_bus_ids - _current_bus_ids
            for _vid in _departed_buses:
                _entry_time = self._bus_entry_times.pop(_vid, None)
                if _entry_time is not None:
                    _trip_time = time - _entry_time
                    if _trip_time > 0:
                        self._bus_trip_times.append(_trip_time)
            
            self._previous_bus_ids = _current_bus_ids
        except Exception:
            pass

        # ── Refresh pending pre-request ETAs with current shockwave state ─────────
        # The ETA queued in _pre_requests was computed when the bus was at the
        # previous junction.  As the bus travels (tracker advances above) and
        # queue conditions change, the ETA shifts.  Refresh it every
        # _ETA_REFRESH_INTERVAL_S so the timing window fires at the right moment.
        _ETA_REFRESH_INTERVAL_S = 1.0
        if COORDINATED_TSP and self._pre_requests:
            _refresh_due = time - getattr(self, '_last_eta_refresh_t', -999.0) >= _ETA_REFRESH_INTERVAL_S
            if _refresh_due:
                self._last_eta_refresh_t = time
                for _ri_id, _req in list(self._pre_requests.items()):
                    _rv = _req[0]   # veh_id
                    _re = _req[1]   # eta_t
                    _rs = _req[2]   # bus_sg
                    _ri = _req[3]   # issued_t
                    _rsrc = _req[4] if len(_req) >= 5 else -1
                    if _re < time - 5.0:   # already past ETA — skip
                        continue
                    _trk_live = self._trackers.get(_rv)
                    _tgt_pos  = self.corridor_pos.get(_ri_id)
                    if _trk_live is None or _tgt_pos is None:
                        continue
                    # Source junction for signal_aware_eta: use wave origin or source
                    _src_id = self._wave_origin if self._wave_origin > 0 else _rsrc
                    if _src_id > 0 and _src_id in self._route_index:
                        _new_eta = self._signal_aware_eta(_src_id, _ri_id, _trk_live, time)
                    else:
                        _new_eta = _trk_live.eta(_tgt_pos, time)
                    # Apply shockwave queue correction
                    _n_gb  = self._ctrl_map.get(_ri_id)
                    _n_ic  = self._ic_map.get(_ri_id)
                    _n_sg  = _n_gb.bus_sg if _n_gb else None
                    if COORDINATION_ALGO in ("SHOCKWAVE", "ADAPTIVE"):
                        _new_eta, _, _, _ = self._shockwave_eta_adjust(
                            _n_gb, _n_sg, _new_eta, next_ic=_n_ic)
                    # Only update if changed by > 5 s to avoid jitter
                    if abs(_new_eta - _re) > 5.0:
                        self._pre_requests[_ri_id] = (_rv, _new_eta, _rs, _ri, _rsrc)
                        if LOG_CORRIDOR:
                            log_to_file(
                                f"[ETA_REFRESH] jct={_ri_id} bus={_rv} "
                                f"old_eta_in={_re - time:.1f}s new_eta_in={_new_eta - time:.1f}s "
                                f"delta={_new_eta - _re:+.1f}s")

        states    = {iid: c.state            for iid, c in self._ctrl_map.items()}
        n_groups  = {iid: len(getattr(c, 'phase_groups', None) or [])
                     for iid, c in self._ctrl_map.items()}
        bus_reqs  = {iid: c.bus_request       for iid, c in self._ctrl_map.items()}

        n_idle       = sum(1 for s in states.values() if s == GroupBasedController.IDLE)
        n_green      = sum(1 for s in states.values() if s == GroupBasedController.GREEN)
        n_intergreen = sum(1 for s in states.values() if s == GroupBasedController.INTERGREEN)
        any_bus_req  = any(v is not None for v in bus_reqs.values())

        # ── Periodic state dump ───────────────────────────────────────────────
        if LOG_CORRIDOR and time - self._last_log_t >= self.LOG_CORRIDOR_INTERVAL:
            self._last_log_t = time
            # phase_groups is a GROUP_BASED-layer field that stays empty in
            # DRL_DENSITY/coordination modes; showing it misled (and caused the
            # KeyError crash). Show each member's real per-phase green count
            # instead, from the live plan-state tracker.
            detail = " | ".join(
                f"{iid}:{(states.get(iid) or '?')[:1]}"
                f"g{sum(1 for p in getattr(self._ctrl_map.get(iid), 'phase_list', [])
                        if (_global_plan_dur(iid, p) or 0.0) > 0.0)}"
                for iid in self.inter_ids
            )
            _vprint(
                f"[CORRIDOR] t={time:.0f} group={self.name} "
                f"idle={n_idle} green={n_green} ig={n_intergreen} "
                f"bus_req={any_bus_req} | {detail}"
            )

        # ── Group sync detection ──────────────────────────────────────────────
        all_idle = n_idle == len(self._ctrl_map)
        if all_idle and not any_bus_req and time - self._last_sync_t > 5.0:
            self._last_sync_t = time
            self._sync_count += 1
            if LOG_CORRIDOR:
                _vprint(
                    f"[CORRIDOR SYNC] t={time:.0f} group={self.name} "
                    f"sync#{self._sync_count} — all {len(self._ctrl_map)} members IDLE "
                    f"(phase_groups={list(n_groups.values())})"
                )

        # ── Pass-gate hold diagnostics: periodic per-junction summary ─────────
        # Starvation signature = a junction whose held requests never fire
        # (starved >> cleared). Every 600 s, one line per junction with holds.
        try:
            if time - self._last_pass_summary >= 600.0:
                self._last_pass_summary = time
                if self._pass_hold_n:
                    _bits = []
                    for _jid in sorted(self._pass_hold_n, key=int):
                        _bits.append(
                            "%d(h%d c%d s%d held%d)" % (
                                int(_jid),
                                int(self._pass_hold_n.get(_jid, 0)),
                                int(self._pass_cleared.get(_jid, 0)),
                                int(self._pass_starved.get(_jid, 0)),
                                sum(1 for (_v, _t) in self._pass_hold_t0
                                    if _t == _jid)))
                    log_to_file(
                        f"[PASSGATE] t={time:.0f} group={self.name} summary: "
                        + " ".join(_bits))
        except Exception:
            pass

    # ------------------------------------------------------------------
    def summary(self) -> str:
        _late_n = int(self._prearm_stats.get('late_success', 0) or 0)
        _late_sum = float(self._prearm_stats.get('late_success_delay_s', 0.0) or 0.0)
        _late_avg = (_late_sum / _late_n) if _late_n > 0 else 0.0
        _fired = int(self._prearm_stats.get('fired', 0) or 0)
        _success = int(self._prearm_stats.get('success', 0) or 0)
        _succ_pct = (100.0 * _success / _fired) if _fired > 0 else 0.0
        _q = int(self._algo_diag.get('queued', 0) or 0)
        _sw_n = int(self._algo_diag.get('sw_adj_count', 0) or 0)
        _sw_sum = float(self._algo_diag.get('sw_adj_total_s', 0.0) or 0.0)
        _sw_avg = (_sw_sum / _sw_n) if _sw_n > 0 else 0.0
        _sw_max = float(self._algo_diag.get('sw_adj_max_s', 0.0) or 0.0)
        _adp_n = int(self._algo_diag.get('adaptive_fire_count', 0) or 0)
        _adp_dyn = int(self._algo_diag.get('adaptive_dynamic_count', 0) or 0)
        _adp_sum = float(self._algo_diag.get('adaptive_lead_total_s', 0.0) or 0.0)
        _adp_avg = (_adp_sum / _adp_n) if _adp_n > 0 else 0.0
        _adp_min = float(self._algo_diag.get('adaptive_lead_min_s', 1e9) or 1e9)
        _adp_max = float(self._algo_diag.get('adaptive_lead_max_s', 0.0) or 0.0)
        if _adp_n <= 0 or _adp_min >= 1e8:
            _adp_min = 0.0
        return (
            f"CorridorCoordinator group={self.name} "
            f"members={self.inter_ids} syncs={self._sync_count} "
            f"algo={COORDINATION_ALGO} "
            f"pre_arms_issued={self._pre_arm_count} "
            f"pre_arms_pending={len(self._pre_requests)} "
            f"fired={self._prearm_stats.get('fired', 0)} "
            f"success={self._prearm_stats.get('success', 0)} "
            f"success_pct={_succ_pct:.1f}% "
            f"missed={self._prearm_stats.get('missed', 0)} "
            f"expired={self._prearm_stats.get('expired', 0)} "
            f"discarded={self._prearm_stats.get('discarded', 0)} "
            f"late_success={_late_n} "
            f"late_success_delay_s={_late_sum:.1f} "
            f"avg_late_success_delay_s={_late_avg:.1f} "
            f"sw_adj={_sw_n}/{_q} sw_adj_avg_s={_sw_avg:.1f} sw_adj_max_s={_sw_max:.1f} "
            f"adp_dynamic={_adp_dyn}/{_adp_n} adp_lead_avg_s={_adp_avg:.1f} "
            f"adp_lead_min_s={_adp_min:.1f} adp_lead_max_s={_adp_max:.1f}"
        )


# module-level list populated in AAPIInit
corridor_coordinators: list = []


def _viability_update(armed, gate_on, ratio_breach, ratio_clear, sat, frac):
    """TSP viability state transition (pure function -- unit-tested).

    The viability gate stands the controller down when intervening can only
    compound congestion, instead of letting actions cascade into gridlock on
    saturated demand samples (proven on KG: MARL 163-246 and BARGAIN 95-202
    across seeds with identical trip counts -- the bad seeds are the ones
    where actions hurt cars AND buses).

    Inputs: armed (current _tsp_armed), gate_on (DCTSP_CONGESTION_GATE),
    ratio_breach (cross/bus pax-rate over threshold, already grace-aware),
    ratio_clear (ratio back under the hysteresis band), sat (max approach
    saturation 0..1+, density/jam), frac (DCTSP_CONGESTION_GATE_FRACTION).
    Returns (new_armed, changed, reason) with reason in
    gate-off/rearm/ratio/saturation/None.
    """
    try:
        if not bool(gate_on):
            return (True, not bool(armed), 'gate-off')
        if not bool(armed):
            _sat_ok = float(sat) <= float(frac) - 0.15
            if bool(ratio_clear) and _sat_ok:
                return (True, True, 'rearm')
            return (False, False, None)
        if bool(ratio_breach):
            return (False, True, 'ratio')
        try:
            _sat_hit = float(sat) >= float(frac)
        except Exception:
            _sat_hit = False
        if _sat_hit:
            return (False, True, 'saturation')
        return (True, False, None)
    except Exception:
        return (True, False, None)


# =============================================================================
# INTERSECTION CONTROLLER
# =============================================================================

class IntersectionController:

    def __init__(self, config):

        # ── static config ─────────────────────────────────────────────
        self.config  = config
        raw_id = config['IntersectionID']
        if not isinstance(raw_id, int):
            raise TypeError(
                f"IntersectionID must be int, got {type(raw_id).__name__}: {raw_id!r} "
                f"— check intersection_configs.py for unfilled placeholder IDs")
        
        self.id = raw_id
        self.TSPStrategy =0
        self.current_phase = 1
        self.stats   = stats
        self.CarOcc  = config.get('CarOcc', 1.5)
        self.BusOcc  = config.get('BusOcc', 40.0)
        self.id      = config["IntersectionID"]
        # node_id: the Aimsun-internal node ID for all topology/signal API calls.
        # Start with any explicitly configured override, defaulting to self.id.
        # _resolve_node_id() (called after section tracking is set up) will
        # auto-correct this via section topology if the configured value is wrong.
        self.node_id = config.get("AimsunNodeID", self.id)

        self.BusPhase         = config.get("BusPhase", 2)

        # BusPhaseDuration — use config value if present, otherwise discover
        # from Aimsun live plan.  Allows minimal configs with just IntersectionID.
        _bpd = config.get("BusPhaseDuration")
        if _bpd is None:
            try:
                _bpd = GetPhaseDuration(self.id, self.BusPhase, 0.0)
                if not _bpd or _bpd <= 0:
                    _bpd = 30.0
            except Exception:
                _bpd = 30.0
        self.BusPhaseDuration = float(_bpd)

        self.BusDet           = config.get("BusDet", [])
        self.main_sections = config.get('MainSections', [])
        self.side_sections = config.get('SideSections', [])
        self.call_sections = config.get(
            'call_sections',
            config.get('BusCallDetectors',
                    config.get('BusDet', []))
        )

        # These three fields are optional — minimal configs may omit them.
        # Default to empty so downstream code sees a consistent type (list/dict).
        self.UpDetList        = config.get("UpDetList", [])
        self.SignalGroupIDList = config.get("SignalGroupIDList", [])
        self.PhaseIndex       = config.get("PhaseIndex", {})
        self.VehLength        = config.get("VehLength", 4.5)
        self.DetLength        = config.get("DetLength", 5)
        self.JamDensity       = config.get("JamDensity", 200)
        self.SaturationDensity= config.get("SaturationDensity", 35)
        self.SaturationFlow   = config.get("SaturationFlow", 1800)
        self.GE_lower_bound   = config.get("GE_lower_bound", 0)
        self.GE_upper_bound   = config.get("GE_upper_bound", 20)
        self.BP_lower_bound   = config.get("BP_lower_bound", 5)
        self.BP_upper_bound   = config.get("BP_upper_bound", 60)
                # === TSP COOLDOWN (prevents spam) ===
        self.last_tsp_action_time = 0.0          # ← ADD THIS
        self.tsp_cooldown_seconds = (
            TSP_COOLDOWN_OVERRIDE_S if TSP_COOLDOWN_OVERRIDE_S is not None else 60.0)
        # 60 s default = one full cycle on most plans
        # Per-bus approach detection debounce: {bus_id: last_detection_record_t}
        # Prevents per-step recording inflating skip/detection counts.
        # Reset when a bus leaves the zone (zone_exit) or after 120 s.
        self._approach_det_t: dict = {}   # bus_id -> sim_time of last stat record
        self._detection_seen: dict = {}   # bus_id -> sim_time of last COUNTED detection
        if "DetDistance" in self.config:
            d = self.config["DetDistance"]
            if not isinstance(d, (list, tuple)) or len(d) == 0:
                self.config["DetDistance"] = [[50.0]]
            elif not isinstance(d[0], (list, tuple)):
                self.config["DetDistance"] = [d]
        else:
            self.config["DetDistance"] = [[50.0]]
        self.DetDistance = self.config["DetDistance"]
         
        self.max_iterations   = config.get("max_iterations", 20)
        self.harmony_memory_size = config.get("harmony_memory_size", 10)
        self.hmcr             = config.get("hmcr", 0.9)
        self.par              = config.get("par", 0.3)
        self.NumberOfLanes    = config.get("NumberOfLanes", 1)

        self.CarOcc = config.get('CarOcc', 1.5)
        self.BusOcc = config.get('BusOcc', 40.0)
        self.TruckOcc = config.get('TruckOcc', self.CarOcc)

        # Decision-window / intervention cadence.  TSP_CYCLE_LENGTH_OVERRIDE_S
        # (from run_config.py, e.g. the signal-sequencing X1/X2/X3 sweep) sets
        # how often the controller may re-evaluate and act; when absent, fall
        # back to the junction config's CycleTime.
        _cycle_ovr = globals().get('TSP_CYCLE_LENGTH_OVERRIDE_S')
        self.cycle_len_s = (
            float(_cycle_ovr) if _cycle_ovr is not None
            else float(config.get('CycleTime', 135)))
        # Keep the action cooldown from capping the configured window: at
        # higher intervention frequencies (window < 60 s) the cooldown must not
        # throttle the rate below what the window allows.
        self.tsp_cooldown_seconds = min(self.tsp_cooldown_seconds,
                                        self.cycle_len_s)
        # ── Hard phase-sequencing cap ────────────────────────────────────
        # PHASE_SEQ_MAX_PER_CYCLE (run_config.py) caps how many SEQ (phase
        # rotation) interventions may fire within one signal cycle, independent
        # of the decision window above.  The count window is the junction's own
        # CycleTime so the cap is measured per 135 s cycle, not per window.
        _seq_max_ovr = globals().get('PHASE_SEQ_MAX_PER_CYCLE')
        self._seq_max_per_cycle = (
            int(_seq_max_ovr) if _seq_max_ovr not in (None, 0)
            else 0)
        self._seq_window_start = -1.0
        self._seq_window_count = 0
        

        # ── URTSP config — read from config dict or use defaults ──────
        u = URTSP_DEFAULTS
        self.urtsp_ge_extension      = min(config.get("GE_extension", u["GE_extension"]), MAX_GE_EXTENSION_S)
        self.urtsp_ins_min           = config.get("insertion_min_duration",  u["insertion_min_duration"])
        self.urtsp_ins_max           = config.get("insertion_max_duration",  u["insertion_max_duration"])
        self.urtsp_cycle_length      = config.get("cycle_length",            u["cycle_length"])
        self.urtsp_detection_window  = config.get("detection_window_m",      u["detection_window_m"])
        self.urtsp_pt_line_filter    = config.get("priority_pt_line_ids",    u["priority_pt_line_ids"])

        # call detectors: prefer dedicated URTSP list, else use BusDet
        self.urtsp_call_det_ids = config.get("BusCallDetectors", self.BusDet)
        self.urtsp_exit_det_ids = config.get("BusExitDetectors", [])

        # ── resolve detector geometry once at init ────────────────────
        self._urtsp_call_geometry = {}   # {det_id: (section_id, ini_pos, fin_pos)}
        self._urtsp_exit_geometry = {}
        self._resolve_urtsp_geometry()

        # ── URTSP runtime state (instance variables — no globals) ─────
        self._urtsp_flag               = 0      # 0=idle 1=extension 2=insertion
        self._urtsp_prev_phase         = -1
        self._urtsp_prev_phase_elapsed = -1.0
        self._urtsp_insertion_start    = -1.0
        self._urtsp_granted_this_cycle = False
        self._urtsp_cycle_reset_time   = -1.0
        self._urtsp_served_veh_ids     = set()
        self._urtsp_active_veh_id      = -1
        self._urtsp_bus_phase_nominal  = GetPhaseDuration(self.node_id, self.BusPhase, 0.0)
        # end-of-run counters
        self._urtsp_n_detections   = 0
        self._urtsp_n_extensions   = 0
        self._urtsp_n_insertions   = 0
        self._urtsp_n_exit_clears  = 0
        self._urtsp_n_cap_clears   = 0

        # ── GroupBasedController sub-controller (GROUP_BASED modes only) ──
        # Always None for HARMONY / URTSP / REWARD_TSP / NORMAL modes.
        # Set by GroupBasedController.__init__ when CONTROL_MODE is group-based.
        self.gb = None

        # ── Corridor coordination back-reference (HARMONY mode) ──────────
        # Set by CorridorCoordinator.__init__ when CONTROL_MODE == "HARMONY".
        # None when this intersection is not part of a coordinated group.
        self._corridor_coord    = None
        # Pre-arm request fired by coordinator: (veh_id, eta_t, issued_t).
        # When set, check_bus_priority applies TSP immediately without waiting
        # for local detector presence (Kalman ETA replaces BusSpeed-based ETA).
        self._harmony_prearm    = None

        # ── general dynamic state ─────────────────────────────────────
        self.prev_total_delay   = 0.0
        self.TSPActiveTime      = 0
        # Viability gate: armed until saturation/cross-pressure trips it
        # (see _viability_update; re-armed per run in AAPIInit).
        self._tsp_armed         = True
        self.flag               = 0      # used by HARMONY / NORMAL paths
        self.previous_phase     = None
        self.last_detected_bus_id = -1
        self.incoming_sections  = []
        self._initialize_section_tracking()
        self._resolve_node_id()   # verify/auto-fix node_id after sections are known
        self.phase_list         = []

        num_phases = ECIGetNumberPhases(self.id)
        self.phase_list = list(range(1, num_phases + 1))

        # ── Auto-discover BusPhase when config doesn't provide one ──────────
        # config.get("BusPhase", 2) is just a default guess.  Scan the Aimsun
        # signal plan at runtime to find which phase actually serves the
        # corridor (the phase with the longest green duration, since the main
        # corridor phase typically gets the most green time in a fixed-time
        # plan).  This mirrors GroupBasedController's _bus_aimsun_phase
        # discovery in intersection_controller_experimental.py:4037-4056.
        if not config.get("BusPhase"):
            _best_ph = self.BusPhase
            _best_dur = 0.0
            for _ph in self.phase_list:
                try:
                    _dur = float(GetPhaseDuration(self.id, _ph, 0.0) or 0.0)
                except Exception:
                    _dur = 0.0
                if _dur > _best_dur:
                    _best_dur = _dur
                    _best_ph = _ph
            if _best_ph != self.BusPhase:
                if LOG_INIT:
                    AKIPrintString(
                        f"[INIT] Inter {self.id} auto-discovered BusPhase={_best_ph} "
                        f"(duration={_best_dur:.0f}s, was default {self.BusPhase})")
                self.BusPhase = int(_best_ph)
                # Re-discover BusPhaseDuration for the correct phase
                try:
                    _bpd_new = GetPhaseDuration(self.id, self.BusPhase, 0.0)
                    if _bpd_new and _bpd_new > 0:
                        self.BusPhaseDuration = float(_bpd_new)
                except Exception:
                    pass

        # ── Auto-discover CycleTime when config doesn't provide one ─────────
        if not config.get('CycleTime') and not config.get('cycle_length'):
            _ct = sum(
                float(GetPhaseDuration(self.id, _ph, 0.0) or 0.0)
                for _ph in self.phase_list)
            if _ct > 0:
                self.config['CycleTime'] = _ct
                if LOG_INIT:
                    AKIPrintString(
                        f"[INIT] Inter {self.id} auto-discovered CycleTime={_ct:.0f}s")

        # Re-derive the fallback cycle length from the (possibly auto-discovered)
        # config CycleTime unless a run_config override is in force.
        if globals().get('TSP_CYCLE_LENGTH_OVERRIDE_S') is None:
            self.cycle_len_s = float(self.config.get('CycleTime', 135))
            self.tsp_cooldown_seconds = min(self.tsp_cooldown_seconds,
                                            self.cycle_len_s)

        stats_car_pos = getattr(self.stats, '_car_pos', -1)
        stats_bus_pos = getattr(self.stats, '_bus_pos', -1)
        scan_car_pos, scan_bus_pos, scan_truck_pos = _scan_named_vehicle_type_positions()

        self.bus_type_pos = stats_bus_pos if stats_bus_pos > 0 else scan_bus_pos
        if self.bus_type_pos <= 0:
            cfg_bus_pos = safe_float(config.get('BUS_TYPE_POS', -1), -1.0)
            self.bus_type_pos = int(cfg_bus_pos) if cfg_bus_pos > 0 else -1

        self.car_type_pos = stats_car_pos if stats_car_pos > 0 else scan_car_pos
        if self.car_type_pos <= 0:
            self.car_type_pos = _choose_car_type_pos(
                self.bus_type_pos,
                scan_truck_pos if scan_truck_pos > 0 else getattr(self.stats, '_truck_pos', -1),
                preferred_pos=self.car_type_pos)

        if LOG_INIT: AKIPrintString(f"[INIT] Inter {self.id} | car_type_pos={self.car_type_pos} bus_type_pos={self.bus_type_pos}")
        self.print_config_summary()
        if LOG_INIT: AKIPrintString(f"[INIT] Phase list: {self.phase_list}")

        self.initialize_state()
        # Warmup: suppress TSP for the first two signal cycles so the
        # network can settle before any priority decisions are made.
        _warmup = 2.0 * float(self.cycle_len_s)
        self.TSPActiveTime = _warmup

        initial_state = self.build_state()
        state_dim  = len(initial_state)
        action_dim = len(self.UpDetList)
        # ── RL agent — only load when mode is RL ──────────────────────
        self.rl_agent   = None
        self.TRAIN_MODE = False
        if CONTROL_MODE == 'RL':
            try:
                from rl_agent import RLIntersectionAgent
                self.rl_agent   = RLIntersectionAgent(state_dim, action_dim, algorithm='DQN')
                self.TRAIN_MODE = True
                self.rl_agent.load_model("trained_model.pth")
                if LOG_INIT: AKIPrintString(f"[RL] Agent loaded for intersection {self.id}")
            except Exception as e:
                _vprint(f"[RL] WARNING: Could not load RL agent: {e}")

        if LOG_URTSP: AKIPrintString(f"[URTSP] Intersection {self.id} ready | "
                       f"mode={CONTROL_MODE} | "
                       f"call_dets={self.urtsp_call_det_ids} | "
                       f"exit_dets={self.urtsp_exit_det_ids}")

    # =========================================================================
    # URTSP — GEOMETRY RESOLUTION
    # =========================================================================


    
    
    def _resolve_urtsp_geometry(self):
        """Cache section_id and positions for call and exit detectors."""
        for det_id in self.urtsp_call_det_ids:
            props = AKIDetGetPropertiesDetectorById(det_id)
            if props.report < 0:
                if LOG_URTSP: AKIPrintString(f"[URTSP] WARNING: call det {det_id} not found")
                continue
            self._urtsp_call_geometry[det_id] = (
                props.IdSection, props.InitialPosition, props.FinalPosition)
            if LOG_URTSP: AKIPrintString(f"[URTSP] call det={det_id} "
                           f"section={props.IdSection} "
                           f"pos=[{props.InitialPosition:.1f},{props.FinalPosition:.1f}]m")

        for det_id in self.urtsp_exit_det_ids:
            props = AKIDetGetPropertiesDetectorById(det_id)
            if props.report < 0:
                if LOG_URTSP: AKIPrintString(f"[URTSP] WARNING: exit det {det_id} not found")
                continue
            self._urtsp_exit_geometry[det_id] = (
                props.IdSection, props.InitialPosition, props.FinalPosition)
            if LOG_URTSP: AKIPrintString(f"[URTSP] exit det={det_id} "
                           f"section={props.IdSection} "
                           f"pos=[{props.InitialPosition:.1f},{props.FinalPosition:.1f}]m")

        # read nominal bus-phase duration from background plan
        self._urtsp_bus_phase_nominal = GetPhaseDuration(
            self.id, self.BusPhase, 0.0)
        if LOG_URTSP: AKIPrintString(f"[URTSP] bus phase nominal = {self._urtsp_bus_phase_nominal:.1f}s")

    
    
    def _resolve_urtsp_geometry(self):
        for det_id in self.urtsp_call_det_ids:
            props = AKIDetGetPropertiesDetectorById(det_id)
            if props.report >= 0:
                self._urtsp_call_geometry[det_id] = (props.IdSection, props.InitialPosition, props.FinalPosition)

        for det_id in self.urtsp_exit_det_ids:
            props = AKIDetGetPropertiesDetectorById(det_id)
            if props.report >= 0:
                self._urtsp_exit_geometry[det_id] = (props.IdSection, props.InitialPosition, props.FinalPosition)

        self._urtsp_bus_phase_nominal = GetPhaseDuration(self.node_id, self.BusPhase, 0.0)
    
    # =========================================================================
    # URTSP — PT VEHICLE HELPERS
    # =========================================================================

    def _get_pt_vehicles(self):
        """
        Return list of (line_id, inf) for PT vehicles AND injected buses.
        Primary: scan registered PT lines.
        Fallback: scan bus vehicles directly on call sections (catches
                  injected buses not registered as PT line vehicles).
        """
        result = []
        seen   = set()
        allowed = set(self.urtsp_pt_line_filter) if self.urtsp_pt_line_filter else None

        # ── Primary: registered PT lines ─────────────────────────────
        for li in range(AKIPTGetNumberLines()):
            line_id = AKIPTGetIdLine(li)
            if allowed is not None and line_id not in allowed:
                continue
            for vi in range(AKIGetNbVehiclesFollowingPTLine(line_id)):
                veh_id = AKIGetVehicleFollowingPTLine(line_id, vi)
                inf    = AKIPTVehGetInf(veh_id)
                if inf.report >= 0:
                    result.append((line_id, inf))
                    seen.add(veh_id)

        # ── Fallback: scan bus vehicles directly on call sections ─────
        for det_id, (sec_id, _, _) in self._urtsp_call_geometry.items():
            n = AKIVehStateGetNbVehiclesSection(sec_id, True)
            for i in range(n):
                inf = AKIVehStateGetVehicleInfSection(sec_id, i)
                if inf.idVeh in seen:
                    continue
                if inf.type != self.bus_type_pos:
                    continue
                result.append((-1, inf))
                seen.add(inf.idVeh)

        return result

    def _scan_urtsp_call(self, pt_vehicles):
        """
        Scan call detector zones for an unserved eligible bus.
        Scans from position 0 to fin_pos + window to catch approaching buses.
        Returns (veh_id, line_id, det_id, pos) or (-1,-1,-1,-1.0).
        """
        w = self.urtsp_detection_window
        for det_id, (sec_id, ini_pos, fin_pos) in self._urtsp_call_geometry.items():
            # Widen UPSTREAM only — fin_pos is the intended downstream boundary.
            # Matches TSP_single_intersection: detect_ini widened by window,
            # detect_fin preserved as fin_pos so buses that already passed are excluded.
            detect_ini = max(0.0, fin_pos - w)
            detect_fin = fin_pos
            for line_id, inf in pt_vehicles:
                if inf.idSection != sec_id:
                    continue
                if not (detect_ini <= inf.CurrentPos <= detect_fin):
                    continue
                veh_id = inf.idVeh
                pos    = inf.CurrentPos
                if veh_id in self._urtsp_served_veh_ids:
                    pass
                elif self._urtsp_flag != 0:
                    _vprint(
                        f"[URTSP] SKIP veh={veh_id} line={line_id} "
                        f"pos={pos:.1f}m reason=tsp_active(flag={self._urtsp_flag})")
                    self._urtsp_served_veh_ids.add(veh_id)
                elif self._urtsp_granted_this_cycle:
                    _vprint(
                        f"[URTSP] SKIP veh={veh_id} line={line_id} "
                        f"pos={pos:.1f}m reason=already_granted_this_cycle")
                    self._urtsp_served_veh_ids.add(veh_id)
                else:
                    _vprint(
                        f"[URTSP] BUS IN ZONE | veh={veh_id} line={line_id} "
                        f"sec={sec_id} pos={pos:.1f}m zone=[{detect_ini:.1f},{detect_fin:.1f}]m")
                    return veh_id, line_id, det_id, pos
        return -1, -1, -1, -1.0

    def _check_urtsp_exit(self, veh_id, pt_vehicles):
        for _, (sec_id, _, fin_pos) in self._urtsp_exit_geometry.items():
            detect_ini = 0.0
            detect_fin = fin_pos + self.urtsp_detection_window
            for _, inf in pt_vehicles:
                if inf.idVeh == veh_id and inf.idSection == sec_id:
                    if detect_ini <= inf.CurrentPos <= detect_fin:
                        return True
        return False

    def _bus_on_call_section(self, veh_id, pt_vehicles):
        """Return True if veh_id is still on any call detector section."""
        for _, (sec_id, _, _) in self._urtsp_call_geometry.items():
            for _, inf in pt_vehicles:
                if inf.idVeh == veh_id and inf.idSection == sec_id:
                    return True
        return False

    # =========================================================================
    # URTSP — MAIN STATE MACHINE  (replaces run_normal / check_bus_priority)
    # =========================================================================

    def run_urtsp(self, time, timeSta, acycle):
        # ── Diagnostic every 300s: confirm buses are on call sections ──
        if int(time) % 300 == 0 and int(time) != getattr(self, '_last_diag_t', -1):
            self._last_diag_t = int(time)
            pt_count = len(self._get_pt_vehicles())
            for det_id, (sec_id, ini, fin) in self._urtsp_call_geometry.items():
                n = AKIVehStateGetNbVehiclesSection(sec_id, True)
                _vprint(
                    f"[URTSP] DIAG t={time:.0f}s inter={self.id} "
                    f"det={det_id} sec={sec_id} "
                    f"veh_on_section={n} pt_vehicles={pt_count}")

        current_phase  = ECIGetCurrentPhase(self.node_id)
        phase_start    = ECIGetStartingTimePhase(self.node_id)
        phase_elapsed  = time - phase_start
        phase_duration = GetPhaseDuration(self.node_id, current_phase, timeSta)

        pt_vehicles = self._get_pt_vehicles()

        # ── per-cycle grant reset ─────────────────────────────────────
        if self._urtsp_granted_this_cycle and time >= self._urtsp_cycle_reset_time:
            if LOG_URTSP: AKIPrintString(f"[URTSP] cycle grant reset at t={time:.1f}s")
            self._urtsp_granted_this_cycle = False

        # ── expire served_veh_ids ─────────────────────────────────────
        self._urtsp_served_veh_ids = {
            vid for vid in self._urtsp_served_veh_ids
            if self._bus_on_call_section(vid, pt_vehicles)
        }

        # ── FLAG 1: GREEN EXTENSION active ────────────────────────────
        if self._urtsp_flag == 1:
            if current_phase != self.BusPhase:
                self.reset_bus_color(self._urtsp_active_veh_id)
                if LOG_URTSP: AKIPrintString(f"[URTSP] EXTENSION ENDED | t={time:.1f}s "
                               f"resumed phase={current_phase}")
                self._urtsp_flag           = 0
                self._urtsp_active_veh_id  = -1
                _release_focus(time, "urtsp_ge_done")
            return

        # ── FLAG 2: PHASE INSERTION active ───────────────────────────
        if self._urtsp_flag == 2:
            insertion_elapsed = time - self._urtsp_insertion_start
            min_ok      = insertion_elapsed >= self.urtsp_ins_min
            bus_cleared = min_ok and self._check_urtsp_exit(
                self._urtsp_active_veh_id, pt_vehicles)
            cap_reached = insertion_elapsed >= self.urtsp_ins_max

            if bus_cleared or cap_reached:
                self.reset_bus_color(self._urtsp_active_veh_id)
                reason          = "exit_detector" if bus_cleared else "cap"
                restore_elapsed = self._urtsp_prev_phase_elapsed if bus_cleared else 0.0
                _vprint(
                    f"[URTSP] INSERTION ENDED | t={time:.1f}s | reason={reason} "
                    f"duration={insertion_elapsed:.1f}s | "
                    f"restoring phase={self._urtsp_prev_phase} elapsed={restore_elapsed:.1f}s")
                ECIChangeDirectPhase(self.node_id, self._urtsp_prev_phase,
                                     timeSta, time, acycle, restore_elapsed)
                if bus_cleared:
                    self._urtsp_n_exit_clears += 1
                    self.stats.record_tsp_event(self.id, 'exit_clear')
                else:
                    self._urtsp_n_cap_clears  += 1
                    self.stats.record_tsp_event(self.id, 'cap_clear')
                self._urtsp_flag               = 0
                self._urtsp_prev_phase         = -1
                self._urtsp_prev_phase_elapsed = -1.0
                self._urtsp_insertion_start    = -1.0
                self._urtsp_active_veh_id      = -1
                _release_focus(time, "urtsp_ins_done")
            return

        # ── IDLE: scan call detectors ─────────────────────────────────
        veh_id, line_id, det_id, pos = self._scan_urtsp_call(pt_vehicles)
        if veh_id < 0:
            return

        # ── Global bus focus gate ─────────────────────────────────────
        if _is_focus_blocked(veh_id, self.id, time):
            if LOG_URTSP:
                _vprint(
                    f"[BUS_FOCUS] t={time:.1f} inter={self.id} "
                    f"v={veh_id} SUPPRESSED — focus bus={_focus_bus_id}")
            _mark_detection_point(self.id, veh_id, 0.0, 0.0,
                                  time, "focus_suppress")
            return

        self._urtsp_n_detections        += 1
        self._urtsp_served_veh_ids.add(veh_id)
        self._urtsp_granted_this_cycle   = True
        self._urtsp_cycle_reset_time     = time + self.urtsp_cycle_length
        self._record_detection(time)

        remaining = max(0.0, phase_duration - phase_elapsed)
        _vprint(
            f"[URTSP] DETECTED | t={time:.1f}s | veh={veh_id} line={line_id} "
            f"det={det_id} pos={pos:.1f}m | phase={current_phase} "
            f"elapsed={phase_elapsed:.1f}s dur={phase_duration:.1f}s rem={remaining:.1f}s")

        # ── Strategy 1: GREEN EXTENSION ───────────────────────────────
        if current_phase == self.BusPhase:
            new_dur = self._urtsp_bus_phase_nominal + self.urtsp_ge_extension
            _vprint(
                f"[URTSP] GREEN EXTENSION | new_dur={new_dur:.1f}s "
                f"(nominal={self._urtsp_bus_phase_nominal:.1f}s "
                f"+ {self.urtsp_ge_extension:.0f}s)")
            ECIChangeTimingPhase(self.node_id, current_phase, new_dur, timeSta)
            self._urtsp_active_veh_id = veh_id
            self._urtsp_flag          = 1
            self._urtsp_n_extensions += 1
            self.highlight_bus(veh_id)   # ✅ ADD THIS
            if veh_id and veh_id > 0:
                _acquire_focus(veh_id, self.id, time)
            self.stats.record_tsp_event(self.id, 'extension')

        # ── Strategy 2: PHASE INSERTION ───────────────────────────────
        else:
            _vprint(
                f"[URTSP] PHASE INSERTION | inserting phase={self.BusPhase} "
                f"interrupted phase={current_phase} at {phase_elapsed:.1f}s")
            self._urtsp_prev_phase         = current_phase
            self._urtsp_prev_phase_elapsed = phase_elapsed
            self._urtsp_insertion_start    = time
            self._urtsp_active_veh_id      = veh_id
            ECIChangeDirectPhase(self.node_id, self.BusPhase,
                                 timeSta, time, acycle, 0)
            self._urtsp_flag            = 2
            self._urtsp_n_insertions   += 1
            self.highlight_bus(veh_id)
            if veh_id and veh_id > 0:
                _acquire_focus(veh_id, self.id, time)
            self.stats.record_tsp_event(self.id, 'insertion')

    def get_urtsp_summary(self):
        """Return a summary string for AAPIFinish."""
        return (
            f"[URTSP] intersection={self.id} | "
            f"detections={self._urtsp_n_detections} | "
            f"extensions={self._urtsp_n_extensions} | "
            f"insertions={self._urtsp_n_insertions} | "
            f"exit_det_clears={self._urtsp_n_exit_clears} | "
            f"cap_clears={self._urtsp_n_cap_clears}"
        )

    # =========================================================================
    # EXISTING METHODS — unchanged from original
    # =========================================================================

    def initialize_state(self):

        # n_phases must cover every detector group in UpDetList AND every
        # PhaseIndex value used in the config.  When NumberOfPhases is absent
        # (e.g. kg configs that omit it), derive the minimum required size so
        # UpDetCountList[i] and friends don't raise IndexError at i=1+.
        _cfg_n_phases = self.config.get("NumberOfPhases", None)
        _det_groups   = max(len(self.UpDetList), 1)
        _phase_idx_max = (max(self.PhaseIndex.values()) + 1
                          if self.PhaseIndex else 1)
        if _cfg_n_phases is not None:
            n_phases = max(int(_cfg_n_phases), _det_groups, _phase_idx_max, len(self.phase_list), 1)
        else:
            n_phases = max(_det_groups, _phase_idx_max, len(self.phase_list), 1)

        n_lanes  = max(self.NumberOfLanes, 1)
        n_busdet = max(len(self.BusDet), 1)
        # Queue arrays must be wide enough for all detectors in the largest UpDetList group.
        # After NB+SB merge a group may have more detectors than n_lanes.
        _max_group = max((len(g) for g in self.UpDetList if g), default=1)
        n_cols = max(n_lanes, _max_group)
        
        
        self.BusPresence           = np.zeros((1, n_busdet))
        self.BusSpeed              = np.zeros((1, n_busdet))

        self.UpDetCountList        = np.zeros((n_phases, n_cols))
        self.UpDetOccList          = np.zeros((n_phases, n_cols))
        self.UpAveOccList          = np.zeros((n_phases, n_cols))
        self.RedStartTimeList      = np.zeros((n_phases, n_cols))
        self.GreenStartTimeList    = np.zeros((n_phases, n_cols))
        self.RedDurationList       = np.zeros((n_phases, n_cols))
        self.GreenDurationList     = np.zeros((n_phases, n_cols))
        self.UpFlowList            = np.zeros((n_phases, n_cols))
        self.UpDenList             = np.zeros((n_phases, n_cols))
        self.ShockwaveSpeed1List   = np.zeros((n_phases, n_cols))
        self.ShockwaveSpeed2List   = np.zeros((n_phases, n_cols))
        self.ShockwaveSpeed3List   = np.zeros((n_phases, n_cols))
        self.ShockwaveSpeed4List   = np.zeros((n_phases, n_cols))
        self.MaxQueueLength        = np.zeros((n_phases, n_cols))
        self.MaxQueueLengthTime    = np.zeros((n_phases, n_cols))
        self.MinQueueLength        = np.zeros((n_phases, n_cols))
        self.MinQueueLengthTime    = np.zeros((n_phases, n_cols))
        self.QueueDissTime         = np.zeros((n_phases, n_cols))
        self.NextRedStartTime      = np.zeros((n_phases, n_cols))

        # Harmony Search arrays
        self.HSRedStartTimeList    = np.zeros((n_phases, n_cols))
        self.HSRedDurationList     = np.zeros((n_phases, n_cols))
        self.HSGreenStartTimeList  = np.zeros((n_phases, n_cols))
        self.HSGreenDurationList   = np.zeros((n_phases, n_cols))
        self.HSNextRedStartTime    = np.zeros((n_phases, n_cols))
        self.HSUpFlowList          = np.zeros((n_phases, n_cols))
        self.HSUpDenList           = np.zeros((n_phases, n_cols))
        self.HSShockwaveSpeed1List = np.zeros((n_phases, n_cols))
        self.HSShockwaveSpeed3List = np.zeros((n_phases, n_cols))
        self.HSMaxQueueLength      = np.zeros((n_phases, n_cols))
        self.HSMaxQueueLengthTime  = np.zeros((n_phases, n_cols))
        self.HSMinQueueLength      = np.zeros((n_phases, n_cols))

        self.BusDelay              = np.zeros((n_phases, n_cols))
        self.OtherDelay            = np.zeros((n_phases, n_cols))
        self.TotalVeh              = np.zeros((n_phases, n_cols))

        side_secs = self._get_side_sections()
        n_side = max(len(side_secs), 1)
        self.SideUpFlowList        = np.zeros(n_side)
        self.SideUpDenList         = np.zeros(n_side)
        self.SideShockwaveSpeed1   = np.zeros(n_side)
        self.SideShockwaveSpeed3   = np.zeros(n_side)
        self._side_red_start       = np.zeros(n_side)
        self._side_last_phase      = ECIGetCurrentPhase(self.node_id)

        # Persistent per-vehicle delay tracking for side sections.
        # Key: (section_id, vehicle_id); value: last measured delay (s).
        # Initialised here so collect_delay never has to check hasattr.
        self._side_stoptime_prev: dict = {}

        # Profile all approach sections once at startup (geometry + ff time).
        try:
            self._profile_sections()
        except Exception:
            pass

        # Other state variables
        self.BusJoinQueueTime      = np.zeros((n_phases, n_cols))
        self.BusStoplineTime       = np.zeros((n_phases, n_cols))
        self.BusPhaseMinDuration   = np.zeros((n_phases, n_cols))
        self.HSQueueDissTime       = np.zeros((n_phases, n_cols))

        self.step_delay            = 0.0
        self.TSPActiveTime         = 0.0
        self.flag                  = 0
        self.previous_phase        = ECIGetCurrentPhase(self.node_id)
        self.last_detected_bus_id  = -1

        # Sentinel values
        self.BusPhaseEndTime       = 1e9
        self.TimeToTerminateBusPhase = 1e9

        # ── Cycle-recovery state (GE only) ────────────────────────────────────
        # When a green extension of X seconds is granted the cycle is "in debt".
        # After the GE ends, remaining phases are shortened proportionally so the
        # cycle re-aligns with its nominal start offset as quickly as possible.
        # _ge_debt_s  : seconds still owed (decremented as phases absorb it)
        # _ge_opt_GE  : the extension that was granted (for logging)
        self._ge_debt_s  = 0.0
        self._ge_opt_GE  = 0.0
        # Recovered-cycle-plan state (multi-cycle recovery; RECOVERY_MAX_CYCLES>1).
        self._recovery_cycles_used = 0
        self._recovery_continued_this_cycle = False

        # _nominal_phase_durations: lazily-populated on first GE.
        # Stores the ORIGINAL plan durations so cycle recovery always trims
        # relative to the base (not relative to a previously-trimmed value).
        # Without this, repeated GEs compound trimming → permanent short greens.
        self._nominal_phase_durations: dict = {}

        # _phases_to_restore: set after trimming — {phase: nominal_dur}.
        # Restored to their nominals when BusPhase next becomes current
        # (i.e. start of the next signal cycle), ensuring trimmed durations
        # only apply for ONE cycle.
        self._phases_to_restore: dict = {}
        self._restore_fired_this_cycle: bool = False

        if LOG_INIT: AKIPrintString(f"[INIT] Inter {self.id} | phases={n_phases} | lanes={n_lanes} | busdets={n_busdet} | arrays initialized safely")

    def _get_inter_state(self):
        inter_map = getattr(self.stats, '_inter', None)
        if inter_map is None:
            return None
        return inter_map.get(self.id)

    def _normalize_sections(self, sections):
        if sections is None:
            return []

        if isinstance(sections, np.ndarray):
            sections = sections.tolist()
        elif isinstance(sections, str):
            sections = sections.replace(';', ',').split(',')
        elif isinstance(sections, (int, float, np.integer, np.floating)):
            sections = [sections]
        else:
            try:
                sections = list(sections)
            except TypeError:
                sections = [sections]

        normalized = []
        seen = set()
        for sec in sections:
            sec_val = safe_float(sec, default=-1.0)
            if sec_val <= 0.0:
                continue
            sec_id = int(sec_val)
            if sec_id not in seen:
                seen.add(sec_id)
                normalized.append(sec_id)
        return normalized

    def _derive_sections_from_detectors(self):
        sections = []
        seen = set()
        invalid_dets = []
        valid_dets = []
        for phase in self.UpDetList:
            for det_id in phase:
                det_info = AKIDetGetPropertiesDetectorById(det_id)
                if getattr(det_info, 'report', -1) < 0:
                    invalid_dets.append(det_id)
                    continue
                valid_dets.append(det_id)
                sec_id = int(getattr(det_info, 'IdSection', 0) or 0)
                if sec_id > 0 and sec_id not in seen:
                    seen.add(sec_id)
                    sections.append(sec_id)
        if invalid_dets:
            # Scan ALL detectors in the model and report any whose IDs are
            # adjacent (±2000) to the invalid IDs — helpful for finding the real IDs.
            _nearby = {}
            _all_det_sec = {}   # det_id → section_id for every valid detector in model
            try:
                n_all = AKIDetGetNumberDetectors()
                for _di in range(n_all):
                    _did = AKIDetGetIdDetector(_di)
                    _p = AKIDetGetPropertiesDetectorById(_did)
                    if getattr(_p, 'report', -1) >= 0:
                        _dsec = getattr(_p, 'IdSection', -1)
                        _all_det_sec[_did] = _dsec
                        for _bad in invalid_dets:
                            if abs(_did - _bad) <= 2000:
                                _nearby[_did] = _dsec
            except Exception:
                pass

            # Junction-based scan: find detectors on turn-origin sections that are
            # NOT in the valid-detector section list — identifies missing approach dets
            _junction_cands = {}
            if True:   # always run: even partial valid_dets can miss an approach
                try:
                    n_turns = AKIInfNetGetNbTurnsInNode(self.node_id)
                    _turn_orig_secs = set()
                    for _ti in range(n_turns):
                        try:
                            _tsec = AKIInfNetGetOriginSectionInTurn(self.node_id, _ti)
                            if _tsec > 0:
                                _turn_orig_secs.add(_tsec)
                        except Exception:
                            pass
                    _missing_secs = _turn_orig_secs - set(sections)
                    for _did, _dsec in _all_det_sec.items():
                        if _dsec in _missing_secs:
                            _junction_cands[_did] = _dsec
                except Exception:
                    pass

            log_to_file(
                f"[INIT_WARN] inter={self.id} "
                f"{len(invalid_dets)} INVALID detector IDs (report<0): {invalid_dets} — "
                f"buses on their sections will NOT be detected. "
                f"Valid detectors: {valid_dets} → sections: {sections}. "
                f"Nearby valid IDs (±2000): {_nearby}. "
                f"Junction-approach candidates: {_junction_cands}")
        return sections

    def _resolve_node_id(self):
        """
        Verify self.node_id is a valid Aimsun node ID by calling
        AKIInfNetGetNbTurnsInNode.  If it returns a negative error code,
        auto-discover the real node ID by querying idNodeTo on each known
        approach section.  Logs the result so the operator can update
        intersection_configs.py with the correct AimsunNodeID.
        """
        test = AKIInfNetGetNbTurnsInNode(self.node_id)
        if test >= 0:
            # Already valid — nothing to do
            return

        # node_id is wrong: find the real node from approach sections
        if LOG_NODE_ID:
            log_to_file(
                f"[NODE_ID] inter={self.id} node_id={self.node_id} invalid "
                f"(AKIInfNetGetNbTurnsInNode returned {test}) — auto-discovering ..."
            )
        candidates = {}   # node_id → count of sections pointing to it
        for sec_id in self.incoming_sections:
            try:
                si = AKIInfNetGetSectionANGInf(sec_id)
                if si.report >= 0 and si.idNodeTo > 0:
                    candidates[si.idNodeTo] = candidates.get(si.idNodeTo, 0) + 1
            except Exception:
                pass

        if candidates:
            best = max(candidates, key=candidates.get)
            # NODE_ID resolution is always logged — critical config hint
            log_to_file(
                f"[NODE_ID] inter={self.id} auto-resolved node_id "
                f"{self.node_id} → {best}  "
                f"(votes: {candidates})  "
                f"*** add AimsunNodeID: {best} to intersection_configs.py ***"
            )
            self.node_id = best
        else:
            # Always log failure — it means signal control is broken
            log_to_file(
                f"[NODE_ID] inter={self.id} could not auto-resolve node_id — "
                f"all approach sections returned report<0 (transit links). "
                f"Signal control and topology calls will be broken for this junction."
            )

    def _initialize_section_tracking(self):
        inter_state = self._get_inter_state()  # may be None if stats not yet registered
        detector_secs = self._derive_sections_from_detectors()

        main_secs = self._normalize_sections(self.config.get('MainSections', []))
        if not main_secs and inter_state is not None:
            main_secs = self._normalize_sections(inter_state.get('main_sections', []))
        for sec_id in detector_secs:
            if sec_id not in main_secs:
                main_secs.append(sec_id)

        # Validate: keep only ids that are REAL simulated sections. Stats-layer
        # topology used to leak upstream NODE ids in as "sections" (measured on
        # Logan: inter 17498 mains=[17963,20824,22370], all AKI report -4002 —
        # 17963 is the neighbouring junction), which silently zeroed this
        # junction's main-approach flow/queue reads for the whole run. Dropping
        # them here lets the AAPI topology fallback below repopulate with real
        # turn-origin sections.
        _valid_mains = []
        for _sid in main_secs:
            try:
                _si = AKIInfNetGetSectionANGInf(int(_sid))
                if getattr(_si, 'report', -1) >= 0 and float(
                        getattr(_si, 'length', 0.0) or 0.0) > 0.0:
                    _valid_mains.append(_sid)
            except Exception:
                continue
        if len(_valid_mains) < len(main_secs):
            log_to_file(
                f"[SECTION] inter={self.id} dropped "
                f"{len(main_secs) - len(_valid_mains)} non-section id(s) from "
                f"mains {main_secs} -> {_valid_mains}", force=True)
        main_secs = _valid_mains

        side_secs = self._normalize_sections(self.config.get('SideSections', []))
        if not side_secs and inter_state is not None:
            side_secs = self._normalize_sections(inter_state.get('side_sections', []))

        # Topology fallback: when ALL configured detectors are invalid (or BusDet is empty),
        # detector_secs and main_secs are both empty → detect_bus and collect_delay find
        # no sections to scan.  Fall back to every turn-origin section at this junction so
        # the controller can still detect buses and measure delay without physical detectors.
        self._topo_fallback_main = False  # True = main_secs came from topology, not detectors
        if not main_secs:
            try:
                _topo_seen = set()
                _topo_secs = []
                n_turns = AKIInfNetGetNbTurnsInNode(self.node_id)
                for _ti in range(n_turns):
                    try:
                        _tsec = AKIInfNetGetOriginSectionInTurn(self.node_id, _ti)
                        if _tsec > 0 and _tsec not in _topo_seen:
                            _topo_seen.add(_tsec)
                            _topo_secs.append(_tsec)
                    except Exception:
                        pass
                if _topo_secs:
                    main_secs = _topo_secs
                    self._topo_fallback_main = True
                    if LOG_SECTION:
                        log_to_file(
                            f"[SECTION] inter={self.id} no valid detector sections — "
                            f"topology fallback: incoming_sections={main_secs}")
            except Exception:
                pass

        self.incoming_sections = list(main_secs)
        self.config['MainSections'] = list(main_secs)
        self.config['SideSections'] = list(side_secs)

        if inter_state is not None:
            inter_state['main_sections'] = list(main_secs)
            inter_state['side_sections'] = list(side_secs)

    def _validate_section_ids(self, sec_ids):
        """Return only section IDs that exist in this Aimsun model."""
        valid = []
        for sid in sec_ids:
            try:
                result = AKIVehStateGetNbVehiclesSection(sid, False)
                if result >= 0:
                    valid.append(sid)
            except Exception:
                pass
        return valid

    def _classify_sections_by_geometry(self, section_ids):
        """
        Split approach sections into main (corridor, N-S) and side (cross-street, E-W)
        using their geometric orientation relative to the junction centroid.

        Used when no UpDetList detector sections are configured — the only reliable AAPI
        way to distinguish Logan Road (N-S) approaches from cross-street (E-W) approaches.

        Returns (main_secs, side_secs) as lists of int section IDs.
        Falls back to (all_sections, []) if coordinates are unavailable.
        """
        jct_xy = self._get_junction_xy()
        if jct_xy is None:
            return list(section_ids), []

        jx, jy = float(jct_xy[0]), float(jct_xy[1])
        # Try alternate XY attribute names used across Aimsun versions
        _XY_ATTRS = [
            ('xSection',     'ySection'),
            ('xSectionTo',   'ySectionTo'),
            ('xcoordTo',     'ycoordTo'),
            ('xTo',          'yTo'),
            ('xDestination', 'yDestination'),
            ('xcoord',       'ycoord'),
            ('x',            'y'),
        ]

        main_secs, side_secs, unknown_secs = [], [], []
        for sec_id in section_ids:
            try:
                si = AKIInfNetGetSectionANGInf(int(sec_id))
                if getattr(si, 'report', -1) < 0:
                    unknown_secs.append(sec_id)
                    continue
                sx, sy = None, None
                for xa, ya in _XY_ATTRS:
                    _x = getattr(si, xa, None)
                    _y = getattr(si, ya, None)
                    if _x is not None and _y is not None:
                        try:
                            _xf, _yf = float(_x), float(_y)
                            if not (_xf == 0.0 and _yf == 0.0):
                                sx, sy = _xf, _yf
                                break
                        except (TypeError, ValueError):
                            pass
                if sx is None:
                    unknown_secs.append(sec_id)
                    continue
                # Direction vector: from junction centroid → section coordinate.
                # For an incoming section, this vector points AWAY from the junction
                # towards the section's upstream end.
                dx = abs(sx - jx)
                dy = abs(sy - jy)
                if dx < 1.0 and dy < 1.0:
                    # Section centroid essentially at junction — can't determine direction
                    unknown_secs.append(sec_id)
                    continue
                # N-S approach: |dy| dominates; E-W approach: |dx| dominates
                if dy >= dx:
                    main_secs.append(sec_id)   # N-S → Logan Road main corridor
                else:
                    side_secs.append(sec_id)   # E-W → cross-street
            except Exception:
                unknown_secs.append(sec_id)

        # Unknowns are conservatively assigned to main so they use partial stats
        main_secs.extend(unknown_secs)
        if LOG_SIDE_DISC:
            log_to_file(
                f"[SIDE_DISC] inter={self.id} geometry-split: "
                f"main={main_secs} side={side_secs} unknown_kept_main={unknown_secs}"
            )
        return main_secs, side_secs

    def _signal_plan_split(self):
        """Split this junction's approaches by the LIVE signal plan, keyed on the
        bus phase: returns (bus_origins, side_origins) where bus_origins are the
        origin sections of every signal group green in self.BusPhase and
        side_origins the origins of groups NEVER green in it (minus bus_origins).
        Reads per-phase SGs via ECI*ofJunction and maps sg -> sections via the
        AAPI turning calls (positional sg ids — the catalog cannot resolve them).
        Returns (set(), set()) whenever the plan cannot be read; callers fall
        back to geometry."""
        try:
            _jid = int(getattr(self, 'node_id', 0) or 0) or int(self.id)
            _bp = int(getattr(self, 'BusPhase', -1) or -1)
            if _bp < 1:
                return set(), set()
            try:
                _n_ph = int(ECIGetNumberofPhases(_jid))
            except Exception:
                try:
                    _n_ph = int(ECIGetNumberPhases(_jid))
                except Exception:
                    _n_ph = 0
            if _n_ph < 2 or _bp > _n_ph:
                return set(), set()
            _phase_sgs = {}
            _all_sgs = set()
            for _ph in range(1, _n_ph + 1):
                _sgs = set()
                try:
                    _nsg = int(ECIGetNbSignalGroupsPhaseofJunction(_jid, _ph, 0.0))
                    for _pos in range(1, _nsg + 1):
                        try:
                            _sg = int(ECIGetSignalGroupPhaseofJunction(
                                _jid, _ph, _pos, 0.0))
                            if _sg > 0:
                                _sgs.add(_sg)
                                _all_sgs.add(_sg)
                        except Exception:
                            pass
                except Exception:
                    pass
                _phase_sgs[_ph] = _sgs
            _bus_sgs = _phase_sgs.get(_bp, set())
            if not _bus_sgs or not _all_sgs:
                return set(), set()

            def _sg_origins(_sg):
                _out = set()
                try:
                    _nt = int(ECIGetNumberTurningsofSignalGroup(_jid, int(_sg)))
                    for _ti in range(max(_nt, 0)):
                        try:
                            _fp = intp(); _tp = intp()
                            ECIGetFromToofTurningofSignalGroup(
                                _jid, int(_sg), _ti, _fp, _tp)
                            _sec = int(_fp.value())
                            if _sec > 0:
                                _out.add(_sec)
                        except Exception:
                            continue
                except Exception:
                    pass
                return _out

            _bus_origins = set()
            for _sg in _bus_sgs:
                _bus_origins |= _sg_origins(_sg)
            _side_origins = set()
            for _sg in _all_sgs:
                if _sg in _bus_sgs:
                    continue
                if _sg in _phase_sgs.get(_bp, set()):
                    continue
                _side_origins |= _sg_origins(_sg)
            _side_origins -= _bus_origins
            return _bus_origins, _side_origins
        except Exception:
            return set(), set()

    def _phase_origin_sections(self):
        """{phase: set(origin sections)} from the LIVE signal plan, cached.

        Maps each phase's signal groups -> turning origin sections via the same
        AAPI positional-sg primitives as _signal_plan_split / _classify_turnings.
        Used to fill UpFlowList per phase/DIRECTION (2026-09-26): a bus-free
        continuous monitor must price the direction being SERVED, not a
        both-direction mean (Logan's two mains differ ~3x at some junctions).
        {} when the plan cannot be read -- callers then keep the broadcast
        mean. Cached on the controller (recreated per replication)."""
        _c = getattr(self, '_phase_secs_cache', None)
        if _c is not None:
            return _c
        _out = {}
        try:
            _jid = int(getattr(self, 'node_id', 0) or 0) or int(self.id)
            try:
                _n_ph = int(ECIGetNumberofPhases(_jid))
            except Exception:
                _n_ph = int(ECIGetNumberPhases(_jid))
            for _ph in range(1, max(_n_ph, 0) + 1):
                _sgs = set()
                try:
                    _nsg = int(ECIGetNbSignalGroupsPhaseofJunction(_jid, _ph, 0.0))
                    for _pos in range(1, _nsg + 1):
                        try:
                            _sg = int(ECIGetSignalGroupPhaseofJunction(
                                _jid, _ph, _pos, 0.0))
                            if _sg > 0:
                                _sgs.add(_sg)
                        except Exception:
                            pass
                except Exception:
                    pass
                _secs = set()
                for _sg in _sgs:
                    try:
                        _nt = int(ECIGetNumberTurningsofSignalGroup(_jid, int(_sg)))
                        for _ti in range(max(_nt, 0)):
                            try:
                                _fp = intp(); _tp = intp()
                                ECIGetFromToofTurningofSignalGroup(
                                    _jid, int(_sg), _ti, _fp, _tp)
                                _s = int(_fp.value())
                                if _s > 0:
                                    _secs.add(_s)
                            except Exception:
                                continue
                    except Exception:
                        pass
                if _secs:
                    _out[_ph] = _secs
        except Exception:
            _out = {}
        if _out:
            self._phase_secs_cache = _out
        return _out

    def _log_plan_scan(self, time):
        """One-time [PLAN_SCAN] dump: per phase, the signal-plan origin sections
        (from _phase_origin_sections) with their REAL length + lane count, so the
        scanned approaches can be checked against the actual intersection geometry
        -- a short length flags a model connector rather than a full approach lane.
        Read-only diagnostic; fires once per junction."""
        if getattr(self, '_plan_scan_done', False):
            return
        self._plan_scan_done = True
        try:
            _po = self._phase_origin_sections() or {}
            _bp = int(getattr(self, 'BusPhase', -1) or -1)
            if not _po:
                log_to_file(f"[PLAN_SCAN] inter={self.id} t={time:.0f} "
                            f"(no signal-plan origins resolved)", force=True)
                return
            for _ph in sorted(_po.keys()):
                _parts = []
                for _s in sorted(_po[_ph]):
                    try:
                        _si = AKIInfNetGetSectionANGInf(int(_s))
                        if getattr(_si, 'report', -1) >= 0:
                            _L = float(getattr(_si, 'length', 0.0) or 0.0)
                            _ln = max(int(getattr(_si, 'nbCentralLanes', 1))
                                      + int(getattr(_si, 'nbSideLanes', 0)), 1)
                            _parts.append(f"{_s}({_L:.0f}m,{_ln}L)")
                        else:
                            _parts.append(f"{_s}(?)")
                    except Exception:
                        _parts.append(f"{_s}(?)")
                log_to_file(
                    f"[PLAN_SCAN] inter={self.id} t={time:.0f} "
                    f"ph{_ph}{'*BUS' if _ph == _bp else ''} origins={_parts}",
                    force=True)
        except Exception as _e:
            log_to_file(f"[PLAN_SCAN] inter={self.id} error {_e!r}", force=True)

    def _nonmain_phase_indices(self):
        """0-based UpFlowList ROW indices of the SIDE-street phases (not the bus
        phase, not a phase serving any main approach). (2026-09-26)

        The analytic cross cost iterates per-phase rows: pricing a side phase's
        row is right (its own approach flow -- both cross directions
        distinguished), but pricing the OPPOSITE MAIN phase's row double-counts
        once _measured_opposite_main_delay prices that direction from measured
        queues. Returns None when the plan map is unresolved (callers keep the
        legacy all-non-bus-rows behaviour), or the (possibly empty) row list
        when resolved. Rows follow the fillers' swap: row 0 = bus phase, phase 1
        takes row (BusPhase-1) when BusPhase != 1."""
        try:
            _ps = self._phase_origin_sections() or {}
            if not _ps:
                return None
            _mains = set(int(s) for s in
                         (getattr(self, 'incoming_sections', []) or []))
            _bp = int(getattr(self, 'BusPhase', -1) or -1)
            _rows = []
            for _ph, _secs in _ps.items():
                _ph = int(_ph)
                if _ph == _bp:
                    continue
                if any(int(s) in _mains for s in _secs):
                    continue        # main-direction phase -> measured term prices it
                if _ph == 1 and _bp != 1:
                    _rows.append(_bp - 1)
                else:
                    _rows.append(_ph - 1)
            return _rows
        except Exception:
            return None

    def _turning_flow_vph(self, from_sec, to_sec, veh_type=-1, sim_hours=None):
        """Authoritative flow (veh/h) for the turn from_sec->to_sec, from Aimsun's
        own TURNING statistics (node flow = sum of turning flows). Prefers the
        current-interval .Flow; falls back to cumulative count/sim_hours. 0.0 if
        unavailable. Turning is (fromSectionId, toSectionId, vehType) per the AAPI."""
        try:
            _st = AKIEstGetCurrentStatisticsTurning(int(from_sec), int(to_sec), int(veh_type))
            if _st is not None and getattr(_st, 'report', -1) == 0:
                _f = float(getattr(_st, 'Flow', 0.0) or 0.0)
                if _f > 0.0:
                    return _f
        except Exception:
            pass
        if sim_hours and sim_hours > 0.0:
            try:
                _st = AKIEstGetGlobalStatisticsTurning(int(from_sec), int(to_sec), int(veh_type))
                if _st is not None and getattr(_st, 'report', -1) == 0:
                    _f = float(getattr(_st, 'Flow', 0.0) or 0.0)
                    if _f > 0.0:
                        return _f
                    _c = float(getattr(_st, 'count', 0.0) or 0.0)
                    if _c > 0.0:
                        return _c / float(sim_hours)
            except Exception:
                pass
        return 0.0

    def _classify_turnings(self):
        """(main_turns, side_turns): sets of (from_sec,to_sec) turning pairs where
        MAIN = turnings of signal groups green in the bus phase, SIDE = turnings of
        conflicting SGs (never green with the bus phase). This is the turning-level
        version of _signal_plan_split -- the correct main/side split for the
        shockwave (a section whose lanes serve different phases is split per-turn).
        Returns (set(), set()) if the plan can't be read."""
        try:
            _jid = int(getattr(self, 'node_id', 0) or 0) or int(self.id)
            _bp = int(getattr(self, 'BusPhase', -1) or -1)
            if _bp < 1:
                return set(), set()
            try:
                _n_ph = int(ECIGetNumberofPhases(_jid))
            except Exception:
                try:
                    _n_ph = int(ECIGetNumberPhases(_jid))
                except Exception:
                    _n_ph = 0
            if _n_ph < 2 or _bp > _n_ph:
                return set(), set()
            _phase_sgs = {}
            _all_sgs = set()
            for _ph in range(1, _n_ph + 1):
                _sgs = set()
                try:
                    _nsg = int(ECIGetNbSignalGroupsPhaseofJunction(_jid, _ph, 0.0))
                    for _pos in range(1, _nsg + 1):
                        try:
                            _sg = int(ECIGetSignalGroupPhaseofJunction(_jid, _ph, _pos, 0.0))
                            if _sg > 0:
                                _sgs.add(_sg); _all_sgs.add(_sg)
                        except Exception:
                            pass
                except Exception:
                    pass
                _phase_sgs[_ph] = _sgs
            _bus_sgs = _phase_sgs.get(_bp, set())
            if not _bus_sgs or not _all_sgs:
                return set(), set()

            def _sg_turn_pairs(_sg):
                _pairs = set()
                try:
                    _nt = int(ECIGetNumberTurningsofSignalGroup(_jid, int(_sg)))
                    for _ti in range(max(_nt, 0)):
                        try:
                            _fp = intp(); _tp = intp()
                            ECIGetFromToofTurningofSignalGroup(_jid, int(_sg), _ti, _fp, _tp)
                            _fr = int(_fp.value()); _to = int(_tp.value())
                            if _fr > 0 and _to > 0:
                                _pairs.add((_fr, _to))
                        except Exception:
                            continue
                except Exception:
                    pass
                return _pairs

            _main = set()
            for _sg in _bus_sgs:
                _main |= _sg_turn_pairs(_sg)
            _side = set()
            for _sg in _all_sgs:
                if _sg in _bus_sgs:
                    continue
                _side |= _sg_turn_pairs(_sg)
            _side -= _main
            return _main, _side
        except Exception:
            return set(), set()

    def _turning_main_side_flow(self, sim_hours=None):
        """(main_vph, side_vph, n_main_turns, n_side_turns): total flow across the
        junction's MAIN turnings (bus-phase) and SIDE turnings (conflicting), summed
        from authoritative Aimsun turning statistics -- the node=sum-of-turnings
        method. (0,0,0,0) if the plan/turnings can't be read."""
        _main, _side = self._classify_turnings()
        _mv = sum(self._turning_flow_vph(_f, _t, -1, sim_hours) for (_f, _t) in _main)
        _sv = sum(self._turning_flow_vph(_f, _t, -1, sim_hours) for (_f, _t) in _side)
        return _mv, _sv, len(_main), len(_side)

    def _conflicting_sg_origin_sections(self, main_sec_ids):
        """Origin sections of the signal groups that CONFLICT with the bus phase
        (i.e. never green together with it). Uses self.SignalGroupIDList (the
        per-phase signal-group id lists rebuilt from the live plan) + PyANGKernel
        GKSignalGroup turnings -> origin sections. Returns a set of section ids
        (minus main); empty set if the plan/topology can't be read (caller then
        keeps the unfiltered incoming-minus-main set)."""
        try:
            _sgl = getattr(self, 'SignalGroupIDList', None)
            _bp = int(getattr(self, 'BusPhase', -1) or -1)
            if not _sgl or _bp < 1 or _bp > len(_sgl):
                return set()

            def _phase_sgs(ph):
                try:
                    v = _sgl[ph - 1]
                    if isinstance(v, (list, tuple, set)):
                        return set(int(x) for x in v)
                    return {int(v)}
                except Exception:
                    return set()

            bus_sgs = _phase_sgs(_bp)
            conflicting = set()
            for ph in range(1, len(_sgl) + 1):
                if ph == _bp:
                    continue
                for sg in _phase_sgs(ph):
                    if sg not in bus_sgs:
                        conflicting.add(sg)
            if not conflicting:
                return set()

            _eci_id = int(getattr(self, 'node_id', 0) or 0) or int(self.id)

            try:
                from PyANGKernel import GKSystem
                model = GKSystem.getSystem().getActiveModel()
                catalog = model.getCatalog() if model is not None else None
            except Exception:
                catalog = None

            def _sg_sections(sg_id):
                secs = set()
                # PRIMARY: AAPI turning enumeration — the sg ids in
                # SignalGroupIDList come from ECIGetSignalGroupPhaseofJunction
                # and are POSITIONAL plan indices (e.g. 1..12), not ANG catalog
                # ids, so catalog.find() cannot resolve them. These AAPI calls
                # use the same positional ids (proven pattern in
                # intersection_controller_experimental._map_sg_sections).
                try:
                    _nt = int(ECIGetNumberTurningsofSignalGroup(_eci_id, int(sg_id)))
                    for _ti in range(max(_nt, 0)):
                        try:
                            _fp = intp(); _tp = intp()
                            ECIGetFromToofTurningofSignalGroup(
                                _eci_id, int(sg_id), _ti, _fp, _tp)
                            _sec = int(_fp.value())
                            if _sec > 0:
                                secs.add(_sec)
                        except Exception:
                            continue
                except Exception:
                    pass
                if secs:
                    return secs
                # FALLBACK: PyANGKernel catalog (builds where sg ids are ANG ids).
                if catalog is None:
                    return secs
                try:
                    sg_obj = catalog.find(int(sg_id))
                except Exception:
                    sg_obj = None
                if sg_obj is None:
                    return secs
                for meth in ('getSignals', 'getTurnings', 'getSignalGroupSignals'):
                    fn = getattr(sg_obj, meth, None)
                    if not callable(fn):
                        continue
                    try:
                        items = fn()
                    except Exception:
                        continue
                    if items is None:
                        continue
                    for it in (list(items) if hasattr(items, '__iter__') else [items]):
                        turn = it
                        for tmeth in ('getTurning', 'getGKTurning'):
                            tf = getattr(it, tmeth, None)
                            if callable(tf):
                                try:
                                    t = tf()
                                    if t is not None:
                                        turn = t
                                        break
                                except Exception:
                                    pass
                        for ometh in ('getOrigin', 'getFromSection', 'getSection'):
                            of = getattr(turn, ometh, None)
                            if callable(of):
                                try:
                                    o = of()
                                    if o is not None:
                                        oid = int(o.getId())
                                        if oid > 0:
                                            secs.add(oid)
                                        break
                                except Exception:
                                    pass
                    if secs:
                        break
                return secs

            out = set()
            for sg in conflicting:
                out |= _sg_sections(sg)
            out -= set(int(s) for s in (main_sec_ids or set()))
            return out
        except Exception:
            return set()

    def _auto_discover_side_sections(self):
        """
        Discover side-street approach sections feeding into this junction node.
        Uses AKIInfNetGetNbTurnsInNode / AKIInfNetGetOriginSectionInTurn to enumerate
        all incoming sections at the junction, then excludes the main corridor sections
        (those that contain upstream detectors).

        CACHING POLICY:
          • Cache the result only when the AAPI scan itself succeeded (n_turns queried).
          • When the scan fails (exception) or is skipped (_topo_fallback_main), return []
            WITHOUT caching so the next collect_delay call retries.  This prevents a
            transient Aimsun API unavailability at startup from permanently locking in
            an empty side-section set for the whole simulation.
        """
        if hasattr(self, '_cached_side_sections'):
            return self._cached_side_sections

        # ── Signal-plan split FIRST (2026-08-27) ──────────────────────────────
        # On models with detectors on EVERY approach (Logan), the detector-
        # derived "main" set covers all entrances, so the turn-scan subtraction
        # below yields side=[] and CACHES it — no cross sections all run. The
        # signal plan is the only authority that knows which approaches serve
        # the bus: main = origins of signal groups green in BusPhase, side =
        # origins of groups never green with it. Try it unconditionally; fall
        # through to the legacy detector/turn/geometry logic when unreadable.
        try:
            _sp_main, _sp_side = self._signal_plan_split()
        except Exception:
            _sp_main, _sp_side = set(), set()
        if not (_sp_main and _sp_side) and not getattr(self, '_sp_split_logged', False):
            self._sp_split_logged = True
            log_to_file(
                f"[SIDE_DISC] inter={self.id} signal-plan split unavailable "
                f"(bus_origins={len(_sp_main)} side_origins={len(_sp_side)} "
                f"BusPhase={getattr(self, 'BusPhase', '?')}) — using legacy "
                f"detector/turn/geometry side discovery", force=True)
        if _sp_main and _sp_side:
            _inc0 = list(getattr(self, 'incoming_sections', []) or [])
            _new_main = [s for s in _inc0 if s in _sp_main] or sorted(_sp_main)
            _new_side = [s for s in sorted(_sp_side) if s not in _sp_main]
            # Resolve connectors to real queuing sections like the legacy path.
            try:
                _new_side = self._resolve_real_approach_sections(
                    _new_side, set(_new_main)) or _new_side
            except Exception:
                pass
            if _new_main and _new_side:
                self._cached_side_sections = _new_side
                self.incoming_sections = list(_new_main)
                self.config['MainSections'] = list(_new_main)
                self.config['SideSections'] = list(_new_side)
                self._topo_fallback_main = False
                _inter_d = (self.stats._inter.get(self.id, {})
                            if self.stats else {})
                if _inter_d:
                    _inter_d['main_sections'] = list(_new_main)
                    _inter_d['side_sections'] = list(_new_side)
                    _inter_d['side_sections_resolved'] = True
                    _inter_d['side_sections_source'] = 'signal_plan'
                log_to_file(
                    f"[SIDE_DISC] inter={self.id} signal-plan split: "
                    f"main={_new_main} side={_new_side}", force=True)
                try:
                    if self.stats and hasattr(self.stats,
                                              '_write_side_sections_report'):
                        self.stats._write_side_sections_report()
                except Exception:
                    pass
                return _new_side

        main_sec_ids = set(self._derive_sections_from_detectors())
        # When all configured detectors are invalid, _derive_sections_from_detectors()
        # returns [].  If incoming_sections was populated from real detectors, use it
        # as the exclusion set.  But if it was populated by topology fallback (no
        # detectors at all), using it would exclude ALL sections → 0 side sections.
        # In that case, use Stats topology discovery which has PyANGKernel info
        # about section names/directions to correctly identify side streets.
        if not main_sec_ids and getattr(self, 'incoming_sections', None):
            if getattr(self, '_topo_fallback_main', False):
                # No detector sections — all incoming_sections came from topology.
                # (The signal-plan split at the top of this function has already
                # been tried; reaching here means the plan was unreadable.)
                # Use geometric orientation (N-S vs E-W) to split main from side.
                # This is reliable for Logan Road which runs roughly N-S.
                _geo_main, _geo_side = self._classify_sections_by_geometry(
                    self.incoming_sections)
                if _geo_side:
                    # Geometry split succeeded: cache result and refine main sections
                    self._cached_side_sections = _geo_side
                    _inter_d = (self.stats._inter.get(self.id, {})
                                if self.stats else {})
                    if not _inter_d.get('main_sections'):
                        _inter_d['main_sections'] = _geo_main
                        self.config['MainSections'] = _geo_main
                        # Narrow incoming_sections to corridor-only (N-S) sections
                        self.incoming_sections = _geo_main
                        self._topo_fallback_main = False  # geometry split is reliable
                    if LOG_SIDE_DISC:
                        log_to_file(
                            f"[SIDE_DISC] inter={self.id} topo-fallback: "
                            f"geometry resolved main={_geo_main} side={_geo_side}")
                    return _geo_side
                # Geometry couldn't split (coordinates unavailable) — still uncached
                if LOG_SIDE_DISC:
                    log_to_file(
                        f"[SIDE_DISC] inter={self.id} topo-fallback: "
                        f"geometry also failed — treating all incoming as main")
                return []   # intentionally uncached — retry on next call
            main_sec_ids = set(self.incoming_sections)
            if LOG_SIDE_DISC:
                log_to_file(
                    f"[SIDE_DISC] inter={self.id} no detector sections — "
                    f"using incoming_sections as main_sec_ids={sorted(main_sec_ids)}")
        side_secs = []
        tried_method = "none"

        try:
            n_turns = AKIInfNetGetNbTurnsInNode(self.node_id)
            tried_method = "AKIInfNetGetNbTurnsInNode"
            if LOG_SIDE_DISC:
                log_to_file(
                    f"[SIDE_DISC] inter={self.id} node={self.node_id} "
                    f"junction has {n_turns} turns; "
                    f"main_secs={sorted(main_sec_ids)}")

            seen = set()
            for t_idx in range(n_turns):
                try:
                    sec_id = AKIInfNetGetOriginSectionInTurn(self.node_id, t_idx)
                except Exception:
                    continue
                if sec_id <= 0 or sec_id in seen:
                    continue
                seen.add(sec_id)
                if sec_id in main_sec_ids:
                    continue
                try:
                    if AKIVehStateGetNbVehiclesSection(sec_id, False) < 0:
                        continue
                except Exception:
                    continue
                side_secs.append(sec_id)

        except Exception as ex:
            if LOG_SIDE_DISC:
                log_to_file(
                    f"[SIDE_DISC] inter={self.id} turn-based scan error: {ex} — "
                    f"NOT caching empty result (will retry next call)")
            # AAPI call failed — do NOT cache, allow retry
            return []

        # ── Conflicting-signal-group filter (shockwave-correct cross traffic) ──
        # The turn scan above returns EVERY incoming approach minus main -- which
        # includes the OPPOSING same-direction approach that shares green with the
        # bus. For shockwave propagation we want only the approaches whose signal
        # groups CONFLICT with the bus phase (lose green when the bus is served) --
        # that is the queue the bus grant actually grows. Best-effort: if the plan
        # or GKSignalGroup topology can't be read, keep the unfiltered set.
        # 2026-08-27: default OFF. This ONE side set prices the cross cost of ALL
        # action families, and while conflicting-only is correct for GE (extending
        # the bus green steals only from conflicting groups), an INSERTION /
        # phase-steal also takes green from the OPPOSING same-phase approach --
        # filtering it out UNDER-priced INS-family cost and the Logan re-run showed
        # every action-firing arm got worse. Until the cost paths are per-action-
        # family, price cost on the conservative full set (over-pricing degrades
        # to safe NO_ACTION, never gridlock). The stats-layer conflicting-SG split
        # (reporting/objective) is unaffected. Set True to re-enable for GE-only
        # experiments.
        if side_secs and bool(globals().get('SIDE_CONFLICTING_SG_ONLY', False)):
            try:
                _conf = self._conflicting_sg_origin_sections(main_sec_ids)
                if _conf:
                    _filtered = [s for s in side_secs if s in _conf]
                    if _filtered:
                        if LOG_SIDE_DISC and set(_filtered) != set(side_secs):
                            log_to_file(
                                f"[SIDE_DISC] inter={self.id} conflicting-SG filter: "
                                f"{sorted(side_secs)} -> {sorted(_filtered)}")
                        side_secs = _filtered
            except Exception:
                pass

        # ── Resolve connectors → real upstream queuing sections ──────────────
        # Turn-origin sections in Aimsun are often short connector links (<200 m)
        # that carry no simulated vehicles.  The real approach section where vehicles
        # queue is one (sometimes two) hops upstream.  Replace each connector with
        # its upstream real section so the per-vehicle delay scan finds actual traffic.
        if side_secs:
            side_secs = self._resolve_real_approach_sections(side_secs, main_sec_ids)

        # AAPI scan succeeded (even if n_turns == 0, that is a valid answer).
        # Cache the result so subsequent calls skip the AAPI overhead.
        self._cached_side_sections = side_secs
        if LOG_SIDE_DISC:
            log_to_file(
                f"[SIDE_DISC] inter={self.id} method={tried_method} "
                f"found {len(side_secs)} side sections (after resolve): {side_secs}")
        if side_secs:
            self.config['SideSections'] = side_secs
        return side_secs

    def _resolve_real_approach_sections(self, raw_secs: list, main_sec_ids: set) -> list:
        """
        Replace short connector sections with their real upstream queuing sections.

        Aimsun models often place a short connector link (<200 m) immediately before
        a signalised junction node.  These connectors appear as turn-origin sections
        but carry NO simulated traffic — vehicles queue on the UPSTREAM real section.

        For each section in raw_secs:
          1. If its length >= CONNECTOR_THRESHOLD_M, assume it is a real road section.
          2. Otherwise:
             a. Read the section's origin node (idNodeOrigin) from the network info.
             b. Scan turns at that origin node to find which one has THIS connector
                as its destination.
             c. Return the ORIGIN section of that turn — the real queuing section.
          3. Any resolved section that is itself a connector (still short) is resolved
             one additional hop.  The process stops after 3 hops to avoid infinite loops.
          4. Exclude resolved sections that are already in main_sec_ids.
        """
        CONNECTOR_THRESHOLD_M = 200.0
        MAX_HOPS = 3

        def _resolve_one(sec_id: int, depth: int) -> int:
            if depth >= MAX_HOPS:
                return sec_id
            try:
                si = AKIInfNetGetSectionANGInf(sec_id)
                if getattr(si, 'report', -1) < 0:
                    return sec_id
                if float(si.length) >= CONNECTOR_THRESHOLD_M:
                    return sec_id  # real section, done
                origin_node = int(getattr(si, 'idNodeOrigin', -1) or -1)
                if origin_node <= 0:
                    return sec_id
                n = int(AKIInfNetGetNbTurnsInNode(origin_node))
                for ti in range(n):
                    try:
                        dest = int(AKIInfNetGetDestinationSectionInTurn(origin_node, ti))
                        if dest == sec_id:
                            origin = int(AKIInfNetGetOriginSectionInTurn(origin_node, ti))
                            if origin > 0 and origin != sec_id:
                                return _resolve_one(origin, depth + 1)
                    except Exception:
                        continue
            except Exception:
                pass
            return sec_id

        resolved = []
        seen = set()
        for sec in raw_secs:
            real = _resolve_one(sec, 0)
            if real > 0 and real not in main_sec_ids and real not in seen:
                seen.add(real)
                resolved.append(real)
        return resolved

    def _movement_map_side_origins(self):
        """Side approach sections from the phase->turning map (2026-09-28).

        Authoritative source: the movement map (_phase_movement_map) lists every
        phase's turnings (from,to). SIDE approaches = origin sections of the
        NON-bus phases' turnings that aren't already main. This catches
        junctions whose signal-plan split / topology discovery return empty
        (e.g. 17249, 18942) even though they carry real side streets -- so the
        side-delay measurement actually has sections to price. Returns []
        when genuinely sideless (e.g. 17308).
        """
        try:
            _pm = self._phase_movement_map()
            _bp = int(getattr(self, 'BusPhase', -1) or -1)
            _main_ids = set(int(s) for s in
                            (getattr(self, 'incoming_sections', None) or []))
            _side = set()
            for _ph, _e in (_pm or {}).items():
                if int(_ph) == _bp:
                    continue
                for (_f, _t) in _e.get('turns', []):
                    if int(_f) > 0 and int(_f) not in _main_ids:
                        _side.add(int(_f))
            if not _side:
                return []
            try:
                _res = self._resolve_real_approach_sections(
                    sorted(_side), _main_ids) or sorted(_side)
            except Exception:
                _res = sorted(_side)
            return sorted(set(int(s) for s in _res))
        except Exception:
            return []

    def _get_side_sections(self):
        # First try config / stats stored IDs, but validate and resolve them
        candidate = self._normalize_side_sections(self.config.get('SideSections', []))
        if not candidate:
            inter_state = self._get_inter_state()
            if inter_state is not None:
                candidate = self._normalize_side_sections(inter_state.get('side_sections', []))

        if candidate:
            valid = self._validate_section_ids(candidate)
            if valid:
                # Resolve connectors → real approach sections before caching.
                # Also clear any stale _cached_side_sections so the resolved
                # sections get properly cached on next auto-discover call.
                main_ids = set(self.incoming_sections) | set(
                    (self._get_inter_state() or {}).get('main_sections', []))
                resolved = self._resolve_real_approach_sections(valid, main_ids)
                if resolved:
                    self.config['SideSections'] = resolved
                    # Update discovery cache so repeated calls return resolved secs
                    self._cached_side_sections = resolved
                    if LOG_SIDE_DISC and set(resolved) != set(valid):
                        log_to_file(
                            f"[SIDE_DISC] inter={self.id} connector→real resolve: "
                            f"{sorted(valid)} → {sorted(resolved)}")
                    return resolved
                # Resolved to empty — fall through to auto-discovery
            # All stored IDs were invalid — fall through to auto-discovery

        # ── Movement-map fallback (2026-09-28) ──────────────────────────────
        # When config + signal-plan/topology discovery return nothing, the
        # phase->turning map still knows the side approaches (17249/18942).
        # Map them so the side-delay measurement has sections to price.
        if not getattr(self, '_cached_side_sections', None):
            _mm_side = self._movement_map_side_origins()
            if _mm_side:
                self.config['SideSections'] = _mm_side
                self._cached_side_sections = _mm_side
                # Sync into the stats per-junction dict so the QUEUE FEED
                # (Simulation_Stats.accumulate_intersection_step scans
                # main+side_sections) actually measures these sections --
                # otherwise they'd be mapped here but never scanned, so the
                # side queue/delay would still read blank.
                try:
                    _sd = getattr(self.stats, '_inter', None)
                    _rec = (_sd or {}).get(int(self.id))
                    if _rec is not None:
                        _prev = set(int(s) for s in
                                    (_rec.get('side_sections') or []))
                        _rec['side_sections'] = list(
                            _prev | set(int(s) for s in _mm_side))
                except Exception:
                    pass
                log_to_file(
                    f"[SIDE_DISC] inter={self.id} movement-map side: "
                    f"{sorted(_mm_side)}", force=True)
                return _mm_side

        return self._auto_discover_side_sections()

    def _normalize_side_sections(self, side_secs):
        return self._normalize_sections(side_secs)

    def _ensure_side_section_arrays(self, side_secs, time):
        n = max(len(side_secs), 1)
        if len(self.SideUpFlowList) == n:
            return
        self.SideUpFlowList      = np.zeros(n)
        self.SideUpDenList       = np.zeros(n)
        self.SideShockwaveSpeed1 = np.zeros(n)
        self.SideShockwaveSpeed3 = np.zeros(n)

    def _profile_sections(self):
        """
        Build a permanent cache of static section geometry for all approach
        sections (main + side) at this junction.  Called once at startup so
        the delay measurement paths never call AKIInfNetGetSectionANGInf
        during simulation hot-path.

        Cache key: section_id (int)
        Cache value: {
            'length_m': float,     # section length in metres
            'ff_time_s': float,    # free-flow travel time (length / speed_limit)
            'n_lanes':   int,      # number of trafficable lanes
            'sat_flow':  float,    # saturation flow for this section (veh/h/lane)
            'jam_density': float,  # jam density (veh/km)
        }
        """
        if hasattr(self, '_sec_profile'):
            return  # already built

        cache = {}
        # Use _get_side_sections() (which now resolves connectors) so the profile
        # covers real queuing sections, not Aimsun connector links.
        _side = self._get_side_sections()
        all_secs = list(set(self.incoming_sections) | set(_side))
        for sec in all_secs:
            try:
                si       = AKIInfNetGetSectionANGInf(sec)
                length_m = max(float(si.length),    1.0)
                spd_ms   = max(float(si.speedLimit) / 3.6, 1.0)   # km/h → m/s
                n_lanes  = max(int(si.nbCentralLanes) + int(si.nbSideLanes), 1)
                ff_s     = length_m / spd_ms
                cache[sec] = {
                    'length_m':   length_m,
                    'ff_time_s':  ff_s,
                    'n_lanes':    n_lanes,
                    # Use junction-level saturation flow if available; otherwise
                    # fall back to Aimsun default ~1800 veh/h/lane.
                    'sat_flow':   float(getattr(self, 'SaturationFlow', 1800)),
                    'jam_density': float(getattr(self, 'JamDensity', 150)),
                }
            except Exception:
                cache[sec] = {
                    'length_m': 100.0, 'ff_time_s': 10.0,
                    'n_lanes': 1, 'sat_flow': 1800.0, 'jam_density': 150.0,
                }
        self._sec_profile = cache
        # Also seed the legacy side_ff_cache so Priority-B fallback
        # (if ever reached) picks up the correct values immediately.
        if not hasattr(self, '_side_ff_cache'):
            self._side_ff_cache = {}
        for sec, prof in cache.items():
            self._side_ff_cache[sec] = prof['ff_time_s']
        if LOG_SIDE_DISC:
            log_to_file(
                f"[PROFILE] inter={self.id} profiled {len(cache)} sections: "
                + ", ".join(f"{s}(ff={v['ff_time_s']:.1f}s,{v['n_lanes']}ln)"
                            for s, v in cache.items())
            )

    def _measured_sections_queue_veh(self, sections):
        """Total MEASURED standing queue (veh) over `sections` from the live
        detector feed (stats.latest_section, populated by MEASURED_QUEUE_FEED).
        Returns None unless EVERY section has a fresh measurement, so a phase
        with partial detector coverage is never gap-out truncated on a
        partially-observed zero (a loaded but unmeasured approach would be
        starved). Callers keep their analytic estimate on None. (2026-09-24)"""
        _stats = globals().get('stats', None) or getattr(self, 'stats', None)
        _ls = getattr(_stats, 'latest_section', None) if _stats is not None else None
        if not _ls or not sections:
            return None
        try:
            _t_now = float(AKIGetCurrentSimulationTime())
        except Exception:
            _t_now = -1.0
        _fresh = float(globals().get('MEASURED_SIDE_FRESH_S', 90.0))
        _q = 0.0
        for _ms in sections:
            try:
                _st = _ls.get(int(_ms))
            except Exception:
                _st = None
            if not _st:
                return None            # unmeasured approach: unknown, not empty
            if _t_now >= 0.0 and abs(_t_now - float(_st.get('t', -1e9))) > _fresh:
                return None            # stale measurement: unknown, not empty
            _lanes = max(int(_st.get('lanes', 1) or 1), 1)
            _q += max(0.0, float(_st.get('queue_veh', 0.0) or 0.0)) * _lanes
        return _q

    def _measured_delay_per_veh_s(self, sections):
        """MEASURED mean delay per vehicle (s) over `sections`, from Aimsun's own
        section statistics (.DTa = delay-time-average, the microscopic delay the
        car-following model actually produces). Prefers the current interval, falls
        back to cumulative. None when unavailable. This is the realised delay the
        KPIs are scored on -- used to CALIBRATE the analytic decision reward toward
        the plant, closing the decide-analytic / score-measured gap."""
        _tot = 0.0
        _n = 0
        for _s in (sections or []):
            try:
                _st = AKIEstGetCurrentStatisticsSection(int(_s), -1)
                if getattr(_st, 'report', -1) != 0:
                    _st = AKIEstGetGlobalStatisticsSection(int(_s), -1)
                if getattr(_st, 'report', -1) == 0:
                    _d = float(getattr(_st, 'DTa', 0.0) or 0.0)
                    if _d >= 0.0:
                        _tot += _d
                        _n += 1
            except Exception:
                continue
        return (_tot / _n) if _n > 0 else None

    def _analytic_delay_per_veh_s(self, sections, phase, timeSta=0.0):
        """The MODEL's PREDICTED delay/veh (s) for `phase` under the current plan --
        Webster uniform delay d = 0.5*C*(1-g/C)^2 / (1-x), x = q*C/(mu*g). Matched to
        _measured_delay_per_veh_s (same lanes, same operating point) so the
        calibration factor kappa = realised(.DTa) / predicted is a TRUE ratio, not
        just measured/REF. None when the plan/flow can't be read."""
        try:
            _jid = int(getattr(self, 'node_id', 0) or 0) or int(self.id)
            _C = float(self._signal_cycle_s(timeSta) or 0.0)
            _g = float(GetPhaseDuration(_jid, int(phase), timeSta) or 0.0)
            if _C <= 1.0 or _g <= 0.0:
                return None
            _mu = max(float(getattr(self, 'SaturationFlow', 1900.0) or 1900.0), 1.0)
            _q = 0.0
            for _s in (sections or []):
                _q += max(0.0, float(self._measured_section_flow_vph(int(_s))))
            if _q <= 0.0:
                for _s in (sections or []):
                    try:
                        _q += max(0.0, float(self._demand_seed_flow_for_sec(int(_s))))
                    except Exception:
                        pass
            if _q <= 0.0:
                return None
            _x = min(_q * _C / (_mu * _g), 0.98)          # degree of saturation
            _lam = min(max(_g / _C, 0.01), 0.99)
            return max(0.0, 0.5 * _C * (1.0 - _lam) ** 2 / max(1.0 - _x, 0.02))
        except Exception:
            return None

    def _update_delay_calibration(self, timeSta=0.0):
        """Maintain per-approach EWMA calibration factors kappa_main / kappa_side =
        measured delay-per-veh (.DTa) / DELAY_CAL_REF_S, so the analytic reward can
        be scaled toward the realised microscopic delay -- differentially per side,
        so it changes the surplus (a uniform factor would not). Default inert."""
        if not bool(globals().get('DELAY_CALIBRATION', False)):
            return
        _ref = max(float(globals().get('DELAY_CAL_REF_S', 15.0)), 1.0)
        _a = float(globals().get('DELAY_CAL_ALPHA', 0.1) or 0.1)
        _lo = float(globals().get('DELAY_CAL_MIN', 0.25))
        _hi = float(globals().get('DELAY_CAL_MAX', 4.0))

        def _ewma(_tag, _k):
            _p = getattr(self, _tag, None)
            setattr(self, _tag, _k if _p is None else (1.0 - _a) * _p + _a * _k)

        try:
            # PER-PHASE openness (2026-09-30): rather than a rigid geographic
            # main/side split, read EVERY signal phase's realised delay from the
            # lanes IT serves (_phase_origin_sections -> .DTa) -- a general
            # per-movement 'how open is this phase' factor. Then map to the eval's
            # served/conflicting interface: benefit scales by the SERVED phase's
            # openness, cost by the WORST conflicting phase (act less when any
            # conflicting movement is congested). Falls back to main/side sections.
            # kappa is the TRUE realised/predicted ratio: measured .DTa divided by
            # the model's Webster prediction for the SAME phase+plan. Falls back to
            # measured/REF only when no analytic prediction is available.
            def _kappa(_secs, _phase):
                _m = self._measured_delay_per_veh_s(list(_secs))
                if _m is None:
                    return None
                _pred = (self._analytic_delay_per_veh_s(list(_secs), _phase, timeSta)
                         if _phase is not None else None)
                _ratio = (_m / _pred) if (_pred and _pred > 1.0) else (_m / _ref)
                return min(max(_ratio, _lo), _hi)

            _po = self._phase_origin_sections() or {}
            _bp = int(getattr(self, 'BusPhase', -1) or -1)
            if _po:
                _kphase = {}
                for _ph, _secs in _po.items():
                    _k = _kappa(_secs, int(_ph))
                    if _k is not None:
                        _kphase[int(_ph)] = _k
                if _kphase:
                    self._delay_cal_phase = _kphase   # per-phase realised/predicted
                    if _bp in _kphase:
                        _ewma('_delay_cal_main', _kphase[_bp])
                    _others = [v for p, v in _kphase.items() if p != _bp]
                    if _others:
                        _ewma('_delay_cal_side', max(_others))
                    return
            # Fallback: geographic main vs side sections.
            _main = (list(getattr(self, 'incoming_sections', []) or [])
                     or list((getattr(self, 'config', {}) or {}).get('MainSections', []) or []))
            _side = self._get_side_sections() or []
            for _tag, _secs, _ph in (('_delay_cal_main', _main, _bp),
                                     ('_delay_cal_side', _side, None)):
                _k = _kappa(_secs, _ph)
                if _k is not None:
                    _ewma(_tag, _k)
        except Exception:
            pass

    def _measured_section_flow_vph(self, sec):
        """MEASURED flow (veh/h) on `sec` from the LIVE vehicle count and space-mean
        speed -- q = density x speed = (n / len_km) * mean_speed_kmh (the fundamental
        relation). This WORKS on the virtual/modeled sections where Aimsun's own
        section statistics report Flow=0 (the roll_ctr=0 blind spot): the vehicle
        count and per-vehicle speed are live queries, not gathered statistics. A
        fully stopped queue returns ~0 (correct: a jam has ~0 throughput -- its cost
        is priced from the standing count, not the flow). 0.0 when empty or the
        geometry is unavailable."""
        try:
            _n = int(AKIVehStateGetNbVehiclesSection(int(sec), False))
            if _n <= 0:
                return 0.0
            _si = AKIInfNetGetSectionANGInf(int(sec))
            _ok = getattr(_si, 'report', -1) >= 0
            _len = float(getattr(_si, 'length', 0.0) or 0.0) if _ok else 0.0
            _lanes = (max(int(getattr(_si, 'nbCentralLanes', 1))
                          + int(getattr(_si, 'nbSideLanes', 0)), 1) if _ok else 1)
            # A section shorter than the min is a connector stub (e.g. a 10 m
            # [dead+main+model] link): density = n/len_km explodes there (1 veh /
            # 10 m = 100 veh/km), so count x speed gives a meaningless ~5000 vph.
            # Treat it as unmeasurable and return 0 rather than a spike.
            if _len < float(globals().get('MEAS_MIN_SECTION_M', 25.0)):
                return 0.0
            _sv = 0.0
            _c = 0
            for _vi in range(_n):
                try:
                    _inf = AKIVehStateGetVehicleInfSection(int(sec), _vi)
                    _sv += max(0.0, float(getattr(_inf, 'CurrentSpeed', 0.0) or 0.0))
                    _c += 1
                except Exception:
                    continue
            if _c <= 0:
                return 0.0
            _vmean = _sv / _c                       # km/h, arithmetic space-mean
            _q = (_n / (_len / 1000.0)) * _vmean    # veh/h = density x speed
            # Physical ceiling: a lane cannot discharge faster than saturation.
            # On a very short (e.g. 10 m connector) section density x speed can
            # blow up (2 veh / 10 m => 200 veh/km); cap at saturation x lanes so
            # the measured flow stays realistic instead of ~12000 vph.
            _qmax = max(float(getattr(self, 'SaturationFlow', 1900.0) or 1900.0), 1.0) * _lanes
            return max(0.0, min(_q, _qmax))
        except Exception:
            return 0.0

    def _measured_main_queue_veh(self, phase=None):
        """MEASURED queue (veh) on this junction's MAIN approaches (for Nash
        measured state). None when no fresh measurement.

        phase=None -> self.BusPhase when the signal plan resolves: only the
        sections THAT PHASE serves are summed, so the mainline benefit prices
        the served DIRECTION, not both directions at once (2026-09-26)."""
        _main = (list(getattr(self, 'incoming_sections', []) or [])
                 or list((getattr(self, 'config', {}) or {}).get('MainSections', []) or []))
        try:
            _ph = int(phase) if phase is not None \
                else int(getattr(self, 'BusPhase', -1) or -1)
            if _ph >= 1:
                _ps = self._phase_origin_sections() or {}
                _secs = _ps.get(_ph)
                if _secs:
                    _sel = [s for s in _main if int(s) in _secs]
                    if _sel:
                        _main = _sel
        except Exception:
            pass
        _q = self._measured_sections_queue_veh(_main)
        if _q is not None:
            return _q
        # Live fallback (2026-09-29): the detector feed (latest_section) can be
        # empty on a corridor that isn't populating MEASURED_QUEUE_FEED, so the
        # analytic mainline benefit (q_sat*g) over-credits an empty main phase and
        # the demand-based controller extends green with no cars to serve. Count
        # the LIVE standing vehicles zoned near the stop line on the served main
        # sections, symmetric to the side live-cost floor, so the mainline BENEFIT
        # is bounded by the ACTUAL cars present. None only when no main sections.
        if not _main:
            return None
        try:
            _n = 0.0
            for _s in _main:
                try:
                    _c, _L, _why = self._zone_queue_count(int(_s))
                    _n += max(0.0, float(_c))
                except Exception:
                    pass
            return _n
        except Exception:
            return None

    def _current_green_remaining_s(self, time, timeSta):
        """Remaining seconds of the CURRENT phase (engine-side method, so the
        engine's GetPhaseDuration wrapper resolves natively -- calling it bare from
        specialized_modes raised NameError and disabled the bus ETA logic). Returns
        None on failure so callers keep their legacy magnitude behaviour."""
        try:
            _cur = int(ECIGetCurrentPhase(self.node_id))
            _ps = float(ECIGetStartingTimePhase(self.node_id))
            _pd = float(GetPhaseDuration(self.node_id, _cur, timeSta))
            return max(0.0, _pd - (float(time) - _ps))
        except Exception:
            return None

    def _actuated_coord_phase(self, timeSta):
        """Coordinated phase = the LONGEST fixed phase (the main-street green band).
        Cached once per junction, together with its BASE (programmed) duration and
        the nominal cycle length (sum of base phase durations) — read BEFORE any
        reclaim so the offset-preserve maths never double-counts. Returns the
        1-based phase index or None."""
        _c = getattr(self, '_coord_phase_cache', None)
        if _c is not None:
            return _c
        try:
            _n = int(ECIGetNumberofPhases(self.node_id))
        except Exception:
            try:
                _n = int(ECIGetNumberPhases(self.node_id))
            except Exception:
                _n = 0
        _best_ph, _best_d, _sum = None, -1.0, 0.0
        _durs = {}
        for _ph in range(1, _n + 1):
            try:
                _d = float(GetPhaseDuration(self.node_id, _ph, timeSta))
            except Exception:
                _d = 0.0
            _durs[_ph] = _d
            _sum += max(0.0, _d)
            if _d > _best_d:
                _best_d, _best_ph = _d, _ph
        self._coord_phase_cache = _best_ph
        self._coord_base_dur = _best_d if _best_d > 0.0 else None
        # Nominal cycle = the programmed cycle length (includes intergreens).
        # Sum-of-greens under-reads it by the total intergreen/lost time, which
        # tripped the drift guard on every clean cycle. Fall back to the sum.
        _cfg_cyc = 0.0
        try:
            _cfg_cyc = float((getattr(self, 'config', {}) or {}).get('CycleTime', 0.0) or 0.0)
        except Exception:
            _cfg_cyc = 0.0
        self._act_nominal_cycle = (_cfg_cyc if _cfg_cyc > 0.0
                                   else (_sum if _sum > 0.0 else None))
        log_to_file(f"[ACTBASE][NOMINAL] inter={self.id} n_ph={_n} "
                    f"durs={_durs} sum={_sum:.1f}s cfg_cyc={_cfg_cyc:.1f}s "
                    f"nominal={self._act_nominal_cycle} coord={_best_ph}",
                    force=True)
        return _best_ph

    def _phase_served_sections(self, phase):
        """Origin (approach) sections served green in a GIVEN phase, via the live
        signal plan (phase -> signal groups -> turning origin sections). Same ECI*
        mapping _signal_plan_split uses for the bus phase, generalised to any
        phase and cached. Returns a set() (possibly empty) or None if unreadable."""
        _cache = getattr(self, '_phase_sec_cache', None)
        if _cache is None:
            _cache = {}
            self._phase_sec_cache = _cache
        _pk = int(phase)
        if _pk in _cache:
            return _cache[_pk]
        _jid = int(getattr(self, 'node_id', 0) or 0) or int(self.id)
        _out = set()
        try:
            _nsg = int(ECIGetNbSignalGroupsPhaseofJunction(_jid, _pk, 0.0))
            for _pos in range(1, _nsg + 1):
                try:
                    _sg = int(ECIGetSignalGroupPhaseofJunction(_jid, _pk, _pos, 0.0))
                except Exception:
                    continue
                if _sg <= 0:
                    continue
                try:
                    _nt = int(ECIGetNumberTurningsofSignalGroup(_jid, _sg))
                except Exception:
                    _nt = 0
                for _ti in range(max(_nt, 0)):
                    try:
                        _fp = intp(); _tp = intp()
                        ECIGetFromToofTurningofSignalGroup(_jid, _sg, _ti, _fp, _tp)
                        _sec = int(_fp.value())
                        if _sec > 0:
                            _out.add(_sec)
                    except Exception:
                        continue
        except Exception:
            _cache[_pk] = None
            return None
        _cache[_pk] = _out
        return _out

    def _in_permissive_window(self, time, timeSta, current_phase):
        """ACTUATED_PERMISSIVE_GATE: the coordinated-actuated permissive window in
        which a decider may act. Defined as the coordinated (band) phase being
        green -- so no-bus / continuous perturbations can only touch the arterial
        phase, never a side phase (which would walk the band). Bus-present actions
        are gated separately by the caller (they stay allowed). Returns True when
        the gate is off or we're in-window / can't resolve the coord phase."""
        if not bool(globals().get('ACTUATED_PERMISSIVE_GATE', False)):
            return True
        try:
            _coord = self._actuated_coord_phase(timeSta)
        except Exception:
            _coord = None
        if _coord is None:
            return True
        try:
            return int(current_phase) == int(_coord)
        except Exception:
            return True

    def _coordinated_actuated_base(self, time, timeSta, acycle):
        """Layer 2: coordinated-actuated BASE control under the TSP algorithms.
        The plans are fixed-time, so add demand-responsiveness: GAP-OUT a non-
        coordinated phase whose OWN served approaches are empty (measured), MAX-OUT
        an over-long one, while PROTECTING the coordinated (longest) phase.

        OFFSET PRESERVATION (ACTUATED_OFFSET_PRESERVE): truncating a phase shortens
        the cycle and would drift the coordinated offset, so the reclaimed seconds
        are handed to the coordinated phase (extend it -> cycle length, and thus the
        offset, is held; coordinated-actuated "rest in green"). Uses ECIChangeTiming
        Phase (same primitive as the GE/VP executors). NOTE: this RETIMES phases and
        MUST be validated in a sim run. Returns True if it truncated. Default OFF."""
        if not bool(globals().get('ACTUATED_BASE_MODE', False)):
            return False
        try:
            _cur = int(ECIGetCurrentPhase(self.node_id))
        except Exception:
            return False
        if _cur < 1:
            return False
        _coord = self._actuated_coord_phase(timeSta)
        if _coord is None:
            return False
        # ── Self-verifying cycle / offset-drift check (removes the "unobserved
        # retiming" caveat). Each time the coordinated phase STARTS, measure the
        # realised cycle length vs nominal; on persistent drift, auto-DISABLE
        # offset-preserve and log [ACTBASE][DRIFT]. Also resets the per-cycle
        # reclaim tally so coord extensions never accumulate across gap-outs.
        # ONLY clean cycles are measured: the priming edge (first observation
        # may be mid-green at sim load), cycles dirtied by an own gap-out
        # truncation, and cycles containing any TSP grant (their length was
        # deliberately changed) are all skipped -- otherwise every intervention
        # reads as drift, the guard fires constantly and offset-preserve latches
        # off (which is exactly the failure seen on Logan). A sticky-disabled
        # flag self-heals after consecutive clean in-tol cycles.
        _prev = getattr(self, '_act_prev_phase', None)
        if _cur == _coord and _prev != _coord:
            _last = getattr(self, '_act_last_coord_start', None)
            _nom = getattr(self, '_act_nominal_cycle', None)
            _primed = bool(getattr(self, '_act_cycle_primed', False))
            _dirty = bool(getattr(self, '_act_cycle_dirty', False))
            self._act_cycle_dirty = False
            try:
                _grant_in_cycle = (_last is not None and float(
                    getattr(self, 'last_tsp_action_time', -1e9)) > float(_last))
            except Exception:
                _grant_in_cycle = False
            if _last is not None and _nom and _primed and not _dirty and not _grant_in_cycle:
                _meas = float(time) - float(_last)
                _tol = float(globals().get('ACTUATED_DRIFT_TOL_S', 5.0) or 5.0)
                # Two-reference AND-gate: the programmed nominal can be wrong
                # (phase-count quirks, e.g. a 300 s sum on a ~92 s cycle), so a
                # deviation only counts when the cycle ALSO disagrees with the
                # median of recent clean cycles. Clean agreements are learned
                # into the history (cap 12); faults are not.
                _hist = list(getattr(self, '_act_cycle_hist', []) or [])
                _med = (sorted(_hist)[len(_hist) // 2] if len(_hist) >= 3 else None)
                _bad_prog = abs(_meas - _nom) > _tol
                _bad_hist = (_med is not None and abs(_meas - _med) > _tol)
                if _med is not None and _nom and abs(_med - _nom) > _tol and not bool(
                        getattr(self, '_act_nom_logged', False)):
                    self._act_nom_logged = True
                    log_to_file(f"[ACTBASE][NOMINAL] inter={self.id} programmed={_nom:.1f}s "
                                f"observed-median={_med:.1f}s (plan/config mismatch?)",
                                force=True)
                if _med is not None and _bad_prog and _bad_hist:
                    self._act_drift_count = int(getattr(self, '_act_drift_count', 0)) + 1
                    log_to_file(f"[ACTBASE][DRIFT] inter={self.id} t={time:.1f} "
                                f"cycle={_meas:.1f}s nominal={_nom:.1f}s "
                                f"med={_med:.1f} "
                                f"count={self._act_drift_count}", force=True)
                    if self._act_drift_count >= int(globals().get('ACTUATED_DRIFT_MAX', 3)):
                        self._act_offset_disabled = True
                        log_to_file(f"[ACTBASE][DRIFT] inter={self.id} offset-preserve "
                                    f"DISABLED (persistent drift)", force=True)
                else:
                    # No count until 3 clean cycles are learned (a garbage
                    # programmed nominal alone can never latch the guard).
                    self._act_drift_count = max(0, int(getattr(self, '_act_drift_count', 0)) - 1)
                    if getattr(self, '_act_offset_disabled', False) and int(
                            getattr(self, '_act_drift_count', 0)) <= 0:
                        self._act_offset_disabled = False
                        log_to_file(f"[ACTBASE][DRIFT] inter={self.id} offset-preserve "
                                    f"RE-ENABLED (cycle back within tol)", force=True)
                    self._act_cycle_hist = (_hist + [_meas])[-12:]
            self._act_cycle_primed = True
            self._act_last_coord_start = float(time)
            self._act_cycle_reclaim = 0.0
        self._act_prev_phase = _cur
        if _cur == _coord:
            return False               # never gap/max the coordinated band phase
        try:
            _ps = float(ECIGetStartingTimePhase(self.node_id))
            _elapsed = max(0.0, time - _ps)
            _pdur = float(GetPhaseDuration(self.node_id, _cur, timeSta))
        except Exception:
            return False
        _min_g = float(globals().get('ACTUATED_MIN_GREEN_S', 5.0) or 5.0)
        if _elapsed < _min_g:
            return False
        _max_g = float(globals().get('ACTUATED_MAX_GREEN_S', 0.0) or 0.0)
        _reason = None
        if _max_g > 0.0 and _elapsed >= _max_g:
            _reason = "max-out"
        else:
            # gap-out: no measured demand on THIS phase's OWN served approaches
            # (precise per-phase mapping; falls back to the aggregate side set only
            # when the per-phase signal-plan read is unavailable).
            _served = None
            try:
                _served = self._phase_served_sections(_cur)
            except Exception:
                _served = None
            _secs = list(_served) if _served else list(self._get_side_sections() or [])
            try:
                _q = self._measured_sections_queue_veh(_secs)
            except Exception:
                _q = None
            _eps = float(globals().get('ACTUATED_GAP_QUEUE_EPS_VEH', 0.5) or 0.0)
            if _q is None or _q > _eps:
                return False           # demand present (or unknown) -> let it run
            _reason = "gap-out (served=%d)" % len(_secs)
        try:
            _new = max(_min_g, _elapsed)
            _delta = max(0.0, _pdur - _new)     # seconds reclaimed from this phase
            ECIChangeTimingPhase(self.node_id, _cur, _new, timeSta)
            _absorbed = 0.0
            if (_delta > 0.0 and bool(globals().get('ACTUATED_OFFSET_PRESERVE', False))
                    and not getattr(self, '_act_offset_disabled', False)):
                # Hand the reclaimed time to the coordinated phase so cycle length
                # (hence the offset) is preserved. Extend to the coord phase's BASE
                # duration + the total reclaimed THIS cycle (+delta) so repeated
                # gap-outs in one cycle do NOT stack (the accumulation bug the SUMO
                # shim revealed). Guarded by the drift self-check above.
                try:
                    _base = getattr(self, '_coord_base_dur', None)
                    _tally = float(getattr(self, '_act_cycle_reclaim', 0.0))
                    if _base is not None:
                        ECIChangeTimingPhase(self.node_id, _coord,
                                             float(_base) + _tally + _delta, timeSta)
                        self._act_cycle_reclaim = _tally + _delta
                        _absorbed = _delta
                except Exception:
                    _absorbed = 0.0
            # Zero-reclaim ends (phase already at/past its programmed end, e.g. an
            # Aimsun actuated hold) still end the hold now, but they retime
            # nothing: keep them quiet (no force-log spam), keep them out of the
            # TSP cooldown timestamp, and still mark the cycle dirty. Only a real
            # reclaim consumes cooldown and the force log line.
            if _delta > 0.0:
                self.last_tsp_action_time = time
            self._act_cycle_dirty = True   # this cycle was deliberately shortened:
                                           # skip it in the drift self-check
            try:
                self.stats.record_tsp_event(self.id, 'phase_skip')
            except Exception:
                pass
            log_to_file(f"[ACTBASE] inter={self.id} t={time:.1f} phase={_cur} "
                        f"{_reason} (coord={_coord}) trunc={_new:.1f}s "
                        f"reclaimed={_delta:.1f}s -> coord+{_absorbed:.1f}s",
                        force=(_delta > 0.0))
            return True
        except Exception as _e:
            log_to_file(f"[ACTBASE] inter={self.id} exec error {_e!r}")
            return False

    def _measured_side_delay_penalty(self, extra_red):
        """Congestion-aware side (cross) delay from the MEASURED cross-approach
        state. Ties the predicted side cost to how full the cross approaches
        ACTUALLY are, so holding a near-jammed cross street on red is priced high
        (spillback) -- fixing the shockwave estimate's under-pricing that caused
        the seed-lottery car cascades. Returns (delay_pax_s, veh_hours); (0,0)
        when no fresh measurement. Reads stats.latest_section (populated by the
        MEASURED_QUEUE_FEED): queue_veh (per-lane), q (flow veh/h), k (density
        veh/km/lane), queue_m, lanes."""
        extra_red = max(safe_float(extra_red), 0.0)
        if extra_red <= 0.0:
            return 0.0, 0.0
        # latest_section lives on the module-global stats singleton (the proven
        # accessor used by the cascade term); fall back to self.stats.
        _stats = globals().get('stats', None) or getattr(self, 'stats', None)
        _ls = getattr(_stats, 'latest_section', None) if _stats is not None else None
        # Empty latest_section feed no longer returns 0 wholesale (that priced a
        # busy cross approach at 0 on KG -> corridor over-action): fall through so
        # each side section is priced from the LIVE side flow instead. (2026-09-29)
        _ls = _ls or {}
        try:
            _t_now = float(AKIGetCurrentSimulationTime())
        except Exception:
            _t_now = -1.0
        _fresh = float(globals().get('MEASURED_SIDE_FRESH_S', 90.0))
        _spill = max(0.0, float(globals().get('MEASURED_SIDE_SPILL_GAIN', 3.0)))
        _car_occ = max(safe_float(getattr(self, 'CarOcc', 1.6)), 1.0)
        _kjam = max(safe_float(getattr(self, 'JamDensity', 150.0)), 1.0)  # veh/km/lane
        _side = self._get_side_sections()
        # Live side flow/density, parallel to _get_side_sections() (same order the
        # [SIDE_SCAN]/FLOW_DIAG logs confirm), for the no-fresh-measurement floor.
        _upflow = list(getattr(self, 'SideUpFlowList', []) or [])
        _upden = list(getattr(self, 'SideUpDenList', []) or [])
        _delay = 0.0
        _vehh = 0.0
        # ── diagnostic accounting (why the measured cost is / isn't engaging) ──
        _diag_on = bool(globals().get('MEASURED_SIDE_COST_DIAG', False))
        _n_total = 0; _n_present = 0; _n_fresh = 0
        _dbg = []

        def _live_side_cost(_idx, _ss):
            # Arrivals-over-red cost from the LIVE side flow when there is no fresh
            # latest_section reading. On a cross approach that is uncongested AT
            # DECISION TIME the standing queue is ~0, but the extra red still
            # delays every vehicle that ARRIVES during it (triangular avg wait
            # ~extra_red/2), scaled by a superlinear spillback severity from the
            # live density. Prefers the live flow, then the demand seed, then 0.
            _q = 0.0; _k = 0.0
            if _idx is not None and _idx < len(_upflow):
                _q = max(0.0, safe_float(_upflow[_idx]))
                if _idx < len(_upden):
                    _k = max(0.0, safe_float(_upden[_idx]))
            if _q < 1.0:
                _q = max(_q, safe_float(self._demand_seed_flow_for_sec(_ss)))
            if _q <= 0.0:
                return 0.0, 0.0
            _veh = (_q / 3600.0) * extra_red
            _sat = min(_k / _kjam, 0.95)
            _sev = 1.0 + _spill * (_sat / max(1.0 - _sat, 0.05))
            return (_veh * extra_red * 0.5 * _car_occ * _sev,
                    _veh * extra_red / 3600.0)

        for _idx_ss, _ss in enumerate(_side or []):
            _n_total += 1
            _st = _ls.get(int(_ss))
            if not _st:
                if _diag_on:
                    _dbg.append(f"{_ss}:NO_MEAS->live")
                _d, _v = _live_side_cost(_idx_ss, _ss)
                _delay += _d
                _vehh += _v
                continue
            _n_present += 1
            if _t_now >= 0.0 and abs(_t_now - float(_st.get('t', -1e9))) > _fresh:
                if _diag_on:
                    _dbg.append(f"{_ss}:STALE->live(dt={_t_now - float(_st.get('t', -1e9)):.0f}s)")
                _d, _v = _live_side_cost(_idx_ss, _ss)
                _delay += _d
                _vehh += _v
                continue
            _n_fresh += 1
            _lanes = max(int(_st.get('lanes', 1) or 1), 1)
            _nq = max(0.0, float(_st.get('queue_veh', 0.0) or 0.0)) * _lanes  # standing queue (veh)
            _qarr = max(0.0, float(_st.get('q', 0.0) or 0.0)) / 3600.0        # arrivals (veh/s)
            # MEASURED saturation of the cross approach: density/jam, refined by
            # the spatial queue fill (queue_m / section length) when available.
            _sat = min(max(0.0, float(_st.get('k', 0.0) or 0.0)) / _kjam, 1.0)
            try:
                _len_m = float(AKIInfNetGetSectionANGInf(int(_ss)).length or 0.0)
                if _len_m > 1.0:
                    _sat = max(_sat, min(float(_st.get('queue_m', 0.0) or 0.0) / _len_m, 1.0))
            except Exception:
                pass
            # Vehicles delayed by the extra red: standing queue + arrivals in window.
            _veh = _nq + _qarr * extra_red
            # SUPERLINEAR spillback severity: as the cross approach fills the
            # marginal delay of extra red explodes (queue can't clear, blocks
            # upstream). Bounded at sat<=0.95 so it stays finite.
            _s = min(_sat, 0.95)
            _sev = 1.0 + _spill * (_s / max(1.0 - _s, 0.05))
            _contrib = _veh * extra_red * _car_occ * _sev
            if _diag_on:
                _dbg.append(f"{_ss}:qv={_nq:.1f},sat={_sat:.2f},sev={_sev:.1f},c={_contrib:.0f}")
            if _veh <= 0.0:
                continue
            _delay += _contrib
            _vehh += _veh * extra_red / 3600.0
        # Throttled diagnostic (<=1 per junction per 20 sim-seconds) so we can SEE
        # whether the measured cross cost is engaging and, if not, why (NO_MEAS =
        # side section absent from latest_section feed; STALE = feed too old).
        if _diag_on:
            try:
                _last = globals().setdefault('_MEAS_SIDE_DIAG_LAST', {})
                if _t_now < 0.0 or (_t_now - float(_last.get(int(self.id), -1e9))) >= 20.0:
                    _last[int(self.id)] = _t_now
                    log_to_file(
                        f"[MEAS_SIDE] inter={self.id} red={extra_red:.0f}s "
                        f"side={_n_total} present={_n_present} fresh={_n_fresh} "
                        f"meas_delay={_delay:.0f}paxs | " + " ".join(_dbg))
            except Exception:
                pass
        return _delay, _vehh

    def _measured_opposite_main_delay(self, extra_red):
        """MEASURED delay (pax·s) imposed on the OPPOSITE mainline DIRECTION
        (the main approaches NOT served by the bus phase) when `extra_red`
        seconds of green are shifted to the bus phase. (2026-09-26)

        A green-shifting action (GE/GR/INS/ER/…) takes time from the OTHER
        corridor direction as well as the cross street, but the analytic
        mainline benefit (_mainline_pax_saved_for_green) credits only the
        SERVED direction -- so a phase insertion looked beneficial even when
        it queued the opposite direction. Mirror of
        _measured_side_delay_penalty's veh = standing + arrivals structure
        (both directions priced, same spirit as the two-way band check).
        Returns 0.0 when the phase map or feed is unavailable (fail-open:
        current behaviour preserved)."""
        extra_red = max(safe_float(extra_red), 0.0)
        if extra_red <= 0.0:
            return 0.0
        try:
            _ps = self._phase_origin_sections() or {}
        except Exception:
            _ps = {}
        _bp = int(getattr(self, 'BusPhase', -1) or -1)
        _bus_secs = _ps.get(_bp) if _bp >= 1 else None
        if not _bus_secs:
            return 0.0
        _opp = [int(s) for s in (getattr(self, 'incoming_sections', []) or [])
                if int(s) not in _bus_secs]
        if not _opp:
            return 0.0
        _stats = globals().get('stats', None) or getattr(self, 'stats', None)
        _ls = getattr(_stats, 'latest_section', None) if _stats is not None else None
        try:
            _t_now = float(AKIGetCurrentSimulationTime())
        except Exception:
            _t_now = -1.0
        _fresh = float(globals().get('MEASURED_SIDE_FRESH_S', 90.0))
        _car_occ = max(safe_float(getattr(self, 'CarOcc', 1.6)), 1.0)
        _delay = 0.0
        for _s in _opp:
            _nq = 0.0
            _qarr = 0.0
            _lanes = 1
            _seen = False
            if _ls:
                _st = _ls.get(_s)
                if _st is not None and (_t_now < 0.0 or abs(
                        _t_now - float(_st.get('t', -1e9))) <= _fresh):
                    _seen = True
                    _lanes = max(int(_st.get('lanes', 1) or 1), 1)
                    _nq = max(0.0, float(_st.get('queue_veh', 0.0) or 0.0)) * _lanes
                    _qarr = max(0.0, float(_st.get('q', 0.0) or 0.0)) / 3600.0
            if not _seen:
                # no fresh measurement: fall back to the live standing count
                try:
                    _nq = float(max(int(AKIVehStateGetNbVehiclesSection(
                        int(_s), False)), 0))
                except Exception:
                    _nq = 0.0
            _veh = _nq + _qarr * extra_red
            if _veh > 0.0:
                _delay += _veh * extra_red * _car_occ
        return _delay

    def _compute_side_delay_penalty(self, extra_red, _suppress_log=False):
        extra_red = max(safe_float(extra_red), 0.0)
        if extra_red <= 0.0:
            return 0.0, 0.0
        # MEASURED-congestion side cost: computed once here and blended (max) into
        # every substantive return below so a congested cross approach is never
        # under-priced. Off unless MEASURED_SIDE_COST is set.
        _meas_delay = 0.0
        _meas_vehh = 0.0
        if bool(globals().get('MEASURED_SIDE_COST', False)):
            try:
                _meas_delay, _meas_vehh = self._measured_side_delay_penalty(extra_red)
            except Exception:
                _meas_delay, _meas_vehh = 0.0, 0.0

        def _mx(_d, _v):
            return (max(float(_d), _meas_delay, _turn_delay),
                    max(float(_v), _meas_vehh))

        # Movement-decomposed side cost (MEASURED_TURN_COST, 2026-09-28):
        # dedicated turn lanes are distinct movements with their own queue and
        # phase; the section-level cost lumps them into the approach average.
        # Decompose over each non-bus phase's turnings (from the live
        # _phase_movement_map), splitting a section's zone queue across the
        # turnings that share it and charging each under its own extra red.
        _turn_delay = 0.0
        if bool(globals().get('MEASURED_TURN_COST', False)):
            try:
                _pm = self._phase_movement_map()
                _bp = int(getattr(self, 'BusPhase', -1) or -1)
                _side_turns = []
                for _ph, _e in (_pm or {}).items():
                    if int(_ph) == _bp:
                        continue
                    for (_f, _t) in _e.get("turns", []):
                        _side_turns.append((_f, _t))
                _from_count = {}
                for (_f, _t) in _side_turns:
                    _from_count[_f] = _from_count.get(_f, 0) + 1
                _occ = max(safe_float(getattr(self, 'CarOcc', 1.6)), 1.0)
                for (_f, _t) in _side_turns:
                    _n, _L, _why = self._zone_queue_count(_f)
                    if _n > 0:
                        _k = max(int(_from_count.get(_f, 1)), 1)
                        _turn_delay += (float(_n) / _k) * extra_red * _occ
                if _turn_delay > 0.0 and not _suppress_log:
                    log_to_file(
                        f"[TURN_COST] inter={self.id} "
                        f"extra_red={extra_red:.2f} "
                        f"turns={len(_side_turns)} movement-decomposed "
                        f"side_delay={_turn_delay:.1f} pax-s")
            except Exception:
                _turn_delay = 0.0

        # Fallback: when detector arrays are empty (minimal config like Logan Road),
        # estimate side delay from live section vehicle counts.  Without this,
        # the reward evaluation sees zero side cost for every GE/INS action,
        # the controller extends green without penalty, and side streets get
        # crushed — the "massive side delay" the user observed.
        if not hasattr(self, 'SideUpFlowList') or len(self.SideUpFlowList) == 0:
            _side_secs = self._get_side_sections()
            if not _side_secs:
                return 0.0, 0.0
            _car_occ = max(safe_float(getattr(self, 'CarOcc', 1.6)), 1.0)
            _total_side_veh = 0.0
            _total_side_delay = 0.0
            for _ss in _side_secs:
                # Zoned count: only vehicles held near THIS stop line.
                # Whole-section counting priced queues from the upstream
                # junction into this light's decisions.
                _n, _L, _why = self._zone_queue_count(_ss)
                if _n > 0:
                    _total_side_veh += _n
                    # Zone-held vehicles genuinely experience the extra red.
                    _total_side_delay += _n * extra_red * _car_occ
            if not _suppress_log:
                log_to_file(
                    f"[SIDE_OBJ] inter={self.id} extra_red={extra_red:.2f} "
                    f"fallback (no detectors): {_total_side_veh:.0f} veh on "
                    f"{len(_side_secs)} side sections → delay={_total_side_delay:.1f} pax-s")
            return _mx(_total_side_delay, _total_side_veh * extra_red / 3600.0)

        side_other_delay = 0.0
        side_total_veh = 0.0
        w2_side = abs(ShockwaveSpeed2(
            self.SaturationFlow, self.SaturationDensity, self.JamDensity))
        if w2_side <= 1e-6:
            return _mx(0.0, 0.0)

        jam_density = max(safe_float(self.JamDensity), 0.0)
        sat_density = max(safe_float(self.SaturationDensity), 0.0)

        # Standing-queue floor basis (2026-09-26): section order + geometry,
        # resolved at most once per sim-second (candidates within one decision
        # share the sim time, so this costs one resolution per step, not per
        # candidate). Profile cache is built once at startup; SideUpDenList is
        # already populated by the tier scan above.
        _floor_secs = ()
        _floor_on = bool(globals().get('SIDE_QUEUE_FLOOR', True))
        try:
            _ft = float(AKIGetCurrentSimulationTime())
        except Exception:
            _ft = -1.0
        if _floor_on:
            try:
                if (getattr(self, '_floor_secs_t', None) != _ft
                        or not isinstance(getattr(self, '_floor_secs', None), tuple)):
                    self._floor_secs = tuple(self._get_side_sections() or [])
                    self._floor_secs_t = _ft
                _floor_secs = self._floor_secs
            except Exception:
                _floor_secs = ()
        try:
            _zone_m = max(float(self._queue_zone_m(False)), 1.0)
        except Exception:
            _zone_m = 60.0
        _prof = getattr(self, '_sec_profile', {}) or {}

        for idx in range(len(self.SideUpFlowList)):
            q_s = max(safe_float(self.SideUpFlowList[idx]), 0.0)
            if q_s < 1.0:
                # Blind spot: stopped queues read ~0 flow, so a jammed cross
                # street prices zero (22603: 1165 vph side flow, pred_side=0
                # on all commits). Floor from LIVE standing vehicles -- NOT
                # density: SideUpDenList is flow-derived (den = flow*k/q), so
                # density is 0 whenever flow is ~0 and a density-based floor
                # is unreachable (measured: 1 of 6860 [SIDE_OBJ] lines
                # eligible). The live section count prices the stopped queue
                # it actually holds, capped by the zone's jam storage.
                # (veh-s here; the caller applies CarOcc.)
                if _floor_on and idx < len(_floor_secs):
                    try:
                        _n_live = int(AKIVehStateGetNbVehiclesSection(
                            int(_floor_secs[idx]), False))
                    except Exception:
                        _n_live = 0
                    if _n_live > 0:
                        try:
                            _pr = _prof.get(int(_floor_secs[idx]), None) or {}
                            _ln = max(int(_pr.get('n_lanes', 1) or 1), 1)
                            _k_jam = max(safe_float(
                                getattr(self, 'JamDensity', 150.0)), 1.0)
                            _cap = max(1.0, _ln * (_zone_m / 1000.0) * _k_jam)
                            _n_stand = min(float(_n_live), _cap)
                            side_other_delay += _n_stand * extra_red
                            side_total_veh += _n_stand * extra_red / 3600.0
                        except Exception:
                            pass
                continue

            k_s = min(max(safe_float(self.SideUpDenList[idx]), 0.0), jam_density)
            w1_s = abs(safe_float(self.SideShockwaveSpeed1[idx]))
            w3_s = abs(safe_float(self.SideShockwaveSpeed3[idx]))
            denom_s = w2_side - w1_s
            if denom_s <= 1e-6 or w3_s <= 1e-6:
                continue

            side_max_q = w2_side * w1_s * extra_red / denom_s
            if side_max_q <= 0.0:
                continue

            jam_term = max(jam_density - k_s, 0.0) / 1000.0
            sat_term = max(sat_density - k_s, 0.0) / 1000.0
            side_diss = side_max_q / w3_s
            side_delay_veh_s = (
                side_max_q * extra_red * 0.5 * jam_term
                + side_diss * side_max_q * 0.5 * sat_term)
            side_other_delay += side_delay_veh_s
            side_total_veh += q_s * extra_red / 3600.0

        # compute raw vehicle counts for each side section for the log
        _side_secs_log = self._get_side_sections()
        _side_nveh = []
        for _ss in _side_secs_log:
            try:
                _side_nveh.append(int(AKIVehStateGetNbVehiclesSection(_ss, False)))
            except Exception:
                _side_nveh.append(-1)
        # estimated queue lengths (max queue from shockwave model, converted to vehicles)
        _veh_len = max(self.VehLength, 1.0) + 2.0  # vehicle + gap
        _qlen_veh = [round(float(self.SideUpFlowList[_k]) * extra_red / 3600.0, 1)
                     for _k in range(len(self.SideUpFlowList))]
        if not _suppress_log:
            log_to_file(
                f"[SIDE_OBJ] inter={self.id} extra_red={extra_red:.2f} "
                f"side_secs={_side_secs_log} "
                f"n_veh={_side_nveh} "
                f"flow={[round(float(v),1) for v in self.SideUpFlowList]} "
                f"den={[round(float(v),2) for v in self.SideUpDenList]} "
                f"q_veh={_qlen_veh} "
                f"delay={side_other_delay:.2f} veh={side_total_veh:.2f} "
                f"meas={_meas_delay:.2f}"
            )

        return _mx(side_other_delay, side_total_veh)

    def _reset_harmony_work_arrays(self):
        for arr_name in (
            'BusDelay', 'OtherDelay', 'TotalVeh', 'HSMinQueueLength',
            'HSMaxQueueLength', 'HSMaxQueueLengthTime', 'HSQueueDissTime',
            'BusJoinQueueTime', 'BusStoplineTime', 'BusPhaseMinDuration'
        ):
            arr = getattr(self, arr_name, None)
            if arr is not None:
                arr.fill(0.0)

    @staticmethod
    def _safe_array_sum(arr):
        return float(np.nan_to_num(arr, nan=0.0, posinf=0.0, neginf=0.0).sum())

    def _finalize_objective_stats(self, bus_delay_total, other_delay_total,
                                  total_veh, avg_passenger_delay):
        bus_delay_total = max(safe_float(bus_delay_total), 0.0)
        other_delay_total = max(safe_float(other_delay_total), 0.0)
        total_veh = max(safe_float(total_veh), 0.0)
        avg_passenger_delay = max(safe_float(avg_passenger_delay), 0.0)
        return bus_delay_total, other_delay_total, total_veh, avg_passenger_delay

    def _estimated_other_vehicle_occupancy(self):
        inter_state = self._get_inter_state() or {}
        car_passages = max(safe_float(inter_state.get('car_veh_passages', 0.0)), 0.0)
        truck_passages = max(safe_float(inter_state.get('truck_veh_passages', 0.0)), 0.0)
        car_occ = max(safe_float(self.CarOcc), 0.0)
        truck_occ = max(safe_float(getattr(self, 'TruckOcc', self.CarOcc)), 0.0)
        total_other_passages = car_passages + truck_passages
        if total_other_passages <= 1e-6:
            return max(car_occ, 1e-6)
        total_other_pax_equiv = car_passages * car_occ + truck_passages * truck_occ
        return max(total_other_pax_equiv / total_other_passages, 1e-6)

    
    def _plan_det_reach(self, is_main, measured_q_vph=None):
        """VIRTUAL detector reach (m) derived from THIS junction's signal plan.

        Replaces the flat SIDE_QUEUE_ZONE_M / MAIN_QUEUE_ZONE_M = 60 m with a
        per-junction, per-approach distance, because one constant cannot be right
        for a 3-lane main with 50 s of green AND a side street with ~7 s: the
        reach that captures the main queue under-counts the side one, and the
        reach that captures the side queue counts free-flowing main traffic as if
        it were queued.

        Placement rule: put the virtual detector just UPSTREAM of the maximum
        queue the approach can hold at the end of its own red, so that
            vehicles between detector and stop line  ==  the queue
            vehicles crossing the detector             ==  arrivals
        Derivation (all quantities from the signal plan or the plant):
            R    = C - g                     red time for this approach
            q    = measured arrival flow     (fallback: capacity x v/c target)
            Qmax = q * R                     vehicles queued at end of red
            Lq   = Qmax / (k_jam * lanes)    km  -> *1000 = metres
            D    = clamp(Lq * SAFETY + MARGIN, MIN, MAX)
        The reach therefore SHRINKS where green is long and lanes are many, and
        GROWS where red is long and the approach is thin -- which is the whole
        point of deriving it rather than fixing it.

        g (effective green) for the main approach is BusPhaseDuration; for a side
        approach it is the SMALLEST non-bus phase green, which is the
        conservative choice (shortest green -> longest red -> longest reach, so
        the side queue is over- rather than under-counted).

        Returns None when the plan fields are unavailable, so callers fall back to
        the existing constant instead of guessing.
        """
        try:
            cfg = getattr(self, 'config', {}) or {}
            C = float(cfg.get('cycle_length') or 0.0)
            lanes = max(float(cfg.get('NumberOfLanes') or 0.0), 1.0)
            k_jam = float(getattr(self, 'JamDensity', None)
                          or cfg.get('JamDensity') or 150.0)
            sat = float(getattr(self, 'SaturationFlow', None)
                        or cfg.get('SaturationFlow') or 1800.0)   # veh/h/lane
            gb = cfg.get('GroupBasedConfig') or {}
            ig = float(gb.get('intergreen_duration') or 4.0)
            if C <= 0.0 or k_jam <= 0.0 or sat <= 0.0:
                return None

            if is_main:
                g = float(cfg.get('BusPhaseDuration') or 0.0)
            else:
                # smallest non-bus phase green at this junction
                _mg = [float(v) for v in (gb.get('min_green') or {}).values()]
                _mg = [v for v in _mg if v > 0.0]
                g = min(_mg) if _mg else max(C * 0.10, 5.0)
            if g <= 0.0 or g >= C:
                return None

            R = C - g
            # arrival rate: prefer the MEASURED flow (real plant state); fall
            # back to the approach's own capacity at a design v/c so the reach is
            # still plan-derived rather than arbitrary.
            q_vph = float(measured_q_vph or 0.0)
            if q_vph <= 0.0:
                _vc = float(globals().get('VIRTUAL_DET_VC_TARGET', 0.90) or 0.90)
                q_vph = sat * lanes * (g / C) * _vc
            q_vps = q_vph / 3600.0

            Qmax = q_vps * R                                   # vehicles
            Lq_m = (Qmax / (k_jam * lanes)) * 1000.0           # metres
            safety = float(globals().get('VIRTUAL_DET_SAFETY', 1.30) or 1.30)
            margin = float(globals().get('VIRTUAL_DET_MARGIN_M', 15.0) or 15.0)
            lo = float(globals().get('VIRTUAL_DET_MIN_M', 30.0) or 30.0)
            hi = float(globals().get('VIRTUAL_DET_MAX_M', 200.0) or 200.0)
            D = min(max(Lq_m * safety + margin, lo), hi)
            return D
        except Exception:
            return None

    def _queue_zone_m(self, is_main, measured_q_vph=None):
        """Reach used for queue counting / virtual detection.

        With VIRTUAL_DET_FROM_PLAN on, the per-junction signal-plan reach above;
        otherwise the historical flat constant. Logged once per junction so the
        derived distances can be AUDITED before they are trusted.
        """
        _fallback = (float(globals().get('MAIN_QUEUE_ZONE_M', 60.0) or 60.0)
                     if is_main
                     else float(globals().get('SIDE_QUEUE_ZONE_M', 60.0) or 60.0))
        if not bool(globals().get('VIRTUAL_DET_FROM_PLAN', False)):
            return _fallback
        D = self._plan_det_reach(is_main, measured_q_vph)
        if D is None:
            return _fallback
        try:
            _seen = getattr(self, '_vdet_logged', None)
            if _seen is None:
                _seen = self._vdet_logged = set()
            _tag = 'main' if is_main else 'side'
            if _tag not in _seen:
                _seen.add(_tag)
                _cfg = getattr(self, 'config', {}) or {}
                # Say WHICH input the reach came from, because the capacity fallback
                # cannot distinguish a 2-lane from a 3-lane approach (lanes cancel
                # when demand is assumed proportional to capacity), while a measured
                # flow can. Without this flag on the line, a fallback-derived reach
                # looks exactly as trustworthy as a measured one.
                _src = 'measured' if float(measured_q_vph or 0.0) > 0.0 else 'fallback'
                log_to_file(
                    f"[VDET] inter={self.id} {_tag}: reach={D:.0f}m src={_src} "
                    f"(C={_cfg.get('cycle_length')}s g={_cfg.get('BusPhaseDuration')}s "
                    f"lanes={_cfg.get('NumberOfLanes')} kjam={_cfg.get('JamDensity')} "
                    f"q={float(measured_q_vph or 0.0):.0f}vph "
                    f"flat={_fallback:.0f}m)", force=True)
        except Exception:
            pass
        return D

    def _upstream_chain(self, sec_id, max_len_m):
        """Upstream segments for queue counting: [(sec, dist_base, sec_len)].

        Returns every section within max_len_m (path distance) upstream of
        sec_id's downstream end (the stop line), as (section, dist_base,
        length) with dist_base = metres of chain downstream of the
        segment. Walks via origin node + turns (same primitives as
        _resolve_real_approach_sections). A 7 m virtual section alone
        cannot hold a real queue -- without this walk every vehicle
        spilling past its upstream end is invisible and side-street delay
        is underpriced (proven on KG side sections 66329/66334).
        Merge (several turns into one section): follows ALL branches --
        every in-zone vehicle on any branch feeding the stop line waits out
        our extra red, so counting one branch underprices side delay and
        lets green over-extend into real side queues. Stops a branch at
        main corridor sections and at managed (signalised) junctions:
        queues beyond those belong elsewhere and would not arrive this
        cycle. Loop-guarded, max 6 hops / 16 segments. Never raises; worst
        case returns the stop-line section alone.

        Returns (segments, stop_reason) with reason in zone/dead/managed/
        main/loop/hops/cap/empty/model/apifail-node/apifail-turns for the
        SIDE_SCAN diagnostic ([dead] = verified entry, nothing upstream;
        [zone+model] = full reach with model-topology hops filling AKI gaps
        (virtual connector resolved); apifail-* = both failed, queue
        possibly missed).
        """
        try:
            _zone = max(float(max_len_m), 1.0)
        except Exception:
            _zone = 60.0
        try:
            _main = set(int(s) for s in
                        ((getattr(self, 'config', {}) or {}).get('MainSections', [])
                         or []))
        except Exception:
            _main = set()
        # Managed-junction nodes: never count across intersections. Queues
        # beyond an upstream signal belong to that junction, and far vehicles
        # would not arrive this cycle anyway.
        try:
            _ctrls = globals().get('controllers', {}) or {}
            _managed_nodes = set()
            for _cc in list(_ctrls.values()):
                try:
                    _nn = int(getattr(_cc, 'node_id', -1) or -1)
                    if _nn > 0:
                        _managed_nodes.add(_nn)
                except Exception:
                    continue
        except Exception:
            _managed_nodes = set()

        def _sec_len(_s):
            try:
                _si = AKIInfNetGetSectionANGInf(int(_s))
                if getattr(_si, 'report', -1) < 0:
                    return None
                _L = float(getattr(_si, 'length', 0.0) or 0.0)
                return _L if _L > 0.0 else None
            except Exception:
                return None

        def _hop_ups(_s):
            """All (origin section, origin node) pairs feeding _s, plus an ok
            flag and detail: 'dead' (verified entry), 'node'/'turns' (AKI
            lookup failed), 'model' (AKI gave nothing; model topology used).

            AKI turn tables are sim truth and go first. Virtual connectors
            (no origin node / turns in AKI) fall back to the MODEL topology
            (session-cached section origin/destination map): a connector the
            model attaches to an upstream section is NOT a dead-end, and its
            queue lives upstream. Model candidates are sections ending at
            our origin node; the walk's managed/main guards still apply.
            Bias note: without turn filtering this can include a branch that
            does not feed us (overcount leans conservative = protects side
            streets; the old behaviour silently counted zero)."""
            _out = []
            try:
                _si = AKIInfNetGetSectionANGInf(int(_s))
                if getattr(_si, 'report', -1) < 0:
                    return _out, False, 'node'
                _node = int(getattr(_si, 'idNodeOrigin', -1) or -1)
                if _node <= 0:
                    _aki_detail = 'node'
                else:
                    _aki_detail = None
                    try:
                        _n = int(AKIInfNetGetNbTurnsInNode(_node))
                    except Exception:
                        return _out, False, 'turns'
                    for _ti in range(max(_n, 0)):
                        try:
                            _dest = int(AKIInfNetGetDestinationSectionInTurn(_node, _ti))
                            if _dest != int(_s):
                                continue
                            _org = int(AKIInfNetGetOriginSectionInTurn(_node, _ti))
                            if _org > 0 and _org != int(_s):
                                _out.append((_org, _node))
                        except Exception:
                            continue
                    if _out:
                        return _out, True, 'ok'
                    _aki_detail = 'dead'
            except Exception:
                return _out, False, 'turns'
            # AKI gave nothing: second opinion from the model topology.
            try:
                _topo = _model_topo()
            except Exception:
                _topo = {}
            try:
                if not (isinstance(_topo, dict) and _topo.get('ok')):
                    return _out, _aki_detail == 'dead', (_aki_detail or 'dead')
                _org_map = _topo.get('org', {}) or {}
                _by_dest = _topo.get('by_dest', {}) or {}
                if int(_s) in _org_map and _org_map[int(_s)] is None:
                    return _out, True, 'dead'  # model confirms: true entry
                _mo = _org_map.get(int(_s))
                if _mo is None:
                    return _out, _aki_detail == 'dead', (_aki_detail or 'dead')
                _mc = [(_t, _mo) for _t in (_by_dest.get(_mo, []) or [])
                       if int(_t) > 0 and int(_t) != int(_s)]
                if _mc:
                    return _mc, True, 'model'
                return _out, True, 'dead'
            except Exception:
                return _out, _aki_detail == 'dead', (_aki_detail or 'dead')

        _segs = []          # (sec, dist_base, sec_len)
        _seen = set()
        _whys = set()     # early-stop reasons across branches
        _reached = [False]  # any branch covered the full zone
        _model_used = [False]  # model topology supplied hops AKI missed
        # Worklist of (section, dist_base, via_node, hops), always expanded
        # smallest-distance-first (Dijkstra order): a merge must not let a
        # section be first reached via a LONGER path (which would inflate
        # every distance downstream of it and hide in-zone sections).
        # The stop-line section is seeded at 0 so it always counts.
        _work = [(int(sec_id), 0.0, None, 0)]
        while _work and len(_segs) < 16:
            _bi = min(range(len(_work)), key=lambda _i: (_work[_i][1], _work[_i][0]))
            _s, _db, _via, _hops = _work.pop(_bi)
            if _s in _seen:
                _whys.add('loop')
                continue
            _seen.add(_s)
            _L = _sec_len(_s)
            if _L is None:
                _whys.add('dead')
                continue
            _segs.append((_s, _db, _L))
            if _db + _L >= _zone or _hops >= 6:
                if _db + _L >= _zone:
                    _reached[0] = True
                else:
                    _whys.add('hops')
                continue
            _kids = 0
            _hop_cands, _hop_ok, _hop_detail = _hop_ups(_s)
            if _hop_detail == 'model':
                _model_used[0] = True
            if not _hop_ok:
                # Topology lookup failed (not a verified dead-end): flag it
                # distinctly -- a silent [dead] here could hide a real queue.
                # 'node' = section carries no origin node (typical virtual
                # connector); 'turns' = turn-table read failed.
                _whys.add('apifail-' + str(_hop_detail))
            for (_org, _node) in _hop_cands:
                if _org in _seen:
                    _whys.add('loop')
                    continue
                if _org in _main:
                    _whys.add('main')
                    continue
                if _node in _managed_nodes:
                    # Crossing a managed (signalised) junction: queues
                    # beyond it belong to that junction. Stop this branch.
                    _whys.add('managed')
                    continue
                _work.append((_org, _db + _L, _node, _hops + 1))
                _kids += 1
            if _kids == 0 and _db + _L < _zone and _hop_ok:
                _whys.add('dead')
        if len(_segs) >= 16:
            _whys.add('cap')
        if not _segs:
            _L0 = _sec_len(sec_id)
            if _L0:
                _segs = [(int(sec_id), 0.0, _L0)]
            _whys.add('empty')
        # A branch that reached the zone means coverage is complete; only
        # report early stops when NOTHING reached it. A '+model' suffix notes
        # the model topology supplied hops AKI turn tables missed (virtual
        # connectors) -- the case this fallback was built for.
        _why = 'zone' if _reached[0] else '+'.join(sorted(_whys)[:2] or ['zone'])
        if _model_used[0] and 'model' not in _why:
            _why = _why + '+model'
        return _segs, _why

    def _zone_queue_count(self, sec_id, zone_m=None):
        """(count, lane_m, why): vehicles within zone of the section's
        DOWNSTREAM end (the stop line). zone_m overrides SIDE_QUEUE_ZONE_M
        (main approaches pass their own MAIN_QUEUE_ZONE_M)."""
        try:
            zone = float(zone_m if zone_m is not None
                         else self._queue_zone_m(False))
        except Exception:
            zone = 60.0
        try:
            _segs, _why = self._upstream_chain(sec_id, zone)
        except Exception:
            return 0, None, 'error'
        cnt = 0
        _bus_in_zone = 0
        _zone_lane_m = 0.0
        for (_cs, _dist_base, _L) in _segs:
            if _L <= 0.0:
                continue
            # In-zone portion of this segment (lane-metres holding counted cars).
            _zone_lane_m += max(0.0, min(_L, zone - _dist_base))
            try:
                _n = max(0, int(AKIVehStateGetNbVehiclesSection(int(_cs), False) or 0))
            except Exception:
                continue
            if _n == 0:
                continue
            # MICROSCOPIC QUEUE (align with Aimsun's own queue definition): Aimsun
            # counts a vehicle as queuing only when its SPEED is below a threshold
            # (stopped/slow), not merely present in a zone. Counting every in-zone
            # vehicle over-states the queue (moving vehicles included) and mis-prices
            # the reward vs the plant. When MICRO_QUEUE_MODE is on, count only
            # vehicles with CurrentSpeed <= MICRO_QUEUE_SPEED_KMH.
            #
            # BUSES ARE NOT CARS (2026-10-01). This is a DETECTOR-style estimate and
            # detectors are for general traffic: buses are PT vehicles with known
            # IDs and routes, tracked individually through the PT APIs
            # (AKIGetVehicleFollowingPTLine / AKIPTVehGetInf), so folding them into
            # the car queue double-counts them -- once here at CarOcc and again in
            # the bus-delay term at BusOcc (40 pax). AKIVehStateGetVehicleInfSection
            # exposes both idVeh and type in one call, so the split is free.
            # EXCLUDE_BUS_FROM_CAR_QUEUE (default off) turns the split on; the bus
            # count is kept in self._last_zone_bus_cnt for diagnostics so the two
            # populations can be compared rather than assumed.
            _micro = bool(globals().get('MICRO_QUEUE_MODE', False))
            _vq_kmh = float(globals().get('MICRO_QUEUE_SPEED_KMH', 5.0))
            _excl_bus = bool(globals().get('EXCLUDE_BUS_FROM_CAR_QUEUE', False))
            try:
                _bus_pos = int(getattr(self, 'bus_type_pos', None)
                               or getattr(self.stats, '_bus_pos', -1) or -1)
            except Exception:
                _bus_pos = -1
            for _i in range(_n):
                try:
                    _inf = AKIVehStateGetVehicleInfSection(int(_cs), _i)
                    _pos = float(getattr(_inf, 'CurrentPos', 0.0) or 0.0)
                    _d = _dist_base + (_L - _pos)
                    if 0.0 <= _d <= zone:
                        if _excl_bus and _bus_pos > 0 and \
                                int(getattr(_inf, 'type', -1) or -1) == _bus_pos:
                            _bus_in_zone += 1
                            continue      # bus: tracked via the PT APIs, not here
                        if _micro and float(getattr(_inf, 'CurrentSpeed', 0.0) or 0.0) > _vq_kmh:
                            continue      # moving -> not in queue (Aimsun definition)
                        cnt += 1
                except Exception:
                    continue
        try:
            self._last_zone_bus_cnt = _bus_in_zone
        except Exception:
            pass
        return cnt, (_zone_lane_m if _zone_lane_m > 0.0 else None), _why

    def _flow_stage_snapshot(self):
        """Compact flow REGIME the controller is deciding on (no new API calls).

        Returns dict(stage, main_x, side_max_flow, queue_veh, armed): stage in
        FREE (x<0.6, small queue) / SAT (0.6-0.85) / OVER (0.85-1.0 or big
        queue) / JAM (x>=1 or disarmed-on-saturation). main_x = max main
        approach flow / saturation; queue = max MaxQueueLength cell. Cheap:
        reads cached UpFlowList/SideUpFlowList/MaxQueueLength/_tsp_armed only,
        so it is safe to call on every decision + every 60 s [FLOW_STAGE] tick.
        """
        try:
            import numpy as _np
            _q_sat = max(float(getattr(self, 'SaturationFlow', 1800.0) or 1800.0), 1.0)
            try:
                _upf = _np.asarray(getattr(self, 'UpFlowList', [0.0]),
                                   dtype=float).ravel()
                _upf = _upf[_upf > 0.0]
                _main_flow = float(_np.max(_upf)) if _upf.size else 0.0
            except Exception:
                _main_flow = 0.0
            # Busiest MEASURED approach floor (2026-09-26): UpFlowList rows can
            # still be a broadcast mean when the phase map is unresolved; never
            # under-read main congestion -- take the max with the per-section
            # measured flow.
            try:
                _stats = globals().get('stats', None) or getattr(self, 'stats', None)
                _ls = getattr(_stats, 'latest_section', None) if _stats is not None else None
                if _ls:
                    for _s in (getattr(self, 'incoming_sections', []) or []):
                        _st = _ls.get(int(_s))
                        if not _st:
                            continue
                        _q = float(_st.get('q', 0.0) or 0.0)
                        if _q > _main_flow:
                            _main_flow = _q
            except Exception:
                pass
            _main_x = _main_flow / _q_sat
            try:
                _suf = _np.asarray(getattr(self, 'SideUpFlowList', [0.0]),
                                   dtype=float).ravel()
                _side_max = float(_np.max(_suf)) if _suf.size else 0.0
            except Exception:
                _side_max = 0.0
            try:
                _mq = _np.asarray(getattr(self, 'MaxQueueLength', [[0.0]]),
                                  dtype=float).ravel()
                _queue = float(_np.max(_mq)) if _mq.size else 0.0
            except Exception:
                _queue = 0.0
            _armed = bool(getattr(self, '_tsp_armed', True))
            if not _armed or _main_x >= 1.0 or _queue >= 12.0:
                _stage = "JAM"
            elif _main_x >= 0.85 or _queue >= 6.0:
                _stage = "OVER"
            elif _main_x >= 0.60 or _queue >= 3.0:
                _stage = "SAT"
            else:
                _stage = "FREE"
            return {"stage": _stage, "main_x": round(_main_x, 3),
                    "side_max_flow": round(_side_max, 1),
                    "queue_veh": round(_queue, 1), "armed": _armed}
        except Exception:
            return {"stage": "UNK", "main_x": 0.0, "side_max_flow": 0.0,
                    "queue_veh": 0.0, "armed": True}

    def _sec_lane_count(self, sec_id):
        """Live lane count for a section (central + side, NumberLanes fallback)."""
        try:
            _g = AKIInfNetGetSectionANGInf(int(sec_id))
            if getattr(_g, 'report', -1) < 0:
                return 0
            _n = (int(getattr(_g, 'nbCentralLanes', 0) or 0)
                  + int(getattr(_g, 'nbSideLanes', 0) or 0))
            if _n <= 0:
                _n = int(getattr(_g, 'NumberLanes', 0) or 0)
            return max(int(_n), 0)
        except Exception:
            return 0

    def _phase_movement_map(self):
        """Per-phase movement map: what each phase actually serves (2026-09-27).

        Joins phase -> signal groups -> turning pairs -> origin lanes, with
        each turning role-labelled against _classify_turnings (MAIN = bus-phase
        turnings, SIDE = conflicting) and each origin section lane-counted, so
        the controller knows e.g. "phase 3 serves 2 side-street turnings from
        1-lane section 8257" instead of "phase 3 = 33 s". Cached per junction;
        read-only API calls. Returns {} if the plan can't be read.
        """
        try:
            if isinstance(getattr(self, '_phase_movement_cache', None), dict):
                return self._phase_movement_cache
        except Exception:
            pass
        _map = {}
        try:
            _jid = int(getattr(self, 'node_id', 0) or 0) or int(self.id)
            try:
                _n_ph = int(ECIGetNumberofPhases(_jid))
            except Exception:
                try:
                    _n_ph = int(ECIGetNumberPhases(_jid))
                except Exception:
                    _n_ph = 0
            if _n_ph < 1:
                return {}
            _main_turns, _side_turns = self._classify_turnings()
            for _ph in range(1, _n_ph + 1):
                try:
                    _dur = round(float(GetPhaseDuration(
                        self.node_id, _ph, 0.0) or 0.0), 1)
                except Exception:
                    _dur = 0.0
                _sgs = set()
                try:
                    _nsg = int(ECIGetNbSignalGroupsPhaseofJunction(
                        _jid, _ph, 0.0))
                    for _pos in range(1, _nsg + 1):
                        try:
                            _sg = int(ECIGetSignalGroupPhaseofJunction(
                                _jid, _ph, _pos, 0.0))
                            if _sg > 0:
                                _sgs.add(_sg)
                        except Exception:
                            pass
                except Exception:
                    pass
                _turns = set()
                for _sg in _sgs:
                    try:
                        _nt = int(ECIGetNumberTurningsofSignalGroup(
                            _jid, int(_sg)))
                        for _ti in range(max(_nt, 0)):
                            try:
                                _fp = intp(); _tp = intp()
                                ECIGetFromToofTurningofSignalGroup(
                                    _jid, int(_sg), _ti, _fp, _tp)
                                _fr = int(_fp.value()); _to = int(_tp.value())
                                if _fr > 0 and _to > 0:
                                    _turns.add((_fr, _to))
                            except Exception:
                                continue
                    except Exception:
                        pass
                _origins = {}
                _n_main = _n_side = 0
                for (_fr, _to) in _turns:
                    if (_fr, _to) in _main_turns:
                        _n_main += 1
                    else:
                        _n_side += 1
                    if _fr not in _origins:
                        _origins[_fr] = self._sec_lane_count(_fr)
                _map[_ph] = {"dur_s": _dur, "sgs": sorted(_sgs),
                             "n_turns": len(_turns), "n_main": _n_main,
                             "n_side": _n_side, "origins": _origins,
                             "turns": sorted(_turns)}
            try:
                self._phase_movement_cache = _map
            except Exception:
                pass
            # Seed the GLOBAL plan-state tracker with the as-built plan so
            # downstream delay estimators read a full per-phase plan from t=0.
            try:
                _PLAN_STATE[int(self.id)] = {
                    "durs": {int(_ph): float(_e["dur_s"])
                             for _ph, _e in _map.items()},
                    "cycle_s": sum(float(_e["dur_s"]) for _e in _map.values()),
                    "bus_phase": int(getattr(self, 'BusPhase', -1) or -1),
                    "version": 0,
                    "t": -1.0,
                }
            except Exception:
                pass
            # ── Live plan capture for the SUMO converter (2026-09-28) ──
            # The export dump's sg_states/signal_groups are empty, so the
            # converter falls back to synthetic 2-phase programs. This dumps
            # the LIVE plan instead: per-phase durations + signal groups +
            # turning pairs, exactly what plan_to_tls.py needs. Accumulates
            # across junctions, flushes once all managed junctions reported.
            try:
                global _PLAN_DUMP
                try:
                    _pd = _PLAN_DUMP
                    if not isinstance(_pd, dict):
                        _pd = {}
                        _PLAN_DUMP = _pd
                except Exception:
                    _pd = {}
                    _PLAN_DUMP = _pd
                _pd[int(self.id)] = {
                    "bus_phase": int(getattr(self, 'BusPhase', -1) or -1),
                    "phases": {str(_ph): {
                        "dur_s": _e["dur_s"], "sgs": _e["sgs"],
                        "turns": [[int(a), int(b)] for (a, b) in
                                  _e["turns"]]}
                        for _ph, _e in _map.items()},
                }
                _need = int(globals().get('PLAN_DUMP_MIN_JUNCTIONS', 23) or 23)
                if len(_pd) >= _need:
                    try:
                        _ld = os.path.dirname(LOG_FILE)
                    except Exception:
                        _ld = ""
                    if _ld and os.path.isdir(_ld):
                        import datetime as _dt_mod
                        _fn = ("plan_dump_%s.json" % _dt_mod.datetime.now(
                            ).strftime("%Y%m%d_%H%M%S"))
                        _fp = os.path.join(_ld, _fn)
                        if not os.path.isfile(_fp):
                            import json as _js_mod
                            with open(_fp, "w",
                                      encoding="utf-8") as _fh:
                                _js_mod.dump(
                                    {"engine_build": str(globals().get(
                                        'ENGINE_BUILD', '?')), "junctions": {
                                            str(k): v for k, v in
                                            _pd.items()}}, _fh)
                            log_to_file(
                                f"[PLANDUMP] wrote {_fp} "
                                f"({len(_pd)} junctions)", force=True)
            except Exception:
                pass
            # One observability line per junction: which phases serve side
            # streets/turns, from how many lanes.
            try:
                _bits = []
                for _ph in sorted(_map):
                    _e = _map[_ph]
                    _org = ",".join("%d:%dln" % (_s, _e["origins"][_s])
                                    for _s in sorted(_e["origins"]))
                    _bits.append("ph%d=%ds turns=%d(main%d/side%d) [%s]" % (
                        _ph, _e["dur_s"], _e["n_turns"], _e["n_main"],
                        _e["n_side"], _org))
                log_to_file(f"[PHASEMAP] inter={self.id} " + " ".join(_bits),
                            force=True)
                # Main-movement openness: the signal settings read AT the main
                # (paper eq:main_open / eq:main_green). The main movement is
                # served by the bus phase; its openness = that phase's green
                # share of the cycle, with how many main turnings it carries.
                try:
                    _mb = _map.get(int(getattr(self, 'BusPhase', -1) or -1))
                    if _mb:
                        _cyc_m = sum(float(e["dur_s"]) for e in _map.values())
                        _g = float(_mb.get("dur_s", 0.0))
                        log_to_file(
                            f"[MAIN_OPEN] inter={self.id} "
                            f"main_ph={int(getattr(self, 'BusPhase', -1) or -1)} "
                            f"green={_g:.1f}s/{_cyc_m:.1f}s = "
                            f"{100.0 * _g / _cyc_m if _cyc_m > 0 else 0.0:.0f}% cycle "
                            f"main_turnings={int(_mb.get('n_main', 0))} "
                            f"(x_main = bus-phase gate)", force=True)
                except Exception:
                    pass
            except Exception:
                pass
        except Exception:
            return {}
        return _map

    def _apply_headroom_reserve(self, timeSta=0.0):
        """Carve repayable slack into the plan once at startup (2026-09-28).

        HEADROOM_RESERVE_S>0 moves RESERVE seconds from the bus phase to EACH
        non-bus phase (cycle conserved, bus floored at min green). Cross phases
        then sit RESERVE above minimum, giving _reward_get_recoverable a real
        budget so recovery trims can actually fire. Costs main capacity by
        RESERVE x n_cross s/cycle. Returns (added_s, n_cross, bus_before,
        bus_after) for the [HEADROOM] line; any failure leaves the plan as-is.
        """
        _added = _n_cross = 0.0
        _bus0 = _bus1 = 0.0
        try:
            if float(globals().get('HEADROOM_RESERVE_S', 0.0) or 0.0) <= 0.0:
                return (_added, _n_cross, _bus0, _bus1)
            _r = float(globals().get('HEADROOM_RESERVE_S', 0.0) or 0.0)
            try:
                _n = int(ECIGetNumberofPhases(self.node_id))
            except Exception:
                try:
                    _n = int(ECIGetNumberPhases(self.node_id))
                except Exception:
                    _n = 0
            if _n < 2:
                return (_added, _n_cross, _bus0, _bus1)
            _bp = int(getattr(self, 'BusPhase', -1) or -1)
            _durs = {}
            for _ph in range(1, _n + 1):
                try:
                    _durs[_ph] = float(GetPhaseDuration(
                        self.node_id, _ph, timeSta) or 0.0)
                except Exception:
                    _durs[_ph] = 0.0
            _nonbus = [p for p in _durs if p != _bp and _durs[p] > 0.0]
            if not _nonbus or _bp not in _durs:
                return (_added, _n_cross, _bus0, _bus1)
            _floor = float(globals().get('MIN_GREEN_FLOOR_S', 5.0) or 5.0)
            _bus_cap = max(0.0, float(_durs[_bp]) - _floor)
            _need = float(len(_nonbus)) * _r
            _r_eff = min(_r, _bus_cap / max(len(_nonbus), 1.0)) if _need > 0 else 0.0
            if _r_eff <= 0.0:
                return (_added, _n_cross, _bus0, _bus1)
            _bus0 = float(_durs[_bp])
            for _ph in _nonbus:
                _new = float(_durs[_ph]) + _r_eff
                try:
                    ECIChangeTimingPhase(self.node_id, int(_ph), _new, timeSta)
                    _durs[_ph] = _new
                    _added += _r_eff
                    _n_cross += 1
                except Exception:
                    continue
            _bus1 = float(_durs[_bp]) - _r_eff * len(_nonbus)
            try:
                ECIChangeTimingPhase(self.node_id, int(_bp), _bus1, timeSta)
            except Exception:
                _bus1 = float(_durs[_bp])
            # invalidate caches so solvers/gates see the carved plan
            self._signal_cycle_cache = 0.0
            self._coord_phase_cache = None
            self._coord_base_dur = None
        except Exception:
            pass
        return (_added, _n_cross, _bus0, _bus1)

    def _apply_retime_csv(self, timeSta=0.0):
        """Apply offline-retimed splits once per junction (2026-09-28).

        Reads RETIME_CSV (RETIME_CSV flag or <bundle>/retime/retime_v1.csv),
        sets each listed stage-green duration via ECI when it differs by
        >=0.5 s, then re-reads to verify. Splits only (v1): starts shift by
        construction; the residual offset walk is stage 2. Any failure or
        mismatch fails SAFE (log + continue on the base plan). Returns
        (applied, verified, total) for the [RETIME] line.
        """
        _applied = _verified = _total = 0
        try:
            if not bool(globals().get('RETIME_APPLY', False)):
                return (_applied, _verified, _total)
            global _RETIME_ROWS
            try:
                _cache = _RETIME_ROWS
            except Exception:
                _cache = None
            if not isinstance(_cache, dict):
                _csv_path = str(globals().get('RETIME_CSV', '') or '')
                if not _csv_path or not os.path.isfile(_csv_path):
                    for _cand in (
                            os.path.join(os.path.dirname(os.path.abspath(
                                __file__)), "..", "retime", "retime_v1.csv"),
                            r"C:\Users\ahernz\github_for_aimsun\bcc113_bundle_v5"
                            r"\retime\retime_v1.csv"):
                        if os.path.isfile(_cand):
                            _csv_path = _cand
                            break
                _cache = {}
                if _csv_path and os.path.isfile(_csv_path):
                    import csv as _csv_mod
                    with open(_csv_path, encoding="utf-8-sig") as _fh:
                        for _r in _csv_mod.DictReader(_fh):
                            try:
                                _g = {}
                                for _part in str(
                                        _r.get("stage_greens_s", "")).split(";"):
                                    if "=" in _part:
                                        _k, _v = _part.split("=")
                                        _g[int(_k)] = float(_v)
                                _cache[str(_r.get("junction"))] = {
                                    "greens": _g,
                                    "offset": float(
                                        _r.get("offset_bus_green_start_s",
                                               0.0) or 0.0),
                                }
                            except Exception:
                                continue
                _RETIME_ROWS = _cache
            _row = ( _cache or {}).get(str(int(self.id)))
            if not _row:
                return (_applied, _verified, _total)
            for _ph, _tgt in sorted(_row["greens"].items()):
                _total += 1
                try:
                    _cur = float(GetPhaseDuration(
                        self.node_id, int(_ph), timeSta) or 0.0)
                except Exception:
                    continue
                if abs(_cur - float(_tgt)) < 0.5:
                    _verified += 1
                    continue
                try:
                    ECIChangeTimingPhase(self.node_id, int(_ph),
                                         float(_tgt), timeSta)
                    _applied += 1
                except Exception:
                    continue
                try:
                    _chk = float(GetPhaseDuration(
                        self.node_id, int(_ph), timeSta) or 0.0)
                    if abs(_chk - float(_tgt)) < 0.5:
                        _verified += 1
                except Exception:
                    pass
        except Exception:
            pass
        return (_applied, _verified, _total)

    def _log_startup_plan(self, time):
        """One-time as-designed fixed-time plan snapshot per junction.

        The initial signal plans are set up for a reason (corridor
        coordination): this dumps the programmed plan -- phase count and
        durations, cycle sum, bus phase + duration, longest (coordinated)
        phase, live phase + its start time -- so the [FLOW_STAGE] stream from
        t=1 can be read against the plan it runs on (splits/offsets vs actual
        FREE/SAT/OVER/JAM regime from startup). Runs once; read-only API
        calls except the optional RETIME_APPLY splits load (verified,
        fail-safe); never touches per-step control.
        """
        if bool(getattr(self, '_plan_logged', False)):
            return
        self._plan_logged = True
        # Offline-retimed splits (v1) go FIRST so the [PLAN] snapshot below
        # reads the running plan, and the whole run (including NO_TSP
        # baselines) sits on it. Read-back verified; fails safe to base.
        _rt_mode = ""
        try:
            if bool(globals().get('RETIME_APPLY', False)):
                _ra, _rv, _rt = self._apply_retime_csv(0.0)
                _rt_mode = ("RETIMED" if _rt > 0 and _rv == _rt
                            else "BASE-PLAN")
                log_to_file(
                    f"[RETIME] inter={self.id} t={time:.0f} "
                    f"applied={_ra} verified={_rv}/{_rt} {_rt_mode}",
                    force=True)
        except Exception:
            pass
        # Headroom reserve (2026-09-28): carve repayable slack into the plan
        # so recovery trims can fire. Applies after any retime load so the
        # [PLAN] snapshot reads the final running plan.
        try:
            if float(globals().get('HEADROOM_RESERVE_S', 0.0) or 0.0) > 0.0:
                _ha, _hc, _hb0, _hb1 = self._apply_headroom_reserve(0.0)
                if _hc > 0:
                    log_to_file(
                        f"[HEADROOM] inter={self.id} t={time:.0f} "
                        f"reserve={_ha / max(_hc, 1):.1f}s x {_hc} cross "
                        f"phases, bus {_hb0:.1f}s -> {_hb1:.1f}s "
                        f"(repayable budget carved)", force=True)
        except Exception:
            pass
        try:
            try:
                _n = int(ECIGetNumberofPhases(self.node_id))
            except Exception:
                try:
                    _n = int(ECIGetNumberPhases(self.node_id))
                except Exception:
                    _n = 0
            _durs = {}
            for _ph in range(1, _n + 1):
                try:
                    _durs[_ph] = round(
                        float(GetPhaseDuration(self.node_id, _ph, 0.0) or 0.0), 1)
                except Exception:
                    _durs[_ph] = 0.0
            _cyc = round(sum(max(0.0, _v) for _v in _durs.values()), 1)
            try:
                _cur = int(ECIGetCurrentPhase(self.node_id))
            except Exception:
                _cur = -1
            try:
                _ps = round(float(ECIGetStartingTimePhase(self.node_id)), 1)
            except Exception:
                _ps = -1.0
            try:
                _bp = int(getattr(self, 'BusPhase', -1))
            except Exception:
                _bp = -1
            _bpd = float(_durs.get(_bp, 0.0))
            _coord = max(_durs, key=lambda _k: _durs[_k]) if _durs else -1
            try:
                _cfg = float((getattr(self, 'config', {}) or {}).get(
                    'CycleTime', 0.0) or 0.0)
            except Exception:
                _cfg = 0.0
            log_to_file(
                f"[PLAN] inter={self.id} t={time:.0f} n_ph={_n} durs={_durs} "
                f"cycle_sum={_cyc:.1f}s cfg_cyc={_cfg:.0f}s bus_ph={_bp} "
                f"bus_dur={_bpd:.1f}s coord_ph={_coord} cur_ph={_cur} "
                f"ph_start={_ps:.1f}s "
                f"({'retimed' if _rt_mode == 'RETIMED' else 'as-designed fixed-time plan'})",
                force=True)
            # Phase->movement semantics (lanes, side streets, turns) for the
            # same startup diagnosis: which phases serve what.
            try:
                self._phase_movement_map()
            except Exception:
                pass
        except Exception as _e:
            try:
                log_to_file(f"[PLAN] inter={self.id} error {_e!r}")
            except Exception:
                pass

    def _sample_side_sections(self, time):
        """
        Virtual detector for side sections using instantaneous density.

        Scans live vehicle count on each side section, converts to density
        via section length (AKIInfNetGetSectionANGInf), then derives flow
        from the LWR triangular model. No aggregation periods needed.
        """
        # ── As-designed plan snapshot (2026-09-27): one [PLAN] line per
        # junction on its first tick -- the initial fixed-time plan exists for
        # a reason (coordination), so join it to the [FLOW_STAGE] stream to
        # diagnose flow from startup (plan splits/offsets vs actual regime).
        # Placed before the no-sides early return so sideless junctions log too.
        try:
            self._log_startup_plan(time)
        except Exception:
            pass
        side_secs = self._get_side_sections()
        if not side_secs:
            return

        self._ensure_side_section_arrays(side_secs, time)

        _nveh_log = []
        _len_log  = []

        # Pre-compute main corridor flow as a turning-ratio reference for virtual sections.
        # Use the mean of non-zero values from UpFlowList (main approach detector readings).
        _main_flow_ref = 0.0
        try:
            _uf = np.asarray(self.UpFlowList, dtype=float).ravel()
            _uf_pos = _uf[_uf > 0.0]
            if _uf_pos.size > 0:
                _main_flow_ref = float(np.mean(_uf_pos))
        except Exception:
            pass

        for idx, sec_id in enumerate(side_secs):
            # Zoned virtual detector: vehicles near the stop line only,
            # walking upstream across short sections (chain length returned
            # alongside the count -- a 7 m section alone cannot hold a queue).
            n_veh, _chain_len_m, _chain_why = self._zone_queue_count(sec_id)
            _in_sim = True

            # Resolve geometry — skip density computation if geometry is invalid.
            # Lanes come from the stop-line section; the density LENGTH is the
            # queue-chain length (capped at the zone), not the single section.
            sec_len_m   = None
            n_lanes_sec = 1
            try:
                _sec_inf = AKIInfNetGetSectionANGInf(sec_id)
                if getattr(_sec_inf, 'report', -1) >= 0:
                    _raw_len = float(_sec_inf.length)
                    if _raw_len > 0.0:
                        sec_len_m   = _raw_len
                        n_lanes_sec = max(int(_sec_inf.nbCentralLanes) + int(_sec_inf.nbSideLanes), 1)
            except Exception:
                pass

            geom_valid = (_chain_len_m or sec_len_m) is not None and ((_chain_len_m or sec_len_m) or 0.0) > 0.0

            # Tier 0: continuous rolling window-count — every vehicle that
            # crossed `sec_id` in the last 5 min (live-detection tracking).
            # Highest fidelity: the counter never misses a passthrough the way
            # an occupancy snapshot at an empty instant does.
            _roll_flow = self._section_window_flow(
                sec_id, time, 300.0,
                sec_len_hint=float(_chain_len_m or sec_len_m or 0.0))

            if _roll_flow > 0.0:
                _side_cap = float(self.SaturationFlow) * max(int(n_lanes_sec), 1)
                flow    = min(_roll_flow, _side_cap)
                density = flow * float(self.SaturationDensity) / max(float(self.SaturationFlow), 1.0)
            elif _in_sim and n_veh > 0 and geom_valid:
                # Queued vehicles over the upstream chain -- use density from
                # the chain vehicle count over the chain length (capped at the
                # zone), NOT the single stop-line section (a 7 m virtual link
                # would read ~1 car as gridlock).
                _eff_len_m = min(float(_chain_len_m or sec_len_m or 0.0),
                                 float(self._queue_zone_m(False)))
                density_per_lane = n_veh / n_lanes_sec / max(_eff_len_m / 1000.0, 0.001)
                k_sat  = max(float(self.SaturationDensity), 1.0)
                k_jam  = max(float(self.JamDensity),        k_sat + 1.0)
                k      = min(density_per_lane, k_jam)
                if k <= k_sat:
                    flow = k * self.SaturationFlow / k_sat
                else:
                    flow = self.SaturationFlow * (k_jam - k) / max(k_jam - k_sat, 1.0)
                density = k
            else:
                # Section not in dynamic simulation (-4002), empty, or geometry invalid.
                # Estimate arrival flow using section-level accumulated stats first,
                # then a turning-ratio from the main approach, then a small default.
                _est_flow = 0.0

                # Tier 1: section-specific cumulative stats (most accurate for virtual secs)
                try:
                    _sg = AKIEstGetGlobalStatisticsSection(sec_id, -1)
                    if getattr(_sg, 'report', -1) == 0 and float(getattr(_sg, 'count', 0) or 0) > 0 and time > 0:
                        _est_flow = float(_sg.count) / max(time / 3600.0, 1.0 / 3600.0)
                except Exception:
                    pass

                # Tier 2: current-interval MEASURED flow (veh/h). BUGFIX (2026-09-25):
                # the old call passed (time-300) as the 2nd arg to
                # AKIEstGetParcialStatisticsSection, but that API wants the STATS-
                # INTERVAL time (timeSta) -- an arbitrary sim time never matches an
                # interval, so it always returned count=0 (the "roll_ctr=0 everywhere
                # despite n_veh>0" symptom, and Tier-2 measurement never landing ->
                # side flow fell back to the seed prior / saturation, over-pricing
                # the cross cost). AKIEstGetCurrentStatisticsSection needs no timeSta
                # and returns the current interval's Flow directly; report!=0 / 0 for
                # virtual/unmeasurable sections (honest -> Tier 3/4 handle those).
                if _est_flow <= 0.0:
                    try:
                        _sp = AKIEstGetCurrentStatisticsSection(sec_id, -1)
                        if getattr(_sp, 'report', -1) == 0:
                            _est_flow = max(0.0, float(getattr(_sp, 'Flow', 0.0) or 0.0))
                    except Exception:
                        pass

                # Tier 3: turning-ratio estimate from main approach flow.
                # Minor approaches typically carry 10-20% of the main corridor flow.
                if _est_flow <= 0.0 and _main_flow_ref > 0.0:
                    _est_flow = _main_flow_ref * 0.15

# Tier 4: no Aimsun evidence and zone empty -> faithful zero.
                # Previously 400/180 priced an empty 50m zone as busy and
                # blocked good TSP opportunities on Logan. Zero is the honest
                # prior; if traffic appears, Tiers 0-2 will capture it next tick.
                if _est_flow <= 0.0:
                    _est_flow = 0.0

                # ── Corridor viability gate (2026-08-26; units fixed 2026-08-27;
                #  enforced 2026-09-12) ──────────────────────────────────────
                # If cross-street pressure is too high relative to bus demand,
                # or approaches sit at jam storage, the junction stands down
                # to the fixed-time plan: intervening can only compound debt
                # into gridlock (proven KG seed variance: MARL 163-246,
                # BARGAIN 95-202 on identical trip counts -- bad seeds are the
                # ones where actions hurt cars AND buses). Previously this
                # block computed _viable but NOTHING consumed _tsp_armed (never
                # armed, never enforced) and the disarm arm called a
                # request_phase() method that does not exist -- the gate was
                # dead three ways over. Now: arm at init/per-run reset, enforce
                # in run_reward_tsp + check_bus_priority, hysteresis re-arm.
                # UNITS FIX: the original compared _est_flow (veh/h) against
                # CUMULATIVE bus pax served (starts at 0), so the ratio opened in
                # the hundreds and the gate withdrew TSP for long stretches at the
                # start of every run. Compare LIKE UNITS instead: cross pax/h
                # (veh/h x CarOcc) vs bus pax/h (cumulative pax / elapsed hours),
                # and give a grace period while there is no bus data yet.
                _bus_pax_today = float(getattr(self, '_bus_pax_served_today', 0) or 0)
                _elapsed_h = max(float(time), 1.0) / 3600.0
                _bus_pax_rate = _bus_pax_today / max(_elapsed_h, 1e-6)   # pax/h
                _car_occ_vg = max(safe_float(getattr(self, 'CarOcc', 1.2)), 1.0)
                _cross_pax_rate = max(_est_flow, 0.0) * _car_occ_vg      # pax/h
                # Corridor-specific viability threshold
                _corridor_dir = globals().get('_CORRIDOR_DIR', '') or ''
                _is_logan = 'logan' in _corridor_dir.lower()
                _threshold = 3.5 if _is_logan else 2.5  # Logan: higher tolerance
                if float(time) < 600.0 or _bus_pax_rate <= 0.0:
                    _viable = True   # no bus evidence yet -- do not disarm on air
                    _ratio_breach = False
                    _ratio_clear = True
                else:
                    _cross_ratio = _cross_pax_rate / _bus_pax_rate
                    _viable = _cross_ratio <= _threshold
                    _ratio_breach = not _viable
                    _ratio_clear = _cross_ratio <= _threshold * 0.7
                # Storage saturation: max approach density ratio (main slots +
                # side slots, last-known). A junction at jam storage cannot
                # discharge anything granted it -- stand down.
                _sat = 0.0
                try:
                    _kjam = max(float(getattr(self, 'JamDensity', 150.0)) or 150.0, 1.0)
                    _dens = []
                    try:
                        for _row in (getattr(self, 'UpDenList', []) or []):
                            try:
                                for _v in _row:
                                    _dens.append(float(_v))
                            except TypeError:
                                _dens.append(float(_row))
                    except Exception:
                        pass
                    try:
                        for _sv in (getattr(self, 'SideUpDenList', []) or []):
                            _dens.append(float(_sv))
                    except Exception:
                        pass
                    if _dens:
                        _sat = max(0.0, max(_dens) / _kjam)
                except Exception:
                    pass
                _gate_on = bool(globals().get('DCTSP_CONGESTION_GATE', False))
                try:
                    _frac = float(globals().get('DCTSP_CONGESTION_GATE_FRACTION', 0.70) or 0.70)
                except Exception:
                    _frac = 0.70
                try:
                    _new_armed, _changed, _why = _viability_update(
                        getattr(self, '_tsp_armed', True), _gate_on,
                        _ratio_breach, _ratio_clear, _sat, _frac)
                except Exception:
                    _new_armed, _changed, _why = True, False, None
                if _changed:
                    self._tsp_armed = bool(_new_armed)
                    try:
                        log_to_file(
                            f"[VIABILITY] inter={self.id} t={time:.0f}s "
                            f"{'DISARM' if not _new_armed else 'RE-ARM'} "
                            f"({_why}) ratio_breach={_ratio_breach} "
                            f"sat={_sat:.2f}/{_frac:.2f}", force=True)
                    except Exception:
                        pass

                # ── MaxPressure cyclic coordination guard ───────────────────────
                # MaxPressure-FIX only activates when the corridor viability gate
                # passes (cross-street pressure is not dominant). This prevents
                # the moving-wave gridlock seen in the first run where cyclic
                # phase switching across junctions created permanent conflicts.
                if getattr(self, '_tsp_armed', False) and not _viable:
                    # TSP already disabled by viability gate — skip MP entirely
                    pass

                flow    = min(_est_flow, float(self.SaturationFlow))
                density = flow * float(self.SaturationDensity) / max(self.SaturationFlow, 1.0)
            # NOTE (2026-09-16): flow intentionally carries the DEMAND SEED
            # (section's demand-rated arrival rate) before measurement -- a valid
            # prior so extending red still prices the cross demand that arrives
            # during the red. The earlier count-based cap was REVERTED (it wrongly
            # zeroed that arrival term). The misleading part was `roll_ctr` in the
            # [SIDE_SCAN] log echoing this seed instead of the true observed count;
            # that is fixed in the log (roll_ctr = measured window count, 0 at
            # warm-up), keeping flow=seed and roll_ctr=0 distinct.

            self.SideUpFlowList[idx]      = flow
            self.SideUpDenList[idx]       = density
            self.SideShockwaveSpeed1[idx] = ShockwaveSpeed1(flow, self.JamDensity, density)
            self.SideShockwaveSpeed3[idx] = ShockwaveSpeed3(
                self.SaturationFlow, flow, self.SaturationDensity, density)
            _nveh_log.append(n_veh)
            # Log chain reach + stop reason (zone/dead/managed/main/...),
            # so a bare "7.0" reads as what it is, e.g. 7.0[dead] (entry
            # section, nothing upstream) vs 7.0[managed] (stopped at the
            # upstream signal -- correct, not a failure).
            _lv = (round(_chain_len_m, 0) if _chain_len_m is not None
                   else (round(sec_len_m, 0) if sec_len_m is not None else 'N/A'))
            _len_log.append(f"{_lv}[{_chain_why}]")

        # Throttle: only log every 60 s to avoid flooding the log file
        if not hasattr(self, '_side_scan_log_t'):
            self._side_scan_log_t = -999.0
        if time - self._side_scan_log_t >= 60.0:
            self._side_scan_log_t = time
            # flow = the estimate actually used (SideUpFlowList) -- carries the
            # DEMAND SEED (a prior) before measurement. roll_ctr = the TRUE
            # measured rolling count from Aimsun's partial stats (0 until a real
            # passthrough is counted; 0 for virtual sections that can't be
            # measured). These were previously the SAME array, so roll_ctr
            # misleadingly echoed the seed (e.g. 3600 at t=1 with n_veh=0);
            # separating them makes "seed vs measured" visible (2026-09-16).
            _flow_vals = [round(float(v), 1) for v in self.SideUpFlowList]
            _meas_roll = []
            for _ss in side_secs:
                # MEASURED flow (veh/h) from live count x space-mean speed -- works
                # on virtual/modeled sections where AKIEstGetCurrentStatisticsSection
                # reports Flow=0 (the roll_ctr=0 blind spot). Fall back to Aimsun's
                # own section flow if the count-based one is 0 (e.g. moving free flow
                # the count momentarily missed).
                _mf = 0.0
                try:
                    _mf = float(self._measured_section_flow_vph(int(_ss)))
                except Exception:
                    _mf = 0.0
                if _mf <= 0.0:
                    try:
                        _sp = AKIEstGetCurrentStatisticsSection(int(_ss), -1)
                        if getattr(_sp, 'report', -1) == 0:
                            _mf = max(0.0, float(getattr(_sp, 'Flow', 0.0) or 0.0))
                    except Exception:
                        pass
                _meas_roll.append(round(_mf, 1))
            # len_m tags: [dead]=verified network entry (NORMAL, nothing
            # upstream to miss); [main]/[managed]=correctly stopped at the
            # corridor / an upstream signal (NORMAL, that queue belongs
            # elsewhere); [zone]=full 60 m covered (NORMAL); +model=virtual
            # connector resolved via model topology (NORMAL). Only
            # apifail-node/apifail-turns/empty mean the walk itself failed and
            # a queue could be missed. roll_ctr=0 before ~300 s is NORMAL
            # warm-up (no passthrough counted yet); flow then carries the
            # OD-rated seed prior, NOT a measurement. A stale counter is only
            # a fault when t>600 s AND n_veh>0 AND roll stays 0 (vehicles
            # present but never counted) -- flagged as [noupdate] below.
            _stale = []
            try:
                if float(time) > 600.0:
                    for _i, (_ss, _mr, _nv) in enumerate(
                            zip(side_secs, _meas_roll, _nveh_log)):
                        if float(_mr) <= 0.0 and int(_nv or 0) > 0:
                            _stale.append(str(_ss))
            except Exception:
                _stale = []
            log_to_file(
                f"[SIDE_SCAN] inter={self.id} t={time:.0f} "
                f"secs={side_secs} "
                f"n_veh={_nveh_log} len_m={_len_log} "
                f"flow={_flow_vals} "
                f"flow_meas_vph={_meas_roll} "
                f"den={[round(float(v),2) for v in self.SideUpDenList]}"
                f"{' [noupdate stale=' + ','.join(_stale) + ']' if _stale else ''}",
                force=(int(time) % 300 == 0) or bool(_stale))
            # ── Flow STAGE (2026-09-25): the regime the decider sees, same
            # throttle as SIDE_SCAN so "what stage was junction N in?" is one
            # grep away. Uses cached lists only (no new API calls).
            try:
                if bool(globals().get('DIAG_FLOW_STAGE', True)):
                    _fs = self._flow_stage_snapshot()
                    log_to_file(
                        f"[FLOW_STAGE] inter={self.id} t={time:.0f} "
                        f"stage={_fs['stage']} main_x={_fs['main_x']:.2f} "
                        f"side_max={_fs['side_max_flow']:.0f}vph "
                        f"queue={_fs['queue_veh']:.0f} "
                        f"armed={int(_fs['armed'])}")
            except Exception:
                pass
            # ── [MAIN_SCAN] (2026-09-29): symmetric to SIDE_SCAN. Because the
            # corridor controller acts on DEMAND independent of buses, the BENEFIT
            # of extending green must reflect the MAIN-approach counts it actually
            # discharges -- not just the bus. Log live veh + measured flow on the
            # main (incoming) sections so "is there main demand to serve?" is one
            # grep away, and matches the live basis _measured_main_queue_veh uses.
            try:
                _main_secs = list(getattr(self, 'incoming_sections', []) or [])
                _mn_veh = []
                _mn_roll = []
                for _msx in _main_secs:
                    try:
                        _mn_veh.append(int(AKIVehStateGetNbVehiclesSection(int(_msx), False)))
                    except Exception:
                        _mn_veh.append(-1)
                    # MEASURED flow (veh/h) from live count x speed (works on virtual
                    # sections; car flow travelling WITH the bus on the main approach).
                    _mf = 0.0
                    try:
                        _mf = float(self._measured_section_flow_vph(int(_msx)))
                    except Exception:
                        _mf = 0.0
                    if _mf <= 0.0:
                        try:
                            _sp = AKIEstGetCurrentStatisticsSection(int(_msx), -1)
                            if getattr(_sp, 'report', -1) == 0:
                                _mf = max(0.0, float(getattr(_sp, 'Flow', 0.0) or 0.0))
                        except Exception:
                            pass
                    _mn_roll.append(round(_mf, 1))
                try:
                    _mq_meas = self._measured_main_queue_veh()
                except Exception:
                    _mq_meas = None
                log_to_file(
                    f"[MAIN_SCAN] inter={self.id} t={time:.0f} "
                    f"secs={_main_secs} n_veh={_mn_veh} flow_meas_vph={_mn_roll} "
                    f"served_q={'na' if _mq_meas is None else round(float(_mq_meas), 1)}",
                    force=(int(time) % 300 == 0))
            except Exception:
                pass
            # One-time signal-plan geometry dump (per-phase origin sections + real
            # length/lanes) so the scanned approaches can be checked vs the network.
            try:
                self._log_plan_scan(time)
            except Exception:
                pass

    def build_state(self):
        state = []
        for sec in self.incoming_sections:
            stat = AKIEstGetParcialStatisticsSection(
                sec, AKIGetCurrentSimulationTime(), 50)
            state.append(min(stat.count / 50.0, 1.0))

        bus_presence = 1.0 if np.any(self.BusPresence) else 0.0
        state.append(bus_presence)
        state.append(min(np.max(self.BusSpeed) / 20.0, 1.0) if bus_presence else 0.0)

        current_phase = ECIGetCurrentPhase(self.node_id)
        num_phases    = len(self.UpDetList)
        phase_one_hot = [0.0] * num_phases
        if 1 <= current_phase <= num_phases:
            phase_one_hot[current_phase - 1] = 1.0
        state.extend(phase_one_hot)

        start_time  = ECIGetStartingTimePhase(self.node_id)
        time_in_phase = AKIGetCurrentSimulationTime() - start_time
        state.append(min(time_in_phase / 60.0, 1.0))

        return np.array(state, dtype=np.float32)

    def collect_detector_data(self):
        """
        Update UpDetCountList from physical detectors where available.
        Also builds _det_sec_cache for the section-scan fallback used in
        update_queue_model when aggregated counts are still 0.
        """
        if not hasattr(self, '_prev_updet_counter'):
            self._prev_updet_counter = {}
        if not hasattr(self, '_det_sec_cache'):
            # Build once: {(i,j): (sec_id, sec_len_m)} for every valid detector
            self._det_sec_cache = {}
            for i in range(len(self.UpDetList)):
                for j, det_id in enumerate(self.UpDetList[i]):
                    props = AKIDetGetPropertiesDetectorById(det_id)
                    if props.report >= 0:
                        try:
                            sec_len = float(AKIInfNetGetSectionANGInf(props.IdSection).length)
                        except Exception:
                            sec_len = 50.0
                        self._det_sec_cache[(i, j)] = (props.IdSection, max(sec_len, 1.0))

        for i in range(len(self.UpDetList)):
            for j in range(len(self.UpDetList[i])):
                det_id = self.UpDetList[i][j]
                count = AKIDetGetCounterAggregatedbyId(det_id, 0)
                if count >= 0:
                    prev = self._prev_updet_counter.get(det_id)
                    if prev is None:
                        delta = max(count, 0)
                    elif count >= prev:
                        delta = count - prev
                    else:
                        delta = max(count, 0)
                    self._prev_updet_counter[det_id] = count
                    self.UpDetCountList[i][j] += delta

    def detect_bus_old(self, time):
        """
        Position-based continuous bus detection.

        Instead of polling whether a bus is physically over a detector at the
        exact 1-second tick, we scan ALL PT vehicles on call sections every
        step and compute their ETA to the stop line.  BusPresence[0][i] is
        set to 1 if any bus is within cycle_length seconds of arrival.
        BusSpeed[0][i] holds that bus's live speed in m/s.

        This eliminates missed detections caused by the 1-second sampling
        interval — a bus travelling at 50 km/h covers ~14 m per tick, so it
        can easily skip over a narrow detector zone.  Using live position data
        instead means we never miss it.
        """
        self.BusPresence[:] = 0
        self.BusSpeed[:]    = 0.0
        if not hasattr(self, '_bus_eta'):
            self._bus_eta = {}
        self._bus_eta.clear()
        self._detected_buses = []

        # Build det_sec_map: section_id -> [(det_index, det_distance_m, det_final_pos)]
        det_sec_map = {}
        for i, det_id in enumerate(self.BusDet):
            props = AKIDetGetPropertiesDetectorById(det_id)
            if props.report >= 0:
                sec = props.IdSection
                det_dist_group = self.config["DetDistance"][0]
                dist = det_dist_group[i] if i < len(det_dist_group) else 50.0
                det_sec_map.setdefault(sec, []).append((i, dist, props.FinalPosition))

        if not det_sec_map:
            # All physical detector IDs are invalid in this Aimsun model — fall back
            # to scanning incoming_sections directly with a default distance estimate.
            for sec_id in self.incoming_sections:
                try:
                    sec_len_m = float(AKIInfNetGetSectionANGInf(sec_id).length)
                except Exception:
                    sec_len_m = 50.0
                sec_len_m = max(sec_len_m, 1.0)
                det_sec_map[sec_id] = [(0, sec_len_m, sec_len_m)]

        if not det_sec_map:
            return

        lookahead = self.urtsp_cycle_length   # accept buses arriving within one cycle

        seen = set()

        def _record_detected_bus(det_idx, veh_id, speed_ms, remaining, eta,
                                 line_id=None):
            # ── stop-aware ETA bias learning ──────────────────────────────
            if BUS_ETA_BIAS_LEARN:
                now_s = (float(AKIGetCurrentSimulationTime())
                         if 'AKIGetCurrentSimulationTime' in globals() else 0.0)
                tr = _ETA_TRACK.get(veh_id)
                if tr is None:
                    if len(_ETA_TRACK) > 400:
                        for _k in list(_ETA_TRACK.keys())[:200]:
                            _ETA_TRACK.pop(_k, None)
                    _ETA_TRACK[veh_id] = {"t0": now_s, "eta0": eta,
                                          "line": line_id}
                elif not tr.get("done") and remaining <= _ETA_ARRIVAL_M:
                    tr["done"] = True
                    err = now_s - (tr["t0"] + tr["eta0"])
                    lk = tr.get("line") or "unk"
                    _eta_bias_update(lk, err)

            # ── schedule adherence: set this bus's priority multiplier ────
            try:
                _sched_adherence_on_detect(self, line_id, remaining, veh_id)
                _trk_new = _ETA_TRACK.get(veh_id)
                if _trk_new is not None:
                    _trk_new["mult"] = float(
                        getattr(self, "_cur_sched_mult", 1.0))
            except Exception:
                pass

            # ── ETA uncertainty stash for certainty-level scoring ─────────
            try:
                _coord = getattr(self, "_corridor_coord", None)
                _trk = getattr(_coord, "_trackers", {}).get(int(veh_id)) \
                    if _coord is not None else None
                if _trk is not None and hasattr(_trk, "uncertainty_for_remaining"):
                    sig = float(_trk.uncertainty_for_remaining(remaining))
                else:
                    sig = 0.15 * max(eta, 1.0)      # fallback: ~15% of eta
                self._cur_eta_sigma_s = max(0.5, min(sig, 45.0))
                self._cur_eta_sigma_rel = self._cur_eta_sigma_s / max(eta, 1.0)
            except Exception:
                pass

            prev_eta = self._bus_eta.get(det_idx, (None, 1e9))[1]
            if self.BusPresence[0][det_idx] == 0 or eta < prev_eta:
                self.BusPresence[0][det_idx]    = 1
                self.BusSpeed[0][det_idx]       = speed_ms
                self.last_detected_bus_id       = veh_id
                self._bus_eta[det_idx]          = (veh_id, eta, remaining, speed_ms)
            self._detected_buses.append({
                'detector_index': det_idx,
                'vehicle_id': veh_id,
                'eta_s': eta,
                'remaining_m': remaining,
                'speed_mps': speed_ms,
            })

        # ── Primary: registered PT line vehicles ─────────────────────
        # Periodic diagnostic: every 5 min, log where ALL PT buses are so we
        # can confirm whether any ever reach the detector sections.
        _diag_pt_t = int(time) // 300
        _do_pt_diag = (_diag_pt_t != getattr(self, '_pt_diag_t', -1))
        if _do_pt_diag:
            self._pt_diag_t = _diag_pt_t
        _pt_on_det_sec = []   # (veh_id, section, eta)
        _pt_elsewhere  = []   # (veh_id, section)  — not on det_sec_map
        try:
            n_lines = AKIPTGetNumberLines()
            for li in range(n_lines):
                try:
                    line_id = AKIPTGetIdLine(li)
                    n_vehs  = AKIGetNbVehiclesFollowingPTLine(line_id)
                except Exception:
                    continue
                for vi in range(n_vehs):
                    try:
                        veh_id = AKIGetVehicleFollowingPTLine(line_id, vi)
                        if veh_id in seen:
                            continue
                        inf = AKIPTVehGetInf(veh_id)
                        if inf.report < 0:
                            continue
                        seen.add(veh_id)
                        if inf.idSection not in det_sec_map:
                            if _do_pt_diag:
                                _pt_elsewhere.append((veh_id, inf.idSection))
                            continue
                        speed_ms  = max(inf.CurrentSpeed / 3.6, 0.5)
                        for i, det_dist, det_fin in det_sec_map[inf.idSection]:
                            if inf.CurrentPos <= det_fin:
                                remaining = (det_fin - inf.CurrentPos) + det_dist
                            else:
                                remaining = max(0.0, det_dist - (inf.CurrentPos - det_fin))
                            eta = remaining / speed_ms
                            if _do_pt_diag:
                                _pt_on_det_sec.append((veh_id, inf.idSection, round(eta, 1)))
                            if eta <= lookahead:
                                _record_detected_bus(i, veh_id, speed_ms,
                                                     remaining, eta,
                                                     line_id=line_id)
                    except Exception:
                        continue
        except Exception:
            pass
        if _do_pt_diag:
            log_to_file(
                f"[PT_SCAN] inter={self.id} t={time:.0f} "
                f"det_sec_map_secs={list(det_sec_map.keys())} "
                f"on_det_secs={_pt_on_det_sec} "
                f"elsewhere(veh,sec)={_pt_elsewhere[:10]}"  # cap at 10
            )

        # ── Fallback: direct section scan for injected buses ─────────
        for sec, det_entries in det_sec_map.items():
            try:
                n = AKIVehStateGetNbVehiclesSection(sec, True)
                for vi in range(n):
                    inf = AKIVehStateGetVehicleInfSection(sec, vi)
                    if _do_pt_diag and inf.idVeh not in seen:
                        # Log every vehicle type found on detector sections
                        log_to_file(
                            f"[FALLBACK_SCAN] inter={self.id} t={time:.0f} "
                            f"sec={sec} veh={inf.idVeh} type={inf.type} "
                            f"bus_type_pos={self.bus_type_pos} "
                            f"pos={inf.CurrentPos:.1f} speed={inf.CurrentSpeed:.1f}"
                        )
                    if inf.idVeh in seen or inf.type != self.bus_type_pos:
                        continue
                    seen.add(inf.idVeh)
                    speed_ms  = max(inf.CurrentSpeed / 3.6, 0.5)
                    for i, det_dist, det_fin in det_entries:
                        if inf.CurrentPos <= det_fin:
                            remaining = (det_fin - inf.CurrentPos) + det_dist
                        else:
                            remaining = max(0.0, det_dist - (inf.CurrentPos - det_fin))
                        eta = remaining / speed_ms
                        if eta <= lookahead:
                            _record_detected_bus(i, inf.idVeh, speed_ms, remaining, eta)
            except Exception:
                continue
    
    
    def detect_bus_semi(self, time):
        """
        Production‑safe bus detection.

        ✔ Works with PT vehicles
        ✔ Works without detectors
        ✔ Works if bus type inference changes
        ✔ Cannot throw NameError
        """

        # Reset presence arrays
        self.BusPresence[:] = 0
        self.BusSpeed[:]    = 0.0
        self.last_detected_bus_id = -1

        # Always define this
        bus_found = False

        # ─────────────────────────────────────────────
        # 1️⃣ Primary: PT line vehicles
        # ─────────────────────────────────────────────
        try:
            n_lines = AKIPTGetNumberLines()
        except Exception:
            n_lines = 0

        for li in range(n_lines):
            try:
                line_id = AKIPTGetIdLine(li)
                n_vehs  = AKIGetNbVehiclesFollowingPTLine(line_id)
            except Exception:
                continue

            for vi in range(n_vehs):
                try:
                    veh_id = AKIGetVehicleFollowingPTLine(line_id, vi)
                    inf    = AKIPTVehGetInf(veh_id)

                    if inf.report < 0:
                        continue

                    if inf.idSection in self.incoming_sections:
                        self.BusPresence[0][0] = 1
                        self.BusSpeed[0][0]    = max(inf.CurrentSpeed / 3.6, 0.5)
                        self.last_detected_bus_id = veh_id
                        bus_found = True
                        break

                except Exception:
                    continue

            if bus_found:
                break

        # ─────────────────────────────────────────────
        # 2️⃣ Fallback: direct section scan
        # ─────────────────────────────────────────────
        if not bus_found:

            for sec in self.incoming_sections:
                try:
                    n = AKIVehStateGetNbVehiclesSection(sec, True)

                    for i in range(n):
                        inf = AKIVehStateGetVehicleInfSection(sec, i)

                        if inf.type == self.bus_type_pos:
                            self.BusPresence[0][0] = 1
                            self.BusSpeed[0][0]    = max(inf.CurrentSpeed / 3.6, 0.5)
                            self.last_detected_bus_id = inf.idVeh
                            bus_found = True
                            break

                    if bus_found:
                        break

                except Exception:
                    continue
    
    def _get_junction_xy(self):
        """
        Return the X,Y centroid of this junction.  Tries several coordinate
        field name variants used across Aimsun versions:
          Aimsun 22/26: xSection/ySection (centroid) or xSectionTo/ySectionTo
          Older builds:  xcoordTo/ycoordTo
        Falls back to turn-origin sections from the junction topology if
        incoming_sections are all transit links (report<0).
        Result is cached only on success — retries every call until resolved.
        """
        if getattr(self, '_junction_xy', None) is not None:
            return self._junction_xy   # already resolved — fast path

        xs, ys = [], []

        # First try incoming_sections (detector-based approach sections)
        for sec_id in self.incoming_sections:
            try:
                si = AKIInfNetGetSectionANGInf(sec_id)
                if si.report >= 0:
                    _xy = _extract_xy_from_section_info(si)
                    if _xy is not None:
                        xs.append(_xy[0])
                        ys.append(_xy[1])
            except Exception:
                pass

        # If that yielded nothing, try all turn-origin sections at the junction
        if not xs:
            try:
                n_turns = AKIInfNetGetNbTurnsInNode(self.node_id)
                for ti in range(max(n_turns, 0)):
                    try:
                        sec_id = AKIInfNetGetOriginSectionInTurn(self.node_id, ti)
                        if sec_id <= 0:
                            continue
                        si = AKIInfNetGetSectionANGInf(sec_id)
                        if si.report >= 0:
                            _xy = _extract_xy_from_section_info(si)
                            if _xy is not None:
                                xs.append(_xy[0])
                                ys.append(_xy[1])
                    except Exception:
                        pass
            except Exception:
                pass

        if xs:
            self._junction_xy = (sum(xs) / len(xs), sum(ys) / len(ys))
            if LOG_JUNC_XY:
                log_to_file(
                    f"[JUNC_XY] inter={self.id} resolved={self._junction_xy} "
                    f"from {len(xs)} sections"
                )
            return self._junction_xy

        _model_xy = _resolve_junction_xy_from_model(self.node_id, self.incoming_sections)
        if _model_xy is not None:
            self._junction_xy = _model_xy
            log_to_file(
                f"[JUNC_XY] IC inter={self.id} resolved via model "
                f"-> ({_model_xy[0]:.1f}, {_model_xy[1]:.1f})"
            )
            return self._junction_xy

        # Still nothing — log once (always, regardless of flag) to help diagnose
        if not getattr(self, '_junc_xy_warn_logged', False):
            self._junc_xy_warn_logged = True
            try:
                si = AKIInfNetGetSectionANGInf(self.incoming_sections[0])
                fields = {k: getattr(si, k, '?') for k in dir(si) if not k.startswith('_')}
            except Exception:
                fields = {}
            log_to_file(
                f"[JUNC_XY_FAIL] inter={self.id} cannot resolve junction coordinates. "
                f"incoming_sections={self.incoming_sections} "
                f"section_ANGInf_fields={fields}"
            )
        return None

    def detect_bus(self, time):
        """
        Coordinate-distance bus detection — robust against transit links.

        PT buses in Aimsun travel through transit-link sections whose IDs return
        report<0 from AKIInfNetGetSectionANGInf (no topology info).  Section-based
        detection therefore never fires.  Instead we:

        1. Get the junction centroid X,Y from the 'to' coordinates of approach sections.
        2. For every active PT line vehicle, compute Euclidean distance to the junction.
        3. If distance <= detection_radius_m and type==bus_type_pos → detect.
        4. Fallback: direct section scan on incoming_sections for type==bus_type_pos.

        Periodic [PT_SCAN] log (every 5 min) shows all PT vehicles, their coordinates,
        and distances so we can verify the radius is appropriate.
        """

        self.BusPresence[:] = 0
        self.BusSpeed[:]    = 0.0
        self.last_detected_bus_id = -1
        if isinstance(getattr(self, '_bus_eta', None), dict):
            self._bus_eta.clear()
        else:
            self._bus_eta = {}

        # Detection radius: ~1 cycle length at 50 km/h ≈ 1875 m, capped at 500 m to
        # avoid false positives from buses at nearby parallel intersections.
        detection_radius_m = min(self.urtsp_cycle_length * 14.0, 500.0)

        # Junction centroid (cached after first call)
        junc_xy = self._get_junction_xy()

        # Periodic diagnostic throttle: every 5 minutes — only when LOG_PT_SCAN=True
        _diag_t = int(time) // 300
        _do_diag = LOG_PT_SCAN and (_diag_t != getattr(self, '_db_diag_t', -1))
        if _do_diag:
            self._db_diag_t = _diag_t
        _pt_info = []   # (veh_id, dist_m, speed) for diagnostic

        seen = set()
        jx = jy = None
        if junc_xy is not None:
            jx, jy = junc_xy
        _bus_type_is_provisional = bool(globals().get('_bus_type_provisional', False))

        _prev_presence = int(self.BusPresence[0][0]) if len(self.BusPresence[0]) else 0

        def _hit(veh_id, speed_kph, hit_x=None, hit_y=None):
            speed_ms = max(speed_kph / 3.6, 0.5)
            if jx is not None and hit_x is not None and _jct_xy_cache:
                try:
                    _self_dist = math.sqrt((float(hit_x) - jx) ** 2 + (float(hit_y) - jy) ** 2)
                    _nearest_jid, _nearest_dist = min(
                        (
                            (int(_jid), math.sqrt((float(hit_x) - float(_xy[0])) ** 2 + (float(hit_y) - float(_xy[1])) ** 2))
                            for _jid, _xy in _jct_xy_cache.items()
                            if _xy is not None and len(_xy) >= 2
                        ),
                        key=lambda _item: _item[1],
                    )
                    # Only let the nearest junction claim the live IC-detect.
                    # This suppresses overlapping-junction artefacts where one
                    # bus position creates simultaneous detections several
                    # hundred metres upstream of multiple intersections.
                    if _nearest_jid != self.id and (_self_dist - _nearest_dist) > 25.0:
                        return
                except Exception:
                    pass
            self.BusPresence[0][0]    = 1
            self.BusSpeed[0][0]       = speed_ms
            self.last_detected_bus_id = veh_id
            # Compute actual distance to junction centroid and store in _bus_eta
            # so check_bus_priority can compute a correct ETA (previously it fell
            # back to DetDistance[0][0]=50m, wildly underestimating when the bus
            # is detected 200-500m away — causing "always natural green").
            if not isinstance(getattr(self, '_bus_eta', None), dict):
                self._bus_eta = {}
            if jx is not None and hit_x is not None:
                _dist_m = ((float(hit_x) - jx) ** 2 + (float(hit_y) - jy) ** 2) ** 0.5
            else:
                _dist_m = float(self.config.get("DetDistance", [[50.0]])[0][0])
            _eta_s = _dist_m / max(float(speed_ms), 0.5)
            try:
                _emx = float(globals().get('BUS_ETA_MAX_S', 300.0) or 300.0)
            except Exception:
                _emx = 300.0
            _eta_s = min(_eta_s, _emx)
            # Systematic ETA: prefer the adaptive-Kalman corridor estimate
            # (position+speed state, uncertainty-scaled) over raw dist/speed
            # when the bus has a tracker; log the source for diagnostics.
            _eta_src = "dist-speed"
            try:
                _cc_e = getattr(self, '_corridor_coord', None)
                if _cc_e is not None:
                    _ek, _es, _esrc = _eta_s_for(
                        getattr(_cc_e, '_trackers', None) or {},
                        getattr(_cc_e, 'corridor_pos', None) or {},
                        int(veh_id), int(self.id), float(time),
                        fallback_s=_eta_s)
                    if _ek is not None:
                        _eta_s, _eta_src = _ek, _esrc
            except Exception:
                pass
            self._bus_eta[0] = (veh_id, _eta_s, _dist_m, speed_ms)
            # Record the bus passage in stats (works for transit-link buses that
            # never appear on regular approach sections)
            try:
                self.stats.record_pt_bus_detection(self.id, veh_id, time)
            except Exception:
                pass
            # Detection-point marker: use vehicle XY, fall back to junction
            # centroid, then (0,0) so the CSV is always written.
            _mx = hit_x if hit_x is not None else (jx if jx is not None else 0.0)
            _my = hit_y if hit_y is not None else (jy if jy is not None else 0.0)
            _mark_detection_point(self.id, veh_id, _mx, _my, time, "IC-detect")

        # ── Tier 0: position-tracker zone-presence supplement ───────────────
        # _track_all_bus_positions maintains _tracking_zone_presence with buses
        # confirmed inside this junction's detection zone at the last 5-second
        # interval.  Buses on transit-link sections (report<0) won't appear in
        # the PT API scan below, so this Tier 0 fills that gap.
        for _tz_vid, (_tz_bx, _tz_by, _tz_spd) in list(
                _tracking_zone_presence.get(self.id, {}).items()):
            if _tz_vid not in seen:
                seen.add(_tz_vid)
                _hit(_tz_vid, _tz_spd, _tz_bx, _tz_by)

        # ── Tier 1: PT line vehicle scan ────────────────────────────────────
        # Always runs regardless of whether junction coordinates are available.
        # When coordinates are known: accept buses within detection_radius_m.
        # When coordinates are unknown: accept buses on any incoming_section
        #   OR any bus whose section leads directly to this junction (idNodeTo).
        try:
            n_lines = AKIPTGetNumberLines()
        except Exception:
            n_lines = 0

        for li in range(n_lines):
            try:
                line_id = AKIPTGetIdLine(li)
                n_vehs  = AKIGetNbVehiclesFollowingPTLine(line_id)
            except Exception:
                continue
            for vi in range(n_vehs):
                try:
                    veh_id = AKIGetVehicleFollowingPTLine(line_id, vi)
                    if veh_id in seen:
                        continue
                    inf = AKIPTVehGetInf(veh_id)
                    if inf.report < 0:
                        continue
                    seen.add(veh_id)
                    if self.bus_type_pos > 0 and not _bus_type_is_provisional and inf.type != self.bus_type_pos:
                        continue

                    if jx is not None:
                        # Primary path: coordinate distance
                        dx   = float(inf.xCurrentPos) - jx
                        dy   = float(inf.yCurrentPos) - jy
                        dist = (dx * dx + dy * dy) ** 0.5
                        if _do_diag:
                            _pt_info.append(
                                f"v={veh_id} d={dist:.0f}m "
                                f"spd={inf.CurrentSpeed:.0f}kph "
                                f"sec={inf.idSection}"
                            )
                        if dist <= detection_radius_m:
                            _hit(veh_id, inf.CurrentSpeed,
                                 float(inf.xCurrentPos), float(inf.yCurrentPos))
                    else:
                        # Fallback path — coordinates not yet available.
                        # Build/use a cached set of all sections that feed into
                        # this junction (turn-origin sections from topology).
                        if not hasattr(self, '_turn_origin_secs'):
                            _tos = set(self.incoming_sections)
                            try:
                                _nt = AKIInfNetGetNbTurnsInNode(self.node_id)
                                for _ti in range(max(_nt, 0)):
                                    try:
                                        _ts = AKIInfNetGetOriginSectionInTurn(self.node_id, _ti)
                                        if _ts > 0:
                                            _tos.add(_ts)
                                    except Exception:
                                        pass
                            except Exception:
                                pass
                            self._turn_origin_secs = _tos

                        sec_id = inf.idSection
                        matched = sec_id in self._turn_origin_secs
                        if not matched:
                            try:
                                si = AKIInfNetGetSectionANGInf(sec_id)
                                if si.report >= 0 and si.idNodeTo == self.node_id:
                                    matched = True
                            except Exception:
                                pass
                        if _do_diag:
                            _pt_info.append(
                                f"v={veh_id} sec={sec_id} "
                                f"spd={inf.CurrentSpeed:.0f}kph "
                                f"matched={matched}"
                            )
                        if matched:
                            _hit(veh_id, inf.CurrentSpeed,
                                 float(getattr(inf, 'xCurrentPos', 0.0)),
                                 float(getattr(inf, 'yCurrentPos', 0.0)))
                except Exception:
                    continue

        # ── Tier 2: direct section scan on approach sections ────────────────
        if not any(self.BusPresence[0]):
            for sec_id in self.incoming_sections:
                try:
                    n = AKIVehStateGetNbVehiclesSection(sec_id, True)
                    for vi in range(n):
                        inf = AKIVehStateGetVehicleInfSection(sec_id, vi)
                        if inf.idVeh in seen:
                            continue
                        if self.bus_type_pos <= 0 or _bus_type_is_provisional or inf.type == self.bus_type_pos:
                            _hit(inf.idVeh, inf.CurrentSpeed)
                            break
                except Exception:
                    continue
                if any(self.BusPresence[0]):
                    break

        # ── Periodic diagnostic ─────────────────────────────────────────────
        if _do_diag:
            log_to_file(
                f"[PT_SCAN] inter={self.id} t={time:.0f} "
                f"junc_xy={junc_xy} radius={detection_radius_m:.0f}m "
                f"n_lines={n_lines} bus_type_pos={self.bus_type_pos} "
                f"turn_origin_secs={sorted(getattr(self,'_turn_origin_secs',set()))} "
                f"BusPresence={self.BusPresence[0][0]} "
                f"all_type3_buses=[{'; '.join(_pt_info)}]"
            )
    def _section_window_flow(self, sec_id, now, window_s, sec_len_hint=0.0,
                               allow_seed=True):
        """Actual Aimsun flow (veh/h) on `sec_id`, read straight from the
        section statistics.  Tries in order:
         1. partial-window count-delta from AKIEstGetParcialStatisticsSection
            with vehTypePos=-1 (ALL vehicle types) — the same method
            kg/Simulation_Stats.py uses for its ground-truth section stats
         2. AKIEstGetCurrentStatisticsSection (live per-type stats)
         3. AKIEstGetGlobalStatisticsSection  (whole-run aggregates)

        The all-type partial count is primary because the per-type current
        stats only cover one vehicle class (cars) and under-report the true
        section demand by roughly the lane/class mix (~3x in this network).

        DEMAND SEED (warm-up independence): the OD demand profile is loaded
        once per run (_demand_rated_flow_vph, veh/h from GKTrafficDemand).  The
        microsim's own t=0 flow is 0 by construction, so before any real
        measurement exists the estimator returns the DEMAND-RATED flow for this
        section (its lane share of the corridor demand), and only switches to
        measured values once Aimsun's counters become non-zero.  This makes the
        online gates/shockwave speeds correct from the very first step and
        matches the way the clairvoyant MILP receives q_{i,p,t} as a
        pre-computed parameter -- both sides of the comparison use the same
        demand-derived flow, not a warm-up ramp.  Past DEMAND_SEED_WARM_S the
        seed decays to faithful 0 (see fallback below).

        allow_seed=False skips that prior and returns 0.0 when nothing is
        measured (2026-09-25): _refresh_live_flow_rolling overlays this onto
        SideUpFlowList, so letting the seed through there PINNED every
        unmeasured virtual side section at the seed (1800.0) all run and
        wiped out _sample_side_sections' faithful Tier-4 zero for an empty
        approach. Live-overlay callers must pass False; warm-up gate callers
        keep the default True.

        Returns 0.0 when Aimsun reports nothing (caller falls back to the
        density/LWR occupancy scan)."""
        _sec = int(sec_id)
        _car_pos  = int(getattr(self, 'car_type_pos', 1) or 1)
        _bus_pos  = int(getattr(self, 'bus_type_pos', 2) or 2)

        # ── Demand-seed cache: rated veh/h for this section, set once out of
        # the OD profile (lane share of the corridor's demand).
        _seed_tbl = getattr(self, '_demand_flow_seed', None)
        if _seed_tbl is None:
            _seed_tbl = {}
            self._demand_flow_seed = _seed_tbl
        if _sec not in _seed_tbl:
            _seed_tbl[_sec] = self._demand_seed_flow_for_sec(_sec)

        def _flow_from(st):
            if st is None or getattr(st, 'report', -1) != 0:
                return 0.0
            # Aimsun reports real flow directly; count*3600/window is backup.
            _f = max(float(getattr(st, 'Flow', 0.0) or 0.0), 0.0)
            _c = max(float(getattr(st, 'count', 0.0) or 0.0), 0.0)
            if _f > 0.0:
                return _f
            if _c > 0.0:
                return _c * 3600.0 / max(window_s, 1.0)
            return 0.0

        try:
            # Primary: all-vehicle-type count over the rolling window (same
            # ground-truth method as kg/Simulation_Stats.py).  Aimsun only
            # answers a partial-stats request for a window it still retains;
            # 300 s can come back report != 0 (silently skips this tier).
            # Retry with progressively smaller windows, ending at the 30 s
            # cadence Simulation_Stats.py uses successfully (INTERVAL_S=30).
            _sp_wins = sorted(set([float(window_s), 300.0, 60.0, 30.0, 10.0]),
                              reverse=True)
            for _w in _sp_wins:
                try:
                    _sp = AKIEstGetParcialStatisticsSection(
                        _sec, max(0.0, now - _w), -1)
                    if getattr(_sp, 'report', -1) == 0:
                        _c = max(float(getattr(_sp, 'count', 0.0) or 0.0), 0.0)
                        if _c > 0.0:
                            self._flow_tier_logged = getattr(
                                self, '_flow_tier_logged', {})
                            _tag = 'partial_w%.0f' % _w
                            if _tag not in self._flow_tier_logged:
                                self._flow_tier_logged[_tag] = set()
                            if _sec not in self._flow_tier_logged[_tag]:
                                self._flow_tier_logged[_tag].add(_sec)
                                log_to_file(
                                    '[FLOW SRC] sec=%s tier=partial window=%.0fs '
                                    'count=%d flow=%.1f veh/h (all types)' %
                                    (_sec, _w, int(_c),
                                     _c * 3600.0 / max(_w, 1.0)))
                            return _c * 3600.0 / max(_w, 1.0)
                except Exception:
                    pass

            # Tier 2: all-vehicle-type snapshot flow (matches the ground-truth
            # method Simulation_Stats.py actually lands on).  Aimsun's partial
            # statistics (vehTypePos=-1) return report != 0 for these virtual
            # side sections, so the true cross-street demand is NOT readable via
            # AKIEst.  The stats module therefore falls back to
            #     flow = density * speed * lanes
            #         = n_veh(ALL types) * space-mean-speed / length_km
            # which counts every vehicle class (cars+buses+trucks) and is the
            # ~3x figure the per-type car-only stats miss.  The running-mean
            # buffer smooths the instantaneous snapshot.
            try:
                _n_snap = int(AKIVehStateGetNbVehiclesSection(_sec, False))
                if _n_snap > 0:
                    _inv_spd = 0.0
                    _spd_n   = 0
                    for _vi in range(_n_snap):
                        _vi_inf = AKIVehStateGetVehicleInfSection(_sec, _vi)
                        _vs = float(getattr(_vi_inf, 'CurrentSpeed', 0.0) or 0.0)
                        if _vs > 0.0:
                            _inv_spd += 1.0 / _vs
                            _spd_n += 1
                    _sec_geo = AKIInfNetGetSectionANGInf(_sec)
                    _sec_len_m = float(getattr(_sec_geo, 'length', 0.0) or 0.0)
                    # VIRTUAL/dead sections return length 0 from the AKI API (their
                    # length is only known from the model-topology scan). Fall back
                    # to the caller's model-length hint so the vehicle-scan flow
                    # (n_veh * speed / length) can be computed instead of dropping
                    # to the demand seed -- this is what made a 46m "dead" side
                    # approach read flow=3600 (seed) despite n_veh>0 (2026-09-16).
                    if _sec_len_m <= 0.0:
                        _sec_len_m = float(sec_len_hint or 0.0)
                    if _spd_n > 0 and _inv_spd > 0.0 and _sec_len_m > 0.0:
                        _spd_kmh = float(_spd_n) / _inv_spd
                        _snap_flow = _n_snap * _spd_kmh / (_sec_len_m / 1000.0)
                        if _snap_flow > 0.0:
                            _bf = getattr(self, '_snap_flow_buf', {})
                            _bq = _bf.setdefault(_sec, [])
                            _bq.append(_snap_flow)
                            if len(_bq) > 12:
                                _bq.pop(0)
                            _buf_mean = sum(_bq) / len(_bq)
                            self._flow_tier_logged = getattr(
                                self, '_flow_tier_logged', {})
                            _tag = 'snapshot_alltypes'
                            if _tag not in self._flow_tier_logged:
                                self._flow_tier_logged[_tag] = set()
                            if _sec not in self._flow_tier_logged[_tag]:
                                self._flow_tier_logged[_tag].add(_sec)
                                log_to_file(
                                    '[FLOW SRC] sec=%s tier=snapshot_alltypes '
                                    'nveh=%d spd=%.1f len=%.0fm flow=%.1f veh/h '
                                    '(running-mean over %d samples)' %
                                    (_sec, _n_snap, _spd_kmh, _sec_len_m,
                                     _buf_mean, len(_bq)))
                            return _buf_mean
            except Exception:
                pass
            # Empty instant: keep feeding the buffer the last smoothed value so
            # the running mean is preserved (like GT's 30s time-averaging) and
            # momentary gaps don't reset the flow to zero.
            try:
                _bf = getattr(self, '_snap_flow_buf', {})
                _bq = _bf.get(_sec)
                if _bq:
                    _buf_mean = sum(_bq) / len(_bq)
                    if _buf_mean > 0.0:
                        return _buf_mean
            except Exception:
                pass

            _st = None
            try:
                _st = AKIEstGetCurrentStatisticsSection(_sec, _car_pos)
            except Exception:
                _st = None
            if _flow_from(_st) <= 0.0:
                try:
                    _st = AKIEstGetGlobalStatisticsSection(_sec, _car_pos)
                except Exception:
                    _st = None
            if _flow_from(_st) <= 0.0 and _bus_pos != _car_pos:
                try:
                    _st = AKIEstGetCurrentStatisticsSection(_sec, _bus_pos)
                except Exception:
                    _st = None
                if _flow_from(_st) <= 0.0:
                    try:
                        _st = AKIEstGetGlobalStatisticsSection(_sec, _bus_pos)
                    except Exception:
                        _st = None
            _measured = max(0.0, _flow_from(_st))
            # ── Demand-seed fallback: warm-up PRIOR, not a measurement ──
            # The OD-rated flow makes gates/shockwave speeds correct from the
            # very first step, but it must DECAY: past DEMAND_SEED_WARM_S
            # (default 300 s) an unmeasured section reads faithful 0 instead
            # of a permanent seed clamped at saturation (the "always 1800.0"
            # symptom on sides whose counters never tick). The tiers above
            # already returned live values whenever vehicles are actually
            # present (snapshot / running-mean buffer), so reaching this line
            # means nothing is measured. allow_seed=False skips it at any age
            # (live-overlay path: an empty approach must read 0, not the 1800
            # seed, or the side cost is over-priced all run).
            if _measured <= 0.0 and allow_seed:
                try:
                    _warm = float(globals().get('DEMAND_SEED_WARM_S', 300.0))
                except Exception:
                    _warm = 300.0
                try:
                    _now_f = float(now)
                except Exception:
                    _now_f = 0.0
                if _now_f > _warm:
                    return 0.0
                _seed_v = _seed_tbl.get(_sec, 0.0)
                if _seed_v > 0.0:
                    if not getattr(self, '_demand_seed_logged', False):
                        self._demand_seed_logged = True
                        log_to_file(
                            '[FLOW SRC] sec=%s tier=demand_profile flow=%.1f '
                            'veh/h (OD-rated seed, no live measurement yet)' %
                            (_sec, _seed_v))
                    return _seed_v
            return _measured
        except Exception:
            return 0.0

    def _demand_seed_flow_for_sec(self, sec_id):
        """OD-rated flow (veh/h) for a section, derived from the corridor's
        GKTrafficDemand profile -- the pre-computed q parameter of the MILP,
        not a runtime measurement.  Splits the rated corridor flow by the
        section's lane share of the corridor; sections without lane geometry
        fall back to the corridor mean.  0 when the profile is unavailable
        (callers then rely on measured flow)."""
        try:
            import os.path as _osp
            _sec = int(sec_id)
            if not _demand_rated_flow_vph or _demand_rated_flow_vph <= 0.0:
                return 0.0
            # Section -> incoming lanes (corridor-facing).
            # BUGFIX (2026-09-25): AKIInfNetGetSectionANGInf carries
            # nbCentralLanes/nbSideLanes -- there is NO `NumberLanes` attr, so
            # getattr(..., 'NumberLanes', 0) was ALWAYS 0. Every side section
            # then seeded at min(rated*0.15, 1800*1): with a ~12k veh/h Logan
            # corridor that is EXACTLY 1800.0 on every unmeasured side approach
            # (the "valid ones vs 1800.0" symptom -- 1800 is the seed prior,
            # not a measurement). Use the real lane count with a NumberLanes
            # fallback so seeds are section-specific again.
            def _sec_lanes(_s):
                try:
                    _g = AKIInfNetGetSectionANGInf(int(_s))
                    if getattr(_g, 'report', -1) < 0:
                        return 0
                    _n = (int(getattr(_g, 'nbCentralLanes', 0) or 0)
                          + int(getattr(_g, 'nbSideLanes', 0) or 0))
                    if _n <= 0:
                        _n = int(getattr(_g, 'NumberLanes', 0) or 0)
                    return max(int(_n), 0)
                except Exception:
                    return 0
            _n_lanes_sec = _sec_lanes(_sec)
            _incoming = getattr(self, 'incoming_sections', None) or []
            # Physical ceiling: a section cannot carry more than saturation flow
            # per lane. Without this, a SIDE section (not in `incoming_sections`,
            # so its lane share of the MAIN denominator can be ~1.0) was seeded
            # with the WHOLE corridor's rated flow -> implausible values like
            # 4654 veh/h from 0 live vehicles, which corrupted the shockwave
            # cross-cost. Clamp every seed to SaturationFlow x lanes.
            _q_sat = float(getattr(self, 'SaturationFlow', 1800.0) or 1800.0)
            _cap = _q_sat * float(max(_n_lanes_sec, 2))
            # SIDE/cross section: NOT one of the main incoming approaches, so it
            # must NOT be seeded with a lane-share of the corridor THROUGH-demand
            # (that put ~half-to-all of the corridor flow on a minor side entry,
            # then clamped to saturation -> the phantom 3600 on a dead 46m
            # approach, 2026-09-16). A side approach carries its OWN minor
            # entry/turning demand -- seed it at the turning-ratio fraction of the
            # corridor demand; the MEASURED flow (the ACTUAL path demand in the
            # sim) overrides this prior once Aimsun's counters warm up.
            try:
                _is_side = int(_sec) not in set(int(_s) for _s in _incoming)
            except Exception:
                _is_side = False
            if _is_side:
                _side_frac = float(globals().get('SIDE_DEMAND_FRACTION', 0.15))
                _side_cap = _q_sat * float(max(_n_lanes_sec, 1))
                return max(0.0, min(_demand_rated_flow_vph * _side_frac, _side_cap))
            if _n_lanes_sec <= 0 and _incoming:
                # No lane geometry: weight by the controller's own section set.
                try:
                    _share = 1.0 / max(len(_incoming), 1)
                except Exception:
                    _share = 0.0
                return min(_demand_rated_flow_vph * _share, _cap)
            # Lane-weighted share across the controller's incoming sections.
            _tot_lanes = 0
            for _s in _incoming:
                _tot_lanes += _sec_lanes(_s) or 1
            if _tot_lanes <= 0:
                return min(_demand_rated_flow_vph / max(len(_incoming), 1), _cap)
            return min(_demand_rated_flow_vph * (_n_lanes_sec / float(_tot_lanes)), _cap)
        except Exception:
            return 0.0

    def _refresh_live_flow_rolling(self, time, window_s=300.0):
        """Prefer continuous rolling window-counts over the instantaneous
        density scan for BOTH main and side sections. Throttled to every 5 s.

        Live detections should be tracking & counting every vehicle that
        crosses, so this becomes the primary flow source; the LWR density
        fallback (occupancy snapshot) only covers sections the counter misses.
        Returns the live main-flow (veh/h) for callers that need one mean."""
        _every = 5.0
        _last = getattr(self, '_live_flow_t', -999.0)
        if _every > 0.0 and time - _last < _every:
            return getattr(self, '_live_flow_main', 0.0)
        self._live_flow_t = time

        _main_samples = []
        _sec_f = {}
        for _s in list(getattr(self, 'incoming_sections', [])):
            _f = self._section_window_flow(_s, time, window_s)
            if _f > 0.0:
                _main_samples.append(_f)
                _sec_f[int(_s)] = float(_f)
        _main_mean = (float(np.mean(_main_samples)) if _main_samples else 0.0)
        self._live_flow_main = _main_mean
        # Side sections for the per-phase rows (2026-09-26): a side phase's row
        # must carry ITS OWN approach flow, not the main mean. Reuse the
        # per-section side flows already maintained by the sampler.
        _sec_f_side = {}
        try:
            _suf_all = np.asarray(getattr(self, 'SideUpFlowList', []), dtype=float)
            for _idx, _ss in enumerate(self._get_side_sections() or []):
                if _idx < _suf_all.size and _suf_all[_idx] > 0.0:
                    _sec_f_side[int(_ss)] = float(_suf_all[_idx])
        except Exception:
            _sec_f_side = {}

        # Overlay rolling counts onto UpFlowList red-phase slots (like
        # _populate_flow_from_sections but from the counter, not occupancy).
        # Per-phase (per-DIRECTION) overlay since 2026-09-26: row 0 = bus phase
        # (engine convention), other rows carry their own phase's sections;
        # falls back to the broadcast mean when the plan map can't resolve.
        _upf = getattr(self, 'UpFlowList', None)
        if _upf is not None and len(_upf) > 0:
            k_sat = max(float(self.SaturationDensity), 1.0)
            q_sat = max(float(self.SaturationFlow), 1.0)
            _ps = {}
            try:
                _ps = self._phase_origin_sections() or {}
            except Exception:
                _ps = {}
            _bp = int(getattr(self, 'BusPhase', 1) or 1)
            for _i in range(len(_upf)):
                _ph = _i + 1
                if _i == 0 and 1 <= _bp <= len(_upf):
                    _ph = _bp
                elif _i == _bp - 1 and _bp != 1:
                    _ph = 1
                _row = None
                _secs = _ps.get(int(_ph))
                if _secs:
                    _vals = []
                    for _s in _secs:
                        _v = _sec_f.get(int(_s))
                        if _v is None:
                            _v = _sec_f_side.get(int(_s))
                        if _v is not None and _v > 0.0:
                            _vals.append(float(_v))
                    if _vals:
                        _row = float(np.mean(_vals))
                if _row is None:
                    _row = _main_mean
                if _row <= 0.0:
                    continue
                _den = _row * k_sat / q_sat
                for _j in range(len(_upf[_i])):
                    if self.RedDurationList[_i][_j] > 0:
                        if _upf[_i][_j] <= 0.0:
                            _upf[_i][_j] = _row
                            try:
                                self.UpDenList[_i][_j] = _den
                            except Exception:
                                pass

        # Side sections: prefer the rolling counter per section.
        # allow_seed=False (2026-09-25): the OD seed is a warm-up PRIOR, not a
        # measurement. Overlaying it here pinned every unmeasured virtual side
        # at 1800.0 all run and erased _sample_side_sections' faithful zero
        # for an empty approach (the phantom side cost that vetoed good TSP).
        # Only a real measured flow may overwrite the LWR/zero estimate.
        _suf = getattr(self, 'SideUpFlowList', None)
        if _suf is not None:
            _side_secs = self._get_side_sections()
            _n = min(len(_side_secs), len(_suf))
            for _idx in range(_n):
                _f = self._section_window_flow(
                    _side_secs[_idx], time, window_s, allow_seed=False)
                if _f > 0.0:
                    _cap = float(self.SaturationFlow)
                    try:
                        _inf = AKIInfNetGetSectionANGInf(int(_side_secs[_idx]))
                        if getattr(_inf, 'report', -1) >= 0:
                            _cap *= max(int(_inf.nbCentralLanes) + int(_inf.nbSideLanes), 1)
                    except Exception:
                        pass
                    _suf[_idx] = min(_f, _cap)
                    try:
                        self.SideUpDenList[_idx] = _f * max(float(self.SaturationDensity), 1.0) / max(float(self.SaturationFlow), 1.0)
                    except Exception:
                        pass
        return _main_mean

    def _monitor_state_ready(self, time):
        """Gate for no-bus CONTINUOUS monitor ticks (MONITOR_STATE_GATE).

        A car-only commit made with zero state information cannot price its
        cost: pred_side reads 0 either because the approach is truly empty or
        because the counters never tick ([noupdate] stale) -- indistinguishable
        at commit time. The Logan losses were exactly these commits (FREE
        stage, bus=-1, pred_side=0, including no-side junctions acting with no
        opposing cost at all). Ready when ANY of: a fresh side measurement
        exists (latest_section within MEASURED_SIDE_FRESH_S), a side section
        is occupied right now, or the main approach is queued -- so no-side
        junctions only pass when their own main is queued. Fail-open (ready)
        when the measured feed is entirely absent and no side sections are
        configured, preserving legacy arms without measured feeds.
        Bus-present ticks are unaffected. Overridable per-arm with
        MONITOR_STATE_GATE=False."""
        try:
            if not bool(globals().get('MONITOR_STATE_GATE', True)):
                return True
            try:
                _fresh = float(globals().get('MEASURED_SIDE_FRESH_S', 90.0))
            except Exception:
                _fresh = 90.0
            try:
                _t_now = float(AKIGetCurrentSimulationTime())
            except Exception:
                _t_now = float(time)
            _stats = globals().get('stats', None) or getattr(self, 'stats', None)
            _ls = getattr(_stats, 'latest_section', None) if _stats is not None else None
            _side = self._get_side_sections() or []
            if not _side:
                # No opposing approaches mapped (source=none junctions): a
                # car-only tick cannot price any cost, so every evaluation
                # looks profitable. Hold unless explicitly restored.
                try:
                    if bool(globals().get('SIDLESS_MONITOR_HOLD', True)):
                        return False
                except Exception:
                    pass
            if _side:
                for _ss in _side:
                    try:
                        if int(AKIVehStateGetNbVehiclesSection(int(_ss), False)) > 0:
                            return True
                    except Exception:
                        pass
                    try:
                        _st = (_ls.get(int(_ss)) if _ls else None)
                        if _st is not None and _t_now >= 0.0 and abs(
                                _t_now - float(_st.get('t', -1e9))) <= _fresh:
                            return True
                    except Exception:
                        pass
            try:
                _mq = np.asarray(getattr(self, 'MaxQueueLength', [[0.0]]),
                                 dtype=float).ravel()
                if _mq.size and float(np.max(_mq)) > 0.5:
                    return True
            except Exception:
                pass
            if not _side and not _ls:
                return True
            return False
        except Exception:
            return True

    def _populate_flow_from_sections(self, time):
        """
        Populate UpFlowList / UpDenList for the current red phase from live
        vehicle counts on main approach sections when no physical UpDetList
        detectors are configured.

        Called by update_queue_model() once per cycle step when UpDetList is empty.
        Uses incoming_sections (N-S corridor approaches) and the same LWR
        triangular model used by _sample_side_sections.
        """
        if not self.incoming_sections:
            return
        if len(self.UpFlowList) == 0:
            return

        # Only use sections with valid geometry and length >= MIN_APPROACH_LEN_M
        MIN_APPROACH_LEN_M = 20.0
        _max_flow = max(self.SaturationFlow * 1.5, 3600.0)
        k_sat  = max(float(self.SaturationDensity), 1.0)
        k_jam  = max(float(self.JamDensity), k_sat + 1.0)
        q_sat  = max(float(self.SaturationFlow), 1.0)

        flow_samples  = []
        n_lanes_total = 0
        _sec_flow_map = {}   # sec -> (lwr flow, lanes) for the per-phase fill

        for sec_id in self.incoming_sections:
            try:
                _si = AKIInfNetGetSectionANGInf(int(sec_id))
                if getattr(_si, 'report', -1) < 0:
                    continue
                sec_len_m = float(getattr(_si, 'length', 0.0) or 0.0)
                if sec_len_m < MIN_APPROACH_LEN_M:
                    continue
                n_lanes = max(
                    int(getattr(_si, 'nbCentralLanes', 0)) + int(getattr(_si, 'nbSideLanes', 0)), 1)
            except Exception:
                continue

            try:
                n_veh = max(int(AKIVehStateGetNbVehiclesSection(sec_id, False)), 0)
            except Exception:
                n_veh = 0

            sec_len_km = sec_len_m / 1000.0
            density_per_lane = n_veh / n_lanes / max(sec_len_km, 0.001)
            k = min(density_per_lane, k_jam)
            if k <= k_sat:
                _flow = k * q_sat / k_sat
            else:
                _flow = q_sat * (k_jam - k) / max(k_jam - k_sat, 1.0)
            _flow = min(max(_flow, 0.0), _max_flow)
            _sec_flow_map[int(sec_id)] = (float(_flow), int(n_lanes))
            # Weight by lane count so multi-lane sections dominate
            flow_samples.extend([_flow] * n_lanes)
            n_lanes_total += n_lanes

        # Side approaches feed the per-phase map too (2026-09-26): the analytic
        # cross cost iterates PER-PHASE rows, so a side phase's row must carry
        # ITS OWN approach flow (both cross directions distinguished), not the
        # main-mean fallback. SideUpFlowList is per side section (populated by
        # _sample_side_sections / the rolling overlay).
        try:
            _suf_all = np.asarray(getattr(self, 'SideUpFlowList', []), dtype=float)
            for _idx, _ss in enumerate(self._get_side_sections() or []):
                if _idx >= _suf_all.size or _suf_all[_idx] <= 0.0:
                    continue
                if int(_ss) in _sec_flow_map:
                    continue
                _ln_s = 1
                try:
                    _si_s = AKIInfNetGetSectionANGInf(int(_ss))
                    _ln_s = max(int(getattr(_si_s, 'nbCentralLanes', 0))
                                + int(getattr(_si_s, 'nbSideLanes', 0)), 1)
                except Exception:
                    _ln_s = 1
                _sec_flow_map[int(_ss)] = (float(_suf_all[_idx]), _ln_s)
        except Exception:
            pass

        if not flow_samples:
            return

        mean_flow = float(np.mean(flow_samples))
        mean_den  = mean_flow * k_sat / q_sat
        no_physical_detectors = not any(self.UpDetList)

        # ── Per-phase (per-DIRECTION) rows (2026-09-26) ──────────────────────
        # UpFlowList rows are (phase, slot). Fill each row from the sections
        # THAT PHASE serves (signal-plan origins), so a bus-free continuous
        # monitor prices the direction being served -- not a both-direction
        # mean (Logan's two mains differ ~3x at some junctions). Row 0 keeps
        # the engine's documented "row 0 = bus phase" convention (bus code
        # reads UpFlowList[0]); phase 1 takes the bus row's old slot when
        # BusPhase != 1. Falls back to the broadcast mean per row whenever the
        # plan map can't resolve.
        _ps = {}
        try:
            _ps = self._phase_origin_sections() or {}
        except Exception:
            _ps = {}

        def _row_flow_for(_ph):
            _secs = _ps.get(int(_ph))
            if not _secs:
                return None
            _vals = []
            for _s in _secs:
                _sf = _sec_flow_map.get(int(_s))
                if _sf is not None:
                    _vals.extend([_sf[0]] * _sf[1])
            if not _vals:
                return None
            _rf = float(np.mean(_vals))
            return _rf, _rf * k_sat / q_sat

        _bp = int(getattr(self, 'BusPhase', 1) or 1)
        for i in range(len(self.UpFlowList)):
            _ph = i + 1
            if i == 0 and 1 <= _bp <= len(self.UpFlowList):
                _ph = _bp                      # row 0 = bus phase (convention)
            elif i == _bp - 1 and _bp != 1:
                _ph = 1                        # phase 1 takes the old bus row
            _rf = _row_flow_for(_ph)
            _f_row, _d_row = _rf if _rf is not None else (mean_flow, mean_den)
            for j in range(len(self.UpFlowList[i])):
                if (self.RedDurationList[i][j] > 0 or no_physical_detectors):
                    self.UpFlowList[i][j] = _f_row
                    self.UpDenList[i][j]  = _d_row

    def _timetable_intensity(self):
        """Bus arrivals/hour proxy at this junction from the PT timetable, scaled
        to ~[0,2] (1.0 ~ a busy ~30 bus/h corridor). Coarse v1: PT line count over
        a nominal headway. 0 when no PT info -- then the transit weight is neutral."""
        try:
            _n = int(AKIPTGetNumberLines())
            if _n <= 0:
                return 0.0
            _hw = max(float(globals().get('PLAN_NOMINAL_HEADWAY_S', 600.0)), 60.0)
            _bph = _n * (3600.0 / _hw)          # buses/hour across lines
            return min(_bph / 30.0, 2.0)
        except Exception:
            return 0.0

    def _optimize_startup_plan(self, timeSta):
        """OFFLINE WARM-START (PLAN_OPTIMIZE): at startup, from the OD demand +
        bus timetable, solve each junction's CYCLE and PHASE SPLITS (Webster) to
        minimise expected delay, transit-weighting the bus phase by the timetable
        intensity, and apply as the base fixed-time plan. The online methods
        (Nash / CellQ) then correct for the stochastic progression on top. Runs
        ONCE per junction. v1: per-junction cycle + splits; corridor OFFSETS are
        set by the coordinator's green-wave solve (see _optimize_corridor_offsets).

        Webster: C = (1.5*L + 5) / (1 - Y), Y = sum of critical flow ratios
        y_p = demand_p / saturation, L = lost time (n_phases * intergreen).
        Green_p is proportional to y_p (transit-weighted for the bus phase), floored
        at min-green, scaled to fill C - L. Applied via ECIChangeTimingPhase."""
        if getattr(self, '_plan_opt_done', False):
            return
        self._plan_opt_done = True
        try:
            _jid = int(getattr(self, 'node_id', 0) or 0) or int(self.id)
            try:
                _n = int(ECIGetNumberofPhases(_jid))
            except Exception:
                _n = int(ECIGetNumberPhases(_jid))
            if _n < 2:
                return
            _sat = max(float(getattr(self, 'SaturationFlow', 1900.0) or 1900.0), 1.0)
            _ig = float(globals().get('PLAN_INTERGREEN_S', 4.0))
            _po = self._phase_origin_sections() or {}
            _bp = int(getattr(self, 'BusPhase', -1) or -1)
            # per-phase OD demand (veh/h) over each phase's origin sections
            _y = {}
            for _ph in range(1, _n + 1):
                _d = 0.0
                for _s in (_po.get(_ph, set()) or set()):
                    try:
                        _d += max(0.0, float(self._demand_seed_flow_for_sec(int(_s))))
                    except Exception:
                        pass
                _y[_ph] = min(_d / _sat, 0.95)             # flow ratio y_p
            # ── BUGFIX 2026-09-30: Webster's Y must be the CRITICAL flow ratio,
            # i.e. the largest y among movements that CONFLICT with each other --
            # not the sum over every phase at the junction. Summing all phases
            # gave Y=3.8..6.3 on kg, so min(Y,0.90) pinned at 0.90, C = 10*(1.5L+5)
            # and every junction clamped to PLAN_CYCLE_MAX_S=150 (vs the real
            # ~80-135 s): car delay 19.9->64.8 s, bus 15.1->31.8 s, a -68%
            # objective regression versus simply not running the optimiser.
            # Phases are conflicting unless they share an origin section (same
            # physical approach => may run together), so the critical ratio is
            # the max y within each conflict set, and Y the sum of those maxima.
            _adj = {}
            for _ph in _y:
                _s_ph = _po.get(_ph, set()) or set()
                _adj[_ph] = {q for q in _y
                             if q == _ph
                             or not (_s_ph & (_po.get(q, set()) or set()))}
            # Union-find over the conflict relation -> independent groups.
            _par = {p: p for p in _y}

            def _find(a):
                while _par[a] != a:
                    _par[a] = _par[_par[a]]
                    a = _par[a]
                return a

            for _p in _y:
                for _q in _adj[_p]:
                    _ra, _rb = _find(_p), _find(_q)
                    if _ra != _rb:
                        _par[_rb] = _ra
            _grp = {}
            for _p in _y:
                _grp.setdefault(_find(_p), []).append(_p)
            _Y = sum(max(_y[p] for p in _g) for _g in _grp.values())
            # Hard domain guard: Webster is only valid for Y < 1. Refuse to
            # apply a plan rather than emit a degenerate one.
            if _Y >= 0.98:
                log_to_file(
                    f"[PLAN_OPT] inter={self.id} Y={_Y:.2f} >= 0.98 (oversaturated) "
                    f"-> KEEP network plan, skip optimisation", force=True)
                return
            if _Y <= 0.0:
                log_to_file(f"[PLAN_OPT] inter={self.id} no OD demand -> skip",
                            force=True)
                return
            _L = _n * _ig
            _C = (1.5 * _L + 5.0) / (1.0 - _Y) if _Y < 1.0 else float('inf')
            # Anchor the optimised cycle to the cycle the network ACTUALLY runs.
            # A global 60-150 s band let Webster inflate an 80-135 s corridor to
            # 150 s at every junction; a signal-timing change that far from the
            # commissioned plan is never an improvement in practice.
            _Cbase = self._signal_cycle_s(timeSta) or 0.0
            _lo = float(globals().get('PLAN_CYCLE_MIN_S', 60.0))
            _hi = float(globals().get('PLAN_CYCLE_MAX_S', 150.0))
            _band_pct = 20.0
            if _Cbase > 0.0:
                _band = float(globals().get('PLAN_CYCLE_BAND', 0.20))
                _band_pct = 100.0 * _band
                _lo = max(_lo, _Cbase * (1.0 - _band))
                _hi = min(_hi, _Cbase * (1.0 + _band))
            _C = min(max(_C, _lo), _hi)
            _mg = float(globals().get('PLAN_MIN_GREEN_S', 7.0))
            # Min-green floors must FIT: n_phases x min-green + lost time is a
            # hard lower bound on the cycle. If the floors do not fit inside the
            # band, the plan is infeasible at this junction -- keep the network
            # plan instead of emitting an over-long, all-floors cycle.
            if _n * _mg + _L > _C + 1e-6:
                log_to_file(
                    f"[PLAN_OPT] inter={self.id} n_ph={_n} min-green {_n*_mg:.0f}s"
                    f" + lost {_L:.0f}s > C={_C:.0f}s -> KEEP network plan",
                    force=True)
                return
            # transit weight on the bus phase from the timetable intensity
            _tw = 1.0
            if _bp in _y:
                _tw = 1.0 + float(globals().get('PLAN_TRANSIT_WEIGHT', 0.5)) \
                    * float(self._timetable_intensity())
            _w = {_ph: (_y[_ph] * (_tw if _ph == _bp else 1.0)) for _ph in _y}
            _wsum = sum(_w.values()) or 1.0
            _eff = _C - _L                            # effective green budget
            # ── BUGFIX 2026-09-30: allocate with a floor-and-redistribute pass so
            # sum(greens) == C - L EXACTLY. The old code floored at _mg, rescaled,
            # then floored AGAIN; when the floors bound (common once C is large)
            # the second floor silently broke the identity and the applied plan
            # did not sum to its own cycle (kg inter=39590: 158.8 s applied for a
            # nominal 150 s cycle). Water-filling: start from the floor, hand out
            # the surplus in proportion to weight, respecting the floor.
            _greens = {p: _mg for p in _w}
            _slack = _eff - _n * _mg
            if _slack > 0:
                _rem_w = dict(_w)
                for _ in range(24):                 # converges fast; bounded anyway
                    _s = sum(_rem_w.values())
                    if _s <= 1e-12:
                        break
                    _add = {}
                    for _p in _w:
                        _share = _slack * (_rem_w[_p] / _s)
                        if _share > 1e-9:
                            _add[_p] = _share
                            _rem_w[_p] = 0.0
                    if not _add:
                        break
                    for _p, _a in _add.items():
                        _greens[_p] += _a
                    _slack -= sum(_add.values())
                    if _slack <= 1e-6:
                        break
            # Final exactness pass: put any residue on the largest-weight phase.
            _resid = _eff - sum(_greens.values())
            if abs(_resid) > 1e-6:
                _best = max(_w, key=lambda p: _w[p]) if _w else None
                if _best is not None and _greens[_best] + _resid >= _mg - 1e-6:
                    _greens[_best] += _resid
            # Round to the 0.1 s the network is driven at, then force
            # sum(greens) + lost == C exactly by correcting the largest phase:
            # rounding is the last thing that can break the identity.
            _applied = {p: round(float(_greens.get(p, _mg)), 1) for p in range(1, _n + 1)}
            _resid = round(_C - _L - sum(_applied.values()), 1)
            if abs(_resid) >= 0.05 and _applied:
                _best = max(_applied, key=lambda p: _applied[p])
                if _applied[_best] + _resid >= _mg:
                    _applied[_best] = round(_applied[_best] + _resid, 1)
            _targets = {p: float(v) for p, v in _applied.items()}
            for _ph, _dur in _applied.items():
                try:
                    ECIChangeTimingPhase(_jid, _ph, float(_dur), timeSta)
                except Exception:
                    pass
            # Cache the optimized splits so _reassert_plan can re-impose them each
            # cycle if the fixed control plan reverts them; make the optimized bus
            # green the nominal one so RECOVERY restores to the optimized base too.
            self._plan_target_greens = _targets
            try:
                if _bp in _targets:
                    self.BusPhaseDuration = _targets[_bp]
                self._coord_phase_cache = None   # re-cache coord base from new plan
                self._signal_cycle_cache = float(_C)
            except Exception:
                pass
            # Log the self-consistency check: sum(greens)+lost must equal C, else
            # Aimsun is running a cycle we did not intend (this is how the 158.8 s
            # / 150 s mismatch was found).
            _sum_g = round(sum(_applied.values()), 1)
            _ok = abs(_sum_g + _L - _C) < 0.15
            log_to_file(
                f"[PLAN_OPT] inter={self.id} C={_C:.0f}s Y={_Y:.2f} "
                f"(Cbase={_Cbase:.0f}s band=+/-{_band_pct:.0f}%) L={_L:.0f}s "
                f"busphase={_bp} tw={_tw:.2f} sumG={_sum_g:.1f} "
                f"sumG+L={_sum_g + _L:.1f} {'OK' if _ok else 'MISMATCH'} "
                f"greens={_applied}", force=True)
            if not _ok:
                log_to_file(
                    f"[PLAN_OPT] inter={self.id} WARN cycle identity violated "
                    f"({_sum_g + _L:.1f} != {_C:.1f})", force=True)
            # ── Corridor GREEN-WAVE OFFSET (Eq. plan_offset) ────────────────────
            # Seed this junction's offset relative to the corridor anchor by a
            # one-time transient: extend the CURRENT phase by phi (mod C) so the
            # cycle here starts phi seconds after the anchor, forming the bus-
            # direction green wave. Same mechanism as an OC action; applied once.
            if bool(globals().get('PLAN_OPTIMIZE_OFFSETS', True)):
                _cc = getattr(self, '_corridor_coord', None)
                if _cc is not None:
                    try:
                        _offs = getattr(_cc, '_plan_offsets', None)
                        if not _offs:
                            _offs = _cc._compute_plan_offsets()
                        _phi = float(_offs.get(int(self.id), 0.0)) % _C
                        if _phi > 0.5:
                            _cur = int(ECIGetCurrentPhase(_jid))
                            _pd = float(GetPhaseDuration(_jid, _cur, timeSta))
                            _shift = min(_phi, _C - _mg)   # bounded startup transient
                            ECIChangeTimingPhase(_jid, _cur, _pd + _shift, timeSta)
                            log_to_file(f"[PLAN_OFFSET] inter={self.id} "
                                        f"phi={_phi:.1f}s applied (green-wave)",
                                        force=True)
                    except Exception:
                        pass
        except Exception as _e:
            log_to_file(f"[PLAN_OPT] inter={self.id} error {_e!r}", force=True)

    def _reassert_plan(self, time, timeSta):
        """Re-impose the optimized splits each cycle so a fixed control plan that
        Aimsun re-asserts cannot silently revert PLAN_OPTIMIZE. Only acts when the
        signal is AT REST (no active TSP grant) so it never fights an online GE/INS/
        OC action -- during a grant it yields, and after recovery it nudges the phase
        back to its optimized target. Cheap: only the current phase, only on drift."""
        _tgt = getattr(self, '_plan_target_greens', None)
        if not _tgt:
            return
        # Yield while a TSP action is active (respect the online recourse layer).
        if float(time) < float(getattr(self, 'TSPActiveTime', 0.0) or 0.0):
            return
        try:
            _jid = int(getattr(self, 'node_id', 0) or 0) or int(self.id)
            _cur = int(ECIGetCurrentPhase(_jid))
            _want = float(_tgt.get(_cur, 0.0) or 0.0)
            if _want <= 0.0:
                return
            _live = float(GetPhaseDuration(_jid, _cur, timeSta) or 0.0)
            if abs(_live - _want) > 1.0:      # only when the plan drifted
                ECIChangeTimingPhase(_jid, _cur, _want, timeSta)
        except Exception:
            pass

    def _signal_cycle_s(self, timeSta: float = 0.0) -> float:
        """True signal cycle length (s), discovered from the network itself.

        Corridor-agnostic by construction: the live sum of phase durations is
        tried FIRST, so this works on a config that carries nothing but
        `IntersectionID` (logan_road_new is exactly that -- it discovers
        phases, sections, detectors and cycle lengths from the Aimsun model at
        runtime, and supplies no CycleTime/cycle_length/SaturationFlow keys at
        all).  Config values are only a fallback for when the signal API is not
        answering yet.

        Deliberately NOT `self.cycle_len_s`: that is the TSP *decision cadence*
        and is overridden by TSP_CYCLE_LENGTH_OVERRIDE_S (135 s in the current
        kg sweep).  It coincides with kg's cycle by accident, but it is a
        different quantity and using it would silently mis-scale any corridor
        whose sweep sets a cadence unequal to its cycle.

        Cached after the first successful discovery.
        """
        _c = getattr(self, '_signal_cycle_cache', 0.0)
        if _c and _c > 0:
            return _c
        _ct = 0.0
        try:
            for _ph in (getattr(self, 'phase_list', None) or []):
                _ct += float(GetPhaseDuration(self.node_id, _ph, timeSta) or 0.0)
        except Exception:
            _ct = 0.0
        if _ct <= 0.0:
            try:
                _cfg = getattr(self, 'config', {}) or {}
                _ct = float(_cfg.get('CycleTime', _cfg.get('cycle_length', 0)) or 0.0)
            except Exception:
                _ct = 0.0
        if _ct <= 0.0:
            try:
                _ct = float(URTSP_DEFAULTS.get('cycle_length', 135.0))
            except Exception:
                _ct = 135.0
        # Only cache a value that actually came from the network/config, so a
        # transient API miss at t=0 does not freeze the default in place.
        if _ct > 0.0:
            self._signal_cycle_cache = _ct
        return _ct

    def _detection_rearm_s(self) -> float:
        """Re-arm window for the detection counter, derived from this junction.

        Must exceed the longest plausible SINGLE approach, or one approach gets
        counted twice; must stay well short of a genuine repeat visit.  Derived
        from the detection zone this controller actually uses
        (`min(cycle*14, 500) m`, see detect_bus) traversed at a congested-bus
        crawl, and from the cycle itself since a bus can be held across more
        than one cycle at a saturated approach.
        """
        try:
            _zone_m = min(float(getattr(self, 'urtsp_cycle_length', 135.0)) * 14.0, 500.0)
        except Exception:
            _zone_m = 500.0
        _v_crawl_mps = 2.5          # ~9 km/h
        return max(_zone_m / _v_crawl_mps, 2.0 * self._signal_cycle_s(), 120.0)

    def _record_detection(self, time, veh_id=None, inter_id=None):
        """Edge-triggered detection stat: one event per (junction, bus) approach.

        `stats.record_tsp_event(..., 'detection')` was called from 25 sites
        scattered through the TSP decision tree.  Only `run_normal`'s site was
        edge-triggered (it gates on `_normal_det_active`); the 17 sites in
        `check_bus_priority`, the 2 in the reward path and — worst — the
        all-controllers sweep in `_aapi_post_manage_impl` ("record detection
        passes for intersections with buses") fired EVERY simulation step for
        as long as a bus sat in the zone.  Measured on CELLQLEARN seed 300:
        18 398 reported detections against 324 real (junction, bus) approaches,
        a 57x inflation, spread evenly across all 12 junctions.  NO_TSP, which
        only reaches `run_normal`, reported a correct 301.

        Returns True when the event was actually counted, so callers can keep a
        paired stat (e.g. record_tsp_skip) consistent with it.
        """
        _iid = self.id if inter_id is None else inter_id
        try:
            _vid = int(veh_id if veh_id is not None
                       else (getattr(self, 'last_detected_bus_id', -1) or -1))
        except Exception:
            _vid = -1
        if _vid <= 0:
            # No identifiable bus: record unconditionally, exactly as before.
            # Suppressing here would silently under-count the detector-edge
            # path, which is already correct.
            self.stats.record_tsp_event(_iid, 'detection')
            return True
        _key = (_iid, _vid)
        if (time - self._detection_seen.get(_key, -1e9)) < self._detection_rearm_s():
            return False
        self._detection_seen[_key] = time
        self.stats.record_tsp_event(_iid, 'detection')
        return True

    def update_queue_model(self, time):
        det_sec_cache = getattr(self, '_det_sec_cache', {})
        # Maximum plausible approach flow: 1.5× saturation (handles multi-turn aggregation)
        _max_flow = max(self.SaturationFlow * 1.5, 3600.0)

        # ── Fallback: no physical detectors → derive flow from section vehicle counts ──
        _has_det = any(self.UpDetList)
        if not _has_det:
            # Preferred: continuous rolling window-count of all vehicles that
            # crossed (live-detection tracking). Falls back internally to the
            # instantaneous occupancy density scan when counters are empty.
            self._refresh_live_flow_rolling(time)
            self._populate_flow_from_sections(time)

        # ── Red-duration ceiling ─────────────────────────────────────────────
        # RedStartTimeList is stamped ONLY when a phase is the one that just
        # ended (see update()).  A phase/lane slot that never runs keeps its
        # initial 0.0 forever, so `time - 0` made red_duration equal the whole
        # simulation clock (measured: junction 39587 reported red=4462 s, i.e.
        # sw_red_s == sim_time_s in 72/75 snapshot rows).  MaxQueueLength is
        # LINEAR in red_duration, so the queue estimate diverged to 1301 veh on
        # an approach whose measured queue was 0-92 veh, and that bogus queue
        # fed straight into the reward model.  Cap at two signal cycles: a
        # movement can legitimately stay red across a skipped cycle, but beyond
        # that the queue is storage-bound, not arrival-bound.
        # Cycle comes from the network, not from a config key -- a minimal
        # config (logan_road_new supplies only IntersectionID) must cap at ITS
        # cycle, not at kg's 135 s.
        _red_cap_s = max(2.0 * self._signal_cycle_s(), 60.0)

        for i in range(len(self.UpDetList)):
            for j in range(len(self.UpDetList[i])):
                # Lazy init: a slot still holding the 0.0 sentinel has never
                # been stamped by a phase transition.  Adopt `time` as its red
                # start so the duration grows from now instead of from t=0.
                if self.RedStartTimeList[i][j] <= 0.0 and time > 0.0:
                    self.RedStartTimeList[i][j] = time
                red_duration = min(time - self.RedStartTimeList[i][j], _red_cap_s)
                if red_duration > 0:
                    self.RedDurationList[i][j] = red_duration
                    # Clamp red_duration to at least 5 s before converting count→flow
                    # to prevent explosion when the sim first enters red on the last step.
                    _red_dur_clamped = max(red_duration, 5.0)

                    if self.UpDetCountList[i][j] > 0:
                        # Preferred: aggregated detector count → flow rate
                        flow = self.UpDetCountList[i][j] * 3600.0 / _red_dur_clamped
                        # Safety cap: never exceed 1.5× saturation flow
                        flow = min(flow, _max_flow)
                    else:
                        # Fallback: instantaneous density from live vehicle scan.
                        # Chain-count across short sections: a stub detector
                        # section misses everything upstream of it (the same
                        # blind spot side streets had). Falls back to the
                        # single section when the walk adds nothing.
                        sec_info = det_sec_cache.get((i, j))
                        if sec_info is not None:
                            sec_id, sec_len_m = sec_info
                            try:
                                _mzone = float(self._queue_zone_m(True))
                            except Exception:
                                _mzone = 60.0
                            try:
                                _zc, _zl, _zw = self._zone_queue_count(sec_id, _mzone)
                                if _zl and _zl > 0.0:
                                    n_veh, sec_len_m = _zc, _zl
                                else:
                                    raise ValueError("empty chain")
                            except Exception:
                                try:
                                    n_veh = max(int(AKIVehStateGetNbVehiclesSection(sec_id, False)), 0)
                                except Exception:
                                    n_veh = 0
                            try:
                                _sec_inf = AKIInfNetGetSectionANGInf(sec_id)
                                n_lanes_sec = max(
                                    int(getattr(_sec_inf, 'nbCentralLanes', 0))
                                    + int(getattr(_sec_inf, 'nbSideLanes', 0)), 1)
                            except Exception:
                                n_lanes_sec = max(self.NumberOfLanes, 1)
                            density_per_lane = n_veh / n_lanes_sec / max(sec_len_m / 1000.0, 0.001)
                            # Cap at 90% SatDen so shockwave denominator stays non-zero
                            density_fallback = min(density_per_lane, self.SaturationDensity * 0.9)
                            flow = density_fallback * self.SaturationFlow / max(self.SaturationDensity, 1.0)
                        else:
                            # No physical detector count and no detector-section
                            # cache entry.  _populate_flow_from_sections() may have
                            # already set a value from live vehicle scans — keep it.
                            flow = (self.UpFlowList[i][j]
                                    if (not _has_det and self.UpFlowList[i][j] > 0)
                                    else 0.0)

                    self.UpFlowList[i][j] = flow
                    # LWR: k = q / v_f = q * k_sat / q_sat  (v_f = q_sat/k_sat)
                    self.UpDenList[i][j] = (
                        flow * self.SaturationDensity / self.SaturationFlow
                        if self.SaturationFlow > 0 else 0.0)

                    # ── Measured-state feed (shockwave-grade stats) ──
                    # Gated by MEASURED_STATE_FEED (arm-level flag, default off).
                    # Rules, both unit-safe by construction:
                    #  INTENSIVE -> adopt: approach density IS section density
                    #    (same units); replaces the imposed LWR k above.
                    #  EXTENSIVE -> cap only: a phase/detector flow can never
                    #    exceed its section's verified total (subset <= whole).
                    #    Never inflates, only corrects over-estimates.
                    # Queues deliberately untouched here: MaxQueueLength is a
                    # per-cycle MAXIMUM while measurements are instantaneous --
                    # capping a max by an instant would undercount by design.
                    # (MPC initial conditions already take measured queues.)
                    # Freshness: entries older than 90 s (≈3 samples) are ignored.
                    try:
                        if bool(globals().get('MEASURED_STATE_FEED', False)):
                            _mf = globals().get('_MEAS_FEED')
                            if isinstance(_mf, dict):
                                _mf["seen"] = int(_mf.get("seen", 0) or 0) + 1
                                if not globals().get('_MEAS_FEED_LOGGED', False):
                                    globals()['_MEAS_FEED_LOGGED'] = True
                                    log_to_file(
                                        "[MEAS-FEED] ENGAGED this run "
                                        f"(flag True, build {ENGINE_BUILD})",
                                        force=True)
                            _sec_info = det_sec_cache.get((i, j))
                            if _sec_info is not None:
                                _stt = (getattr(stats, 'latest_section', None)
                                        or {}).get(int(_sec_info[0]))
                                if (_stt is not None and abs(
                                        float(time) - float(_stt.get("t", -1e9))) <= 90.0):
                                    _mk = float(_stt.get("k", 0) or 0)
                                    if _mk > 0:
                                        self.UpDenList[i][j] = _mk
                                        if isinstance(_mf, dict):
                                            _mf["den"] = int(_mf.get("den", 0) or 0) + 1
                                    _sq = float(_stt.get("q", 0) or 0)
                                    if _sq > 0 and flow > _sq:
                                        self.UpFlowList[i][j] = _sq
                                        if isinstance(_mf, dict):
                                            _mf["cap"] = int(_mf.get("cap", 0) or 0) + 1
                    except Exception:
                        pass

                    self.ShockwaveSpeed1List[i][j] = ShockwaveSpeed1(
                        self.UpFlowList[i][j], self.JamDensity, self.UpDenList[i][j])
                    self.ShockwaveSpeed2List[i][j] = ShockwaveSpeed2(
                        self.SaturationFlow, self.SaturationDensity, self.JamDensity)
                    self.ShockwaveSpeed3List[i][j] = ShockwaveSpeed3(
                        self.SaturationFlow, self.UpFlowList[i][j],
                        self.SaturationDensity, self.UpDenList[i][j])
                    self.ShockwaveSpeed4List[i][j] = ShockwaveSpeed4(
                        self.SaturationFlow, self.JamDensity, self.SaturationDensity)

                    w1 = self.ShockwaveSpeed1List[i][j]
                    w2 = self.ShockwaveSpeed2List[i][j]
                    w3 = self.ShockwaveSpeed3List[i][j]
                    w4 = self.ShockwaveSpeed4List[i][j]
                    denom = abs(w2) - abs(w1)
                    if abs(denom) < 1e-6:
                        continue

                    self.MaxQueueLength[i][j]     = abs(w2 * w1 * red_duration / denom)
                    self.MaxQueueLengthTime[i][j] = (
                        self.RedStartTimeList[i][j] + abs(w2) * red_duration / denom)

                    if abs(w3) > 1e-6:
                        self.QueueDissTime[i][j] = (
                            self.MaxQueueLengthTime[i][j]
                            + self.MaxQueueLength[i][j] / abs(w3))
                    else:
                        self.QueueDissTime[i][j] = self.MaxQueueLengthTime[i][j]

                    # Residual queue for next cycle
                    nrs = self.NextRedStartTime[i][j]
                    if self.QueueDissTime[i][j] > nrs and abs(w3) > 1e-6 and abs(w4) > 1e-6:
                        self.MinQueueLength[i][j] = (
                            (self.MaxQueueLength[i][j] / abs(w3)
                             + self.MaxQueueLengthTime[i][j] - nrs)
                            / (1.0 / abs(w3) + 1.0 / abs(w4)))
                        self.MinQueueLengthTime[i][j] = (
                            nrs + self.MinQueueLength[i][j] / abs(w4))
                    else:
                        self.MinQueueLength[i][j]     = 0.0
                        self.MinQueueLengthTime[i][j] = 0.0

                    # ── Measured queue floor (MEASURED_QUEUE_FEED) ──
                    # MaxQueueLength is a per-cycle MAXIMUM from shockwave
                    # theory. A measured standing queue is a LOWER BOUND on
                    # that maximum (the queue was at least this long at sample
                    # time), so the only safe correction is a FLOOR:
                    #   max = max(theory_max, measured_veh)
                    # Never capping (an instant can be below a cycle max) and
                    # never double-counting. Uses the same fresh (<=90 s)
                    # latest_section state as the flow/density feed.
                    try:
                        if bool(globals().get('MEASURED_QUEUE_FEED', False)):
                            _sec_info = det_sec_cache.get((i, j))
                            if _sec_info is not None:
                                _stt = (getattr(stats, 'latest_section', None)
                                        or {}).get(int(_sec_info[0]))
                                if (_stt is not None and abs(
                                        float(time) - float(_stt.get("t", -1e9))) <= 90.0):
                                    _mq = float(_stt.get("queue_veh", 0) or 0) * \
                                        max(int(_stt.get("lanes", 1) or 1), 1)
                                    if _mq > float(self.MaxQueueLength[i][j]):
                                        self.MaxQueueLength[i][j] = _mq
                    except Exception:
                        pass

        # Refresh virtual side-section detector data for use in GE/BP objectives.
        self._sample_side_sections(time)

    def highlight_bus(self, veh_id):
        strategy_name = {1: "GREEN EXTENSION", 2: "PHASE INSERTION"}.get(self.TSPStrategy, "UNKNOWN")
        if LOG_TSP_EVT: AKIPrintString(f"[TSP EVENT] ▶ START | {strategy_name} | veh={veh_id} | inter={self.id}")

    def reset_bus_color(self, veh_id):
        if LOG_TSP_EVT: AKIPrintString(f"[TSP EVENT] ■ END   | veh={veh_id} | inter={self.id}")

    def enforce_starvation_protection(self, time, timeSta, acycle):
        MAX_RED       = 1200000
        current_phase = ECIGetCurrentPhase(self.node_id)
        for phase_id in self.phase_list:
            if phase_id == current_phase or phase_id not in self.PhaseIndex:
                continue
            phase_index = self.PhaseIndex[phase_id]
            red_time    = time - self.RedStartTimeList[phase_index][0]
            if red_time > MAX_RED:
                _vprint(f"STARVATION: phase {phase_id} red for {red_time:.0f}s")
                ECIChangeDirectPhase(self.node_id, phase_id, timeSta, time, acycle, 0)
                return

    def apply_action(self, action, timeSta, time, acycle):
        current_phase = ECIGetCurrentPhase(self.node_id)
        start         = ECIGetStartingTimePhase(self.node_id)
        time_in_phase = time - start
        MIN_GREEN     = 5
        MAX_GREEN     = 60
        if time_in_phase < MIN_GREEN:
            return
        if time_in_phase >= MAX_GREEN:
            next_phase = (current_phase % len(self.phase_list)) + 1
            _vprint(f"MAX_GREEN override → phase {next_phase}")
            ECIChangeDirectPhase(self.node_id, next_phase, timeSta, time, acycle, 0)
            return
        if action < len(self.phase_list):
            target_phase = self.phase_list[action]
            if target_phase != current_phase:
                ECIChangeDirectPhase(self.node_id, target_phase, timeSta, time, acycle, 0)

    def run_rl(self, time, timeSta, acycle):
        state  = self.build_state()
        action = self.rl_agent.select_action(state)
        self.apply_action(action, timeSta, time, acycle)
        reward = -self.step_delay
        self.prev_total_delay = self.step_delay
        next_state = self.build_state()
        if self.TRAIN_MODE:
            self.rl_agent.update(reward, next_state, done=False)

    # ──────────────────────────────────────────────────────────────────────────
    # REWARD_TSP — action-reward based TSP using delay cost-benefit analysis
    # ──────────────────────────────────────────────────────────────────────────
    # Inspired by the MDP framework in Helmstedt & Possingham (2017):
    #   V(s,t) = max_a [ R(s,a) + Σ T_a(s,s')·V(s',t+1) ]
    #
    # Here we use a myopic (one-step lookahead) version:
    #   best_action = argmax_a R(s,a)
    # where R(s,a) = -α·ΔD_bus(a) - β·ΔD_other(a) - γ·ΔD_side(a)
    #
    # Actions evaluated:
    #   NO_ACTION  — do nothing; bus waits for natural green
    #   GE_k       — extend current green by k seconds (if bus phase is active)
    #   INS        — insert bus phase immediately (if bus phase is not active)
    # ──────────────────────────────────────────────────────────────────────────

    def _next_bus_green_window(self, time, timeSta):
        """(start_in_s, end_in_s) of the NEXT bus-phase green from NOW.

        Walks the live plan forward (phase durations via GetPhaseDuration).
        (0.0, remaining) when the bus phase is green now. (None, None) when
        the plan cannot be read (callers fail open). Answers "will the signal
        get the next green" for a pre-armed bus before any grant is spent.
        Prefers this junction's pushed post-change plan (upstream direction):
        same-tick commits are visible without waiting for ECI polling."""
        try:
            _push = self._pushed_plan()
        except Exception:
            _push = None
        try:
            _bp = int(getattr(self, 'BusPhase', -1) or -1)
            _phs = list(getattr(self, 'phase_list', []) or [])
            if _bp < 1 or not _phs:
                return None, None
            try:
                _cur = int(ECIGetCurrentPhase(self.node_id))
            except Exception:
                return None, None
            try:
                _ps0 = float(ECIGetStartingTimePhase(self.node_id))
            except Exception:
                _ps0 = float(time)
            _el = max(0.0, float(time) - _ps0)
            if _cur == _bp:
                try:
                    _rem = max(0.0, float(GetPhaseDuration(
                        self.node_id, _cur, timeSta) or 0.0) - _el)
                except Exception:
                    _rem = 0.0
                # Pushed GE on the live phase lengthens it past ECI until the
                # executor applies: overlay so the window is post-commit truth.
                try:
                    if isinstance(_push, dict) and int(
                            _push.get("phase", -1)) == int(_cur):
                        _rem = max(0.0, float(_push.get(
                            "bus_phase_dur", 0.0)) - _el)
                except Exception:
                    pass
                return 0.0, _rem
            try:
                _ci = _phs.index(_cur); _bi = _phs.index(_bp)
            except Exception:
                return None, None
            _n = len(_phs)
            try:
                _t = max(0.0, float(GetPhaseDuration(
                    self.node_id, _cur, timeSta) or 0.0) - _el)
            except Exception:
                _t = 0.0
            for _k in range(1, (_bi - _ci) % _n):
                try:
                    _t += max(0.0, float(_dur_or_live(
                        self.node_id, _phs[(_ci + _k) % _n], timeSta) or 0.0))
                except Exception:
                    pass
            try:
                _g = max(0.0, float(_dur_or_live(
                    self.node_id, _bp, timeSta) or 0.0))
            except Exception:
                _g = 0.0
            # Pushed bus-green length wins over the ECI read (same-tick
            # commits visible to upstream checks with no polling gap).
            try:
                if isinstance(_push, dict) and float(
                        _push.get("bus_phase_dur", 0.0)) > 0.0:
                    _g = max(0.0, float(_push["bus_phase_dur"]))
            except Exception:
                pass
            return _t, _t + _g
        except Exception:
            return None, None

    def _prearm_feasible(self, eta_from_now, time, timeSta):
        """Can the next bus-phase green serve a bus arriving in eta seconds?

        (True, why); False ONLY when the ETA provably falls beyond green_end
        + max bridgeable hold (BP_upper_bound / MAX_GE_EXTENSION_S) -- a grant
        sized for such an arrival expires before the bus gets there (the
        burst-grant failure: consecutive-junction grants in bursts timed
        nothing like the arrival). Fail-open True on any unreadable plan state
        so the gate can never wedge control."""
        try:
            _w = self._next_bus_green_window(time, timeSta)
        except Exception:
            return True, "unknown"
        if not _w or _w[0] is None:
            return True, "unknown"
        try:
            _bridge = max(float(getattr(self, 'BP_upper_bound', 0) or 0.0),
                          float(globals().get('MAX_GE_EXTENSION_S', 10.0) or 10.0),
                          5.0)
        except Exception:
            _bridge = 10.0
        try:
            _eta = float(eta_from_now)
            if _eta <= float(_w[1]) + _bridge:
                return True, ("natural" if _eta <= float(_w[1]) else "bridged")
            return False, ("eta %.0fs beyond green_end %.0fs+bridge %.0fs"
                           % (_eta, float(_w[1]), _bridge))
        except Exception:
            return True, "unknown"

    def _reward_estimate_no_action(self, time, timeSta, bus_eta_s):
        """Estimate bus delay if no TSP action is taken."""
        cycle = float(self.cycle_len_s)
        # Worst-case delay a bus can ever face is one full red phase = cycle - BusPhaseDuration.
        # Use this as a cap so far-away buses (eta >> cycle) don't inflate the estimate.
        _max_delay = max(cycle - float(self.BusPhaseDuration), 0.0)

        current_phase = ECIGetCurrentPhase(self.node_id)
        if current_phase == self.BusPhase:
            # Bus phase is active — how much time remains?
            _ps = ECIGetStartingTimePhase(self.node_id)
            _pd = GetPhaseDuration(self.node_id, current_phase, timeSta)
            _remain = max(0.0, _pd - (time - _ps))
            if bus_eta_s <= _remain:
                return 0.0  # bus makes the natural green
            # Bus misses this green — cap at worst-case one-cycle wait
            raw = bus_eta_s - _remain + _max_delay
            return min(raw, _max_delay)
        else:
            # Compute time until next BusPhase green
            _ps_now = ECIGetStartingTimePhase(self.node_id)
            _elapsed = max(0.0, time - _ps_now)
            _rem_cur = max(0.0,
                GetPhaseDuration(self.node_id, current_phase, timeSta) - _elapsed)
            _time_to_bp = _rem_cur
            try:
                _ci = self.phase_list.index(current_phase)
                _bi = self.phase_list.index(self.BusPhase)
                _n  = len(self.phase_list)
                _steps = (_bi - _ci) % _n
                for _k in range(1, _steps):
                    _ph = self.phase_list[(_ci + _k) % _n]
                    _time_to_bp += GetPhaseDuration(self.node_id, _ph, timeSta)
            except Exception:
                _time_to_bp = cycle
            if bus_eta_s <= _time_to_bp + self.BusPhaseDuration:
                return max(0.0, _time_to_bp - bus_eta_s)
            # Bus misses the next natural green — cap at one full red wait
            return min(_max_delay, max(0.0, _time_to_bp + cycle - bus_eta_s))

    def _reward_objective_snapshot(self, extra_side_red: float = 0.0):
        """
        Snapshot the current objective arrays in passenger-delay units.

        This lets REWARD_TSP compare actions using the same occupancy-weighted
        delay logic as the harmony objective functions.
        """
        other_occ = self._estimated_other_vehicle_occupancy()
        bus_delay_s = max(self._safe_array_sum(self.BusDelay), 0.0)
        other_delay_s = max(self._safe_array_sum(self.OtherDelay), 0.0)
        side_delay_s = 0.0
        if extra_side_red > 1e-6:
            try:
                side_delay_s, _ = self._compute_side_delay_penalty(extra_side_red)
            except Exception:
                side_delay_s = 0.0
        side_delay_s = max(safe_float(side_delay_s), 0.0)
        bus_occ = max(safe_float(self.BusOcc), 0.0)
        return {
            "bus_delay_s": bus_delay_s,
            "other_delay_s": other_delay_s,
            "side_delay_s": side_delay_s,
            "bus_delay_pax_s": bus_delay_s * bus_occ,
            "other_delay_pax_s": other_delay_s * other_occ,
            "side_delay_pax_s": side_delay_s * other_occ,
        }

    def _measured_network_cost_factor(self) -> float:
        """Return a measured-network correction multiplier for the analytic
        car-cost term.

        The analytic cross-traffic estimate (``_dctsp_cross_traffic_delay_s``)
        is derived from nominal flow/shock-wave assumptions and is known to
        UNDER-estimate the real cost a TSP action imposes on the surrounding
        network (downstream spillback, platoon break-ups, lost main-street
        throughput).  This method measures the actual congestion from the sim's
        own tracked state (average density / queue) and scales the analytic
        cost up when the network is more loaded than the saturation-flow
        assumption implies.  When there is no data it returns 1.0 so behaviour
        is unchanged.
        """
        try:
            _meas = getattr(self.stats, '_inter_dsf_avg', None)
            _jam = safe_float(getattr(self, 'JamDensity', 0.0))
            if _meas is None or _jam <= 0:
                return 1.0
            _state = self.stats._inter.get(self.id, {})
            if not _state:
                return 1.0
            # Average network occupancy proxy: measured v/c from tracked density.
            _den = _meas(self.id, 'density_sum')
            _vc = (_den / _jam) if _den > 0 else 0.0
            # Ramp from 1x at v/c=0 to 3x at v/c=1.0.
            #
            # This used to ramp to 200x on the claim that the analytic model
            # under-predicts by >100x.  That claim was never calibrated, and
            # stacked with CROSS_TRAFFIC_COST_MULTIPLIER (2x) and the
            # multi-cycle 1/(1-x) term (up to 50x) it gave ~20 000x of
            # multiplicative headroom on a cost already quadratic in action
            # duration.  Measured result: other_inc_pax_s reached 1.94e9 pax-s
            # against a bus benefit that maxes out at ~4 080 pax-s, so every
            # candidate lost to NO_ACTION (804 of 978 decisions) and TSP
            # collapsed onto the do-nothing policy.  A congestion correction
            # is defensible; three orders of magnitude of it is not.
            if _vc < 0.1:
                return 1.0
            # Restored from the 1->3x cut (which under-priced cross cost ~30x and
            # let the act-gate over-fire into gridlock -- measured car delay
            # +260% while the model estimated ~176 pax-s/action).  1->20x ramp is
            # the calibrated middle: still bounded, but actions now carry a
            # realistic cross cost.  The closed-loop reward measures the TRUE
            # car cost regardless; this keeps the analytic seed sane.
            _factor = 1.0 + _vc * 19.0
            return min(max(_factor, 1.0), 20.0)
        except Exception:
            return 1.0

    def _ctm_cross_cost_paxs(self, action_s: float, timeSta: float = 0.0) -> float:
        """GENUINE MULTI-CELL Cell-Transmission-Model cross-approach cost (pax·s) of
        holding the conflicting movements RED `action_s` seconds longer.

        Each conflicting (cross/side) approach is discretised into a CHAIN of Daganzo
        CTM cells (length L=v_f·dt, so a free-flow vehicle advances one cell per step),
        oriented upstream(cell 0) -> stop line(cell K-1). Per step, per cell i:
          • sending   S_i = min(n_i, Q)                       (demand out of i)
          • receiving R_i = min(Q, (w/v_f)·(N_i - n_i))       (space in i; BACKWARD WAVE)
          • inter-cell flow  y_i = min(S_i, R_{i+1})          (i -> i+1)
          • stop line  y_{K-1} = S_{K-1} if GREEN else 0      (signal gates ONLY here)
          • conservation  n_i(t+dt) = n_i + y_{i-1} - y_i ; cell 0 inflow = min(q_arr·dt, R_0)
        A downstream cell that fills (red at the stop line) shrinks its receiving term,
        which throttles the cell behind it -> the queue SPILLS BACK upstream cell by
        cell (the physics a single stop-line cell cannot represent).

        Parameterised from the Aimsun plant so the controller matches the simulator:
        SaturationFlow -> Q, JamDensity -> per-cell storage N_i, section speed-limit ->
        v_f (cell length), measured arrivals (`_measured_section_flow_vph`), and the
        current micro-queue (`_zone_queue_count`, filled into the stop-line cells).
        Cost = EXTRA vehicle-seconds (Σ over cells & steps) under `action_s` more red
        vs none, × CarOcc, summed over conflicting approaches. Backward-wave speed and
        free-flow are tunable (CELLQ_CTM_WAVE_KMH / CELLQ_CTM_FREEFLOW_KMH); cell count
        is capped (CELLQ_CTM_MAX_CELLS). Returns pax·s (>=0); 0 on missing plant data.
        """
        try:
            if action_s <= 0.0:
                return 0.0
            _dt = float(globals().get('CELLQ_CTM_DT_S', 1.0) or 1.0)
            _car_occ = max(safe_float(getattr(self, 'CarOcc', 1.0)), 1.0)
            _kj = max(float(getattr(self, 'JamDensity', 150.0) or 150.0), 1.0)   # veh/km/lane
            _sat_h = float(getattr(self, 'SaturationFlow', 1800.0) or 1800.0)    # veh/h/lane
            _vf_kmh = float(globals().get('CELLQ_CTM_FREEFLOW_KMH', 50.0) or 50.0)
            _w_kmh = float(globals().get('CELLQ_CTM_WAVE_KMH', 18.0) or 18.0)
            _max_cells = max(1, int(globals().get('CELLQ_CTM_MAX_CELLS', 10) or 10))
            _secs = list(self._get_side_sections() or [])
            if not _secs:
                return 0.0
            _cyc = float(self._signal_cycle_s(timeSta)) if hasattr(self, '_signal_cycle_s') else 120.0
            _horizon = min(float(action_s) + max(_cyc, 60.0), 300.0)
            _n_steps = max(1, int(round(_horizon / _dt)))
            _extra_red_steps = max(0, int(round(float(action_s) / _dt)))
            _total = 0.0
            for _sec in _secs:
                try:
                    _lanes = max(int(self._sec_lane_count(int(_sec))) if hasattr(self, '_sec_lane_count') else 1, 1)
                    _q_arr = 0.0
                    if hasattr(self, '_measured_section_flow_vph'):
                        _q_arr = max(0.0, float(self._measured_section_flow_vph(int(_sec)) or 0.0)) / 3600.0
                    if _q_arr <= 0.0:
                        continue
                    # section length + free-flow speed from the plant (per-section
                    # speed limit when exposed, else the flag default).
                    _len_m = 150.0
                    _vf = max(_vf_kmh / 3.6, 1.0)
                    try:
                        _si = AKIInfNetGetSectionANGInf(int(_sec))
                        if getattr(_si, 'report', -1) >= 0 and float(_si.length) > 0:
                            _len_m = float(_si.length)
                        _slim = float(getattr(_si, 'speedLimit', 0.0) or 0.0)      # km/h
                        if _slim > 1.0:
                            _vf = max(_slim / 3.6, 1.0)
                    except Exception:
                        pass
                    _w = max(_w_kmh / 3.6, 0.1)
                    _w_ratio = min(1.0, _w / _vf)
                    _L = max(_vf * _dt, 5.0)                       # cell length (m)
                    # CELLQ_CTM_SINGLE_CELL (2026-10-01): lump the whole approach into
                    # ONE cell of length = section length. This is the fair single-cell
                    # baseline the multi-cell chain is supposed to beat: same storage
                    # (a full approach can fill), same signal gate at the stop line,
                    # but NO inter-cell flow and therefore NO backward-wave spillback.
                    # Note we must set the CELL LENGTH, not just the cell COUNT --
                    # forcing _K=1 while keeping L=v_f*dt leaves a cell that can hold
                    # barely one step of flow, which measures storage error rather
                    # than the absence of spatial structure. With L=_len_m the
                    # existing ceil(_len_m/_L) below yields K=1 on its own.
                    _single_cell = bool(globals().get('CELLQ_CTM_SINGLE_CELL', False))
                    if _single_cell:
                        _L = max(_len_m, 5.0)
                    _K = max(1, min(int(math.ceil(_len_m / _L)), _max_cells))
                    _N = max(_kj * (_L / 1000.0) * _lanes, 1.0)    # veh storage / cell
                    _Q = max(_sat_h / 3600.0 * _lanes * _dt, 1e-6) # max veh / step
                    _inflow = _q_arr * _dt                         # arrivals / step
                    # seed the standing micro-queue into the STOP-LINE cells (K-1 back).
                    _n0 = 0.0
                    try:
                        if hasattr(self, '_zone_queue_count'):
                            _n0 = max(0.0, float(self._zone_queue_count(int(_sec)) or 0.0))
                    except Exception:
                        _n0 = 0.0

                    # ambient free-flow density already on the approach: rho = q/v_f
                    # (veh/m) -> veh per cell, so the moving stream is present in EVERY
                    # cell (a red bites the cells near the stop line immediately, not
                    # only after arrivals travel the whole approach). The standing
                    # micro-queue seeds the stop-line cells ON TOP of the ambient.
                    _amb = min((_q_arr / _vf) * _L, _N)

                    def _init_cells():
                        _c = [_amb] * _K
                        _rem = _n0; _i = _K - 1
                        while _rem > 1e-9 and _i >= 0:
                            _put = min(_rem, max(0.0, _N - _c[_i])); _c[_i] += _put
                            _rem -= _put; _i -= 1
                        return _c

                    def _sim(extra_red_steps):
                        n = _init_cells(); d = 0.0
                        for _k in range(_n_steps):
                            _green = (_k >= extra_red_steps)
                            _S = [min(n[i], _Q) for i in range(_K)]
                            _R = [min(_Q, _w_ratio * max(0.0, _N - n[i])) for i in range(_K)]
                            _y = [0.0] * _K                     # y[i] = flow i -> i+1
                            for i in range(_K - 1):
                                _y[i] = min(_S[i], _R[i + 1])
                            _out = _S[_K - 1] if _green else 0.0  # stop-line discharge
                            _in0 = min(_inflow, _R[0])            # upstream arrivals
                            _nn = n[:]
                            for i in range(_K):
                                _in_i = _in0 if i == 0 else _y[i - 1]
                                _out_i = _out if i == _K - 1 else _y[i]
                                _nn[i] = n[i] + _in_i - _out_i
                            n = [x if x > 0.0 else 0.0 for x in _nn]
                            d += sum(n) * _dt
                        return d

                    _total += max(0.0, _sim(_extra_red_steps) - _sim(0)) * _car_occ
                except Exception:
                    continue
            _nf = float(getattr(_spm, 'NETWORK_FACTOR', 1.0) or 1.0)
            return max(0.0, _total * _nf)
        except Exception:
            return 0.0

    def _dctsp_cross_traffic_delay_s(self, action_s: float,
                                       queue_elapsed_s: float = 0.0,
                                       phases=None) -> float:
        try:
            if action_s <= 0.0:
                return 0.0
            # FLOW_DIAG logs at t≈0 (empty net) AND again mid-run so live vehicle
            # counts can be compared against the flow lists during steady state.
            _now = (float(AKIGetSimulationTime()) if 'AKIGetSimulationTime' in globals() else 0.0)
            _prev = getattr(self, '_flow_diag_at', [])
            # Log on the first call and then every ~600 s of sim time whenever the
            # cost path runs (the old milestone ladder only fired at 900/1800 s and
            # never again -- "doesn't update after 7:45" -- so main-section health
            # could not be checked mid-run).
            _should_log = (not _prev) or (_now - _prev[-1] >= 600.0)
            if _should_log:
                self._flow_diag_at = (_prev + [_now])[-3:]
                try:
                    _diag = []
                    _upf = getattr(self, 'UpFlowList', np.zeros((0, 0)))
                    _upf = np.asarray(_upf, dtype=float)
                    _nz = int(np.count_nonzero(_upf)) if _upf.size else 0
                    _diag.append(f"UpFlowList shape={_upf.shape} nonzero={_nz} "
                                 f"max={float(_upf.max()) if _upf.size else 0.0:.2f}")
                    _suf = getattr(self, 'SideUpFlowList', np.zeros((0,)))
                    _suf = np.asarray(_suf, dtype=float)
                    _nzs = int(np.count_nonzero(_suf)) if _suf.size else 0
                    _diag.append(f"SideUpFlowList len={_suf.size} nonzero={_nzs} "
                                 f"vals={[round(float(v),1) for v in _suf.tolist()]}")
                    _secs = self._get_side_sections()
                    _diag.append(f"side_secs={_secs}")
                    # Report the RAW AKIVehState return: a NEGATIVE value (e.g.
                    # -4002 "not in dynamic simulation" / bad id) was previously
                    # clamped to 0, making a broken section id indistinguishable
                    # from a genuinely-empty section.
                    _live = []
                    for _s in list(_secs)[:6]:
                        try:
                            _live.append(int(AKIVehStateGetNbVehiclesSection(_s, False) or 0))
                        except Exception:
                            _live.append(-999)
                    _diag.append(f"side_live_veh={_live}")
                    _inc = getattr(self, 'incoming_sections', [])
                    _inc_live = []
                    for _s in list(_inc)[:6]:
                        try:
                            _inc_live.append(int(AKIVehStateGetNbVehiclesSection(_s, False) or 0))
                        except Exception:
                            _inc_live.append(-999)
                    _diag.append(f"incoming_sections={_inc} live_veh={_inc_live}")
                    log_to_file("[FLOW_DIAG] inter=%s t=%.0f phase=%s | %s" % (
                        self.id, _now,
                        ECIGetCurrentPhase(self.node_id),
                        " | ".join(_diag)), force=True)
                except Exception as _d_err:
                    log_to_file(f"[FLOW_DIAG] error: {_d_err!r}")
            _nf = _spm.NETWORK_FACTOR

            # ── ANALYTIC COST ──
            cross_pax_s = 0.0
            car_occ = max(safe_float(getattr(self, 'CarOcc', 1.0)), 1.0)
            sat_flow_vps = float(
                getattr(self, 'SaturationFlow', 1800) or 1800
            ) / 3600.0
            upf = getattr(self, 'UpFlowList', np.zeros((1,1)))
            n_phases = upf.shape[0] if hasattr(upf, 'shape') else 0
            if phases is not None:
                _phase_iter = phases
            else:
                # Prefer SIDE-phase rows only when the plan map resolves: the
                # opposite MAIN direction is priced separately by
                # _measured_opposite_main_delay (both-directions discipline,
                # 2026-09-26) -- charging its row here too would double count.
                _phase_iter = None
                try:
                    _phase_iter = self._nonmain_phase_indices()
                except Exception:
                    _phase_iter = None
                if _phase_iter is None:
                    _phase_iter = range(1, n_phases)
            for p in _phase_iter:
                if p < 0 or p >= n_phases:
                    continue
                row = upf[p]
                avg_flow_vph = float(np.mean(row)) if len(row) > 0 else 0.0
                if avg_flow_vph <= 0:
                    continue
                flow_vps = avg_flow_vph / 3600.0
                Q_0 = flow_vps * max(0.0, queue_elapsed_s)
                _phase_delay = Q_0 * action_s * car_occ
                _phase_delay += flow_vps * action_s * (action_s / 2.0) * car_occ
                s_eff = max(sat_flow_vps - flow_vps, sat_flow_vps * 0.10)
                Q_end = Q_0 + flow_vps * action_s
                _phase_delay += (Q_end ** 2) / (2.0 * s_eff) * car_occ
                _x_phase = flow_vps / max(sat_flow_vps, 1e-9)
                _xt = _spm.DCTSP_MULTI_CYCLE_X_THR
                _xf = _spm.DCTSP_MULTI_CYCLE_X_FLOOR
                if p != 0 and _x_phase > _xt:
                    _mc_mult = 1.0 / max(1.0 - _x_phase, _xf)
                    _phase_delay *= _mc_mult
                cross_pax_s += _phase_delay
            _cmult = float(getattr(_spm, 'CROSS_TRAFFIC_COST_MULTIPLIER', 100.0) or 100.0)
            if cross_pax_s <= 0 and action_s > 0:
                _car_occ_v2 = max(safe_float(getattr(self, 'CarOcc', 1.0)), 1.0)
                cross_pax_s = action_s * _car_occ_v2 * 5.0
            # Apply the measured-network correction: the analytic cross model
            # under-predicts real cost (downstream spillback, platoon breakup),
            # so scale it by observed congestion when data exists (1.0 otherwise).
            try:
                _mfac = self._measured_network_cost_factor()
            except Exception:
                _mfac = 1.0
            _cost = max(0.0, cross_pax_s * _nf * _cmult * max(float(_mfac), 1.0))

            # ── Physical plausibility ceiling ────────────────────────────────
            # The deterministic oversaturation term Q_end^2/(2*s_eff) diverges
            # as x -> 1 (s_eff is floored at 10% of saturation) and is then
            # amplified by the multi-cycle 1/(1-x) factor, so a single
            # candidate could be priced in the billions of pax-s.  Bound it by
            # the worst case that is physically possible: every cross approach
            # discharging at saturation, with every vehicle arriving during the
            # action plus one recovery cycle held for that entire window.
            # Guarded: if the ceiling cannot be computed, return the uncapped
            # cost rather than letting the outer `except` return 0.0 -- a zero
            # side cost makes every action look free, which is the far more
            # damaging failure (it is what previously drove hundreds of
            # phase rotations per run).
            try:
                _win = float(action_s) + self._signal_cycle_s()
                _cap = (sat_flow_vps * max(n_phases - 1, 1)
                        * _win * _win * car_occ)
                if _cap > 0.0:
                    _cost = min(_cost, _cap)
            except Exception:
                pass
            # ── CTM cell-to-cell CASCADE (downstream spillback) ──────────────
            # Everything above is a SINGLE cell. The defining CTM feature --
            # vehicles released HERE become the DOWNSTREAM cell's arrivals and
            # SPILL BACK when that cell is full -- is what the local model was
            # blind to, and it is exactly why aggressive TSP gridlocks on some
            # seeds. Add it (pax-s) when CASCADE_COST_MODE is on, so BOTH the
            # net-benefit gate and the Nash bargain price the true network cost.
            if bool(globals().get('CASCADE_COST_MODE', False)):
                try:
                    _cost += float(self._cascade_spillback_paxs(float(action_s)))
                except Exception:
                    pass
            return _cost
        except Exception:
            return 0.0

    def _cascade_spillback_paxs(self, action_s: float) -> float:
        """MULTI-CELL forward CTM spillback cost of releasing extra main vehicles
        into the DOWNSTREAM corridor. Propagates the release hop-by-hop: each
        downstream cell absorbs what its spare storage allows, charges a spillback
        delay if it is congested, and passes the OVERFLOW to the next cell; the
        platoon decays by a turning fraction each hop and stops at the horizon or
        when it dissipates. Returns pax-s (>=0). This is the network cascade the
        single-cell point-queue cost was blind to (corridor gridlock usually
        builds 2-3 junctions down, not at the immediate neighbour)."""
        # WHY-ZERO diagnostic: the [CASCADE] cost-line only logs when >0, so a
        # cascade that never fires is invisible. Log the reason it returns 0
        # (throttled, reuses MEASURED_SIDE_COST_DIAG) so we can tell coord-missing
        # vs junction-not-on-route vs no-downstream-congestion apart. (2026-09-14)
        def _casc_zero(_why):
            if not bool(globals().get('MEASURED_SIDE_COST_DIAG', False)):
                return
            try:
                _t = float(AKIGetCurrentSimulationTime())
            except Exception:
                _t = -1.0
            try:
                _cl = globals().setdefault('_CASCADE_ZERO_LAST', {})
                if _t < 0.0 or (_t - float(_cl.get(int(self.id), -1e9))) >= 30.0:
                    _cl[int(self.id)] = _t
                    log_to_file(f"[CASCADE_ZERO] inter={self.id} act={action_s:.0f}s "
                                f"reason={_why}", force=True)
            except Exception:
                pass
        if action_s <= 0.0:
            return 0.0
        _coord = getattr(self, '_corridor_coord', None)
        if _coord is None:
            _casc_zero("no_corridor_coord")
            return 0.0
        try:
            _order = list(getattr(_coord, 'route_inter_ids', []) or [])
            _ri = getattr(_coord, '_route_index', {}) or {}
            idx = _ri.get(int(self.id))
            if idx is None:
                _casc_zero(f"jct_not_on_route(route_len={len(_order)})")
                return 0.0
            _icm = getattr(_coord, '_ic_map', {}) or {}
            _ctm = getattr(_coord, '_ctrl_map', {}) or {}
            _thr = float(globals().get('CASCADE_SAT_THRESHOLD', 0.45))
            _horizon = max(1, int(globals().get('CASCADE_HORIZON', 4)))
            _turn = min(0.9, max(0.0, float(globals().get('CASCADE_TURN_FRACTION', 0.15))))
            _spill_gain = max(0.0, float(globals().get('CASCADE_SPILL_GAIN', 2.0)))
            _car_occ = max(float(getattr(self, 'CarOcc', 1.6) if hasattr(self, 'CarOcc') else 1.6), 1.0)
            _nf = float(getattr(_spm, 'NETWORK_FACTOR', 1.0) or 1.0)
            try:
                _t_now = float(AKIGetCurrentSimulationTime())
            except Exception:
                _t_now = -1.0
            _ls_meas = getattr(globals().get('stats', None), 'latest_section', None) or {}
            # extra main veh released by `action_s` of extra green at THIS junction
            _extra = (max(float(getattr(self, 'SaturationFlow', 1800.0)), 1.0) / 3600.0) * float(action_s)
            _total = 0.0
            _hops = 0
            _max_sat = 0.0   # highest projected downstream saturation seen (diag)
            _rcm = getattr(_coord, '_route_ctrl_map', {}) or {}
            for j in range(idx + 1, len(_order)):
                down = (_icm.get(int(_order[j])) or _ctm.get(int(_order[j]))
                        or _rcm.get(int(_order[j])))
                if down is None:
                    continue
                _hops += 1
                if _hops > _horizon or _extra <= 1e-3:
                    break
                # downstream cell state (main approach): queue n, storage cap, discharge
                _dupf = np.asarray(getattr(down, 'UpFlowList', np.zeros((1, 1))), dtype=float)
                _dq_arr = (float(np.mean(_dupf[_dupf > 0.0])) / 3600.0
                           if np.any(_dupf > 0.0) else 0.0)
                _drdt = np.asarray(getattr(down, 'RedDurationList', np.zeros((1, 1))), dtype=float)
                _dred = (float(np.max(_drdt[_drdt > 0.0])) if np.any(_drdt > 0.0) else 60.0)
                # PREFER the MEASURED downstream main-approach queue: flow x red
                # under-estimates a genuinely congested queue, so the cascade
                # returned ~0 and NASH over-acted (2026-09-11). MEASURED_QUEUE_FEED
                # gives a truer standing queue via
                # stats.latest_section[sec]['queue_veh']*lanes (fresh <=90 s).
                # Fall back to flow x red only when no fresh measurement exists.
                _n_down = 0.0
                try:
                    _dsecs = (list(getattr(down, 'incoming_sections', []) or [])
                              or list(getattr(down, 'main_sections', []) or []))
                    for _sid in _dsecs:
                        _st = _ls_meas.get(int(_sid))
                        if _st is None:
                            continue
                        if _t_now >= 0.0 and abs(_t_now - float(_st.get('t', -1e9))) > 90.0:
                            continue
                        _n_down += (float(_st.get('queue_veh', 0) or 0.0)
                                    * max(int(_st.get('lanes', 1) or 1), 1))
                except Exception:
                    _n_down = 0.0
                if _n_down <= 0.0:
                    _n_down = max(0.0, _dq_arr * _dred)   # fallback: flow x red
                _kjam = max(float(getattr(down, 'JamDensity',
                                         getattr(down, 'SaturationDensity', 150.0)) or 150.0), 1.0)
                _cap = 0.15 * _kjam                       # per-cell storage (matches _cap_veh)
                _q_sat_d = max(float(getattr(down, 'SaturationFlow', 1800.0)), 1.0) / 3600.0
                # PROJECTED saturation AFTER our released platoon (+ the normal
                # arrivals that queue during the downstream red) reaches this cell.
                # The gridlock forms from the platoon we ADD, so charge on the
                # POST-release state, not the still-moderate CURRENT queue -- the
                # old current-queue test at thr=0.6 returned ~0 on the very seeds
                # that then gridlocked (cross/downstream sat only 0.3-0.5 at
                # decision time; the platoon is what pushes them over). (2026-09-14)
                _arr_red = max(0.0, _dq_arr * _dred)
                _proj = _n_down + _extra + _arr_red
                _sat_proj = _proj / max(_cap, 1.0)
                _max_sat = max(_max_sat, _sat_proj)
                if _sat_proj > _thr:
                    # SUPERLINEAR spillback severity (matches the measured side
                    # cost): as the projected cell fills, the marginal delay of the
                    # added platoon explodes -- the queue can't clear and blocks
                    # upstream, including THIS junction. Bounded at sat<=0.95.
                    _s = min(_sat_proj, 0.95)
                    _sev = 1.0 + _spill_gain * (_s / max(1.0 - _s, 0.05))
                    _wait = _proj / _q_sat_d               # clear the projected queue at sat flow
                    _total += _extra * _wait * _car_occ * _nf * _sev
                    # overflow beyond storage spills to the next downstream cell.
                    _extra = max(0.0, _proj - _cap)
                else:
                    # fits: only the part exceeding spare storage carries downstream.
                    _extra = max(0.0, _extra - max(0.0, _cap - _n_down - _arr_red))
                # platoon thins as vehicles turn off the corridor each hop
                _extra *= (1.0 - _turn)
            # Throttled diagnostic so we can SEE the projected-saturation cascade
            # engage on the gridlock seeds (reuses MEASURED_SIDE_COST_DIAG flag).
            if bool(globals().get('MEASURED_SIDE_COST_DIAG', False)):
                try:
                    _cl = globals().setdefault('_CASCADE_DIAG_LAST', {})
                    if _t_now < 0.0 or (_t_now - float(_cl.get(int(self.id), -1e9))) >= 20.0:
                        _cl[int(self.id)] = _t_now
                        if _total > 0.0:
                            log_to_file(f"[CASCADE] inter={self.id} act={action_s:.0f}s "
                                        f"hops={_hops} cost={_total:.0f}paxs "
                                        f"max_sat={_max_sat:.2f}", force=True)
                        else:
                            # reached the loop but nothing charged -> downstream not
                            # projected-congested. Report the max sat seen + hops so
                            # we know if the threshold (0.45) is the limiter.
                            log_to_file(f"[CASCADE_ZERO] inter={self.id} act={action_s:.0f}s "
                                        f"reason=no_downstream_congestion hops={_hops} "
                                        f"max_sat={_max_sat:.2f} thr={_thr:.2f}", force=True)
                except Exception:
                    pass
            return max(0.0, _total)
        except Exception:
            return 0.0

    def _reward_evaluate_ge(self, ge_s, time, timeSta, bus_eta_s):
        """
        Evaluate a green extension in passenger-delay units.

        Returns (bus_saved_pax_s, other_added_pax_s, side_added_pax_s).
        """
        self.GE_Objective_Function(ge_s, time)
        ge_cost = self._reward_objective_snapshot(extra_side_red=ge_s)

        self.GE_Objective_Function(0.0, time)
        base_cost = self._reward_objective_snapshot(extra_side_red=0.0)

        # Signed passenger-delay deltas (pax·s): NEGATIVE = delay reduced = a
        # network benefit.  `other` covers ALL non-bus vehicles — including the
        # mainline cars served by the extended bus phase — so extending the bus
        # phase now credits the delay reduction those cars enjoy (previously
        # discarded by the max(0, …) clamp) instead of only the single bus.
        bus_delta = ge_cost["bus_delay_pax_s"] - base_cost["bus_delay_pax_s"]
        other_delta = ge_cost["other_delay_pax_s"] - base_cost["other_delay_pax_s"]
        side_delta = ge_cost["side_delay_pax_s"] - base_cost["side_delay_pax_s"]

        # bus_saved: non-negative bus-delay reduction (for logging / thresholds).
        bus_saved = max(0.0, -bus_delta)
        # other_inc / side_inc: SIGNED so a reduction is a negative cost (a
        # benefit that lowers the total-network penalty below).
        other_inc = other_delta
        side_inc = side_delta

        # Fallback: when detector arrays are empty (minimal config), both deltas
        # sit near 0 and the shockwave estimators return 0.  Without a cost
        # floor the controller sees only bus benefit and fires aggressively,
        # crushing side streets.  Apply the cross-traffic floor with MAX so it
        # binds whenever no measured benefit/cost is available.
        if abs(other_inc) < 1.0 and abs(side_inc) < 1.0:
            _car_occ = max(safe_float(getattr(self, 'CarOcc', 1.6)), 1.0)
            _cross_pax = self._dctsp_cross_traffic_delay_s(ge_s)
            other_inc = max(other_inc, _cross_pax * 0.5)
            _sd, _ = self._compute_side_delay_penalty(ge_s, _suppress_log=True)
            # Opposite-direction mainline cost (2026-09-26): the analytic
            # fallback priced only the cross street; price the OTHER corridor
            # direction too (measured-queue mirror), so a bus-free GE is
            # quantified against BOTH directions.
            try:
                _opp = float(self._measured_opposite_main_delay(ge_s))
            except Exception:
                _opp = 0.0
            side_inc = max(side_inc, _sd) + _opp

        return bus_saved, other_inc, side_inc

    def _reward_evaluate_insertion(self, ins_dur, time, timeSta, bus_eta_s):
        """
        Evaluate a phase insertion in passenger-delay units.

        Returns (bus_saved_pax_s, other_added_pax_s, side_added_pax_s).
        """
        # Bus delay saved: difference between waiting for natural green and insertion
        no_action_bus_delay = self._reward_estimate_no_action(time, timeSta, bus_eta_s)
        baseline_bus_cost = max(0.0, no_action_bus_delay) * max(safe_float(self.BusOcc), 0.0)
        # With insertion, bus gets green immediately — delay is just the ETA
        # Snapshot the no-action network (cars) state BEFORE modifying the plan.
        no_act_cost = self._reward_objective_snapshot(extra_side_red=0.0)
        self.BP_Objective_Function(ins_dur, time)
        action_cost = self._reward_objective_snapshot(extra_side_red=ins_dur + 5.0)
        bus_saved = max(0.0, baseline_bus_cost - action_cost["bus_delay_pax_s"])

        # Total-network (cars) delay change: SIGNED so that the mainline cars
        # served by the inserted bus phase count as a benefit (negative cost),
        # not just the bus.  Cross/side traffic that loses green is the cost.
        other_increase = action_cost["other_delay_pax_s"] - no_act_cost["other_delay_pax_s"]
        side_delay = action_cost["side_delay_pax_s"] - no_act_cost["side_delay_pax_s"]

        # Fallback for minimal configs without detector arrays (same as GE)
        if abs(other_increase) < 1.0 and abs(side_delay) < 1.0:
            _car_occ = max(safe_float(getattr(self, 'CarOcc', 1.6)), 1.0)
            _cross_pax = self._dctsp_cross_traffic_delay_s(ins_dur)
            other_increase = max(other_increase, _cross_pax * 0.5)
            _sd, _ = self._compute_side_delay_penalty(ins_dur + 5.0, _suppress_log=True)
            # Opposite-direction mainline cost (2026-09-26): a phase insertion
            # takes time from the OTHER corridor direction too -- price its
            # measured queue (both-directions discipline, as above).
            try:
                _opp = float(self._measured_opposite_main_delay(ins_dur + 5.0))
            except Exception:
                _opp = 0.0
            side_delay = max(side_delay, _sd) + _opp

        return bus_saved, other_increase, side_delay

    def _maybe_skip_empty_phase(self, time, timeSta, acycle, current_phase):
        """Rule C: if the CURRENT phase has essentially no queue and the pressure
        lies on another phase, truncate the current green so the fixed plan
        advances toward the pressured phase -- i.e. give the freed time to the
        most-pressured phase (MaxPressure intent), using the same tested
        ECIChangeTimingPhase primitive the EARLY_RED executor uses. Respects the
        configured MinGreen (never cuts below it) and MIN_PHASE_ACTIVE_S (already
        gated in run_reward_tsp). Returns True if it truncated (caller returns).

        Uses _spm._mp_pressures_for_junction's main-vs-side proxy: index 0 is the
        main/bus phase, [1:] the side phases. cur_p is the current phase's own
        pressure; oth_p the best pressure elsewhere. Bus-free / no tracker."""
        try:
            _pres = _spm._mp_pressures_for_junction(self, time, current_phase)
        except Exception:
            return False
        if not _pres:
            return False
        _p_main = float(_pres[0]) if len(_pres) > 0 else 0.0
        _p_side = float(max(list(_pres[1:]) or [0.0]))
        _cur_is_main = False
        try:
            _cur_is_main = (int(current_phase) == int(self.BusPhase))
        except Exception:
            _cur_is_main = False
        _cur_p = _p_main if _cur_is_main else _p_side
        _oth_p = _p_side if _cur_is_main else _p_main
        _eps = float(globals().get('EMPTY_PHASE_QUEUE_EPS_PAX', 1.0) or 0.0)
        _tgt_min = float(globals().get('EMPTY_PHASE_MIN_TARGET_PAX', 5.0) or 0.0)
        if _cur_p > _eps or _oth_p < _tgt_min:
            return False
        # Respect min-green: only truncate a phase that has run at least MinGreen.
        _min_green = float(self.config.get('MinGreen', 5.0) or 5.0)
        try:
            _ps = float(ECIGetStartingTimePhase(self.node_id))
            _elapsed = max(0.0, time - _ps)
        except Exception:
            _elapsed = _min_green
        if _elapsed < _min_green:
            return False
        # Truncate the current (empty) phase to end now (floored at MinGreen) so
        # the plan advances toward the pressured phase.
        try:
            _new_dur = max(_min_green, _elapsed)
            ECIChangeTimingPhase(self.node_id, current_phase, _new_dur, timeSta)
            self.last_tsp_action_time = time
            self._reward_no_action_until = time + max(
                3.0, float(globals().get('NO_ACTION_HOLD_S', 3.0) or 0.0))
            try:
                self.stats.record_tsp_event(self.id, 'phase_skip')
            except Exception:
                pass
            log_to_file(
                f"[EMPTY_SKIP] inter={self.id} t={time:.1f} cur_phase={current_phase} "
                f"(cur_p={_cur_p:.0f}pax<=eps) -> advance to pressure "
                f"(oth_p={_oth_p:.0f}pax) trunc={_new_dur:.1f}s", force=True)
            return True
        except Exception as _e:
            log_to_file(f"[EMPTY_SKIP] inter={self.id} exec error {_e!r}")
            return False

    def run_reward_tsp(self, time, timeSta, acycle):
        """REWARD_TSP control mode — action-reward evaluation for TSP decisions.

        When a bus is detected, evaluates all candidate actions (no-action,
        green extensions of various durations, phase insertion) and picks the
        one with the highest reward R = -α·ΔD_bus - β·ΔD_other - γ·ΔD_side.
        """
        # OFFLINE WARM-START: optimize the base cycle+splits from OD + timetable
        # ONCE at startup (before any online correction), so the online methods
        # correct a good plan rather than the given fixed one. Self-guards to run once.
        if bool(globals().get('PLAN_OPTIMIZE', False)):
            try:
                self._optimize_startup_plan(timeSta)
                self._reassert_plan(time, timeSta)   # hold the plan vs any revert
            except Exception:
                pass
        # DELAY CALIBRATION: refresh per-approach kappa from Aimsun's measured .DTa
        # so _dctsp_eval_action can scale the analytic reward toward realised delay.
        try:
            self._update_delay_calibration(timeSta)
        except Exception:
            pass
        # Phase restoration (same as HARMONY — reuse existing method)
        self.restore_phase_if_needed(time, timeSta, acycle)

        # ── Layer 2: coordinated-actuated BASE (runs UNDER the TSP algorithm) ──
        # Fixed-time plans have no gap-out/max-out; add it here so an empty cross
        # phase returns its green to the coordinated band before the decider even
        # runs. Default OFF. If it truncates the current phase, let the plan
        # advance this step.
        if bool(globals().get('ACTUATED_BASE_MODE', False)):
            try:
                if self._coordinated_actuated_base(time, timeSta, acycle):
                    return
            except Exception as _abe:
                log_to_file(f"[ACTBASE] inter={self.id} error {_abe!r}")

        # ── Viability gate (saturation/cross-pressure stand-down) ─────────
        # Disarmed junctions run the fixed-time plan untouched: intervening
        # into gridlock only compounds debt (KG seed variance mechanism).
        # Silent stand-down (no per-step stat spam); transitions log via
        # [VIABILITY] where the gate trips. Prearm path below is covered.
        if not getattr(self, '_tsp_armed', True):
            return

        # Cooldown guard after a grant
        if time - self.last_tsp_action_time < self.tsp_cooldown_seconds:
            return

        # Short re-evaluation debounce after a NO_ACTION decision — avoids
        # running the full reward calculation on every simulation step when
        # nothing is changing (the 30 s stats debounce only affects counters).
        if time < getattr(self, '_reward_no_action_until', -1.0):
            return

        # Already active — don't re-evaluate
        if self.flag != 0:
            return
        if getattr(self, '_tsp_cycle_grant_until', -1.0) > time:
            return

        current_phase = ECIGetCurrentPhase(self.node_id)
        if current_phase < 0:
            return

        # ── Rule: minimum phase-active time before another TSP action ─────────
        # Once a phase starts, run it at least MIN_PHASE_ACTIVE_S before a new
        # action is considered, so the controller does not re-action a green it
        # only just started. 0 = off. Applies to the whole decision path below
        # (bus-present and continuous-monitor).
        _min_active = float(globals().get('MIN_PHASE_ACTIVE_S', 0.0) or 0.0)
        if _min_active > 0.0:
            try:
                _ps_active = float(ECIGetStartingTimePhase(self.node_id))
                if (time - _ps_active) < _min_active:
                    return
            except Exception:
                pass

        # ── Corridor pre-arm check (REWARD_TSP coordination) ─────────────────
        # PREARM_CYCLE_END_ONLY (2026-09-30): a pre-arm commits green DOWNSTREAM of
        # the decision that justified it. Mid-cycle it truncates whatever phase is
        # live, and the loss lands on cross traffic that never got a vote -- which
        # is the suspected mechanism behind the KG result where coordination is
        # worse than taking no action at all (car delay +53.1%, and bus delay
        # +10.3% vs NO_TSP, seed 400). The paper admits an offset shift only at a
        # cycle boundary (eq:offset_repay), so honour that here: a pre-arm may only
        # be honoured once the target phase has ended and the junction is back on a
        # cycle boundary. Default OFF so existing behaviour is untouched until the
        # A/B is run; ON is the candidate fix.
        if bool(globals().get('PREARM_CYCLE_END_ONLY', False)):
            try:
                _ps_now = float(ECIGetStartingTimePhase(self.node_id))
                _min_g = float(getattr(self, 'min_green_s', 0) or 0)
                # seconds elapsed in the current phase
                _phase_age = float(time) - _ps_now
                _phase_known = _ps_now > 0.0
            except Exception:
                _phase_age, _min_g, _phase_known = 0.0, 0.0, False
            if _phase_known and _phase_age < _min_g:
                if not getattr(self, '_prearm_block_logged', False):
                    self._prearm_block_logged = True
                    try:
                        log_to_file(
                            f"[PREARM CYCLE-END] inter={self.id} t={time:.0f} "
                            f"DEFER: phase age={_phase_age:.1f}s < min-green "
                            f"{_min_g:.1f}s -- pre-arm must land on a cycle "
                            f"boundary, not truncate a live phase",
                            force=True)
                    except Exception:
                        pass
                return
            self._prearm_block_logged = False

        _prearm = getattr(self, '_harmony_prearm', None)
        if _prearm is not None and self.TSPStrategy == 0:
            _pa_veh, _pa_eta_t, _pa_issued_t, _pa_dir, _pa_from = _unpack_prearm(_prearm)
            if _pa_veh is None:
                self._harmony_prearm = None
                _pa_veh, _pa_eta_t, _pa_issued_t = -1, -1e9, -1e9
            _eta_from_now = _pa_eta_t - time
            if _eta_from_now < -20.0 or time - _pa_issued_t > 120.0:
                self._harmony_prearm = None
            elif 0.0 <= _eta_from_now <= getattr(self, '_eta_max_s', 90.0):
                # Next-green feasibility (2026-09-26): evaluate only prearms
                # the bus phase can serve around the ETA; unservable ones are
                # cleared and deferred to local detection (fail-open: unknown
                # plan state evaluates as before). The coordinator re-fires as
                # the ETA shrinks, so the grant lands timed to the arrival
                # instead of bursting far early.
                _serv, _swhy = self._prearm_feasible(_eta_from_now, time, timeSta)
                if not _serv:
                    self._harmony_prearm = None
                    try:
                        log_to_file(
                            f"[PREARM FEASIBILITY] inter={self.id} t={time:.0f} "
                            f"bus={_pa_veh} eta={_eta_from_now:.0f}s dir={_pa_dir} "
                            f"from={_pa_from} SKIP unservable ({_swhy}) -- defer local",
                            force=True)
                    except Exception:
                        pass
                    try:
                        self.stats.record_tsp_skip(self.id, 'prearm_unservable')
                    except Exception:
                        pass
                else:
                    self._harmony_prearm = None
                    # Use reward evaluation with the prearm ETA as the bus ETA
                    self._run_reward_tsp_evaluate(
                        time, timeSta, acycle, current_phase,
                        _eta_from_now, _pa_veh, prearm_sourced=True)
                    return

        # ── Bus detection check ───────────────────────────────────────────────
        _n_det_slots = max(len(self.BusDet), 1)
        bus_detected = False
        bus_speed = 0.0
        det_idx = 0
        for i in range(_n_det_slots):
            if self.BusSpeed[0][i] > 0:
                bus_speed = self.BusSpeed[0][i]
                det_idx = i
                bus_detected = True
                break

        if not bus_detected:
            # ── Rule: skip an EMPTY phase, giving its green to the most-pressured
            # phase ── If the current phase has no queue and pressure lies on
            # another phase, truncate the current green so the plan advances toward
            # the pressure (min-green floored). Runs before the monitor eval.
            if bool(globals().get('EMPTY_PHASE_SKIP_MODE', False)):
                try:
                    if self._maybe_skip_empty_phase(time, timeSta, acycle,
                                                    current_phase):
                        return
                except Exception as _spe:
                    log_to_file(f"[EMPTY_SKIP] inter={self.id} error {_spe!r}")
            # ── CONTINUOUS MONITOR (state feedback, no bus needed) ────────────
            # Reframe from bus-triggered to continuous: with CONTINUOUS_MONITOR_MODE
            # on, evaluate the signal-action set on the CURRENT traffic state each
            # cadence even when no bus is present (car-only objective: bus term 0,
            # actions scored on mainline vs cross). A bus, when present, takes the
            # normal path above with its passenger-weighted term. The reward-layer
            # action set is main/bus-phase-oriented, so this mainly extends a
            # congested main/coordinated phase; MaxPressure covers all phases.
            # EXPERIMENTAL, default OFF -- validate before trusting.
            # Permissive-window gate: with ACTUATED_PERMISSIVE_GATE on, a no-bus
            # perturbation may only touch the coordinated (band) phase, never a
            # side phase (which would walk the offset).
            if (bool(globals().get('CONTINUOUS_MONITOR_MODE', False))
                    and self._in_permissive_window(time, timeSta, current_phase)):
                try:
                    if not self._monitor_state_ready(time):
                        try:
                            _mgl = globals().setdefault('_MON_GATE_LAST', {})
                            if float(time) - float(_mgl.get(int(self.id), -1e9)) >= 120.0:
                                _mgl[int(self.id)] = float(time)
                                log_to_file(
                                    f"[MONITOR_GATE] inter={self.id} t={time:.0f} "
                                    f"no-bus tick held (no fresh side feed, side "
                                    f"empty, main queue=0)")
                        except Exception:
                            pass
                    else:
                        self._run_reward_tsp_evaluate(
                            time, timeSta, acycle, current_phase,
                            bus_eta_s=1.0e9, veh_id=-1, stats_ok=False, monitor=True)
                except Exception as _mme:
                    log_to_file(f"[MONITOR] inter={self.id} error {_mme!r}")
            return

        # ── Approach debounce for detection stats (30 s per bus approach) ───────
        # TSP *actions* still fire when warranted (checked below); only stat
        # recording is suppressed within the debounce window.
        _det_vid_chk = self.last_detected_bus_id
        _reward_stats_ok = True
        if _det_vid_chk and _det_vid_chk > 0:
            _last_rec = self._approach_det_t.get(_det_vid_chk, -999.0)
            if (time - _last_rec) < 30.0:
                _reward_stats_ok = False   # suppress stat recording this step
            else:
                self._approach_det_t[_det_vid_chk] = time

        # ── Global bus focus gate ─────────────────────────────────────────────
        _det_vid = self.last_detected_bus_id
        if _det_vid and _det_vid > 0 and _is_focus_blocked(_det_vid, self.id, time):
            if LOG_REWARD:
                _vprint(
                    f"[REWARD_TSP] t={time:.1f} inter={self.id} "
                    f"v={_det_vid} focus_suppress — focus bus={_focus_bus_id}")
            _mark_detection_point(self.id, _det_vid, 0.0, 0.0, time, "focus_suppress")
            self._record_detection(time)
            return

        # ── Compute bus ETA ───────────────────────────────────────────────────
        eta_info = getattr(self, '_bus_eta', {}).get(det_idx)
        _det_dist_fb = (
            self.config['DetDistance'][0][det_idx]
            if self.config.get('DetDistance') and len(self.config['DetDistance']) > 0
               and det_idx < len(self.config['DetDistance'][0])
            else 200.0
        )
        bus_eta_s = eta_info[1] if eta_info else (_det_dist_fb / max(float(bus_speed), 0.5))
        try:
            _emx2 = float(globals().get('BUS_ETA_MAX_S', 300.0) or 300.0)
        except Exception:
            _emx2 = 300.0
        bus_eta_s = min(float(bus_eta_s), _emx2)

        # ── Stop-aware ETA padding (learned per-line lateness) ──────
        try:
            self._cur_decision_veh = int(_det_vid) if _det_vid else None
            _trk_b = _ETA_TRACK.get(int(_det_vid)) if _det_vid else None
            _lk = (_trk_b or {}).get("line") or "unk"
            bus_eta_s += max(0.0, min(_eta_bias_for(_lk), BUS_ETA_BIAS_MAX_S))
        except Exception:
            pass

        # Skip evaluation when bus is too far away to benefit from TSP.
        # 2 × cycle_time is the threshold: beyond that the bus will encounter
        # natural greens and the reward estimate is too noisy to be useful.
        _cycle = float(self.cycle_len_s)
        if bus_eta_s > 2.0 * _cycle:
            self._reward_no_action_until = time + float(globals().get('NO_ACTION_HOLD_S', 5.0) or 5.0)
            return
        # ── Certainty-gated commitment window (receding horizon) ──────
        # Commit actions only when arrival is near enough to be trusted
        # (Kalman sigma <= BUS_SIGMA_ACT_MAX_S) and late enough that the
        # intergreen can still complete. Outside: observe / pre-arm only.
        _sig_act = float(getattr(self, "_cur_eta_sigma_s", 0.0) or 0.0)
        _sig_max = float(globals().get("BUS_SIGMA_ACT_MAX_S", 12.0))
        _act_min_lead = float(globals().get(
            "MIN_EFFECTIVE_PREARM_LEAD_S", 10.0) or 10.0)
        if (_sig_act > _sig_max) or (bus_eta_s < _act_min_lead):
            self._reward_no_action_until = time + 3.0
            return

        # ── MULTIBUS_JOINT: observe ALL oncoming buses and act on the
        # reward-optimal one (occupancy x lateness-urgency), not just the
        # first/late detected bus. R10 keeps one action per window; R11's
        # green-keep covers a following convoy. Logs the choice so the
        # selection is auditable.
        if bool(getattr(_spm, 'MULTIBUS_JOINT', False)):
            try:
                _cc = getattr(self, '_corridor_coord', None)
                if _cc is not None and hasattr(_cc, 'best_bus_for'):
                    _bb, _bs, _n = _cc.best_bus_for(int(self.id), time)
                    if _bb is not None and _n > 1 and int(_bb) != int(_det_vid or -1):
                        log_to_file(
                            f"[MULTIBUS] inter={self.id} t={time:.1f} "
                            f"buses={_n} choose bus={_bb} "
                            f"(score={_bs:.0f}) over detected={_det_vid}")
                        _det_vid = int(_bb)
            except Exception:
                pass

        self._run_reward_tsp_evaluate(
            time, timeSta, acycle, current_phase, bus_eta_s, _det_vid,
            stats_ok=_reward_stats_ok)
        # ── Rule: NO_ACTION hold ──────────────────────────────────────────────
        # If the evaluation did not grant anything (flag still 0), hold for
        # NO_ACTION_HOLD_S before re-checking so the full evaluation is not re-run
        # every sim step while nothing changes. A grant sets its own longer window.
        if self.flag == 0:
            _hold = float(globals().get('NO_ACTION_HOLD_S', 5.0) or 0.0)
            if _hold > 0.0:
                self._reward_no_action_until = max(
                    getattr(self, '_reward_no_action_until', -1.0), time + _hold)

    def _junction_ge_ub(self, timeSta=0.0):
        """Corridor-agnostic GE upper bound for THIS junction (2026-09-27).

        min(global MAX_GE_EXTENSION_S, GE_MAX_FRAC_OF_CYCLE * live cycle).
        A 15 s extension is a different intervention on a 60 s cycle than on
        a 135 s one; scaling by the discovered cycle keeps the solver's
        lattice (grid/de/exact) meaningful on any corridor. Falls back to the
        global MAX when the cycle is undiscoverable.
        """
        try:
            _gmax = float(globals().get('MAX_GE_EXTENSION_S', 10.0))
        except Exception:
            _gmax = 10.0
        try:
            _frac = float(globals().get('GE_MAX_FRAC_OF_CYCLE', 0.15) or 0.0)
        except Exception:
            _frac = 0.15
        if _frac <= 0.0:
            return max(1.0, _gmax)
        try:
            _cyc = float(self._signal_cycle_s(timeSta) or 0.0)
        except Exception:
            _cyc = 0.0
        if _cyc <= 0.0:
            return max(1.0, _gmax)
        return max(1.0, min(_gmax, _frac * _cyc))

    def _pushed_plan(self):
        """Latest published post-change plan for THIS junction (or None).

        Same-tick truth after any commit/restore/recovery: readers prefer it
        over attributes/ECI, so both directions (downstream projections,
        upstream window checks) see the new plan with no polling gap.
        """
        try:
            _cc = getattr(self, '_corridor_coord', None)
            if _cc is not None and hasattr(_cc, 'get_pushed_plan'):
                return _cc.get_pushed_plan(int(self.id))
        except Exception:
            pass
        return None

    def _broadcast_timing_change(self, action, magnitude_s, time, why,
                                   current_phase=None, timeSta=0.0,
                                   live_read=False):
        """Push this junction's new plan to the corridor (2026-09-27).

        Invalidation is not enough: neighbours coordinate against snapshots,
        and ECI does not carry a commit's values until its executor applies
        them (the ledger fires pre-execution). So this publishes the
        POST-change plan itself -- analytically for ledger commits (pre-commit
        ECI truth + action delta), by live ECI re-read for recovery/restore/
        pre-arm executors (already applied, live_read=True) -- into the
        coordinator's push registry. Both directions read the same store:
        downstream delay projections AND upstream green-window checks prefer
        it over attributes/ECI, so same-tick commits are visible with no
        polling gap and no execution-order dependence.
        """
        try:
            self._signal_cycle_cache = 0.0
        except Exception:
            pass
        try:
            self._coord_phase_cache = None
            self._coord_base_dur = None
        except Exception:
            pass
        # Mark Python-side plan attributes stale: cross-junction projections
        # read these (not ECI). The refresh itself is deferred to the next
        # evaluation (see _run_reward_tsp_evaluate head): ECI does not carry
        # the new values until the executors below apply them.
        try:
            self._plan_attrs_dirty = True
        except Exception:
            pass
        # ── Publish post-change (bpd, cycle, full per-phase durs) ────────
        try:
            _bpd_new = _cyc_new = None
            _ph_pub = -1
            _durs_new = {}
            try:
                for _ph in (getattr(self, 'phase_list', None) or []):
                    _durs_new[int(_ph)] = float(GetPhaseDuration(
                        self.node_id, int(_ph), timeSta) or 0.0)
            except Exception:
                _durs_new = {}
            if live_read:
                try:
                    _bpd_new = float(GetPhaseDuration(
                        self.node_id, self.BusPhase, timeSta) or 0.0)
                except Exception:
                    _bpd_new = None
                try:
                    self._signal_cycle_cache = 0.0
                    _cyc_new = float(self._signal_cycle_s(timeSta) or 0.0)
                except Exception:
                    _cyc_new = None
                # live_read: ECI already applied -> durs_new is the truth.
            else:
                try:
                    _bpd0 = float(GetPhaseDuration(
                        self.node_id, self.BusPhase, timeSta) or 0.0)
                except Exception:
                    _bpd0 = 0.0
                if _bpd0 <= 0.0:
                    try:
                        _bpd0 = float(getattr(self, 'BusPhaseDuration', 0.0)
                                      or 0.0)
                    except Exception:
                        _bpd0 = 0.0
                try:
                    _cyc0 = 0.0
                    for _ph in (getattr(self, 'phase_list', None) or []):
                        _cyc0 += float(GetPhaseDuration(
                            self.node_id, _ph, timeSta) or 0.0)
                except Exception:
                    _cyc0 = 0.0
                try:
                    _ak, _ = _spm.parse_action_token(str(action))
                except Exception:
                    _ak = ""
                _mag = max(0.0, float(magnitude_s or 0.0))
                _bpd_new, _cyc_new = _bpd0, _cyc0
                if _ak == "GE":
                    try:
                        _cur = int(current_phase)
                        _bp = int(getattr(self, 'BusPhase', -1))
                    except Exception:
                        _cur, _bp = -1, -2
                    if _cur == _bp and _cur >= 0:
                        _bpd_new = _bpd0 + _mag
                        _ph_pub = _cur
                        _durs_new[_bp] = float(_durs_new.get(_bp, _bpd0)) + _mag
                    _cyc_new = _cyc0 + _mag
                elif _ak == "INS":
                    _cyc_new = _cyc0 + _mag
                elif _ak == "ER":
                    _cyc_new = max(1.0, _cyc0 - _mag)
            # Update the GLOBAL plan-state tracker (the single store every
            # causal-delay estimator reads).
            if _durs_new:
                try:
                    _ps = _global_plan_state(self.id) or {}
                    _ver = int(_ps.get("version", 0) or 0) + 1
                    _PLAN_STATE[int(self.id)] = {
                        "durs": dict(_durs_new),
                        "cycle_s": (_cyc_new if _cyc_new and _cyc_new > 0.0
                                    else sum(_durs_new.values())),
                        "bus_phase": int(getattr(self, 'BusPhase', -1) or -1),
                        "version": _ver,
                        "t": float(time),
                    }
                except Exception:
                    pass
            _cc = getattr(self, '_corridor_coord', None)
            if (_cc is not None and _bpd_new and _bpd_new > 0.0
                    and _cyc_new and _cyc_new > 0.0
                    and hasattr(_cc, 'notify_timing_changed')):
                _cc.notify_timing_changed(
                    int(self.id), str(action), float(magnitude_s or 0.0),
                    float(time), str(why),
                    plan={"bus_phase_dur": float(_bpd_new),
                          "cycle_s": float(_cyc_new),
                          "phase": int(_ph_pub)})
        except Exception:
            pass

    def _run_reward_tsp_evaluate(self, time, timeSta, acycle,
                                  current_phase, bus_eta_s, veh_id,
                                  stats_ok: bool = True, prearm_sourced: bool = False,
                                  monitor: bool = False):
        # Corridor anticipation needs to know which bus is being served so it
        # prices everyone ELSE.  One assignment covers every downstream scorer.
        try:
            self._cur_decision_veh = int(veh_id) if veh_id else None
        except Exception:
            self._cur_decision_veh = None
        # Remember whether this evaluation was triggered by a corridor pre-arm.
        # Pre-arm evals fire ~450×/run and previously committed uncounted OC/GR/
        # ER/PT timing changes that cascade car delay (champion search 2026-08-24).
        # The executor uses this to hard-veto those action families for pre-arms.
        self._prearm_sourced_eval = bool(prearm_sourced)
        # ETA display: the no-bus monitor tick passes the 1e9 sentinel (gates
        # test bus_eta_s > 1e8), but printing it as eta=1000000000.0s is noise.
        # Show "--" for monitor ticks and cap anything absurd at the realistic
        # ceiling so the logs read like the street, not like an internal flag.
        try:
            _eta_disp_abs = float(bus_eta_s)
        except Exception:
            _eta_disp_abs = 1.0e9
        if monitor or _eta_disp_abs >= 1.0e8:
            _eta_disp = "--"
        else:
            try:
                _edm = float(globals().get('BUS_ETA_MAX_S', 300.0) or 300.0)
            except Exception:
                _edm = 300.0
            _eta_disp = ("%.1fs" % min(max(_eta_disp_abs, 0.0), _edm))
        # ── Deferred plan-attribute refresh (2026-09-27) ──────────────────
        # ECI writes from the previous tick's commits/restores are live NOW.
        # Re-read own bus-green length into _live_bus_phase_dur: downstream
        # projections read this attribute (not ECI), so without the refresh
        # they coordinate against the pre-commit plan for a full cycle.
        # BusPhaseDuration itself is NEVER touched here -- recovery maths
        # treats it as the nominal; the live value lives separately.
        if bool(getattr(self, '_plan_attrs_dirty', False)):
            try:
                self._plan_attrs_dirty = False
                try:
                    _nbpd = float(GetPhaseDuration(
                        self.node_id, self.BusPhase, timeSta) or 0.0)
                    if _nbpd > 0.0:
                        self._live_bus_phase_dur = _nbpd
                except Exception:
                    pass
            except Exception:
                pass
        if veh_id and veh_id > 0 and _is_focus_blocked(veh_id, self.id, time):
            if LOG_REWARD:
                _vprint(
                    f"[REWARD_TSP] t={time:.1f} inter={self.id} "
                    f"v={veh_id} focus_suppress — focus bus={_focus_bus_id}")
            _mark_detection_point(self.id, veh_id, 0.0, 0.0, time, "focus_suppress")
            if stats_ok:
                self._record_detection(time)
            return

        # Action 0: NO_ACTION
        no_action_bus_delay = self._reward_estimate_no_action(time, timeSta, bus_eta_s)
        no_action_bus_cost = max(0.0, no_action_bus_delay) * max(safe_float(self.BusOcc), 0.0)
        reward_no_action = -REWARD_ALPHA * no_action_bus_cost

        # ── Bus-delay model divergence diagnostic (gated) ─────────────────────
        # BXT/CellQLearn decides from `no_action_bus_delay`, a pure SIGNAL-TIMING
        # estimate ("does the bus arrive during green?") that ignores the QUEUE
        # the bus must discharge through.  The generic GE path instead uses the
        # SHOCKWAVE model (_reward_evaluate_ge -> GE_Objective_Function), which
        # accounts for the queue.  When CellQLearn does nothing but the generic
        # pool found benefit, the two disagree.  Enable BXT_DELAY_DIAG to log
        # both for the same (bus, junction, time) and see where they diverge.
        if globals().get('BXT_DELAY_DIAG', False):
            try:
                _cur_ph = ECIGetCurrentPhase(self.node_id)
                _shock_bus_s = 0.0
                try:
                    # Shockwave NO-ACTION bus delay = base cost at GE=0.
                    self.GE_Objective_Function(0.0, time)
                    _shock_bus_s = max(0.0, float(
                        self._reward_objective_snapshot(extra_side_red=0.0)["bus_delay_s"]))
                except Exception as _se:
                    _shock_bus_s = -1.0
                log_to_file(
                    "[DELAY_DIAG] inter=%s t=%.1f bus=%s eta=%.1fs "
                    "phase=%s bus_phase=%s wrong=%s | timing_delay=%.1fs "
                    "shockwave_delay=%.1fs diverge=%.1fs" % (
                        self.id, time, veh_id, float(bus_eta_s),
                        _cur_ph, self.BusPhase, _cur_ph != self.BusPhase,
                        float(no_action_bus_delay), _shock_bus_s,
                        _shock_bus_s - float(no_action_bus_delay)),
                    )
            except Exception:
                pass

        best_action = "NO_ACTION"
        best_reward = reward_no_action
        best_ge = 0.0

        # Per-cycle reward log: accumulate one row per candidate, write once
        # at end.  Row format: (label, reward, bus_saved, other_inc, side_inc,
        # param_s).  param_s is the executable duration for the action so the
        # Pareto layer never has to re-parse it out of the label.
        _reward_rows = []
        # NO_ACTION: reward = -α·bus_cost; no savings on others; store baseline bus cost
        _reward_rows.append((
            "NO_ACTION", reward_no_action,
            -no_action_bus_cost, 0.0, 0.0, 0.0))  # bus_saved<0 encodes the baseline bus cost

        # ── Strategy Dispatch: per-mode candidate generation ─────────────
        # Every active mode adds its candidates to _reward_rows.  The shared
        # Pareto layer below picks the best from the pool regardless of which
        # mode generated it.
        _sigma_in = float(getattr(self, '_last_sigma', 0.0) or 0.0)
        # Per-bus accumulated lateness (Z3) overrides the per-controller value:
        # a bus that waited at the previous junction IS late, and that lateness
        # must follow the bus down the corridor, not reset at each junction.
        if veh_id and int(veh_id) > 0:
            _sigma_in = max(0.0, float(_bus_lateness.get(int(veh_id), 0.0) or 0.0))
            _headway_dev = (_ETA_TRACK.get(int(veh_id)) or {}).get("headway_dev_s")
            if _headway_dev is not None:
                _sigma_in = max(0.0, float(_headway_dev))
            self._last_sigma = _sigma_in
        _wrong_phase = (current_phase != self.BusPhase)
        _ps_eval = ECIGetStartingTimePhase(self.node_id)
        _pd_eval = GetPhaseDuration(self.node_id, current_phase, timeSta)
        _rem = max(0.0, _pd_eval - (time - _ps_eval))

        # Registry: (active-flag, generator, log tag).  Each generator returns
        # (best_type, best_param, best_r, best_r_delta, sigma_out, t_poz, rows)
        # with rows labelled via _spm.action_label so they are executable.
        _mode_registry = (
            (_spm.DCTSP_ZIG_MODE,                 _spm.dctsp_zig,     'ZIG'),
            (_spm.MP_ECTM_MODE,                   _spm.dctsp_mp_ectm, 'MP_ECTM'),
            (getattr(_spm, 'MP_ECTM_DP_MODE', False),
                                                   _spm.dctsp_mp_ectm_dp, 'MP_ECTM_DP'),
            (getattr(_spm, 'BXT_MODE', False),    _spm.dctsp_bxt,     'BXT'),
            (getattr(_spm, 'BXT_CORRIDOR_MODE', False),
                                                   getattr(_spm, 'dctsp_cellqlearn_corridor', None), 'CELLQ_CORRIDOR'),
            (getattr(_spm, 'CPDQL_MODE', False),  _spm.dctsp_cpdql,   'CPDQL'),
            (getattr(_spm, 'CELLQLEARN_DP_MODE', False),
                                                   _spm.dctsp_cellqlearn_dp, 'CELLQLEARN_DP'),
            (getattr(_spm, 'BARGAIN_SPM_MODE', False),
                                                   _spm.dctsp_bargain, 'BARGAIN'),
            (getattr(_spm, 'MAXPRESSURE_FIX_MODE', False),
                                                   _spm.dctsp_maxpressure_fix, 'MAXPRESSURE_FIX'),
            (getattr(_spm, 'MAXPRESSURE_FLEX_MODE', False),
                                                   _spm.dctsp_maxpressure_flex, 'MAXPRESSURE_FLEX'),
            (getattr(_spm, 'HYBRID_MP_MODE', False),
                                                   getattr(_spm, 'dctsp_hybrid_mp', None), 'HYBRID_MP'),
            (getattr(_spm, 'NASH_GATE_MODE', False),
                                                   getattr(_spm, 'dctsp_nash_gate', None), 'NASH_GATE'),
            (getattr(_spm, 'NASH_BARGAIN_MODE', False),
                                                   getattr(_spm, 'dctsp_nash_bargain', None), 'NASH_BARGAIN'),
            (getattr(_spm, 'MILP_TSP_MODE', False),
                                                   _spm.dctsp_milp_tsp, 'MILP_TSP'),
            (getattr(_spm, 'CENTRALIZED_MODE', False),
                                                   getattr(_spm, 'dctsp_centralised', None), 'CENTRALISED'),
        )
        # Mode-commits-own-action: when a specialised paper method (BXT /
        # CellQLearn, MP-ECTM / CTMGS, ZIG / HSLWR, CellQLearn-DP, Nash-
        # Bargaining) is active, ITS OWN model picks the action and that action
        # is committed directly.  It is NOT pooled with the generic GE/INS/GR
        # candidates and NOT re-decided by the shared Pareto layer — the method
        # already encodes the objective trade-off in its own reward model.
        _mode_committed = False
        _mode_label = None
        _mode_param = 0.0
        _mode_reward = 0.0
        # A specialised mode (BXT/CellQLearn, MP-ECTM/CTMGS, ZIG, ...) is the
        # DECIDER for this junction when one is active.  When MODE_DECISION_IS_
        # FINAL, a mode that returns NO_ACTION is respected as a real "do
        # nothing" -- the generic GE/INS/OC/VP candidate pool below is NOT run
        # to override it.  Without this, CellQLearn's NO_ACTION fell through to
        # the generic heuristic, which then fired GE/INS/OC anyway, so the mode
        # was effectively decorative (measured: BXT chose 851 NO_ACTION but 79
        # GE + 48 INS + 57 OC executed from the generic pool).
        _mode_active = any(bool(_on) for (_on, _f, _t) in _mode_registry)
        _mode_final = bool(globals().get('MODE_DECISION_IS_FINAL', True))
        _mode_is_decider = _mode_active and _mode_final
        # CONTINUOUS MONITOR: with no bus, a committing decider returns NO_ACTION
        # (no bus to serve); force the state-based generic GE/OC/GR pool so the
        # controller can still act on the current traffic state (car objective).
        if monitor:
            _mode_is_decider = False
        for _m_on, _m_func, _m_tag in _mode_registry:
            if not _m_on:
                continue
            try:
                (_mtype, _mparam, _mr, _mrd, _mso, _mtp, _mrows) = _m_func(
                    self, time, timeSta, acycle, bus_eta_s, veh_id,
                    current_phase, no_action_bus_delay, _sigma_in,
                    remaining_red_s=_rem)
                for (lbl, par, r, so, tp, bps, cpc, nsd, std) in _mrows:
                    if lbl == 'NO_ACTION':
                        continue  # baseline row already seeded above
                    # The specialised-mode row packs the FULL cross + side +
                    # DP-penalty cost into `cpc` (cross_pax_cost); `nsd` is the
                    # bus's own no-action delay (pax·s), NOT a side cost.
                    # Feeding `nsd` into the side_inc slot made every CTM/DP
                    # candidate carry ~2073 pax·s of bogus cost -> Z1 hugely
                    # positive -> always dominated by NO_ACTION -> the mode's
                    # candidate could never win, collapsing CTMGS/CTMGS_DP/
                    # CELLQLEARN onto GR_BASE.
                    _sr = (REWARD_ALPHA * bps - REWARD_BETA * cpc)
                    _bps_row = bps
                    if monitor and bool(getattr(_spm, 'MONITOR_BUS_ZERO', True)):
                        # No bus on a car-only tick: its savings are phantom
                        # (DE500: pred_bus mean 405 on bus=-1 commits). Seat
                        # the row on cost alone so selection -- and the
                        # [DECISION] ledger below, which reads these rows --
                        # sees zero bus credit.
                        _sr = -REWARD_BETA * cpc
                        _bps_row = 0.0
                    _reward_rows.append((lbl, _sr, _bps_row, cpc, 0.0, par))
                    if lbl == _spm.action_label(_mtype, _mparam) and _sr > best_reward:
                        best_reward = _sr
                        best_ge = par
                        best_action = lbl
                # Commit the mode's own chosen action (non-NO_ACTION) directly.
                if _mtype != 'NO_ACTION' and abs(float(_mparam or 0.0)) > 0.0:
                    _mode_committed = True
                    _mode_label = _spm.action_label(_mtype, _mparam)
                    _mode_param = float(_mparam or 0.0)
                    # Use the mode's own reward delta for logging consistency.
                    _mode_reward = float(_mr or 0.0)
            except Exception as _m_err:
                log_to_file(f"[{_m_tag}] error: {_m_err}", force=True)

        # ── Analytic cost veto over the learned-Q decider ─────────────────────
        # dctsp_bxt / CellQLearn commits by its LEARNED Q, which -- under-trained
        # on few seeds -- can commit an action whose analytic cross-street cost
        # dwarfs its bus benefit.  That is the cascading car-delay that made
        # CELLQLEARN lose to NO_TSP (-44.7%, car +161%): 115 greedy actions the
        # learned Q thought were fine but whose real cross cost gridlocked the
        # corridor.  Safety net: veto the committed action to NO_ACTION when its
        # OWN analytic row shows cross cost > bus benefit * ratio.  This reuses
        # the mode's already-computed bps (bus benefit, pax·s) and cpc (full
        # cross+side cost, pax·s) -- it introduces NO new multiplier, so it
        # CANNOT be mis-scaled the way the §28 veto was (that one stacked a
        # ~200x congestion ramp and vetoed everything).  Ratio is tunable and
        # defaults to break-even (veto only when cost strictly exceeds benefit).
        if _mode_committed and _mode_is_decider:
            # MaxPressure exemption: MP is a deterministic network-pressure
            # policy, NOT bus-benefit-driven. Its wrong-phase green extensions
            # book a nominal bus penalty in _dctsp_eval_action (-param*BusOcc,
            # e.g. exactly -1000 pax·s for GE_25), so max(bps,0)*ratio == 0 and
            # this break-even veto rejected 100% of MP actions (KG pre-flight
            # 2026-08-24: every proposal VETOed -> byte-identical to NO_TSP).
            # The veto remains a safety net for the learned/bus-centric modes.
            _mp_veto_exempt = (bool(getattr(_spm, 'MAXPRESSURE_FIX_MODE', False))
                               or bool(getattr(_spm, 'MAXPRESSURE_FLEX_MODE', False)))
            _veto_bps = _veto_cpc = None
            for (_vl, _vr, _vb, _vc, _vs, _vp) in _reward_rows:
                if _vl == _mode_label:
                    _veto_bps, _veto_cpc = float(_vb), float(_vc)
                    break
            # Read from _spm, NOT engine globals: AAPIInit propagates run_config
            # values into _spm.MODE_FLAGS and reset_mode_flags() restores the
            # default between experiments there. Reading engine globals leaked a
            # previous arm's tuned ratio into every later arm in the session.
            _veto_ratio = float(getattr(_spm, 'DECIDER_COST_VETO_RATIO', 1.0) or 1.0)
            # ── Action-aware ratio: serve HELD buses generously, extend tightly ──
            # INS / wrong-phase GR (advancing a held bus's green) is the action the
            # winning arms (MARL/CENTRALISED) use to beat NO_TSP — it steals a cross
            # phase so its cross cost is high, and a break-even veto always killed
            # it (INS=0 for every CELLQLEARN run). Give it the winners' generous
            # ratio so a genuinely-held bus gets served, while GE / EARLY_RED keep
            # the tight base ratio (GE over-extension was the residual gridlock).
            try:
                _mk_v, _ = _spm.parse_action_token(_mode_label)
                if (_mk_v in ('INS', 'GR')
                    and not bool(getattr(_spm, 'MILP_TSP_MODE', False))):
                    _veto_ratio = float(getattr(_spm, 'DECIDER_COST_VETO_RATIO_INS',
                                                3.0) or _veto_ratio)
            except Exception:
                pass
            # ── Car-cost uncertainty band ─────────────────────────────────────
            # ASYMMETRY: the bus benefit is now PRECISE (continuous per-second
            # tracking, §50), but the cross-street car cost is DETECTOR-ESTIMATED
            # (coarser, noisy). So don't judge the precise bus benefit against a
            # single noisy car-cost point estimate -- judge it against a risk-
            # adjusted UPPER bound. The uncertainty is measured directly from the
            # DISAGREEMENT between the two independent car-cost estimators (the
            # analytic CTM cross-cost vs the live side-detector count): when they
            # agree the cost is trustworthy (tight band), when they diverge it is
            # uncertain (wide band) and we act only if the bus benefit clears the
            # pessimistic end. Set CAR_COST_UNCERTAINTY_K=0 to disable.
            _car_for_veto = _veto_cpc
            if _veto_cpc is not None:
                _k_unc = float(globals().get('CAR_COST_UNCERTAINTY_K', 0.5) or 0.0)
                if _k_unc > 0.0:
                    try:
                        _mag_v = abs(float(_mode_param))
                        _ca = float(self._dctsp_cross_traffic_delay_s(_mag_v))   # analytic CTM
                        _sd, _ = self._compute_side_delay_penalty(_mag_v, _suppress_log=True)
                        _cl = max(0.0, float(_sd)) * max(safe_float(getattr(self, 'CarOcc', 1.2)), 1.0)  # live detectors
                        _uncert = abs(_ca - _cl)                # estimator disagreement
                        _car_for_veto = max(_veto_cpc, _ca, _cl) + _k_unc * _uncert
                    except Exception:
                        _car_for_veto = _veto_cpc
            # NOTE: the row's bus benefit arrives ALREADY equity-weighted
            # (+ green-keep credit) from dctsp_bxt -- do NOT multiply by
            # BUS_PAX_WEIGHT here again or the tilt doubles.
            if (_car_for_veto is not None and _veto_bps is not None
                    and not _mp_veto_exempt
                    and _car_for_veto > max(_veto_bps, 0.0) * _veto_ratio):
                # LOG_COST_VETO (controller config, silenced by _set_logging
                # during batches): the veto ITSELF always applies and is still
                # counted via record_tsp_skip('decider_cost_veto') -- only the
                # per-event line is gated, else sweeps spam thousands of lines.
                if bool(globals().get('LOG_COST_VETO', True)):
                    log_to_file(
                        f"[COST VETO] inter={self.id} t={time:.1f} bus={veh_id} "
                        f"action={_mode_label} bus_benefit={_veto_bps:.0f} "
                        f"(equity-weighted) cross_cost={_veto_cpc:.0f} "
                        f"risk_adj={_car_for_veto:.0f} "
                        f"(ratio {_veto_ratio:.2f}) — VETO to NO_ACTION", force=True)
                self.stats.record_tsp_skip(self.id, 'decider_cost_veto')
                _mode_label = "NO_ACTION"
                _mode_param = 0.0
                _mode_reward = reward_no_action

        # If a specialised method committed an action, its decision is final:
        # skip the generic GE/INS/GR/VP/PT candidate pool and the shared
        # Pareto/Z4 layers entirely for this detection.
        if _mode_committed:
            best_action = _mode_label
            best_ge = _mode_param
            best_reward = _mode_reward
            if monitor and bool(getattr(_spm, 'MONITOR_BUS_ZERO', True)):
                # The mode's own delta (_mr) carries the same phantom bus
                # credit; re-derive best from the zeroed seated row so the
                # MONITOR_PROG price + min-gain test below see car economics.
                for (_zl, _zr, _zb, _zc, _zs, _zp) in _reward_rows:
                    if _zl == _mode_label:
                        best_reward = float(_zr)
                        break

        # ── Standard candidate evaluation ──────────────────────────────────
        # Runs for every strategy (NORMAL/HARMONY/REWARD_TSP/ZIG/ECTM),
        # alongside specialized modes.  All candidates pool into the same
        # Pareto layer.
        _remain = _rem
        _zig_ge  = bool(getattr(_spm, 'ZIG_ENABLE_GE', True))
        _zig_ins = bool(getattr(_spm, 'ZIG_ENABLE_INS', True))
        _zig_gr  = bool(getattr(_spm, 'ZIG_ENABLE_GR', True))
        _zig_seq = bool(getattr(_spm, 'ZIG_ENABLE_SEQ', True))
        _pr_mode = bool(getattr(_spm, 'PHASE_ROTATION_MODE', True))
        if not _mode_committed and not _mode_is_decider and current_phase == self.BusPhase and REWARD_TSP_ENABLE_GE:
            # ── GE candidates ──────────────────────────────────────────
            if _zig_ge:
                # REWARD_GE_SOLVER (2026-09-27): 'grid' (legacy fixed
                # REWARD_GE_CANDIDATES), 'de' (DE on the decision reward), or
                # 'exact' (exhaustive integer-lattice argmax -- the true
                # optimum on a ~13-value domain, deterministic, ~13 evals).
                # Solved modes optimise the DECISION reward itself, not the
                # degenerate shockwave curve. Any failure falls back to grid.
                _ge_solver = str(globals().get('REWARD_GE_SOLVER', 'grid')).lower()
                _ge_list = list(REWARD_GE_CANDIDATES)
                _ge_tag = ""
                if _ge_solver in ('de', 'exact'):
                    try:
                        _s_lb = max(1.0, float(globals().get(
                            'MIN_GE_EXTENSION_S', 3.0)))
                        # Cycle-scaled bound, then the junction's OWN
                        # recoverable headroom: the solver may only pick a
                        # magnitude the cycle can repay (recoverable budget +
                        # slack, same currency the RECOVER_GATE enforces at
                        # execution). Falls back to the scaled bound when the
                        # headroom is unreadable.
                        _s_ub = float(self._junction_ge_ub(timeSta))
                        try:
                            _rec = float(self._reward_get_recoverable(
                                current_phase, timeSta))
                            _slack = float(globals().get(
                                'RECOVERABILITY_SLACK_S', 1.0))
                            _s_ub = min(_s_ub, max(1.0, _rec + _slack))
                        except Exception:
                            pass

                        def _neg_r(_g, _t, _tt=time, _ts=timeSta,
                                   _eta=bus_eta_s):
                            _bs, _oi, _si = self._reward_evaluate_ge(
                                float(_g), _tt, _ts, _eta)
                            return -(REWARD_ALPHA * _bs - REWARD_BETA * _oi
                                     - REWARD_GAMMA * _si)

                        if _ge_solver == 'exact':
                            _sol, _sol_r = None, None
                            _gi = int(math.ceil(_s_lb))
                            while _gi <= int(math.floor(_s_ub)):
                                try:
                                    _rr = -_neg_r(_gi, time)
                                except Exception:
                                    _rr = None
                                if _rr is not None and _rr == _rr and (
                                        _sol_r is None or _rr > _sol_r):
                                    _sol, _sol_r = float(_gi), float(_rr)
                                _gi += 1
                            if _sol is None:
                                raise ValueError('exact lattice empty')
                        else:
                            _sol = differential_evolution_search(
                                _neg_r, _s_lb, _s_ub, time,
                                pop_size=int(globals().get('TIMING_DE_POP', 10)),
                                max_generations=int(globals().get('TIMING_DE_GENS', 6)),
                                F=float(globals().get('TIMING_DE_F', 0.7)),
                                CR=float(globals().get('TIMING_DE_CR', 0.9)),
                                seed=int(globals().get('TIMING_DE_SEED', 12345)))
                        _sol = min(max(float(_sol), _s_lb), _s_ub)
                        _ge_list = [_sol]
                        _ge_tag = "(solved-%s)" % _ge_solver
                    except Exception as _sge_err:
                        if LOG_REWARD:
                            log_to_file(
                                f"[REWARD_TSP] inter={self.id} GE solver "
                                f"fallback to grid ({_sge_err!r})")
                        _ge_list = list(REWARD_GE_CANDIDATES)
                        _ge_tag = ""
                for ge_s in _ge_list:
                    if ge_s > float(self._junction_ge_ub(timeSta)):
                        continue
                    bus_saved, other_inc, side_inc = self._reward_evaluate_ge(
                        ge_s, time, timeSta, bus_eta_s)
                    reward = (REWARD_ALPHA * bus_saved
                              - REWARD_BETA * other_inc
                              - REWARD_GAMMA * side_inc)
                    _reward_rows.append((f"GE_{ge_s:.0f}", reward, bus_saved, other_inc, side_inc, ge_s))
                    if LOG_REWARD:
                        log_to_file(f"[REWARD_TSP] inter={self.id} R(GE_{ge_s:.0f})={reward:.1f}{_ge_tag}")
                    if reward > best_reward:
                        best_reward = reward; best_ge = ge_s
                        best_action = f"GE_{ge_s:.0f}"

            # ── ER (Early Red) ─────────────────────────────────────────
            if _zig_seq:
                for er_s in [5.0, 10.0]:
                    r, so, tp, bps, cpc, nsd, std = _spm._dctsp_eval_action(
                        self, 'EARLY_RED', er_s, _sigma_in, no_action_bus_delay, bus_eta_s,
                        wrong_phase=False, remaining_red_s=_remain)
                    _reward_rows.append((f"ER_{er_s:.0f}", r, bps, cpc, 0.0, er_s))
                    if r > best_reward:
                        best_reward = r; best_ge = er_s
                        best_action = f"ER_{er_s:.0f}"

            # ── OC (Offset Correction) -- SOLVED alignment shift ───────
            # Compute the exact boundary shift that aligns the bus-phase start
            # with the bus arrival (a proper method, not the old +/-{5,10} grid).
            # Returns 0 when the bus phase is already active (use GE instead).
            if _zig_seq:
                _oc_shift, _oc_tbp = self._solve_offset_correction(
                    bus_eta_s, current_phase, timeSta, _remain)
                if abs(_oc_shift) >= 3.0:
                    r, so, tp, bps, cpc, nsd, std = _spm._dctsp_eval_action(
                        self, 'OFFSET_CORRECTION', _oc_shift, _sigma_in,
                        no_action_bus_delay, bus_eta_s,
                        wrong_phase=False, remaining_red_s=_remain)
                    _reward_rows.append((f"OC_{_oc_shift:+.0f}", r, bps, cpc, 0.0, abs(_oc_shift)))
                    if r > best_reward:
                        best_reward = r; best_ge = abs(_oc_shift)
                        best_action = f"OC_{_oc_shift:+.0f}"

            # ── GR on active bus phase ─────────────────────────────────
            if _spm.DCTSP_GREEN_REALLOC_MODE and _zig_gr:
                for gr_s in [5.0, 10.0, 15.0]:
                    r, so, tp, bps, cpc, nsd, std = _spm._dctsp_eval_action(
                        self, 'GREEN_REALLOC', gr_s, _sigma_in, no_action_bus_delay, bus_eta_s,
                        wrong_phase=False, remaining_red_s=_remain)
                    _reward_rows.append((f"GR_{gr_s:.0f}", r, bps, cpc, 0.0, gr_s))
                    if r > best_reward:
                        best_reward = r; best_ge = gr_s
                        best_action = f"GR_{gr_s:.0f}"

            # ── INS close-proximity ─────────────────────────────────────
            if _zig_ins and bus_eta_s < float(self.BusPhaseDuration):
                ins_dur_close = bus_eta_s + 10.0
                bus_saved, other_inc, side_inc = self._reward_evaluate_insertion(
                    ins_dur_close, time, timeSta, bus_eta_s)
                reward_ins_c = (REWARD_ALPHA * bus_saved
                                - REWARD_BETA * other_inc - REWARD_GAMMA * side_inc)
                _reward_rows.append(("INS_close", reward_ins_c, bus_saved, other_inc, side_inc, ins_dur_close))
                if reward_ins_c > best_reward:
                    best_reward = reward_ins_c; best_ge = ins_dur_close
                    best_action = "INS_close"

        elif not _mode_committed and not _mode_is_decider and current_phase != self.BusPhase and REWARD_TSP_ENABLE_INS:
            # ── INS ────────────────────────────────────────────────────
            if _zig_ins:
                ins_dur = min(float(self.BP_upper_bound),
                              max(float(self.BP_lower_bound), bus_eta_s + 5.0))
                bus_saved, other_inc, side_inc = self._reward_evaluate_insertion(
                    ins_dur, time, timeSta, bus_eta_s)
                reward_ins = (REWARD_ALPHA * bus_saved
                              - REWARD_BETA * other_inc - REWARD_GAMMA * side_inc)
                _reward_rows.append((f"INS_{ins_dur:.0f}", reward_ins, bus_saved, other_inc, side_inc, ins_dur))
                if LOG_REWARD:
                    log_to_file(f"[REWARD_TSP] inter={self.id} R(INS_{ins_dur:.0f})={reward_ins:.1f}")
                if reward_ins > best_reward:
                    best_reward = reward_ins; best_ge = ins_dur
                    best_action = f"INS_{ins_dur:.0f}"

            # ── GR (Green Reallocation) ────────────────────────────────
            if _zig_gr:
                for gr_s in [5.0, 10.0, 15.0]:
                    r, so, tp, bps, cpc, nsd, std = _spm._dctsp_eval_action(
                        self, 'GREEN_REALLOC', gr_s, _sigma_in, no_action_bus_delay, bus_eta_s,
                        wrong_phase=_wrong_phase, remaining_red_s=_rem)
                    _reward_rows.append((f"GR_{gr_s:.0f}", r, bps, cpc, 0.0, gr_s))
                    if r > best_reward:
                        best_reward = r; best_ge = gr_s
                        best_action = f"GR_{gr_s:.0f}"

            # ── VP (Phase Skipping) ────────────────────────────────────
            if _zig_seq:
                for vp_s in [_rem, max(5.0, _rem)]:
                    r, so, tp, bps, cpc, nsd, std = _spm._dctsp_eval_action(
                        self, 'PHASE_SKIP', vp_s, _sigma_in, no_action_bus_delay, bus_eta_s,
                        wrong_phase=False, remaining_red_s=_rem)
                    _reward_rows.append((f"VP_{vp_s:.0f}", r, bps, cpc, 0.0, vp_s))
                    if r > best_reward:
                        best_reward = r; best_ge = vp_s
                        best_action = f"VP_{vp_s:.0f}"

            # ── OC (Offset Correction) -- SOLVED alignment shift ───────
            # Exact boundary shift aligning the bus-phase start with the bus
            # arrival (a proper method, not the old +/-{5,10} grid).
            if _zig_seq:
                _oc_shift, _oc_tbp = self._solve_offset_correction(
                    bus_eta_s, current_phase, timeSta, _rem)
                if abs(_oc_shift) >= 3.0:
                    r, so, tp, bps, cpc, nsd, std = _spm._dctsp_eval_action(
                        self, 'OFFSET_CORRECTION', _oc_shift, _sigma_in,
                        no_action_bus_delay, bus_eta_s,
                        wrong_phase=False, remaining_red_s=_rem)
                    _reward_rows.append((f"OC_{_oc_shift:+.0f}", r, bps, cpc, 0.0, abs(_oc_shift)))
                    if r > best_reward:
                        best_reward = r; best_ge = abs(_oc_shift)
                        best_action = f"OC_{_oc_shift:+.0f}"

            # ── OPP (Optimised Plan Push) -- corridor stagger realignment ─
            # Moves the bus-green START toward the joint (sequence, offset)
            # optimum from retime/optimize.py. Touches NO green duration, so the
            # splits stay hand-tuned (the half the 2026-09-28 A/B refuted).
            # Offered ALONGSIDE OC, not instead of it: OC chases one bus's
            # arrival, OPP chases the platoon's. Priced like OC, so OPP only wins
            # a tick when the advance genuinely helps the waiting bus.
            if _zig_seq and bool(globals().get('BXT_OPT_OFFSET_PUSH', False)):
                _opp_shift, _opp_tgt = self._solve_offset_plan_push(
                    current_phase, timeSta)
                if abs(_opp_shift) >= 3.0:
                    r, so, tp, bps, cpc, nsd, std = _spm._dctsp_eval_action(
                        self, 'OFFSET_PLAN_PUSH', _opp_shift, _sigma_in,
                        no_action_bus_delay, bus_eta_s,
                        wrong_phase=False, remaining_red_s=_remain)
                    _reward_rows.append((f"OPP_{_opp_shift:+.0f}", r, bps, cpc, 0.0,
                                         abs(_opp_shift)))
                    if r > best_reward:
                        best_reward = r; best_ge = _opp_shift
                        best_action = f"OPP_{_opp_shift:+.0f}"

            # ── OC at phase end (adaptive alignment) ─────────────────────
            # When the current (non-bus) phase is about to end and the bus
            # misses the natural bus green, consider shifting THIS boundary
            # by exactly the misalignment so the bus phase starts as the bus
            # arrives (green-wave alignment at the switch). One candidate,
            # not a grid: advance = time_to_bus_phase - bus_eta. Advance
            # only (shortening); delaying green helps nothing here. Bounded
            # by min-green preservation (executor floors at 5 s anyway) and
            # skipped below the action minimum. The fixed ±5/±10 grid above
            # covers mid-phase alignment; this covers the phase-end case the
            # grid quantises poorly. Pareto/Z4/cost-veto still apply.
            if _zig_seq:
                try:
                    _oc_trig = float(globals().get('OC_END_TRIGGER_S', 15.0))
                except Exception:
                    _oc_trig = 15.0
                if 0.0 < _rem <= _oc_trig:
                    _t_bp2 = None
                    try:
                        _t_bp2 = max(0.0, _rem)
                        _ci2 = self.phase_list.index(current_phase)
                        _bi2 = self.phase_list.index(self.BusPhase)
                        _n2 = len(self.phase_list)
                        for _k in range(1, (_bi2 - _ci2) % _n2):
                            _t_bp2 += float(GetPhaseDuration(
                                self.node_id, self.phase_list[(_ci2 + _k) % _n2],
                                timeSta))
                    except Exception:
                        _t_bp2 = None
                    if _t_bp2 is not None:
                        _shift = _t_bp2 - max(0.0, float(bus_eta_s))
                        _min_oc = 3.0
                        _max_oc = min(15.0, max(0.0, _rem - 5.0))
                        if _min_oc <= _shift <= _max_oc:
                            r, so, tp, bps, cpc, nsd, std = _spm._dctsp_eval_action(
                                self, 'OFFSET_CORRECTION', -_shift, _sigma_in,
                                no_action_bus_delay, bus_eta_s,
                                wrong_phase=False, remaining_red_s=_rem)
                            _reward_rows.append((f"OC_{-_shift:+.0f}", r, bps, cpc,
                                                 0.0, _shift))
                            if r > best_reward:
                                best_reward = r; best_ge = _shift
                                best_action = f"OC_{-_shift:+.0f}"

            # ── PT (Phase Rotation) ────────────────────────────────────
            _n_ph = len(self.phase_list)
            _ci_pt = self.phase_list.index(current_phase) if current_phase in self.phase_list else 0
            if _zig_seq and _pr_mode:
                for _pt_skip in range(1, _n_ph):
                    _pt_skip_dur = 0.0
                    for _k in range(1, _pt_skip + 1):
                        _ph_k = self.phase_list[(_ci_pt + _k) % _n_ph]
                        try:
                            _pt_skip_dur += float(GetPhaseDuration(self.node_id, _ph_k, timeSta) or 0.0)
                        except Exception:
                            _pt_skip_dur += 15.0
                    _pt_skip_dur = max(5.0, _pt_skip_dur)
                    r, so, tp, bps, cpc, nsd, std = _spm._dctsp_eval_action(
                        self, 'PHASE_ROTATION', _pt_skip_dur, _sigma_in, no_action_bus_delay, bus_eta_s,
                        wrong_phase=False, remaining_red_s=_rem)
                    # label keeps the skip COUNT (execution derives the target
                    # phase from it); param carries the green DURATION.
                    _reward_rows.append((f"PT_{_pt_skip}", r, bps, cpc, 0.0, _pt_skip_dur))
                    if r > best_reward:
                        best_reward = r; best_ge = _pt_skip_dur
                        best_action = f"PT_{_pt_skip}"

        # ── Pareto-based selection (weight-free) + Z4 throughput constraint ──
        # Overrides the scalar alpha/beta/gamma argmax above: builds each
        # candidate's objective vector from the SAME evaluations already in
        # _reward_rows and picks via dominance + Z4 gate + ideal-point
        # compromise (_pareto_select_candidates). The scalar rewards remain in
        # the CSV for post-hoc comparison, but the decision is weight-free.
        # GLOBAL_REWARD aggregation switch (DCTSP_MARL lineage): when on, the
        # Pareto layer below is SKIPPED and the corridor-global rescore block
        # after it decides instead (local net + downstream-chain bus effect).
        # Flag off = byte-identical legacy path.
        _global_reward_on = (bool(globals().get('GLOBAL_REWARD_MODE', False))
                             or bool(getattr(_spm, 'GLOBAL_REWARD_MODE', False)))
        if (not _mode_committed and not _mode_is_decider and PARETO_SELECTION_MODE
                and len(_reward_rows) > 1 and not _global_reward_on):
            _bus_occ_c = max(safe_float(self.BusOcc), 1.0)
            # NO_ACTION keeps the incoming lateness; its delta vector is
            # (0 net, 0 downstream, sigma_in).
            _cands = [{"action": "NO_ACTION", "param": 0.0,
                       "bus_saved": 0.0, "other_inc": 0.0, "side_inc": 0.0,
                       "downstream": 0.0, "sigma_out": _sigma_in}]
            for _act, _rwd, _bs, _oi, _si, _par in _reward_rows:
                if _act == "NO_ACTION":
                    continue   # delta vector for NO_ACTION is (0,0,0) by definition
                # Residual bus lateness (Z3): mirror _dctsp_eval_action.  Only
                # actions that advance the bus (GE/INS/VP/PT/GR) reduce it by
                # the seconds saved; ER/OC leave it unchanged.
                _bs_s = max(0.0, float(_bs)) / _bus_occ_c
                _ekind, _ = _spm.parse_action_token(_act)
                if _ekind in ("GE", "INS", "VP", "PT", "GR"):
                    _so = max(0.0, _sigma_in - _bs_s)
                else:
                    _so = _sigma_in
                # Downstream coordination impact (Z2) at the NEXT managed
                # junction, from live corridor state.  Zero when no corridor /
                # downstream target / tracker is available.
                _down = 0.0
                if _bs > 0.0 and self._corridor_coord is not None:
                    try:
                        _down = float(self._corridor_coord.project_downstream_delay_paxs(
                            int(self.id), int(veh_id or -1), float(time),
                            float(timeSta), float(bus_eta_s), _bs_s, _bus_occ_c))
                    except Exception:
                        _down = 0.0
                _cands.append({"action": _act, "param": _par, "bus_saved": _bs,
                               "other_inc": _oi, "side_inc": _si,
                               "downstream": _down, "sigma_out": _so})
            _chosen, _pinfo = _pareto_select_candidates(
                _cands, safe_float(self.BusOcc), safe_float(self.CarOcc))
            log_to_file(f"[REWARD_TSP] inter={self.id} {_pinfo}")
            if _chosen is not None:
                _tok = str(_chosen["action"])
                best_action = _tok
                # Executable duration comes straight from the candidate row —
                # never re-parsed from the label (labels like INS_POST_15 or
                # PT_2 do not carry the duration in a parseable position).
                best_ge = safe_float(_chosen.get("param", 0.0), 0.0)
                # Keep best_reward consistent with the chosen row for logging.
                for _act, _rwd, _bs, _oi, _si, _par in _reward_rows:
                    if _act == _tok:
                        best_reward = _rwd
                        break

        # ── GLOBAL_REWARD aggregation (DCTSP_MARL lineage) ───────────────
        # When GLOBAL_REWARD_MODE is on, the common selection layer maximises
        # CORRIDOR-global net passenger impact instead of this-junction-local
        # net:  global_net = local_net + chain_downstream_bus_effect, where
        # chain_downstream is the signed output of project_chain_delay_paxs
        # (+ = coordination cost, − = coordination benefit, pax-s).
        # α/β/γ are untouched -- the switch is aggregation SCOPE, not weights.
        # NO_ACTION keeps its local baseline (its chain is 0 by construction)
        # so the bar is unchanged; only action rows gain their corridor
        # effect. Decides in place of the scalar argmax above (the Pareto
        # block is skipped when the flag is on, see its gate); the Z4
        # feasibility gate below still applies. best_action stays a
        # _reward_rows label, so the lateness rollover, reward CSV and
        # executor below work unchanged.
        _g_chain_out = 0.0  # corridor-chain effect of the chosen action (pax-s)
        if (_global_reward_on and not _mode_committed and not _mode_is_decider
                and len(_reward_rows) > 1):
            try:
                _g_occ = max(safe_float(self.BusOcc), 1.0)
                _g_chain_cache = {}
                _g_best_act, _g_best_ge = "NO_ACTION", 0.0
                _g_best_rwd, _g_best_chain = reward_no_action, 0.0
                for _act, _rwd, _bs, _oi, _si, _par in _reward_rows:
                    if _act == "NO_ACTION":
                        continue
                    _bs_s = max(0.0, float(_bs)) / _g_occ
                    _ck = round(_bs_s, 1)
                    if _ck not in _g_chain_cache:
                        _ch = 0.0
                        if (_bs_s > 0.0 and self._corridor_coord is not None
                                and veh_id and int(veh_id) > 0):
                            try:
                                _ch = float(self._corridor_coord.project_chain_delay_paxs(
                                    int(self.id), int(veh_id), float(time),
                                    float(timeSta), float(bus_eta_s), _bs_s,
                                    _g_occ))
                            except Exception:
                                _ch = 0.0
                        _g_chain_cache[_ck] = _ch
                    _g_rwd = float(_rwd) - _g_chain_cache[_ck]
                    if _g_rwd > _g_best_rwd:
                        _g_best_rwd = _g_rwd
                        _g_best_act = _act
                        _g_best_ge = safe_float(_par, 0.0)
                        _g_best_chain = _g_chain_cache[_ck]
                if _g_best_act != best_action:
                    log_to_file(
                        f"[GLOBAL_REWARD] inter={self.id} t={time:.1f} bus={veh_id} "
                        f"{best_action} -> {_g_best_act} "
                        f"(local_r={best_reward:.0f} global_r={_g_best_rwd:.0f} "
                        f"chain={_g_best_chain:.0f} pax-s)")
                best_action, best_ge, best_reward = _g_best_act, _g_best_ge, _g_best_rwd
                _g_chain_out = float(_g_best_chain)
            except Exception as _gr_e:
                log_to_file(f"[GLOBAL_REWARD] rescore failed inter={self.id}: {_gr_e!r}")

        # ── Z4 throughput gate (non-Pareto path) ──────────────────────────
        # When PARETO_SELECTION_MODE is False the scalar argmax above does NOT
        # check the Z4 hard constraint. Re-assert it here: any chosen action
        # whose net corridor vehicle-time delta violates Z4_TOLERANCE_VEH_S is
        # rejected regardless of how it was selected. NO_ACTION is always
        # feasible so the controller never gets stuck.  When a specialised
        # method commits its own action, its internal balance/gate logic is
        # authoritative, so the global Z4 re-gate is skipped too.
        if Z4_CONSTRAINT_MODE and best_action != "NO_ACTION":
            _bus_occ_z4 = max(safe_float(self.BusOcc), 1.0)
            _car_occ_z4 = max(safe_float(self.CarOcc), 1.0)
            _z4_bs = 0.0; _z4_oi = 0.0; _z4_si = 0.0
            for _act, _rwd, _bs, _oi, _si, _par in _reward_rows:
                if _act == best_action:
                    _z4_bs = float(_bs); _z4_oi = float(_oi); _z4_si = float(_si)
                    break
            # Paper-aligned units: net PASSENGER-seconds (occupancies already
            # baked into _bs/_oi/_si upstream, incl. schedule-adherence
            # scaling). Legacy VEH_S tolerance reused when PAX_S absent.
            _z4_net_pax_s = _z4_bs - _z4_oi - _z4_si
            if _z4_net_pax_s < -_z4_eff_tol():
                _Z4_EVALS[1] += 1
                log_to_file(
                    f"[Z4 GATE] inter={self.id} action={best_action} "
                    f"z4_net={_z4_net_pax_s:.1f} pax-s "
                    f"below tolerance={-_z4_eff_tol():.0f} -> forcing NO_ACTION",
                    )
                best_action = "NO_ACTION"
                best_ge = 0.0
                best_reward = reward_no_action

        # ── Lateness (Z3) rollover ─────────────────────────────────────────
        # Persist the residual schedule deviation for the NEXT decision cycle,
        # per bus (so lateness follows the bus down the corridor).  The bus
        # accrues its actual no-action hold time; the executed action clears
        # the seconds it saved.  NO_ACTION leaves the hold time as lateness.
        try:
            _last_bs = 0.0
            for _act, _rwd, _bs, _oi, _si, _par in _reward_rows:
                if _act == best_action:
                    _last_bs = float(_bs)
                    break
            _last_kind, _ = _spm.parse_action_token(best_action)
            _hold_s = max(0.0, float(no_action_bus_delay))
            if _last_kind in ("GE", "INS", "VP", "PT", "GR") and _last_bs > 0.0:
                _saved_s = max(0.0, _last_bs) / max(safe_float(self.BusOcc), 1.0)
                _last_sigma_out = max(0.0, _sigma_in + _hold_s - _saved_s)
            else:
                # NO_ACTION / ER / OC: the bus still endures the hold.
                _last_sigma_out = max(0.0, _sigma_in + _hold_s)
            self._last_sigma = _last_sigma_out
            if veh_id and int(veh_id) > 0:
                _bus_lateness[int(veh_id)] = _last_sigma_out
        except Exception:
            pass

        # ── Write per-cycle reward CSV ────────────────────────────────────────
        # 2026-09-25: appended flow-stage + chain columns (backwards compatible:
        # old readers ignore the tail). diagnose_vs_notsp.py joins these to the
        # per-intersection deltas to blame the exact losing actions.
        global _reward_cycle_header_written
        try:
            _upflow_bus  = round(float(self.UpFlowList[0][0]), 1)  if self.UpFlowList.shape[1]  > 0 else 0.0
            _maxq_bus    = round(float(self.MaxQueueLength[0][0]), 1) if self.MaxQueueLength.shape[1] > 0 else 0.0
            _reddur_bus  = round(float(self.RedDurationList[0][0]), 1) if self.RedDurationList.shape[1] > 0 else 0.0
            try:
                _fs_csv = self._flow_stage_snapshot()
            except Exception:
                _fs_csv = {"stage": "UNK", "main_x": 0.0, "side_max_flow": 0.0,
                           "queue_veh": 0.0, "armed": True}
            with open(_REWARD_CYCLE_CSV, "a", newline="", encoding="utf-8") as _rcf:
                import csv as _csv_mod
                _rcw = _csv_mod.writer(_rcf)
                if not _reward_cycle_header_written:
                    _rcw.writerow([
                        "sim_time_s", "junction_id", "veh_id", "bus_eta_s",
                        "current_phase", "action",
                        "reward", "bus_saved_pax_s", "other_inc_pax_s", "side_inc_pax_s",
                        "is_chosen",
                        "upflow_bus_vph", "max_queue_bus_veh", "red_dur_bus_s",
                        "param_s",
                        "chain_pax_s", "main_x", "side_max_flow_vph",
                        "queue_veh", "tsp_armed", "monitor", "stage",
                    ])
                    _reward_cycle_header_written = True
                for _act, _r, _bs, _oi, _si, _par in _reward_rows:
                    _rcw.writerow([
                        round(time, 1), self.id, int(veh_id or -1),
                        round(bus_eta_s, 1), current_phase,
                        _act,
                        round(_r, 3), round(_bs, 3), round(_oi, 3), round(_si, 3),
                        1 if _act == best_action else 0,
                        _upflow_bus, _maxq_bus, _reddur_bus,
                        round(safe_float(_par), 2),
                        round(float(_g_chain_out) if _act == best_action else 0.0, 1),
                        _fs_csv["main_x"], _fs_csv["side_max_flow"],
                        _fs_csv["queue_veh"], int(bool(_fs_csv["armed"])),
                        int(bool(monitor)), _fs_csv["stage"],
                    ])
        except Exception as _rce:
            log_to_file(f"[REWARD_CYCLE_CSV] write error: {_rce}")

        # ── Record detection (debounce-guarded) ──────────────────────────────
        if stats_ok:
            self._record_detection(time)

        # ── Execute best action ───────────────────────────────────────────────
        # Hard gate: at most one TSP action per cycle per junction.
        _min_cycle_gap = max(30.0, float(self.config.get('CycleTime', 60.0)) * 0.3)
        _since_last = time - self.last_tsp_action_time
        if best_action != "NO_ACTION" and _since_last < _min_cycle_gap:
            if LOG_REWARD:
                log_to_file(
                    f"[REWARD_TSP] inter={self.id} t={time:.1f} "
                    f"DECISION={best_action} blocked — only {_since_last:.1f}s "
                    f"since last action (min gap={_min_cycle_gap:.0f}s)")
            best_action = "NO_ACTION"
            best_ge = 0.0

        # Minimum viable duration: actions below 5.0 s are not worth the
        # disruption to the signal cycle.
        if best_ge > 0 and best_ge < 5.0:
            if LOG_REWARD:
                log_to_file(
                    f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"DECISION={best_action} best_ge={best_ge:.1f}s < 5.0s "
                    f"— treating as NO_ACTION")
            best_action = "NO_ACTION"
            best_ge = 0.0

        if best_action == "NO_ACTION":
            # Debounce: suppress re-evaluation for 5 s so we don't flood the
            # log with identical NO_ACTION decisions on every simulation step.
            self._reward_no_action_until = time + float(globals().get('NO_ACTION_HOLD_S', 5.0) or 5.0)
            if stats_ok:
                self.stats.record_tsp_skip(self.id, 'reward_no_action')
            log_to_file(
                f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                f"eta={_eta_disp} DECISION=NO_ACTION R={best_reward:.1f} "
                f"(cost to others outweighs bus benefit)")
            # Still propagate corridor coordination
            if self._corridor_coord is not None and COORDINATED_TSP:
                try:
                    self._corridor_coord.notify_bus_granted(
                        veh_id, self.id, time, None)
                except Exception:
                    pass
            return

        # ── CONTINUOUS MONITOR commit guard (car objective, no bus) ──────────
        # A no-bus (monitor) decision commits only if the state-based benefit
        # clears CONTINUOUS_MONITOR_MIN_GAIN_PAXS, so the controller does not
        # twitch the plan for a negligible car gain. The structural gates
        # (recoverability, progression) still apply at execution below.
        if monitor and best_action != "NO_ACTION":
            # ── Zero phantom bus credit on car-only ticks (2026-09-27) ────
            # Generic-pool evaluators credit hypothetical-bus savings even with
            # veh_id=-1 (VP_5 pred_bus=160 at every junction; PT_7 1800). No
            # bus present = no bus savings: strip alpha*bus from the matched
            # row and re-seat it with bs=0 so the min-gain test below -- and
            # the [DECISION] ledger -- see car economics alone. Single funnel:
            # covers every pool (generic + mode rows; mode rows were already
            # zeroed at seating, so their match is a no-op here).
            if bool(getattr(_spm, 'MONITOR_BUS_ZERO', True)):
                try:
                    for (_zi, _zrow) in enumerate(list(_reward_rows)):
                        (_za, _zr, _zb, _zo, _zs, _zp) = _zrow
                        if _za == best_action and float(_zb) > 0.0:
                            _zb_rm = float(REWARD_ALPHA) * float(_zb)
                            best_reward = float(best_reward) - _zb_rm
                            _reward_rows[_zi] = (_za, best_reward, 0.0,
                                                 _zo, _zs, _zp)
                            log_to_file(
                                f"[MONITOR_BUSZERO] inter={self.id} "
                                f"t={time:.1f} {best_action} "
                                f"phantom_bus={_zb_rm:.0f} "
                                f"car_net={float(best_reward):.0f}")
                            break
                except Exception:
                    pass
            # ── Progression priced INTO the monitor reward (2026-09-27) ────
            # Car-only ticks previously saw pure car gain (pred_side=0, no bus
            # term) while the 300 pax-s veto gate never fired on small shifts;
            # DE500 committed 65 such greens and broke progression diffusely
            # (+11.6s car). Subtract the POG-weighted Purdue-diagram platoon
            # loss up front so the min-gain test below sees the NET benefit.
            # Cycle-neutral actions (GR/OC) carry ~no shift and are unaffected.
            try:
                _mp_kind, _ = _spm.parse_action_token(best_action)
            except Exception:
                _mp_kind = ""
            _mp_shift = float(best_ge or 0.0) if _mp_kind in (
                "GE", "INS", "VP", "PT", "ER") else 0.0
            _mp_w = float(globals().get('MONITOR_PROG_WEIGHT', 1.0) or 0.0)
            if _mp_shift >= 1.0 and _mp_w > 0.0:
                try:
                    self._sample_progression(current_phase)
                    _mp_cost = _mp_w * float(self._progression_cost(_mp_shift))
                except Exception:
                    _mp_cost = 0.0
                if _mp_cost > 0.0:
                    best_reward = float(best_reward) - _mp_cost
                    log_to_file(
                        f"[MONITOR_PROG] inter={self.id} t={time:.1f} "
                        f"{best_action} car_gain={float(best_reward) + _mp_cost:.0f} "
                        f"prog_loss={_mp_cost:.0f} net={float(best_reward):.0f} "
                        f"POG={self._progression_pog():.2f}")
            _mon_min = float(globals().get('CONTINUOUS_MONITOR_MIN_GAIN_PAXS', 50.0))
            if float(best_reward) < _mon_min:
                log_to_file(
                    f"[MONITOR] inter={self.id} t={time:.1f} state-eval "
                    f"{best_action} benefit={best_reward:.0f}paxs < {_mon_min:.0f} "
                    f"-> NO_ACTION")
                best_action = "NO_ACTION"; best_reward = 0.0; best_ge = 0.0
                self._reward_no_action_until = time + float(globals().get('NO_ACTION_HOLD_S', 5.0) or 5.0)
                return
            log_to_file(
                f"[MONITOR] inter={self.id} t={time:.1f} state-eval commits "
                f"{best_action} benefit={best_reward:.0f}paxs (no bus present)")

        # Canonical execution kind — one parser handles every candidate label
        # regardless of which mode generated it (GE_10, INS_close, INS_POST_15,
        # ER_10, GR_5, OC_+5, VP_12, PT_2, ...).
        _exec_kind, _ = _spm.parse_action_token(best_action)

        # ── Pre-arm hard-veto (#2): pre-arms may only EXTEND or INSERT ─────────
        # A pre-arm-sourced decision may only fire GE/INS (both counted and cost-
        # gated). The uncounted timing families (OC/GR/ER/PT/VP) are the measured
        # car-delay cascade drivers (champion search 2026-08-24: SAFE seed 300 had
        # 0 ext/0 ins yet car doubled — pure OC/GR from ~450 pre-arms/run). Forbid
        # them on pre-arms unless PREARM_ALLOW_TIMING_ACTIONS re-enables them;
        # fall back to the best GE/INS candidate, else NO_ACTION.
        if (getattr(self, '_prearm_sourced_eval', False)
                and _exec_kind in ("OC", "GR", "ER", "PT", "VP")
                and not bool(globals().get('PREARM_ALLOW_TIMING_ACTIONS', False))):
            _pa_alt, _pa_rwd, _pa_ge = None, None, 0.0
            for _act, _rwd, _bs, _oi, _si, _par in _reward_rows:
                _ak, _ = _spm.parse_action_token(_act)
                if _ak in ("GE", "INS") and (_pa_rwd is None or _rwd > _pa_rwd):
                    _pa_alt, _pa_rwd, _pa_ge = _act, _rwd, _par
            _vetoed_kind = _exec_kind
            if _pa_alt is not None:
                best_action, best_reward, best_ge = _pa_alt, _pa_rwd, _pa_ge
                _exec_kind, _ = _spm.parse_action_token(best_action)
            else:
                best_action, best_reward, best_ge, _exec_kind = \
                    "NO_ACTION", 0.0, 0.0, "NO_ACTION"
            if stats_ok:
                self.stats.record_tsp_skip(self.id, 'prearm_timing_veto')
            log_to_file(
                f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                f"prearm timing-veto {_vetoed_kind}->{best_action}")
            if _exec_kind == "NO_ACTION":
                self._reward_no_action_until = time + float(globals().get('NO_ACTION_HOLD_S', 5.0) or 5.0)
                return

        # ── Hard SEQ cap per signal cycle ─────────────────────────────────
        # When the best action is a phase rotation (SEQ) and PHASE_SEQ_MAX_PER_CYCLE
        # is already exhausted within the current cycle, fall back to the best
        # remaining non-SEQ candidate (GR/GE/... in BOTH-family runs, NO_ACTION in
        # SWAPS-only runs) so the cap binds regardless of the decision window.
        if (getattr(self, '_seq_max_per_cycle', 0) > 0 and _exec_kind == "PT"):
            _seq_cycle = float(self.config.get('CycleTime', 135))
            if self._seq_window_start < 0.0 or \
                    time - self._seq_window_start >= _seq_cycle:
                self._seq_window_start = time
                self._seq_window_count = 0
            if self._seq_window_count >= self._seq_max_per_cycle:
                _alt_action, _alt_reward, _alt_ge = None, 0.0, 0.0
                for _act, _rwd, _bs, _oi, _si, _par in _reward_rows:
                    _ak, _ = _spm.parse_action_token(_act)
                    if _ak == "PT":
                        continue
                    if _rwd > _alt_reward:
                        _alt_action, _alt_reward, _alt_ge = _act, _rwd, _par
                if _alt_action is not None:
                    best_action = _alt_action
                    best_reward = _alt_reward
                    best_ge    = _alt_ge
                    _exec_kind, _ = _spm.parse_action_token(best_action)
                else:
                    best_action = "NO_ACTION"
                    best_reward = 0.0
                    best_ge    = 0.0
                    _exec_kind  = "NO_ACTION"
                log_to_file(
                    f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"SEQ cap ({self._seq_window_count}/{self._seq_max_per_cycle} "
                    f"per {_seq_cycle:.0f}s) hit -> fell back to {best_action}")
                if _exec_kind == "NO_ACTION":
                    if stats_ok:
                        self.stats.record_tsp_skip(self.id, 'seq_cap')
                    return
            else:
                self._seq_window_count += 1

        # ── NO_ACTION: SOLVE a hold before re-deciding (multi-bus aware) ───────
        # Instead of re-deciding every step (or a fixed 5s freeze), when we choose
        # to do nothing, work out WHEN the next decision is actually needed: hold
        # until the NEAREST oncoming bus is about to enter the action window, then
        # wake up. Considers ALL oncoming buses via the coordinator. Capped so a
        # bus that appears/speeds up during the hold isn't missed for long.
        if _exec_kind == "NO_ACTION":
            _hold = 5.0
            try:
                _cc = getattr(self, '_corridor_coord', None)
                _onc = _cc.oncoming_buses(self.id, time) if _cc is not None else []
                _win = float(getattr(self, 'BusPhaseDuration', 20.0)) + float(MAX_GE_EXTENSION_S)
                _cap = float(globals().get('BXT_MAX_NOACT_HOLD_S', 12.0))
                _hold = (max(1.0, min(_onc[0][1] - _win, _cap)) if _onc else _cap)
            except Exception:
                _hold = 5.0
            self._reward_no_action_until = time + _hold
            if stats_ok:
                self.stats.record_tsp_skip(self.id, 'reward_no_action')
            return

        # ── Two-way through-band floors (paper Eqs prog_in/band_*) ──────────
        # Any action reaching execution shifts clocks (GE/INS +δ, ER −δ,
        # GR/others 0 per offset_state); veto it if the shift would newly
        # breach either directional band floor, else commit the shift to the
        # per-cycle accumulator. Single funnel: every executing action,
        # all modes, passes here.
        if _exec_kind != "NO_ACTION" and \
                bool(globals().get('TWOWAY_BAND_MODE', False)):
            _tw_shift = {"GE": 1.0, "INS": 1.0, "ER": -1.0}.get(
                _exec_kind, 0.0) * float(best_ge or 0.0)
            _tw_ok, _tw_detail = _twoway_band_check(self.id, _tw_shift, time)
            if not _tw_ok:
                if stats_ok:
                    self.stats.record_tsp_skip(self.id, 'twoway_band_veto')
                log_to_file(
                    f"[TWOWAY] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"action={best_action} {_tw_detail} — VETO to NO_ACTION")
                best_action = "NO_ACTION"
                best_reward = 0.0
                best_ge = 0.0
                _exec_kind = "NO_ACTION"
                self._reward_no_action_until = time + float(globals().get('NO_ACTION_HOLD_S', 5.0) or 5.0)
                if stats_ok:
                    self.stats.record_tsp_skip(self.id, 'reward_no_action')
                return
            try:
                _twoway_accum(self.id,
                              int(float(time or 0.0) // _twoway_cycle_s()))[0] \
                    += _tw_shift
            except Exception:
                pass

        # ── Recoverability (offset-preservation) gate ─────────────────────────
        # A cycle-LENGTHENING action (GE / INS / VP / PT) borrows `best_ge` s that
        # _apply_cycle_recovery must trim back from the upcoming cross phases THIS
        # cycle to keep the junction aligned with the corridor's coordinated OFFSET.
        # If the borrowed time exceeds the recoverable headroom (upcoming phases'
        # slack above min-green), the debt cannot be repaid this cycle -> the
        # offset drifts permanently -> the green wave breaks downstream. This is
        # the dominant failure on saturated corridors (Logan): the cross phases sit
        # near min-green, so there is no slack to pay the debt back. Gate it:
        # feasible action set = those whose induced cycle debt is recoverable this
        # cycle. Clamp the action to what the cycle can absorb; stand down if even
        # the minimum is unrecoverable. GREEN_REALLOC / OC are cycle-neutral
        # (no net cycle-length change) and are exempt, so the controller naturally
        # falls back to a structure-preserving action instead of drifting the plan.
        if (bool(globals().get('RECOVERABILITY_GATE', True))
                and _exec_kind in ("GE", "INS", "VP", "PT")):
            try:
                _recov = float(self._reward_get_recoverable(current_phase, timeSta))
            except Exception:
                _recov = 999.0
            _rg_slack = float(globals().get('RECOVERABILITY_SLACK_S', 1.0))
            _rg_min = float(globals().get('MIN_GE_EXTENSION_S', 3.0))
            # Recovered-cycle-plan horizon: a grant is admissible if its debt can
            # be repaid within RECOVERY_MAX_CYCLES cycles (K=1 => must recover this
            # cycle, the strict offset-preserving default). The recovery is then
            # spread over K cycles by _solve_recovery_plan + the carry-over in
            # restore_phase_if_needed, so the junction re-locks to its coordinated
            # offset gradually instead of drifting or snapping.
            _kmax = max(1, int(globals().get('RECOVERY_MAX_CYCLES', 1)))
            _recov_budget = _recov * _kmax
            if float(best_ge) > _recov_budget + _rg_slack:
                if _recov_budget >= _rg_min:
                    log_to_file(
                        f"[RECOVER_GATE] inter={self.id} t={time:.1f} bus={veh_id} "
                        f"{best_action} debt={best_ge:.1f}s > {_kmax}-cycle recoverable="
                        f"{_recov_budget:.1f}s -> CLAMP to {_recov_budget:.1f}s "
                        f"(preserve corridor offset)")
                    best_ge = float(_recov_budget)
                else:
                    if stats_ok:
                        self.stats.record_tsp_skip(self.id, 'recoverability_veto')
                    log_to_file(
                        f"[RECOVER_GATE] inter={self.id} t={time:.1f} bus={veh_id} "
                        f"{best_action} debt={best_ge:.1f}s UNRECOVERABLE "
                        f"(headroom={_recov:.1f}s < {_rg_min:.1f}s) -> NO_ACTION "
                        f"(would drift the coordinated offset / break the green wave)")
                    best_action = "NO_ACTION"; best_reward = 0.0
                    best_ge = 0.0; _exec_kind = "NO_ACTION"
                    self._reward_no_action_until = time + float(globals().get('NO_ACTION_HOLD_S', 5.0) or 5.0)
                    return

        # ── Progression (Purdue-diagram) gate: keep the platoon on green ───────
        # A cycle-lengthening / offset-shifting action moves the coordinated green
        # band relative to the arriving main-street platoon (the Purdue
        # Coordination Diagram walks up/down). _progression_cost prices the main
        # pax*s displaced from green by that shift, WEIGHTED by the live
        # arrivals-on-green POG the controller tracks (so it bites only where the
        # green wave is actually working). If the loss exceeds the threshold, the
        # action is vetoed -- the controller refuses to break its own progression.
        # GR/OC still pass the shift test but carry ~no offset debt.
        if (bool(globals().get('PROGRESSION_GATE', True))
                and _exec_kind in ("GE", "INS", "VP", "PT", "OC")):
            try:
                self._sample_progression(current_phase)
                _ploss = float(self._progression_cost(best_ge))
            except Exception:
                _ploss = 0.0
            _pmax = float(globals().get('PROGRESSION_MAX_LOSS_PAXS', 300.0))
            if _ploss > _pmax:
                if stats_ok:
                    self.stats.record_tsp_skip(self.id, 'progression_veto')
                log_to_file(
                    f"[PROG_GATE] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"{best_action} shift={best_ge:.1f}s POG={self._progression_pog():.2f} "
                    f"progression_loss={_ploss:.0f}paxs > {_pmax:.0f} -> NO_ACTION "
                    f"(would push the main platoon off green)")
                best_action = "NO_ACTION"; best_reward = 0.0
                best_ge = 0.0; _exec_kind = "NO_ACTION"
                self._reward_no_action_until = time + float(globals().get('NO_ACTION_HOLD_S', 5.0) or 5.0)
                return

        # ── Decision ledger funnel (2026-09-25): ONE [DECISION] line per
        # COMMITTED action, all modes / all executors. Predicted breakdown comes
        # straight from the chosen _reward_rows entry (bus_saved - other_inc -
        # side_inc = local net; chain = corridor effect when GLOBAL_REWARD is
        # on) plus the flow STAGE at commit. diagnose_vs_notsp.py joins these
        # to the per-intersection deltas to blame the exact losing actions and
        # trace their cascade. Actions are rare so this never floods.
        if best_action != "NO_ACTION" and _exec_kind != "NO_ACTION":
            try:
                if bool(globals().get('DIAG_DECISION', True)):
                    _d_bs = _d_oi = _d_si = 0.0
                    for _act, _rwd, _bs, _oi, _si, _par in _reward_rows:
                        if _act == best_action:
                            _d_bs, _d_oi, _d_si = float(_bs), float(_oi), float(_si)
                            break
                    _d_net = _d_bs - _d_oi - _d_si
                    try:
                        _d_fs = self._flow_stage_snapshot()
                        _d_stage = ("%s x=%.2f side=%.0f q=%.0f armed=%d" % (
                            _d_fs["stage"], _d_fs["main_x"],
                            _d_fs["side_max_flow"], _d_fs["queue_veh"],
                            int(bool(_d_fs["armed"]))))
                    except Exception:
                        _d_stage = "stage=UNK"
                    log_to_file(
                        f"[DECISION] inter={self.id} t={time:.1f} bus={veh_id} "
                        f"action={best_action} dur={best_ge:.1f}s "
                        f"pred_bus={_d_bs:.0f} pred_other={_d_oi:.0f} "
                        f"pred_side={_d_si:.0f} pred_net={_d_net:.0f} "
                        f"chain={float(_g_chain_out):.0f} R={best_reward:.0f} "
                        f"{_d_stage} monitor={int(bool(monitor))}")
            except Exception:
                pass
            # ── Timing-change broadcast (2026-09-27): every committed action
            # rewrites this junction's plan, so tell the corridor before the
            # executors below apply it -- neighbours' pre-arms, ETA
            # projections and offset math must re-read, not run on snapshots.
            # current_phase/timeSta let the push carry analytic post-commit
            # values (ECI is still pre-commit here).
            try:
                self._broadcast_timing_change(best_action, best_ge, time,
                                              "decision",
                                              current_phase=current_phase,
                                              timeSta=timeSta)
            except Exception:
                pass

        if _exec_kind == "GE":
            # Apply green extension — enforce minimum extension duration
            _min_ge = float(globals().get('MIN_GE_EXTENSION_S', 3.0))
            best_ge = max(best_ge, _min_ge)
            # Apply green extension
            _ps = ECIGetStartingTimePhase(self.node_id)
            _pd = GetPhaseDuration(self.node_id, current_phase, timeSta)
            remain = _pd - (time - _ps)
            if int(current_phase) == int(self.BusPhase):
                _new_dur = self.BusPhaseDuration + best_ge
            else:
                # Non-bus phase (MaxPressure serving pressured side green):
                # extend the CURRENT phase, not the bus phase. The legacy
                # formula below assumed bus-phase context unconditionally.
                _new_dur = _pd + best_ge
            ECIChangeTimingPhase(self.node_id, current_phase,
                                 _new_dur, timeSta)
            self.TimeToTerminateBusPhase = time + remain + best_ge
            self.TSPStrategy  = 1
            self.flag         = 1
            self.TSPActiveTime = time + best_ge + float(globals().get('TSP_POST_GRANT_LOCK_S', 5.0))
            self._tsp_cycle_grant_until = time + self.cycle_len_s
            self.last_tsp_action_time   = time
            self._ge_debt_s = best_ge
            self._ge_opt_GE = best_ge
            _ge_events.append((time, self.id, best_ge, best_reward))
            self.highlight_bus(veh_id)
            self.stats.record_tsp_event(self.id, 'extension')
            self.stats.record_tsp_extension_duration(self.id, best_ge)
            if veh_id and veh_id > 0:
                _acquire_focus(veh_id, self.id, time)
            if self._corridor_coord is not None and COORDINATED_TSP:
                try:
                    self._corridor_coord.notify_bus_granted(
                        veh_id, self.id, time, None)
                except Exception:
                    pass
            log_to_file(
                f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                f"eta={_eta_disp} DECISION={best_action} GE={best_ge:.1f}s "
                f"R={best_reward:.1f}")

        elif _exec_kind == "INS":
            # Apply phase insertion — first set the BusPhase duration so
            # Aimsun holds it for opt_BP seconds, then force the switch.
            # Covers INS_close, INS_<dur>, INS_POST_<dur>, INS_PRETERM_<dur>.
            # NOTE: INS_POST is currently executed immediately (PRETERM
            # semantics); a scheduled at-phase-end insertion is a TODO.
            _min_ins = float(globals().get('MIN_BP_INSERTION_S', 5.0))
            best_ge = max(best_ge, _min_ins)
            self.previous_phase  = current_phase
            self.BusPhaseEndTime = time + best_ge
            ECIChangeTimingPhase(self.id, self.BusPhase, best_ge, timeSta)
            ECIChangeDirectPhase(self.id, self.BusPhase, timeSta, time, acycle, 0)
            self.TSPStrategy  = 2
            self.flag         = 2
            self._ins_bus_phase_seen = False
            self._ins_grant_time = time
            self.TSPActiveTime = time + best_ge + float(globals().get('TSP_POST_GRANT_LOCK_S', 5.0))
            self._ge_debt_s   = best_ge   # spread cost across remaining phases
            self._tsp_cycle_grant_until = time + self.cycle_len_s
            self.last_tsp_action_time   = time
            self.highlight_bus(veh_id)
            self.stats.record_tsp_event(self.id, 'insertion')
            self.stats.record_tsp_insertion_duration(self.id, best_ge)
            self.stats.record_tsp_insertion_wait(self.id, max(0.0, bus_eta_s))
            if veh_id and veh_id > 0:
                _acquire_focus(veh_id, self.id, time)
            if self._corridor_coord is not None and COORDINATED_TSP:
                try:
                    self._corridor_coord.notify_bus_granted(
                        veh_id, self.id, time, None)
                except Exception:
                    pass
            log_to_file(
                f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                f"eta={_eta_disp} DECISION=INS BP={best_ge:.1f}s "
                f"R={best_reward:.1f}")

        elif _exec_kind == "GR":
            # ── Green Reallocation: shorten non-bus phase to advance bus green ──
            # When bus phase is NOT active: reduce current phase duration to let bus
            # phase start sooner. Equivalent to INS but without the full insertion.
            if current_phase != self.BusPhase:
                _min_gr = float(globals().get('MIN_GR_REDUCTION_S', 3.0))
                best_ge = max(best_ge, _min_gr)
                _ps_nb = ECIGetStartingTimePhase(self.node_id)
                _pd_nb = GetPhaseDuration(self.node_id, current_phase, timeSta)
                _remain_nb = max(0.0, _pd_nb - (time - _ps_nb))
                _new_dur = max(5.0, _pd_nb - best_ge)
                ECIChangeTimingPhase(self.node_id, current_phase, _new_dur, timeSta)
                self.TSPStrategy  = 3   # GR
                self.flag         = 3
                self.TSPActiveTime = time + best_ge + float(globals().get('TSP_POST_GRANT_LOCK_S', 5.0))
                self._tsp_cycle_grant_until = time + self.cycle_len_s
                self.last_tsp_action_time   = time
                self._ge_debt_s = best_ge
                self.highlight_bus(veh_id)
                self.stats.record_tsp_event(self.id, 'green_reallocation')
                if veh_id and veh_id > 0:
                    _acquire_focus(veh_id, self.id, time)
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        self._corridor_coord.notify_bus_granted(
                            veh_id, self.id, time, None)
                    except Exception:
                        pass
                log_to_file(
                    f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"eta={_eta_disp} DECISION={best_action} GR={best_ge:.1f}s "
                    f"R={best_reward:.1f}")
            else:
                # GR on active bus phase → equivalent to GE: extend the bus phase
                _min_gr = float(globals().get('MIN_GR_REDUCTION_S', 3.0))
                best_ge = max(best_ge, _min_gr)
                _ps_gr2 = ECIGetStartingTimePhase(self.node_id)
                _pd_gr2 = GetPhaseDuration(self.node_id, current_phase, timeSta)
                _remain_gr2 = _pd_gr2 - (time - _ps_gr2)
                ECIChangeTimingPhase(self.node_id, current_phase,
                                     self.BusPhaseDuration + best_ge, timeSta)
                self.TimeToTerminateBusPhase = time + _remain_gr2 + best_ge
                self.TSPStrategy  = 3
                self.flag         = 1   # use GE flag for GR-on-bus-phase
                self.TSPActiveTime = time + best_ge + float(globals().get('TSP_POST_GRANT_LOCK_S', 5.0))
                self._tsp_cycle_grant_until = time + self.cycle_len_s
                self.last_tsp_action_time   = time
                self._ge_debt_s = best_ge
                self._ge_opt_GE = best_ge
                _ge_events.append((time, self.id, best_ge, best_reward))
                self.highlight_bus(veh_id)
                self.stats.record_tsp_event(self.id, 'extension')
                self.stats.record_tsp_extension_duration(self.id, best_ge)
                if veh_id and veh_id > 0:
                    _acquire_focus(veh_id, self.id, time)
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        self._corridor_coord.notify_bus_granted(
                            veh_id, self.id, time, None)
                    except Exception:
                        pass
                log_to_file(
                    f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"eta={_eta_disp} DECISION={best_action} GR-as-GE={best_ge:.1f}s "
                    f"R={best_reward:.1f}")

        elif _exec_kind == "ER":
            # ── Early Red: terminate bus phase early (bus has already cleared) ──
            if current_phase == self.BusPhase:
                _min_er = float(globals().get('MIN_ER_TRUNCATION_S', 3.0))
                best_ge = max(best_ge, _min_er)
                _ps_er = ECIGetStartingTimePhase(self.node_id)
                _pd_er = GetPhaseDuration(self.node_id, current_phase, timeSta)
                _remain_er = max(0.0, _pd_er - (time - _ps_er))
                _new_dur_er = max(5.0, _pd_er - best_ge)
                ECIChangeTimingPhase(self.node_id, current_phase, _new_dur_er, timeSta)
                self.TSPStrategy  = 4   # ER
                self.flag         = 4
                self.TSPActiveTime = time + best_ge + float(globals().get('TSP_POST_GRANT_LOCK_S', 5.0))
                self._tsp_cycle_grant_until = time + self.cycle_len_s
                self.last_tsp_action_time   = time
                self._ge_debt_s = -best_ge   # negative debt = recovered time
                self.highlight_bus(veh_id)
                self.stats.record_tsp_event(self.id, 'early_red')
                if veh_id and veh_id > 0:
                    _acquire_focus(veh_id, self.id, time)
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        self._corridor_coord.notify_bus_granted(
                            veh_id, self.id, time, None)
                    except Exception:
                        pass
                log_to_file(
                    f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"eta={_eta_disp} DECISION={best_action} ER={best_ge:.1f}s "
                    f"R={best_reward:.1f}")
            else:
                # ── Wrong-phase Early Red (mode-generated, e.g. ZIG/BXT):
                # terminate the current NON-bus phase early so the bus phase
                # starts sooner.  Mechanically identical to wrong-phase GR.
                _min_er = float(globals().get('MIN_ER_TRUNCATION_S', 3.0))
                best_ge = max(best_ge, _min_er)
                _ps_er2 = ECIGetStartingTimePhase(self.node_id)
                _pd_er2 = GetPhaseDuration(self.node_id, current_phase, timeSta)
                _new_dur_er2 = max(5.0, _pd_er2 - best_ge)
                ECIChangeTimingPhase(self.node_id, current_phase, _new_dur_er2, timeSta)
                self.TSPStrategy  = 4   # ER
                self.flag         = 4
                self.TSPActiveTime = time + best_ge + float(globals().get('TSP_POST_GRANT_LOCK_S', 5.0))
                self._tsp_cycle_grant_until = time + self.cycle_len_s
                self.last_tsp_action_time   = time
                self._ge_debt_s = best_ge
                self.highlight_bus(veh_id)
                self.stats.record_tsp_event(self.id, 'early_red')
                if veh_id and veh_id > 0:
                    _acquire_focus(veh_id, self.id, time)
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        self._corridor_coord.notify_bus_granted(
                            veh_id, self.id, time, None)
                    except Exception:
                        pass
                log_to_file(
                    f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"eta={_eta_disp} DECISION={best_action} ER-wrong-phase "
                    f"cut={best_ge:.1f}s R={best_reward:.1f}")

        elif _exec_kind == "OC":
            # ── Offset Correction: shift phase timing for green-wave alignment ──
            _oc_ps = ECIGetStartingTimePhase(self.node_id)
            _oc_pd = GetPhaseDuration(self.node_id, current_phase, timeSta)
            _oc_sign = +1.0 if "OC_+" in best_action or "+" in best_action else -1.0
            _oc_new = max(5.0, min(120.0, _oc_pd + _oc_sign * best_ge))
            # Apply only if shortening (negative OC) actually meaningfully changes the phase
            if abs(_oc_new - _oc_pd) > 0.5:
                ECIChangeTimingPhase(self.node_id, current_phase, _oc_new, timeSta)
            self.TSPStrategy  = 5   # OC
            self.flag         = 5
            self.TSPActiveTime = time + best_ge + float(globals().get('TSP_POST_GRANT_LOCK_S', 5.0))
            self._tsp_cycle_grant_until = time + self.cycle_len_s
            self.last_tsp_action_time   = time
            self._ge_debt_s = 0.0  # OC is cycle-neutral — phase adjusts within cycle
            self.highlight_bus(veh_id)
            self.stats.record_tsp_event(self.id, 'offset_correction')
            if veh_id and veh_id > 0:
                _acquire_focus(veh_id, self.id, time)
            if self._corridor_coord is not None and COORDINATED_TSP:
                try:
                    self._corridor_coord.notify_bus_granted(
                        veh_id, self.id, time, None)
                except Exception:
                    pass
            log_to_file(
                f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                f"eta={_eta_disp} DECISION={best_action} OC={best_ge:.1f}s "
                f"R={best_reward:.1f}")

        elif _exec_kind == "OPP":
            # ── Optimised Plan Push: corridor stagger realignment ──────────
            # Same write primitive as OC (shift the running phase's duration, so
            # the bus-green START moves), but the shift comes from the joint
            # (sequence, offset) optimum instead of one bus's arrival. No green
            # duration is redistributed, so this is cycle-neutral by construction:
            # the bus phase and every cross phase keep the seconds they had.
            _opp_ps = ECIGetStartingTimePhase(self.node_id)
            _opp_pd = GetPhaseDuration(self.node_id, current_phase, timeSta)
            _opp_sign = +1.0 if str(best_action).startswith("OPP_+") else -1.0
            _opp_delta = _opp_sign * abs(float(best_ge))
            _opp_new = max(5.0, min(120.0, _opp_pd + _opp_delta))
            if abs(_opp_new - _opp_pd) > 0.5:
                ECIChangeTimingPhase(self.node_id, current_phase, _opp_new, timeSta)
                # Publish the post-change plan so neighbours coordinate against
                # the new stagger on this tick instead of polling ECI.
                try:
                    self._broadcast_timing_change(
                        'offset_plan_push', abs(_opp_new - _opp_pd), time,
                        f"opt_offset target={(self._opt_offset_targets() or {}).get(int(getattr(self, 'id', 0) or 0), 0.0):.1f}",
                        current_phase, timeSta, live_read=False)
                except Exception:
                    pass
                self.stats.record_tsp_event(self.id, 'offset_plan_push')
            self.TSPStrategy  = 5   # same family as OC (phase-boundary shift)
            self.flag         = 5
            self.TSPActiveTime = time + abs(_opp_delta) + float(
                globals().get('TSP_POST_GRANT_LOCK_S', 5.0))
            self._tsp_cycle_grant_until = time + self.cycle_len_s
            self.last_tsp_action_time   = time
            self._ge_debt_s = 0.0  # cycle-neutral: start moves, lengths do not
            self.highlight_bus(veh_id)
            if veh_id and veh_id > 0:
                _acquire_focus(veh_id, self.id, time)
            log_to_file(
                f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                f"DECISION={best_action} OPP={_opp_delta:+.1f}s "
                f"R={best_reward:.1f}")

        elif _exec_kind == "VP":
            # ── Phase Skipping: skip current phase, advance directly to bus phase ──
            if current_phase != self.BusPhase:
                self.previous_phase = current_phase
                ECIChangeDirectPhase(self.id, self.BusPhase, timeSta, time, acycle, 0)
                ECIChangeTimingPhase(self.id, self.BusPhase, best_ge, timeSta)
                self.BusPhaseEndTime = time + best_ge
                self.TSPStrategy  = 6   # VP
                self.flag         = 6
                self._ins_bus_phase_seen = False
                self._ins_grant_time = time
                self.TSPActiveTime = time + best_ge + float(globals().get('TSP_POST_GRANT_LOCK_S', 5.0))
                self._tsp_cycle_grant_until = time + self.cycle_len_s
                self.last_tsp_action_time   = time
                self._ge_debt_s = best_ge
                self.highlight_bus(veh_id)
                self.stats.record_tsp_event(self.id, 'phase_skip')
                if veh_id and veh_id > 0:
                    _acquire_focus(veh_id, self.id, time)
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        self._corridor_coord.notify_bus_granted(
                            veh_id, self.id, time, None)
                    except Exception:
                        pass
                log_to_file(
                    f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"eta={_eta_disp} DECISION={best_action} VP={best_ge:.1f}s "
                    f"R={best_reward:.1f}")

        elif _exec_kind == "PT":
            # ── Phase Rotation: skip N phases, advance to chosen next phase ──
            _pt_skip = safe_float(best_action.split("_", 1)[1], 0.0)
            if _pt_skip > 0 and current_phase != self.BusPhase:
                _ci_pt = self.phase_list.index(current_phase) if current_phase in self.phase_list else 0
                _n_pt  = len(self.phase_list)
                # The target phase is (current + _pt_skip + 1) to skip _pt_skip phases
                # If we skip far enough to reach bus phase, go directly to it
                _target_ph_idx = (_ci_pt + int(_pt_skip) + 1) % _n_pt
                _target_ph = self.phase_list[_target_ph_idx]
                # If the skipped phases include the bus phase, set flag=2 (INS-style)
                # Otherwise it's a regular phase rotation
                _reaches_bus = any(
                    self.phase_list[(_ci_pt + k + 1) % _n_pt] == self.BusPhase
                    for k in range(int(_pt_skip)))
                self.previous_phase = current_phase
                if _reaches_bus:
                    ECIChangeTimingPhase(self.id, self.BusPhase, best_ge, timeSta)
                    self.BusPhaseEndTime = time + best_ge
                    self.flag = 2  # use INS flag (phase restored after bus phase ends)
                    self._ins_bus_phase_seen = False
                    self._ins_grant_time = time
                else:
                    self.flag = 7   # PT flag
                ECIChangeDirectPhase(self.id, _target_ph, timeSta, time, acycle, 0)
                self.TSPStrategy  = 7   # PT
                self.TSPActiveTime = time + best_ge + float(globals().get('TSP_POST_GRANT_LOCK_S', 5.0))
                self._tsp_cycle_grant_until = time + self.cycle_len_s
                self.last_tsp_action_time   = time
                self._ge_debt_s = best_ge
                self.highlight_bus(veh_id)
                self.stats.record_tsp_event(self.id, 'phase_rotation')
                if veh_id and veh_id > 0:
                    _acquire_focus(veh_id, self.id, time)
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        self._corridor_coord.notify_bus_granted(
                            veh_id, self.id, time, None)
                    except Exception:
                        pass
                log_to_file(
                    f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"eta={_eta_disp} DECISION={best_action} PT={best_ge:.1f}s "
                    f"skip={_pt_skip:.0f} target={_target_ph} reaches_bus={_reaches_bus} "
                    f"R={best_reward:.1f}")

        else:
            # A candidate label that the executor cannot map — this must never
            # be silent: a chosen action that does not fire skews every
            # delay/benefit statistic recorded for this junction.
            log_to_file(
                f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                f"UNHANDLED action token '{best_action}' "
                f"(exec_kind={_exec_kind}) — no action executed", force=True)

    def _reward_get_recoverable(self, current_phase, timeSta):
        """Compute recoverable headroom from upcoming phases (same as HARMONY cap logic)."""
        _min_floor = float(self.config.get('MinGreen', 5.0))
        _max_trim_frac = 0.50
        _phase_list = getattr(self, 'phase_list', [])
        if not _phase_list or current_phase not in _phase_list:
            return 999.0
        _ci = _phase_list.index(current_phase)
        _n = len(_phase_list)
        _upcoming = [_phase_list[(_ci + _k) % _n] for _k in range(1, _n)]
        _upcoming = [p for p in _upcoming if p != self.BusPhase and p != current_phase]
        _recoverable = 0.0
        for _ph in _upcoming:
            _nom = self._nominal_phase_durations.get(_ph)
            if _nom is None:
                try:
                    _nom = GetPhaseDuration(self.node_id, _ph, timeSta)
                except Exception:
                    _nom = 15.0
                if not _nom or _nom <= 0:
                    _nom = 15.0
            _nom = max(float(_nom), _min_floor)
            _hr = max(0.0, _nom - _min_floor)
            _hr = min(_hr, _nom * _max_trim_frac)
            _recoverable += _hr
        return _recoverable

    def _solve_recovery_plan(self, debt, current_phase, timeSta):
        """Recovered-cycle-plan heuristic (the signal-transition / "recovery"
        problem). After an intervention leaves the junction's cycle boundary
        `debt` seconds off its coordinated offset, solve the SMALLEST-horizon plan
        that returns the junction to coordination without violating min-green.

        Per cycle the recoverable slack is
            S = sum_p min(g0_p - Gmin, tau * g0_p)   over upcoming cross phases,
        where tau = RECOVERY_TRANSITION_RATE bounds how hard any single phase is
        trimmed in one cycle (a smoothness / transition-shock limit). Recovering
        S per cycle, the plan needs
            K* = ceil(debt / S)                      cycles,
        capped at RECOVERY_MAX_CYCLES. Within a cycle the trim is distributed
        proportional to each phase's slack (minimax-fair: equal fractional trim,
        so no phase is starved more than another). Returns
        (K_needed, per_cycle_trim_s, feasible) where feasible is False when even
        K_max cycles cannot absorb the debt (caller should not have granted it --
        that is the recoverability gate's job, Eq. online_recover).
        """
        _S = float(self._reward_get_recoverable(current_phase, timeSta))
        _kmax = max(1, int(globals().get('RECOVERY_MAX_CYCLES', 1)))
        if debt <= 0.5:
            return (0, 0.0, True)
        if _S <= 0.5:
            return (_kmax, 0.0, False)          # saturated: nothing to trim
        import math as _math
        _k = int(_math.ceil(float(debt) / _S))
        _feasible = (_k <= _kmax)
        _k = min(_k, _kmax)
        # even split of the debt over the plan horizon (bounded by per-cycle S)
        _per_cycle = min(_S, float(debt) / max(_k, 1))
        return (_k, _per_cycle, _feasible)

    # ── Progression (Purdue Coordination Diagram) state, IN the controller ─────
    def _progression_pog(self):
        """Live arrivals-on-green fraction (POG in [0,1]) for the main coordinated
        movement at this junction -- the controller's running Purdue-diagram
        health. Returns 1.0 (assume coordinated / protect) until enough samples."""
        _p = getattr(self, '_pog_ewma', None)
        return float(_p) if _p is not None else 1.0

    def _sample_progression(self, current_phase):
        """Sample arrivals-on-green at a decision event: the main-approach platoon
        (upstream flow, UpFlowList row 0) is 'on green' when the coordinated bus/
        main phase is live. Maintains an EWMA POG per junction so the progression
        gate knows how coordinated the movement actually is."""
        try:
            _q = np.asarray(getattr(self, 'UpFlowList', np.zeros((1, 1))), dtype=float)
            _row = _q[0].ravel() if (_q.ndim >= 2 and _q.shape[0] > 0) else np.zeros(1)
            _main_q = float(np.mean(_row[_row > 0])) if np.any(_row > 0) else 0.0
        except Exception:
            _main_q = 0.0
        if _main_q <= 0.0:
            return                      # no main arrivals to classify
        _on = 1.0 if int(current_phase) == int(getattr(self, 'BusPhase', -1)) else 0.0
        _w = 0.08
        _prev = getattr(self, '_pog_ewma', None)
        self._pog_ewma = _on if _prev is None else (1.0 - _w) * _prev + _w * _on

    def _coord_degree(self):
        """Corridor degree for THIS junction: number of coordinated neighbours
        on its route (1 for an end, 2 for a middle). 0 when no corridor info.
        Middle junctions are harder -- their offset must satisfy both bands --
        so actions there should be priced against both directions."""
        try:
            _cc = getattr(self, '_corridor_coord', None)
            if _cc is None:
                return 0
            _ids = [int(j) for j in _cc.inter_ids
                    if j in getattr(_cc, 'corridor_pos', {})]
            _me = int(self.id)
            if _me not in _ids:
                return 0
            _ids.sort(key=lambda j: float(_cc.corridor_pos.get(j, 0.0)))
            _i = _ids.index(_me)
            _deg = 0
            if _i > 0:
                _deg += 1
            if _i < len(_ids) - 1:
                _deg += 1
            return max(_deg, 1)
        except Exception:
            return 1

    def _progression_cost(self, shift_s):
        """Estimated pax*s of the MAIN coordinated platoon displaced from green by
        an offset shift of `shift_s`, WEIGHTED by the live POG so the penalty is
        large only where the green wave is actually working (high POG) and small
        where it is already broken. This is the controller's online reading of the
        Purdue Coordination Diagram: keep the platoon on green.
        With PROGRESSION_DEGREE_WEIGHT, the cost scales by the junction's
        corridor degree (middle junctions displace BOTH directions, ends one)."""
        _s = abs(float(shift_s))
        if _s < 1.0:
            return 0.0
        try:
            _q = np.asarray(getattr(self, 'UpFlowList', np.zeros((1, 1))), dtype=float)
            _row = _q[0].ravel() if (_q.ndim >= 2 and _q.shape[0] > 0) else np.zeros(1)
            _main_q = (float(np.mean(_row[_row > 0])) / 3600.0) if np.any(_row > 0) else 0.0
        except Exception:
            _main_q = 0.0
        if _main_q <= 0.0:
            return 0.0
        _occ = max(float(getattr(self, 'CarOcc', 1.6) if hasattr(self, 'CarOcc') else 1.6), 1.0)
        _cyc = float(self._signal_cycle_s()) if hasattr(self, '_signal_cycle_s') else 135.0
        _s = min(_s, _cyc)
        # ── BIDIRECTIONAL progression (2026-09-30) ─────────────────────────
        # An offset shift displaces the coordinated platoon in BOTH main
        # directions, not just the served one. The served band is UpFlowList row 0
        # (_main_q). Price the OPPOSITE band by its OWN measured flow (main approach
        # sections NOT served by the bus phase) rather than a x2 degree proxy, so an
        # ASYMMETRIC corridor (Logan's two mains differ ~3x) is priced correctly.
        # Falls back to the degree-weight proxy when the opposite flow can't be read.
        _q_total = _main_q
        _bidir = bool(getattr(_spm, 'PROGRESSION_BIDIRECTIONAL', True))
        _opp_ok = False
        if _bidir:
            try:
                _served = set(int(x) for x in (self._phase_origin_sections().get(
                    int(getattr(self, 'BusPhase', -1)), set()) or []))
                _opp_q = 0.0
                for _sec in (getattr(self, 'incoming_sections', []) or []):
                    if int(_sec) not in _served:
                        _opp_q += max(0.0, float(
                            self._measured_section_flow_vph(int(_sec)))) / 3600.0
                if _opp_q > 0.0:
                    _q_total = _main_q + _opp_q      # both bands, each by own flow
                    _opp_ok = True
            except Exception:
                _opp_ok = False
        # displaced platoon (veh) ~ q * shift; each faces ~shift more red.
        _loss = self._progression_pog() * _q_total * _s * _s * _occ
        # Degree-weight proxy: only when we could NOT price the opposite band
        # explicitly (bidirectional off, or no opposite flow) -- middle junctions
        # displace both bands, so scale by corridor degree (1/2).
        if (not _opp_ok) and bool(getattr(_spm, 'PROGRESSION_DEGREE_WEIGHT', True)):
            try:
                _loss *= max(1.0, float(self._coord_degree() or 1.0))
            except Exception:
                pass
        return _loss

    def run_normal(self, time, timeSta, acycle):
        """Passive baseline — data collection only, no signal changes.

        Still records bus detections (mark_detection_point + stats) so that
        NORMAL mode produces detection counts comparable to HARMONY, and the
        batch results show how many buses were 'seen' without TSP action.
        """
        # OFFLINE WARM-START also applies under NORMAL (optimized base plan with NO
        # online correction) so its standalone effect can be isolated. Runs once.
        if bool(globals().get('PLAN_OPTIMIZE', False)):
            try:
                self._optimize_startup_plan(timeSta)
                self._reassert_plan(time, timeSta)   # hold the plan vs any revert
            except Exception:
                pass
        busTypePos = self.bus_type_pos

        # Primary: physical detector crossing this cycle
        busCallActive = any(
            AKIDetGetCounterCyclebyId(det, busTypePos) > 0
            for det in self.BusDet)
        # Fallback: position-based scan (detect_bus already ran this step)
        if not busCallActive:
            busCallActive = any(
                self.BusPresence[0][i] > 0
                for i in range(len(self.BusDet)))

        # ── Passive detection recording ───────────────────────────────────────
        # Track which detector slots are newly presenting a bus this step.
        # Use a set on self to avoid counting the same bus twice per approach.
        if not hasattr(self, '_normal_det_active'):
            self._normal_det_active = set()   # slots currently presenting

        _newly_detected = False
        for i, det in enumerate(self.BusDet):
            _presence = self.BusPresence[0][i] if i < len(self.BusPresence[0]) else 0
            _counter  = AKIDetGetCounterCyclebyId(det, busTypePos)
            _active   = (_presence > 0) or (_counter > 0)
            if _active and i not in self._normal_det_active:
                # New bus arrival at this detector slot
                self._normal_det_active.add(i)
                _newly_detected = True
                _vid = int(self.last_detected_bus_id) if hasattr(self, 'last_detected_bus_id') else -1
                _mark_detection_point(
                    junction_id=self.id,
                    veh_id=_vid,
                    x=0.0, y=0.0,
                    sim_time=time,
                    tier="NORMAL-detect",
                )
                self._record_detection(time)
                # Check if the bus phase is currently green (natural green)
                _is_natural = False
                try:
                    _cur_ph = ECIGetCurrentPhase(self.id)
                    if _cur_ph == self.BusPhase:
                        _is_natural = True
                except Exception:
                    pass
                if _is_natural:
                    self.stats.record_tsp_skip(self.id, 'natural_green')
                else:
                    self.stats.record_tsp_skip(self.id, 'no_action')
                try:
                    self.stats.record_pt_bus_detection(self.id, _vid, time)
                except Exception:
                    pass
            elif not _active and i in self._normal_det_active:
                self._normal_det_active.discard(i)

        # Periodic diagnostic — log det counters + BusPresence every 5 minutes
        _diag_t = int(time) // 300
        if _diag_t != getattr(self, '_run_normal_diag_t', -1):
            self._run_normal_diag_t = _diag_t
            counters = [AKIDetGetCounterCyclebyId(d, busTypePos) for d in self.BusDet]
            presence = self.BusPresence[0].tolist()
            log_to_file(
                f"[NORMAL DIAG] t={time:.0f}s inter={self.id} "
                f"det_counters={counters} BusPresence={presence} "
                f"busCallActive={busCallActive} newly_det={_newly_detected}")

    def _apply_cycle_recovery(self, timeSta: float):
        """
        Proportionally shorten the remaining phases in the current cycle to
        recover the time stolen by a green extension.

        Algorithm
        ---------
        1. Build the ordered list of phases AFTER the current one in this cycle.
        2. For each candidate phase (skip BusPhase — already served):
               nominal  = ECIGetDurationsPhase(phase)
               min_dur  = config MinGreen or 5 s hard floor
               headroom = nominal - min_dur   (how much can be trimmed)
               fraction = headroom / total_headroom_remaining
               trim     = min(fraction * debt, headroom)
               new_dur  = nominal - trim
               ECIChangeTimingPhase(phase, new_dur, ...)
        3. Accumulate actual trimmed; update _ge_debt_s with any residual
           (can't always recover 100% if minimums bind).

        Both GE (flag==1) and phase insertion (flag==2) trigger this.
        For insertion, _ge_debt_s is set to opt_BP at insertion time so the
        cost is spread over remaining phases when the insertion ends.
        """
        if self._ge_debt_s <= 0.5:
            self._ge_debt_s = 0.0
            return

        current_phase = ECIGetCurrentPhase(self.node_id)
        phase_list    = getattr(self, 'phase_list', [])
        if not phase_list or current_phase not in phase_list:
            self._ge_debt_s = 0.0
            return

        # Build ordered list of phases still to run this cycle (after current)
        ci = phase_list.index(current_phase)
        n  = len(phase_list)
        upcoming = [phase_list[(ci + k) % n] for k in range(1, n)]
        # Exclude BusPhase (just completed) and current phase
        upcoming = [p for p in upcoming if p != self.BusPhase and p != current_phase]

        if not upcoming:
            self._ge_debt_s = 0.0
            return

        # Gather nominals (always from stored originals, never from a trimmed plan)
        # and minimum floors.
        min_floor   = float(self.config.get('MinGreen', 5.0))
        # Safety cap: never trim more than 50 % of any single phase's nominal.
        max_trim_frac = 0.50
        nominals  = {}
        headrooms = {}
        for ph in upcoming:
            # Prefer the stored nominal from before any trimming happened.
            nom = self._nominal_phase_durations.get(ph)
            if nom is None:
                try:
                    nom = GetPhaseDuration(self.node_id, ph, timeSta)
                except Exception:
                    nom = 15.0
                if not nom or nom <= 0:
                    nom = 15.0
                # Lock in the original value so subsequent GEs don't compound.
                self._nominal_phase_durations[ph] = float(nom)
            nom = max(float(nom), min_floor)
            hr  = max(0.0, nom - min_floor)
            # Apply 50 % cap
            hr  = min(hr, nom * max_trim_frac)
            nominals[ph]  = nom
            headrooms[ph] = hr

        total_headroom = sum(headrooms.values())
        if total_headroom < 0.5:
            # Phases already at minimum — can't recover
            self._ge_debt_s = 0.0
            return

        debt          = self._ge_debt_s
        total_trimmed = 0.0

        for ph in upcoming:
            hr = headrooms[ph]
            if hr <= 0.0 or debt <= 0.0:
                continue
            # Proportional share of the debt for this phase
            trim    = min(hr, debt * (hr / total_headroom))
            new_dur = nominals[ph] - trim
            try:
                ECIChangeTimingPhase(self.node_id, ph, new_dur, timeSta)
            except Exception:
                continue
            total_trimmed += trim
            debt          -= trim
            # Schedule restoration to nominal at the start of the next cycle.
            # This prevents permanent drift: trimmed durations only apply for
            # the recovery cycle, not all subsequent cycles.
            self._phases_to_restore[ph] = nominals[ph]

        self._ge_debt_s = max(0.0, debt)   # residual (if minimums bound)

        # Back-fill recovery amount into the most recent _ge_events entry
        # for this intersection so the schedule-recovery plot can show it.
        for _i in range(len(_ge_events) - 1, -1, -1):
            if _ge_events[_i][1] == self.id:
                _t, _iid, _ge, _rec = _ge_events[_i]
                _ge_events[_i] = (_t, _iid, _ge, _rec + total_trimmed)
                break

        if LOG_HARMONY:
            _vprint(
                f"[HARMONY] Cycle recovery inter={self.id} "
                f"GE={self._ge_opt_GE:.1f}s trimmed={total_trimmed:.1f}s "
                f"residual={self._ge_debt_s:.1f}s phases={upcoming} "
                f"restore_scheduled={list(self._phases_to_restore.keys())}"
            )
        else:
            log_to_file(
                f"[HARMONY] Cycle recovery inter={self.id} "
                f"GE={self._ge_opt_GE:.1f}s trimmed={total_trimmed:.1f}s "
                f"residual={self._ge_debt_s:.1f}s phases={upcoming}"
            )
        # Recovery rewrote upcoming phases: broadcast so neighbours re-read.
        # ECI already applied -> live_read publishes re-read post-change truth.
        if total_trimmed > 0.5:
            try:
                try:
                    _bt = float(AKIGetCurrentSimulationTime())
                except Exception:
                    _bt = -1.0
                self._broadcast_timing_change("RECOVER_TRIM", total_trimmed,
                                              _bt, "recovery",
                                              timeSta=timeSta, live_read=True)
            except Exception:
                pass
            try:
                self.stats.record_tsp_event(self.id, 'retiming')
            except Exception:
                pass

    def restore_phase_if_needed(self, time, timeSta, acycle):
        global _focus_bus_id, _focus_jct_id, _focus_passed_jcts
        current_phase = ECIGetCurrentPhase(self.node_id)

        # ── Safety restore: force nominal plan at cycle boundary ────────────
        # If a prior recovery/update path missed restoration bookkeeping,
        # this guard reasserts nominal durations when BusPhase starts.
        # It prevents permanent drift of phase durations across cycles.
        if current_phase == self.BusPhase:
            if not getattr(self, '_nominal_safety_restore_fired', False):
                _n_safety = 0
                for _ph, _nom in (self._nominal_phase_durations or {}).items():
                    try:
                        _cur = float(GetPhaseDuration(self.node_id, _ph, timeSta) or 0.0)
                    except Exception:
                        _cur = float(_nom)
                    if abs(_cur - float(_nom)) > 0.5:
                        try:
                            ECIChangeTimingPhase(self.node_id, _ph, float(_nom), timeSta)
                            _n_safety += 1
                        except Exception:
                            pass
                if _n_safety > 0:
                    log_to_file(
                        f"[HARMONY] Nominal safety restore inter={self.id} restored {_n_safety} phase durations"
                    )
                    # Restored durations rewrite the plan: broadcast it.
                    # ECI already applied -> live_read publishes re-read truth.
                    try:
                        self._broadcast_timing_change(
                            "RESTORE", float(_n_safety), float(time),
                            "safety-restore", timeSta=timeSta, live_read=True)
                    except Exception:
                        pass
                    try:
                        self.stats.record_tsp_event(self.id, 'retiming')
                    except Exception:
                        pass
                self._nominal_safety_restore_fired = True
        else:
            self._nominal_safety_restore_fired = False

        # ── Recovered-cycle-plan: continue multi-cycle recovery (opt-in) ──────
        # Default RECOVERY_MAX_CYCLES=1 => this block never runs and residual debt
        # is handled exactly as before. When K>1, and a residual offset debt
        # remains after the safety-restore-to-nominal above, apply the NEXT
        # cycle's trim (proportional-to-slack, min-green bounded) so the junction
        # walks its offset back to coordination over <=K cycles instead of
        # orphaning the debt (permanent drift) or snapping. Gated + bounded so a
        # bug cannot trim forever.
        _rmax = int(globals().get('RECOVERY_MAX_CYCLES', 1))
        if current_phase == self.BusPhase and _rmax > 1:
            if (float(getattr(self, '_ge_debt_s', 0.0)) > 0.5
                    and not getattr(self, '_recovery_continued_this_cycle', False)):
                _used = int(getattr(self, '_recovery_cycles_used', 0))
                if _used < _rmax:
                    self._recovery_cycles_used = _used + 1
                    self._recovery_continued_this_cycle = True
                    log_to_file(
                        f"[RECOVER_PLAN] inter={self.id} t={time:.1f} continue "
                        f"recovery cycle {self._recovery_cycles_used}/{_rmax} "
                        f"residual_debt={self._ge_debt_s:.1f}s")
                    try:
                        self._apply_cycle_recovery(timeSta)
                    except Exception as _rpe:
                        log_to_file(f"[RECOVER_PLAN] inter={self.id} error {_rpe!r}")
                        self._ge_debt_s = 0.0
                else:
                    # horizon exhausted (should not happen when gated) -- release
                    self._ge_debt_s = 0.0
                    self._recovery_cycles_used = 0
            elif float(getattr(self, '_ge_debt_s', 0.0)) <= 0.5:
                self._recovery_cycles_used = 0
        elif current_phase != self.BusPhase:
            self._recovery_continued_this_cycle = False

        # ── Restore phases trimmed by cycle recovery in the PREVIOUS cycle ───
        # When BusPhase next becomes current (start of a new cycle) we reset
        # any phases that were shortened for cycle recovery back to their
        # original nominal durations so trimming doesn't accumulate over time.
        if self._phases_to_restore:
            if current_phase == self.BusPhase:
                if not self._restore_fired_this_cycle:
                    _n_restored = 0
                    for _ph, _nom in self._phases_to_restore.items():
                        try:
                            ECIChangeTimingPhase(self.node_id, _ph, _nom, timeSta)
                            _n_restored += 1
                        except Exception:
                            pass
                    if _n_restored:
                        log_to_file(
                            f"[HARMONY] Nominal restore inter={self.id} "
                            f"restored {_n_restored} phases to plan durations"
                        )
                    self._phases_to_restore.clear()
                    self._restore_fired_this_cycle = True
            else:
                self._restore_fired_this_cycle = False

        # ── Flag 1: GREEN EXTENSION ─────────────────────────────────────────
        # Primary end: Aimsun naturally advanced past BusPhase (phase changed).
        # Fallback:    TimeToTerminateBusPhase elapsed (safety timer).
        if self.flag == 1:
            phase_ended = (current_phase != self.BusPhase)
            timed_out   = (time > self.TimeToTerminateBusPhase)
            if phase_ended or timed_out:
                ECIChangeTimingPhase(
                    self.id, self.BusPhase, self.BusPhaseDuration, timeSta)
                if timed_out and not phase_ended:
                    ECIEnableEventsActivatingPhase(
                        self.id, self.BusPhase + 1, 0.0, time)
                self.flag        = 0
                self.TSPStrategy = 0
                self.reset_bus_color(self.last_detected_bus_id)
                # ── Release global bus focus (only when wave truly idle) ───
                _defer_focus_release = False
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        _same_focus_bus = (
                            _focus_bus_id > 0
                            and int(self.last_detected_bus_id or -1) == int(_focus_bus_id)
                        )
                        _coord_has_pending = (
                            bool(getattr(self._corridor_coord, '_pre_requests', {}))
                            or bool(getattr(self._corridor_coord, '_wave_active', False))
                        )
                        _defer_focus_release = _same_focus_bus and _coord_has_pending
                    except Exception:
                        _defer_focus_release = False
                if _defer_focus_release:
                    if _focus_jct_id >= 0 and _focus_jct_id != self.id:
                        _focus_passed_jcts.add(_focus_jct_id)
                    _focus_jct_id = self.id
                    if LOG_HARMONY:
                        _vprint(
                            f"[BUS_FOCUS] t={time:.1f} inter={self.id} "
                            f"defer release after GE (downstream wave pending)")
                else:
                    _release_focus(time, "harmony_ge_done")
                # ── Cycle recovery: spread the GE debt across remaining phases
                self._apply_cycle_recovery(timeSta)
                if LOG_HARMONY:
                    log_to_file(
                        f"[HARMONY] GE ended | t={time:.1f}s "
                        f"reason={'phase_change' if phase_ended else 'timeout'} "
                        f"inter={self.id}")

        # ── Flag 2: PHASE INSERTION ─────────────────────────────────────────
        # Primary end: BusPhase naturally ended (Aimsun advanced past it).
        # Fallback:    BusPhaseEndTime elapsed.
        # In both cases: restore interrupted phase explicitly — Aimsun does
        # NOT return to the interrupted phase automatically after insertion.
        if self.flag == 2:
            # The direct-phase change takes >= 1 step (and usually an
            # interphase) before ECIGetCurrentPhase reports BusPhase.
            # Without this guard every insertion was cancelled one step
            # after grant (held=0.8s in the [BUS_FOCUS] release log) and the
            # bus never received its inserted green.
            if current_phase == self.BusPhase and not getattr(
                    self, '_ins_bus_phase_seen', False):
                self._ins_bus_phase_seen = True
                # Re-anchor the hold window to when the green actually began
                _grant_t = getattr(self, '_ins_grant_time', None)
                if _grant_t is not None:
                    self.BusPhaseEndTime += max(0.0, time - float(_grant_t))
            _ins_seen = getattr(self, '_ins_bus_phase_seen', False)
            phase_ended = _ins_seen and (current_phase != self.BusPhase)
            # If the bus phase never appears, the timeout (plus a grace for
            # the interphase transition) still ends the insertion.
            timed_out = time > self.BusPhaseEndTime + (0.0 if _ins_seen else 10.0)
            if phase_ended or timed_out:
                if not _ins_seen:
                    log_to_file(
                        f"[HARMONY] INS ended inter={self.id} t={time:.1f} but "
                        f"bus phase NEVER became active — direct phase change "
                        f"ineffective? (cur={current_phase} bus={self.BusPhase})",
                        )
                self._ins_bus_phase_seen = False
                self._ins_grant_time = None
                ECIChangeTimingPhase(
                    self.id, self.BusPhase, self.BusPhaseDuration, timeSta)
                if (self.previous_phase
                        and self.previous_phase > 0
                        and current_phase != self.previous_phase):
                    ECIChangeDirectPhase(
                        self.id, self.previous_phase,
                        timeSta, time, acycle, 0)
                self.flag        = 0
                self.TSPStrategy = 0
                _defer_focus_release = False
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        _same_focus_bus = (
                            _focus_bus_id > 0
                            and int(self.last_detected_bus_id or -1) == int(_focus_bus_id)
                        )
                        _coord_has_pending = (
                            bool(getattr(self._corridor_coord, '_pre_requests', {}))
                            or bool(getattr(self._corridor_coord, '_wave_active', False))
                        )
                        _defer_focus_release = _same_focus_bus and _coord_has_pending
                    except Exception:
                        _defer_focus_release = False
                if _defer_focus_release:
                    if _focus_jct_id >= 0 and _focus_jct_id != self.id:
                        _focus_passed_jcts.add(_focus_jct_id)
                    _focus_jct_id = self.id
                    if LOG_HARMONY:
                        _vprint(
                            f"[BUS_FOCUS] t={time:.1f} inter={self.id} "
                            f"defer release after INS (downstream wave pending)")
                else:
                    _release_focus(time, "harmony_ins_done")
                # ── Cycle recovery: recover the insertion's time cost from
                # the remaining phases this cycle (same as GE recovery).
                self._apply_cycle_recovery(timeSta)
                if LOG_HARMONY:
                    log_to_file(
                        f"[HARMONY] Insertion ended | t={time:.1f}s "
                        f"reason={'phase_change' if phase_ended else 'timeout'} "
                        f"restored_phase={self.previous_phase} inter={self.id}")

        # ── Flag 3: GREEN REALLOCATION ──────────────────────────────────────
        # A non-bus phase was shortened to advance bus green. End condition:
        # the shortened phase naturally ended (phase changed) or TSPActiveTime
        # elapsed. Restore the shortened phase duration on cleanup.
        if self.flag == 3:
            _gr_timed_out = (time > self.TSPActiveTime)
            if current_phase != self.BusPhase or _gr_timed_out:
                # Restore the shortened non-bus phase duration to nominal
                try:
                    _nom = self._nominal_phase_durations.get(current_phase)
                    if _nom is None:
                        _nom = GetPhaseDuration(self.node_id, current_phase, timeSta)
                    if _nom and _nom > 0:
                        ECIChangeTimingPhase(self.id, current_phase, float(_nom), timeSta)
                except Exception:
                    pass
                self.flag        = 0
                self.TSPStrategy = 0
                self.reset_bus_color(self.last_detected_bus_id)
                _release_focus(time, "gr_done")
                self._apply_cycle_recovery(timeSta)
                if LOG_HARMONY:
                    log_to_file(
                        f"[HARMONY] GR ended | t={time:.1f}s "
                        f"reason={'timeout' if _gr_timed_out else 'phase_change'} "
                        f"inter={self.id}")

        # ── Flag 4: EARLY RED ───────────────────────────────────────────────
        # Bus phase was terminated early. End condition: bus phase naturally
        # ended (Aimsun advanced past it) or TSPActiveTime elapsed.
        if self.flag == 4:
            _er_phase_ended = (current_phase != self.BusPhase)
            _er_timed_out   = (time > self.TSPActiveTime)
            if _er_phase_ended or _er_timed_out:
                # Restore bus phase duration to nominal
                ECIChangeTimingPhase(
                    self.id, self.BusPhase, self.BusPhaseDuration, timeSta)
                self.flag        = 0
                self.TSPStrategy = 0
                self.reset_bus_color(self.last_detected_bus_id)
                _release_focus(time, "er_done")
                if LOG_HARMONY:
                    log_to_file(
                        f"[HARMONY] ER ended | t={time:.1f}s "
                        f"reason={'phase_change' if _er_phase_ended else 'timeout'} "
                        f"inter={self.id}")

        # ── Flag 5: OFFSET CORRECTION ──────────────────────────────────────
        # Phase timing was shifted by ±Δ for green-wave alignment.
        # End condition: TSPActiveTime elapsed or phase changed.
        if self.flag == 5:
            _oc_timed_out = (time > self.TSPActiveTime)
            if current_phase != self.BusPhase or _oc_timed_out:
                try:
                    _nom_oc = self._nominal_phase_durations.get(current_phase)
                    if _nom_oc is None:
                        _nom_oc = GetPhaseDuration(self.node_id, current_phase, timeSta)
                    if _nom_oc and _nom_oc > 0:
                        ECIChangeTimingPhase(self.id, current_phase, float(_nom_oc), timeSta)
                except Exception:
                    pass
                self.flag        = 0
                self.TSPStrategy = 0
                self.reset_bus_color(self.last_detected_bus_id)
                _release_focus(time, "oc_done")
                if LOG_HARMONY:
                    log_to_file(
                        f"[HARMONY] OC ended | t={time:.1f}s "
                        f"reason={'timeout' if _oc_timed_out else 'phase_change'} "
                        f"inter={self.id}")

        # ── Flag 6: PHASE SKIPPING ─────────────────────────────────────────
        # Current phase was skipped to advance bus green. End condition:
        # BusPhase naturally ended or BusPhaseEndTime elapsed.
        if self.flag == 6:
            # Same interphase-transition guard as flag 2 (see comment there).
            if current_phase == self.BusPhase and not getattr(
                    self, '_ins_bus_phase_seen', False):
                self._ins_bus_phase_seen = True
                _grant_t6 = getattr(self, '_ins_grant_time', None)
                if _grant_t6 is not None:
                    self.BusPhaseEndTime += max(0.0, time - float(_grant_t6))
            _vp_seen = getattr(self, '_ins_bus_phase_seen', False)
            _vp_phase_ended = _vp_seen and (current_phase != self.BusPhase)
            _vp_timed_out = time > self.BusPhaseEndTime + (0.0 if _vp_seen else 10.0)
            if _vp_phase_ended or _vp_timed_out:
                if not _vp_seen:
                    log_to_file(
                        f"[HARMONY] VP ended inter={self.id} t={time:.1f} but "
                        f"bus phase NEVER became active — direct phase change "
                        f"ineffective? (cur={current_phase} bus={self.BusPhase})",
                        )
                self._ins_bus_phase_seen = False
                self._ins_grant_time = None
                ECIChangeTimingPhase(
                    self.id, self.BusPhase, self.BusPhaseDuration, timeSta)
                if (self.previous_phase
                        and self.previous_phase > 0
                        and current_phase != self.previous_phase):
                    ECIChangeDirectPhase(
                        self.id, self.previous_phase,
                        timeSta, time, acycle, 0)
                self.flag        = 0
                self.TSPStrategy = 0
                self.reset_bus_color(self.last_detected_bus_id)
                _release_focus(time, "vp_done")
                self._apply_cycle_recovery(timeSta)
                if LOG_HARMONY:
                    log_to_file(
                        f"[HARMONY] VP ended | t={time:.1f}s "
                        f"reason={'phase_change' if _vp_phase_ended else 'timeout'} "
                        f"inter={self.id}")

        # ── Flag 7: PHASE ROTATION ──────────────────────────────────────────
        # Phase sequence was rotated to skip intermediate phases.  End condition:
        # TSPActiveTime elapsed or the rotated-to phase ended.
        if self.flag == 7:
            _pt_timed_out   = (time > self.TSPActiveTime)
            _pt_phase_ended = (current_phase != self.BusPhase and
                               current_phase not in getattr(self, '_pt_skipped_phases', set()))
            if _pt_timed_out or _pt_phase_ended:
                if self.previous_phase and self.previous_phase > 0:
                    try:
                        ECIChangeDirectPhase(
                            self.id, self.previous_phase,
                            timeSta, time, acycle, 0)
                    except Exception:
                        pass
                self.flag        = 0
                self.TSPStrategy = 0
                self.reset_bus_color(self.last_detected_bus_id)
                _release_focus(time, "pt_done")
                if LOG_HARMONY:
                    log_to_file(
                        f"[HARMONY] PT ended | t={time:.1f}s "
                        f"reason={'timeout' if _pt_timed_out else 'phase_change'} "
                        f"inter={self.id}")

    def collect_delay(self, time, timeSta=None):

        # ── [DELAY] per-intersection CURRENT delay, throttled to 60 s ────────
        # Reports the PREVIOUS step's accumulated pax-seconds/s per class, so one
        # line lets you watch every junction's cost evolve live. total is
        # car+bus+truck; queued is the main/side stopped-vehicle count that step.
        try:
            if time - float(getattr(self, '_ix_delay_log_t', -1e9)) >= 60.0:
                self._ix_delay_log_t = time
                _ic = float(getattr(self, '_ix_car', 0.0))
                _ib = float(getattr(self, '_ix_bus', 0.0))
                _it = float(getattr(self, '_ix_truck', 0.0))
                log_to_file(
                    f"[DELAY_RATE] inter={self.id} t={time:.0f} "
                    f"car={_ic:.2f} bus={_ib:.2f} truck={_it:.2f} "
                    f"total={_ic + _ib + _it:.2f} paxs/s "
                    f"queued_main={int(getattr(self, '_ix_q_main', 0))} "
                    f"queued_side={int(getattr(self, '_ix_q_side', 0))}",
                    force=True)
            self._ix_car = 0.0
            self._ix_bus = 0.0
            self._ix_truck = 0.0
            self._ix_q_main = 0
            self._ix_q_side = 0
        except Exception:
            pass
        self.step_delay = 0.0
        weighted_delay  = 0.0
        # Use timeSta (stats interval start) for partial stats if available;
        # AKIEstGetParcialStatisticsSection expects the interval start time.
        stat_time = timeSta if timeSta is not None else time

        inter_state = self.stats._inter.get(self.id, {})
        main_secs   = set(inter_state.get('main_sections', []))
        side_secs   = set(inter_state.get('side_sections', []))

        # --- resolve side sections -------------------------------------------
        # Priority 1: already stored in inter_state (populated by Stats at init
        #             or by a previous collect_delay call below).
        # Priority 2: try the Stats topology method (PyANGKernel GKSystem).
        # Priority 3: fall back to the controller's own AAPI-based discovery
        #             (_cached_side_sections built by _auto_discover_side_sections)
        #             which uses AKIInfNetGetNbTurnsInNode / GetOriginSectionInTurn
        #             and is guaranteed to work in this Aimsun 26 environment.
        
        # --- resolve side sections (FIXED PRIORITY CHAIN) ---
#    1️⃣ Always prefer controller AAPI discovery (correct section IDs)
        try:
            controller_side = set(self._get_side_sections())
        except Exception:
            controller_side = set()

        if controller_side:
            side_secs = controller_side
            inter_state['side_sections'] = list(sorted(side_secs))
            inter_state['side_sections_resolved'] = True

        # 2️⃣ Only fallback to stats topology if controller found nothing
        elif main_secs or self.incoming_sections:
            # Use whichever main set is available: stats-registered or topology-derived
            _main_for_topo = main_secs if main_secs else set(self.incoming_sections)
            try:
                resolved_side = self.stats._side_sections_from_topology(
                    self.id, list(_main_for_topo))
                side_secs = set(int(s) for s in resolved_side
                                if s and int(s) not in _main_for_topo)
                if side_secs:
                    inter_state['side_sections'] = list(sorted(side_secs))
                    inter_state['side_sections_resolved'] = True
            except Exception:
                side_secs = set()
        
        
        # --- resolve main sections -------------------------------------------
        # When inter_state has no main_sections (detector IDs were invalid at
        # init time), fall back to the controller's incoming_sections set, which
        # is derived live from the BusDet detector properties.
        if not main_secs:
            main_secs = set(self.incoming_sections)

        # Only subtract main from side if the side sections were NOT resolved
        # by Stats topology (PyANGKernel).  For topology-fallback junctions
        # (no detectors), main_secs contains ALL incoming sections from AAPI,
        # while side_secs was correctly derived by PyANGKernel.  Subtracting
        # would incorrectly remove legitimate side sections.
        if not inter_state.get('side_sections_resolved', False):
            side_secs -= main_secs
        else:
            # Side sections resolved by Stats topology — remove them from
            # main_secs to prevent double-counting delay.
            main_secs -= side_secs

        all_delay_secs = set(self.incoming_sections) | main_secs | side_secs

        # Refresh SideUpFlowList so the signal-timing delay estimator has current
        # arrival rates.  This runs every step in all modes (including NORMAL) —
        # previously it only ran inside update_queue_model (TSP processing only).
        if side_secs:
            try:
                self._sample_side_sections(time)
            except Exception:
                pass

        # One-time diagnostic: verify real sections, test AKIEst/AKIVehState access
        if not getattr(self, '_delay_secs_logged', False):
            self._delay_secs_logged = True
            _diag_side = {}
            for _ds in side_secs:
                _nveh_raw = -9999
                try:
                    _nveh_raw = int(AKIVehStateGetNbVehiclesSection(_ds, True))
                except Exception:
                    _nveh_raw = -9999
                _in_dynamic_sim = (_nveh_raw >= 0)

                _est_ok = False
                _est_report = -9999
                try:
                    _st = AKIEstGetGlobalStatisticsSection(_ds, self.car_type_pos)
                    _est_report = int(getattr(_st, 'report', -9999) or -9999)
                    _est_ok = (_st.report == 0)
                except Exception:
                    pass

                if _in_dynamic_sim:
                    _diag_side[_ds] = (
                        f"nveh={_nveh_raw},sim=dynamic,est={'ok' if _est_ok else f'report={_est_report}'}"
                    )
                else:
                    # Many side sections are virtual/non-microsim in this model.
                    # Negative nveh (e.g. -4002) is expected there; side delay is
                    # still collected via AKIEst global deltas and/or signal timing.
                    _diag_side[_ds] = (
                        f"nveh={_nveh_raw},sim=virtual,"
                        f"est={'ok' if _est_ok else f'report={_est_report}'},"
                        f"fallback=signal_timing"
                    )
            log_to_file(
                f"[DELAY_SECS] inter={self.id} "
                f"main={sorted(main_secs)} "
                f"side={sorted(side_secs)} "
                f"side_access={_diag_side}",
                force=True,
            )

        if not hasattr(self, '_cum_sec_prev'):
            self._cum_sec_prev = {}
        # Accumulate all vehicle IDs seen on side sections this call,
        # used for lazy pruning of the _side_stop_prev dict.
        _all_side_veh_ids = set()

        for sec in all_delay_secs:
            # A section is "main" if it is a known main corridor section.
            # Everything else (auto-discovered cross streets) is "side".
            # When both sets are empty this falls back to True (all main).
            is_main = (sec in main_secs) if (main_secs or side_secs) else True
            _p3_synthetic = False   # True when side delay is estimated (Priority 3), not measured

            car_stat = AKIEstGetParcialStatisticsSection(
                sec, stat_time, self.car_type_pos)
            truck_stat = AKIEstGetParcialStatisticsSection(
                sec, stat_time, getattr(self.stats, '_truck_pos', -1))

            # MAIN_MEAS source label (2026-10-01). Main had NO method label at
            # all, so unlike the side path there was nothing to aggregate and no
            # way to tell whether main delay was MEASURED or fell through to a
            # warmup/failure path. Main is the dominant term -- the bus runs on it
            # and main cars carry most of the passenger weight -- so it needs the
            # same visibility side already had.
            _main_src = 'none'
            if car_stat.report == 0 and is_main:
                # ── Main section: AKIEst partial stats ─────────────────────
                # AKIEstGetParcialStatisticsSection counts vehicles that have
                # EXITED the section since stat_time.  During a GREEN step this
                # correctly captures delay for throughput vehicles.  During RED
                # it returns count=0 — those vehicles will be counted when they
                # eventually exit on green, so cumulative totals are correct.
                # We supplement with a per-vehicle scan so REAL-TIME delay
                # (needed for reward-based TSP) is also captured for vehicles
                # queued at red that haven't exited yet.
                bus_stat = AKIEstGetParcialStatisticsSection(
                    sec, stat_time, self.bus_type_pos)
                _truck_pos_m = getattr(self.stats, '_truck_pos', -1)
                car_d    = car_stat.DTa * car_stat.count * self.CarOcc
                bus_d    = bus_stat.DTa * bus_stat.count * self.BusOcc
                truck_d  = (
                    truck_stat.DTa * truck_stat.count * self.TruckOcc
                    if getattr(truck_stat, 'report', -1) == 0 and _truck_pos_m > 0
                    else 0.0
                )
                bus_cnt   = bus_stat.count
                car_cnt   = car_stat.count
                _main_src = 'akiest_partial'   # measured: real exited-vehicle stats
                truck_cnt = (
                    truck_stat.count
                    if getattr(truck_stat, 'report', -1) == 0 and _truck_pos_m > 0
                    else 0
                )

                # Track distinct vehicle IDs from AKIEst exits (green phase).
                # This populates n_distinct_cars/trucks which stay 0 if only using
                # the per-vehicle scan (which only runs during red when count==0).
                # AKIEst gives count but not individual IDs, so we scan vehicles
                # periodically to add IDs — throttle to every 5s to limit overhead.
                if car_cnt > 0 or bus_cnt > 0 or truck_cnt > 0:
                    if not hasattr(self, '_distinct_last_scan_t'):
                        self._distinct_last_scan_t = -999.0
                    if time - self._distinct_last_scan_t >= 5.0:
                        self._distinct_last_scan_t = time
                        _inter_d2 = self.stats._inter.get(self.id, {})
                        try:
                            _n_d = max(int(AKIVehStateGetNbVehiclesSection(sec, True)), 0)
                            for _dvi in range(_n_d):
                                try:
                                    _dveh = AKIVehStateGetVehicleInfSection(sec, _dvi)
                                    if _dveh.report < 0:
                                        continue
                                    _dvid  = int(_dveh.idVeh)
                                    _dtype = int(_dveh.type)
                                    if _dtype == self.bus_type_pos:
                                        _inter_d2.get('_seen_bus_ids', set()).add(_dvid)
                                    elif _truck_pos_m > 0 and _dtype == _truck_pos_m:
                                        _inter_d2.get('_seen_truck_ids', set()).add(_dvid)
                                    else:
                                        _inter_d2.get('_seen_car_ids', set()).add(_dvid)
                                except Exception:
                                    pass
                        except Exception:
                            pass

                # Supplement: if this step has no exited vehicles (red phase),
                # use the per-vehicle scan to capture queued delay in real time.
                # The AKIEst path already accounts for exited vehicles, so the
                # per-vehicle scan is only used when count==0.
                if car_cnt == 0 and bus_cnt == 0:
                    _prof_m  = getattr(self, '_sec_profile', {}).get(sec)
                    _ff_s_m  = _prof_m['ff_time_s'] if _prof_m else getattr(
                        self, '_side_ff_cache', {}).get(sec, 10.0)
                    if not hasattr(self, '_main_stoptime_prev'):
                        self._main_stoptime_prev = {}
                    _n_main = max(int(AKIVehStateGetNbVehiclesSection(sec, True)), 0)
                    _inter_d = self.stats._inter.get(self.id, {})
                    for _mvi in range(_n_main):
                        try:
                            _mveh = AKIVehStateGetVehicleInfSection(sec, _mvi)
                            if _mveh.report < 0:
                                continue
                            _mvid  = int(_mveh.idVeh)
                            _mtype = int(_mveh.type)
                            _mkey  = (sec, _mvid)
                            # Track distinct vehicle IDs so n_distinct_cars/trucks
                            # are populated (otherwise they stay 0 forever).
                            if _mtype == self.bus_type_pos:
                                _inter_d.get('_seen_bus_ids', set()).add(_mvid)
                            elif _truck_pos_m > 0 and _mtype == _truck_pos_m:
                                _inter_d.get('_seen_truck_ids', set()).add(_mvid)
                            else:
                                _inter_d.get('_seen_car_ids', set()).add(_mvid)
                            _ent_t = float(
                                getattr(_mveh, 'SectionEntranceT', -1.0) or -1.0)
                            if 0.0 < _ent_t < time:
                                _dly_now = max(0.0, (time - _ent_t) - _ff_s_m)
                            else:
                                _dly_now = max(0.0, float(
                                    getattr(_mveh, 'CurrentStopTime', 0.0) or 0.0))
                            _prev_m   = self._main_stoptime_prev.get(_mkey, _dly_now)
                            _delta_m  = max(0.0, _dly_now - _prev_m)
                            self._main_stoptime_prev[_mkey] = _dly_now
                            if _delta_m <= 0.0:
                                continue
                            if _mtype == self.bus_type_pos:
                                bus_d   += _delta_m * self.BusOcc
                            elif _truck_pos_m > 0 and _mtype == _truck_pos_m:
                                truck_d += _delta_m * self.TruckOcc
                            else:
                                car_d   += _delta_m * self.CarOcc
                        except Exception:
                            pass
                    if car_d > 0.0 or bus_d > 0.0:
                        _main_src = 'vehicle_scan'  # measured: queued at red

            elif not is_main:
                # ── Side section delay: three-priority measurement ──────────
                #
                # Side sections in this model are NOT in the dynamic vehicle
                # simulation (AKIVehStateGetNbVehiclesSection returns -4002 =
                # AKI_ERROR_SECTION_NOTEXIST).  They exist in Aimsun's routing
                # topology but cross-street demand is handled as virtual demand
                # that never places physical vehicles on road sections.
                #
                # Priority 1 — AKIEst global cumulative stats (timSta=0.0)
                #   Works even for non-physically-simulated sections when Aimsun
                #   has a statistics collector configured for the section.  The
                #   running DTa*count product increases monotonically; delta gives
                #   the per-step delay contribution from vehicles that DID exit.
                #
                # Priority 2 — Per-vehicle scan (AKIVehState)
                #   Only applicable when the section IS in the dynamic simulation
                #   (AKIVehState returns >= 0).  Captures queued vehicles that
                #   have not yet exited, including those stopped at red.
                #
                # Priority 3 — Signal-timing shockwave estimate (always-on)
                #   When neither of the above yields data, compute theoretical
                #   queue delay from the current signal phase state:
                #     delta = (arrival_rate / 3600) × red_elapsed_s × Occ
                #   This is the same model used by GE/BP objective functions and
                #   correctly accumulates during red, resets on cross-street green.
                #   Arrival rate comes from SideUpFlowList (maintained by
                #   _update_side_section_virtual_detectors); when that is also 0
                #   a conservative 300 veh/h default is used.
                #   This ensures non-zero side delay is always recorded throughout
                #   the run — even in NORMAL mode with no bus detection events.
                car_d = bus_d = truck_d = 0.0
                car_cnt = bus_cnt = truck_cnt = 0
                _truck_pos_s = getattr(self.stats, '_truck_pos', -1)
                _priority_used = "none"

                # ── Priority 1: AKIEst global cumulative delta ────────────
                if not hasattr(self, '_side_global_prev'):
                    self._side_global_prev = {}
                try:
                    _cg  = AKIEstGetGlobalStatisticsSection(sec, self.car_type_pos)
                    _bg  = AKIEstGetGlobalStatisticsSection(sec, self.bus_type_pos)
                    _p1_ok = (_cg.report == 0 and _bg.report == 0)
                    if _p1_ok:
                        _now_c = float(_cg.DTa * _cg.count) if _cg.count > 0 else 0.0
                        _now_b = float(_bg.DTa * _bg.count) if _bg.count > 0 else 0.0
                        _pc = self._side_global_prev.get((sec, 'c'), 0.0)
                        _pb = self._side_global_prev.get((sec, 'b'), 0.0)
                        car_d = max(0.0, _now_c - _pc) * self.CarOcc
                        bus_d = max(0.0, _now_b - _pb) * self.BusOcc
                        self._side_global_prev[(sec, 'c')] = _now_c
                        self._side_global_prev[(sec, 'b')] = _now_b
                        if _truck_pos_s > 0:
                            _tg = AKIEstGetGlobalStatisticsSection(sec, _truck_pos_s)
                            if _tg.report == 0 and _tg.count > 0:
                                _now_t = float(_tg.DTa * _tg.count)
                                _pt = self._side_global_prev.get((sec, 't'), 0.0)
                                truck_d = max(0.0, _now_t - _pt) * self.TruckOcc
                                self._side_global_prev[(sec, 't')] = _now_t
                        if car_d > 0.0 or bus_d > 0.0:
                            _priority_used = "akiest_global"
                except Exception:
                    _p1_ok = False

                # ── Priority 2: per-vehicle scan (only if section is in sim) ─
                _n_test = int(AKIVehStateGetNbVehiclesSection(sec, True))
                _in_sim = (_n_test >= 0)
                if _in_sim and car_d == 0.0 and bus_d == 0.0:
                    _prof = getattr(self, '_sec_profile', {}).get(sec)
                    _ff_s = _prof['ff_time_s'] if _prof else getattr(
                        self, '_side_ff_cache', {}).get(sec, 10.0)
                    _alive_keys = set()
                    for _vi in range(_n_test):
                        try:
                            _veh = AKIVehStateGetVehicleInfSection(sec, _vi)
                            if _veh.report < 0:
                                continue
                            _vid   = int(_veh.idVeh)
                            _vtype = int(_veh.type)
                            _key   = (sec, _vid)
                            _alive_keys.add(_key)
                            _ent_t = float(
                                getattr(_veh, 'SectionEntranceT', -1.0) or -1.0)
                            if 0.0 < _ent_t < time:
                                _delay_now = max(0.0, (time - _ent_t) - _ff_s)
                            else:
                                _delay_now = max(0.0, float(
                                    getattr(_veh, 'CurrentStopTime', 0.0) or 0.0))
                            _prev_d = self._side_stoptime_prev.get(_key, _delay_now)
                            _delta  = max(0.0, _delay_now - _prev_d)
                            self._side_stoptime_prev[_key] = _delay_now
                            _all_side_veh_ids.add(_vid)
                            if _delta <= 0.0:
                                continue
                            if _vtype == self.bus_type_pos:
                                bus_d   += _delta * self.BusOcc
                            elif _truck_pos_s > 0 and _vtype == _truck_pos_s:
                                truck_d += _delta * self.TruckOcc
                            else:
                                car_d   += _delta * self.CarOcc
                        except Exception:
                            pass
                    # Prune stale entries for this section
                    _stale = [k for k in self._side_stoptime_prev
                              if k[0] == sec and k not in _alive_keys]
                    for _k in _stale:
                        del self._side_stoptime_prev[_k]
                    if car_d > 0.0 or bus_d > 0.0:
                        _priority_used = "vehicle_scan"

                # ── Priority 2.5: the ACTUAL virtual queue (2026-10-01) ────────
                # WHY THIS EXISTS: side sections are not in the dynamic vehicle
                # simulation (AKIVehState returns -4002), so the previous chain
                # measured nothing and fell through to the Priority-3 shockwave
                # ESTIMATE -- an arrival_rate x red_elapsed model whose arrival
                # rate, when the virtual detectors are also empty, is a hardcoded
                # default. But Aimsun DOES track the side demand it refuses to
                # place as physical vehicles: the VIRTUAL QUEUE, exposed per section
                # by AKIEstGetParcialStatisticsSection(sec, 0.0, type):
                #     numVehiclesInVQ          vehicles currently in the virtual queue
                #     waitingTimeVirtualQueue  their waiting time (s)
                #     virtualQueueAvg / Max    queue-length statistics
                # (Simulation_Stats.py already reads these for the network roll-up,
                # which is why Net_VQMax_Bus is non-zero in the run summary -- the
                # data was always there, the side delay path just never asked.)
                #
                # This replaces an ESTIMATE with a MEASUREMENT: the queue count the
                # plant itself maintains, priced as veh-seconds per step. Runs BEFORE
                # Priority 3 so the shockwave model only fires when even the virtual
                # queue is unavailable.
                if car_d <= 0.0 and bus_d <= 0.0 and truck_d <= 0.0:
                    try:
                        _vq_car = AKIEstGetParcialStatisticsSection(
                            sec, 0.0, self.car_type_pos)
                        # USE virtualQueueAvg, NOT numVehiclesInVQ. The live probe
                        # (results/*/api_probe.log) shows `numVehiclesInVQ` present in
                        # the attrs list but ABSENT from the returned values dict, so
                        # getattr(..., 0) yields 0 forever and the branch would never
                        # fire. `virtualQueueAvg` IS populated (0.0045 on sec=21530).
                        # `virtualQueueMax` is the fallback.
                        # NOTE the -1.0 sentinel: waitingTimeVirtualQueue returns -1.0
                        # when there is no queue, so any use of it must guard < 0.
                        _vq_n = float(getattr(_vq_car, 'virtualQueueAvg', 0.0) or 0.0)
                        if _vq_n <= 0.0:
                            _vq_n = float(getattr(_vq_car, 'virtualQueueMax', 0.0) or 0.0)
                        if getattr(_vq_car, 'report', -1) == 0 and _vq_n > 0.0:
                            _dt_vq = float(globals().get('CELLQ_CTM_DT_S', 1.0) or 1.0)
                            _vq_bus = 0.0
                            try:
                                _vq_b = AKIEstGetParcialStatisticsSection(
                                    sec, 0.0, self.bus_type_pos)
                                if getattr(_vq_b, 'report', -1) == 0:
                                    _vq_bus = float(getattr(_vq_b,
                                                            'virtualQueueAvg', 0.0) or 0.0)
                            except Exception:
                                _vq_bus = 0.0
                            _vq_cars = max(0.0, _vq_n - _vq_bus)
                            # veh-seconds accrued this step by vehicles sitting in
                            # the virtual queue, in pax-seconds via occupancy
                            car_d   += _vq_cars * _dt_vq * self.CarOcc
                            bus_d   += _vq_bus * _dt_vq * self.BusOcc
                            if car_d > 0.0 or bus_d > 0.0:
                                _priority_used = (
                                    f"vq_measured(n={_vq_n:.2f},bus={_vq_bus:.2f},"
                                    f"dt={_dt_vq:.0f}s)")
                            # Throttled raw-value log (once per 60 s per section).
                            # The probe showed these fields EXIST but are empty on
                            # some sections, so record the actual numbers rather
                            # than inferring from the bucket counts.
                            if not hasattr(self, '_vq_log_t'):
                                self._vq_log_t = {}
                            if time - self._vq_log_t.get(sec, -999.0) >= 60.0:
                                self._vq_log_t[sec] = time
                                log_to_file(
                                    f"[VQ] inter={self.id} t={time:.0f} sec={sec} "
                                    f"avg={_vq_n:.4f} bus={_vq_bus:.4f} "
                                    f"max={float(getattr(_vq_car, 'virtualQueueMax', 0.0) or 0.0):.2f} "
                                    f"wait={float(getattr(_vq_car, 'waitingTimeVirtualQueue', -1.0) or -1.0):.3f}",
                                    force=True)
                    except Exception:
                        pass

                # ── Priority 3: signal-timing shockwave estimate ──────────
                # Always runs.  Provides non-zero side delay even for sections
                # not in the dynamic simulation.  Consistent with GE/BP
                # objective functions which use the same shockwave model.
                #
                # Allocate delay proportionally across vehicle types using
                # per-vehicle-type statistics from Priority 1 when available,
                # or fallback to default proportions (car: 70%, bus: 20%, truck: 10%).
                #
                # delta = (q_arr / 3600) × red_elapsed_s × Occ × (vtype_count / total_count)
                #
                # This correctly integrates: summing (q/3600)×r×Occ dr from r=0
                # to R gives (q/3600) × R²/2 × Occ = standard uniform delay.
                # The estimate is applied to supplement (not overwrite) measured
                # delay so Priority 1/2 data is never discarded.
                # Only when the section is NOT dynamically simulated: for
                # in-sim sections Priority 2 measured the real queue — if it
                # found nothing there IS no delay, and inventing a 400 veh/h
                # phantom queue here was the source of the enormous synthetic
                # SidePassDelay (and, via the per-type split, of the broken
                # AvgCarPassDelay_s) in the batch results.
                if (not _in_sim) and car_d == 0.0 and bus_d == 0.0:
                    try:
                        _nid    = getattr(self, 'node_id', self.id)
                        _cur_ph = ECIGetCurrentPhase(_nid)
                        _bus_ph = int(getattr(self, 'BusPhase', 1) or 1)

                        # Cross-streets accumulate red-light delay during main
                        # corridor phases (bus phase and typically phase 2).
                        # Track cumulative red elapsed per section using a running
                        # counter so delay accumulates correctly across phase changes.
                        if not hasattr(self, '_side_red_elapsed'):
                            self._side_red_elapsed = {}
                            self._side_last_t      = {}

                        _last_t = self._side_last_t.get(sec, time)
                        _dt     = max(0.0, time - _last_t)
                        self._side_last_t[sec] = time

                        # Determine if cross-street is currently at red.
                        # Heuristic: cross-street is at red during the bus
                        # (main corridor) phase.  Reset counter on any other phase.
                        if _cur_ph == _bus_ph:
                            self._side_red_elapsed[sec] = (
                                self._side_red_elapsed.get(sec, 0.0) + _dt)
                        else:
                            # Cross-street may be green — reset accumulated red time
                            self._side_red_elapsed[sec] = 0.0

                        _red_el = self._side_red_elapsed.get(sec, 0.0)
                        if _red_el > 0.0:
                            # Arrival rate: prefer SideUpFlowList (from _sample_side_sections
                            # which uses 15% of main flow as fallback). If still 0, derive
                            # from main approach flow (UpFlowList[0]) × 15% ratio.
                            _side_secs_live = self._get_side_sections()
                            _side_flow      = 0.0
                            try:
                                _sidx = _side_secs_live.index(sec)
                                _sf   = float(self.SideUpFlowList[_sidx])
                                if _sf > 0.0:
                                    _side_flow = _sf
                            except Exception:
                                pass
                            if _side_flow <= 0.0:
                                # Estimate from main corridor approach flow (15% cross-street ratio).
                                # No hard 400 veh/h floor: if the main approach is empty there is
                                # nothing to turn onto the side street, so inventing a 400 veh/h
                                # phantom queue here would fabricate delay (the old phantom-queue bug).
                                try:
                                    _main_q = float(self.UpFlowList[0][0]) if hasattr(self, 'UpFlowList') and len(self.UpFlowList) > 0 else 0.0
                                    _side_flow = max(_main_q * 0.15, 0.0)
                                except Exception:
                                    _side_flow = 0.0

                            if _side_flow > 0.0:
                                # Allocate delay across vehicle types.
                                # First try to get per-vehicle-type counts from Priority 1.
                                # If unavailable, use default proportions.
                                _c_car = 0.0
                                _c_bus = 0.0
                                _c_truck = 0.0
                                _c_total = 1.0   # avoid division by zero
                                _truck_pos_p3 = getattr(self.stats, '_truck_pos', -1)
                                try:
                                    _cg = AKIEstGetGlobalStatisticsSection(sec, self.car_type_pos)
                                    _bg = AKIEstGetGlobalStatisticsSection(sec, self.bus_type_pos)
                                    if _cg.report == 0 and _bg.report == 0:
                                        _c_car   = float(_cg.count) if _cg.count > 0 else 0.0
                                        _c_bus   = float(_bg.count) if _bg.count > 0 else 0.0
                                        if _truck_pos_p3 > 0:
                                            _tg = AKIEstGetGlobalStatisticsSection(sec, _truck_pos_p3)
                                            _c_truck = float(_tg.count) if _tg.report == 0 and _tg.count > 0 else 0.0
                                        _c_total = _c_car + _c_bus + _c_truck
                                        if _c_total <= 0.0:
                                            _c_total = 1.0
                                except Exception:
                                    pass

                                # If counts are all zero, use fallback proportions.
                                # Side streets carry almost exclusively cars; the
                                # old 70/20/10 split charged 20% of every synthetic
                                # vehicle-second at BusOcc(40) — inflating side
                                # delay ~9x per vehicle.
                                if _c_car <= 0.0 and _c_bus <= 0.0 and _c_truck <= 0.0:
                                    _c_car   = 0.95   # 95% cars
                                    _c_bus   = 0.00   # buses on side streets are measured, not assumed
                                    _c_truck = 0.05   # 5% trucks
                                    _c_total = 1.0

                                # Base delay: (q/3600) × red_elapsed × dt
                                _base_delay = (_side_flow / 3600.0) * _red_el * _dt
                                # Allocate to each type proportionally
                                car_d   = _base_delay * (_c_car / _c_total) * self.CarOcc if _c_total > 0 else 0.0
                                bus_d   = _base_delay * (_c_bus / _c_total) * self.BusOcc if _c_total > 0 else 0.0
                                truck_d = _base_delay * (_c_truck / _c_total) * self.TruckOcc if _c_total > 0 else 0.0
                                _p3_synthetic = True

                                _priority_used = (
                                    f"signal_timing(red={_red_el:.0f}s,"
                                    f"q={_side_flow:.0f},dt={_dt:.0f}s,"
                                    f"split=c:{_c_car/max(_c_total,1):.2f},"
                                    f"b:{_c_bus/max(_c_total,1):.2f},"
                                    f"t:{_c_truck/max(_c_total,1):.2f})"
                                )
                    except Exception:
                        pass

                self._last_side_priority = _priority_used

                # ── AGGREGATE the measurement path (2026-10-01) ────────────────
                # The per-section [SIDE_DELAY] line says which method was used for
                # ONE section at ONE instant, which cannot answer the question that
                # actually matters: is side delay MEASURED from the plant, or
                # ESTIMATED from signal timing? A single run can be mostly estimated
                # and still look healthy line-by-line. This buckets every side
                # measurement and periodically reports the split, so the estimated
                # FRACTION is visible -- that fraction is the honesty bound on any
                # result that depends on side cost.
                try:
                    _p = str(_priority_used)
                    if _p.startswith('akiest_global'):
                        _bucket = 'akiest_global'      # real per-section stats
                    elif _p.startswith('vq_measured'):
                        # the plant's own VIRTUAL QUEUE -- a measurement, not an
                        # estimate, and the only real source on sections that are
                        # not in the dynamic vehicle simulation
                        _bucket = 'vq_measured'
                    elif _p.startswith('vehicle_scan'):
                        _bucket = 'vehicle_scan'       # real per-vehicle state
                    elif _p.startswith('signal_timing'):
                        _bucket = 'signal_timing'      # ESTIMATE (shockwave model)
                    elif _p.startswith('none'):
                        # 'none' is INTENDED to mean "genuinely empty": Priority 3
                        # only fires when _side_flow > 0, and inventing demand for an
                        # empty approach was the old phantom-queue bug. But the
                        # counter alone cannot tell a correctly-empty section from a
                        # measurement GAP, and those have opposite meanings.
                        #
                        # REFINED 2026-10-01: a real gap needs QUEUED vehicles, not
                        # merely PRESENT ones. Priority 2 accrues the INCREMENT in
                        # each vehicle's stop time, so a section full of MOVING
                        # traffic yields _delta = 0 and stays 'none' -- correctly, as
                        # moving vehicles accrue no delay. Counting mere presence as
                        # a gap therefore raised a false alarm: on KG inter=39578 it
                        # reported "15% priced at ZERO" when much of that was
                        # free-flowing traffic. Only a STOPPED vehicle that produced
                        # no delay is a genuine hole in the pricing.
                        _queued = 0
                        try:
                            _nv = int(AKIVehStateGetNbVehiclesSection(
                                int(sec), False) or 0)
                            _qspd = float(globals().get(
                                'MICRO_QUEUE_SPEED_KMH', 5.0) or 5.0)
                            for _vi in range(_nv):
                                try:
                                    _vv = AKIVehStateGetVehicleInfSection(
                                        int(sec), _vi)
                                    if float(getattr(_vv, 'CurrentSpeed',
                                                     0.0) or 0.0) <= _qspd:
                                        _queued += 1
                                except Exception:
                                    continue
                        except Exception:
                            _nv = -1
                        if _queued > 0:
                            _bucket = 'GAP_queued_no_data'  # REAL hole
                        elif _nv > 0:
                            _bucket = 'moving_no_delay'     # correct zero
                        elif _nv == 0:
                            _bucket = 'empty'               # correct zero
                        else:
                            _bucket = 'gap_unknown'         # query failed
                    else:
                        _bucket = 'other'
                    _pc = getattr(self, '_side_meas_counts', None)
                    if _pc is None:
                        _pc = self._side_meas_counts = {}
                    _pc[_bucket] = int(_pc.get(_bucket, 0)) + 1
                    _tot = sum(_pc.values())
                    _est = int(_pc.get('signal_timing', 0))
                    _gap = int(_pc.get('GAP_queued_no_data', 0)) + int(
                        _pc.get('gap_unknown', 0))
                    _meas = (int(_pc.get('akiest_global', 0))
                             + int(_pc.get('vehicle_scan', 0))
                             + int(_pc.get('vq_measured', 0)))
                    _last_sum = float(getattr(self, '_side_meas_sum_t', -1e9))
                    if _tot >= 50 and (time - _last_sum) >= 300.0:
                        self._side_meas_sum_t = time
                        # Headline the GAP fraction, not the estimated fraction:
                        # an estimate is at least priced from the signal plan, while
                        # a gap prices cross traffic at ZERO. The estimated share is
                        # kept because it is still a weaker input than a measurement.
                        log_to_file(
                            f"[SIDE_MEAS] inter={self.id} t={time:.0f} n={_tot} "
                            f"measured={_meas} estimated={_est} "
                            f"({100.0 * _est / max(_tot, 1):.0f}% est) "
                            f"GAP_queued={_gap} ({100.0 * _gap / max(_tot, 1):.0f}% priced "
                            f"at ZERO) detail={_pc}", force=True)
                except Exception:
                    pass

            else:
                # ── Main section fallback: partial stats unavailable (warmup) ──
                # Use cumulative delta from AKIEstGetGlobalStatisticsSection.
                try:
                    car_cum = AKIEstGetCurrentStatisticsSection(
                        sec, self.car_type_pos)
                    bus_cum = AKIEstGetCurrentStatisticsSection(
                        sec, self.bus_type_pos)
                    truck_cum = AKIEstGetCurrentStatisticsSection(
                        sec, getattr(self.stats, '_truck_pos', -1))

                    if car_cum.report != 0:
                        car_cum = AKIEstGetGlobalStatisticsSection(
                            sec, self.car_type_pos)
                    if bus_cum.report != 0:
                        bus_cum = AKIEstGetGlobalStatisticsSection(
                            sec, self.bus_type_pos)
                    if getattr(self.stats, '_truck_pos', -1) > 0 and truck_cum.report != 0:
                        truck_cum = AKIEstGetGlobalStatisticsSection(
                            sec, getattr(self.stats, '_truck_pos', -1))

                    prev_car   = self._cum_sec_prev.get((sec, 'car'),   (0.0, 0))
                    prev_bus   = self._cum_sec_prev.get((sec, 'bus'),   (0.0, 0))
                    prev_truck = self._cum_sec_prev.get((sec, 'truck'), (0.0, 0))

                    car_total_now   = (car_cum.DTa   * car_cum.count)   if car_cum.report   == 0 else 0.0
                    bus_total_now   = (bus_cum.DTa   * bus_cum.count)   if bus_cum.report   == 0 else 0.0
                    truck_total_now = (
                        truck_cum.DTa * truck_cum.count
                        if getattr(truck_cum, 'report', -1) == 0 and getattr(self.stats, '_truck_pos', -1) > 0
                        else 0.0)

                    car_cnt   = max(0, (car_cum.count   if car_cum.report   == 0 else 0) - prev_car[1])
                    bus_cnt   = max(0, (bus_cum.count   if bus_cum.report   == 0 else 0) - prev_bus[1])
                    truck_cnt = max(0, (
                        (truck_cum.count if getattr(truck_cum, 'report', -1) == 0 else 0) - prev_truck[1]))

                    car_d   = max(0.0, car_total_now   - prev_car[0])   * self.CarOcc
                    bus_d   = max(0.0, bus_total_now   - prev_bus[0])   * self.BusOcc
                    truck_d = max(0.0, truck_total_now - prev_truck[0]) * self.TruckOcc

                    self._cum_sec_prev[(sec, 'car')]   = (
                        car_total_now,   car_cum.count   if car_cum.report   == 0 else prev_car[1])
                    self._cum_sec_prev[(sec, 'bus')]   = (
                        bus_total_now,   bus_cum.count   if bus_cum.report   == 0 else prev_bus[1])
                    self._cum_sec_prev[(sec, 'truck')] = (
                        truck_total_now,
                        truck_cum.count if getattr(truck_cum, 'report', -1) == 0 else prev_truck[1])

                    _main_src = 'akiest_cumulative'  # measured: cumulative delta
                except Exception:
                    car_d = bus_d = truck_d = 0.0
                    car_cnt = bus_cnt = truck_cnt = 0
                    _main_src = 'none'

            sec_delay = car_d + bus_d + truck_d
            weighted_delay += sec_delay

            # ── PER-INTERSECTION CURRENT DELAY (2026-10-01) ───────────────────
            # Accumulate this step's delay per intersection so a single [DELAY]
            # line can report what every junction is costing RIGHT NOW, split by
            # vehicle class. Existing logs are per-SECTION ([SIDE_DELAY]) or
            # per-measurement-path ([SIDE_MEAS]/[MAIN_MEAS]); none answers "what
            # is junction X costing at this moment", which is what you need to
            # watch a run evolve. The emitter (top of collect_delay) reports the
            # previous step's totals, a 1 s lag that is immaterial here.
            try:
                self._ix_car = float(getattr(self, '_ix_car', 0.0)) + float(car_d)
                self._ix_bus = float(getattr(self, '_ix_bus', 0.0)) + float(bus_d)
                self._ix_truck = float(getattr(self, '_ix_truck', 0.0)) + float(truck_d)
                if is_main:
                    self._ix_q_main = int(getattr(self, '_ix_q_main', 0)) + int(car_cnt)
                else:
                    self._ix_q_side = int(getattr(self, '_ix_q_side', 0)) + int(car_cnt)
            except Exception:
                pass

            # ── MAIN_MEAS: same visibility for main that side already has ─────
            # Buckets the source, and when NOTHING produced delay asks whether the
            # section actually held QUEUED vehicles -- because only a stopped
            # vehicle with no delay recorded is a real pricing hole. Vehicles
            # merely present (moving) accrue no delay by definition, so counting
            # them would be the same false alarm the side GAP bucket raised.
            if is_main:
                try:
                    _ms = str(_main_src)
                    if sec_delay > 0.0:
                        _mb = _ms
                    else:
                        _q = 0
                        try:
                            _nvm = int(AKIVehStateGetNbVehiclesSection(sec, False) or 0)
                            _qs = float(globals().get('MICRO_QUEUE_SPEED_KMH', 5.0) or 5.0)
                            # A stopped vehicle only has DELAY once it has been on
                            # the section longer than its FREE-FLOW traversal time --
                            # the main path computes delay as
                            #   max(0, (time - entranceT) - ff_time)
                            # so a vehicle stopped but still inside its free-flow
                            # budget legitimately accrues ZERO. Counting it as a gap
                            # would repeat the false alarm the side bucket raised.
                            _ffm = 10.0
                            try:
                                _pm = getattr(self, '_sec_profile', {}).get(sec)
                                if _pm:
                                    _ffm = float(_pm.get('ff_time_s', 10.0) or 10.0)
                                else:
                                    _ffm = float(getattr(self, '_side_ff_cache',
                                                         {}).get(sec, 10.0) or 10.0)
                            except Exception:
                                pass
                            for _mi in range(_nvm):
                                try:
                                    _mv = AKIVehStateGetVehicleInfSection(sec, _mi)
                                    if float(getattr(_mv, 'CurrentSpeed', 0.0) or 0.0) > _qs:
                                        continue
                                    _ent = float(getattr(_mv, 'SectionEntranceT', -1.0) or -1.0)
                                    if 0.0 < _ent < time:
                                        if (time - _ent) - _ffm <= 0.0:
                                            continue   # inside free-flow budget
                                    else:
                                        if float(getattr(_mv, 'CurrentStopTime', 0.0) or 0.0) <= 0.0:
                                            continue
                                    _q += 1
                                except Exception:
                                    continue
                        except Exception:
                            _nvm = -1
                        if _q > 0:
                            _mb = 'GAP_queued_no_data'
                        elif _nvm > 0:
                            _mb = 'moving_no_delay'
                        elif _nvm == 0:
                            _mb = 'empty'
                        else:
                            _mb = 'gap_unknown'
                    _mc = getattr(self, '_main_meas_counts', None)
                    if _mc is None:
                        _mc = self._main_meas_counts = {}
                    _mc[_mb] = int(_mc.get(_mb, 0)) + 1
                    _mt = sum(_mc.values())
                    _mg = int(_mc.get('GAP_queued_no_data', 0)) + int(_mc.get('gap_unknown', 0))
                    _lastm = float(getattr(self, '_main_meas_sum_t', -1e9))
                    if _mt >= 50 and (time - _lastm) >= 300.0:
                        self._main_meas_sum_t = time
                        log_to_file(
                            f"[MAIN_MEAS] inter={self.id} t={time:.0f} n={_mt} "
                            f"GAP_queued={_mg} "
                            f"({100.0 * _mg / max(_mt, 1):.0f}% priced at ZERO) "
                            f"detail={_mc}", force=True)
                except Exception:
                    pass

            # Throttled side-delay diagnostic (once per 60 s per section)
            if not is_main and sec_delay > 0.0:
                if not hasattr(self, '_side_delay_log_t'):
                    self._side_delay_log_t = {}
                _last_log = self._side_delay_log_t.get(sec, -999.0)
                if time - _last_log >= 60.0:
                    self._side_delay_log_t[sec] = time
                    log_to_file(
                        f"[SIDE_DELAY] inter={self.id} t={time:.0f} "
                        f"sec={sec} delay={sec_delay:.3f}pax·s "
                        f"method={getattr(self, '_last_side_priority', 'unknown')}"
                    )

            # For side sections the `bus_cnt` / `car_cnt` values are per-step
            # stopped-vehicle counts, NOT passage counts. Adding them to the
            # stats passages denominator would inflate PaxEquivPassages by
            # N_stopped_vehicles × N_steps (×1000 s of overcounting).
            # Side-section delay is captured in `delay_side` via `is_main=False`;
            # the passage/passenger denominators only need main-section counts.
            _pass_bus_cnt   = bus_cnt   if is_main else 0
            _pass_car_cnt   = car_cnt   if is_main else 0
            _pass_truck_cnt = truck_cnt if is_main else 0

            # Synthetic (Priority 3) side delay counts toward total/side delay
            # but must NOT enter the per-type accumulators: per-type averages
            # divide by MAIN-section passenger counts, so synthetic side pax·s
            # in the numerator produced absurd values (AvgCarPassDelay_s in
            # the hundreds of thousands of seconds).
            _type_bus_d   = 0.0 if _p3_synthetic else bus_d
            _type_car_d   = 0.0 if _p3_synthetic else car_d
            _type_truck_d = 0.0 if _p3_synthetic else truck_d

            self.stats.add_section_delay_split(
                intersection_id   = self.id,
                weighted_delay    = sec_delay,
                bus_vehicle_count = _pass_bus_cnt,
                car_vehicle_count = _pass_car_cnt,
                truck_vehicle_count = _pass_truck_cnt,
                is_main           = is_main,
                bus_delay         = _type_bus_d,
                car_delay         = _type_car_d,
                truck_delay       = _type_truck_d,
            )

            if not is_main and sec in side_secs:
                if not hasattr(self, '_side_red_counts'):
                    self._side_red_counts = {}
                if not hasattr(self, '_side_live_counts'):
                    self._side_live_counts = {}
                live_side_count = 0
                try:
                    live_side_count = max(int(AKIVehStateGetNbVehiclesSection(sec, True)), 0)
                except Exception:
                    live_side_count = 0
                self._side_live_counts[sec] = live_side_count
                self._side_red_counts[sec] = (
                    safe_float(self._side_red_counts.get(sec, 0.0))
                    + max(live_side_count, int(max(0, bus_cnt + car_cnt + truck_cnt)))
                )

        self.step_delay += weighted_delay

        # Prune _side_stop_prev: remove vehicle IDs not seen this call.
        # Only runs every ~60 s to avoid per-step overhead.
        if hasattr(self, '_side_stop_prev') and _all_side_veh_ids:
            if not hasattr(self, '_side_prune_t'):
                self._side_prune_t = time
            if time - self._side_prune_t > 60.0:
                self._side_stop_prev = {
                    k: v for k, v in self._side_stop_prev.items()
                    if k in _all_side_veh_ids}
                self._side_prune_t = time

        # Periodic delay debug log (every 60 s) — LOG_DELAY flag
        if LOG_DELAY:
            if not hasattr(self, '_delay_log_t'):
                self._delay_log_t = time
            if time - self._delay_log_t >= 60.0:
                _inter_d = self.stats._inter.get(self.id, {})
                _avg_den = self.stats._inter_dsf_avg(self.id, 'density_sum')
                _avg_spd = self.stats._inter_dsf_avg(self.id, 'speed_sum')
                _avg_flw = self.stats._inter_dsf_avg(self.id, 'flow_sum')
                _avg_que = self.stats._inter_dsf_avg(self.id, 'queue_sum')
                log_to_file(
                    f"[DELAY] inter={self.id} t={time:.0f} "
                    f"main_secs={sorted(main_secs)} "
                    f"side_secs={sorted(side_secs)} "
                    f"step_weighted={weighted_delay:.4f} "
                    f"avg_density={_avg_den:.2f}veh/km "
                    f"avg_speed={_avg_spd:.2f}km/h "
                    f"avg_flow={_avg_flw:.1f}veh/h "
                    f"avg_queue={_avg_que:.2f}veh "
                    f"cum_side_delay_s={_inter_d.get('delay_side', 0.0):.2f} "
                    f"cum_main_delay_s={_inter_d.get('delay_main', 0.0):.2f} "
                    f"side_veh_tracked={len(getattr(self, '_side_stop_prev', {}))}"
                )
                self._delay_log_t = time

    # =========================================================================
    # GROUP-BASED READINESS GUARD
    # =========================================================================

    def update(self, time, timeSta, acycle):
        if TSP_ACTIVE_INTERSECTIONS is not None and self.id not in TSP_ACTIVE_INTERSECTIONS:
            return

        try:
            # ── All other modes: phase-based tracking + TSP logic ─────────────
            current_phase = ECIGetCurrentPhase(self.node_id)
            if current_phase < 0:
                return

            # Phase-transition bookkeeping
            if current_phase != getattr(self, 'previous_phase', -1):
                prev_phase = getattr(self, 'previous_phase', -1)
                if prev_phase in self.PhaseIndex:
                    prev_idx = self.PhaseIndex[prev_phase]
                    if prev_idx < len(self.RedStartTimeList):
                        self.RedStartTimeList[prev_idx][:] = time
                        self.UpDetCountList[prev_idx][:] = 0.0
                        self.UpAveOccList[prev_idx][:]   = 0.0
                if current_phase in self.PhaseIndex:
                    idx = self.PhaseIndex[current_phase]
                    if idx < len(self.GreenStartTimeList):
                        self.GreenStartTimeList[idx][:] = time
                        dur = GetPhaseDuration(self.node_id, current_phase, timeSta)
                        if idx < len(self.NextRedStartTime):
                            self.NextRedStartTime[idx][:] = time + dur
                self.previous_phase = current_phase

            self.collect_detector_data()
            self.update_queue_model(time)
            self.detect_bus(time)

            # ── Closed-loop RL: credit realized outcomes back to the Q-table ──
            # Applies _bxt_update_q for any logged BXT decision whose evaluation
            # window has elapsed, using the delay actually measured at this
            # junction.  Cheap: no-op unless BXT is active and decisions are
            # pending.  This is what lets CellQLearn LEARN whether its cost
            # prices were wrong instead of us hand-tuning them.
            if getattr(_spm, 'BXT_MODE', False):
                try:
                    _spm._bxt_apply_pending_updates(self, time)
                except Exception:
                    pass
            # ── Closed-loop RL (CPD-QL): realized-advantage TD updates ────────
            if getattr(_spm, 'CPDQL_MODE', False):
                try:
                    _spm._cpdql_apply_pending_updates(self, time)
                except Exception:
                    pass

            # Periodic heartbeat (every 60 s) — controlled by LOG_HEARTBEAT flag
            if LOG_HEARTBEAT:
                _t60 = int(time) // 60
                if _t60 != getattr(self, '_last_log_min', -1):
                    self._last_log_min = _t60
                    log_to_file(
                        f"[HEARTBEAT] t={time:.0f}s inter={self.id} "
                        f"mode={CONTROL_MODE} phase={current_phase} "
                        f"flag={self.flag} TSPStrategy={self.TSPStrategy} "
                        f"TSPActiveTime={self.TSPActiveTime:.0f} "
                        f"BusPresence={self.BusPresence[0].tolist()} "
                        f"BusSpeed={[round(v,2) for v in self.BusSpeed[0].tolist()]} "
                        f"MaxQ={[round(v,1) for v in self.MaxQueueLength[0].tolist()]} "
                        f"UpFlow={[round(v,1) for v in self.UpFlowList[0].tolist()]}"
                    )

            if CONTROL_MODE == "NORMAL":
                self.run_normal(time, timeSta, acycle)

            elif CONTROL_MODE == "HARMONY":
                self.restore_phase_if_needed(time, timeSta, acycle)
                if time - self.last_tsp_action_time < self.tsp_cooldown_seconds:
                    if LOG_TSP_EVT and int(time) % 15 == 0:
                        _vprint(
                            f"[TSP COOLDOWN] inter={self.id} t={time:.1f} "
                            f"skipping HARMONY (remaining ~"
                            f"{self.tsp_cooldown_seconds-(time-self.last_tsp_action_time):.0f}s)")
                else:
                    _was_idle  = (self.TSPStrategy == 0)
                    tsp_active = self.check_bus_priority(time, timeSta, acycle)
                    if tsp_active and _was_idle:
                        self.last_tsp_action_time = time
                        if LOG_TSP_EVT:
                            _vprint(
                                f"[TSP] inter={self.id} HARMONY action t={time:.1f} "
                                f"next after {time+self.tsp_cooldown_seconds:.1f}s")

            elif CONTROL_MODE == "RL":
                tsp_active = self.check_bus_priority(time, timeSta, acycle)
                if not tsp_active:
                    self.run_rl(time, timeSta, acycle)
                self.restore_phase_if_needed(time, timeSta, acycle)

            elif CONTROL_MODE == "URTSP":
                if time - self.last_tsp_action_time < self.tsp_cooldown_seconds:
                    if LOG_TSP_EVT and int(time) % 10 == 0:
                        _vprint(
                            f"[TSP COOLDOWN] inter={self.id} t={time:.1f} "
                            f"skipping URTSP (remaining ~"
                            f"{self.tsp_cooldown_seconds-(time-self.last_tsp_action_time):.0f}s)")
                else:
                    self.run_urtsp(time, timeSta, acycle)

            elif CONTROL_MODE == "REWARD_TSP":
                self.run_reward_tsp(time, timeSta, acycle)

            elif CONTROL_MODE == "DRL_DENSITY":
                self.run_reward_tsp(time, timeSta, acycle)

        except Exception as e:
            stop_simulation(f"update crashed inter={self.id} t={time:.1f}: {e}")
            import traceback
            log_to_file(traceback.format_exc())
            return 0


    # ── HARMONY check_bus_priority kept intact below ──────────────────
    def check_bus_priority(self, time, timeSta, acycle):
        if time < self.TSPActiveTime:
            return False
        if self.flag != 0:
            return True
        # One TSP grant per cycle — prevents re-firing on the same bus
        if getattr(self, '_tsp_cycle_grant_until', -1.0) > time:
            return False
        # ── Viability gate (saturation/cross-pressure stand-down) ─────────
        # (see run_reward_tsp; prearm path below is covered)
        if not getattr(self, '_tsp_armed', True):
            return False

        # Read current phase ONCE — consistent across all detectors this step
        current_phase = ECIGetCurrentPhase(self.node_id)

        # Guard: negative phase means junction not under external control yet
        if current_phase < 0:
            # Log once per minute so we know this is happening
            _t60 = int(time) // 60
            if _t60 != getattr(self, '_last_phase_warn', -1):
                self._last_phase_warn = _t60
                log_to_file(
                    f"[WARN] inter={self.id} t={time:.0f}s ECIGetCurrentPhase={current_phase} "
                    f"— junction NOT under external control. "
                    f"Set junction signal control to 'External' in Aimsun model GUI "
                    f"(Properties → Signal Control → External API).")
            return False

        # ── Corridor pre-arm check (HARMONY coordination) ────────────────────
        # When the CorridorCoordinator has pre-armed this intersection, apply TSP
        # immediately using the Kalman ETA rather than waiting for local detector
        # presence. Bypasses harmony search — uses a fixed eta+buffer duration so
        # the bus is guaranteed to arrive during the granted phase.
        _prearm = getattr(self, '_harmony_prearm', None)
        if _prearm is not None and self.TSPStrategy == 0:
            _pa_veh, _pa_eta_t, _pa_issued_t, _pa_dir, _pa_from = _unpack_prearm(_prearm)
            if _pa_veh is None:
                self._harmony_prearm = None
                _pa_veh, _pa_eta_t, _pa_issued_t = -1, -1e9, -1e9
            _eta_from_now = _pa_eta_t - time
            def _notify_coord_prearm_consumed():
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        self._corridor_coord.notify_bus_granted(_pa_veh, self.id, time, None)
                    except Exception as _coord_e:
                        log_to_file(
                            f"[HARMONY COORD] notify_bus_granted failed "
                            f"inter={self.id} bus={_pa_veh}: {_coord_e}"
                        )
            # Clear stale or already-expired pre-arms.
            # Use a tight negative tolerance (-5 s) so that once the predicted
            # ETA has passed (bus should have arrived), the pre-arm is discarded
            # immediately and local Harmony detection is allowed to take over.
            # The old -20 s threshold created a deadlock window where the bus
            # was present but neither the pre-arm fired (eta < 0) nor local
            # Harmony ran (authority gate still active).
            _prearm_timeout_s = (
                float(getattr(self._corridor_coord, 'PRE_REQ_TIMEOUT_S', 90.0))
                if self._corridor_coord is not None else 90.0
            )
            if _eta_from_now < -5.0 or time - _pa_issued_t > _prearm_timeout_s:
                self._harmony_prearm = None
            elif 0.0 <= _eta_from_now <= getattr(self, '_eta_max_s', 90.0):
                # ── Fire immediately — no secondary hold ──────────────────────
                # The coordinator already accounts for PRE_GREEN_LEAD_S=50 s.
                # The old _PREARM_INS_WINDOW hold (≤ 35 s) wasted 15 s of setup
                # time and caused buses to arrive before the bus phase was ready.
                _prearm_dur = max(float(self.BP_lower_bound), _eta_from_now + 5.0)
                _prearm_dur = min(_prearm_dur, float(self.BP_upper_bound))
                self._harmony_prearm = None
                # Next-green feasibility (2026-09-26): grant only what the bus
                # phase can serve around the ETA (same gate as the reward-eval
                # path). Unservable prearms fail _prearm_cost_ok below, so BOTH
                # grant paths skip and the local gated decider takes over
                # (prearm already consumed above; the coordinator re-fires as
                # the ETA shrinks).
                _prearm_unserv = False
                try:
                    _serv2, _swhy2 = self._prearm_feasible(_eta_from_now, time, timeSta)
                    if not _serv2:
                        _prearm_unserv = True
                        log_to_file(
                            f"[PREARM FEASIBILITY] inter={self.id} t={time:.0f} "
                            f"bus={_pa_veh} eta={_eta_from_now:.0f}s dir={_pa_dir} "
                            f"from={_pa_from} SKIP unservable ({_swhy2})",
                            force=True)
                except Exception:
                    pass
                # ── (a) Cross-cost gate on the coordinator pre-arm ────────────
                # The GE/INS grant below holds green ~_prearm_dur s with NO
                # cross-street cost check -- the root cause of the coordinator
                # gridlocking cross traffic (591 un-gated grants/run).  Reuse the
                # RL's validated cross-cost model and fire only when the bus
                # pax-s the grant advances exceed the cross-street pax-s the hold
                # delays (v/c-scaled).  On skip we clear the pre-arm (done above)
                # and DON'T fire, so execution falls through to the local RL
                # decider, which applies its own cost check -- i.e. the un-gated
                # coordinator defers to the gated decider.  Fail OPEN: a cost
                # estimate error must never disable pre-arm.
                _prearm_cost_ok = (not _prearm_unserv)
                try:
                    _grant_dur   = float(_prearm_dur)
                    _bus_occ     = max(float(getattr(self, 'BusOcc', 40.0)), 1.0)
                    _min_grant   = float(globals().get('MIN_PREARM_GRANT_S', 3.0) or 3.0)
                    _margin      = float(globals().get('COORD_PREARM_COST_MARGIN', 1.0) or 1.0)
                    _bus_benefit = _grant_dur * _bus_occ
                    _cross_cost  = float(self._dctsp_cross_traffic_delay_s(_grant_dur))
                    if _grant_dur < _min_grant or _bus_benefit <= _cross_cost * _margin:
                        _prearm_cost_ok = False
                        log_to_file(
                            f"[PREARM COST GATE] inter={self.id} t={time:.1f} "
                            f"bus={_pa_veh} grant={_grant_dur:.1f}s "
                            f"benefit={_bus_benefit:.0f} cross_cost={_cross_cost:.0f} "
                            f"(x{_margin:.2f}) — SKIP, defer to local decider",
                            )
                        self._record_detection(time)
                        self.stats.record_tsp_skip(self.id, 'prearm_cost_gate')
                        _notify_coord_prearm_consumed()
                except Exception as _cg_e:
                    log_to_file(f"[PREARM COST GATE] inter={self.id} error: {_cg_e}")
                    _prearm_cost_ok = True
                if LOG_HARMONY:
                    _vprint(
                        f"[HARMONY PREARM FIRE] inter={self.id} t={time:.1f} "
                        f"bus={_pa_veh} eta={_eta_from_now:.1f}s "
                        f"dur={_prearm_dur:.1f}s phase={'GE' if current_phase == self.BusPhase else 'INS'}"
                    )
                if _prearm_cost_ok and current_phase == self.BusPhase:
                    # GE path — cap to MAX_GE_EXTENSION_S.
                    # If bus needs more extension than the hard cap, skip entirely.
                    _ge_needed = max(0.0, _eta_from_now + 5.0)
                    if _ge_needed > MAX_GE_EXTENSION_S:
                        if LOG_HARMONY:
                            _vprint(
                                f"[HARMONY COORD GE SKIP] inter={self.id} t={time:.1f} "
                                f"bus_eta={_eta_from_now:.1f}s needs GE={_ge_needed:.1f}s "
                                f"> MAX_GE={MAX_GE_EXTENSION_S:.0f}s — skipping")
                        self._record_detection(time)
                        self.stats.record_tsp_skip(self.id, 'ge_trivial')
                        _notify_coord_prearm_consumed()
                    else:
                        _prearm_dur = min(_prearm_dur, MAX_GE_EXTENSION_S)
                        # If the current phase already ends after the bus arrives, skip.
                        try:
                            _ps_start  = ECIGetStartingTimePhase(self.node_id)
                            _ph_dur    = GetPhaseDuration(self.node_id, current_phase, timeSta)
                            _remain    = max(0.0, _ph_dur - (time - _ps_start))
                            _next_red  = time + _remain
                            _bus_arr   = time + _eta_from_now
                            # (c) Min-bus-delay gate: skip when the bus makes the
                            # natural green OR would wait less than MIN_PREARM_BUS_DELAY_S
                            # beyond it -- a trivial red wait isn't worth disrupting
                            # cross traffic for.
                            _min_bus_delay = float(globals().get('MIN_PREARM_BUS_DELAY_S', 6.0) or 0.0)
                            if _bus_arr <= _next_red + _min_bus_delay:
                                # Bus will make the natural green (or wait < threshold) — no GE needed
                                log_to_file(
                                    f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                                    f"bus={_pa_veh} eta={_eta_from_now:.1f}s "
                                    f"type=NATURAL source=COORD_PREARM "
                                    f"(phase already green until {_next_red:.1f}s)",
                                    )
                                if LOG_HARMONY:
                                    _vprint(
                                        f"[HARMONY COORD GE SKIP] inter={self.id} t={time:.1f} "
                                        f"bus_arr={_bus_arr:.1f}s <= next_red={_next_red:.1f}s "
                                        f"— natural green, skipping pre-arm GE")
                                self._record_detection(time)
                                self.stats.record_tsp_skip(self.id, 'natural_green')
                                _notify_coord_prearm_consumed()
                            else:
                                _min_ge = float(globals().get('MIN_GE_EXTENSION_S', 3.0))
                                _prearm_dur = max(_prearm_dur, _min_ge)
                                ECIChangeTimingPhase(
                                    self.node_id, current_phase,
                                    self.BusPhaseDuration + _prearm_dur, timeSta)
                                self.TimeToTerminateBusPhase = time + _remain + _prearm_dur
                                self.TSPStrategy  = 1
                                self.flag         = 1
                                self.TSPActiveTime = time + _prearm_dur + float(globals().get('TSP_POST_GRANT_LOCK_S', 5.0))
                                self._tsp_cycle_grant_until = time + self.cycle_len_s
                                self.last_tsp_action_time   = time
                                self._ge_debt_s = _prearm_dur
                                self._ge_opt_GE = _prearm_dur
                                _ge_events.append((time, self.id, float(_prearm_dur), 0.0))
                                log_to_file(
                                    f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                                    f"bus={_pa_veh} eta={_eta_from_now:.1f}s "
                                    f"type=COORD_GE source=PREARM GE={_prearm_dur:.1f}s",
                                    )
                                if LOG_HARMONY:
                                    _vprint(
                                        f"[HARMONY COORD GE] inter={self.id} t={time:.1f} "
                                        f"prearm bus={_pa_veh} eta={_eta_from_now:.1f}s "
                                        f"GE={_prearm_dur:.1f}s")
                                self._record_detection(time)
                                self.stats.record_tsp_event(self.id, 'extension')
                                self.stats.record_tsp_extension_duration(self.id, float(_prearm_dur))
                                try:
                                    self._broadcast_timing_change(
                                        "GE", float(_prearm_dur), float(time),
                                        "prearm-exec", timeSta=timeSta,
                                        live_read=True)
                                except Exception:
                                    pass
                                _mark_detection_point(
                                    self.id, _pa_veh, 0.0, 0.0, time,
                                    "harmony-ge-prearm",
                                    {
                                        "force_write": True,
                                        "prearm_status": "action",
                                        "prearm_eta_s": round(max(0.0, float(_eta_from_now)), 1),
                                        "prearm_note": f"GE {float(_prearm_dur):.1f}s prearm",
                                    },
                                )
                                if _pa_veh and _pa_veh > 0:
                                    _acquire_focus(_pa_veh, self.id, time)
                                _notify_coord_prearm_consumed()
                                return True
                        except Exception as _e:
                            log_to_file(f"[HARMONY COORD GE] inter={self.id} failed: {_e}")
                elif _prearm_cost_ok:
                    # Insertion path — only insert if the bus will miss the next natural BusPhase.
                    try:
                        _ps_now     = ECIGetStartingTimePhase(self.node_id)
                        _elapsed    = max(0.0, time - _ps_now)
                        _rem_cur    = max(0.0,
                            GetPhaseDuration(self.node_id, current_phase, timeSta) - _elapsed)
                        _time_to_bp = _rem_cur
                        try:
                            _ci  = self.phase_list.index(current_phase)
                            _bi  = self.phase_list.index(self.BusPhase)
                            _n   = len(self.phase_list)
                            _steps = (_bi - _ci) % _n
                            for _k in range(1, _steps):
                                _ph = self.phase_list[(_ci + _k) % _n]
                                _time_to_bp += GetPhaseDuration(self.node_id, _ph, timeSta)
                        except Exception:
                            _time_to_bp = float(self.cycle_len_s)
                        _nat_end = _time_to_bp + self.BusPhaseDuration
                        # (c) Min-bus-delay gate: skip when the bus catches the
                        # natural bus phase OR would wait less than
                        # MIN_PREARM_BUS_DELAY_S beyond it.
                        _min_bus_delay = float(globals().get('MIN_PREARM_BUS_DELAY_S', 6.0) or 0.0)
                        if _eta_from_now <= _nat_end + _min_bus_delay:
                            # Bus will catch the natural BusPhase (or wait < threshold) — no insertion needed
                            log_to_file(
                                f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                                f"bus={_pa_veh} eta={_eta_from_now:.1f}s "
                                f"type=NATURAL source=COORD_PREARM "
                                f"(natural bus phase in {_time_to_bp:.1f}s)",
                                )
                            if LOG_HARMONY:
                                _vprint(
                                    f"[HARMONY COORD INS SKIP] inter={self.id} t={time:.1f} "
                                    f"eta={_eta_from_now:.1f}s <= natural_end={_nat_end:.1f}s "
                                    f"— no pre-arm insertion needed")
                            self._record_detection(time)
                            self.stats.record_tsp_skip(self.id, 'natural_green')
                            _notify_coord_prearm_consumed()
                        else:
                            _ins_wait_s = max(0.0, float(_eta_from_now))
                            self.previous_phase  = current_phase
                            # Hard cap on insertion duration + enforce minimum
                            _min_ins = float(globals().get('MIN_BP_INSERTION_S', 5.0))
                            _prearm_dur = max(_min_ins, min(_prearm_dur, MAX_BP_INSERTION_S))
                            self.BusPhaseEndTime = time + _prearm_dur
                            ECIChangeTimingPhase(self.id, self.BusPhase, _prearm_dur, timeSta)
                            ECIChangeDirectPhase(
                                self.id, self.BusPhase, timeSta, time, acycle, 0)
                            self.TSPStrategy  = 2
                            self.flag         = 2
                            self._ins_bus_phase_seen = False
                            self._ins_grant_time = time
                            self.TSPActiveTime = time + _prearm_dur + float(globals().get('TSP_POST_GRANT_LOCK_S', 5.0))
                            self._ge_debt_s   = float(_prearm_dur)  # cycle recovery
                            self._tsp_cycle_grant_until = time + self.cycle_len_s
                            self.last_tsp_action_time   = time
                            log_to_file(
                                f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                                f"bus={_pa_veh} eta={_eta_from_now:.1f}s "
                                f"type=COORD_INS source=PREARM BP={_prearm_dur:.1f}s",
                                )
                            if LOG_HARMONY:
                                _vprint(
                                    f"[HARMONY COORD INS] inter={self.id} t={time:.1f} "
                                    f"prearm bus={_pa_veh} eta={_eta_from_now:.1f}s "
                                    f"BP={_prearm_dur:.1f}s")
                            self._record_detection(time)
                            self.stats.record_tsp_event(self.id, 'insertion')
                            self.stats.record_tsp_insertion_duration(self.id, float(_prearm_dur))
                            self.stats.record_tsp_insertion_wait(self.id, _ins_wait_s)
                            try:
                                self._broadcast_timing_change(
                                    "INS", float(_prearm_dur), float(time),
                                    "prearm-exec", timeSta=timeSta,
                                    live_read=True)
                            except Exception:
                                pass
                            _mark_detection_point(
                                self.id, _pa_veh, 0.0, 0.0, time,
                                "harmony-ins-prearm",
                                {
                                    "force_write": True,
                                    "prearm_status": "action",
                                    "prearm_eta_s": round(max(0.0, float(_eta_from_now)), 1),
                                    "prearm_note": f"INS {float(_prearm_dur):.1f}s prearm",
                                },
                            )
                            if _pa_veh and _pa_veh > 0:
                                _acquire_focus(_pa_veh, self.id, time)
                            _notify_coord_prearm_consumed()
                            return True
                    except Exception as _e:
                        log_to_file(f"[HARMONY COORD INS] inter={self.id} failed: {_e}")

        # ── Pre-arm authority gate ────────────────────────────────────────────
        # If a coordinator pre-arm is still live (bus en route and ETA > -5s),
        # suppress ALL local detection so the pre-arm remains the sole TSP
        # trigger for this junction.  This prevents local Harmony Search from
        # inserting/extending independently while the wave is orchestrated by
        # the CorridorCoordinator.  The -5 s stale threshold above guarantees
        # the gate clears as soon as the bus has arrived (ETA < -5 s), so a
        # bus that arrives earlier than predicted falls through to local Harmony.
        _lingering = getattr(self, '_harmony_prearm', None)
        if _lingering is not None:
            if LOG_HARMONY:
                _lpa_veh, _lpa_eta_t, _, _, _ = _unpack_prearm(_lingering)
                try:
                    _lp_eta_rem = float(_lpa_eta_t) - time
                except Exception:
                    _lp_eta_rem = float('nan')
                _t60 = int(time) // 60
                if _t60 != getattr(self, '_prearm_gate_warn_t', -1):
                    self._prearm_gate_warn_t = _t60
                    _vprint(
                        f"[PREARM GATE] inter={self.id} t={time:.1f} "
                        f"bus={_lpa_veh} eta_rem={_lp_eta_rem:.1f}s — local detection suppressed")
            return False

        # ── TSP state snapshot (once per check, not per detector) ─────────────
        _diag_every = getattr(self, '_tsp_diag_t', -1)
        if int(time) != _diag_every:
            self._tsp_diag_t = int(time)
            _main_secs = self.incoming_sections
            _sec_info = []
            for _s in _main_secs:
                try:
                    _nv = AKIVehStateGetNbVehiclesSection(_s, False)
                    _sl = float(AKIInfNetGetSectionANGInf(_s).length)
                    _sec_info.append(f"sec={_s} n={_nv} len={_sl:.0f}m")
                except Exception as _e:
                    _sec_info.append(f"sec={_s} err={_e}")
            log_to_file(
                f"[TSP_DIAG] inter={self.id} t={time:.1f} "
                f"phase={ECIGetCurrentPhase(self.node_id)} flag={self.flag} "
                f"TSPStrat={self.TSPStrategy} "
                f"BusPresence={self.BusPresence[0].tolist()} "
                f"BusSpeed={[round(v,2) for v in self.BusSpeed[0].tolist()]} "
                f"UpFlow={[round(float(v),1) for v in self.UpFlowList[0].tolist()]} "
                f"UpDen={[round(float(v),2) for v in self.UpDenList[0].tolist()]} "
                f"MaxQ={[round(float(v),1) for v in self.MaxQueueLength[0].tolist()]} "
                f"RedDur={[round(float(v),1) for v in self.RedDurationList[0].tolist()]} "
                f"sections={_sec_info}"
            )

        # ── Approach-level debounce for detection STATISTICS ─────────────────
        # TSP *actions* (GE, insertion) fire regardless; only stat recording
        # is debounced so skip/detection counts reflect unique bus approaches
        # rather than every simulation step.  Debounce window = 30 s (roughly
        # one signal cycle).  Reset when a new bus is seen at this junction.
        _approach_debounce_s = 30.0
        _det_vid_now = self.last_detected_bus_id
        if _det_vid_now and _det_vid_now > 0:
            _last_rec_t = self._approach_det_t.get(_det_vid_now, -999.0)
            if (time - _last_rec_t) < _approach_debounce_s:
                # Already recorded stats for this bus approach recently.
                _detection_recorded_this_call = True   # suppress further stat writes
            else:
                self._approach_det_t[_det_vid_now] = time
                _detection_recorded_this_call = False
        else:
            _detection_recorded_this_call = False

        # Each detector slot may fire in the same call — count detection only once.
        _coord_notified_this_call = False

        def _notify_coord_bus_progress(veh_id: int, reason: str):
            """Propagate downstream coordination even when local action is natural green."""
            nonlocal _coord_notified_this_call
            if _coord_notified_this_call:
                return
            if self._corridor_coord is None or not COORDINATED_TSP:
                return
            try:
                self._corridor_coord.notify_bus_granted(veh_id, self.id, time, None)
                _coord_notified_this_call = True
                if LOG_CORRIDOR:
                    _vprint(
                        f"[HARMONY COORD] inter={self.id} t={time:.1f} "
                        f"bus={veh_id} propagated ({reason})"
                    )
            except Exception as _coord_e:
                log_to_file(
                    f"[HARMONY COORD] notify_bus_granted failed "
                    f"inter={self.id} bus={veh_id} reason={reason}: {_coord_e}"
                )

        def _log_local_decision(_tier: str, _note: str, _eta_s: float | None = None):
            """Write one debounced decision row so the dashboard can show it."""
            _vid = int(self.last_detected_bus_id or -1)
            if _vid <= 0:
                return
            if not hasattr(self, '_last_local_decision_log_t'):
                self._last_local_decision_log_t = {}
            _key = (_vid, _tier, _note)
            _last_t = self._last_local_decision_log_t.get(_key, -9999.0)
            if time - _last_t < 1.0:
                return
            self._last_local_decision_log_t[_key] = float(time)
            _meta = {
                "force_write": True,
                "prearm_status": "decision",
                "prearm_note": _note,
            }
            if _eta_s is not None:
                try:
                    _meta["prearm_eta_s"] = round(max(0.0, float(_eta_s)), 1)
                except Exception:
                    pass
            _mark_detection_point(self.id, _vid, 0.0, 0.0, time, _tier, _meta)

        def _fmt_noins_reason(_base: str, **_vals) -> str:
            """Compact, parseable reason string for NO_INS / NO_GE diagnostics."""
            _parts = [_base]
            for _k, _v in _vals.items():
                try:
                    if isinstance(_v, float):
                        _parts.append(f"{_k}={_v:.1f}")
                    else:
                        _parts.append(f"{_k}={_v}")
                except Exception:
                    _parts.append(f"{_k}=na")
            return " | ".join(_parts)

        def _trace_objective(_mode: str, _decision: str, _reason: str,
                             _bus_eta_s=None, _time_to_bp_s=None, _natural_end_s=None,
                             _next_red_s=None, _ge_lb_s=None, _ge_ub_s=None, _opt_ge_s=None,
                             _bp_lb_s=None, _bp_ub_s=None, _opt_bp_s=None, _note=""):
            # ── Validate bounds are reasonable before logging ──
            # GE window should never exceed MAX_GE_EXTENSION_S (10s hard cap)
            if _ge_ub_s is not None:
                _ge_ub_s = min(float(_ge_ub_s), MAX_GE_EXTENSION_S)
            if _ge_lb_s is not None and _ge_ub_s is not None:
                _ge_lb_s = min(float(_ge_lb_s), _ge_ub_s)
            # BP window should be reasonable (upper bound capped at MAX_BP_INSERTION_S)
            if _bp_ub_s is not None:
                _bp_ub_s = min(float(_bp_ub_s), MAX_BP_INSERTION_S)
            if _bp_lb_s is not None and _bp_ub_s is not None:
                _bp_lb_s = min(float(_bp_lb_s), _bp_ub_s)
            
            _record_objective_trace({
                "sim_time_s": round(float(time), 1),
                "junction_id": int(self.id),
                "veh_id": int(self.last_detected_bus_id or -1),
                "mode": str(_mode),
                "decision": str(_decision),
                "reason": str(_reason),
                "current_phase": int(current_phase),
                "bus_phase": int(self.BusPhase),
                "bus_eta_s": (round(float(_bus_eta_s), 3) if _bus_eta_s is not None else ""),
                "time_to_bp_s": (round(float(_time_to_bp_s), 3) if _time_to_bp_s is not None else ""),
                "natural_end_s": (round(float(_natural_end_s), 3) if _natural_end_s is not None else ""),
                "next_red_s": (round(float(_next_red_s), 3) if _next_red_s is not None else ""),
                "ge_lb_s": (round(float(_ge_lb_s), 3) if _ge_lb_s is not None else ""),
                "ge_ub_s": (round(float(_ge_ub_s), 3) if _ge_ub_s is not None else ""),
                "opt_ge_s": (round(float(_opt_ge_s), 3) if _opt_ge_s is not None else ""),
                "bp_lb_s": (round(float(_bp_lb_s), 3) if _bp_lb_s is not None else ""),
                "bp_ub_s": (round(float(_bp_ub_s), 3) if _bp_ub_s is not None else ""),
                "opt_bp_s": (round(float(_opt_bp_s), 3) if _opt_bp_s is not None else ""),
                "wave_active": int(bool(self._corridor_coord and getattr(self._corridor_coord, '_wave_active', False))),
                "focus_bus_id": int(_focus_bus_id if _focus_bus_id > 0 else -1),
                "note": str(_note or ""),
            })

        # Iterate at least 1 slot: detect_bus() populates index 0 of
        # BusPresence/BusSpeed even when BusDet is empty (no physical detectors).
        _n_det_slots = max(len(self.BusDet), 1)
        for i in range(_n_det_slots):
            bus_speed = self.BusSpeed[0][i]
            if bus_speed <= 0:
                continue

            # ── Global bus focus gate ─────────────────────────────────────────
            _det_vid = self.last_detected_bus_id
            if _det_vid and _det_vid > 0 and _is_focus_blocked(_det_vid, self.id, time):
                if LOG_HARMONY:
                    _vprint(
                        f"[BUS_FOCUS] t={time:.1f} inter={self.id} "
                        f"v={_det_vid} SUPPRESSED — focus bus={_focus_bus_id}")
                _mark_detection_point(self.id, _det_vid, 0.0, 0.0,
                                      time, "focus_suppress")
                if not _detection_recorded_this_call:
                    self._record_detection(time)
                    _detection_recorded_this_call = True
                continue

            if current_phase == self.BusPhase:
                red_start        = self.RedStartTimeList[0][i]
                _ps = ECIGetStartingTimePhase(self.node_id)
                _pd = GetPhaseDuration(self.node_id, current_phase, timeSta)
                next_red_start = _ps + _pd
                # Use live remaining distance from ETA tracker if available
                eta_info   = getattr(self, '_bus_eta', {}).get(i)
                _det_dist_fallback = (
                    self.config["DetDistance"][0][i]
                    if self.config.get("DetDistance") and len(self.config["DetDistance"]) > 0
                       and i < len(self.config["DetDistance"][0])
                    else 200.0   # default ~200m upstream detection
                )
                live_dist  = eta_info[2] if eta_info else _det_dist_fallback

                bus_stopline_time = time + live_dist / bus_speed

                if bus_stopline_time <= next_red_start:
                    # Bus will naturally clear on green — no TSP action needed
                    if not _detection_recorded_this_call:
                        self._record_detection(time)
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'natural_green')
                    _log_local_decision(
                        "harmony-no-ge-local",
                        "NO_GE natural_green_current_phase",
                        bus_stopline_time - time,
                    )
                    _notify_coord_bus_progress(self.last_detected_bus_id, 'natural_green_current_phase')
                    log_to_file(
                        f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                        f"bus={self.last_detected_bus_id} "
                        f"type=NATURAL source=LOCAL "
                        f"(phase green until {next_red_start:.1f}s bus_arr={bus_stopline_time:.1f}s)",
                        )
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] NAT_GREEN | inter={self.id} "
                            f"bus_arr={bus_stopline_time:.1f}s < red={next_red_start:.1f}s "
                            f"— no action needed")
                    _trace_objective(
                        "GE", "SKIP", "natural_green_current_phase",
                        _bus_eta_s=(bus_stopline_time - time),
                        _next_red_s=(next_red_start - time),
                    )
                    continue

                if bus_stopline_time > next_red_start and self.TSPStrategy == 0:
                    GE_lb = bus_stopline_time - next_red_start

                    # ── Hard cap: skip if bus needs more extension than allowed ─
                    if GE_lb > MAX_GE_EXTENSION_S:
                        if LOG_HARMONY:
                            _vprint(
                                f"[HARMONY] GE SKIP | inter={self.id} "
                                f"needed={GE_lb:.1f}s > MAX_GE={MAX_GE_EXTENSION_S:.0f}s "
                                f"— bus too far, skipping extension")
                        if not _detection_recorded_this_call:
                            self._record_detection(time)
                            _detection_recorded_this_call = True
                        self.stats.record_tsp_skip(self.id, 'ge_trivial')
                        _trace_objective(
                            "GE", "SKIP", "over_max_extension",
                            _bus_eta_s=(bus_stopline_time - time),
                            _next_red_s=(next_red_start - time),
                            _ge_lb_s=GE_lb,
                            _ge_ub_s=min(float(self.GE_upper_bound), MAX_GE_EXTENSION_S),
                        )
                        _log_local_decision(
                            "harmony-no-ge-local",
                            "NO_GE over_max_extension",
                            bus_stopline_time - time,
                        )
                        continue

                    _ge_ub = min(float(self.GE_upper_bound), MAX_GE_EXTENSION_S)

                    # Block local Harmony Search while coordinator wave is active.
                    # The wave manages this junction's TSP via the pre-arm mechanism.
                    if self._corridor_coord is not None and COORDINATED_TSP:
                        _wave_bus = int(getattr(self._corridor_coord, '_wave_veh_id', -1) or -1)
                        _this_bus = int(self.last_detected_bus_id or -1)
                        if self._corridor_coord._wave_active and _wave_bus > 0 and _wave_bus != _this_bus:
                            return False

                    opt_GE = _solve_timing_min(
                        self, self.GE_Objective_Function, GE_lb, _ge_ub, time)
                    if math.isnan(opt_GE) or opt_GE < 0:
                        opt_GE = min(10.0, _ge_ub)

                    # Hard-cap result to MAX_GE_EXTENSION_S
                    opt_GE = min(opt_GE, MAX_GE_EXTENSION_S)
                    # Enforce minimum GE if applied
                    _min_ge = float(globals().get('MIN_GE_EXTENSION_S', 3.0))
                    if opt_GE > 0 and opt_GE < _min_ge:
                        opt_GE = _min_ge

                    # ── Cap GE to what this cycle can actually recover ──────────
                    # Prevents granting 28 s of GE when the remaining phases
                    # only have 5 s of combined headroom — which would leave a
                    # massive irrecoverable debt and inflate cycle length.
                    _min_floor_ge  = float(self.config.get('MinGreen', 5.0))
                    _max_trim_frac = 0.50
                    _phase_list    = getattr(self, 'phase_list', [])
                    if _phase_list and current_phase in _phase_list:
                        _ci = _phase_list.index(current_phase)
                        _n  = len(_phase_list)
                        _upcoming_ge = [
                            _phase_list[(_ci + _k) % _n]
                            for _k in range(1, _n)
                        ]
                        _upcoming_ge = [
                            p for p in _upcoming_ge
                            if p != self.BusPhase and p != current_phase
                        ]
                        _recoverable = 0.0
                        for _ph in _upcoming_ge:
                            _nom = self._nominal_phase_durations.get(_ph)
                            if _nom is None:
                                try:
                                    _nom = GetPhaseDuration(self.node_id, _ph, timeSta)
                                except Exception:
                                    _nom = 15.0
                                if not _nom or _nom <= 0:
                                    _nom = 15.0
                            _nom = max(float(_nom), _min_floor_ge)
                            _hr  = max(0.0, _nom - _min_floor_ge)
                            _hr  = min(_hr, _nom * _max_trim_frac)
                            _recoverable += _hr
                        if _recoverable > 0.5 and opt_GE > _recoverable:
                            if LOG_HARMONY:
                                _vprint(
                                    f"[HARMONY] GE cap | inter={self.id} "
                                    f"opt_GE={opt_GE:.1f}s → capped to "
                                    f"{_recoverable:.1f}s (cycle headroom limit)"
                                )
                            opt_GE = _recoverable

                    # After capping: verify extension is still sufficient to guarantee the bus
                    # makes the light. If the recoverable headroom is less than the minimum
                    # needed (GE_lb = bus_stopline_time − next_red_start), applying an
                    # insufficient extension is worse than no action — skip it instead.
                    if opt_GE < GE_lb:
                        if LOG_HARMONY:
                            _vprint(
                                f"[HARMONY] GE SKIP | inter={self.id} "
                                f"capped_GE={opt_GE:.1f}s < needed={GE_lb:.1f}s "
                                f"(cycle headroom {_recoverable:.1f}s insufficient "
                                f"— bus cannot be guaranteed through the light)")
                        if not _detection_recorded_this_call:
                            self._record_detection(time)
                            _detection_recorded_this_call = True
                        self.stats.record_tsp_skip(self.id, 'ge_trivial')
                        _trace_objective(
                            "GE", "SKIP", "insufficient_cycle_headroom",
                            _bus_eta_s=(bus_stopline_time - time),
                            _next_red_s=(next_red_start - time),
                            _ge_lb_s=GE_lb,
                            _ge_ub_s=_ge_ub,
                            _opt_ge_s=opt_GE,
                            _note=f"recoverable={_recoverable:.2f}",
                        )
                        _log_local_decision(
                            "harmony-no-ge-local",
                            "NO_GE insufficient_cycle_headroom",
                            bus_stopline_time - time,
                        )
                        continue

                    # Skip if harmony says extension is trivially small (below minimum)
                    _min_ge = float(globals().get('MIN_GE_EXTENSION_S', 3.0))
                    if opt_GE < _min_ge:
                        if LOG_HARMONY:
                            _vprint(
                                f"[HARMONY] GE skip | inter={self.id} "
                                f"opt_GE={opt_GE:.2f}s < MIN_GE={_min_ge:.1f}s — no action")
                        if not _detection_recorded_this_call:
                            self._record_detection(time)
                            _detection_recorded_this_call = True
                        self.stats.record_tsp_skip(self.id, 'ge_trivial')
                        _trace_objective(
                            "GE", "SKIP", "not_optimal",
                            _bus_eta_s=(bus_stopline_time - time),
                            _next_red_s=(next_red_start - time),
                            _ge_lb_s=GE_lb,
                            _ge_ub_s=_ge_ub,
                            _opt_ge_s=opt_GE,
                        )
                        _log_local_decision(
                            "harmony-no-ge-local",
                            "NO_GE not_optimal",
                            bus_stopline_time - time,
                        )
                        # Log wave event: bus detected, harmony evaluated GE but not beneficial
                        _grp = self._corridor_coord.name if self._corridor_coord else "local"
                        _record_wave_event(
                            time, _grp, "tsp_skip",
                            source_jct=self.id, target_jct=self.id,
                            veh_id=self.last_detected_bus_id or -1,
                            note="ge_not_optimal",
                        )
                        continue

                    remain = GetPhaseDuration(self.node_id, current_phase, timeSta) \
                             - (time - ECIGetStartingTimePhase(self.node_id))
                    ECIChangeTimingPhase(self.node_id, current_phase,
                                         self.BusPhaseDuration + float(opt_GE), timeSta)
                    self.TimeToTerminateBusPhase = time + remain + opt_GE
                    self.TSPStrategy = 1
                    self.flag        = 1
                    self.TSPActiveTime = time + float(opt_GE) + 30
                    self._tsp_cycle_grant_until = time + self.cycle_len_s
                    # Record the cycle debt so restore_phase_if_needed can
                    # spread the recovery across remaining phases.
                    self._ge_debt_s = float(opt_GE)
                    self._ge_opt_GE = float(opt_GE)
                    _ge_events.append((time, self.id, float(opt_GE), 0.0))
                    log_to_file(
                        f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                        f"bus={self.last_detected_bus_id} "
                        f"eta={bus_stopline_time - time:.1f}s "
                        f"type=LOCAL_GE source=LOCAL GE={opt_GE:.1f}s",
                        )
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] GE | t={time:.1f}s inter={self.id} "
                            f"bus_eta={bus_stopline_time - time:.1f}s "
                            f"next_red={next_red_start - time:.1f}s "
                            f"opt_GE={opt_GE:.1f}s")
                    _trace_objective(
                        "GE", "ACTION", "grant_extension",
                        _bus_eta_s=(bus_stopline_time - time),
                        _next_red_s=(next_red_start - time),
                        _ge_lb_s=GE_lb,
                        _ge_ub_s=_ge_ub,
                        _opt_ge_s=opt_GE,
                    )
                    self.highlight_bus(self.last_detected_bus_id)
                    if not _detection_recorded_this_call:
                        self._record_detection(time)
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_event(self.id, 'extension')
                    self.stats.record_tsp_extension_duration(self.id, float(opt_GE))
                    _mark_detection_point(
                        self.id, self.last_detected_bus_id, 0.0, 0.0, time,
                        "harmony-ge-local",
                        {
                            "force_write": True,
                            "prearm_status": "action",
                            "prearm_eta_s": round(max(0.0, float(bus_stopline_time - time)), 1),
                            "prearm_note": f"GE {float(opt_GE):.1f}s local",
                        },
                    )
                    # Acquire global bus focus
                    if self.last_detected_bus_id and self.last_detected_bus_id > 0:
                        _acquire_focus(self.last_detected_bus_id, self.id, time)
                    # Notify corridor coordinator so it can Kalman-predict and
                    # pre-arm downstream intersections (HARMONY coordination).
                    if self._corridor_coord is not None and COORDINATED_TSP:
                        try:
                            self._corridor_coord.notify_bus_granted(
                                self.last_detected_bus_id, self.id, time, None)
                        except Exception:
                            pass
                    return True

            else:
                # ── Phase insertion need assessment ────────────────────────
                # Theory: only insert if bus will MISS the next natural BusPhase
                # green. Compute time from now to the natural next BusPhase start.
                bus_approaching = (
                    self.BusPresence[0][i] == 1
                    and bus_speed > 0
                )
                if not (current_phase in self.PhaseIndex
                        and bus_approaching
                        and self.TSPStrategy == 0):
                    continue

                # Time remaining in current phase
                _ps_now        = ECIGetStartingTimePhase(self.node_id)
                _elapsed       = max(0.0, time - _ps_now)
                _rem_current   = max(0.0,
                    GetPhaseDuration(self.node_id, current_phase, timeSta) - _elapsed)

                # Walk phase sequence from current to BusPhase
                _time_to_bp = _rem_current
                try:
                    _ci  = self.phase_list.index(current_phase)
                    _bi  = self.phase_list.index(self.BusPhase)
                    _n   = len(self.phase_list)
                    _steps = (_bi - _ci) % _n  # phases between current+1 and BusPhase
                    for _k in range(1, _steps):
                        _ph = self.phase_list[(_ci + _k) % _n]
                        _time_to_bp += GetPhaseDuration(self.node_id, _ph, timeSta)
                except (ValueError, Exception):
                    _time_to_bp = float(self.cycle_len_s)

                # Bus ETA to stopline (seconds from now)
                _eta_info  = getattr(self, '_bus_eta', {}).get(i)
                _det_dist_fb = (
                    self.config['DetDistance'][0][i]
                    if self.config.get('DetDistance') and len(self.config['DetDistance']) > 0
                       and i < len(self.config['DetDistance'][0])
                    else 200.0
                )
                _bus_eta_s = _eta_info[1] if _eta_info else (_det_dist_fb / bus_speed)
                _bus_eta_effective_s = _bus_eta_s + float(INS_CLEARANCE_BUFFER_S)

                if LOG_HARMONY:
                    _vprint(
                        f"[INS DEBUG] inter={self.id} bus={self.last_detected_bus_id} "
                        f"eta={_bus_eta_s:.1f}s eta_eff={_bus_eta_effective_s:.1f}s "
                        f"(clr_buf={INS_CLEARANCE_BUFFER_S:.1f}s) to_bp={_time_to_bp:.1f}s "
                        f"bp_dur={self.BusPhaseDuration:.1f}s curr_phase={current_phase} "
                        f"bus_phase={self.BusPhase} strat={self.TSPStrategy}"
                    )

                # Insert when either:
                #  1) bus misses natural bus-phase window, OR
                #  2) bus would wait too long for next natural bus-phase start.
                _natural_bus_end = _time_to_bp + self.BusPhaseDuration
                _ins_trigger_margin_s = float(INS_TRIGGER_MARGIN_S)
                try:
                    _ins_trigger_margin_s = max(
                        float(INS_TRIGGER_MARGIN_MIN_S),
                        min(float(INS_TRIGGER_MARGIN_MAX_S),
                            float(INS_TRIGGER_MARGIN_S) + 0.15 * max(float(_bus_eta_s), 0.0))
                    )
                except Exception:
                    _ins_trigger_margin_s = float(INS_TRIGGER_MARGIN_S)
                _ins_trigger_threshold = _natural_bus_end - _ins_trigger_margin_s
                _wait_to_natural_s = max(0.0, _time_to_bp - _bus_eta_effective_s)
                _miss_natural_window = (_bus_eta_effective_s > _ins_trigger_threshold)
                _wait_too_long = (_wait_to_natural_s > float(INS_MAX_WAIT_TRIGGER_S))

                if (not _miss_natural_window) and (not _wait_too_long):
                    # Bus can catch the natural green — no insertion needed
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] NO INSERT inter={self.id} "
                            f"bus_eta_eff={_bus_eta_effective_s:.1f}s <= "
                            f"threshold={_ins_trigger_threshold:.1f}s "
                            f"wait_to_bp={_wait_to_natural_s:.1f}s <= wait_thr={INS_MAX_WAIT_TRIGGER_S:.1f}s "
                            f"(natural_end={_natural_bus_end:.1f}s margin={_ins_trigger_margin_s:.1f}s) "
                            f"(to_bp={_time_to_bp:.1f}s + dur={self.BusPhaseDuration:.1f}s)")
                    if not _detection_recorded_this_call:
                        self._record_detection(time)
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'natural_green')
                    _noins_note = _fmt_noins_reason(
                        "NO_INS natural_green_future_bus_phase",
                        eta_s=float(_bus_eta_s),
                        to_bp_s=float(_time_to_bp),
                        nat_end_s=float(_natural_bus_end),
                        bp_dur_s=float(self.BusPhaseDuration),
                    )
                    _log_local_decision(
                        "harmony-no-ins-local",
                        _noins_note,
                        _bus_eta_s,
                    )
                    if LOG_HARMONY:
                        _vprint(f"[HARMONY NO_INS] inter={self.id} {_noins_note}")
                    _trace_objective(
                        "INS", "SKIP", "natural_green_future_bus_phase",
                        _bus_eta_s=_bus_eta_s,
                        _time_to_bp_s=_time_to_bp,
                        _natural_end_s=_natural_bus_end,
                        _bp_lb_s=float(self.BP_lower_bound),
                        _bp_ub_s=float(self.BP_upper_bound),
                        _opt_bp_s=None,  # No optimization performed, skipped
                        _note=(
                            f"eta_eff={_bus_eta_effective_s:.1f};"
                            f"wait_to_bp={_wait_to_natural_s:.1f};"
                            f"wait_thr={INS_MAX_WAIT_TRIGGER_S:.1f}"
                        ),
                    )
                    _notify_coord_bus_progress(self.last_detected_bus_id, 'natural_green_future_bus_phase')
                    continue

                # Bus misses natural window OR wait is too long → evaluate insertion.
                if LOG_HARMONY:
                    _trigger_reason = (
                        "miss_natural_window" if _miss_natural_window else "wait_too_long"
                    )
                    _vprint(
                        f"[INS DEBUG] evaluate INS inter={self.id} bus={self.last_detected_bus_id} "
                        f"eta_eff={_bus_eta_effective_s:.1f}s > threshold={_ins_trigger_threshold:.1f}s "
                        f"(natural_end={_natural_bus_end:.1f}s margin={_ins_trigger_margin_s:.1f}s) "
                        f"wait_to_bp={_wait_to_natural_s:.1f}s reason={_trigger_reason}"
                    )
                # ── Prefer natural phase completion ───────────────────
                # If the current phase is nearly done (< 8s remaining),
                # defer the insertion to the natural transition — this
                # avoids abruptly cutting a phase that's about to end
                # and reduces disruption to other traffic.
                _NATURAL_COMPLETION_THRESHOLD = 8.0
                if _rem_current <= _NATURAL_COMPLETION_THRESHOLD and _rem_current > 0.5:
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] INS DEFER | inter={self.id} "
                            f"phase_rem={_rem_current:.1f}s < {_NATURAL_COMPLETION_THRESHOLD:.0f}s "
                            f"— waiting for natural phase completion")
                    continue  # will re-evaluate next step when phase transitions

                # The lower bound must guarantee the bus will arrive and clear
                # during the inserted phase: use bus ETA + 2 s headway buffer.
                # If even this minimum exceeds the upper bound, the bus is too far
                # away for a practical insertion — skip rather than insert too short.
                _bp_lb_effective = max(float(self.BP_lower_bound), _bus_eta_s + 2.0)
                if _bp_lb_effective >= float(self.BP_upper_bound):
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] INS SKIP | inter={self.id} "
                            f"bus_eta={_bus_eta_s:.1f}s → lb={_bp_lb_effective:.1f}s "
                            f">= BP_upper={self.BP_upper_bound:.0f}s "
                            f"— insertion impractical (bus too far away)")
                    if not _detection_recorded_this_call:
                        self._record_detection(time)
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'ins_trivial')
                    _noins_note = _fmt_noins_reason(
                        "NO_INS impractical_upper_bound",
                        eta_s=float(_bus_eta_s),
                        lb_s=float(_bp_lb_effective),
                        ub_s=float(self.BP_upper_bound),
                    )
                    _log_local_decision(
                        "harmony-no-ins-local",
                        _noins_note,
                        _bus_eta_s,
                    )
                    if LOG_HARMONY:
                        _vprint(f"[HARMONY NO_INS] inter={self.id} {_noins_note}")
                    _trace_objective(
                        "INS", "SKIP", "impractical_upper_bound",
                        _bus_eta_s=_bus_eta_s,
                        _time_to_bp_s=_time_to_bp,
                        _natural_end_s=_natural_bus_end,
                        _bp_lb_s=_bp_lb_effective,
                        _bp_ub_s=float(self.BP_upper_bound),
                        _opt_bp_s=None,  # No optimization performed, bus too far
                    )
                    continue

                # Block local Harmony Search while coordinator wave is active.
                if self._corridor_coord is not None and COORDINATED_TSP:
                    _wave_bus = int(getattr(self._corridor_coord, '_wave_veh_id', -1) or -1)
                    _this_bus = int(self.last_detected_bus_id or -1)
                    if self._corridor_coord._wave_active and _wave_bus > 0 and _wave_bus != _this_bus:
                        return False

                opt_BP = _solve_timing_min(
                    self, self.BP_Objective_Function, _bp_lb_effective,
                    self.BP_upper_bound, time)

                # Skip if harmony says insertion phase is trivially short.
                # Special handling when BP_lower_bound=0 ("don't apply" option):
                #  • Lower bound becomes max(0, _bus_eta_s + 2.0)
                #  • If opt_BP < 10s and BP_lower_bound=0, treat as "not optimal" since
                #    we have the option to not insert, and short insertions are wasteful.
                _bp_min_viable = max(0.1, float(self.BP_lower_bound) - 0.5)
                _bp_lb_config = float(self.BP_lower_bound)
                
                if math.isnan(opt_BP):
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] INS skip | inter={self.id} "
                            f"opt_BP=NaN — harmony search failed")
                    if not _detection_recorded_this_call:
                        self._record_detection(time)
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'ins_trivial')
                    _noins_note = _fmt_noins_reason(
                        "NO_INS not_optimal",
                        eta_s=float(_bus_eta_s),
                        lb_s=float(_bp_lb_effective),
                        ub_s=float(self.BP_upper_bound),
                        opt_bp_s=-1.0,
                    )
                    _log_local_decision(
                        "harmony-no-ins-local",
                        _noins_note,
                        _bus_eta_s,
                    )
                    if LOG_HARMONY:
                        _vprint(f"[HARMONY NO_INS] inter={self.id} {_noins_note}")
                    _trace_objective(
                        "INS", "SKIP", "harmony_nan",
                        _bus_eta_s=_bus_eta_s,
                        _time_to_bp_s=_time_to_bp,
                        _natural_end_s=_natural_bus_end,
                        _bp_lb_s=_bp_lb_effective,
                        _bp_ub_s=float(self.BP_upper_bound),
                        _opt_bp_s=opt_BP,  # Log the NaN result
                    )
                    continue
                
                # Clamp to effective bounds
                opt_BP_clamped = max(float(_bp_lb_effective), min(float(opt_BP), float(self.BP_upper_bound)))
                
                # ── Skip if result is too short (below minimum) ──
                _min_ins = float(globals().get('MIN_BP_INSERTION_S', 5.0))
                if _bp_lb_config <= 0.0 and opt_BP_clamped < max(10.0, _min_ins):
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] INS skip | inter={self.id} "
                            f"opt_BP={opt_BP_clamped:.2f}s < max(10s, MIN_INS={_min_ins:.1f}s) "
                            f"with BP_lower_bound=0 — not optimal")
                    if not _detection_recorded_this_call:
                        self._record_detection(time)
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'ins_trivial')
                    _noins_note = _fmt_noins_reason(
                        "NO_INS too_short",
                        eta_s=float(_bus_eta_s),
                        lb_s=0.0,
                        opt_bp_s=float(opt_BP),
                    )
                    _log_local_decision(
                        "harmony-no-ins-local",
                        _noins_note,
                        _bus_eta_s,
                    )
                    if LOG_HARMONY:
                        _vprint(f"[HARMONY NO_INS] inter={self.id} {_noins_note}")
                    _trace_objective(
                        "INS", "SKIP", "not_optimal_too_short",
                        _bus_eta_s=_bus_eta_s,
                        _time_to_bp_s=_time_to_bp,
                        _natural_end_s=_natural_bus_end,
                        _bp_lb_s=0.0,  # Show that no insertion was option
                        _bp_ub_s=float(self.BP_upper_bound),
                        _opt_bp_s=float(opt_BP),
                    )
                    continue
                
                if opt_BP_clamped < _bp_min_viable:
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] INS skip | inter={self.id} "
                            f"opt_BP={opt_BP:.2f}s → clamped={opt_BP_clamped:.2f}s < {_bp_min_viable:.2f}s — below viable")
                    if not _detection_recorded_this_call:
                        self._record_detection(time)
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'ins_trivial')
                    _noins_note = _fmt_noins_reason(
                        "NO_INS not_optimal",
                        eta_s=float(_bus_eta_s),
                        lb_s=float(_bp_lb_effective),
                        ub_s=float(self.BP_upper_bound),
                        opt_bp_s=float(opt_BP),
                    )
                    _log_local_decision(
                        "harmony-no-ins-local",
                        _noins_note,
                        _bus_eta_s,
                    )
                    if LOG_HARMONY:
                        _vprint(f"[HARMONY NO_INS] inter={self.id} {_noins_note}")
                    _trace_objective(
                        "INS", "SKIP", "not_optimal",
                        _bus_eta_s=_bus_eta_s,
                        _time_to_bp_s=_time_to_bp,
                        _natural_end_s=_natural_bus_end,
                        _bp_lb_s=_bp_lb_effective,
                        _bp_ub_s=float(self.BP_upper_bound),
                        _opt_bp_s=float(opt_BP),
                    )
                    continue

                # Use clamped value for phase insertion
                opt_BP = opt_BP_clamped

                # Hard cap: never hold bus phase longer than MAX_BP_INSERTION_S
                opt_BP = min(float(opt_BP), MAX_BP_INSERTION_S)
                # Enforce minimum BP if applied
                _min_ins = float(globals().get('MIN_BP_INSERTION_S', 5.0))
                if opt_BP > 0 and opt_BP < _min_ins:
                    opt_BP = _min_ins

                self.previous_phase  = current_phase
                self.BusPhaseEndTime = time + float(opt_BP)
                # Set bus phase duration first so Aimsun holds it for opt_BP
                # seconds, then force the switch into the bus phase.
                ECIChangeTimingPhase(self.id, self.BusPhase, float(opt_BP), timeSta)
                ECIChangeDirectPhase(
                    self.id, self.BusPhase, timeSta, time, acycle, 0)
                self.TSPStrategy   = 2
                self.flag          = 2
                self._ins_bus_phase_seen = False
                self._ins_grant_time = time
                self.TSPActiveTime = time + float(opt_BP) + 30
                self._ge_debt_s    = float(opt_BP)  # cycle recovery debt
                self._tsp_cycle_grant_until = time + self.cycle_len_s
                log_to_file(
                    f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                    f"bus={self.last_detected_bus_id} "
                    f"eta={_bus_eta_s:.1f}s "
                    f"type=LOCAL_INS source=LOCAL BP={opt_BP:.1f}s",
                    )
                if LOG_HARMONY:
                    _vprint(
                        f"[HARMONY] INSERTION | t={time:.1f}s inter={self.id} "
                        f"bus_eta={_bus_eta_s:.1f}s > natural_end={_natural_bus_end:.1f}s "
                        f"opt_BP={opt_BP:.1f}s prev_phase={current_phase}")
                _trace_objective(
                    "INS", "ACTION", "grant_insertion",
                    _bus_eta_s=_bus_eta_s,
                    _time_to_bp_s=_time_to_bp,
                    _natural_end_s=_natural_bus_end,
                    _bp_lb_s=_bp_lb_effective,
                    _bp_ub_s=float(self.BP_upper_bound),
                    _opt_bp_s=float(opt_BP),  # Log final value after hard cap to MAX_BP_INSERTION_S
                    _note=(
                        f"eta_eff={_bus_eta_effective_s:.1f};"
                        f"wait_to_bp={max(0.0, _time_to_bp - _bus_eta_effective_s):.1f};"
                        f"wait_thr={INS_MAX_WAIT_TRIGGER_S:.1f}"
                    ),
                )
                self.highlight_bus(self.last_detected_bus_id)
                if not _detection_recorded_this_call:
                    self._record_detection(time)
                    _detection_recorded_this_call = True
                self.stats.record_tsp_event(self.id, 'insertion')
                self.stats.record_tsp_insertion_duration(self.id, float(opt_BP))
                self.stats.record_tsp_insertion_wait(self.id, max(0.0, float(_bus_eta_s)))
                _mark_detection_point(
                    self.id, self.last_detected_bus_id, 0.0, 0.0, time,
                    "harmony-ins-local",
                    {
                        "force_write": True,
                        "prearm_status": "action",
                        "prearm_eta_s": round(max(0.0, float(_bus_eta_s)), 1),
                        "prearm_note": f"INS {float(opt_BP):.1f}s local",
                    },
                )
                # Acquire global bus focus
                if self.last_detected_bus_id and self.last_detected_bus_id > 0:
                    _acquire_focus(self.last_detected_bus_id, self.id, time)
                # Notify corridor coordinator for downstream pre-arming.
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        self._corridor_coord.notify_bus_granted(
                            self.last_detected_bus_id, self.id, time, None)
                    except Exception:
                        pass
                return True

        # ── No GE or INS was applied this call ───────────────────────────────
        # Only cancel the coordination wave if NO bus was detected at all this
        # call.  If a bus was detected but got natural green (or was focus-
        # suppressed), the wave must continue so downstream junctions keep
        # their pre-arms.  Only cancel when the wave origin is truly "empty"
        # (no bus presence at all → bus has passed or was never there).
        if (not _detection_recorded_this_call and
                not _coord_notified_this_call and
                self._corridor_coord is not None and COORDINATED_TSP):
            if (self._corridor_coord._wave_active and
                    self._corridor_coord._wave_origin == self.id):
                self._corridor_coord._wave_active     = False
                self._corridor_coord._wave_veh_id     = -1
                self._corridor_coord._wave_origin     = -1
                self._corridor_coord._wave_served_ids = set()
                self._corridor_coord._pre_requests.clear()
                log_to_file(
                    f"[HARMONY WAVE CANCEL] inter={self.id} t={time:.1f} "
                    f"no bus detected at wave origin — wave cancelled",
                    )
        return False

    def print_config_summary(self):
        """Comprehensive one-time logfile for debugging TSP logic"""
        log_to_file("=" * 80)
        log_to_file(f"[CONFIG SUMMARY] Intersection {self.id}")
        log_to_file(f"  BusPhase: {self.BusPhase} | Duration: {self.BusPhaseDuration}s")
        log_to_file(f"  PhaseIndex: {self.PhaseIndex}")
        log_to_file(f"  BusDet (NB-only): {self.BusDet}  ← must match DetDistance[0]")
        log_to_file(f"  BusCallDetectors: {self.urtsp_call_det_ids}")
        log_to_file(f"  UpDetList length: {len(self.UpDetList)} groups")
        for g, dets in enumerate(self.UpDetList):
            dd = self.DetDistance[g] if g < len(self.DetDistance) else "N/A"
            log_to_file(f"    Group {g}: {dets} | DetDistance: {dd}")
        log_to_file(f"  MainSections: {self.config.get('MainSections', [])}")
        log_to_file(f"  SideSections: {self.config.get('SideSections', [])}")
        log_to_file(f"  NumberOfLanes: {self.NumberOfLanes}")
        log_to_file(f"  Control mode: {CONTROL_MODE}")
        log_to_file("=" * 80)

    def _solve_offset_correction(self, bus_eta_s, current_phase, timeSta,
                                 remaining_red_s):
        """Proper offset-correction SOLVE (bidirectional): the SIGNED phase-
        boundary shift that aligns the bus-phase START with the bus ARRIVAL,
        instead of snapping to a fixed +/-{5,10} grid.

        Method: compute t_bp = time from now until the bus phase would start
        naturally (remaining time in the current phase + the durations of the
        intervening phases up to the bus phase). The misalignment is
            m = t_bp - bus_eta_s
          * m > 0  -> the bus ARRIVES BEFORE the green: ADVANCE (shorten the
                      current phase) by m so the green starts as the bus arrives
                      -> shift = -min(m, max_advance)   (negative = advance)
          * m < 0  -> the bus arrives during/after the green would start: OC does
                      not help (a green EXTENSION does), so shift = 0.
        The advance is bounded so the current phase never drops below its minimum
        green (max_advance = remaining_red - MinGreen). Returns (shift_s, t_bp_s);
        shift is 0.0 when no useful, feasible alignment exists. Pure (no signal
        side effects) -- the caller evaluates/commits it. (2026-09-22)"""
        try:
            _ci = self.phase_list.index(current_phase)
            _bi = self.phase_list.index(self.BusPhase)
        except Exception:
            return (0.0, 0.0)
        _n = len(self.phase_list)
        if _n == 0 or (_bi - _ci) % _n == 0:
            return (0.0, 0.0)            # already the bus phase -> use GE, not OC
        _tbp = max(0.0, float(remaining_red_s))
        try:
            for _k in range(1, (_bi - _ci) % _n):
                _tbp += float(GetPhaseDuration(
                    self.node_id, self.phase_list[(_ci + _k) % _n], timeSta) or 0.0)
        except Exception:
            return (0.0, _tbp)
        _misalign = _tbp - max(0.0, float(bus_eta_s))
        _min_green = float(self.config.get('MinGreen', 5.0) or 5.0)
        _max_advance = max(0.0, float(remaining_red_s) - _min_green)
        if _misalign > 0.5:
            _shift = -min(_misalign, _max_advance)     # advance (negative)
        else:
            _shift = 0.0                                # bus already catches green
        return (float(_shift), float(_tbp))

    def _opt_offset_targets(self):
        """Target bus-green start offsets (s) per junction, from the joint
        (sequence, offset) solution.

        Primary source is the retime CSV written by retime/optimize.py -- an exact
        Viterbi DP over stage order and offset that minimises two-directional
        arrival-in-green miss. Columns used: `junction` and
        `offset_bus_green_start_s` (cycle-relative position of the main/bus green
        start). If the CSV is absent or unreadable we fall back to the corridor
        coordinator's travel-time cumulant (_compute_plan_offsets), so the action
        still degenerates to a plain green-wave stagger instead of no-opping.

        Cached on the corridor coordinator when one is attached, else on self.
        Returns {junction_id: offset_s}; empty dict when nothing is available.
        """
        _owner = getattr(self, '_corridor_coord', None) or self
        try:
            _cached = getattr(_owner, '_opt_offset_cache', None)
            _path = str(globals().get('BXT_OPT_OFFSET_CSV', '') or '')
            if isinstance(_cached, dict) and getattr(
                    _owner, '_opt_offset_cache_path', None) == _path:
                return _cached
        except Exception:
            _cached = None
            _path = str(globals().get('BXT_OPT_OFFSET_CSV', '') or '')

        _out = {}
        if _path:
            try:
                import csv as _csv
                with open(_path, 'r', newline='', encoding='utf-8',
                          errors='replace') as _fh:
                    for _row in _csv.DictReader(_fh):
                        try:
                            _j = int(str(_row.get('junction', '')).strip())
                            _o = float(str(
                                _row.get('offset_bus_green_start_s', '')).strip())
                        except Exception:
                            continue
                        _out[_j] = _o
            except Exception:
                _out = {}
        if not _out:
            # No CSV (or it failed to parse): use the bus-speed travel-time
            # cumulant. Same units, coarser, but keeps the action meaningful.
            try:
                _cc = getattr(self, '_corridor_coord', None)
                _co = getattr(_cc, '_plan_offsets', None) if _cc is not None else None
                if isinstance(_co, dict) and _co:
                    _out = {int(k): float(v) for k, v in _co.items()}
            except Exception:
                _out = {}
        try:
            _owner._opt_offset_cache = _out
            _owner._opt_offset_cache_path = _path
        except Exception:
            pass
        return _out

    def _solve_offset_plan_push(self, current_phase, timeSta):
        """Signed stagger realignment toward the optimised corridor offset.

        The bus-green START currently sits at
            cur = (sum of durations of phases BEFORE BusPhase) mod C
        and the joint optimum wants it at `tgt`. We move by the shortest signed
        wrap, so the push is always the cheaper direction around the cycle:

            delta = ((tgt - cur + C/2) mod C) - C/2      (negative = advance)

        Guarded, because this rewrites the plan mid-run:
          * |delta| < BXT_OPT_PUSH_MIN_S -> no-op (noise);
          * |delta| clamped to BXT_OPT_PUSH_MAX_S, remainder re-aims next cycle;
          * BXT_OPT_PUSH_REQUIRE_BEFORE_BUS: if the bus phase has already started
            this cycle the shift would land AFTER the green we are trying to move,
            so we defer rather than overshoot;
          * BXT_OPT_PUSH_SAT_VETO: skip on a saturated main approach. That is the
            2026-09-28 failure mode (rewriting timings on a starved corridor).

        Returns (delta_s, tgt_off_s); delta is 0.0 when no feasible push exists.
        Pure -- the caller evaluates/commits it.
        """
        _g = globals()
        if not bool(_g.get('BXT_OPT_OFFSET_PUSH', False)):
            return (0.0, 0.0)
        try:
            _pl = list(self.phase_list or [])
            _bi = _pl.index(self.BusPhase)
            _ci = _pl.index(current_phase)
        except Exception:
            return (0.0, 0.0)
        _C = 0.0
        try:
            _C = float(self._signal_cycle_s(timeSta) or 0.0)
        except Exception:
            _C = 0.0
        if _C <= 1.0:
            return (0.0, 0.0)
        try:
            _cur = 0.0
            for _ph in _pl[:_bi]:
                _cur += float(GetPhaseDuration(
                    self.node_id, _ph, timeSta) or 0.0)
            _cur = _cur % _C
        except Exception:
            return (0.0, 0.0)

        _tgt_map = self._opt_offset_targets() or {}
        _tgt = _tgt_map.get(int(getattr(self, 'id', 0) or 0))
        if _tgt is None:
            return (0.0, 0.0)
        try:
            _tgt = float(_tgt) % _C
        except Exception:
            return (0.0, 0.0)

        if bool(_g.get('BXT_OPT_PUSH_REQUIRE_BEFORE_BUS', True)) and _ci >= _bi:
            return (0.0, _tgt)          # bus green already started; defer

        _sat = 0.0
        try:
            _fs = self._flow_stage_snapshot() or {}
            _cap = float(_fs.get('side_max_flow', 0.0) or 0.0)
            _x = float(_fs.get('main_x', 0.0) or 0.0)
            _sat = (_x / _cap) if _cap > 1e-6 else 0.0
        except Exception:
            _sat = 0.0
        if _sat > float(_g.get('BXT_OPT_PUSH_SAT_VETO', 0.90)):
            return (0.0, _tgt)

        _delta = ((_tgt - _cur + _C / 2.0) % _C) - _C / 2.0
        _mn = float(_g.get('BXT_OPT_PUSH_MIN_S', 3.0))
        _mx = float(_g.get('BXT_OPT_PUSH_MAX_S', 12.0))
        if abs(_delta) < _mn:
            return (0.0, _tgt)
        _delta = max(-_mx, min(_mx, _delta))
        return (float(_delta), _tgt)

    def solve_green_extension(self, lb, ub, time):
        """Harmony-search the green extension (s) in [lb, ub] that MINIMISES
        total passenger delay.

        `GE_Objective_Function` returns bus_delay*BusOcc + other_delay*other_occ
        -- the true total SYSTEM delay in pax-s, bus AND car/side, from real
        shockwave queue dynamics (not the underpriced CTM cross-cost proxy).
        Harmony search finds the extension that best trades bus benefit against
        that real car cost, so it cannot over-extend: pushing GE too far raises
        other_delay and the objective rejects it.

        Returns (opt_ge, base_pax, opt_pax): base_pax is total pax delay at GE=0
        (do nothing), opt_pax at the solved extension.  The caller should act
        ONLY if opt_pax < base_pax -- i.e. the extension lowers TOTAL system
        delay, not merely bus delay.
        """
        try:
            lb = max(0.0, float(lb)); ub = max(lb, float(ub))
            base_pax = float(self.GE_Objective_Function(0.0, time))
            if ub <= lb + 1e-6:
                return lb, base_pax, float(self.GE_Objective_Function(lb, time))
            opt = _solve_timing_min(self, self.GE_Objective_Function, lb, ub, time)
            if opt is None or (isinstance(opt, float) and math.isnan(opt)) or opt < 0:
                opt = lb
            opt = min(max(float(opt), lb), ub)
            return opt, base_pax, float(self.GE_Objective_Function(opt, time))
        except Exception as _e:
            # Never let the solver break a decision -- fall back to "no gain
            # known", which the caller reads as do-nothing.
            log_to_file(f"[BXT] solve_green_extension error: {_e}")
            _lb = max(0.0, float(lb))
            return _lb, 0.0, 0.0

    def GE_Objective_Function(self, GE, time):
        self._reset_harmony_work_arrays()
        _n_det_slots = max(len(self.BusDet), 1)
        # ── Phase 0 (Bus phase) ───────────────────────────────────────────────
        for i in range(_n_det_slots):
            self.HSMaxQueueLengthTime[0][i] = self.MaxQueueLengthTime[0][i]
            self.HSGreenStartTimeList[0][i] = self.GreenStartTimeList[0][i]
            self.HSMaxQueueLength[0][i]     = self.MaxQueueLength[0][i]
            self.HSRedDurationList[0][i]    = self.RedDurationList[0][i]
            self.HSQueueDissTime[0][i]      = self.QueueDissTime[0][i]
            self.HSMinQueueLength[0][i]     = self.MinQueueLength[0][i]
            self.HSMaxQueueLength[0][i]     = max(self.HSMaxQueueLength[0][i], 0.0)
            self.HSMinQueueLength[0][i]     = max(self.HSMinQueueLength[0][i], 0.0)
            _base_green_0 = float(self.BusPhaseDuration)
            self.TotalVeh[0][i] = (
                self.UpFlowList[0][i] *
                (self.HSRedDurationList[0][i] + _base_green_0 + GE) / 3600)
            if self.BusJoinQueueTime[0][i] <= self.HSMaxQueueLengthTime[0][i]:
                _w1 = abs(self.ShockwaveSpeed1List[0][i])
                _w2 = abs(self.ShockwaveSpeed2List[0][i])
                # A bus crawling at <= BUS_STOPPED_SPEED_MPS is effectively
                # STOPPED in the queue; snap it to the stopped limit (_bs = 0) so
                # the queue-join term reflects a waiting bus rather than an
                # in-between kinematic value that under-states its delay.
                _bs = abs(self.BusSpeed[0][i])
                if _bs <= float(globals().get('BUS_STOPPED_SPEED_MPS', 3.0)):
                    _bs = 0.0
                _denom_a = (_w1 + _bs) * _w2   # denominator of the queue-join term
                _denom_b = _w1 + _w2            # denominator of the travel-time term
                if _denom_a < 1e-6 or _denom_b < 1e-6:
                    self.BusDelay[0][i] = 0.0
                else:
                    self.BusDelay[0][i] = (
                        self.HSGreenStartTimeList[0][i]
                        + (_w1 * self.DetDistance[0][i]) / _denom_a
                        - (time + self.DetDistance[0][i] / _denom_b)
                    )
            else:
                self.BusDelay[0][i] = 0
            if self.HSQueueDissTime[0][i] < self.NextRedStartTime[0][i] + GE:
                self.OtherDelay[0][i] = max(0.0, (
                    (self.HSMaxQueueLength[0][i] * self.HSRedDurationList[0][i] / 2)
                    * (self.JamDensity - self.UpDenList[0][i]) / 1000
                    + ((self.HSQueueDissTime[0][i] - self.HSGreenStartTimeList[0][i])
                       * self.HSMaxQueueLength[0][i] / 2)
                    * (self.SaturationDensity - self.UpDenList[0][i]) / 1000))
            else:
                w3_ge = abs(self.ShockwaveSpeed3List[0][i])
                w4_ge = abs(self.ShockwaveSpeed4List[0][i])
                if w3_ge < 1e-6 or w4_ge < 1e-6:
                    self.OtherDelay[0][i] = 0.0
                else:
                    self.HSMinQueueLength[0][i] = max(0.0, (
                        (self.HSMaxQueueLength[0][i] / w3_ge
                         + self.HSMaxQueueLengthTime[0][i]
                         - self.NextRedStartTime[0][i] - GE) /
                        (1.0 / w3_ge + 1.0 / w4_ge)))
                    self.OtherDelay[0][i] = max(0.0, (
                        (self.HSMaxQueueLength[0][i] * self.HSRedDurationList[0][i] / 2)
                        * (self.JamDensity - self.UpDenList[0][i]) / 1000
                        + ((self.HSQueueDissTime[0][i] - self.HSGreenStartTimeList[0][i])
                           * self.HSMaxQueueLength[0][i]
                           - (self.HSQueueDissTime[0][i] - self.RedStartTimeList[0][i] - GE)
                           * self.HSMinQueueLength[0][i]) / 2
                        * (self.SaturationDensity - self.UpDenList[0][i]) / 1000))

        # ── Other phases (1..N) — project impact of extended green on their queues
        # Use actual number of phases when UpDetList is empty (minimal config).
        # Otherwise the other-phase delay is never computed and the reward
        # evaluation sees zero cost for extending/inserting bus phase.
        _n_other_phases = len(self.UpDetList) if self.UpDetList else len(self.phase_list)
        for i in range(1, _n_other_phases):
            # When UpDetList is empty, the inner dimension may not have per-detector
            # slots — use the first column only for the per-phase estimate.
            _n_slots = len(self.UpDetList[i]) if i < len(self.UpDetList) else 1
            for _slot in range(_n_slots):
                j = _slot if i < len(self.UpDetList) else 0
                # Shift green start forward by actual cycle time + GE
                _cycle_s = float(self.cycle_len_s)
                self.HSGreenStartTimeList[i][j] = self.GreenStartTimeList[i][j] + _cycle_s + GE
                self.HSRedDurationList[i][j]    = (
                    self.HSGreenStartTimeList[i][j] - self.RedStartTimeList[i][j])
                self.HSMaxQueueLengthTime[i][j] = self.MaxQueueLengthTime[i][j]
                self.HSQueueDissTime[i][j]      = self.QueueDissTime[i][j]
                self.HSMaxQueueLength[i][j]     = self.MaxQueueLength[i][j]
                self.HSMinQueueLength[i][j]     = self.MinQueueLength[i][j]

                # Use UpFlowList (section-scan fallback already applied)
                self.HSUpFlowList[i][j]  = self.UpFlowList[i][j]
                self.HSUpDenList[i][j]   = (
                    self.HSUpFlowList[i][j] * self.SaturationDensity / self.SaturationFlow
                    if self.SaturationFlow > 0 else 0.0)
                self.HSUpDenList[i][j] = min(
                    max(self.HSUpDenList[i][j], 0.0), self.JamDensity)
                self.HSShockwaveSpeed1List[i][j] = ShockwaveSpeed1(
                    self.HSUpFlowList[i][j], self.JamDensity, self.HSUpDenList[i][j])
                self.HSShockwaveSpeed3List[i][j] = ShockwaveSpeed3(
                    self.SaturationFlow, self.HSUpFlowList[i][j],
                    self.SaturationDensity, self.HSUpDenList[i][j])

                w1 = self.HSShockwaveSpeed1List[i][j]
                w2 = self.ShockwaveSpeed2List[i][j]
                w3 = self.HSShockwaveSpeed3List[i][j]
                w4 = self.ShockwaveSpeed4List[i][j]
                rd = self.HSRedDurationList[i][j]
                denom = abs(w2) - abs(w1)
                # Estimate other-phase base green = (cycle - bus_phase) / n_other_phases
                _n_other = max(_n_other_phases - 1, 1)
                _base_green_i = max(
                    (float(self.cycle_len_s) - float(self.BusPhaseDuration)) / _n_other,
                    10.0)
                if denom <= 1e-6 or abs(w3) < 1e-6:
                    self.TotalVeh[i][j] = self.UpFlowList[i][j] * (rd + GE + _base_green_i) / 3600
                    continue

                self.HSMaxQueueLength[i][j]     = abs(w2) * abs(w1) * rd / denom
                self.HSMaxQueueLengthTime[i][j] = (
                    abs(w2) * rd / denom)
                self.HSQueueDissTime[i][j]      = (
                    abs(w1) * abs(w2) * rd /
                    (abs(w3) * (abs(w2) - abs(w1))))
                self.TotalVeh[i][j] = self.UpFlowList[i][j] * (rd + GE + _base_green_i) / 3600

                nrs = self.NextRedStartTime[i][j]
                if self.HSQueueDissTime[i][j] < nrs + GE:
                    self.OtherDelay[i][j] = max(0.0, (
                        abs(w1) * abs(w2) * rd / (abs(w2) - abs(w1)) / 2
                        * (self.JamDensity - self.HSUpDenList[i][j]) / 1000
                        + (self.HSQueueDissTime[i][j] - self.HSGreenStartTimeList[i][j])
                        * self.HSMaxQueueLength[i][j] / 2
                        * (self.SaturationDensity - self.HSUpDenList[i][j]) / 1000))
                else:
                    if abs(w3) > 1e-6 and abs(w4) > 1e-6:
                        self.HSMinQueueLength[i][j] = (
                            (self.HSMaxQueueLength[i][j] / abs(w3)
                             + self.HSMaxQueueLengthTime[i][j] - (nrs + GE))
                            / (1.0 / abs(w3) + 1.0 / abs(w4)))
                    self.HSMinQueueLength[i][j] = max(self.HSMinQueueLength[i][j], 0.0)
                    self.OtherDelay[i][j] = max(0.0, (
                        abs(w1) * abs(w2) * rd / (abs(w2) - abs(w1)) / 2
                        * (self.JamDensity - self.HSUpDenList[i][j]) / 1000
                        + ((self.HSQueueDissTime[i][j] - self.HSGreenStartTimeList[i][j])
                           * self.HSMaxQueueLength[i][j]
                           - (self.HSQueueDissTime[i][j] - nrs - GE)
                           * self.HSMinQueueLength[i][j]) / 2
                        * (self.SaturationDensity - self.HSUpDenList[i][j]) / 1000))

        # ── Side-street delay penalty ─────────────────────────────────────────
        # GE holds each side section at red for an extra GE seconds.
        # Triangle model: growth phase (w1 speed) + discharge phase (w3 speed).
        side_other_delay, side_total_veh = self._compute_side_delay_penalty(GE, _suppress_log=True)

        bus_delay_total   = self._safe_array_sum(self.BusDelay)
        base_other_delay  = self._safe_array_sum(self.OtherDelay)
        other_delay_total = base_other_delay + safe_float(side_other_delay)
        total_veh         = self._safe_array_sum(self.TotalVeh) + safe_float(side_total_veh)

        other_occ = self._estimated_other_vehicle_occupancy()
        total_pax_delay = (
            bus_delay_total * self.BusOcc +
            other_delay_total * other_occ
        )
        bus_delay_total, other_delay_total, total_veh, total_pax_delay = (
            self._finalize_objective_stats(
                bus_delay_total, other_delay_total, total_veh, total_pax_delay
            )
        )

        # log_to_file(
        #     f"[HS GE_OBJ] inter={self.id} GE={GE:.2f}s "
        #     f"bus_delay={bus_delay_total:.2f} "
        #     f"other_delay={base_other_delay:.2f} "
        #     f"side_delay={safe_float(side_other_delay):.2f} "
        #     f"other_occ={other_occ:.2f} "
        #     f"total_veh={total_veh:.1f} "
        #     f"total_pax_delay={total_pax_delay:.4f}")
        self.stats.store_objective_stats(
            bus_delay=bus_delay_total,
            other_delay=other_delay_total,
            avg_pass_delay=total_pax_delay)
        return total_pax_delay

    def solve_bus_phase_green(self, lb, ub, time):
        """Harmony-search the bus-phase green / advance (s) in [lb, ub] that
        MINIMISES total passenger delay for a bus held on red (wrong phase).

        `BP_Objective_Function` returns the same total-system pax delay
        (bus*BusOcc + other*other_occ) as GE, but for the case where the bus
        phase must be brought forward -- exactly the wrong-phase GREEN_REALLOC /
        insertion situation.  Advancing the bus green helps the held bus but
        the shortened cross phase costs cross traffic; harmony finds the amount
        that best trades the two, and cannot over-advance (too much raises
        other_delay).

        Returns (opt, base_pax, opt_pax): base_pax at GreenTime=lb (minimum
        service), opt_pax at the solved value.  Caller acts iff opt_pax lowers
        total delay versus doing nothing.
        """
        try:
            lb = max(0.0, float(lb)); ub = max(lb, float(ub))
            base_pax = float(self.BP_Objective_Function(0.0, time))
            if ub <= lb + 1e-6:
                return lb, base_pax, float(self.BP_Objective_Function(lb, time))
            opt = _solve_timing_min(self, self.BP_Objective_Function, lb, ub, time)
            if opt is None or (isinstance(opt, float) and math.isnan(opt)) or opt < 0:
                opt = lb
            opt = min(max(float(opt), lb), ub)
            return opt, base_pax, float(self.BP_Objective_Function(opt, time))
        except Exception as _e:
            log_to_file(f"[BXT] solve_bus_phase_green error: {_e}")
            return max(0.0, float(lb)), 0.0, 0.0

    def BP_Objective_Function(self, GreenTime, time):
        """
        Bus-phase rotation (phase insertion) objective function.
        Mirrors BP_Objective_Function from Bus_priority_single_intersection_3.py,
        adapted for multi-intersection class with full debug logging.
        """
        self._reset_harmony_work_arrays()
        _n_det_slots = max(len(self.BusDet), 1)
        # ── Phase 0: Bus phase ─────────────────────────────────────────────────
        for i in range(_n_det_slots):
            # log_to_file(f"[HS BP_OBJ] inter={self.id} bus_det_idx={i} "
            #             f"UpDetCount={self.UpDetCountList[0][i]:.0f}")
            # Projected green start: now + 5s (insertion delay)
            self.HSGreenStartTimeList[0][i] = time + 5
            self.HSRedStartTimeList[0][i]   = self.RedStartTimeList[0][i]
            self.HSRedDurationList[0][i]    = (
                self.HSGreenStartTimeList[0][i] - self.HSRedStartTimeList[0][i])
            red_dur = max(self.HSRedDurationList[0][i], 1.0)

            # Use UpFlowList which already incorporates section-scan fallback
            # when physical detector counts are unavailable (returns 0).
            self.HSUpFlowList[0][i]          = self.UpFlowList[0][i]
            self.HSUpDenList[0][i]           = min(max(
                self.HSUpFlowList[0][i] * self.SaturationDensity / self.SaturationFlow
                if self.SaturationFlow > 0 else 0.0, 0.0), self.JamDensity)
            self.HSShockwaveSpeed1List[0][i] = ShockwaveSpeed1(
                self.HSUpFlowList[0][i], self.JamDensity, self.HSUpDenList[0][i])
            self.HSShockwaveSpeed3List[0][i] = ShockwaveSpeed3(
                self.SaturationFlow, self.HSUpFlowList[0][i],
                self.SaturationDensity, self.HSUpDenList[0][i])

            # log_to_file(f"[HS BP_OBJ] inter={self.id} i={i} "
            #             f"HSUpFlow={self.HSUpFlowList[0][i]:.1f} "
            #             f"HSUpDen={self.HSUpDenList[0][i]:.4f} "
            #             f"w1={self.HSShockwaveSpeed1List[0][i]:.4f} "
            #             f"w2={self.ShockwaveSpeed2List[0][i]:.4f} "
            #             f"w3={self.HSShockwaveSpeed3List[0][i]:.4f}")

            self.TotalVeh[0][i] = self.HSUpFlowList[0][i] * (red_dur + GreenTime) / 3600

            w1 = self.HSShockwaveSpeed1List[0][i]
            w2 = self.ShockwaveSpeed2List[0][i]
            denom = abs(w2) - abs(w1)
            if denom > 1e-6:
                self.HSMaxQueueLength[0][i] = (
                    abs(w2) * abs(w1) * (time + 5 - self.HSRedStartTimeList[0][i])
                    / denom)
                self.HSMaxQueueLengthTime[0][i] = (
                    self.HSRedStartTimeList[0][i]
                    + abs(w2) * (time + 5 - self.HSRedStartTimeList[0][i]) / denom)
                self.HSMaxQueueLength[0][i] = max(self.HSMaxQueueLength[0][i], 0.0)

        for i in range(_n_det_slots):
            w1 = self.HSShockwaveSpeed1List[0][i]
            w2 = self.ShockwaveSpeed2List[0][i]
            w3 = self.HSShockwaveSpeed3List[0][i]
            w4 = self.ShockwaveSpeed4List[0][i]
            denom = abs(w2) - abs(w1)

            if denom <= 1e-6 or abs(w3) < 1e-6:
                self.BusDelay[0][i]  = 0.0
                self.OtherDelay[0][i] = 0.0
                continue

            # log_to_file(f"[HS BP_OBJ] inter={self.id} i={i} "
            #             f"HSMaxQ={self.HSMaxQueueLength[0][i]:.1f} "
            #             f"HSMaxQTime={self.HSMaxQueueLengthTime[0][i]:.1f}")

            bus_speed = self.BusSpeed[0][i]
            if bus_speed > 0:
                # Time bus joins queue front
                self.BusJoinQueueTime[0][i] = (
                    (self.DetDistance[0][i]
                     - abs(w1) * (time - self.HSRedStartTimeList[0][i]))
                    / (bus_speed + abs(w1)) + time)

                # log_to_file(f"[HS BP_OBJ] inter={self.id} i={i} "
                #             f"BusJoinQTime={self.BusJoinQueueTime[0][i]:.1f} "
                #             f"HSMaxQTime={self.HSMaxQueueLengthTime[0][i]:.1f}")

                if self.BusJoinQueueTime[0][i] > self.HSMaxQueueLengthTime[0][i]:
                    # Bus arrives after max queue → no stop
                    self.BusStoplineTime[0][i] = time + self.DetDistance[0][i] / bus_speed
                    self.BusPhaseMinDuration[0][i] = (
                        self.BusStoplineTime[0][i] - self.HSGreenStartTimeList[0][i])
                    self.BusDelay[0][i] = 0.0

                    # log_to_file(f"[HS BP_OBJ] inter={self.id} i={i} "
                    #             f"case=no_stop_queue_clear BusStopline={self.BusStoplineTime[0][i]:.1f} "
                    #             f"MinDur={self.BusPhaseMinDuration[0][i]:.1f}")

                    for k in range(len(self.BusDet)):
                        w3k = abs(self.HSShockwaveSpeed3List[0][k])
                        w4k = abs(self.ShockwaveSpeed4List[0][k])
                        if w3k < 1e-6:
                            self.OtherDelay[0][k] = 0.0
                            continue
                        self.HSQueueDissTime[0][k] = (
                            self.HSMaxQueueLengthTime[0][k]
                            + self.HSMaxQueueLength[0][k] / w3k)
                        green_end = self.HSGreenStartTimeList[0][k] + GreenTime
                        if self.HSQueueDissTime[0][k] < green_end:
                            self.OtherDelay[0][k] = max(0.0, (
                                self.HSMaxQueueLength[0][k] * self.HSRedDurationList[0][k]
                                / 2 * (self.JamDensity - self.HSUpDenList[0][k]) / 1000
                                + (self.HSQueueDissTime[0][k]
                                   - self.HSGreenStartTimeList[0][k])
                                * self.HSMaxQueueLength[0][k] / 2
                                * (self.SaturationDensity - self.HSUpDenList[0][k]) / 1000))
                        else:
                            hsmin = 0.0
                            if w3k > 1e-6 and w4k > 1e-6:
                                nrs_k = self.HSNextRedStartTime[0][k]
                                hsmin = (
                                    (self.HSMaxQueueLength[0][k] / w3k
                                     + self.HSMaxQueueLengthTime[0][k] - (nrs_k + GreenTime))
                                    / (1.0 / w3k + 1.0 / w4k))
                            self.HSMinQueueLength[0][k] = max(hsmin, 0.0)
                            self.OtherDelay[0][k] = max(0.0, (
                                self.HSMaxQueueLength[0][k] * self.HSRedDurationList[0][k]
                                / 2 * (self.JamDensity - self.HSUpDenList[0][k]) / 1000
                                + ((self.HSQueueDissTime[0][k]
                                    - self.HSGreenStartTimeList[0][k])
                                   * self.HSMaxQueueLength[0][k]
                                   - (self.HSQueueDissTime[0][k] - green_end)
                                   * self.HSMinQueueLength[0][k]) / 2
                                * (self.SaturationDensity - self.HSUpDenList[0][k]) / 1000))

                else:
                    # Bus joins queue → compute discharge time
                    bus_pos = (self.DetDistance[0][i]
                               - bus_speed
                               * ((self.DetDistance[0][i]
                                   - abs(w1) * (time - self.RedStartTimeList[0][i]))
                                  / (bus_speed + abs(w1))))
                    bus_discharge = (
                        self.HSGreenStartTimeList[0][i] + bus_pos / abs(w2))
                    self.BusStoplineTime[0][i] = (
                        bus_discharge + bus_pos / abs(w3))
                    if self.BusStoplineTime[0][i] > self.HSGreenStartTimeList[0][i]:
                        self.BusPhaseMinDuration[0][i] = (
                            self.BusStoplineTime[0][i] - self.HSGreenStartTimeList[0][i])
                    self.BusDelay[0][i] = max(0.0,
                        self.HSGreenStartTimeList[0][i]
                        + (self.DetDistance[0][i]
                           - bus_speed * (self.DetDistance[0][i]
                                          - (self.HSGreenStartTimeList[0][i]
                                             - self.HSRedStartTimeList[0][i])
                                          * abs(w1))
                           / (bus_speed + abs(w1))) / abs(w2)
                        - (time + (self.DetDistance[0][i]
                                   - (self.HSGreenStartTimeList[0][i]
                                      - self.HSRedStartTimeList[0][i])
                                   * abs(w1))
                           / (bus_speed + abs(w1))))

                    # log_to_file(f"[HS BP_OBJ] inter={self.id} i={i} "
                    #             f"case=joins_queue bus_pos={bus_pos:.1f} "
                    #             f"BusDelay={self.BusDelay[0][i]:.2f}")

                    for k in range(len(self.BusDet)):
                        w1k = abs(self.HSShockwaveSpeed1List[0][k])
                        w2k = abs(self.ShockwaveSpeed2List[0][k])
                        w3k = abs(self.HSShockwaveSpeed3List[0][k])
                        if w3k < 1e-6 or (w2k - w1k) <= 1e-6:
                            self.HSQueueDissTime[0][k] = 0.0
                            self.OtherDelay[0][k] = 0.0
                            continue
                        self.HSQueueDissTime[0][k] = (
                            self.HSRedStartTimeList[0][k]
                            + w2k * self.HSRedDurationList[0][k] / (w2k - w1k)
                            + w2k * w1k * self.HSRedDurationList[0][k]
                            / ((w2k - w1k) * w3k))
                        green_end = self.HSGreenStartTimeList[0][k] + GreenTime
                        if self.HSQueueDissTime[0][k] < green_end:
                            self.OtherDelay[0][k] = max(0.0, (
                                (self.HSMaxQueueLength[0][k]
                                 * self.HSRedDurationList[0][k] / 2)
                                * (self.JamDensity - self.HSUpDenList[0][k]) / 1000
                                + ((self.HSQueueDissTime[0][k]
                                    - self.HSGreenStartTimeList[0][k])
                                   * self.HSMaxQueueLength[0][k] / 2)
                                * (self.SaturationDensity - self.HSUpDenList[0][k]) / 1000))
                        else:
                            self.OtherDelay[0][k] = max(0.0, (
                                (self.HSMaxQueueLength[0][k]
                                 * self.HSRedDurationList[0][k] / 2)
                                * (self.JamDensity - self.HSUpDenList[0][k]) / 1000
                                + ((self.HSQueueDissTime[0][k]
                                    - self.HSGreenStartTimeList[0][k])
                                   * self.HSMaxQueueLength[0][k] / 2)
                                * (self.SaturationDensity - self.HSUpDenList[0][k]) / 1000
                                - (self.HSQueueDissTime[0][k] - green_end) / 2
                                * (self.SaturationDensity - self.HSUpDenList[0][k]) / 1000))

        # ── Interrupted phase (OrderToTerminatePhase = previous_phase index) ──
        otp_phase = self.previous_phase  # phase being interrupted
        if otp_phase in self.PhaseIndex:
            otp_idx = self.PhaseIndex[otp_phase]
            # Detector groups can be empty after section-scan cleanup. Use the
            # available per-phase array width instead of assuming UpDetList has
            # a matching entry for every phase.
            _phase_slots = len(self.HSNextRedStartTime) if self.HSNextRedStartTime is not None else 0
            if _phase_slots <= 0:
                return -1000000000
            if otp_idx >= _phase_slots:
                otp_idx = 0
            _det_count = 0
            if otp_idx < len(self.UpDetList):
                _det_count = len(self.UpDetList[otp_idx])
            if _det_count <= 0:
                try:
                    _det_count = len(self.HSNextRedStartTime[otp_idx])
                except Exception:
                    _det_count = 0
            for j in range(_det_count):
                self.HSNextRedStartTime[otp_idx][j] = (
                    self.NextRedStartTime[otp_idx][j] + time + 5)
                self.HSGreenStartTimeList[otp_idx][j] = self.GreenStartTimeList[0][j]
                self.HSGreenDurationList[otp_idx][j] = (
                    self.HSNextRedStartTime[otp_idx][j]
                    - self.HSGreenStartTimeList[otp_idx][j])
                self.HSUpFlowList[otp_idx][j]          = self.UpFlowList[otp_idx][j]
                self.HSShockwaveSpeed1List[otp_idx][j] = self.ShockwaveSpeed1List[otp_idx][j]
                self.HSShockwaveSpeed3List[otp_idx][j] = self.ShockwaveSpeed3List[otp_idx][j]
                self.HSRedDurationList[otp_idx][j]     = self.RedDurationList[otp_idx][j]
                self.TotalVeh[otp_idx][j] = (
                    self.HSUpFlowList[otp_idx][j] * GreenTime / 3600)

                w1o  = self.HSShockwaveSpeed1List[otp_idx][j]
                w2o  = self.ShockwaveSpeed2List[otp_idx][j]
                w3o  = self.HSShockwaveSpeed3List[otp_idx][j]
                w4o  = self.ShockwaveSpeed4List[otp_idx][j]
                gd   = self.HSGreenDurationList[otp_idx][j]
                denom_o = abs(w2o) - abs(w1o)
                if abs(denom_o) < 1e-6 or abs(w3o) < 1e-6:
                    continue

                residual_cleared = (
                    self.MaxQueueLength[otp_idx][j]
                    - abs(w3o) * gd < 0)
                if residual_cleared:
                    self.HSMaxQueueLength[otp_idx][j] = (
                        abs(w2o) * abs(w1o) * GreenTime / denom_o)
                else:
                    self.HSMaxQueueLength[otp_idx][j] = self.MaxQueueLength[otp_idx][j]

                nrs_o = self.HSNextRedStartTime[otp_idx][j]
                q_diss_o = (
                    self.HSMaxQueueLengthTime[otp_idx][j]
                    + self.HSMaxQueueLength[otp_idx][j] / abs(w3o))
                if q_diss_o < nrs_o:
                    self.OtherDelay[otp_idx][j] = max(0.0, (
                        self.HSMaxQueueLength[otp_idx][j]
                        * self.HSRedDurationList[otp_idx][j] / 2
                        * (self.JamDensity - self.UpDenList[otp_idx][j]) / 1000
                        + (q_diss_o - self.HSGreenStartTimeList[otp_idx][j])
                        * self.HSMaxQueueLength[otp_idx][j] / 2
                        * (self.SaturationDensity - self.UpDenList[otp_idx][j]) / 1000))
                else:
                    if abs(w3o) > 1e-6 and abs(w4o) > 1e-6:
                        min_q = (
                            (self.HSMaxQueueLength[otp_idx][j] / abs(w3o)
                             + self.HSMaxQueueLengthTime[otp_idx][j] - nrs_o)
                            / (1.0 / abs(w3o) + 1.0 / abs(w4o)))
                        self.HSMinQueueLength[otp_idx][j] = max(min_q, 0.0)
                    self.OtherDelay[otp_idx][j] = max(0.0, (
                        self.HSMaxQueueLength[otp_idx][j]
                        * self.HSRedDurationList[otp_idx][j] / 2
                        * (self.JamDensity - self.UpDenList[otp_idx][j]) / 1000
                        + ((q_diss_o - self.HSGreenStartTimeList[otp_idx][j])
                           * self.HSMaxQueueLength[otp_idx][j]
                           - (q_diss_o - nrs_o)
                           * self.HSMinQueueLength[otp_idx][j]) / 2
                        * (self.SaturationDensity - self.UpDenList[otp_idx][j]) / 1000))

        # ── All other phases (not bus=0 and not interrupted) ──────────────────
        otp_idx_val = self.PhaseIndex.get(otp_phase, -1) if otp_phase in self.PhaseIndex else -1
        _n_bp_phases = len(self.UpDetList) if self.UpDetList else len(self.phase_list)
        for i in range(_n_bp_phases):
            if i == 0 or i == otp_idx_val:
                continue
            _n_slots_bp = len(self.UpDetList[i]) if i < len(self.UpDetList) else 1
            for _slot in range(_n_slots_bp):
                j = _slot if i < len(self.UpDetList) else 0
                self.HSRedStartTimeList[i][j]  = self.RedStartTimeList[i][j]
                self.HSRedDurationList[i][j]   = self.RedDurationList[i][j] + GreenTime + 5
                elapsed = max(time - self.HSRedStartTimeList[i][j], 1.0)
                self.HSUpFlowList[i][j]        = (
                    self.UpDetCountList[i][j] / elapsed * 3600)
                self.HSUpDenList[i][j] = min(
                    max(self.HSUpFlowList[i][j] * self.SaturationDensity / max(self.SaturationFlow, 1.0), 0.0),
                    self.JamDensity)
                self.TotalVeh[i][j]            = (
                    self.HSUpFlowList[i][j]
                    * (self.HSRedDurationList[i][j] + max(int(self.config.get('GE_upper_bound', 20)), 10)) / 3600)

                w1i = self.ShockwaveSpeed1List[i][j]
                w2i = self.ShockwaveSpeed2List[i][j]
                w3i = self.ShockwaveSpeed3List[i][j]
                w4i = self.ShockwaveSpeed4List[i][j]
                rd_i = self.HSRedDurationList[i][j]
                den_i = abs(w2i) - abs(w1i)
                if den_i <= 1e-6 or abs(w3i) < 1e-6:
                    continue

                self.HSMaxQueueLength[i][j] = (
                    abs(w1i) * abs(w2i) * (rd_i) / den_i)
                self.HSMaxQueueLength[i][j] = max(self.HSMaxQueueLength[i][j], 0.0)
                self.HSMaxQueueLengthTime[i][j] = (
                    self.HSRedStartTimeList[i][j]
                    + abs(w2i) * (rd_i + GreenTime + 5) / den_i)
                self.HSGreenStartTimeList[i][j] = (
                    self.HSRedStartTimeList[i][j] + self.HSRedDurationList[i][j])
                self.HSNextRedStartTime[i][j]   = (
                    self.HSGreenStartTimeList[i][j] + 40)
                q_diss_i = (
                    self.HSMaxQueueLengthTime[i][j]
                    + self.HSMaxQueueLength[i][j] / abs(w3i))
                nrs_i = self.HSNextRedStartTime[i][j]
                if q_diss_i > nrs_i:
                    min_qi = 0.0
                    if abs(w3i) > 1e-6 and abs(w4i) > 1e-6:
                        min_qi = (
                            (self.HSMaxQueueLength[i][j] / abs(w3i)
                             + self.HSMaxQueueLengthTime[i][j] - (nrs_i + GreenTime + 5))
                            / (1.0 / abs(w3i) + 1.0 / abs(w4i)))
                    self.HSMinQueueLength[i][j] = max(min_qi, 0.0)
                    self.OtherDelay[i][j] = max(0.0, (
                        self.HSMaxQueueLength[i][j] * rd_i / 2
                        * (self.JamDensity - self.UpDenList[i][j]) / 1000
                        + ((q_diss_i - self.HSGreenStartTimeList[i][j])
                           * self.HSMaxQueueLength[i][j]
                           - (q_diss_i - nrs_i) * self.HSMinQueueLength[i][j]) / 2
                        * (self.SaturationDensity - self.UpDenList[i][j]) / 1000))
                else:
                    self.OtherDelay[i][j] = max(0.0, (
                        self.HSMaxQueueLength[i][j] * rd_i / 2
                        * (self.JamDensity - self.UpDenList[i][j]) / 1000
                        + (q_diss_i - self.HSGreenStartTimeList[i][j])
                        * self.HSMaxQueueLength[i][j] / 2
                        * (self.SaturationDensity - self.UpDenList[i][j]) / 1000))

        # ── Side-street delay penalty ─────────────────────────────────────────
        # Phase insertion forces side sections to wait GreenTime + 5s extra.
        extra_red = GreenTime + 5.0
        side_other_delay_bp, side_total_veh_bp = self._compute_side_delay_penalty(extra_red, _suppress_log=True)

        bus_delay_total   = self._safe_array_sum(self.BusDelay)
        base_other_delay  = self._safe_array_sum(self.OtherDelay)
        other_delay_total = base_other_delay + safe_float(side_other_delay_bp)
        total_veh         = self._safe_array_sum(self.TotalVeh) + safe_float(side_total_veh_bp)

        other_occ = self._estimated_other_vehicle_occupancy()
        total_pax_delay = (
            bus_delay_total * self.BusOcc +
            other_delay_total * other_occ
        )
        bus_delay_total, other_delay_total, total_veh, total_pax_delay = (
            self._finalize_objective_stats(
                bus_delay_total, other_delay_total, total_veh, total_pax_delay
            )
        )

        # log_to_file(
        #     f"[HS BP_OBJ] inter={self.id} GreenTime={GreenTime:.2f}s "
        #     f"bus_delay={bus_delay_total:.2f} "
        #     f"other_delay={base_other_delay:.2f} "
        #     f"side_delay={safe_float(side_other_delay_bp):.2f} "
        #     f"other_occ={other_occ:.2f} "
        #     f"total_veh={total_veh:.1f} "
        #     f"total_pax_delay={total_pax_delay:.4f}")
        self.stats.store_objective_stats(
            bus_delay=bus_delay_total,
            other_delay=other_delay_total,
            avg_pass_delay=total_pax_delay)
        return total_pax_delay


# =============================================================================
# AIMSUN CALLBACKS
# =============================================================================

def AAPILoad():
    if not _CONFIG_BOUND:
        _self_bootstrap_from_direct_load()
    _vprint("=" * 60)
    if LOG_INIT: AKIPrintString(f"[TSP] Script loaded | mode={CONTROL_MODE}")
    if LOG_INIT: AKIPrintString(f"[TSP] Log file → {LOG_FILE}")
    if LOG_INIT: AKIPrintString(f"[TSP] Intersections configured: {list(INTERSECTIONS_CONFIG.keys())}")
    # ── OD demand scaling (Phase-3 demand sweep) ────────────────────────────
    # AKIODDemandSetDemandODPair ONLY works inside AAPILoad (Aimsun API docs), so
    # it CANNOT be done in AAPIInit where CURRENT_DEMAND_SCALAR is normally
    # propagated -- read the scalar straight from run_config.py here and apply it
    # now, before Aimsun schedules the demand.
    try:
        _rc_scalar = 1.0
        _rc_path = os.path.join(globals().get('_CORRIDOR_DIR', '') or
                                os.path.dirname(os.path.abspath(__file__)),
                                'run_config.py')
        if os.path.isfile(_rc_path):
            _rc_ns = {}
            with open(_rc_path, 'r', encoding='utf-8') as _rf:
                exec(_rf.read(), _rc_ns)
            _rc_scalar = float(_rc_ns.get('CURRENT_DEMAND_SCALAR', 1.0) or 1.0)
        globals()['CURRENT_DEMAND_SCALAR'] = _rc_scalar
        # In-engine OD scaling disabled by default (OD_SCALE_IN_ENGINE_ENABLED):
        # console-side multiply is authoritative; see flag rationale above.
        if globals().get('OD_SCALE_IN_ENGINE_ENABLED', False):
            _apply_od_demand_scalar(_rc_scalar)
    except Exception as _dse:
        log_to_file(f"[LOAD] OD demand scalar apply failed: {_dse!r}", force=True)
    # ── Fresh per-run stats (fixes cross-arm carry-over) ────────────────────
    # The controller creates `stats = SimulationStats(...)` ONCE at module load,
    # but the controller + Simulation_Stats modules are session-cached, so the
    # SAME instance is reused across every arm and its self.* accumulators
    # (bus_trips, delays, passages) CARRY OVER between arms (proven 2026-09-07:
    # N_BusTrips 1025->2043->3061->4069->5077 and TotalPassDelay 1397->..->8738
    # across the 5-arm sweep). AAPILoad runs per replication, so recreate the
    # instance here; AAPIInit re-registers intersections + finalise_init on it,
    # and SimulationStats.__init__ re-reads run_config for this arm's strategy.
    try:
        _SS = globals().get('SimulationStats')
        if _SS is not None:
            globals()['stats'] = _SS(
                CONTROL_MODE, verbose=bool(globals().get('VERBOSE', False)))
            log_to_file("[LOAD] stats reset -- fresh SimulationStats for this run")
        else:
            log_to_file("[LOAD] WARNING: SimulationStats class not bound; stats "
                        "NOT reset (cross-arm carry-over possible)", force=True)
    except Exception as _sse:
        log_to_file(f"[LOAD] stats reset FAILED: {_sse!r} -- cross-arm "
                    "carry-over possible", force=True)
    _vprint("=" * 60)
    log_to_file(f"[LOAD] AAPILoad complete | mode={CONTROL_MODE} | "
                f"n_intersections={len(INTERSECTIONS_CONFIG)} | "
                f"ENGINE_BUILD={ENGINE_BUILD}")
    return 0


def AAPIInit():
    global controllers, corridor_coordinators, _dynaropac_optimizer, _dynaropac_last_eval_t
    global _milp_mpc_controller, _milp_mpc_last_step
    global _DYNAROPAC_DECISION_CSV, _dynaropac_decision_header_written
    global _twoway_shift

    # ── Refresh output file paths for this replication ────────────────────────
    # The module is loaded once per Aimsun session and reused across all batch
    # replications.  run_config.py is rewritten by the batch runner before each
    # run, so we re-read it here to get the correct experiment name and stamp
    # fresh output filenames — otherwise all runs append to the same CSV and
    # the dashboard cannot match bus tracking / detection data by experiment.
    global _CURRENT_EXPERIMENT, _BUS_TRACKING_CSV, _PRESENCE_SNAPSHOT_CSV
    global _DET_CSV, _WAVE_EVENTS_CSV
    global _DET_GEOJSON, _JUNC_CSV, _RUN_SUMMARY_TXT
    global _OFFSET_CSV, _offset_header_written, _QUEUE_SNAPSHOT_CSV, _NO_INS_SUMMARY_CSV
    global _OBJECTIVE_TRACE_CSV, _objective_trace_header_written
    try:
        _rc_path2 = os.path.join(_CORRIDOR_DIR, 'run_config.py')
        _rc_ns2: dict = {}
        with open(_rc_path2, 'r') as _rc_f2:
            exec(_rc_f2.read(), _rc_ns2)
        _CURRENT_EXPERIMENT = str(_rc_ns2.get('CURRENT_EXPERIMENT',
                                               _rc_ns2.get('CURRENT_STRATEGY', 'UNKNOWN'))).strip()

        # ── Reset all mode state to defaults BEFORE applying this run_config ──
        # This module is loaded ONCE per Aimsun session and reused for every
        # experiment in a batch.  run_config.py for each experiment only lists
        # the flags it turns ON — so without this reset a mode enabled by an
        # earlier experiment leaks into every later one, making different
        # strategies run identical code paths and produce identical results.
        try:
            _spm.reset_mode_flags()
        except Exception as _rst_err:
            log_to_file(f"[INIT] reset_mode_flags failed: {_rst_err!r}", force=True)
        # ── Reset ENGINE-namespace flag copies too (2026-09-25) ──────────
        # reset_mode_flags() restores _spm's copies, but decision code reads
        # ENGINE globals (globals().get(...)). The propagation loops below
        # only write keys PRESENT in run_config, so an arm that omits a flag
        # inherits the previous arm's engine copy -- e.g. base DCTSP_MARL
        # inherited CONTINUOUS_MONITOR_MODE=True from CELLQLEARN_CONT_PURPOSE
        # and produced a bit-identical action stream to MARL_CONT. Restore
        # pristine defaults for every propagatable key missing from this run.
        try:
            _defs = getattr(_spm, '_MODE_FLAG_DEFAULTS', {}) or {}
            _n_rst = 0
            for _k, _v in _defs.items():
                if _k not in _rc_ns2:
                    if globals().get(_k, _v) != _v:
                        _n_rst += 1
                    globals()[_k] = _v
            if _n_rst:
                log_to_file(f"[INIT] engine-namespace flag reset: {_n_rst} "
                            f"stale copies restored to defaults", force=True)
        except Exception as _rste:
            log_to_file(f"[INIT] engine flag reset failed: {_rste!r}", force=True)
        try:
            _twoway_shift.clear()   # per-replication clock-shift accumulators
        except Exception:
            pass
        # ── CellQLearn train/eval phase + Q-table reset policy ────────────
        # BXT_TRAIN_SEEDS and BXT_EVAL_SEEDS split the batch. With the default
        # BXT_FREEZE_ON_EVAL=False the Q-table is NEVER frozen: BOTH lists keep
        # crediting realized delay, and eval seeds additionally explore at
        # BXT_TRAIN_EPSILON so they can still discover a better action. The
        # train/eval split then only guarantees no seed is SCORED on a seed it
        # trained on -- the table stays live, it is not pinned. Setting
        # BXT_FREEZE_ON_EVAL=True restores the legacy behaviour (eval = frozen
        # table, eps=0, no learning). When neither list is set, every seed is an
        # independent episode (reset each run) -- the default.
        try:
            _bxt_freeze_on_eval = bool(globals().get('BXT_FREEZE_ON_EVAL', False))
        except Exception:
            _bxt_freeze_on_eval = False
        try:
            _cur_seed = int(_rc_ns2.get('CURRENT_SEED', -1))
        except Exception:
            _cur_seed = -1
        try:
            _train_seeds = [int(x) for x in (globals().get('BXT_TRAIN_SEEDS') or [])]
            _eval_seeds  = [int(x) for x in (globals().get('BXT_EVAL_SEEDS') or [])]
            # CPD-QL uses the same train/eval seed lists (fall back to BXT's).
            _cpd_train_seeds = [int(x) for x in (globals().get('CPDQL_TRAIN_SEEDS')
                                                 or _train_seeds or [])]
            _cpd_eval_seeds  = [int(x) for x in (globals().get('CPDQL_EVAL_SEEDS')
                                                 or _eval_seeds or [])]
        except Exception:
            _train_seeds, _eval_seeds = [], []
            _cpd_train_seeds, _cpd_eval_seeds = [], []
        if not (_train_seeds or _eval_seeds):
            _bxt_phase = 'per_seed'
        elif _cur_seed in _eval_seeds:
            _bxt_phase = 'eval'
        elif _cur_seed in _train_seeds:
            _bxt_phase = 'train'
        else:
            _bxt_phase = 'per_seed'
        globals()['BXT_PHASE'] = _bxt_phase
        try:
            _spm.BXT_PHASE = _bxt_phase
            # These live in specialized_modes' own globals (dctsp_bxt reads them
            # there), so copy the shim/engine values across explicitly.
            _spm.BXT_LEARN = bool(globals().get('BXT_LEARN', True))
            _spm.BXT_TRAIN_EPSILON = float(globals().get('BXT_TRAIN_EPSILON', 0.1))
            # Q-table freeze policy. Default False = the table is NEVER frozen:
            # eval-phase seeds keep crediting realized delay like train seeds.
            # Set BXT_FREEZE_ON_EVAL = True (engine or controller) only to
            # reproduce a legacy frozen-policy run.
            _spm.BXT_FREEZE_ON_EVAL = bool(globals().get('BXT_FREEZE_ON_EVAL', False))
        except Exception:
            pass
        # ── CPD-QL train/eval seed split (same policy: with the default
        # BXT_FREEZE_ON_EVAL=False the CPD-QL table also stays live on eval
        # seeds).  Falls back to per_seed.
        if not (_cpd_train_seeds or _cpd_eval_seeds):
            _cpd_phase = 'per_seed'
        elif _cur_seed in _cpd_eval_seeds:
            _cpd_phase = 'eval'
        elif _cur_seed in _cpd_train_seeds:
            _cpd_phase = 'train'
        else:
            _cpd_phase = 'per_seed'
        globals()['CPDQL_PHASE'] = _cpd_phase
        try:
            _spm.CPDQL_PHASE = _cpd_phase
            _spm.CPDQL_TRAIN_EPSILON = float(globals().get('CPDQL_TRAIN_EPSILON', 0.3))
            _spm.CPDQL_LEARN = bool(globals().get('CPDQL_LEARN', True))
        except Exception:
            pass
        try:
            if _bxt_phase == 'per_seed':
                _spm.reset_bxt_learning()                 # independent episode
            elif _bxt_phase == 'train' and _train_seeds and _cur_seed == _train_seeds[0]:
                _spm.reset_bxt_learning()                 # fresh start of training
            # train (later seeds): accumulate; eval: keep trained Q-table
            try:
                _qt = getattr(_spm, '_dctsp_bxt_q_table', {}) or {}
                _qsz = sum(len(v) for v in _qt.values()
                           if isinstance(v, dict))
            except Exception:
                _qsz = -1
            log_to_file(f"[BXT_PHASE] seed={_cur_seed} phase={_bxt_phase} "
                        f"train={_train_seeds} eval={_eval_seeds} "
                        f"freeze={_spm.BXT_FREEZE_ON_EVAL} "
                        f"q_states={_qsz}", force=True)
        except Exception as _rl_err:
            log_to_file(f"[INIT] bxt phase/reset failed: {_rl_err!r}", force=True)
        try:
            if _cpd_phase == 'per_seed':
                _spm._cpdql_reset()                       # independent episode
            elif _cpd_phase == 'train' and _cpd_train_seeds and _cur_seed == _cpd_train_seeds[0]:
                _spm._cpdql_reset()                       # fresh start of CPD-QL training
            log_to_file(f"[CPDQL_PHASE] seed={_cur_seed} phase={_cpd_phase} "
                        f"train={_cpd_train_seeds} eval={_cpd_eval_seeds}", force=True)
        except Exception as _rl_err:
            log_to_file(f"[INIT] cpdql phase/reset failed: {_rl_err!r}", force=True)
        # Engine-global copies of every mode toggle that gates a code path in
        # this module (the loops below only ever SET, never clear, so these
        # must start False each experiment).
        for _tog in ('DCTSP_ZIG_MODE', 'MP_ECTM_MODE', 'MP_ECTM_DP_MODE',
                     'BXT_MODE', 'CPDQL_MODE',
                     'CELLQLEARN_DP_MODE',
                     'BARGAIN_SPM_MODE', 'META_TSP_MODE', 'MDN_DELAY_MODE',
                     'HS_EXT_MODE', 'REWARD_SELFORG_MODE', 'REWARD_INV_DELAY_MODE',
                     'REWARD_V2X_MODE', 'GLOBAL_REWARD_MODE',
                     'DCTSP_GREEN_REALLOC_MODE', 'CENTRALIZED_MODE',
                     'DCTSP_CONGESTION_GATE'):
            globals()[_tog] = False
        # Clear the per-run decision-window override so a previous replication's
        # value cannot leak into experiments that do not set it.
        globals()['TSP_CYCLE_LENGTH_OVERRIDE_S'] = None
        globals()['PHASE_SEQ_MAX_PER_CYCLE'] = 0
        globals()['BUS_FREQ_INJECT_SCALAR'] = 0.0
        # NOTE (mode dispatch): CONTROL_MODE / COORDINATED_TSP /
        # COORDINATION_ALGO / GROUP_BASED_BUS_PRIORITY /
        # TSP_ACTIVE_INTERSECTIONS are deliberately NOT reset here. They are
        # propagated from run_config.py below *only when present*, so GUI /
        # single runs keep their controller-file values while batch runs
        # (whose write_run_config always emits these keys) switch per run.
        # Resetting them unconditionally would break manual workflows.
        globals()['SKIP_PER_RUN_PLOTS'] = False
        globals()['MEASURED_STATE_FEED'] = False
        globals()['MEASURED_QUEUE_FEED'] = False
        globals()['_MEAS_FEED'] = {"den": 0, "cap": 0, "seen": 0}
        globals()['_MEAS_FEED_LOGGED'] = False
        globals()['CURRENT_DEMAND_SCALAR'] = 1.0

        # Propagate all mode flags from run_config.py into global namespace
        for _k in ('DCTSP_ZIG_MODE', 'BARGAIN_SPM_MODE', 'META_TSP_MODE',
                   'MDN_DELAY_MODE', 'BXT_MODE', 'CPDQL_MODE',
                   'CPDQL_ALPHA', 'CPDQL_GAMMA', 'CPDQL_EPSILON',
                   'CPDQL_TRAIN_EPSILON', 'CPDQL_W_H', 'CPDQL_CAR_OCC',
                   'CPDQL_MIN_GAIN_S',
                   'CELLQLEARN_DP_MODE', 'MP_ECTM_MODE',
                   'MP_ECTM_DP_MODE',
                   'HS_EXT_MODE', 'REWARD_SELFORG_MODE', 'REWARD_INV_DELAY_MODE',
                   'REWARD_V2X_MODE', 'GLOBAL_REWARD_MODE',
                   'DCTSP_GREEN_REALLOC_MODE', 'GREEN_REALLOC_RECOVER_FRACTION',
                   'DCTSP_CONGESTION_GATE', 'DCTSP_CONGESTION_GATE_FRACTION',
                   'CENTRALIZED_MODE', 'CENTRALIZED_INTERVAL_S',
                   'BUS_PREDICTOR_TYPE', 'NETWORK_FACTOR', 'ZIG_BALANCE_FACTOR',
                   'ZIG_GE_BALANCE_FACTOR',
                   'ZIG_PHASE_OVERLAP_S', 'ZIG_MIN_GAIN_S', 'ZIG_ENABLE_GE',
                   'ZIG_ENABLE_INS', 'ZIG_ENABLE_GR', 'ZIG_ENABLE_SEQ',
                   'PHASE_ROTATION_MODE', 'PHASE_ROTATION_N_SEQS',
                   'PHASE_ROTATION_THRESHOLD_S',
                   'WOBJ_ALPHA', 'WOBJ_BETA', 'WOBJ_GAMMA',
                   'WOBJ_Z1_SCALE', 'WOBJ_Z2_SCALE', 'WOBJ_Z3_SCALE', 'WOBJ_Z4_SCALE',
                   'REWARD_ALPHA', 'REWARD_BETA', 'REWARD_GAMMA',
                   'REWARD_MAIN_SECTION_WEIGHT', 'REWARD_SIDE_SECTION_WEIGHT',
                   'META_DT_S', 'META_BASE_BUS_WEIGHT', 'META_HW_SENSITIVITY',
                   'META_HW_REF_S', 'META_MIN_THRESHOLD_PAX_S', 'META_BALANCE_FACTOR',
                   'META_MIN_BUS_DELAY_S', 'META_OC_WEIGHT', 'META_CAR_OCC',
                   'META_LATENESS_TAKEOVER_S',
                   'DETECTION_PROB', 'BUS_OCC_OVERRIDE', 'CAR_OCC_OVERRIDE',
                   'REWARD_FUTURE_HORIZON_CYCLES', 'REWARD_FUTURE_DEBT_GAIN', 'REWARD_FUTURE_OFFSET_GAIN',
                    'TSP_CYCLE_LENGTH_OVERRIDE_S', 'PHASE_SEQ_MAX_PER_CYCLE',
                    'BUS_FREQ_INJECT_SCALAR', 'MEASURED_STATE_FEED',
                    'MEASURED_QUEUE_FEED', 'SKIP_PER_RUN_PLOTS',
                   'INV_DELAY_EPSILON', 'INV_DELAY_CAR_WEIGHT', 'INV_DELAY_MIN_DELAY_S',
                   'V2X_MAX_BUS_OCC', 'V2X_CROWDING_SCALE', 'V2X_EPSILON',
                   'V2X_MIN_DELAY_S', 'V2X_BALANCE_FACTOR',
                   'SELFORG_MIN_BUS_DELAY_S', 'SELFORG_BALANCE_FACTOR',
                   'SELFORG_MAX_SE_S', 'SELFORG_MIN_SE_S', 'SELFORG_SE_FRACTION',
                   'SELFORG_PHASE_OVERLAP_S',
                   'MP_ECTM_DT_S', 'MP_ECTM_MIN_EXT_S', 'MP_ECTM_MAX_EXT_S',
                   'MP_ECTM_CAR_OCC', 'MP_ECTM_BALANCE_FACTOR',
                   'MP_ECTM_GE_BALANCE_FACTOR',
                   'MP_ECTM_DP_HORIZON_S', 'MP_ECTM_DP_STAGE_S',
                   'MP_ECTM_DP_COORD_WEIGHT',
                    'BXT_DT_S', 'BXT_EPSILON', 'BXT_ALPHA', 'BXT_GAMMA',
                    'BXT_CAR_OCC', 'BXT_BALANCE_FACTOR',
                    'BXT_GE_BALANCE_FACTOR', 'BXT_MAX_INS_S',
                    # 2026-09-30 ablation sweep: these MUST be on this whitelist
                    # or an arm that sets them via run_config silently keeps the
                    # controller-file default and every ablation row comes back
                    # byte-identical (the same failure documented for CONTROL_MODE
                    # on 2026-09-09: "95 rows byte-identical per seed").
                    'BXT_BARGAIN_DECISION', 'BXT_BARGAIN_PT', 'BXT_BARGAIN_PC',
                   # virtual-detector reach from the signal plan (per-run
                   # switchable so it can be A/B'd without editing the controller)
                   'VIRTUAL_DET_FROM_PLAN', 'VIRTUAL_DET_VC_TARGET',
                   'EXCLUDE_BUS_FROM_CAR_QUEUE',
                   'VIRTUAL_DET_SAFETY', 'VIRTUAL_DET_MARGIN_M',
                   'VIRTUAL_DET_MIN_M', 'VIRTUAL_DET_MAX_M',
                    'BXT_BARGAIN_MIN_N',
                    'PREARM_CYCLE_END_ONLY', 'GE_UB_CAP_BY_JCT',
                   'HS_EXT_T_MIN', 'HS_EXT_T_MAX', 'HS_EXT_HMS', 'HS_EXT_HMCR',
                   'HS_EXT_PAR', 'HS_EXT_BW', 'HS_EXT_NITER',
                   'MDN_DDT_POWER', 'MDN_N_COMPONENTS', 'MDN_EPSILON',
                   'BG_DET_LVL_IMM_S', 'BG_DET_LVL_NEAR_S', 'BG_DET_LVL_FAR_S',
                   'BG_BUS_W_IMM', 'BG_BUS_W_NEAR', 'BG_BUS_W_FAR', 'BG_BUS_W_VFAR',
                   'BG_SPM_RISK_WEIGHT', 'BG_EQ_FAIRNESS_WEIGHT', 'BG_MIN_BUS_DELAY_S',
                   'BG_MIN_GAIN_S', 'BG_CASCADE_MULT', 'BG_MB_WEIGHT',
                   'PARETO_SELECTION_MODE', 'Z4_TOLERANCE_VEH_S',
                   'REWARD_TSP_ENABLE_GE', 'REWARD_TSP_ENABLE_INS',
                       'DCTSP_W_H', 'DCTSP_CAR_WEIGHT', 'NETWORK_FACTOR_DENSITY_RAMP',
                         'CROSS_TRAFFIC_COST_MULTIPLIER',
                    'TWOWAY_BAND_MODE', 'B_PLUS_MIN', 'B_MINUS_MIN',
                    'TWOWAY_GREEN_S',
                        'MILP_MPC_HORIZON_S', 'MILP_MPC_REPLAN_S',
                        'MILP_MPC_TIME_LIMIT_S', 'MILP_MPC_EPSILON_LATE_S',
                        'MILP_MPC_EPSILON_Z4_S', 'MILP_MPC_Z4_BASELINE',
                        'MILP_MPC_ACTION_S',
                   'REWARD_FUTURE_DEBT_GAIN', 'REWARD_FUTURE_OFFSET_GAIN',
                   'CURRENT_DEMAND_SCALAR', 'SIDE_QUEUE_ZONE_M',
                   'MAIN_QUEUE_ZONE_M',
                   # Mode dispatch: must switch per replication (see reset
                   # block above). Values come from batch write_run_config,
                   # derived from the same strategy map as set_control_mode.
                   'CONTROL_MODE', 'COORDINATED_TSP', 'COORDINATION_ALGO',
                   'COORD_PREARM_ENABLED',
                   'GROUP_BASED_BUS_PRIORITY', 'TSP_ACTIVE_INTERSECTIONS'):
            if _k in _rc_ns2:
                globals()[_k] = _rc_ns2[_k]
        # Z4 (total corridor travel time / vehicles serviced) is a HARD
        # constraint by design (epsilon-constraint method, see
        # _pareto_select_candidates): run_config may tune Z4_TOLERANCE_VEH_S
        # but can never disable the gate itself. Deliberately NOT in the
        # propagation list above — force-set here no matter what.
        if not bool(_rc_ns2.get('Z4_CONSTRAINT_MODE', True)):
            log_to_file("[INIT] run_config requested Z4_CONSTRAINT_MODE=False — "
                        "IGNORED: Z4 is enforced as a hard constraint", force=True)
        # Z4 gate now honors configuration (hard-gate era retired)
        # Propagate specialized TSP mode flags from _spm module
        for _k in _spm.MODE_FLAGS:
            if _k in _rc_ns2:
                val = _rc_ns2[_k]
                setattr(_spm, _k, val)
                globals()[_k] = val
        # The action-duration grids (GE/INS/ER/GR_DURATIONS_S) are STRUCTURAL --
        # DCTSP_RL_ACTION_SPACE is built from them at import, so a run_config
        # override only takes effect after an explicit rebuild.
        try:
            if hasattr(_spm, 'rebuild_action_space'):
                _spm.rebuild_action_space()
                log_to_file(f"[INIT] action grid GE={_spm.GE_DURATIONS_S} "
                            f"INS={_spm.INS_DURATIONS_S} ER={_spm.ER_DURATIONS_S} "
                            f"GR={_spm.GR_DURATIONS_S} "
                            f"(|A|={len(_spm.DCTSP_RL_ACTION_SPACE)})", force=True)
        except Exception as _ase:
            log_to_file(f"[INIT] action-space rebuild skipped: {_ase!r}", force=True)
        # Propagate weighted-objective preferences to specialized_modes so
        # _dctsp_eval_action can apply Z1 (delay) / Z2 (progression) /
        # Z3 (headway) preference weights at decision time.
        for _k in ('WOBJ_ALPHA', 'WOBJ_BETA', 'WOBJ_GAMMA'):
            setattr(_spm, _k, globals().get(_k, 0.0))
        # BXT_SOLVER (string): selects the action-MAGNITUDE solver in
        # specialized_modes -- 'deficit' = closed-form green the bus actually
        # needs to clear (non-degenerate for stopped buses); 'harmony'/'golden' =
        # optimise the shockwave objective, which returns ~0 bus delay for a
        # STOPPED bus so every action is vetoed to NO_ACTION. It is READ from
        # _spm globals (specialized_modes.py:2054) AND engine globals
        # (_solve_timing_min), but was in NEITHER the propagation list nor _spm's
        # module defaults -- so a run_config BXT_SOLVER='deficit' silently fell
        # back to 'harmony' and the deficit path NEVER ran (CELLQLEARN fired 0
        # actions despite the arm setting deficit). Copy it to both. (2026-09-09)
        _bxt_solver_val = str(_rc_ns2.get('BXT_SOLVER', 'harmony')).lower()
        try:
            setattr(_spm, 'BXT_SOLVER', _bxt_solver_val)
        except Exception:
            pass
        globals()['BXT_SOLVER'] = _bxt_solver_val
        log_to_file(f"[INIT] BXT_SOLVER='{_bxt_solver_val}' "
                    "(deficit=closed-form bus green-need; harmony/golden optimise "
                    "the shockwave objective that is degenerate for stopped buses)",
                    force=True)
        # BXT_NET_BENEFIT_GATE (bool): when True, a BXT action is vetoed unless
        # the bus benefit exceeds its cross-traffic cost (read in
        # specialized_modes) -- keeps TSP from acting net-negative on a
        # car-dominated corridor. Same propagation gap as BXT_SOLVER: must reach
        # _spm globals or it silently stays False.
        _nbg_val = bool(_rc_ns2.get('BXT_NET_BENEFIT_GATE', False))
        try:
            setattr(_spm, 'BXT_NET_BENEFIT_GATE', _nbg_val)
        except Exception:
            pass
        globals()['BXT_NET_BENEFIT_GATE'] = _nbg_val
        log_to_file(f"[INIT] BXT_NET_BENEFIT_GATE={_nbg_val}", force=True)
        # CASCADE_COST_MODE (bool): add the CTM cell-to-cell downstream-spillback
        # cost to _dctsp_cross_traffic_delay_s so the gate + Nash bargain price the
        # true network cost, not just the local cell. Read from engine globals.
        _casc_val = bool(_rc_ns2.get('CASCADE_COST_MODE', False))
        globals()['CASCADE_COST_MODE'] = _casc_val
        if 'CASCADE_SAT_THRESHOLD' in _rc_ns2:
            try:
                globals()['CASCADE_SAT_THRESHOLD'] = float(_rc_ns2['CASCADE_SAT_THRESHOLD'])
            except Exception:
                pass
        for _ck in ('CASCADE_HORIZON', 'CASCADE_TURN_FRACTION', 'CASCADE_SPILL_GAIN'):
            if _ck in _rc_ns2:
                try:
                    globals()[_ck] = _rc_ns2[_ck]
                except Exception:
                    pass
        log_to_file(f"[INIT] CASCADE_COST_MODE={_casc_val} "
                    f"thr={globals().get('CASCADE_SAT_THRESHOLD', 0.45)} "
                    f"spill_gain={globals().get('CASCADE_SPILL_GAIN', 2.0)} "
                    f"(projected-saturation cascade)", force=True)
        log_to_file(f"[INIT] TWOWAY_BAND_MODE={bool(globals().get('TWOWAY_BAND_MODE', False))} "
                    f"B+={globals().get('B_PLUS_MIN', 0.0)} "
                    f"B-={globals().get('B_MINUS_MIN', 0.0)} "
                    f"G={globals().get('TWOWAY_GREEN_S', 35.0)}", force=True)
        # ── Arm audit: effective decision flags for THIS run (2026-09-25) ──
        # One line proving what the decider will actually read (engine
        # namespace, post-reset+propagation). Motivation: base DCTSP_MARL once
        # inherited CONTINUOUS_MONITOR_MODE=True from the previous arm and ran
        # a bit-identical action stream to MARL_CONT -- invisible without this.
        try:
            log_to_file(
                f"[ARM] exp={_CURRENT_EXPERIMENT} "
                f"CONT={bool(globals().get('CONTINUOUS_MONITOR_MODE', False))}/"
                f"BXTc={bool(globals().get('BXT_CONTINUOUS_MODE', False))} "
                f"MONGATE={bool(globals().get('MONITOR_STATE_GATE', True))}/"
                f"{bool(globals().get('SIDLESS_MONITOR_HOLD', True))} "
                f"QFLOOR={bool(globals().get('SIDE_QUEUE_FLOOR', True))} "
                f"SEEDWARM={float(globals().get('DEMAND_SEED_WARM_S', 300.0)):.0f}s "
                f"MEAS={bool(globals().get('MEASURED_STATE_FEED', False))}/"
                f"{bool(globals().get('MEASURED_QUEUE_FEED', False))}/"
                f"{bool(globals().get('MEASURED_SIDE_COST', False))} "
                f"CASC={bool(globals().get('CASCADE_COST_MODE', False))} "
                f"BXTgate={bool(globals().get('BXT_NET_BENEFIT_GATE', False))} "
                f"MINBUSd={float(globals().get('SELFORG_MIN_BUS_DELAY_S', 0.0)):.0f}s "
                f"MINCELLq={float(globals().get('CELLQLEARN_MIN_GAIN_S', 0.0)):.0f}s "
                f"VETO={float(globals().get('DECIDER_COST_VETO_RATIO', 0.0)):.1f} "
                f"CONG={bool(globals().get('DCTSP_CONGESTION_GATE', False))}/"
                f"{float(globals().get('DCTSP_CONGESTION_GATE_FRACTION', 0.0)):.2f} "
                f"GRMODE={bool(globals().get('GLOBAL_REWARD_MODE', False))} "
                f"PRED={str(globals().get('BUS_PREDICTOR_TYPE', '?'))} "
                f"COORD={str(globals().get('COORDINATION_ALGO', '?'))}",
                force=True)
        except Exception as _arme:
            log_to_file(f"[ARM] audit failed: {_arme!r}", force=True)
        # ── Decision-gate flag audit (2026-09-10) ────────────────────────
        # One force-logged line recording the EXACT gate values the candidate
        # generators will read at decision time, from BOTH namespaces that
        # read them (engine globals for REWARD_TSP_ENABLE_*, _spm for the
        # rest), plus module-identity fingerprints. Motivation: 2026-09-09
        # MARL runs evaluated starved {NO_ACTION,GE_5,GE_10} pools (all
        # NO_ACTION) while this banner's MODES line showed correct values --
        # i.e. a split between AAPIInit-time and decision-time flag state
        # (stale/foreign module instance or post-INIT clobber). If a future
        # run goes quiet, this line tells instantly whether the gates were
        # already dead at INIT (plumbing) or died mid-run (instance swap).
        try:
            _sm = sys.modules.get('shared_tsp_engine.specialized_modes')
            _sm_top = sys.modules.get('specialized_modes')
            _eng_mod = sys.modules.get(__name__)
            log_to_file(
                f"[FLAGS] exp={_CURRENT_EXPERIMENT} "
                f"ZIG_GE={bool(getattr(_spm, 'ZIG_ENABLE_GE', '?'))}/"
                f"INS={bool(getattr(_spm, 'ZIG_ENABLE_INS', '?'))}/"
                f"GR={bool(getattr(_spm, 'ZIG_ENABLE_GR', '?'))}/"
                f"SEQ={bool(getattr(_spm, 'ZIG_ENABLE_SEQ', '?'))} "
                f"GRMODE_spm={bool(getattr(_spm, 'DCTSP_GREEN_REALLOC_MODE', '?'))} "
                f"GREWARD_spm={bool(getattr(_spm, 'GLOBAL_REWARD_MODE', '?'))} "
                f"EN_GE={bool(globals().get('REWARD_TSP_ENABLE_GE', '?'))}/"
                f"INS={bool(globals().get('REWARD_TSP_ENABLE_INS', '?'))} "
                f"PRMODE={bool(getattr(_spm, 'PHASE_ROTATION_MODE', '?'))} "
                f"snap_SEQ={_spm._MODE_FLAG_DEFAULTS.get('ZIG_ENABLE_SEQ', '?')} "
                f"spm_id={id(_spm)} pkgmatch={_sm is _spm} topmatch={_sm_top is _spm} "
                f"eng_self={getattr(_eng_mod, '__dict__', None) is globals()} "
                f"build={ENGINE_BUILD}",
                force=True)
        except Exception as _fl_e:
            try:
                log_to_file(f"[FLAGS] audit failed: {_fl_e!r}", force=True)
            except Exception:
                pass
        # Corridor coordination depth — how many downstream junctions a bus
        # detection pre-arms. Falls back to the class default (1) when the
        # batch runner doesn't set it, so existing run_config.py files are unaffected.
        if 'COORD_DOWNSTREAM_HOPS' in _rc_ns2:
            try:
                CorridorCoordinator.MAX_PRE_ARM = max(1, int(_rc_ns2['COORD_DOWNSTREAM_HOPS']))
            except Exception:
                pass
    except Exception as _rc_err:
        # A failure here silently disables ALL mode flags for the whole run —
        # never swallow it without a trace.
        try:
            log_to_file(f"[INIT] run_config propagation FAILED: {_rc_err!r} — "
                        f"mode flags may be stale defaults", force=True)
        except Exception:
            pass

    # ── Active-mode banner: one force-logged line so every run records which
    # strategy dispatch paths and gates were actually live.
    try:
        log_to_file(
            f"[MODES] experiment={_CURRENT_EXPERIMENT} "
            f"ZIG={bool(_spm.DCTSP_ZIG_MODE)} "
            f"ECTM={bool(_spm.MP_ECTM_MODE)} "
            f"ECTM_DP={bool(getattr(_spm, 'MP_ECTM_DP_MODE', False))} "
            f"BXT={bool(getattr(_spm, 'BXT_MODE', False))} "
            f"CELLQLEARN_DP={bool(getattr(_spm, 'CELLQLEARN_DP_MODE', False))} "
            f"BARGAIN={bool(getattr(_spm, 'BARGAIN_SPM_MODE', False))} "
            f"MILP={bool(getattr(_spm, 'MILP_TSP_MODE', False))} "
            f"MPC={CONTROL_MODE == 'MILP_MPC'} "
            f"GR={bool(_spm.DCTSP_GREEN_REALLOC_MODE)} "
            f"PARETO={bool(globals().get('PARETO_SELECTION_MODE'))} "
            f"Z4={bool(globals().get('Z4_CONSTRAINT_MODE'))}"
            f"/tol={globals().get('Z4_TOLERANCE_VEH_S')} "
            f"GE_EN={bool(globals().get('REWARD_TSP_ENABLE_GE'))} "
            f"INS_EN={bool(globals().get('REWARD_TSP_ENABLE_INS'))} "
            f"NF={_spm.NETWORK_FACTOR}", force=True)
    except Exception:
        pass
    _ts2 = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    _BUS_TRACKING_CSV  = os.path.join(LOG_DIR, f"bus_positions_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _PRESENCE_SNAPSHOT_CSV = os.path.join(LOG_DIR, f"presence_snapshot_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _DET_CSV           = os.path.join(LOG_DIR, f"detection_points_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _WAVE_EVENTS_CSV   = os.path.join(LOG_DIR, f"corridor_wave_events_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _DET_GEOJSON       = os.path.join(LOG_DIR, f"detection_points_{_ts2}.geojson")
    _JUNC_CSV          = os.path.join(LOG_DIR, f"junction_centroids_{_ts2}.csv")
    _RUN_SUMMARY_TXT   = os.path.join(LOG_DIR, f"tsp_run_summary_{_ts2}.txt")
    _QUEUE_SNAPSHOT_CSV = os.path.join(LOG_DIR, f"queue_snapshot_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _NO_INS_SUMMARY_CSV = os.path.join(LOG_DIR, f"no_ins_summary_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _OFFSET_CSV = os.path.join(LOG_DIR, f"green_offsets_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _offset_header_written = False
    _OBJECTIVE_TRACE_CSV = os.path.join(LOG_DIR, f"objective_trace_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _objective_trace_header_written = False
    _DYNAROPAC_DECISION_CSV = os.path.join(LOG_DIR, f"dynaropac_decisions_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _dynaropac_decision_header_written = False

    # ── Read-only model DB integrity preflight (fail-fast) ───────────────────
    if not _preflight_model_db_health():
        return -1

    # ── Reset per-run detection and tracking state ────────────────────────────
    global _marked_detections, _mark_calls_total, _mark_calls_written
    global _bus_zone_state, _bus_zone_entry_time, _bus_seen_ids, _bus_last_nearest_jct
    global _bus_line_id, _bus_track_last_t, _bus_track_header_written
    global _presence_snapshot_header_written
    global _bus_lateness
    global _geojson_features, _ge_events, _wave_events
    global _pt_line_jct_route, _pt_line_section_set, _sec_to_corridor_jct
    global _corridor_jct_incoming, _bus_observed_jcts
    global _bus_type_provisional
    global _last_dashboard_t, _last_extra_stats_t
    global _queue_snap_last_t, _queue_snap_header_written
    global _PT_SEEN, _PT_LAST_ENTRY, _HEADWAY_DEVS, _SCHED_SPACING
    global _SCHED_LAST_DET, _SCHED_LOADED
    _marked_detections.clear()
    _mark_calls_total        = 0
    _mark_calls_written      = 0
    _bus_zone_state.clear()
    _bus_zone_entry_time.clear()
    _bus_seen_ids.clear()
    _bus_last_nearest_jct.clear()
    _bus_line_id.clear()
    _bus_observed_jcts.clear()
    _bus_lateness.clear()
    _bus_track_last_t        = -1e9
    _bus_track_header_written = False
    _presence_snapshot_header_written = False
    _queue_snap_last_t       = -1e9
    _queue_snap_header_written = False
    _geojson_features.clear()
    _ge_events.clear()
    _wave_events.clear()
    _pt_line_jct_route.clear()
    _pt_line_section_set.clear()
    _sec_to_corridor_jct.clear()
    _corridor_jct_incoming.clear()
    _last_dashboard_t        = -1e9
    _last_extra_stats_t      = -1e9
    _PT_SEEN.clear()
    _PT_FIRST_SEEN.clear()
    _PT_LAST_ENTRY.clear()
    _PT_LAST_VID.clear()
    _HEADWAY_DEVS.clear()
    _SCHED_LAST_DET.clear()
    # _SCHED_SPACING and _SCHED_LOADED are SESSION-level (timetable invariant);
    # do NOT clear per replication. Calibration runs once per Aimsun session.
    _SCHED_SEC_TO_LINES.clear()
    try:
        _pt_inj.MANAGER.reset_for_run()
    except Exception as _pt_reset_err:
        log_to_file(f"[PT-INJ] run reset failed: {_pt_reset_err!r}", force=True)
    # Reset the extra-section-stats capture flag so a fresh replication starts
    # clean (the zero-clobber guard in collect_extra_section_stats keys off it).
    try:
        stats._net_extra_captured = False
    except Exception:
        pass
    try:
        stats._sched_devs = []
        stats._schedule_records = []
        stats._sched_pen_pax = 0.0
    except Exception:
        pass
    _bus_type_provisional    = False

    # ── Deterministic Python RNG — makes harmony search repeatable ────────────
    # The Aimsun replication seed controls vehicle-level stochasticity; this
    # seeds the Python random module so harmony-search results are identical
    # across runs regardless of which Aimsun seed is selected.
    random.seed(12345)

    # ── Clear bus-detection polyline circles left from the previous run ────────
    if ALLOW_MODEL_CATALOG_WRITES:
        try:
            from PyANGKernel import GKSystem as _GKS
            _model = _GKS.getSystem().getActiveModel()
            if _model is not None:
                _pl_type = _model.getType("GKPolyline")
                _ann_type = _model.getType("GKAnnotation")
                _n = _clear_existing_markers(_model, [_pl_type, _ann_type])
                if _n and LOG_INIT:
                    AKIPrintString(f"[INIT] Cleared {_n} TSP marker(s) from previous run")
        except Exception:
            pass  # non-fatal — PyANGKernel may not be available in all environments
    else:
        log_to_file(
            "[INIT] Catalog writes disabled — skipping in-model marker cleanup",
            force=True,
        )
    dm = DemandMonitor()
    dm.print_demand("AAPIInit")
    # ── Phase-3 demand scalar (centroid-based OD demand path) ────────────────
    # Apply OD scaling per-replication in AAPIInit so each run gets the correct
    # demand level.  The AAPILoad call captures the baseline; here we apply the
    # actual per-run scalar and re-read the demand-flow profile.
    _demand_scalar = float(globals().get('CURRENT_DEMAND_SCALAR', 1.0) or 1.0)
    # In-engine OD scaling disabled by default (OD_SCALE_IN_ENGINE_ENABLED):
    # console-side multiply is authoritative; see flag rationale above.
    if globals().get('OD_SCALE_IN_ENGINE_ENABLED', False):
        try:
            _apply_od_demand_scalar(_demand_scalar)
        except Exception as _ods_init:
            log_to_file(f"[INIT] AAPIInit OD demand scalar apply failed: {_ods_init!r}",
                        force=True)
    # Reset the profile-loaded flag so _load_demand_flow_profile re-reads OD
    # demand with the newly-scaled values (the module is reused across
    # replications; the flag would otherwise stay True after the first run).
    _reset_demand_profile_flag()
    # ── Demand-rated flow profile (pre-computed MILP q parameters) ──────────
    # Read the OD demand totals once per run so online flow estimators and the
    # Z2 bandwidth formula can use the DEMAND flow (rated veh/h at the
    # operating point), not the microsimulation's t=0 warm-up ramp.  This is
    # the same total the offline MILP receives as q_{i,p,t} / q_{ij,t}.
    try:
        _rated = _load_demand_flow_profile()
        if _rated > 0.0:
            log_to_file(
                f"[DEMAND FLOW] OD-rated corridor flow: {_rated:.0f} veh/h "
                f"({len(_demand_flow_profile)} demand object(s)) — "
                f"flow estimators seeded; measured values take over once Aimsun "
                f"counters warm up", force=True)
    except Exception as _dfl:
        log_to_file(f"[DEMAND FLOW] init error: {_dfl!r}", force=True)
    _occ_bus_ovr = globals().get('BUS_OCC_OVERRIDE')
    _occ_car_ovr = globals().get('CAR_OCC_OVERRIDE')
    for inter_id, config in INTERSECTIONS_CONFIG.items():
        try:
            if _occ_bus_ovr is not None or _occ_car_ovr is not None:
                config = dict(config)
            if _occ_bus_ovr is not None:
                config['BusOcc'] = float(_occ_bus_ovr)
            if _occ_car_ovr is not None:
                config['CarOcc'] = float(_occ_car_ovr)
            stats.register_intersection(config)
            controllers[inter_id] = IntersectionController(config)
        except Exception as e:
            if LOG_INIT: AKIPrintString(f"[INIT] ERROR creating controller {inter_id}: {e}")

    # Clear any bus/car/truck type guesses that may have been left behind by a
    # previous run.  AAPIInit should always resolve these from the current model.
    stats._car_pos = -1
    stats._bus_pos = -1
    stats._truck_pos = -1

    # ── Reset cross-replication caches (2026-09-28) ─────────────────────────
    # CRITICAL: _MANAGE_ORDER holds (iid, controller) references built on the
    # FIRST replication. The batch runner builds NEW IntersectionController
    # objects per replication; a stale _MANAGE_ORDER made replications 2+
    # collect_delay/update on the OLD controllers -> car delay 0, served 1/8
    # (healthy run 1, broken runs 2+). _PLAN_STATE similarly must not carry
    # the previous replication's plans. Both rebuilt fresh here.
    global _MANAGE_ORDER
    _MANAGE_ORDER = None
    _PLAN_STATE.clear()

    # ── Initialise DynaROPAC network-wide optimizer ───────────────────────────
    if CONTROL_MODE == "DYNAOPAC_HARMONY":
        if _DYNAROPAC_AVAILABLE:
            _dynaropac_optimizer = DynaROPACOptimizer(
                time_interval=5.0,
                eta_min=10.0,
                eta_max=60.0,
                car_occupancy=1.5,
            )
            _dynaropac_last_eval_t = -999.0
            log_to_file("[INIT] DynaROPAC HARMONY optimizer initialised "
                        f"({len(controllers)} intersections, eval_interval={_DYNAROPAC_EVAL_INTERVAL_S}s)")
        else:
            log_to_file("[INIT] WARNING: DYNAOPAC_HARMONY requested but dynaropac_controller "
                        "import failed — falling back to HARMONY mode for TSP decisions")

    # ── Log phase-group summary for every GROUP_BASED / DYNAOPAC intersection ─
    if CONTROL_MODE in ("GROUP_BASED", "GROUP_BASED_URTSP", "GROUP_BASED_HARMONY", "DYNAOPAC", "DYNAOPAC_HARMONY"):
        if LOG_INIT:
            log_to_file("[INIT] ===== GROUP-BASED PHASE GROUP SUMMARY =====")
        for iid, ctrl in controllers.items():
            if ctrl.gb is not None:
                gb = ctrl.gb
                n_pg = len(gb.phase_groups)
                if LOG_INIT:
                    detail = " | ".join(
                        f"[{','.join(map(str,g))}](mg={sum(gb.max_green.get(s,40.) for s in g):.0f}s)"
                        for g in gb.phase_groups
                    )
                    log_to_file(
                        f"[INIT] jct={iid} sg_count={len(gb.all_sg)} "
                        f"phase_groups={n_pg} bus_sg={gb.bus_sg} tsp_mode={gb.tsp_mode} | {detail}"
                    )
                    AKIPrintString(
                        f"[INIT] jct={iid} phase_groups={n_pg} "
                        f"bus_sg={gb.bus_sg} bus_phase={gb._bus_aimsun_phase}"
                    )
            else:
                if LOG_INIT:
                    log_to_file(f"[INIT] jct={iid} — GroupBasedController NOT initialised")
                    AKIPrintString(f"[INIT] WARNING jct={iid} — GroupBasedController not initialised")

    # ── Build corridor coordinators from INTERSECTION_GROUPS ─────────────────
    # DYNAOPAC also builds coordinators (uses COORDINATED_TSP / COORDINATION_ALGO
    # to choose shockwave / kalman / adaptive pre-arm policy like GROUP_BASED_HARMONY)
    if CONTROL_MODE in ("GROUP_BASED", "GROUP_BASED_URTSP", "GROUP_BASED_HARMONY", "HARMONY", "REWARD_TSP", "DRL_DENSITY", "DYNAOPAC", "DYNAOPAC_HARMONY", "MILP_MPC"):
        corridor_coordinators = []
        if LOG_INIT:
            log_to_file(f"[INIT] Building corridor coordinators from {len(INTERSECTION_GROUPS)} group(s)")
        for gname, iids in INTERSECTION_GROUPS.items():
            coord = CorridorCoordinator(gname, iids, controllers)
            corridor_coordinators.append(coord)
        if LOG_INIT:
            AKIPrintString(
                f"[INIT] Corridor groups: "
                + ", ".join(
                    f"{c.name}({len(c.inter_ids)} intersections)"
                    for c in corridor_coordinators
                )
            )

    # MILP-MPC is one shared corridor controller. It must be built after the
    # per-junction controllers and corridor coordinators exist.
    _milp_mpc_controller = None
    _milp_mpc_last_step = -1
    if CONTROL_MODE == "MILP_MPC":
        _init_milp_mpc_controller()

    return 0


def _apply_config_patches(iid, config, ctrl, aimsun_n_phases):
    """
    Patch config dict and live controller attributes to match Aimsun's reality.

    Called once per intersection from validate_intersection_configs after the
    comparison is done.  Only writes a field when the live Aimsun value differs
    from what the config has — so a correct config is untouched.

    Patchable fields
    ----------------
    - NumberOfPhases       → from ECIGetNumberPhases
    - GreenPhaseDuration   → from GetPhaseDuration (each phase, 0-based timeSta)
    - SignalGroupIDList     → rebuilt from ECIGetNumberSignalGroupsPhase /
                              ECIGetSignalGroupId preserving config order where
                              IDs still exist, appending new ones at the end
    - PhaseIndex           → remapped so no value exceeds len(UpDetList)-1;
                              values that are out of range are clamped to 0
    - DetDistance          → wrapped to nested list if still flat
    - controller.PhaseIndex, controller.SignalGroupIDList, controller.phase_list
      updated to stay in sync with the patched config

    Cannot patch at runtime
    -----------------------
    - Control type (must be set in Aimsun GUI)
    - UpDetList / BusDet   (detector wiring, would need re-initialisation)
    """
    patches = []

    try:
        # ── 1. NumberOfPhases ─────────────────────────────────────────────
        if config.get('NumberOfPhases') != aimsun_n_phases:
            config['NumberOfPhases'] = aimsun_n_phases
            patches.append(f'NumberOfPhases → {aimsun_n_phases}')

        # ── 2. GreenPhaseDuration — refresh from Aimsun live plan ─────────
        live_durs = []
        for ph in range(1, aimsun_n_phases + 1):
            try:
                live_durs.append(round(GetPhaseDuration(iid, ph, 0.0), 1))
            except Exception:
                cfg_d = config.get('GreenPhaseDuration', [])
                live_durs.append(cfg_d[ph - 1] if ph - 1 < len(cfg_d) else 10.0)

        cfg_durs = config.get('GreenPhaseDuration', [])
        if live_durs != cfg_durs:
            config['GreenPhaseDuration'] = live_durs
            patches.append(f'GreenPhaseDuration → {live_durs}')

        # ── 3. SignalGroupIDList — rebuild from Aimsun, preserve config order
        live_sg_list = []
        for ph in range(1, aimsun_n_phases + 1):
            try:
                n_sg = ECIGetNbSignalGroupsPhaseofJunction(iid, ph, 0.0)
                ph_sgs = []
                for pos in range(1, n_sg + 1):
                    try:
                        ph_sgs.append(ECIGetSignalGroupPhaseofJunction(iid, ph, pos, 0.0))
                    except Exception:
                        pass
            except Exception:
                ph_sgs = []

            # Preserve config ordering for IDs that still exist; append new ones
            cfg_ph_sgs = (config.get('SignalGroupIDList', [])[ph - 1]
                          if ph - 1 < len(config.get('SignalGroupIDList', []))
                          else [])
            aimsun_set = set(ph_sgs)
            ordered = [sg for sg in cfg_ph_sgs if sg in aimsun_set]
            for sg in ph_sgs:
                if sg not in ordered:
                    ordered.append(sg)
            live_sg_list.append(ordered)

        if live_sg_list != config.get('SignalGroupIDList', []):
            config['SignalGroupIDList'] = live_sg_list
            patches.append(f'SignalGroupIDList rebuilt from Aimsun')
            if ctrl is not None:
                ctrl.SignalGroupIDList = live_sg_list

        # ── 4. PhaseIndex — clamp out-of-range values to 0 ───────────────
        up_det = config.get('UpDetList', [])
        n_groups = max(len(up_det), 1)
        phase_idx = dict(config.get('PhaseIndex', {}))
        clamped = {}
        for k, v in phase_idx.items():
            if v >= n_groups:
                phase_idx[k] = 0
                clamped[k] = v
        if clamped:
            config['PhaseIndex'] = phase_idx
            patches.append(f'PhaseIndex clamped {clamped} → 0 (UpDetList has {n_groups} group(s))')
            if ctrl is not None:
                ctrl.PhaseIndex = phase_idx

        # ── 5. DetDistance — ensure nested ───────────────────────────────
        dd = config.get('DetDistance', [])
        if dd and not isinstance(dd[0], (list, tuple)):
            config['DetDistance'] = [dd]
            patches.append(f'DetDistance wrapped to nested')
            if ctrl is not None:
                ctrl.DetDistance = config['DetDistance']
                ctrl.config['DetDistance'] = config['DetDistance']

        # ── 6. Sync controller phase_list ────────────────────────────────
        if ctrl is not None:
            new_pl = list(range(1, aimsun_n_phases + 1))
            if ctrl.phase_list != new_pl:
                ctrl.phase_list = new_pl
                patches.append(f'phase_list → {new_pl}')

    except Exception as ex:
        log_to_file(f'[PATCH] inter={iid} unexpected error: {ex}')
        _vprint(f'[PATCH] WARNING inter={iid}: patch step failed: {ex}')
        return

    if patches:
        msg = f'[PATCH] inter={iid} auto-corrected: ' + ' | '.join(patches)
        log_to_file(msg)
        _vprint(msg)
    else:
        log_to_file(f'[PATCH] inter={iid}: no patches needed')


def validate_intersection_configs():
    """
    Compare every field in INTERSECTIONS_CONFIG against live Aimsun values.

    Checks per intersection
    -----------------------
    1. Control type        — must be 2 or 3 (External API)
    2. Phase count         — ECIGetNumberPhases vs config NumberOfPhases / SignalGroupIDList length
    3. Phase durations     — GetPhaseDuration vs config GreenPhaseDuration
    4. Signal groups/phase — ECIGetNumberSignalGroupsPhase vs len(SignalGroupIDList[phase-1])
    5. Signal group IDs    — ECIGetSignalGroupId vs SignalGroupIDList values
    6. PhaseIndex sanity   — every value must be < len(UpDetList)
    7. DetDistance shape   — must be nested (list of lists) matching UpDetList shape

    Output: full detail to LOG_FILE, summary warnings to Aimsun console.
    """
    SEP  = '=' * 72
    sep2 = '-' * 72

    log_to_file(SEP)
    log_to_file('[VALIDATE] ===== INTERSECTION CONFIG VALIDATION =====')
    log_to_file(SEP)

    total_warnings = 0
    total_errors   = 0

    for iid, config in INTERSECTIONS_CONFIG.items():
        warnings = []
        errors   = []

        cfg_n_phases   = config.get('NumberOfPhases', len(config.get('SignalGroupIDList', [])))
        cfg_sg_list    = config.get('SignalGroupIDList', [])
        cfg_phase_idx  = config.get('PhaseIndex', {})
        cfg_up_det     = config.get('UpDetList', [])
        cfg_det_dist   = config.get('DetDistance', [])
        cfg_green_dur  = config.get('GreenPhaseDuration', [])

        log_to_file(sep2)
        log_to_file(f'[VALIDATE] Junction {iid}')

        # ── 1. Control type ───────────────────────────────────────────────
        try:
            ctrl_type = ECIGetControlType(iid)
            status = 'OK' if ctrl_type in (2, 3) else 'ERROR'
            log_to_file(f'  ControlType : {ctrl_type}  [{status}]  (expected 2 or 3 = External)')
            if ctrl_type not in (2, 3):
                errors.append(f'control type={ctrl_type} (not External)')
        except Exception as ex:
            errors.append(f'ECIGetControlType failed: {ex}')

        # ── 2. Phase count ────────────────────────────────────────────────
        try:
            aimsun_n = ECIGetNumberPhases(iid)
            match = 'OK' if aimsun_n == cfg_n_phases else 'MISMATCH'
            log_to_file(
                f'  Phases      : Aimsun={aimsun_n}  config={cfg_n_phases}  [{match}]')
            if match != 'OK':
                warnings.append(
                    f'phase count Aimsun={aimsun_n} vs config={cfg_n_phases}')
        except Exception as ex:
            errors.append(f'ECIGetNumberPhases failed: {ex}')
            aimsun_n = cfg_n_phases   # best-guess fallback

        # ── 3. Per-phase: duration, signal groups, SG IDs ─────────────────
        for ph in range(1, aimsun_n + 1):
            ph_idx = ph - 1   # 0-based index into config lists

            # Phase duration
            try:
                aimsun_dur = GetPhaseDuration(iid, ph, 0.0)
                if cfg_green_dur and ph_idx < len(cfg_green_dur):
                    cfg_dur = cfg_green_dur[ph_idx]
                    dur_ok  = abs(aimsun_dur - cfg_dur) < 1.0
                    log_to_file(
                        f'  Phase {ph:2d} dur : Aimsun={aimsun_dur:.1f}s  '
                        f'config={cfg_dur:.1f}s  '
                        f'[{"OK" if dur_ok else "MISMATCH"}]')
                    if not dur_ok:
                        warnings.append(
                            f'phase {ph} duration Aimsun={aimsun_dur:.1f}s '
                            f'vs config={cfg_dur:.1f}s')
                else:
                    log_to_file(
                        f'  Phase {ph:2d} dur : Aimsun={aimsun_dur:.1f}s  '
                        f'config=<not specified>')
            except Exception as ex:
                warnings.append(f'phase {ph} duration query failed: {ex}')

            # Signal group count per phase
            try:
                aimsun_sg_n = ECIGetNbSignalGroupsPhaseofJunction(iid, ph, 0.0)
                cfg_sg_n    = len(cfg_sg_list[ph_idx]) if ph_idx < len(cfg_sg_list) else 0
                sg_n_ok     = (aimsun_sg_n == cfg_sg_n)
                log_to_file(
                    f'  Phase {ph:2d} SGs : Aimsun={aimsun_sg_n}  '
                    f'config={cfg_sg_n}  '
                    f'[{"OK" if sg_n_ok else "MISMATCH"}]')
                if not sg_n_ok:
                    warnings.append(
                        f'phase {ph} SG count Aimsun={aimsun_sg_n} '
                        f'vs config={cfg_sg_n}')

                # Signal group IDs per phase
                aimsun_sgs = []
                for pos in range(1, aimsun_sg_n + 1):
                    try:
                        sg_id = ECIGetSignalGroupPhaseofJunction(iid, ph, pos, 0.0)
                        aimsun_sgs.append(sg_id)
                    except Exception:
                        aimsun_sgs.append(None)

                cfg_sgs = cfg_sg_list[ph_idx] if ph_idx < len(cfg_sg_list) else []
                aimsun_set = set(x for x in aimsun_sgs if x is not None)
                cfg_set    = set(cfg_sgs)
                missing_from_cfg    = aimsun_set - cfg_set
                extra_in_cfg        = cfg_set - aimsun_set

                log_to_file(
                    f'  Phase {ph:2d} IDs : Aimsun={sorted(aimsun_sgs)}  '
                    f'config={sorted(cfg_sgs)}')
                if missing_from_cfg:
                    warnings.append(
                        f'phase {ph} SGs in Aimsun but not config: {sorted(missing_from_cfg)}')
                    log_to_file(
                        f'           WARNING: SGs {sorted(missing_from_cfg)} '
                        f'in Aimsun but missing from config')
                if extra_in_cfg:
                    warnings.append(
                        f'phase {ph} SGs in config but not Aimsun: {sorted(extra_in_cfg)}')
                    log_to_file(
                        f'           WARNING: SGs {sorted(extra_in_cfg)} '
                        f'in config but not found in Aimsun')

            except Exception as ex:
                warnings.append(f'phase {ph} SG query failed: {ex}')

        # ── 4. PhaseIndex vs UpDetList range ──────────────────────────────
        n_det_groups = len(cfg_up_det)
        bad_pi = {k: v for k, v in cfg_phase_idx.items()
                  if v >= n_det_groups and n_det_groups > 0}
        if bad_pi:
            errors.append(
                f'PhaseIndex values {bad_pi} exceed UpDetList length {n_det_groups} '
                f'— will cause IndexError in objective functions')
            log_to_file(
                f'  PhaseIndex  : ERROR — values {bad_pi} out of range '
                f'for UpDetList length {n_det_groups}')
        else:
            log_to_file(
                f'  PhaseIndex  : OK (all values < UpDetList length {n_det_groups})')

        # ── 5. DetDistance shape ──────────────────────────────────────────
        if cfg_det_dist:
            if not isinstance(cfg_det_dist[0], (list, tuple)):
                warnings.append(
                    'DetDistance is flat — should be nested list matching UpDetList '
                    '(auto-fixed at runtime, but config should be corrected)')
                log_to_file(
                    f'  DetDistance : WARN flat list {cfg_det_dist} '
                    f'— auto-nested at runtime')
            else:
                log_to_file(f'  DetDistance : OK nested {cfg_det_dist}')

        # ── 6. Resolved corridor sections ─────────────────────────────────
        # Fail loudly when a controller could not resolve ANY main sections —
        # that means zero detectors, zero incoming_sections, and zero
        # corridor KPIs for the whole run (the 17 Aug 0-lines regression).
        try:
            _ctrl = controllers.get(iid)
            _resolved_main = []
            if _ctrl is not None:
                _resolved_main = list(getattr(_ctrl, 'incoming_sections', []) or [])
                if not _resolved_main:
                    _resolved_main = list(getattr(_ctrl, 'main_sections', []) or [])
                if not _resolved_main:
                    _resolved_main = list(
                        (config.get('MainSections', []) or [])
                        + (config.get('call_sections', config.get('BusDet', [])) or []))
            if not _resolved_main:
                errors.append(
                    'controller resolved 0 main/incoming sections — corridor KPIs '
                    'and TSP detections will all be empty for this run')
                log_to_file(
                    '  Sections     : ERROR — 0 main/incoming sections resolved. '
                    'Check detectors, MainSections config, and topology resolution.')
            else:
                log_to_file(
                    f'  Sections     : OK — {len(_resolved_main)} main/incoming '
                    f'section(s) resolved: {sorted(set(_resolved_main))[:12]}')
        except Exception as ex:
            warnings.append(f'main-section resolution check failed: {ex}')

        # ── Summary for this intersection ─────────────────────────────────
        total_warnings += len(warnings)
        total_errors   += len(errors)

        if errors or warnings:
            _vprint(
                f'[VALIDATE] inter={iid} — '
                f'{len(errors)} error(s), {len(warnings)} warning(s)')
            for e in errors:
                _vprint(f'  [VALIDATE ERROR]   inter={iid}: {e}')
            for w in warnings:
                _vprint(f'  [VALIDATE WARN]    inter={iid}: {w}')
        else:
            _vprint(f'[VALIDATE] inter={iid} — OK')

        # ── Auto-patch: fix the config dict and live controller in-place ──
        # Only touches fields where Aimsun's live values differ from config.
        # Skips control-type errors (can't fix at runtime) and missing junctions.
        ctrl = controllers.get(iid)
        _apply_config_patches(iid, config, ctrl, aimsun_n)

    log_to_file(SEP)
    log_to_file(
        f'[VALIDATE] DONE — {total_errors} errors, {total_warnings} warnings '
        f'across {len(INTERSECTIONS_CONFIG)} intersections')
    log_to_file(f'[VALIDATE] Full detail in log: {LOG_FILE}')
    log_to_file(SEP)
    _vprint(
        f'[VALIDATE] Config check complete — '
        f'{total_errors} error(s), {total_warnings} warning(s). '
        f'See log: {LOG_FILE}')


def AAPISimulationReady():
    global controllers

    # ── Backup polyline marker clear (AAPIInit clear may fail if PyANGKernel
    #    is not yet bound; by SimulationReady the model is always accessible) ──
    try:
        from PyANGKernel import GKSystem as _GKS2
        _model2 = _GKS2.getSystem().getActiveModel()
        if _model2 is not None:
            _pl2   = _model2.getType("GKPolyline")
            _ann2  = _model2.getType("GKAnnotation")
            _n2    = _clear_existing_markers(_model2, [_pl2, _ann2])
            if _n2 and LOG_INIT:
                AKIPrintString(f"[SIMREADY] Cleared {_n2} TSP marker(s) from previous run")
    except Exception:
        pass  # non-fatal

    try:
        stats.finalise_init()
    except Exception as e:
        _vprint(f"[TSP] WARNING: finalise_init failed: {e}")

    validate_intersection_configs()

    # Junctions must be set to External/API control type in the Aimsun model
    # GUI before running — this cannot be done via the AAPI at runtime.
    # Verify each junction is actually under external control and warn if not.
    for iid in list(controllers.keys()):
        ctrl_type = ECIGetControlType(iid)
        if ctrl_type not in (2, 3):
            _vprint(
                f"[CONTROL] WARNING: junction {iid} control type={ctrl_type} "                f"— expected 2 or 3 (External). "                f"Set junction to 'External' control in the Aimsun model GUI.")

    # === REBUILD PHASE LIST NOW THAT JUNCTIONS ARE UNDER CONTROL ===
    for iid, ctrl in controllers.items():
        try:
            num_phases = ECIGetNumberPhases(iid)
            ctrl.phase_list = list(range(1, num_phases + 1))
            '''
            _vprint(f"[CONTROL] Junction {iid}: {num_phases} phases → {ctrl.phase_list}")
            '''
        except Exception as e:
            _vprint(f"[CONTROL] WARNING: could not get phases for {iid}: {e}")
        # Per-run viability re-arm: controllers persist across replications
        # in-session, so a disarm at the end of one run must not leak into
        # the next (the gate re-trips on live data if warranted).
        try:
            ctrl._tsp_armed = True
        except Exception:
            pass

    # === RE-INITIALISE GROUP-BASED CONTROLLERS WITH LIVE ECI DATA ===
    # AAPIInit runs before the simulation starts — ECI phase scan may return
    # nothing for junctions not yet active, producing an all-conflict matrix
    # and 1-SG-per-group structure.  Now that the sim is running, re-derive
    # from the live model to get correct phase-based compatibility groupings.
    if CONTROL_MODE in ("GROUP_BASED", "GROUP_BASED_URTSP", "GROUP_BASED_HARMONY", "HARMONY", "REWARD_TSP", "DRL_DENSITY", "DYNAOPAC", "DYNAOPAC_HARMONY"):
        # ── Verify intersections are in External Control mode ─────────────────
        # GROUP_BASED uses ECIChangeSignalGroupState which requires control_type=2/3.
        # HARMONY does not — it rides on top of the normal plan.
        # If an intersection is not External, log a prominent warning.
        _bad_ctrl = []
        for iid, ctrl in controllers.items():
            if ctrl.gb is None:
                continue
            try:
                ct = ECIGetControlType(iid)
                ctrl.gb._external_control = (ct in (2, 3))
                if not ctrl.gb._external_control:
                    _bad_ctrl.append((iid, ct))
            except Exception:
                ctrl.gb._external_control = False
                _bad_ctrl.append((iid, '?'))
        if _bad_ctrl:
            _msg = (
                f"[GB] CRITICAL: {len(_bad_ctrl)} junction(s) NOT in External Control "
                f"mode — GROUP_BASED signals will NOT change (all-red or frozen). "
                f"Set control type = External in Aimsun for: "
                + ", ".join(f"jct={j}(type={t})" for j, t in _bad_ctrl)
            )
            log_to_file(_msg, force=True)   # always prints regardless of VERBOSE

        for iid, ctrl in controllers.items():
            if ctrl.gb is not None and getattr(ctrl.gb, '_external_control', True):
                try:
                    ctrl.gb.reinitialise_from_model()
                except Exception as e:
                    _vprint(f"[GB] WARNING jct={iid} reinitialise_from_model failed: {e}")

        # Compute corridor positions (metres along route) for Kalman coordination.
        # Junction XY is available now that the simulation is running.
        # We walk each corridor group in listed order, accumulating Euclidean
        # distance between consecutive junction centroids.  If XY cannot be
        # resolved for a junction, its position is estimated using the previous
        # gap + a 400 m nominal link length.
        if COORDINATED_TSP:
            NOMINAL_LINK_M = 400.0   # fallback inter-junction spacing
            for coord in corridor_coordinators:
                pos_map   = {}
                cum_pos   = 0.0
                prev_xy   = None
                # Iterate ALL route junctions (managed + unmanaged intermediates) so
                # that _signal_aware_eta can look up corridor positions for every
                # junction the bus passes through, not just the coordinated ones.
                for iid in coord.route_inter_ids:
                    gb = coord._ctrl_map.get(iid)
                    ic = coord._ic_map.get(iid)
                    # For intermediate route junctions not in _ctrl_map / _ic_map,
                    # fall back to the global controllers dict (they may have their
                    # own IntersectionController with XY data).
                    if gb is None and ic is None:
                        _fb = controllers.get(iid)
                        if _fb is not None:
                            ic = _fb
                    # Prefer GroupBasedController XY; fall back to HARMONY IC XY
                    try:
                        xy = gb._get_junction_xy() if gb else None
                        if xy is None and ic is not None:
                            xy = ic._get_junction_xy()
                    except Exception:
                        xy = None
                    if xy is not None and prev_xy is not None:
                        dx = xy[0] - prev_xy[0]
                        dy = xy[1] - prev_xy[1]
                        cum_pos += math.sqrt(dx*dx + dy*dy)
                    elif prev_xy is not None:
                        cum_pos += NOMINAL_LINK_M   # XY unavailable — use nominal
                    pos_map[iid] = cum_pos
                    if xy is not None:
                        prev_xy = xy
                    elif prev_xy is None:
                        prev_xy = (0.0, 0.0)  # anchor first junction at origin
                coord.set_corridor_positions(pos_map)
            _prearm_on = bool(globals().get('COORD_PREARM_ENABLED', True))
            log_to_file(
                f"[CORRIDOR] COORDINATED_TSP=True algo={COORDINATION_ALGO} "
                f"COORD_PREARM_ENABLED={_prearm_on} — "
                + ("full coordination (pre-arm + corridor coupling)" if _prearm_on
                   else "corridor coupling ONLY, downstream pre-arm SUPPRESSED"),
                force=True,
            )
        else:
            log_to_file("[CORRIDOR] COORDINATED_TSP=False — Kalman pre-arming disabled")

    # ── Build PT-route-aware corridor maps (needs controllers + incoming_sections) ──
    try:
        _build_pt_line_corridor_routes()
    except Exception as _ptrb_e:
        log_to_file(f"[PT-ROUTE] WARNING: _build_pt_line_corridor_routes failed: {_ptrb_e}")

    scan_car_pos, scan_bus_pos, scan_truck_pos = _scan_named_vehicle_type_positions()
    pt_bus_pos = _infer_bus_type_pos_from_pt()
    bus_pos = pt_bus_pos if pt_bus_pos > 0 else (
        getattr(stats, '_bus_pos', -1) if getattr(stats, '_bus_pos', -1) > 0 else scan_bus_pos)

    # Resolve truck type: if name-based scan failed AND there are 3+ vehicle types,
    # use the type that is NOT bus and NOT the smallest-numbered (car) type.
    # For a 3-type model (Car=1, Truck=2, Bus=3) or (Car=1, Bus=2, Truck=3):
    # → truck = remaining position after removing bus and car assignments.
    truck_pos = getattr(stats, '_truck_pos', -1)
    if truck_pos <= 0:
        truck_pos = scan_truck_pos
    if truck_pos <= 0:
        nb_types = AKIVehGetNbVehTypes()
        if nb_types >= 3 and bus_pos > 0:
            # Assign truck = the type that is NOT bus and NOT smallest (assumed car)
            candidates = [p for p in range(1, nb_types + 1) if p != bus_pos]
            # Smallest remaining = car; others = truck candidates
            if len(candidates) >= 2:
                car_candidate = min(candidates)
                truck_candidates = [p for p in candidates if p != car_candidate]
                if truck_candidates:
                    truck_pos = truck_candidates[0]

    car_pos = getattr(stats, '_car_pos', -1)
    if car_pos <= 0 or car_pos == bus_pos:
        car_pos = _choose_car_type_pos(bus_pos, truck_pos, preferred_pos=scan_car_pos)

    log_to_file(
        f"[VEH TYPES] named_scan car={scan_car_pos} bus={scan_bus_pos} truck={scan_truck_pos} | "
        f"pt_inferred_bus={pt_bus_pos} | nb_types={AKIVehGetNbVehTypes()} | "
        f"using car={car_pos} bus={bus_pos} truck={truck_pos}")
    for ctrl in controllers.values():
        if car_pos > 0:
            ctrl.car_type_pos = car_pos
        if bus_pos > 0:
            ctrl.bus_type_pos = bus_pos
        if truck_pos > 0:
            ctrl.truck_type_pos = truck_pos
    if car_pos > 0:
        stats._car_pos = car_pos
    if bus_pos > 0:
        stats._bus_pos = bus_pos
    if truck_pos > 0:
        stats._truck_pos = truck_pos
    else:
        stats._truck_pos = -1

    # If bus type still unresolved, schedule a lazy recheck in PostManage
    # (PT vehicles may not exist yet at AAPIInit time)
    global _bus_type_needs_recheck
    global _bus_type_provisional
    _bus_type_needs_recheck = (bus_pos <= 0)
    _bus_type_provisional = _bus_type_needs_recheck
    if _bus_type_needs_recheck:
        log_to_file("[VEH TYPES] bus_pos unresolved at init — will retry from PT vehicles in first 120s")

    _log_startup_bus_demand_snapshot("AAPIInit")
    '''
    _vprint(f"[TSP] Simulation ready | mode={CONTROL_MODE} | {len(controllers)} intersections under external control")
    '''
    return 0


def AAPIManage(time, timeSta, timeTrans, acycle):
    
    return 0


def AAPIPostManage(time, timeSta, timeTrans, acycle):
    # An exception escaping this callback aborts the whole replication and
    # its traceback goes only to the Aimsun console — invisible in our log.
    # (Suspected cause of the NORMAL/NO_TSP runs ending at 450-1200 sim-s.)
    # Wrap the entire body so the log file always records what died.
    try:
        return _aapi_post_manage_impl(time, timeSta, timeTrans, acycle)
    except Exception:
        import traceback as _tb
        log_to_file(
            f"[FATAL] AAPIPostManage crashed t={time:.1f}:\n{_tb.format_exc()}",
            force=True)
        return 0


# ── Cyclic MaxPressure scheduler (Varaiya-faithful) ──────────────────────────
# Re-evaluates stage pressures EVERY simulation step, independent of bus
# detections: FLEX switches to the argmax-pressure stage every T_A (min-green
# + hysteresis guarded); FIX serves a pressure-proportional green split once
# per cycle then round-robins stages. Stands down per-junction whenever any
# bus-TSP state machine is active so it can never fight the priority executor.
_MP_CYCLIC_ERR_LOGGED = [False]


def _mp_queue_pax(ctrl, secs):
    """Live pax-weighted queue on the given sections (cars 1.5 + bus upgrade)."""
    tot = 0.0
    bus_pos = int(getattr(ctrl, 'bus_type_pos', -1) or -1)
    for s in secs or []:
        try:
            n = int(AKIVehStateGetNbVehiclesSection(int(s), False) or 0)
        except Exception:
            continue
        tot += 1.5 * n
        if bus_pos > 0:
            try:
                nb = int(AKIVehStateGetNbVehiclesSection(int(s), True) or 0)
                for vi in range(nb):
                    inf = AKIVehStateGetVehicleInfSection(int(s), vi)
                    if int(getattr(inf, 'type', -1)) == bus_pos:
                        tot += (40.0 - 1.5)
            except Exception:
                pass
    return tot


def _mp_cyclic_switch(ctrl, pl, new_i, time, timeSta, acycle):
    try:
        ECIChangeDirectPhase(ctrl.id, pl[new_i], timeSta, time, acycle, 0)
    except Exception:
        return False
    ctrl._mp_cyc['stage_t'] = time
    ctrl.previous_phase = ECIGetCurrentPhase(ctrl.node_id)
    try:
        ctrl.stats.record_tsp_event(ctrl.id, 'mp_cyclic_switch')
    except Exception:
        pass
    return True


def _mp_cyclic_tick_one(ctrl, time, timeSta, acycle):
    # Stand down whenever a bus-TSP state machine owns this junction.
    if int(getattr(ctrl, 'TSPStrategy', 0) or 0) != 0:
        return
    if float(getattr(ctrl, 'TSPActiveTime', 0.0) or 0.0) > time:
        return
    if float(getattr(ctrl, '_tsp_cycle_grant_until', 0.0) or 0.0) > time:
        return

    pl = list(getattr(ctrl, 'phase_list', []) or [])
    if len(pl) < 2:
        return
    cur_ph = ECIGetCurrentPhase(ctrl.node_id)
    if cur_ph not in pl:
        return
    cur_i = pl.index(cur_ph)

    cfg = getattr(ctrl, 'config', {}) or {}
    main_secs = list(cfg.get('MainSections', []) or [])
    side_secs = list(cfg.get('SideSections', []) or [])
    if not side_secs:
        side_secs = [s for s in list(getattr(ctrl, 'incoming_sections', []) or [])
                     if s not in main_secs]
    main_q = _mp_queue_pax(ctrl, main_secs)
    side_q = _mp_queue_pax(ctrl, side_secs)
    bus_phase = getattr(ctrl, 'BusPhase', None)
    press = [(main_q if ph == bus_phase else side_q) for ph in pl]

    gmin = float(globals().get('MAXPRESSURE_G_MIN',
                               getattr(_spm, 'MAXPRESSURE_G_MIN', 5)) or 5)
    gmax = float(globals().get('MAXPRESSURE_G_MAX',
                               getattr(_spm, 'MAXPRESSURE_G_MAX', 50)) or 50)

    st = getattr(ctrl, '_mp_cyc', None)
    if st is None or 'stage_t' not in st:
        st = ctrl._mp_cyc = {'stage_t': time, 'anchor': time}
    served = time - float(st.get('stage_t', time))

    if bool(getattr(_spm, 'MAXPRESSURE_FLEX_MODE', False)):
        # ── FLEX: every step, serve argmax pressure; min-green + hysteresis ──
        best_i = max(range(len(pl)), key=lambda i: press[i])
        if best_i == cur_i:
            # Starvation guard: never hold one stage beyond G_MAX.
            if served >= gmax and len(pl) > 1:
                others = [i for i in range(len(pl)) if i != cur_i]
                b2 = max(others, key=lambda i: press[i])
                _mp_cyclic_switch(ctrl, pl, b2, time, timeSta, acycle)
            return
        if served < gmin:
            return
        # Hysteresis: only switch on a meaningful pressure advantage.
        if press[best_i] > press[cur_i] * 1.10 + 1.0:
            _mp_cyclic_switch(ctrl, pl, best_i, time, timeSta, acycle)
        return

    # ── FIX: once per cycle, split (cycle - n*T_L) ∝ pressure; round-robin ──
    cyc = float(getattr(ctrl, 'cycle_len_s', 0.0) or 0.0)
    if cyc <= 0.0:
        cyc = float(getattr(_spm, 'MAXPRESSURE_CYCLE_FIX', 120))
    tl = float(globals().get('MAXPRESSURE_T_L',
                             getattr(_spm, 'MAXPRESSURE_T_L', 3)) or 3)
    n = len(pl)
    if time - float(st.get('anchor', time)) >= cyc or 'split' not in st:
        eff = max(cyc - n * tl, n * gmin)
        tp = sum(press)
        if tp <= 0:
            g = [eff / n] * n
        else:
            g = [p / tp * eff for p in press]
        g = [min(max(x, gmin), gmax) for x in g]
        tot = sum(g)
        if tot > 0:
            g = [x / tot * eff for x in g]
        st['split'] = g
        st['anchor'] = time
    split = st.get('split') or []
    if not split or cur_i >= len(split):
        return
    if served >= min(float(split[cur_i]), gmax):
        nxt = (cur_i + 1) % n
        _mp_cyclic_switch(ctrl, pl, nxt, time, timeSta, acycle)


def _mp_cyclic_tick(time, timeSta, acycle):
    if not (getattr(_spm, 'MAXPRESSURE_FIX_MODE', False)
            or getattr(_spm, 'MAXPRESSURE_FLEX_MODE', False)):
        return
    if not bool(globals().get('MAXPRESSURE_CYCLIC',
                              getattr(_spm, 'MAXPRESSURE_CYCLIC', False))):
        return
    for _iid, _c in list(controllers.items()):
        try:
            _mp_cyclic_tick_one(_c, time, timeSta, acycle)
        except Exception as e:
            if not _MP_CYCLIC_ERR_LOGGED[0]:
                _MP_CYCLIC_ERR_LOGGED[0] = True
                log_to_file(f"[MP-CYC] tick error inter={_iid}: {e!r}", force=True)


import shared_tsp_engine.pt_inject as _pt_inj
_PT_INJ_ERR = [0]

# ── Stop-aware ETA bias learner ──────────────────────────────────────────────
# Raw ETA is distance/speed (engine.py detection), which ignores bus-stop
# dwell between detector and stop line -- so extensions fire early and expire
# before the bus arrives (pure cross-street cost). Instead of guessing stop
# geometry, we LEARN each PT line's systematic lateness: first detection of a
# bus records (t0, eta0); when that bus is next seen within ~40 m of the stop
# line, err = now - (t0 + eta0) updates an EWMA bias keyed by line. Future
# ETAs for that line are padded with the bias before any decision uses them.
_ETA_BIAS = {}      # line_key -> EWMA seconds of observed lateness
_ETA_TRACK = {}     # veh_id -> {t0, eta0, line}
BUS_ETA_BIAS_LEARN = True
BUS_ETA_BIAS_ALPHA = 0.35
BUS_ETA_BIAS_MAX_S = 90.0
_ETA_ARRIVAL_M = 40.0
_PT_SEEN = set()              # every PT veh id ever observed (entry detection)
_PT_FIRST_SEEN = {}           # veh_id -> first detection time (session)
_PT_LAST_ENTRY = {}           # line_id -> last first-entry time
_PT_LAST_VID = {}             # line_id -> last veh_id that produced a pair


def _eta_bias_for(line_key):
    return float(_ETA_BIAS.get(line_key, 0.0))


def _eta_bias_update(line_key, err):
    e = max(-15.0, min(float(err), BUS_ETA_BIAS_MAX_S))
    prev = float(_ETA_BIAS.get(line_key, 0.0))
    _ETA_BIAS[line_key] = prev * (1.0 - BUS_ETA_BIAS_ALPHA) + e * BUS_ETA_BIAS_ALPHA

# ── Schedule-adherence weighting ─────────────────────────────────────────────
# Paper principle: buses must stay faithful to the timetable. A bus running
# LATE against its calibrated headway earns amplified TSP priority; an EARLY
# bus earns almost none -- holding it at red is schedule-corrective, so the
# reward naturally implements green-holding without any extra mechanism.
# Spacing (target headway per line) comes from the x1.0 calibration capture;
# without it the feature is inert (multiplier 1.0).
SCHED_ADHERENCE = True
_SCHED_SPACING = {}     # line_id -> target headway s (median calibrated gap)
_SCHED_LAST_DET = {}    # (line_id, ctrl_id) -> last detection time
_HEADWAY_DEVS = []      # observed deviations for finish reporting
_SCHED_LOADED = [False]
_SCHED_SEC_TO_LINES = {}  # first entry section -> PT line IDs
# Per-bus timetable matching (replaces headway-differencing where possible):
# line_id -> sorted scheduled initial-departure times (seconds-since-midnight,
# fixed schedules only; interval lines keep the headway method). Timetable-
# invariant: loaded once per session, never cleared per replication.
_SCHED_DEPARTURES = {}
# Sim wall-clock start (seconds-since-midnight) mapping sim-time -> wall time
# for departure matching; None when unresolvable (headway fallback used).
_SCHED_WALL_START = [None]


def _schedule_line_registry():
    """Build a read-only PT first-section registry for normal runs too."""
    if _SCHED_SEC_TO_LINES:
        return
    try:
        for _li in range(int(AKIPTGetNumberLines())):
            _lid = int(AKIPTGetIdLine(_li))
            if _lid <= 0:
                continue
            try:
                _sec = int(AKIPTGetIdSectionInLine(_lid, 0))
            except Exception:
                continue
            if _sec > 0:
                _SCHED_SEC_TO_LINES.setdefault(_sec, set()).add(_lid)
    except Exception:
        pass


def _gkt_seconds(obj):
    """GKTimeDuration (or plain number) -> float seconds, or None.

    Tries every known accessor because the exact SWIG surface varies by
    Aimsun version; never raises. Order matters: total-seconds accessors
    first (a bare 'seconds' component would read 0-59, not the total)."""
    if obj is None:
        return None
    if isinstance(obj, (int, float)):
        return float(obj) if float(obj) > 0 else None
    for _meth in ("getTimeInSeconds", "toSeconds", "totalSeconds",
                  "getTotalSeconds"):
        try:
            _fn = getattr(obj, _meth, None)
            _v = _fn() if callable(_fn) else _fn
            if isinstance(_v, (int, float)) and float(_v) > 0:
                return float(_v)
        except Exception:
            continue
    for _hn, _mn, _sn in (("getHours", "getMinutes", "getSeconds"),
                          ("hour", "minute", "second"),
                          ("hours", "minutes", "seconds")):
        try:
            _fh = getattr(obj, _hn, None)
            _fm = getattr(obj, _mn, None)
            _fs = getattr(obj, _sn, None)
            _h = _fh() if callable(_fh) else _fh
            if _h is None:
                continue
            _m = _fm() if callable(_fm) else _fm
            _s = _fs() if callable(_fs) else _fs
            return float(_h or 0) * 3600.0 + float(_m or 0) * 60.0 + float(_s or 0)
        except Exception:
            continue
    try:
        _v = float(obj)
        return _v if _v > 0 else None
    except Exception:
        return None


def _sched_sim_wall_start_s(model):
    """Simulation wall-clock start in seconds-since-midnight, or None.

    Needed to pick the timetable schedule active during the run (lines
    carry several: peak / off-peak / weekend). Tries the active scenario's
    initial time through several accessor spellings; never raises."""
    if model is None:
        return None
    for _sc_meth in ("getActiveScenario", "activeScenario",
                     "getCurrentScenario"):
        try:
            _fn = getattr(model, _sc_meth, None)
            if not callable(_fn):
                continue
            _sc = _fn()
            if _sc is None:
                continue
            for _t_meth in ("getInitialTime", "initialTime", "getStartTime",
                            "startTime", "getInitialDateTime"):
                try:
                    _fn2 = getattr(_sc, _t_meth, None)
                    if not callable(_fn2):
                        continue
                    _v = _gkt_seconds(_fn2())
                    if _v is not None:
                        return _v
                except Exception:
                    continue
        except Exception:
            continue
    return None


def _sched_spacing_load_timetable():
    """Load per-line target headways from the MODEL's bus timetables
    (PyANGKernel GKPublicLine.getTimeTables), not from observed entries.

    Per line: walk every timetable x schedule; fixed-type departures give
    explicit times (median gap inside the sim window); interval-type gives
    the headway directly via the mean interval. The schedule used is the
    one active at sim wall-start (latest start <= start); timetable choice
    (weekday/weekend/...) goes to the candidate with the most departures
    inside the sim window, falling back to most departures overall when the
    wall-start is unresolvable. Returns (n_loaded, n_interval, n_fixed).
    Never raises; lines it cannot resolve are left for the CSV fallback."""
    _n_line = _n_int = _n_fix = 0
    try:
        from PyANGKernel import GKSystem as _GKS
        try:
            _model = _GKS.getSystem().getActiveModel()
        except Exception:
            _model = None
        if _model is None:
            return (0, 0, 0)
        try:
            _catalog = _model.getCatalog()
        except Exception:
            return (0, 0, 0)
        _wall_start = _sched_sim_wall_start_s(_model)
        try:
            _n_lines = int(AKIPTGetNumberLines())
        except Exception:
            return (0, 0, 0)
        _win_end = (_wall_start + 4.0 * 3600.0) if _wall_start is not None else None
        for _li in range(_n_lines):
            try:
                _lid = AKIPTGetIdLine(_li)
            except Exception:
                continue
            try:
                _line = _catalog.find(int(_lid))
                if _line is None:
                    continue
                _tts = list(_line.getTimeTables() or [])
            except Exception:
                continue
            _best = None  # (overlap_count, total_count, headway_s, kind)
            for _tt in _tts:
                try:
                    _scheds = list(_tt.getSchedules() or [])
                except Exception:
                    continue
                for _sched in _scheds:
                    try:
                        _s_start = _gkt_seconds(_sched.getTime())
                    except Exception:
                        _s_start = None
                    # Skip schedules that start after the sim window (when
                    # the wall-start is known); otherwise consider all.
                    if (_wall_start is not None and _s_start is not None
                            and _s_start > _wall_start + 3600.0):
                        continue
                    try:
                        _dtype = str(_sched.getDepartureType())
                    except Exception:
                        _dtype = ""
                    _is_interval = ("nterval" in _dtype)
                    try:
                        _deps = list(_sched.getDepartureTimes() or [])
                    except Exception:
                        _deps = []
                    if _is_interval:
                        for _dep in _deps:
                            try:
                                _h = _gkt_seconds(_dep.getMeanTime())
                            except Exception:
                                _h = None
                            if _h is not None and _h > 30.0:
                                _cand = (0, 1, float(_h), "interval", None)
                                if _best is None or _cand[1] > _best[1]:
                                    _best = _cand
                    else:
                        _times = []
                        for _dep in _deps:
                            try:
                                _t = _gkt_seconds(_dep.getDepartureTime())
                            except Exception:
                                _t = None
                            if _t is not None:
                                _times.append(_t)
                        if len(_times) >= 2:
                            _times.sort()
                            if _win_end is not None and _wall_start is not None:
                                _in = [t for t in _times
                                       if _wall_start - 3600.0 <= t <= _win_end]
                            else:
                                _in = _times
                            if len(_in) >= 2:
                                _gaps = [b - a for a, b in zip(_in, _in[1:])
                                         if b - a > 30]
                                if _gaps:
                                    _gaps.sort()
                                    _h = _gaps[len(_gaps) // 2]
                                    _cand = (len(_in), len(_times), float(_h),
                                             "fixed", list(_times))
                                    if (_best is None
                                            or _cand[0] > _best[0]
                                            or (_cand[0] == _best[0]
                                                and _cand[1] > _best[1])):
                                        _best = _cand
            if _best is not None:
                _SCHED_SPACING[int(_lid)] = _best[2]
                # Keep the full fixed departure list for per-bus matching
                # (dev = observed entry - nearest scheduled departure).
                # Interval lines keep the headway method (no fixed times).
                if _best[3] == "fixed" and len(_best) > 4 and _best[4]:
                    _SCHED_DEPARTURES[int(_lid)] = list(_best[4])
                _n_line += 1
                if _best[3] == "interval":
                    _n_int += 1
                else:
                    _n_fix += 1
        # Wall-start maps sim-time -> wall time for departure matching.
        # Timetable-invariant like spacing: set once per session.
        try:
            if _SCHED_WALL_START[0] is None and _wall_start is not None:
                _SCHED_WALL_START[0] = float(_wall_start)
        except Exception:
            pass
    except Exception as _e:
        try:
            log_to_file(f"[SCHED] timetable load failed: {_e!r}", force=True)
        except Exception:
            pass
    return (_n_line, _n_int, _n_fix)


def _model_topo():
    """Session-once network topology from the MODEL (PyANGKernel), as a
    fallback when the AKI turn tables cannot resolve an upstream section
    (virtual connectors like KG 66329/66334 carry no origin node / turns).

    Returns {'org': {sec: origin_node_or_None}, 'by_dest': {node: [secs]},
    'ok': bool}. Built once per Aimsun session (topology is invariant) via
    catalog.find + GKSection.getOrigin/getDestination (doc-verified names);
    every step guarded. Logs the build outcome ONCE so the log shows whether
    the fallback is armed. Never raises; worst case returns ok=False and all
    callers keep their AKI-only behaviour."""
    try:
        _c = globals().get('_MODEL_TOPO')
    except Exception:
        _c = None
    if isinstance(_c, dict) and _c.get('ok') in (True, False) and _c.get('done'):
        return _c
    _topo = {'org': {}, 'by_dest': {}, 'ok': False, 'done': True, 'n': 0}
    try:
        from PyANGKernel import GKSystem as _GKS
        try:
            _model = _GKS.getSystem().getActiveModel()
            _cat = _model.getCatalog() if _model is not None else None
        except Exception:
            _cat = None
        if _cat is None:
            raise RuntimeError("no model/catalog")
        try:
            _n = int(AKIInfNetNbSectionsANG())
        except Exception:
            _n = 0
        for _i in range(max(_n, 0)):
            try:
                _sid = int(AKIInfNetGetSectionANGId(_i))
            except Exception:
                continue
            if _sid <= 0:
                continue
            try:
                _so = _cat.find(_sid)
                if _so is None:
                    continue
                try:
                    _o = _so.getOrigin()
                    _oid = int(_o.getId()) if _o is not None else None
                except Exception:
                    _oid = None
                try:
                    _d = _so.getDestination()
                    _did = int(_d.getId()) if _d is not None else None
                except Exception:
                    _did = None
            except Exception:
                continue
            _topo['org'][_sid] = _oid
            if _did is not None:
                _topo['by_dest'].setdefault(_did, []).append(_sid)
        _topo['n'] = len(_topo['org'])
        _topo['ok'] = _topo['n'] > 0
    except Exception as _e:
        _topo['note'] = repr(_e)
    try:
        globals()['_MODEL_TOPO'] = _topo
    except Exception:
        pass
    try:
        log_to_file(f"[MODEL-TOPO] built={_topo['ok']} sections={_topo['n']} "
                    f"{_topo.get('note', '')}", force=True)
    except Exception:
        pass
    return _topo


def _sched_spacing_load_csv():
    """Legacy CSV calibration: median entry-gap per line from
    pt_entry_calibration.csv. Returns number of lines loaded."""
    try:
        path = os.path.join(globals().get("_CORRIDOR_DIR", ""),
                            "pt_entry_calibration.csv")
        if not os.path.isfile(path):
            return 0
        per = {}
        with open(path, encoding="utf-8") as f:
            for row in f.read().splitlines()[1:]:
                p = row.split(",")
                if len(p) != 2:
                    continue
                try:
                    per.setdefault(int(p[0]), []).append(float(p[1]))
                except Exception:
                    continue
        for lid, ts in per.items():
            ts.sort()
            gaps = [b - a for a, b in zip(ts, ts[1:]) if b - a > 30]
            if gaps:
                gaps.sort()
                _SCHED_SPACING[lid] = gaps[len(gaps) // 2]
        return len(_SCHED_SPACING)
    except Exception:
        return len(_SCHED_SPACING)


def _sched_spacing_load():
    if _SCHED_LOADED[0]:
        return
    _SCHED_LOADED[0] = True
    try:
        # First try: direct timetable API (explicit schedules). NOTE the
        # AKI timetable/frequency calls may not exist in this Aimsun
        # version -- per-line failures fall through silently, and an empty
        # result below falls back to the CSV (which is the proven source).
        _nl = AKIPTGetNumberLines()
        for _li in range(_nl):
            _lid = AKIPTGetIdLine(_li)
            try:
                _tt = AKIPTGetLineTimeTable(_lid)
                if _tt is not None:
                    # Timetable exists - extract departures for simulation period
                    _deps = []
                    _idx = 0
                    while True:
                        try:
                            _dep = AKIPTGetTimeTableDepartureTime(_lid, _idx)
                            if _dep < 0:
                                break
                            _deps.append(float(_dep))
                            _idx += 1
                        except Exception:
                            break
                    if len(_deps) >= 2:
                        _deps.sort()
                        _gaps = [b - a for a, b in zip(_deps, _deps[1:]) if b - a > 30]
                        if _gaps:
                            _gaps.sort()
                            _SCHED_SPACING[int(_lid)] = _gaps[len(_gaps) // 2]
                            continue
            except Exception:
                pass
            # Fallback: frequency-based line (no explicit timetable)
            try:
                _freq = AKIPTGetLineFrequency(_lid)
                if _freq and float(_freq) > 0:
                    _SCHED_SPACING[int(_lid)] = 3600.0 / float(_freq)
            except Exception:
                pass
        if _SCHED_SPACING:
            log_to_file(f"[SCHED] loaded target headways for "
                        f"{len(_SCHED_SPACING)} lines from API", force=True)
            return
        log_to_file("[SCHED] API yielded 0 lines -- trying model timetables",
                    force=True)
    except Exception as e:
        log_to_file(f"[SCHED] spacing load failed: {e!r} -- trying model "
                    f"timetables", force=True)
    # Stage 2: the model's real bus timetables (authoritative headways).
    _n_tt, _n_int, _n_fix = _sched_spacing_load_timetable()
    if _n_tt:
        log_to_file(f"[SCHED] timetable headways for {_n_tt} lines "
                    f"({_n_int} interval, {_n_fix} fixed)", force=True)
    _missing = 0
    try:
        _missing = max(0, int(AKIPTGetNumberLines()) - len(_SCHED_SPACING))
    except Exception:
        pass
    if _missing:
        log_to_file(f"[SCHED] {_missing} line(s) unresolved from timetables "
                    f"-- falling back to pt_entry_calibration.csv", force=True)
    _n_csv = _sched_spacing_load_csv()
    log_to_file(f"[SCHED] CSV calibration loaded for {_n_csv} lines "
                f"(total spacing known: {len(_SCHED_SPACING)})",
                force=True)


def _match_departure_dev(line_id, observed_wall_s):
    """Per-bus schedule deviation from the timetable: observed wall entry
    minus the nearest scheduled initial departure for the line (early
    negative, late positive). Returns None when the line has no fixed
    departures (interval lines, unknown wall-start) so callers fall back
    to the headway method. Never raises."""
    try:
        _deps = _SCHED_DEPARTURES.get(int(line_id))
        if not _deps:
            return None
        _obs = float(observed_wall_s)
        _best_d = None
        for _t in _deps:
            try:
                _d = _obs - float(_t)
            except Exception:
                continue
            if _best_d is None or abs(_d) < abs(_best_d):
                _best_d = _d
        return _best_d
    except Exception:
        return None


def _sched_mult_from_dev(dev):
    """Deviation from target headway (s) -> bus-priority multiplier.
    Late => amplify; early => suppress (red-holding restores schedule)."""
    if dev > 120.0:
        return 1.80
    if dev > 60.0:
        return 1.50
    if dev > 15.0:
        return 1.20
    if dev < -60.0:
        return 0.30
    if dev < -15.0:
        return 0.70
    return 1.00


def _sched_adherence_on_detect(ctrl, line_id, remaining, veh_id=None):
    """Update per-vehicle schedule multiplier at detection time."""
    if not SCHED_ADHERENCE or not line_id:
        return
    _sched_spacing_load()
    sp = _SCHED_SPACING.get(int(line_id))
    if not sp:
        return
    now_s = float(AKIGetCurrentSimulationTime())
    lk = (int(line_id), id(ctrl))
    last = _SCHED_LAST_DET.get(lk)
    _SCHED_LAST_DET[lk] = now_s
    if last is None:
        return
    gap = now_s - last
    if gap <= 30.0:
        return                      # same bus re-detected, not a new headway
    dev = gap - sp
    _HEADWAY_DEVS.append(dev)
    if len(_HEADWAY_DEVS) > 2000:
        del _HEADWAY_DEVS[:1000]
    ctrl._cur_sched_mult = _sched_mult_from_dev(dev)
    if veh_id is not None:
        tr = _ETA_TRACK.get(int(veh_id))
        if tr is not None:
            tr["headway_dev_s"] = dev


def _pt_inj_lazy_init():
    """Arm the injection manager from config + line registry (once per run)."""
    if _pt_inj.MANAGER.armed:
        return
    scalar = float(globals().get('BUS_FREQ_INJECT_SCALAR', 0.0) or 0.0)
    if scalar <= 0.0:
        return
    _pt_inj.MANAGER.configure(scalar, globals().get('_CORRIDOR_DIR', ''))
    try:
        n_lines = AKIPTGetNumberLines()
        for i in range(n_lines):
            lid = int(AKIPTGetIdLine(i))
            # Register EVERY section of the line, not just section 0.  Buses
            # frequently enter the network mid-route (KG measured: only 25 of
            # 251 buses near section[0], so a first-section-only registry
            # captured 10% of entries and the injection plan was starved).
            # Attempt superset per-line association: any section on the route
            # maps the (line, entry-time) pair; calibration/suppression filter
            # by vehicle type to keep the plan bus-only (see AAPIEnterVehicle).
            try:
                n_secs = int(AKIPTGetNumberSectionsInLine(lid))
            except Exception:
                n_secs = 1
            sec_ids = []
            for si in range(max(n_secs, 1)):
                try:
                    _s = int(AKIPTGetIdSectionInLine(lid, si))
                except Exception:
                    continue
                if _s > 0:
                    sec_ids.append(_s)
            if not sec_ids:
                try:
                    _s = int(AKIPTGetIdSectionInLine(lid, 0))
                except Exception:
                    _s = -1
                if _s > 0:
                    sec_ids = [_s]
            if sec_ids:
                _pt_inj.MANAGER.register_line(lid, sec_ids)
    except Exception as e:
        _PT_INJ_ERR[0] += 1
        if _PT_INJ_ERR[0] <= 2:
            log_to_file(f"[PT-INJ] line registry error: {e!r}", force=True)
        return
    if _pt_inj.MANAGER.calibrating:
        log_to_file("[PT-INJ] calibration mode: recording natural bus entries",
                    )
    else:
        _n = _pt_inj.MANAGER.load_calibration()
        total_extras = _pt_inj.MANAGER.build_plans()
        _n_lines = len(_pt_inj.MANAGER.plan)
        log_to_file(f"[PT-INJ] inject x{scalar:g}: calibration="
                    f"{'MISSING' if not _n else 'ok'} ({_n} entries) -> "
                    f"{total_extras} extra buses planned across {_n_lines} lines",
                    )
        if not _n:
            log_to_file("[PT-INJ] WARNING: no calibration file -- run a x1.0 "
                        "baseline first or scaled levels will inject nothing",
                        )


def _pt_inj_tick(time):
    """Execute due bus injections each step (cheap no-op when disarmed)."""
    _pt_inj_lazy_init()
    m = _pt_inj.MANAGER
    if not m.armed:
        return
    if not hasattr(m, 'due_injections'):
        return                          # stale module mix -- skip, never crash
    if m.bus_pos <= 0:
        bp = getattr(stats, '_bus_pos', -1)
        if bp and bp > 0:
            m.set_bus_pos(bp)
        else:
            if time > m.skipped_no_type_until:
                m.skipped_no_type_until = time + 60.0
                log_to_file(f"[PT-INJ] waiting for bus type resolution (t={time:.0f})")
            return
    for lid in m.due_injections(time):
        try:
            AKIPTEnterVeh(int(lid), m.bus_pos, True)
            m.note_injected(lid)
        except Exception as e:
            _PT_INJ_ERR[0] += 1
            if _PT_INJ_ERR[0] <= 5:
                log_to_file(f"[PT-INJ] AKIPTEnterVeh failed line={lid}: {e!r}",
                            )


# ── Pure signal-wait accumulator for buses (paper delay definition) ─────────
# Delay = seconds held at RED on the junction approach (speed < ~3 km/h while
# the bus phase is not green). Stop dwell is service, NOT delay -- excluded by
# construction because we only accumulate while the bus phase is red.
_BUS_SIGWAIT = {}          # veh_id -> {iid, s, occ}


def _pt_sigwait_tick(time):
    if not controllers:
        return
    # ── schedule-deviation capture: first-seen vehicles per line ──────────
    _schedule_line_registry()
    _sched_spacing_load()
    WARMUP_GRACE_S = 60.0     # vehicles seen this early were pre-existing
    try:
        _nl = AKIPTGetNumberLines()
        for _li in range(_nl):
            _lid = AKIPTGetIdLine(_li)
            _nv = AKIGetNbVehiclesFollowingPTLine(_lid)
            for _vi in range(_nv):
                _vid = int(AKIGetVehicleFollowingPTLine(_lid, _vi))
                if _vid in _PT_SEEN:
                    continue
                _PT_SEEN.add(_vid)
                _PT_FIRST_SEEN[_vid] = float(time)
                _H = _SCHED_SPACING.get(int(_lid))
                if not _H:
                    continue
                # PRIMARY: per-bus timetable match (dev = observed entry -
                # nearest scheduled departure). Needs no previous bus, so it
                # runs before (and independently of) the headway fallback.
                # Pre-existing buses (first-seen in the grace window) still
                # skip: their true entry predates the sim.
                dev = None
                _intended = None
                if _PT_FIRST_SEEN.get(_vid, 1e9) > WARMUP_GRACE_S:
                    try:
                        _w0 = _SCHED_WALL_START[0]
                        if _w0 is not None:
                            dev = _match_departure_dev(
                                int(_lid), float(_w0) + float(time))
                    except Exception:
                        dev = None
                if dev is None:
                    # FALLBACK: headway method (interval lines / unknown wall
                    # / pre-existing bus). Needs a previous genuine entry.
                    # earlier-bus validation: only pair with a bus we actually
                    # recorded a first-entry for (not a pre-existing ghost)
                    _prev_vid = _PT_LAST_VID.get(int(_lid))
                    _last = _PT_LAST_ENTRY.get(int(_lid))
                    _PT_LAST_ENTRY[int(_lid)] = float(time)
                    _PT_LAST_VID[int(_lid)] = _vid
                    if _last is None or _prev_vid is None:
                        continue
                    # warm-up guard: skip if this bus OR the previous bus was
                    # already in network at t=0 (first_seen <= WARMUP_GRACE_S)
                    if (_PT_FIRST_SEEN.get(_vid, 1e9) <= WARMUP_GRACE_S or
                        _PT_FIRST_SEEN.get(_prev_vid, 1e9) <= WARMUP_GRACE_S):
                        continue
                    # detection-cycle cluster guard (redundant but kept)
                    if float(time) - _last <= 30.0:
                        continue
                    _s_eff = max(0.3, float(getattr(
                        _pt_inj.MANAGER, "scalar", 1.0) or 1.0))
                    _intended = _last + (_H / _s_eff)
                    dev = float(time) - _intended
                else:
                    _PT_LAST_ENTRY[int(_lid)] = float(time)
                    _PT_LAST_VID[int(_lid)] = _vid
                try:
                    stats.add_schedule_dev(
                        int(_lid), dev, veh_id=_vid,
                        observed_time_s=float(time), intended_time_s=_intended)
                except Exception:
                    pass
    except Exception:
        pass

    sec2j = {}
    for _iid, _c in controllers.items():
        try:
            _cur = ECIGetCurrentPhase(_c.node_id)
        except Exception:
            continue
        _red = (_cur is not None and _cur != _c.BusPhase)
        for _s in (_c.incoming_sections or []):
            try:
                sec2j[int(_s)] = (_iid, _c, _red)
            except Exception:
                continue
    try:
        _nl = AKIPTGetNumberLines()
    except Exception:
        return
    _seen_now = set()
    for _li in range(_nl):
        try:
            _lid = AKIPTGetIdLine(_li)
            _nv = AKIGetNbVehiclesFollowingPTLine(_lid)
        except Exception:
            continue
        for _vi in range(_nv):
            try:
                _vid = AKIGetVehicleFollowingPTLine(_lid, _vi)
                _inf = AKIPTVehGetInf(_vid)
                if _inf.report < 0:
                    continue
                _vid = int(_vid)
                _seen_now.add(_vid)
                _sid = int(_inf.idSection)
                _j = sec2j.get(_sid)
                _rec = _BUS_SIGWAIT.get(_vid)
                if _j is None:
                    if _rec:
                        stats.add_bus_signal_wait(_vid, _rec["iid"],
                                                  _rec["s"], _rec["occ"])
                        _BUS_SIGWAIT.pop(_vid, None)
                    continue
                _iid, _c, _red = _j
                _occ = float(getattr(_c, "BusOcc", 40.0) or 40.0)
                if _rec is None:
                    _rec = _BUS_SIGWAIT.setdefault(
                        _vid, {"iid": _iid, "s": 0.0, "occ": _occ})
                _spd = max(float(_inf.CurrentSpeed) / 3.6, 0.0)
                if _red and _spd < 0.85:      # held at red (< ~3 km/h)
                    _rec["s"] += 1.0
            except Exception:
                continue
    # flush buses that left the network without a finalised crossing
    for _vid in list(_BUS_SIGWAIT.keys()):
        if _vid not in _seen_now:
            _rec = _BUS_SIGWAIT.pop(_vid)
            if _rec["s"] > 0:
                try:
                    stats.add_bus_signal_wait(_vid, _rec["iid"],
                                              _rec["s"], _rec["occ"])
                except Exception:
                    pass


def _pt_sigwait_flush():
    for _vid, _rec in list(_BUS_SIGWAIT.items()):
        try:
            if _rec["s"] > 0:
                stats.add_bus_signal_wait(_vid, _rec["iid"],
                                          _rec["s"], _rec["occ"])
        except Exception:
            pass
    _BUS_SIGWAIT.clear()


# ── Revisable pre-arm plans (rolling-horizon) ────────────────────────────────
# A pre-arm is a statement about the FUTURE and must be revisable: this tick
# re-evaluates every armed plan against the latest adherence multiplier and
# cancels it when fidelity flips (bus now early/on-time => holding at red is
# schedule-corrective).  Executed plans are removed by _record_prearm_success.
def _prearm_plans_tick(time):
    stats_plans = getattr(stats, "_prearm_plans", None)
    if stats_plans is None:
        return
    for key, plan in list(stats_plans.items()):
        if plan.get("status") != "armed":
            continue
        veh_id, inter_id = key
        tr = _ETA_TRACK.get(int(veh_id)) or {}
        mult = float(tr.get("mult", plan.get("mult", 1.0)))
        # Adherence flip: bus now early/on-time -> cancel the intention.
        if mult < 1.0:
            plan["status"] = "cancelled_adherence"
            stats._prearm_stats["cancelled_adherence"] = \
                stats._prearm_stats.get("cancelled_adherence", 0) + 1
            try:
                stats._fired_prearms.pop(key, None)
            except Exception:
                pass
            log_to_file(f"[PREARM] CANCELLED (adherence) bus={veh_id} "
                        f"jct={inter_id} mult={mult:.2f}")
            continue
        # Staleness: no update for 1.5x horizon -> expire silently (legacy path)
        if time - float(plan.get("created", time)) > MAX_PREARM_HORIZON_S * 1.5:
            plan["status"] = "expired"


def _prearm_allow(veh_id):
    """Adherence gate for NEW pre-arms: an early/on-time bus (mult < 1.0)
    should not receive priority preparation -- holding restores schedule."""
    if not SCHED_ADHERENCE:
        return True
    tr = _ETA_TRACK.get(int(veh_id)) or {}
    return float(tr.get("mult", 1.0)) >= 1.0


def _unpack_prearm(_prearm):
    """(veh_id, eta_t, issued_t, route_dir, from_jct) from a corridor pre-arm.

    Accepts the legacy 3-tuple (veh, eta, issued) and the enriched 5-tuple
    (veh, eta, issued, route_dir, from_jct); missing extras default to
    (0, -1). route_dir is +1/-1 along the coordinator's route_index
    (0 = unknown). Never raises (returns Nones) so a malformed payload can
    never wedge control -- callers clear-and-skip on None veh."""
    try:
        _p = tuple(_prearm)
    except Exception:
        return None, None, None, 0, -1
    try:
        _veh = int(_p[0]); _eta = float(_p[1]); _iss = float(_p[2])
    except Exception:
        return None, None, None, 0, -1
    try:
        _dir = int(_p[3]) if len(_p) > 3 else 0
    except Exception:
        _dir = 0
    try:
        _frm = int(_p[4]) if len(_p) > 4 else -1
    except Exception:
        _frm = -1
    return _veh, _eta, _iss, _dir, _frm


def _record_schedule_entry(veh_id, line_ids, now_s):
    """Record schedule deviation when PT follower enumeration is unavailable.

    PRIMARY: per-bus timetable match (dev = observed entry - nearest
    scheduled departure); needs no previous bus. FALLBACK: headway method.
    Pre-existing buses (first-seen in the grace window) skip both: their
    true entry predates the sim."""
    try:
        vid = int(veh_id)
    except Exception:
        return
    if vid in _PT_SEEN:
        return
    _PT_SEEN.add(vid)
    _PT_FIRST_SEEN[vid] = float(now_s)
    _sched_spacing_load()
    scalar = max(0.3, float(getattr(_pt_inj.MANAGER, "scalar", 1.0) or 1.0))
    WARMUP_GRACE_S = 60.0
    try:
        _w0 = _SCHED_WALL_START[0]
    except Exception:
        _w0 = None
    for line_id in line_ids:
        lid = int(line_id)
        headway = _SCHED_SPACING.get(lid)
        if not headway:
            continue
        dev = None
        _intended = None
        if (_PT_FIRST_SEEN.get(vid, 1e9) > WARMUP_GRACE_S
                and _w0 is not None):
            try:
                dev = _match_departure_dev(
                    lid, float(_w0) + float(now_s))
            except Exception:
                dev = None
        if dev is None:
            prev_vid = _PT_LAST_VID.get(lid)
            last = _PT_LAST_ENTRY.get(lid)
            _PT_LAST_ENTRY[lid] = float(now_s)
            _PT_LAST_VID[lid] = vid
            if last is None or prev_vid is None:
                continue
            if (_PT_FIRST_SEEN.get(vid, 1e9) <= WARMUP_GRACE_S or
                _PT_FIRST_SEEN.get(prev_vid, 1e9) <= WARMUP_GRACE_S):
                continue
            if float(now_s) - last <= 30.0:
                continue
            _intended = last + (headway / scalar)
            dev = float(now_s) - _intended
        else:
            _PT_LAST_ENTRY[lid] = float(now_s)
            _PT_LAST_VID[lid] = vid
        try:
            stats.add_schedule_dev(
                lid, dev, veh_id=vid, observed_time_s=float(now_s),
                intended_time_s=_intended)
        except Exception:
            pass




def _init_milp_mpc_controller():
    """Create the single corridor-level MILP-MPC controller for this run
    (OR-Tools CP-SAT when importable, else HiGHS via scipy -- auto)."""
    global _milp_mpc_controller
    if not _MILP_MPC_AVAILABLE:
        _msg = (
            "MILP_MPC requested but its controller module could not be imported: "
            f"{_MILP_MPC_IMPORT_ERROR}. The HiGHS backend needs scipy>=1.9 in the "
            "Aimsun-visible interpreter."
        )
        log_to_file(f"[MILP_MPC] FATAL: {_msg}", force=True)
        raise RuntimeError(_msg)

    configs = {}
    for iid, ctrl in controllers.items():
        cfg = dict(getattr(ctrl, 'config', {}) or {})
        cfg['_MPCPhaseList'] = list(getattr(ctrl, 'phase_list', []) or [])
        configs[int(iid)] = cfg

    coord = corridor_coordinators[0] if corridor_coordinators else None
    _milp_mpc_controller = create_milp_mpc_controller(
        configs,
        corridor_coord=coord,
        horizon_s=float(globals().get('MILP_MPC_HORIZON_S', 300.0) or 300.0),
        replan_every_s=float(globals().get('MILP_MPC_REPLAN_S', 30.0) or 30.0),
        time_limit_s=float(globals().get('MILP_MPC_TIME_LIMIT_S', 1.5) or 1.5),
        epsilon_late_s=float(globals().get('MILP_MPC_EPSILON_LATE_S', 60.0) or 60.0),
        epsilon_Z4_s=float(globals().get('MILP_MPC_EPSILON_Z4_S', 90.0) or 90.0),
        Z4_baseline_veh_h=float(globals().get('MILP_MPC_Z4_BASELINE', 380.0) or 380.0),
    )
    log_to_file(
        f"[MILP_MPC] initialized solver={_milp_mpc_controller.solver_name} "
        f"intersections={len(configs)} horizon={_milp_mpc_controller.T}s "
        f"replan={_milp_mpc_controller.replan_every}s",
        force=True,
    )


def _milp_mpc_prediction(sim_time):
    """Build a live rolling-horizon prediction from the shared engine state."""
    horizon = int(getattr(_milp_mpc_controller, 'T', 300))
    q_arr = {}
    Q_init = {}
    tau_freeflow = {}
    tau_bar = {}
    phi_init = {}

    for iid, ctrl in controllers.items():
        phases = list(getattr(ctrl, 'phase_list', []) or [])
        flow_rows = getattr(ctrl, 'UpFlowList', None)
        queue_rows = getattr(ctrl, 'MaxQueueLength', None)
        phase_index = getattr(ctrl, 'PhaseIndex', {}) or {}
        # Verified-measurement feed (shockwave-grade stats): the sampler keeps
        # latest_section[sec] = fresh per-section state every 30 s. For MPC
        # INITIAL queues, measured state beats the shockwave-theory max, so it
        # takes precedence when fresh (<=90 s old); the theory max remains the
        # fallback. Arrival forecasts stay detector-driven (verified section
        # totals don't split across phases without extra assumptions).
        # NOTE: `stats` arrives via bind_config from the corridor module; the
        # whole feed below is guarded so exotic import contexts keep working.
        for phase in phases:
            row_idx = phase_index.get(phase, phase - 1)
            flow_vps = 0.0
            queue_veh = 0.0
            try:
                values = [float(v) for v in flow_rows[row_idx]]
                if values:
                    flow_vps = max(0.0, sum(values) / len(values) / 3600.0)
            except Exception:
                pass
            try:
                values = [float(v) for v in queue_rows[row_idx]]
                if values:
                    queue_veh = max(0.0, max(values))
            except Exception:
                pass
            try:
                _latest = getattr(stats, 'latest_section', None) or {}
                _det_sec = getattr(ctrl, '_det_sec_cache', None) or {}
                _ncol = len(flow_rows[row_idx]) if flow_rows is not None else 0
                _mq, _n_meas = 0.0, 0
                for _jj in range(_ncol):
                    _tup = _det_sec.get((row_idx, _jj))
                    if not _tup:
                        continue
                    _st = _latest.get(int(_tup[0]))
                    if not _st:
                        continue
                    if sim_time - float(_st.get("t", -1e9)) > 90.0:
                        continue
                    _n_meas += 1
                    _q = float(_st.get("queue_veh", 0) or 0) * \
                        max(int(_st.get("lanes", 1) or 1), 1)
                    if _q > _mq:
                        _mq = _q
                if _n_meas > 0 and _mq > 0:
                    queue_veh = _mq  # measured state wins for initial conditions
            except Exception:
                pass
            for step in range(horizon):
                q_arr[(int(iid), int(phase), step)] = flow_vps
            Q_init[(int(iid), int(phase))] = queue_veh
        cycle = float(getattr(ctrl, 'cycle_len_s', 135.0) or 135.0)
        phi_init[int(iid)] = float(sim_time) % max(cycle, 1.0)

    bus_states = []
    seen_buses = set()
    for coord in corridor_coordinators:
        for veh_id, tracker in list(getattr(coord, '_trackers', {}).items()):
            veh_id = int(veh_id)
            if veh_id in seen_buses:
                continue
            line_id = int(_bus_line_id.get(veh_id, -1) or -1)
            route = list(_pt_line_jct_route.get(line_id, []) or [])
            if not route:
                route = list(getattr(coord, 'route_inter_ids', []) or [])
            if not route:
                continue
            current_jct = None
            tracker_idx = int(getattr(tracker, '_prev_inter_idx', -1) or -1)
            coord_route = list(getattr(coord, 'route_inter_ids', []) or [])
            if 0 <= tracker_idx < len(coord_route):
                current_jct = coord_route[tracker_idx]
            current_idx = route.index(current_jct) if current_jct in route else 0
            tau_detect = getattr(tracker, 'last_t', None)
            if tau_detect is None:
                tau_detect = sim_time
            bus_states.append(_MPCBusState(
                veh_id=veh_id,
                line_id=line_id,
                route_jcts=route,
                current_jct_idx=current_idx,
                tau_detect=float(tau_detect),
                sigma_detect=max(0.0, float(_bus_lateness.get(veh_id, 0.0) or 0.0)),
            ))
            seen_buses.add(veh_id)

    route_sources = []
    for coord in corridor_coordinators:
        route_sources.append((list(getattr(coord, 'route_inter_ids', []) or []), coord))
    for bus in bus_states:
        route_sources.append((bus.route_jcts, None))
    for route, coord in route_sources:
        for first, second in zip(route, route[1:]):
            if coord is not None:
                positions = getattr(coord, 'corridor_pos', {}) or {}
                distance = abs(float(positions.get(second, 0.0))
                               - float(positions.get(first, 0.0)))
            else:
                distance = 400.0
            tau_freeflow[(int(first), int(second))] = max(distance / 11.0, 5.0)
    for bus in bus_states:
        arrival = float(bus.tau_detect)
        route = bus.route_jcts[bus.current_jct_idx:]
        for index, iid in enumerate(route):
            if index:
                arrival += tau_freeflow.get((route[index - 1], iid), 36.0)
            tau_bar[(bus.veh_id, iid)] = arrival

    return _MPCPrediction(
        q_arr=q_arr,
        q_side={},
        tau_freeflow=tau_freeflow,
        tau_bar=tau_bar,
        Q_init=Q_init,
        phi_init=phi_init,
        bus_states=bus_states,
    )


def _milp_mpc_apply_action(ctrl, action, time, timeSta, acycle, veh_id):
    """Translate one MPC intervention into the existing Aimsun phase API."""
    if ctrl.flag != 0 or time < float(getattr(ctrl, 'TSPActiveTime', 0.0) or 0.0):
        return False
    current_phase = ECIGetCurrentPhase(ctrl.node_id)
    if current_phase < 0:
        return False
    duration = max(5.0, float(globals().get('MILP_MPC_ACTION_S', 10.0) or 10.0))
    phase_start = ECIGetStartingTimePhase(ctrl.node_id)
    phase_duration = float(GetPhaseDuration(ctrl.node_id, current_phase, timeSta) or 0.0)
    elapsed = max(0.0, float(time) - float(phase_start))
    kind = str(action).upper()
    ctrl.last_detected_bus_id = int(veh_id)
    lock_until = float(time) + duration + float(
        globals().get('TSP_POST_GRANT_LOCK_S', 5.0) or 5.0)

    if kind == 'GE' and current_phase == ctrl.BusPhase:
        ECIChangeTimingPhase(ctrl.node_id, current_phase,
                             ctrl.BusPhaseDuration + duration, timeSta)
        ctrl.TimeToTerminateBusPhase = time + max(
            0.0, phase_duration - elapsed) + duration
        ctrl.TSPStrategy = 1
        ctrl.flag = 1
        ctrl.TSPActiveTime = lock_until
        ctrl._ge_debt_s = duration
        ctrl._ge_opt_GE = duration
        _ge_events.append((time, ctrl.id, duration, 0.0))
        ctrl.highlight_bus(veh_id)
        ctrl.stats.record_tsp_event(ctrl.id, 'extension')
        ctrl.stats.record_tsp_extension_duration(ctrl.id, duration)
        if veh_id > 0:
            _acquire_focus(veh_id, ctrl.id, time)
    elif kind == 'INS':
        if current_phase == ctrl.BusPhase:
            return _milp_mpc_apply_action(ctrl, 'GE', time, timeSta, acycle, veh_id)
        ctrl.previous_phase = current_phase
        ctrl.BusPhaseEndTime = time + duration
        ECIChangeTimingPhase(ctrl.node_id, ctrl.BusPhase, duration, timeSta)
        ECIChangeDirectPhase(ctrl.node_id, ctrl.BusPhase, timeSta, time, acycle, 0)
        ctrl.TSPStrategy = 2
        ctrl.flag = 2
        ctrl._ins_bus_phase_seen = False
        ctrl._ins_grant_time = time
        ctrl.TSPActiveTime = lock_until
        ctrl._ge_debt_s = duration
        ctrl.highlight_bus(veh_id)
        ctrl.stats.record_tsp_event(ctrl.id, 'insertion')
        ctrl.stats.record_tsp_insertion_duration(ctrl.id, duration)
        if veh_id > 0:
            _acquire_focus(veh_id, ctrl.id, time)
    elif kind in ('ER', 'GR'):
        if kind == 'GR' and current_phase == ctrl.BusPhase:
            return _milp_mpc_apply_action(ctrl, 'GE', time, timeSta, acycle, veh_id)
        new_duration = max(5.0, phase_duration - duration)
        ECIChangeTimingPhase(ctrl.node_id, current_phase, new_duration, timeSta)
        ctrl.TSPStrategy = 4 if kind == 'ER' else 3
        ctrl.flag = 4 if kind == 'ER' else 3
        ctrl.TSPActiveTime = lock_until
        ctrl._ge_debt_s = duration
        ctrl.highlight_bus(veh_id)
        ctrl.stats.record_tsp_event(
            ctrl.id, 'early_red' if kind == 'ER' else 'green_reallocation')
        if veh_id > 0:
            _acquire_focus(veh_id, ctrl.id, time)
    else:
        return False

    ctrl._tsp_cycle_grant_until = float(time) + float(ctrl.cycle_len_s)
    ctrl.last_tsp_action_time = float(time)
    log_to_file(
        f"[MILP_MPC] t={float(time):.1f} inter={ctrl.id} bus={veh_id} "
        f"action={kind} duration={duration:.1f}s",
        force=True,
    )
    return True


def _milp_mpc_tick(time, timeSta, acycle):
    """Solve/replan once per simulation step and execute eligible starts."""
    global _milp_mpc_last_step
    if _milp_mpc_controller is None:
        return
    sim_step = int(round(float(time)))
    if sim_step == _milp_mpc_last_step:
        return
    _milp_mpc_last_step = sim_step
    pred = _milp_mpc_prediction(float(time))
    _milp_mpc_controller.update_buses(pred.bus_states)
    solution = _milp_mpc_controller.step(pred, sim_step)
    actions = _milp_mpc_controller.get_current_actions(sim_step)
    chosen = {}
    for (iid, kind), _value in sorted(actions.items()):
        if iid not in chosen and kind != 'NA':
            chosen[iid] = kind
    for iid, kind in chosen.items():
        ctrl = controllers.get(iid)
        if ctrl is None:
            continue
        bus_id = -1
        for coord in corridor_coordinators:
            try:
                oncoming = coord.oncoming_buses(iid, float(time), max_eta_s=180.0)
            except Exception:
                oncoming = []
            if oncoming:
                bus_id = int(oncoming[0][0])
                break
        if bus_id <= 0:
            continue
        _milp_mpc_apply_action(ctrl, kind, time, timeSta, acycle, bus_id)
    log_to_file(
        f"[MILP_MPC] t={float(time):.1f} solver={getattr(_milp_mpc_controller, 'solver_name', '?')} "
        f"status={solution.status} objective={solution.objective_value:.1f} "
        f"planned_starts={len(actions)} executed={len(chosen)}",
    )


# Corridor-aware evaluation order cache (built lazily by _aapi_post_manage_impl):
# junctions evaluated upstream->downstream per corridor so commits propagate to
# downstream decisions within the same step.
_MANAGE_ORDER = None

# Global plan-state tracker (2026-09-28): ONE store of each junction's live
# phase plan -- per-phase durations, cycle, bus phase, version -- updated on
# every commit/broadcast and at startup. The causal-delay estimators
# (_signal_delay_at_s, _bus_red_at, _next_bus_green_window) read SUBSEQUENT
# phases from here (preferring the committed plan over live ECI), so an action
# taken at one junction is visible to every downstream delay projection
# immediately, not after ECI settles. Live ECI remains the source for the
# CURRENT phase's remaining-time math.
_PLAN_STATE = {}


def _global_plan_state(jid):
    try:
        _s = _PLAN_STATE.get(int(jid))
        return _s if isinstance(_s, dict) else None
    except Exception:
        return None


def _global_plan_dur(jid, ph):
    """Committed duration for phase ph at jid, or None (caller falls back to
    live ECI)."""
    _s = _global_plan_state(jid)
    if _s is None:
        return None
    try:
        _d = _s.get("durs", {}).get(int(ph))
        return float(_d) if _d is not None else None
    except Exception:
        return None


def _global_plan_cycle(jid):
    _s = _global_plan_state(jid)
    if _s is None:
        return None
    try:
        _c = _s.get("cycle_s")
        return float(_c) if _c is not None else None
    except Exception:
        return None


def _dur_or_live(jid, ph, timeSta=0.0):
    """Committed-then-live phase duration: prefer the global plan-state tracker
    (push-aware) over live ECI, so a just-committed action is priced into any
    forward delay/ETA walk immediately."""
    _td = _global_plan_dur(jid, ph)
    if _td is not None:
        return _td
    try:
        return float(GetPhaseDuration(int(jid), int(ph), timeSta) or 0.0)
    except Exception:
        return 0.0


def _aapi_post_manage_impl(time, timeSta, timeTrans, acycle):
    # Corridor-aware evaluation order cache (2026-09-28), see the loop below.
    global _MANAGE_ORDER
    # Lazy bus-type recheck: PT vehicles may not exist at AAPIInit time
    global _bus_type_needs_recheck
    global _bus_type_provisional
    global _dynaropac_last_eval_t, _dynaropac_decision_header_written
    if _bus_type_needs_recheck:
        # Try every 30 s for the first 600 s (10 min) to allow time for buses
        # to enter the network before giving up.  The original 120 s window was
        # too short — buses hadn't appeared yet when the recheck was abandoned.
        _recheck_interval = 30.0
        _recheck_limit    = 600.0
        if time <= _recheck_limit and int(time) % int(_recheck_interval) == 0:
            _pt_bus = _infer_bus_type_pos_from_pt()
            if _pt_bus > 0:
                _bus_type_needs_recheck = False
                _bus_type_provisional = False
                for ctrl in controllers.values():
                    ctrl.bus_type_pos = _pt_bus
                    if ctrl.gb is not None:
                        ctrl.gb.bus_type_pos = _pt_bus
                stats._bus_pos = _pt_bus

                # Resolve truck type NOW that bus is known.
                # Truck = the type position that is NOT bus and NOT the lowest
                # numbered (assumed car) — elimination method for 3-type models.
                _nb_t = AKIVehGetNbVehTypes()
                if stats._truck_pos <= 0 and _nb_t >= 3:
                    _other = [p for p in range(1, _nb_t + 1) if p != _pt_bus]
                    if len(_other) >= 2:
                        _car_guess = min(_other)   # smallest = car
                        _truck_guess = [p for p in _other if p != _car_guess]
                        if _truck_guess:
                            _trk = _truck_guess[0]
                            stats._truck_pos = _trk
                            for ctrl in controllers.values():
                                if not hasattr(ctrl, 'truck_type_pos') or ctrl.truck_type_pos <= 0:
                                    ctrl.truck_type_pos = _trk
                                if ctrl.gb is not None and (not hasattr(ctrl.gb, 'truck_type_pos') or ctrl.gb.truck_type_pos <= 0):
                                    ctrl.gb.truck_type_pos = _trk
                            # Also update car type if not resolved
                            if stats._car_pos <= 0 or stats._car_pos == _pt_bus:
                                stats._car_pos = _car_guess
                            log_to_file(
                                f"[VEH TYPES] truck resolved via elimination: "
                                f"car={stats._car_pos} bus={_pt_bus} truck={_trk}"
                            )

                log_to_file(
                    f"[VEH TYPES] lazy PT inference at t={time:.0f}: "
                    f"bus_type_pos={_pt_bus} car={stats._car_pos} truck={stats._truck_pos}"
                    f" — updated all controllers + GB sub-controllers"
                )
        elif time > _recheck_limit:
            _bus_type_needs_recheck = False
            log_to_file(
                f"[VEH TYPES] lazy recheck exhausted at t={time:.0f} "
                f"({_recheck_limit:.0f}s limit): bus_type_pos still unresolved. "
                f"Check vehicle type names in Aimsun model or add BUS_TYPE_POS "
                f"to INTERSECTIONS_CONFIG entry."
            )

    try:
        stats.track_bus_positions(time)
    except Exception as e:
        stop_simulation(f"track_bus_positions crashed t={time:.1f}: {e}")
        return 0

    # ── Continuous bus position log ───────────────────────────────────────
    if TRACK_BUS_POSITIONS:
        try:
            # Build junction XY lookup lazily and keep merging until all
            # junction centroids are resolved.
            global _jct_xy_cache
            if _jct_xy_cache is None or len(_jct_xy_cache) < len(controllers):
                _jxy = dict(_jct_xy_cache or {})
                for _iid, _ctrl in controllers.items():
                    if _iid in _jxy:
                        continue
                    try:
                        _xy = _ctrl._get_junction_xy()
                        if _xy is not None:
                            _zone_r = float(getattr(_ctrl, '_detection_zone_m',
                                          _ctrl.config.get('detection_zone_m', 250.0)))
                            _jxy[_iid] = (_xy[0], _xy[1], _zone_r)
                    except Exception:
                        pass
                if _jxy:
                    _jct_xy_cache = _jxy
            _track_all_bus_positions(time, _jct_xy_cache or {})
        except Exception:
            pass

    # ── Cyclic MaxPressure scheduler: runs every step, bus-independent. Must
    # sit BEFORE the per-junction loop so freshly switched phases are visible
    # to the TSP executors this step.
    try:
        _mp_cyclic_tick(time, timeSta, acycle)
    except Exception as e:
        if not _MP_CYCLIC_ERR_LOGGED[0]:
            _MP_CYCLIC_ERR_LOGGED[0] = True
            log_to_file(f"[MP-CYC] scheduler error: {e!r}", force=True)

    # ── PT frequency injection (Plan-B scaler): create due extra buses ──
    try:
        _pt_inj_tick(time)
    except Exception as e:
        _PT_INJ_ERR[0] += 1
        if _PT_INJ_ERR[0] <= 3:
            log_to_file(f"[PT-INJ] tick error: {e!r}", force=True)

    # ── Deferred suppressions from AAPIEnterVehicle (kernel-safe context) ──
    try:
        _pt_inj_process_removals()
    except Exception as e:
        _PT_INJ_ERR[0] += 1
        if _PT_INJ_ERR[0] <= 3:
            log_to_file(f"[PT-INJ] removal pass error: {e!r}", force=True)

    # ── Pure signal-wait accumulator (paper bus-delay definition) ──
    try:
        _pt_sigwait_tick(time)
    except Exception as e:
        _PT_INJ_ERR[0] += 1
        if _PT_INJ_ERR[0] <= 3:
            log_to_file(f"[SIG-WAIT] tick error: {e!r}", force=True)

    # ── Revisable pre-arm plans (adherence re-evaluation) ──
    try:
        _prearm_plans_tick(time)
    except Exception as e:
        _PT_INJ_ERR[0] += 1
        if _PT_INJ_ERR[0] <= 3:
            log_to_file(f"[PREARM] tick error: {e!r}", force=True)

    global _MANAGE_ORDER
    # Corridor-aware evaluation order (2026-09-28): evaluate junctions
    # UPSTREAM -> DOWNSTREAM along each corridor, so an action committed at
    # junction i is APPLIED (live ECI) before downstream junction j evaluates
    # in the same step -- every action propagates to every downstream decision
    # immediately, instead of j guessing from pre-commit state (the sub-tick
    # ordering gap). Cached once; unlisted junctions appended last.
    if _MANAGE_ORDER is None:
        _mo, _seen = [], set()
        for _coord in corridor_coordinators:
            try:
                _grp = sorted(
                    (int(j) for j in _coord.inter_ids),
                    key=lambda j: float(_coord.corridor_pos.get(j, 0.0)))
            except Exception:
                _grp = list(_coord.inter_ids)
            for _j in _grp:
                if _j in controllers and _j not in _seen:
                    _mo.append((_j, controllers[_j]))
                    _seen.add(_j)
        for _iid, _c in controllers.items():
            if _iid not in _seen:
                _mo.append((_iid, _c))
        _MANAGE_ORDER = _mo
        if _mo:
            try:
                log_to_file(
                    f"[ORDER] corridor-aware eval order ({len(_mo)} jcts): "
                    + ", ".join(str(i) for i, _ in _mo), force=True)
            except Exception:
                pass
    for inter_id, controller in _MANAGE_ORDER:
        try:
            # collect_delay runs identically for all modes — GROUP_BASED no longer
            # calls it internally (gb.step is detection + TSP overlay only).
            controller.collect_delay(time, timeSta)
        except Exception as e:
            stop_simulation(f"collect_delay crashed inter={inter_id} t={time:.1f}: {e}")
            return 0
        try:
            controller.update(time, timeSta, acycle)
        except Exception as e:
            stop_simulation(f"update crashed inter={inter_id} t={time:.1f}: {e}")
            return 0

    # ── Step corridor coordinators (after all individual controllers) ─────────
    for coord in corridor_coordinators:
        # Resilient corridor step (2026-09-28): a coordinator that crashes
        # repeatedly must not spin forever corrupting state each step. After
        # MAX consecutive failures it is DISABLED for the run -- the wave ban
        # stays lifted and its junctions run independent TSP (graceful
        # degradation, one clear log line) instead of a silent 30 s crash
        # loop. The first crash still prints the full traceback so the root
        # site is findable.
        _cd = getattr(coord, '_crash_count', 0)
        if _cd >= 3:
            if _cd == 3:
                try:
                    log_to_file(
                        f"[CORRIDOR] coordinator {coord.name} DISABLED after "
                        f"{_cd} consecutive crashes -- junctions run "
                        f"independent TSP (wave coordination off)", force=True)
                except Exception:
                    pass
                coord._crash_count = _cd + 1
            continue
        try:
            coord.step(time, timeSta)
            if _cd > 0:
                coord._crash_count = 0  # recovered
        except Exception as e:
            import traceback as _tb
            log_to_file(
                f"[CORRIDOR] coordinator {coord.name} crashed "
                f"t={time:.1f}: {e}\n{_tb.format_exc()}")
            coord._crash_count = _cd + 1

    if CONTROL_MODE == "MILP_MPC":
        try:
            for _ctrl in controllers.values():
                _ctrl.restore_phase_if_needed(time, timeSta, acycle)
            _milp_mpc_tick(time, timeSta, acycle)
        except Exception as e:
            log_to_file(f"[MILP_MPC] tick failed t={time:.1f}: {e!r}", force=True)
            stop_simulation(f"MILP_MPC tick failed t={time:.1f}: {e}")

    # ── DYNAOPAC_HARMONY: network-wide delay-optimal phase duration search ──────
    # For each intersection, search candidate green extensions (0..MAX_GE in 1s
    # steps) and select the extension that minimises total person-delay.
    # If optimal extension < 0.5 s → record as detection pass (no action).
    # Applies only the single intersection with the greatest net saving.
    # Logs all candidates + delays to dynaropac_decisions_*.csv for plotting.
    if CONTROL_MODE == "DYNAOPAC_HARMONY" and _dynaropac_optimizer is not None:
        if time - _dynaropac_last_eval_t >= _DYNAROPAC_EVAL_INTERVAL_S:
            _dynaropac_last_eval_t = time
            try:
                _global_best_iid    = None
                _global_best_ge     = 0.0
                _global_best_saving = 0.0
                _dyn_log_rows       = []

                for _iid, _ctrl in controllers.items():
                    if TSP_ACTIVE_INTERSECTIONS and _iid not in TSP_ACTIVE_INTERSECTIONS:
                        continue
                    if getattr(_ctrl, 'TSPStrategy', 0) != 0:
                        continue  # already under active TSP
                    try:
                        _cur_phase = ECIGetCurrentPhase(_ctrl.node_id)
                        if _cur_phase < 0:
                            continue

                        # Build approach states from live section vehicle data
                        _approaches = {}
                        for _si, _sec in enumerate(getattr(_ctrl, 'incoming_sections', [])):
                            try:
                                _nveh = max(int(AKIVehStateGetNbVehiclesSection(_sec, False)), 0)
                                _sinf = AKIInfNetGetSectionANGInf(_sec)
                                _len_m = float(getattr(_sinf, 'length', 200.0) or 200.0)
                                _spd_ms = max(float(getattr(_sinf, 'speedLimit', 50.0) or 50.0) / 3.6, 0.1)
                                _sat = float(getattr(_ctrl, 'SaturationFlow', 1800.0))
                                _approaches[_si] = ApproachState(
                                    approach_id=_si,
                                    queue_length=float(_nveh),
                                    upstream_flow=min(_nveh * 3600.0 / 5.0, _sat),
                                    saturation_flow=_sat,
                                    approach_length=_len_m,
                                    average_speed=_spd_ms,
                                )
                            except Exception:
                                pass
                        if not _approaches:
                            continue

                        # Check if a bus is detected
                        _has_bus = (
                            hasattr(_ctrl, 'BusPresence') and
                            len(_ctrl.BusPresence) > 0 and
                            len(_ctrl.BusPresence[0]) > 0 and
                            max(_ctrl.BusPresence[0]) > 0
                        )
                        _buses_det = {}
                        if _has_bus:
                            try:
                                _spd = float(_ctrl.BusSpeed[0][0] or 0.5)
                                _eta_arr = list(getattr(_ctrl, '_bus_eta', {}).values())
                                _eta = float(_eta_arr[0][1]) if _eta_arr else 20.0
                                _buses_det[0] = BusState(
                                    bus_id=0,
                                    distance_to_stopline=max(_spd * _eta, 1.0),
                                    speed=max(_spd, 0.1),
                                    occupancy=float(getattr(_ctrl, 'BusOcc', 40.0)),
                                    eta=_eta,
                                )
                            except Exception:
                                pass

                        # Build minimal IntersectionState (single-phase view for extension search)
                        _phase_min = float(getattr(_ctrl, 'BusPhaseDuration', 6.0))
                        _phase_max = min(float(getattr(_ctrl, 'GE_upper_bound', 20.0)), MAX_GE_EXTENSION_S)
                        _stage = max(_phase_max * 2, 30.0)

                        _phases_def = {1: PhaseDefinition(
                            phase_id=1,
                            served_approaches=list(_approaches.keys()),
                            min_green=_phase_min,
                            max_green=_phase_min + _phase_max,
                            is_bus_phase=True,
                        )}
                        _istate = IntersectionState(
                            intersection_id=_iid,
                            phases=_phases_def,
                            approaches=_approaches,
                            current_phase=_cur_phase,
                            phase_start_time=float(ECIGetStartingTimePhase(_ctrl.node_id) or time),
                            elapsed_green=max(0.0, time - float(ECIGetStartingTimePhase(_ctrl.node_id) or time)),
                            buses_detected=_buses_det,
                        )

                        # Current phase duration (before extension)
                        _before_dur = float(GetPhaseDuration(_ctrl.node_id, _cur_phase, timeSta) or _phase_min)

                        # Search: try extension 0, 1, 2 ... max_ge (1-second steps)
                        _search_max = int(round(_phase_max))
                        _ext_delays  = []  # (extension_s, total_delay)
                        for _ext in range(0, _search_max + 1):
                            _sw = [float(_before_dur + _ext)]
                            _delay = _dynaropac_optimizer.calculate_delay(
                                _istate, [1], _sw, _stage, include_bus_priority=True)
                            _ext_delays.append((_ext, _delay))

                        # Select minimum delay extension
                        _best_ext, _best_delay = min(_ext_delays, key=lambda x: x[1])
                        _baseline_delay = _ext_delays[0][1]  # extension=0 = no action
                        _saving = _baseline_delay - _best_delay

                        # Log all candidates for this intersection
                        _ext_list   = [e for e, _ in _ext_delays]
                        _delay_list = [round(d, 2) for _, d in _ext_delays]
                        _dyn_log_rows.append({
                            "sim_time_s":    round(time, 1),
                            "junction_id":   _iid,
                            "cur_phase":     _cur_phase,
                            "before_dur_s":  round(_before_dur, 2),
                            "extensions_s":  str(_ext_list),
                            "delays_paxs":   str(_delay_list),
                            "best_ext_s":    round(_best_ext, 2),
                            "best_delay":    round(_best_delay, 2),
                            "baseline_delay":round(_baseline_delay, 2),
                            "saving_paxs":   round(_saving, 2),
                            "bus_detected":  int(bool(_buses_det)),
                            "applied":       0,  # updated below
                        })

                        if _saving > _global_best_saving and _best_ext >= 0.5:
                            _global_best_saving = _saving
                            _global_best_iid    = _iid
                            _global_best_ge     = float(_best_ext)

                    except Exception as _dh_inter_err:
                        log_to_file(f"[DYNAOPAC_HARMONY] inter={_iid} eval error: {_dh_inter_err}")
                        continue

                # Apply the best extension globally
                if _global_best_iid is not None:
                    _ctrl = controllers[_global_best_iid]
                    try:
                        _rem = GetPhaseDuration(_ctrl.node_id, ECIGetCurrentPhase(_ctrl.node_id), timeSta) \
                               - (time - ECIGetStartingTimePhase(_ctrl.node_id))
                        _new_dur = _ctrl.BusPhaseDuration + _global_best_ge
                        ECIChangeTimingPhase(_ctrl.node_id, ECIGetCurrentPhase(_ctrl.node_id),
                                             _new_dur, timeSta)
                        _ctrl.TimeToTerminateBusPhase = time + max(_rem, 0.0) + _global_best_ge
                        _ctrl.TSPStrategy  = 1
                        _ctrl.flag         = 1
                        _ctrl.TSPActiveTime = time + _global_best_ge + 30
                        _ctrl._ge_debt_s   = _global_best_ge
                        _ctrl.last_tsp_action_time = time
                        _ctrl._record_detection(time, inter_id=_global_best_iid)
                        _ctrl.stats.record_tsp_event(_global_best_iid, 'extension')
                        _ctrl.stats.record_tsp_extension_duration(_global_best_iid, _global_best_ge)
                        # Mark this row as applied
                        for _row in _dyn_log_rows:
                            if _row['junction_id'] == _global_best_iid:
                                _row['applied'] = 1
                        log_to_file(
                            f"[DYNAOPAC_HARMONY] t={time:.1f} applied GE={_global_best_ge:.1f}s "
                            f"jct={_global_best_iid} saving={_global_best_saving:.1f}pax-s"
                        )
                    except Exception as _dh_app_err:
                        log_to_file(f"[DYNAOPAC_HARMONY] apply failed jct={_global_best_iid}: {_dh_app_err}")
                # ── Also evaluate phase insertion for intersections with detected bus ─
                # Only consider INS when bus is detected but NOT already in BusPhase.
                _ins_best_iid     = None
                _ins_best_dur     = 0.0
                _ins_best_saving  = 0.0
                for _iid3, _ctrl3 in controllers.items():
                    if TSP_ACTIVE_INTERSECTIONS and _iid3 not in TSP_ACTIVE_INTERSECTIONS:
                        continue
                    if getattr(_ctrl3, 'TSPStrategy', 0) != 0:
                        continue
                    try:
                        _cur3 = ECIGetCurrentPhase(_ctrl3.node_id)
                        if _cur3 < 0 or _cur3 == getattr(_ctrl3, 'BusPhase', 1):
                            continue  # already on BusPhase — use GE, not INS
                        _has_bus3 = (
                            hasattr(_ctrl3, 'BusPresence') and
                            len(_ctrl3.BusPresence) > 0 and
                            len(_ctrl3.BusPresence[0]) > 0 and
                            max(_ctrl3.BusPresence[0]) > 0
                        )
                        if not _has_bus3:
                            continue
                        # Estimate bus ETA at this junction
                        _eta3_arr = list(getattr(_ctrl3, '_bus_eta', {}).values())
                        _eta3 = float(_eta3_arr[0][1]) if _eta3_arr else 20.0
                        if _eta3 < 5.0 or _eta3 > 60.0:
                            continue  # outside actionable window
                        # Evaluate: insert BusPhase for _eta3+buffer seconds
                        _bp_lb3  = max(float(getattr(_ctrl3, 'BP_lower_bound', 15)), _eta3 + 2.0)
                        _bp_ub3  = min(float(getattr(_ctrl3, 'BP_upper_bound', 30)), MAX_BP_INSERTION_S)
                        if _bp_lb3 >= _bp_ub3:
                            continue
                        # Build minimal state for INS delay calculation
                        _approaches3 = {}
                        for _si3, _sec3 in enumerate(getattr(_ctrl3, 'incoming_sections', [])):
                            try:
                                _nveh3 = max(int(AKIVehStateGetNbVehiclesSection(_sec3, False)), 0)
                                _sinf3 = AKIInfNetGetSectionANGInf(_sec3)
                                _len3  = float(getattr(_sinf3, 'length', 200.0) or 200.0)
                                _spd3  = max(float(getattr(_sinf3, 'speedLimit', 50.0) or 50.0) / 3.6, 0.1)
                                _sat3  = float(getattr(_ctrl3, 'SaturationFlow', 1800.0))
                                _approaches3[_si3] = ApproachState(
                                    approach_id=_si3,
                                    queue_length=float(_nveh3),
                                    upstream_flow=min(_nveh3 * 3600.0 / 5.0, _sat3),
                                    saturation_flow=_sat3,
                                    approach_length=_len3,
                                    average_speed=_spd3,
                                )
                            except Exception:
                                pass
                        if not _approaches3:
                            continue
                        _stage3 = max(_bp_ub3 * 2.0, 30.0)
                        _phases3 = {1: PhaseDefinition(
                            phase_id=1,
                            served_approaches=list(_approaches3.keys()),
                            min_green=_bp_lb3,
                            max_green=_bp_ub3,
                            is_bus_phase=True,
                        )}
                        _istate3 = IntersectionState(
                            intersection_id=_iid3,
                            phases=_phases3,
                            approaches=_approaches3,
                            current_phase=_cur3,
                            phase_start_time=float(ECIGetStartingTimePhase(_ctrl3.node_id) or time),
                            elapsed_green=max(0.0, time - float(ECIGetStartingTimePhase(_ctrl3.node_id) or time)),
                            buses_detected={},
                        )
                        # ── Harmony-like INS duration search ───────────────────
                        # Sweep _bp_lb3 .. _bp_ub3 in 1-second steps and pick
                        # the duration that minimises person-delay (mirrors the GE
                        # search loop approach used for green extension).
                        _best_ins_dur3   = _bp_lb3
                        _best_ins_delay3 = float('inf')
                        _sw_noins = [float(_bp_lb3)]
                        _noins_delay = _dynaropac_optimizer.calculate_delay(
                            _istate3, [1], _sw_noins, _stage3, include_bus_priority=True)
                        for _ins_candidate in range(int(_bp_lb3), int(_bp_ub3) + 1):
                            _ins_dur_f = float(_ins_candidate)
                            _sw_ins_c = [0.0, _ins_dur_f]
                            try:
                                _ins_delay_c = _dynaropac_optimizer.calculate_delay(
                                    _istate3, [1, 1], _sw_ins_c, _stage3, include_bus_priority=True)
                                if _ins_delay_c < _best_ins_delay3:
                                    _best_ins_delay3 = _ins_delay_c
                                    _best_ins_dur3   = _ins_dur_f
                            except Exception:
                                pass
                        _ins_saving3 = _noins_delay - _best_ins_delay3
                        if _ins_saving3 > _ins_best_saving:
                            _ins_best_saving = _ins_saving3
                            _ins_best_iid    = _iid3
                            _ins_best_dur    = _best_ins_dur3
                    except Exception:
                        pass

                # Pick the better of GE and INS globally
                if _ins_best_iid is not None and _ins_best_saving > _global_best_saving:
                    # Apply phase insertion
                    _ctrl_ins = controllers[_ins_best_iid]
                    try:
                        ECIChangeTimingPhase(_ctrl_ins.id, _ctrl_ins.BusPhase,
                                             float(_ins_best_dur), timeSta)
                        ECIChangeDirectPhase(_ctrl_ins.id, _ctrl_ins.BusPhase,
                                             timeSta, time, 0, 0)
                        _ctrl_ins.TSPStrategy  = 2
                        _ctrl_ins.flag         = 2
                        _ctrl_ins._ins_bus_phase_seen = False
                        _ctrl_ins._ins_grant_time = time
                        _ctrl_ins.previous_phase = ECIGetCurrentPhase(_ctrl_ins.node_id)
                        _ctrl_ins.BusPhaseEndTime = time + float(_ins_best_dur)
                        _ctrl_ins.TSPActiveTime = time + _ins_best_dur + 30
                        _ctrl_ins._ge_debt_s   = _ins_best_dur
                        _ctrl_ins.last_tsp_action_time = time
                        _ctrl_ins._record_detection(time, inter_id=_ins_best_iid)
                        _ctrl_ins.stats.record_tsp_event(_ins_best_iid, 'insertion')
                        _ctrl_ins.stats.record_tsp_insertion_duration(_ins_best_iid, _ins_best_dur)
                        for _row in _dyn_log_rows:
                            if _row['junction_id'] == _ins_best_iid:
                                _row['applied'] = 1
                        log_to_file(
                            f"[DYNAOPAC_HARMONY] t={time:.1f} applied INS={_ins_best_dur:.1f}s "
                            f"jct={_ins_best_iid} saving={_ins_best_saving:.1f}pax-s"
                        )
                        _global_best_iid = _ins_best_iid  # mark as actioned
                    except Exception as _ins_err:
                        log_to_file(f"[DYNAOPAC_HARMONY] INS apply failed jct={_ins_best_iid}: {_ins_err}")

                if _global_best_iid is None:
                    # No GE or INS was beneficial — cancel any active coordination wave
                    # so downstream junctions are freed for independent detection.
                    for _coord_c in corridor_coordinators.values():
                        if _coord_c._wave_active:
                            log_to_file(
                                f"[DYNAOPAC_HARMONY] t={time:.1f} no GE/INS — wave cancelled",
                                )
                            _coord_c._wave_active     = False
                            _coord_c._wave_veh_id     = -1
                            _coord_c._wave_origin     = -1
                            _coord_c._wave_served_ids = set()
                            _coord_c._pre_requests.clear()
                    # Record detection passes for intersections with buses.
                    # This runs EVERY simulation step, so it used to add one
                    # "detection" per junction per step for as long as any bus
                    # was present -- ~16 800 of the 18 398 detections reported
                    # by CELLQLEARN seed 300.  _record_detection collapses it
                    # to one event per (junction, bus) approach; the paired
                    # ge_trivial skip is only recorded when the detection was.
                    for _iid2, _ctrl2 in controllers.items():
                        try:
                            if (hasattr(_ctrl2, 'BusPresence') and
                                    len(_ctrl2.BusPresence) > 0 and max(_ctrl2.BusPresence[0]) > 0):
                                if _ctrl2._record_detection(time, inter_id=_iid2):
                                    _ctrl2.stats.record_tsp_skip(_iid2, 'ge_trivial')
                        except Exception:
                            pass

                # Write decision log rows to CSV
                if _dyn_log_rows and _DYNAROPAC_DECISION_CSV:
                    try:
                        _write_header = not _dynaropac_decision_header_written
                        with open(_DYNAROPAC_DECISION_CSV, "a", newline="", encoding="utf-8") as _f:
                            _wcsv = csv.DictWriter(_f, fieldnames=list(_dyn_log_rows[0].keys()))
                            if _write_header:
                                _wcsv.writeheader()
                                _dynaropac_decision_header_written = True
                            _wcsv.writerows(_dyn_log_rows)
                    except Exception as _csv_err:
                        log_to_file(f"[DYNAOPAC_HARMONY] CSV write failed: {_csv_err}")

            except Exception as _dh_outer:
                log_to_file(f"[DYNAOPAC_HARMONY] eval loop failed t={time:.1f}: {_dh_outer}")

    # ── Incremental network stats sampling (every ~30s) ───────────────────────
    try:
        _all_secs = set(_network_stats_section_ids())
        if _all_secs:
            stats.accumulate_network_step(list(_all_secs), time)
    except Exception:
        pass

    # ── Per-intersection density/speed/flow sampling (every ~30s) ─────────
    try:
        stats.accumulate_intersection_step(time)
    except Exception:
        pass

    # ── Density tick subsampling (cheap count-only, self-gated ~2 s) ──────
    # Feeds time-averaged k for shockwave-grade density; the 30 s sampler
    # consumes the buffer. No-op if the stats object predates the method.
    try:
        _tick_fn = getattr(stats, "sample_density_tick", None)
        if callable(_tick_fn):
            _tick_fn(time)
    except Exception:
        pass

    # ── Extended per-section stats snapshot (every ~300s, after warmup) ───────
    # AKIEstGetGlobalStatisticsSection returns count=0 when queried in
    # AAPIFinish (post-sim), so collect it periodically DURING the run — the
    # zero-clobber guard in collect_extra_section_stats keeps the last valid
    # cumulative read so the Network Statistics table (entry/exit TT, exit
    # count/flow/speed, stops, distance) is populated even though the finish
    # read comes back empty.
    global _last_extra_stats_t
    try:
        if time >= 300.0 and (time - _last_extra_stats_t) >= 300.0:
            _last_extra_stats_t = time
            _xs = set(_network_stats_section_ids())
            if _xs:
                stats.collect_extra_section_stats(list(_xs))
    except Exception:
        pass

    # ── Queue length snapshot every 60s (all intersections) ──────────────────
    try:
        _write_queue_snapshot(time)
    except Exception:
        pass

    # ── Live status dashboard ─────────────────────────────────────────────────
    global _last_dashboard_t
    if STATUS_DASHBOARD_INTERVAL_S > 0 and (time - _last_dashboard_t) >= STATUS_DASHBOARD_INTERVAL_S:
        _last_dashboard_t = time
        try:
            _print_status_dashboard(time)
        except Exception as _de:
            log_to_file(f"[DASH] dashboard error: {_de}")

    return 0


# =============================================================================
# LIVE STATUS DASHBOARD
# =============================================================================

def _print_status_dashboard(time: float):
    """
    Print a compact, always-readable status table to the Aimsun console.

    Example output (every STATUS_DASHBOARD_INTERVAL_S seconds):

      [DASH] t=  3600s ══════════════════════════════════════════════════════
      [DASH]  Junction   Phase    TSP       GE-debt  Bus   det/ext/ins
      [DASH]  ─────────────────────────────────────────────────────────────
      [DASH]  17249      3 / 6    GE        12.4 s   YES   3 / 2 / 0
      [DASH]  17383      5 / 7    IDLE       0.0 s    NO   1 / 1 / 0
      [DASH]  19363      1 / 3    IDLE       0.0 s    NO   0 / 0 / 0
      [DASH]  ─────────────────────────────────────────────────────────────
      [DASH]  Active TSP: 17249 (GE, 12.4 s debt)   Corridor wave: OFF
      [DASH] ══════════════════════════════════════════════════════════════
    """
    if STATUS_DASHBOARD_INTERVAL_S <= 0:
        return
    if not controllers:
        return

    _W  = 66     # total table width
    _SEP  = "─" * _W
    _DSEP = "═" * _W

    hh = int(time // 3600)
    mm = int((time % 3600) // 60)
    ss = int(time % 60)
    t_str = f"{hh:02d}:{mm:02d}:{ss:02d}"

    lines = []
    lines.append(f"[DASH] t={t_str}  " + _DSEP[len(t_str)+8:])
    lines.append(f"[DASH]  {'Junction':<10} {'Phase':<8} {'TSP':<10} {'Debt':>7}  {'Bus':<5} {'det/ext/ins':>11}")
    lines.append(f"[DASH]  " + _SEP)

    active_tsp  = []
    wave_active = any(getattr(c, '_wave_active', False)
                      for coord in corridor_coordinators
                      for c in [coord])

    for iid, ctrl in controllers.items():
        # ── Phase info ──────────────────────────────────────────────────
        try:
            cur_ph  = ECIGetCurrentPhase(ctrl.node_id)
            n_ph    = len(ctrl.phase_list) if ctrl.phase_list else "?"
            ph_str  = f"{cur_ph} / {n_ph}"
        except Exception:
            ph_str  = "?"

        # ── TSP flag ────────────────────────────────────────────────────
        flag = getattr(ctrl, 'flag', 0)
        if flag == 1:
            tsp_str = "GE"
        elif flag == 2:
            tsp_str = "INSERTION"
        else:
            # Check GB sub-controller state too
            gb = getattr(ctrl, 'gb', None)
            gb_state = getattr(gb, 'state', None) if gb else None
            if gb_state and gb_state != "IDLE":
                tsp_str = f"GB:{gb_state}"
            else:
                tsp_str = "IDLE"

        # ── GE debt ─────────────────────────────────────────────────────
        debt   = getattr(ctrl, '_ge_debt_s', 0.0)
        debt_s = f"{debt:5.1f} s" if debt > 0.1 else "  0.0 s"

        # ── Bus presence ────────────────────────────────────────────────
        try:
            bus_here = any(ctrl.BusPresence[0] > 0)
        except Exception:
            bus_here = False
        # Also check last detected bus (non -1 and recent)
        if not bus_here:
            bus_here = getattr(ctrl, 'last_detected_bus_id', -1) != -1

        bus_str = "YES" if bus_here else " NO"

        # ── TSP event counts from stats ──────────────────────────────────
        _si = getattr(stats, '_inter', {}).get(iid, {})
        n_det = _si.get('n_detections', 0)
        n_ext = _si.get('n_extensions',  0)
        n_ins = _si.get('n_insertions',  0)
        ev_str = f"{n_det} / {n_ext} / {n_ins}"

        lines.append(
            f"[DASH]  {iid:<10} {ph_str:<8} {tsp_str:<10} {debt_s:>7}  {bus_str:<5} {ev_str:>11}"
        )

        if tsp_str != "IDLE":
            active_tsp.append(f"{iid} ({tsp_str}, {debt:.1f}s debt)")

    lines.append(f"[DASH]  " + _SEP)

    # ── Summary line ─────────────────────────────────────────────────────────
    if active_tsp:
        tsp_summary = "Active TSP: " + ", ".join(active_tsp)
    else:
        tsp_summary = "Active TSP: none"

    wave_str = "ON" if wave_active else "OFF"
    lines.append(f"[DASH]  {tsp_summary:<42}  Corridor wave: {wave_str}")
    lines.append(f"[DASH] " + _DSEP)

    for ln in lines:
        AKIPrintString(ln)
        try:
            with open(LOG_FILE, "a", encoding="utf-8") as _lf:
                _lf.write(ln + "\n")
        except Exception:
            pass


# =============================================================================
# AIMSUN CANVAS OVERLAY — creates GKAnnotation objects in the network view
# =============================================================================

def _write_overlay_script(valid_feats: list) -> str:
    """
    Write a standalone Aimsun GUI Python script that creates GKPolyline circle
    markers for every detection point.  Returns the script path.

    Run it from Aimsun Next: Tools > Run Script  (or Scripts > Run Script File)
    """
    import json as _json

    script_path = _DET_GEOJSON.replace(".geojson", "_overlay_script.py")

    # Embed the coordinates directly so the script is self-contained
    pts_data = [
        {
            "x": float(f["geometry"]["coordinates"][0]),
            "y": float(f["geometry"]["coordinates"][1]),
            "label": (
                f"[{f['properties'].get('tier','?')}] "
                f"Bus {f['properties'].get('veh_id','?')} "
                f"jct {f['properties'].get('junction_id','?')} "
                f"t={f['properties'].get('sim_time_s','?')}s"
            ),
        }
        for f in valid_feats
    ]

    script = f'''\
"""
TSP Bus Detection Overlay Script
Generated automatically by intersection_controller.py

Run from Aimsun Next:  Tools > Run Script  (select this file)

Creates {len(pts_data)} GKPolyline circle markers in layer "TSP Bus Detections".
"""
import math
from PyANGKernel import GKSystem

CIRCLE_R = 8.0    # marker radius in model units (metres)
CIRCLE_N = 16     # polygon segments
LAYER_NAME = "TSP Bus Detections"

PTS = {_json.dumps(pts_data, indent=2)}


def _make_circle_pts(cx, cy):
    coords = []
    for k in range(CIRCLE_N + 1):
        angle = 2.0 * math.pi * k / CIRCLE_N
        coords.append((cx + CIRCLE_R * math.cos(angle),
                       cy + CIRCLE_R * math.sin(angle), 0.0))
    return coords


def _clear_existing_markers(model, gk_types):
    """
    Delete all marker objects whose name starts with a TSP marker prefix.

    Runs up to 3 sweep passes: deleting while iterating can invalidate the
    catalog snapshot, so a second/third pass catches anything missed.
    Uses catalog.remove() first (confirmed working in Aimsun Next 26).
    """
    _PREFIXES = ("[BUS]", "[WAVE]", "[SEC]", "[DET]", "[IC-detect]", "[NORMAL-detect]")
    if model is None:
        return 0
    if not isinstance(gk_types, (list, tuple)):
        gk_types = [gk_types]
    catalog = model.getCatalog()
    if catalog is None:
        return 0

    def _name_of(obj):
        for fn in ("getName", "getExternalName", "getLabel"):
            try:
                v = getattr(obj, fn)() or ""
                if v:
                    return v
            except Exception:
                pass
        return ""

    def _delete_one(obj):
        # catalog.remove() confirmed working in Aimsun Next 26; try others as
        # fallbacks for older/newer versions.
        for _fn in (
            lambda o: catalog.remove(o),
            lambda o: o.remove(),
            lambda o: catalog.removeObject(o),
            lambda o: catalog.unmanageObject(o),
            lambda o: model.remove(o),
            lambda o: model.deleteObject(o),
            lambda o: model.deleteObjectForever(o),
        ):
            try:
                _fn(obj)
                return True
            except AttributeError:
                pass
            except Exception:
                pass
        return False

    total_del = 0
    for _pass in range(3):   # up to 3 passes to catch catalog-iterator misses
        to_del = []
        for gk_type in gk_types:
            if gk_type is None:
                continue
            try:
                objs = catalog.getObjectsByType(gk_type)
            except Exception:
                continue
            if not objs:
                continue
            # Snapshot into a plain list immediately before any deletion
            obj_list = list(objs.values()) if isinstance(objs, dict) else list(objs)
            for obj in obj_list:
                if any(_name_of(obj).startswith(p) for p in _PREFIXES):
                    to_del.append(obj)

        if not to_del:
            break   # nothing left — done

        n_this_pass = sum(1 for o in to_del if _delete_one(o))
        total_del += n_this_pass
        if n_this_pass == 0:
            break   # deletion failing — don't loop

    return total_del


def run():
    model = GKSystem.getSystem().getActiveModel()
    if model is None:
        print("[overlay] ERROR: no active model")
        return

    pl_type = model.getType("GKPolyline")
    if pl_type is None:
        print("[overlay] ERROR: GKPolyline type not found in this model")
        return

    # Remove markers from any previous run before drawing new ones
    _clear_existing_markers(model, pl_type)

    # Find or create the layer
    # Aimsun Next 26: newObject(type) — one arg only; getCreateFolderForType(str)
    layer = None
    try:
        catalog = model.getCatalog()
        lyr_type = model.getType("GKLayer")
        if catalog and lyr_type:
            for lyr in (catalog.getObjectsByType(lyr_type) or []):
                if getattr(lyr, "getName", lambda: "")() == LAYER_NAME:
                    layer = lyr
                    break
        if layer is None and lyr_type:
            layer = model.newObject(lyr_type)
            if layer:
                for fn in ("setName", "setExternalName"):
                    try:
                        getattr(layer, fn)(LAYER_NAME); break
                    except Exception:
                        pass
                try:
                    folder = model.getCreateFolderForType("GKLayer")
                    model.addObjectToFolder(layer, folder)
                except Exception:
                    pass
    except Exception as e:
        print(f"[overlay] Layer setup failed: {{e}} — continuing without layer")

    # Get creation folder for polylines (string arg in Aimsun Next 26)
    pl_folder = None
    try:
        pl_folder = model.getCreateFolderForType("GKPolyline")
    except Exception:
        pass

    n_ok = n_fail = 0
    for pt in PTS:
        try:
            obj = model.newObject(pl_type)
            if obj is None:
                raise RuntimeError("newObject returned None")
            if pl_folder is not None:
                try:
                    model.addObjectToFolder(obj, pl_folder)
                except Exception:
                    pass

            coords = _make_circle_pts(pt["x"], pt["y"])

            set_ok = False
            if not set_ok:
                try:
                    obj.setPoints(coords); set_ok = True
                except Exception:
                    pass
            if not set_ok:
                try:
                    from PyANGKernel import GKPoint
                    gkpts = []
                    for cx, cy, cz in coords:
                        p = GKPoint(); p.x = cx; p.y = cy; p.z = cz
                        gkpts.append(p)
                    obj.setPoints(gkpts); set_ok = True
                except Exception:
                    pass
            if not set_ok:
                try:
                    for cx, cy, cz in coords:
                        obj.addPoint(cx, cy, cz)
                    set_ok = True
                except Exception:
                    pass

            for fn in ("setName", "setExternalName", "setLabel"):
                try:
                    getattr(obj, fn)(pt["label"]); break
                except Exception:
                    pass

            # Set bright red colour so circles are visible
            try:
                from PyANGKernel import GKColor
                obj.setColor(GKColor(220, 30, 30))
            except Exception:
                try:
                    from PyQt5.QtGui import QColor
                    obj.setColor(QColor(220, 30, 30))
                except Exception:
                    pass

            if layer:
                for fn in ("setLayer", "addToLayer"):
                    try:
                        getattr(obj, fn)(layer); break
                    except Exception:
                        pass

            n_ok += 1
        except Exception as e:
            n_fail += 1
            if n_fail == 1:
                print(f"[overlay] First marker failed: {{e}}")

    # Refresh the view
    try:
        GKSystem.getSystem().getGUI().getActiveView().update()
    except Exception:
        pass

    print(f"[overlay] Done: {{n_ok}} circles created, {{n_fail}} failed.")
    print(f"[overlay] Zoom out on the network canvas to see red circles.")
    print(f"[overlay] Or: Catalog panel > GEO objects to find them by name.")


run()
'''

    with open(script_path, "w", encoding="utf-8") as _sf:
        _sf.write(script)
    return script_path


def _overlay_detections_on_aimsun_map():
    """
    After simulation:
    1. Writes a standalone Aimsun GUI script that creates GKPolyline circle
       markers — run it via Tools > Run Script for instant canvas overlay.
    2. Attempts to create the markers directly (AAPI context — may be read-only).

    Uses PyANGKernel (bundled with Aimsun Next).  Any API mismatch is caught
    and logged — the function never raises.
    """
    if not OVERLAY_DETECTIONS_ON_MAP:
        return
    if not MARK_DETECTION_POINTS:
        return
    if not ALLOW_MODEL_CATALOG_WRITES:
        log_to_file(
            "[MAP] Catalog writes disabled (ALLOW_MODEL_CATALOG_WRITES=False). "
            "Skipping in-model marker creation/deletion; GeoJSON/script outputs only.",
            force=True,
        )
        return

    valid_feats = [
        f for f in _geojson_features
        if not (f["geometry"]["coordinates"][0] == 0.0
                and f["geometry"]["coordinates"][1] == 0.0)
    ]
    if not valid_feats:
        log_to_file("[MAP] No valid-coordinate detections — canvas overlay skipped")
        return

    # Always write the standalone script — works even if the direct AAPI path fails.
    try:
        _script_path = _write_overlay_script(valid_feats)
        log_to_file(
            f"[MAP] Overlay script written: {_script_path}\n"
            f"      → To show circles in Aimsun: Tools > Run Script > select that file",
            force=True
        )
    except Exception as _se:
        log_to_file(f"[MAP] Overlay script write failed: {_se}")

    try:
        from PyANGKernel import GKSystem
    except ImportError:
        log_to_file(
            "[MAP] PyANGKernel not available — use the overlay script above.",
            force=True
        )
        return

    try:
        model = GKSystem.getSystem().getActiveModel()
        if model is None:
            log_to_file("[MAP] getActiveModel() returned None — canvas overlay skipped")
            return
    except Exception as _ge:
        log_to_file(f"[MAP] Could not access Aimsun model: {_ge}")
        return

    try:
        # Try type names used across different Aimsun Next versions.
        # getType() returns None for unknown names — no exception raised.
        _ANN_NAMES = [
            "GKAnnotation", "GKNote", "GKLabel",
            "GKMapLabel", "GKTextAnnotation", "GKAnnotation3D",
        ]
        ann_type = None
        _ann_name_used = ""
        for _tn in _ANN_NAMES:
            _t = model.getType(_tn)
            if _t is not None:
                ann_type = _t
                _ann_name_used = _tn
                break

        _use_polyline = False
        if ann_type is None:
            # GKAnnotation not available — try GKPolyline circle markers instead
            _pl_type = model.getType("GKPolyline")
            if _pl_type is None:
                # No usable type found — log available types for diagnostics
                _PROBE = [
                    "GKNode", "GKSection", "GKDetector", "GKCentroid",
                    "GKAnnotation", "GKNote", "GKLabel", "GKMapLabel",
                    "GKPolyline", "GKPolygon", "GKBitmap", "GKObject",
                ]
                _found = [n for n in _PROBE if model.getType(n) is not None]
                log_to_file(
                    f"[MAP] No overlay type found (tried {_ANN_NAMES} + GKPolyline). "
                    f"Types present in this model: {_found}. "
                    f"Open the GeoJSON manually: File > Import > {_DET_GEOJSON}",
                    force=True
                )
                return
            _use_polyline = True
            log_to_file("[MAP] Using GKPolyline circles as detection markers")
        else:
            log_to_file(f"[MAP] Using annotation type '{_ann_name_used}'")

        # ── Clear markers from any previous simulation run ────────────────────
        _MARKER_PREFIXES = (
            "[BUS]", "[WAVE]", "[SEC]", "[DET]",
            "[IC-detect]", "[NORMAL-detect]",
        )
        _clear_type = _pl_type if _use_polyline else ann_type
        try:
            _catalog = model.getCatalog()
            _all_objs = _catalog.getObjectsByType(_clear_type) if _catalog else None
            _obj_list = (
                list(_all_objs.values()) if isinstance(_all_objs, dict)
                else list(_all_objs or [])
            )
            _n_cleared = 0
            for _old in _obj_list:
                _name = ""
                for _fn in ("getName", "getExternalName"):
                    try:
                        _name = getattr(_old, _fn)() or ""
                        if _name:
                            break
                    except Exception:
                        pass
                if any(_name.startswith(_p) for _p in _MARKER_PREFIXES):
                    try:
                        model.deleteObject(_old)
                        _n_cleared += 1
                    except Exception:
                        pass
            if _n_cleared:
                log_to_file(f"[MAP] Cleared {_n_cleared} marker(s) from previous run")
        except Exception as _ce:
            log_to_file(f"[MAP] Marker clear failed (non-fatal): {_ce}")


        # ── Tier → ASCII prefix (emoji may not render in all Aimsun builds) ─
        def _pfx(tier: str) -> str:
            if "IC-detect" in tier or "PT-coord" in tier:
                return "[BUS]"
            if "coord-prearm" in tier:
                return "[WAVE]"
            if "sec" in tier:
                return "[SEC]"
            return "[DET]"

        # ── Object creation helper (Aimsun Next 26 API) ───────────────────────
        # Confirmed signatures:
        #   model.newObject(gktype)                 — one arg, no parent/folder
        #   model.getCreateFolderForType(type_name) — takes str, not GKType
        #   model.addObjectToFolder(obj, folder)    — add to folder after creation
        def _create_obj(gktype, type_name: str):
            """Create and return a new model object, placed in its default folder."""
            obj = model.newObject(gktype)
            if obj is None:
                raise RuntimeError("model.newObject() returned None")
            # Place in the type's default creation folder
            try:
                _folder = model.getCreateFolderForType(type_name)
                model.addObjectToFolder(obj, _folder)
            except Exception:
                pass
            return obj

        # ── Try to find or create a dedicated layer ───────────────────────────
        _layer = None
        _LAYER_NAME = "TSP Bus Detections"
        try:
            # Iterate layers to find an existing one with this name
            _catalog = model.getCatalog()
            if _catalog is not None:
                for _lyr in (_catalog.getObjectsByType(model.getType("GKLayer")) or []):
                    if getattr(_lyr, 'getName', lambda: '')() == _LAYER_NAME:
                        _layer = _lyr
                        break
            # Create new layer if not found
            if _layer is None:
                _lyr_type = model.getType("GKLayer")
                if _lyr_type is not None:
                    try:
                        _layer = _create_obj(_lyr_type, "GKLayer")
                    except Exception:
                        _layer = None
                    for _set_fn in ("setName", "setExternalName"):
                        try:
                            getattr(_layer, _set_fn)(_LAYER_NAME)
                            break
                        except Exception:
                            pass
        except Exception:
            _layer = None   # proceed without a custom layer

        # ── Create one marker per detection ───────────────────────────────────
        import math as _math
        n_ok   = 0
        n_fail = 0

        # GKPolyline circle parameters
        _CIRCLE_R  = 8.0   # radius in model units (metres)
        _CIRCLE_N  = 16    # number of segments

        for feat in valid_feats:
            x     = float(feat["geometry"]["coordinates"][0])
            y     = float(feat["geometry"]["coordinates"][1])
            props = feat["properties"]
            tier  = str(props.get("tier", ""))
            vid   = props.get("veh_id", "?")
            jid   = props.get("junction_id", "?")
            t_s   = props.get("sim_time_s", "?")
            label = f"{_pfx(tier)} Bus {vid}  jct {jid}  t={t_s}s  [{tier}]"

            try:
                if _use_polyline:
                    # ── Draw a small circle using GKPolyline ──────────────────
                    # Build circle coordinates as plain Python tuples — avoids
                    # depending on GKPoints3D / GKPoint which vary across builds.
                    _coords = []
                    for _k in range(_CIRCLE_N + 1):   # +1 closes the circle
                        _angle = 2.0 * _math.pi * _k / _CIRCLE_N
                        _coords.append((
                            x + _CIRCLE_R * _math.cos(_angle),
                            y + _CIRCLE_R * _math.sin(_angle),
                            0.0
                        ))

                    obj = _create_obj(_pl_type, "GKPolyline")

                    # Try every known point-setting API in order of preference.
                    _pts_set = False

                    # Option A: setPoints with list of tuples (simplest)
                    if not _pts_set:
                        try:
                            obj.setPoints(_coords)
                            _pts_set = True
                        except Exception:
                            pass

                    # Option B: GKPoint objects in a plain list
                    if not _pts_set:
                        try:
                            from PyANGKernel import GKPoint as _GKP
                            _gk_pts = []
                            for _cx, _cy, _cz in _coords:
                                _p = _GKP(); _p.x = _cx; _p.y = _cy; _p.z = _cz
                                _gk_pts.append(_p)
                            obj.setPoints(_gk_pts)
                            _pts_set = True
                        except Exception:
                            pass

                    # Option C: addPoint one at a time (tuple variant)
                    if not _pts_set:
                        try:
                            for _cx, _cy, _cz in _coords:
                                obj.addPoint(_cx, _cy, _cz)
                            _pts_set = True
                        except Exception:
                            pass

                    # Option D: addPoint with GKPoint
                    if not _pts_set:
                        try:
                            from PyANGKernel import GKPoint as _GKP
                            for _cx, _cy, _cz in _coords:
                                _p = _GKP(); _p.x = _cx; _p.y = _cy; _p.z = _cz
                                obj.addPoint(_p)
                            _pts_set = True
                        except Exception:
                            pass

                    if not _pts_set:
                        raise RuntimeError("No working setPoints/addPoint API found for GKPolyline")

                    for _fn in ("setName", "setExternalName", "setLabel"):
                        try:
                            getattr(obj, _fn)(label)
                            break
                        except Exception:
                            pass
                else:
                    # ── Create annotation (GKAnnotation or equivalent) ────────
                    obj = _create_obj(ann_type, _ann_name_used)

                    _pos_set = False
                    try:
                        from PyANGKernel import GKPoint
                        _pt = GKPoint()
                        _pt.x = x; _pt.y = y; _pt.z = 0.0
                        obj.setPosition(_pt)
                        _pos_set = True
                    except Exception:
                        pass

                    if not _pos_set:
                        try:
                            obj.setPoints([(x, y, 0.0)])
                            _pos_set = True
                        except Exception:
                            pass

                    if not _pos_set:
                        try:
                            obj.setPosition((x, y, 0.0))
                        except Exception:
                            pass

                    for _fn in ("setLabel", "setText", "setName", "setExternalName"):
                        try:
                            getattr(obj, _fn)(label)
                            break
                        except Exception:
                            pass

                # ── Set colour (bright red so circles are visible) ────────────
                try:
                    from PyANGKernel import GKColor as _GKC
                    obj.setColor(_GKC(220, 30, 30))
                except Exception:
                    pass
                try:
                    from PyQt5.QtGui import QColor as _QC
                    obj.setColor(_QC(220, 30, 30))
                except Exception:
                    pass

                # ── Assign to layer (both paths) ──────────────────────────────
                if _layer is not None:
                    for _fn in ("setLayer", "addToLayer"):
                        try:
                            getattr(obj, _fn)(_layer)
                            break
                        except Exception:
                            pass

                n_ok += 1

            except Exception as _obj_e:
                n_fail += 1
                if n_fail == 1:
                    log_to_file(f"[MAP] Marker creation failed: {_obj_e}")
                if n_fail >= 2:
                    log_to_file("[MAP] Second failure identical — stopping canvas overlay")
                    break

        # ── Trigger a view refresh so circles appear immediately ──────────────
        try:
            GKSystem.getSystem().getGUI().getActiveView().update()
        except Exception:
            pass

        _marker_kind = "circle(s)" if _use_polyline else "annotation(s)"
        log_to_file(
            f"[MAP] Canvas overlay complete: {n_ok} {_marker_kind} created "
            f"({n_fail} failed) from {len(valid_feats)} detection points.\n"
            f"      → In Aimsun: zoom out on the network canvas to see red circles.\n"
            f"      → Or open the Catalog panel and look under GEO objects.",
            force=True
        )

    except Exception as _top_e:
        import traceback
        log_to_file(
            f"[MAP] Canvas overlay error: {_top_e}\n{traceback.format_exc()}",
            force=True
        )


def AAPIFinish():
    log_to_file("===== AAPIFinish =====")
    log_to_file("[SIM_END] microscopic simulation ended — AAPIFinish started")

    # ── CRITICAL: save results FIRST so runner detects completion fast ─────────
    # The batch runner waits for simulation_results.csv folder or [FINISH] marker.
    # All the analytics below can take 30-60s; write the CSV immediately.
    try:
        stats.print_results()
        stats.save_results()
        log_to_file("[FINISH] stats saved OK")
    except Exception as e:
        import traceback
        log_to_file(f"[FINISH] stats error: {e}\n{traceback.format_exc()}", force=True)

    # ── Measured-state feed summary (witness: did the MARL_MEAS arm differ?) ──
    try:
        _mf = globals().get('_MEAS_FEED') or {}
        _flag = bool(globals().get('MEASURED_STATE_FEED', False))
        log_to_file(f"[MEAS-FEED] SUMMARY flag={_flag} "
                    f"evaluations={int(_mf.get('seen', 0) or 0)} "
                    f"density_adopts={int(_mf.get('den', 0) or 0)} "
                    f"flow_caps={int(_mf.get('cap', 0) or 0)}", force=True)
    except Exception:
        pass

    # ── flush pending pure-signal-wait accumulations, then report ──────────
    try:
        _pt_sigwait_flush()
        _swk = stats.bus_signal_wait_kpis()
        log_to_file("[SIG-WAIT] buses=%(n)d total_red_wait=%(w).0fs "
                    "avg=%(a).1fs/bus pax_weighted=%(p).0f pax-s"
                    % {"n": _swk["n_buses_measured"],
                       "w": _swk["total_wait_s"],
                       "a": _swk["avg_wait_s"],
                       "p": _swk["total_pax_wait_s"]}, force=True)
    except Exception as e:
        log_to_file(f"[SIG-WAIT] finish error: {e!r}", force=True)


    # ── ETA bias learner: report what each line taught us ─────────────────
    try:
        if _ETA_BIAS:
            _top = sorted(_ETA_BIAS.items(), key=lambda kv: -kv[1])[:12]
            log_to_file("[ETA-BIAS] learned per-line lateness (s): "
                        + ", ".join("%s=%.0f" % (k, v) for k, v in _top),
                        )
    except Exception:
        pass


    # ── PT-injection: persist calibration captured this run ──────────────
    try:
        _m = _pt_inj.MANAGER
        if _m.armed:
            if _m.calibrating and _m.session_entries:
                _saved = _m.save_calibration()
                log_to_file(f"[PT-INJ] calibration saved: {_saved} entries -> "
                            f"{_m.calibration_path()}", force=True)
            elif _pt_inj and not _m.calibrating:
                log_to_file(f"[PT-INJ] run summary: {_m.summary()}", force=True)
    except Exception as _pi_err:
        log_to_file(f"[PT-INJ] finish error: {_pi_err!r}", force=True)


    # ── Aggregate corridor coordinator pre-arm stats ───────────────────────────
    try:
        _combined_prearm = {"fired": 0, "success": 0, "missed": 0,
                             "expired": 0, "discarded": 0,
                             "late_success": 0, "late_success_delay_s": 0.0}
        for _coord in corridor_coordinators:
            _ps = getattr(_coord, '_prearm_stats', {})
            for _k in _combined_prearm:
                if _k == "late_success_delay_s":
                    _combined_prearm[_k] += float(_ps.get(_k, 0.0))
                else:
                    _combined_prearm[_k] += int(_ps.get(_k, 0))
        stats.record_prearm_stats(_combined_prearm)
        _fired = int(_combined_prearm.get("fired", 0) or 0)
        _succ = int(_combined_prearm.get("success", 0) or 0)
        _succ_pct = (100.0 * _succ / _fired) if _fired > 0 else 0.0
        log_to_file(f"[FINISH] prearm stats: {_combined_prearm}")
        log_to_file(
            f"[FINISH] prearm success rate: {_succ}/{_fired} = {_succ_pct:.1f}%",
        )
    except Exception as _pe:
        log_to_file(f"[FINISH] prearm stats error: {_pe}", force=True)

    # ── Collect network-level section statistics ───────────────────────────────
    try:
        # Use ALL network sections for global stats — this matches what Aimsun's
        # Statistics panel shows (network-wide density/flow/speed).
        _all_secs: set = set()
        try:
            _n_secs = int(AKIInfNetNbSectionsANG())
            for _si in range(_n_secs):
                _sid = int(AKIInfNetGetSectionANGId(_si))
                if _sid > 0:
                    _all_secs.add(_sid)
            log_to_file(
                f"[FINISH] network sections from AKIInfNet: {len(_all_secs)}",
            )
        except Exception as _net_e:
            log_to_file(
                f"[FINISH] AKIInfNetNbSectionsANG fallback: {_net_e}", force=True
            )
            # Fallback to approach sections from controllers + stats records
            for _ctrl in controllers.values():
                for _sec in getattr(_ctrl, 'incoming_sections', []):
                    if _sec and _sec > 0:
                        _all_secs.add(_sec)
            for _iid_data in getattr(stats, '_inter', {}).values():
                for _sec in _iid_data.get('main_sections', []):
                    if _sec and isinstance(_sec, int) and _sec > 0:
                        _all_secs.add(_sec)
                for _sec in _iid_data.get('side_sections', []):
                    if _sec and isinstance(_sec, int) and _sec > 0:
                        _all_secs.add(_sec)
        stats.collect_network_stats_at_finish(list(_all_secs))
        # Extended per-section stats (entry/exit TT, exit count/flow/speed, stop
        # time, num stops, total distance/travel-time) → the Net_EntryTT_*,
        # Net_ExitCount_*, Net_ExitFlow_*, Net_ExitSpd_* ... CSV columns and the
        # dashboard's "Network Statistics" table.  The pre-refactor lean
        # controller called this in AAPIFinish; the shared-engine refactor
        # dropped it, so those columns were all zero until this line was
        # restored.
        try:
            stats.collect_extra_section_stats(list(_all_secs))
            _ec_all  = getattr(stats, '_net_extra_exit_count_all', 0)
            _et_all  = getattr(stats, '_net_extra_entry_tt_all', 0.0)
            _xt_all  = getattr(stats, '_net_extra_exit_tt_all',  0.0)
            _es_all  = getattr(stats, '_net_extra_exit_spd_all', 0.0)
            log_to_file(
                f"[FINISH] extra section stats collected "
                f"(sections={len(_all_secs)} exit_count_all={_ec_all} "
                f"entry_tt_all={_et_all:.2f}s/km exit_tt_all={_xt_all:.2f}s/km "
                f"exit_spd_all={_es_all:.2f}km/h)",
                force=True)
        except Exception as _extra_e:
            log_to_file(f"[FINISH] collect_extra_section_stats failed: {_extra_e!r}",
                        force=True)
        log_to_file(f"[FINISH] network stats collected ({len(_all_secs)} sections)", force=True)
        try:
            _net_flow = int(getattr(stats, '_net_total_flow_veh', 0) or 0)
            _net_den = float(getattr(stats, '_net_avg_density_vkm', 0.0) or 0.0)
            _net_spd = float(getattr(stats, '_net_avg_speed_kmh', 0.0) or 0.0)
            _net_dbg = dict(getattr(stats, '_net_debug', {}) or {})
            log_to_file(
                f"[FINISH] network kpis: flow={_net_flow} veh "
                f"density={_net_den:.4f} veh/km speed={_net_spd:.3f} km/h",
                force=True,
            )
            if _net_dbg:
                log_to_file(
                    "[FINISH] network debug: "
                    f"source={_net_dbg.get('source')} sim_time_s={_net_dbg.get('sim_time_s')} "
                    f"sections={_net_dbg.get('section_count')} stats_ok={_net_dbg.get('stats_ok_sections')} "
                    f"stats_zero={_net_dbg.get('stats_zero_sections')} snap_ok={_net_dbg.get('snapshot_ok_sections')} "
                    f"snap_with_veh={_net_dbg.get('snapshot_sections_with_vehicles')} "
                    f"snap_zero={_net_dbg.get('snapshot_zero_sections')} "
                    f"missing_len={_net_dbg.get('sections_missing_length')}",
                    force=True,
                )
            if _net_flow <= 0 and _net_den <= 0 and _net_spd <= 0:
                log_to_file(
                    "[FINISH] network kpis are all zero; check section stats API "
                    "availability and section coverage.",
                    force=True,
                )
        except Exception as _nk:
            log_to_file(f"[FINISH] network kpi log error: {_nk}", force=True)
    except Exception as _ne:
        log_to_file(f"[FINISH] network stats error: {_ne}", force=True)

    # ── [FLOW CHECK] turning-level vs section-level main/side flow ───────────
    # Cross-validate the shockwave's section-based main/side flow against Aimsun's
    # AUTHORITATIVE turning statistics (node flow = sum of turning flows). Large
    # disagreement => the section main/side assignment (or the flow estimate) is
    # off. Read-only, logged per managed junction.
    try:
        _sim_t = float(AKIGetCurrentSimulationTime() or 0.0)
        _sh = (_sim_t / 3600.0) if _sim_t > 0.0 else None
        for _iid, _ctrl in list(controllers.items()):
            try:
                _mv, _sv, _nmt, _nst = _ctrl._turning_main_side_flow(_sh)
                _uf = np.asarray(getattr(_ctrl, 'UpFlowList', []), dtype=float).ravel()
                _sf = np.asarray(getattr(_ctrl, 'SideUpFlowList', []), dtype=float).ravel()
                _ufp = _uf[_uf > 0.0]; _sfp = _sf[_sf > 0.0]
                _sec_main = float(np.mean(_ufp)) if _ufp.size else 0.0
                _sec_side = float(np.mean(_sfp)) if _sfp.size else 0.0
                log_to_file(
                    f"[FLOW CHECK] inter={_iid} | turnings main={_mv:.0f} side={_sv:.0f} "
                    f"(nT main={_nmt} side={_nst}) | shockwave main={_sec_main:.0f} "
                    f"side={_sec_side:.0f} veh/h", force=True)
            except Exception:
                continue
    except Exception as _fce:
        log_to_file(f"[FLOW CHECK] error: {_fce!r}", force=True)

    try:
        _gk = stats._global_kpis()
        _nat = int(_gk.get('n_tsp_natural_green', 0) or 0)
        _det = int(_gk.get('n_tsp_detections', 0) or 0)
        _nat_pct = (100.0 * _nat / _det) if _det > 0 else 0.0
        log_to_file(
            f"[FINISH] natural_green: {_nat}/{_det} = {_nat_pct:.1f}%",
        )
    except Exception:
        pass

    try:
        _write_run_summary()
        log_to_file(f"[FINISH] run summary written: {_RUN_SUMMARY_TXT}")
    except Exception as e:
        log_to_file(f"[FINISH] run summary error: {e}", force=True)

    try:
        _write_algorithm_explanation_tex()
        log_to_file(f"[FINISH] algorithm explanation written: {_ALGORITHM_EXPLANATION_TEX}")
    except Exception as e:
        log_to_file(f"[FINISH] algorithm explanation error: {e}", force=True)
    for controller in controllers.values():
        if CONTROL_MODE == "URTSP":
            log_to_file(controller.get_urtsp_summary())
    # ── Corridor summary ──────────────────────────────────────────────────────
    for coord in corridor_coordinators:
        log_to_file(f"[FINISH] {coord.summary()}")
    # ── Schedule-recovery plot ────────────────────────────────────────────────
    # Skipped when SKIP_PER_RUN_PLOTS is set (batch sweeps via write_run_config;
    # GUI/single runs never call it, so their plots are unaffected). The render
    # (6000px+ figures at high GE counts) costs tens of seconds per run --
    # pure overhead across a 91-run sweep. CSVs carry the same numbers.
    if not bool(globals().get('SKIP_PER_RUN_PLOTS', False)):
        try:
            _plot_schedule_recovery()
        except Exception as _sre:
            log_to_file(f"[FINISH] schedule recovery plot error: {_sre}")
    else:
        try:
            log_to_file("[FINISH] schedule recovery plot skipped (batch mode)")
        except Exception:
            pass

    # ── Flush detection-point GeoJSON ─────────────────────────────────────────
    if MARK_DETECTION_POINTS and _geojson_features:
        try:
            import json
            geojson = {
                "type": "FeatureCollection",
                "features": _geojson_features,
            }
            with open(_DET_GEOJSON, "w", encoding="utf-8") as _gf:
                json.dump(geojson, _gf, indent=2)
            log_to_file(
                f"[MARK] Detection GeoJSON written: {_DET_GEOJSON} "
                f"({len(_geojson_features)} points)"
            )
        except Exception as _ge:
            log_to_file(f"[MARK] GeoJSON write failed: {_ge}")

    # ── Detection-point diagnostics (always shown) ────────────────────────────
    log_to_file(
        f"[MARK DIAG] MARK_DETECTION_POINTS={MARK_DETECTION_POINTS} | "
        f"_mark_calls_total={_mark_calls_total} | "
        f"_mark_calls_written={_mark_calls_written} | "
        f"unique_pairs={len(_marked_detections)} | "
        f"geojson_features={len(_geojson_features)} | "
        f"CSV_path={_DET_CSV} | "
        f"CSV_exists={os.path.isfile(_DET_CSV)}",
        force=True
    )

    # ── Per-junction detection summary ───────────────────────────────────────
    # Shows exactly how many unique buses were detected at each junction, split
    # by tier (IC-detect, track-section, track-zone, focus, coord, etc.).
    # Useful for diagnosing "not seen" gaps in the dashboard.
    try:
        _det_by_jct: dict = {}  # {jct_id: {tier: count}}
        _det_buses_by_jct: dict = {}  # {jct_id: set(veh_id)}
        for (_dj, _dv) in _marked_detections:
            _det_buses_by_jct.setdefault(_dj, set()).add(_dv)
        # Also load tier breakdown from CSV
        if os.path.isfile(_DET_CSV):
            with open(_DET_CSV, "r", newline="", encoding="utf-8") as _df:
                for _dr in csv.DictReader(_df):
                    try:
                        _jid = int(float(_dr.get("junction_id", -1) or -1))
                        _tier = str(_dr.get("tier", "?") or "?")
                        if _jid > 0:
                            _det_by_jct.setdefault(_jid, {})
                            _det_by_jct[_jid][_tier] = _det_by_jct[_jid].get(_tier, 0) + 1
                    except Exception:
                        pass
        _total_det_buses = len(set(v for pairs in _det_buses_by_jct.values() for v in pairs))
        _total_active    = len(_bus_seen_ids)
        log_to_file(
            f"[DET SUMMARY] Active buses tracked: {_total_active} | "
            f"Unique buses detected at ≥1 junction: {_total_det_buses} | "
            f"PT route map: {len(_pt_line_jct_route)} lines / {len(_sec_to_corridor_jct)} sections",
            )
        for _jid in sorted(_det_buses_by_jct.keys()):
            _n_det = len(_det_buses_by_jct[_jid])
            _tiers = _det_by_jct.get(_jid, {})
            _tier_str = " ".join(f"{t}:{n}" for t, n in sorted(_tiers.items()))
            log_to_file(
                f"[DET SUMMARY] jct={_jid}: {_n_det} unique buses detected | {_tier_str}",
                )
        # Junctions with 0 detections
        _zero_jcts = [j for j in controllers if j not in _det_buses_by_jct]
        if _zero_jcts:
            log_to_file(
                f"[DET SUMMARY] Junctions with 0 detections: {sorted(_zero_jcts)}",
                )
    except Exception as _ds_e:
        log_to_file(f"[DET SUMMARY] error building summary: {_ds_e}", force=True)

    # ── NO_INS summary by intersection (counts by reason) ───────────────────
    # Reads harmony-no-ins-local decision rows from the detection CSV and
    # aggregates reason buckets for fast diagnosis of insertion denials.
    try:
        _noins_by_jct: dict = {}
        _noins_total = 0
        if os.path.isfile(_DET_CSV):
            with open(_DET_CSV, "r", newline="", encoding="utf-8") as _nf:
                for _nr in csv.DictReader(_nf):
                    try:
                        _tier = str(_nr.get("tier", "") or "").strip()
                        if _tier != "harmony-no-ins-local":
                            continue
                        _jid = int(float(_nr.get("junction_id", -1) or -1))
                        if _jid <= 0:
                            continue
                        _note = str(_nr.get("prearm_note", "") or "").strip()
                        if not _note:
                            _note = str(_nr.get("note", "") or "").strip()
                        _reason = _note if _note else "unspecified"
                        if "|" in _reason:
                            _reason = _reason.split("|", 1)[0].strip()
                        if _reason.upper().startswith("NO_INS "):
                            _reason = _reason[7:].strip()
                        if not _reason:
                            _reason = "unspecified"
                        _noins_by_jct.setdefault(_jid, collections.Counter())[_reason] += 1
                        _noins_total += 1
                    except Exception:
                        continue

        if _noins_total > 0:
            with open(_NO_INS_SUMMARY_CSV, "w", newline="", encoding="utf-8") as _nof:
                _nw = csv.writer(_nof)
                _nw.writerow(["junction_id", "reason", "count"])
                for _jid in sorted(_noins_by_jct.keys()):
                    for _reason, _count in _noins_by_jct[_jid].most_common():
                        _nw.writerow([_jid, _reason, _count])

            log_to_file(
                f"[NO_INS SUMMARY] total_no_ins={_noins_total} | "
                f"junctions={len(_noins_by_jct)} | csv={_NO_INS_SUMMARY_CSV}",
                force=True,
            )
            for _jid in sorted(_noins_by_jct.keys()):
                _items = _noins_by_jct[_jid].most_common()
                _reason_txt = " | ".join(f"{_r}:{_c}" for _r, _c in _items)
                log_to_file(
                    f"[NO_INS SUMMARY] jct={_jid} total={sum(_noins_by_jct[_jid].values())} "
                    f"reasons={_reason_txt}",
                    force=True,
                )
        else:
            log_to_file(
                "[NO_INS SUMMARY] no harmony-no-ins-local rows in detection CSV",
                force=True,
            )
    except Exception as _nis_e:
        log_to_file(f"[NO_INS SUMMARY] error building summary: {_nis_e}", force=True)

    # ── Bus-tracking diagnostics (always shown) ─────────────────────────────
    try:
        _bt_exists = os.path.isfile(_BUS_TRACKING_CSV)
        _bt_rows = 0
        _bt_uniq_bus = set()
        _bt_uniq_jct = set()
        _bt_events = {}
        if _bt_exists:
            with open(_BUS_TRACKING_CSV, "r", newline="", encoding="utf-8") as _bf:
                _br = csv.DictReader(_bf)
                for _r in _br:
                    _bt_rows += 1
                    try:
                        _v = int(float(_r.get("veh_id", 0) or 0))
                        if _v > 0:
                            _bt_uniq_bus.add(_v)
                    except Exception:
                        pass
                    try:
                        _j = int(float(_r.get("nearest_jct", -1) or -1))
                        if _j > 0:
                            _bt_uniq_jct.add(_j)
                    except Exception:
                        pass
                    _ev = str(_r.get("event", "track") or "track")
                    _bt_events[_ev] = int(_bt_events.get(_ev, 0)) + 1
        _ev_text = ", ".join(
            f"{_k}:{_bt_events[_k]}" for _k in sorted(_bt_events.keys())
        ) if _bt_events else "none"
        log_to_file(
            f"[BUS_TRACK DIAG] TRACK_BUS_POSITIONS={TRACK_BUS_POSITIONS} | "
            f"CSV_path={_BUS_TRACKING_CSV} | exists={_bt_exists} | "
            f"rows={_bt_rows} | unique_buses={len(_bt_uniq_bus)} | "
            f"unique_jcts={len(_bt_uniq_jct)} | events={_ev_text}",
            force=True,
        )
    except Exception as _bt_e:
        log_to_file(f"[BUS_TRACK DIAG] error: {_bt_e}", force=True)

    # ── Presence-snapshot diagnostics (always shown) ───────────────────────
    try:
        _ps_exists = os.path.isfile(_PRESENCE_SNAPSHOT_CSV)
        _ps_rows = 0
        _ps_uniq_bus = set()
        _ps_uniq_jct = set()
        _ps_scope = {}
        if _ps_exists:
            with open(_PRESENCE_SNAPSHOT_CSV, "r", newline="", encoding="utf-8") as _pf:
                _pr = csv.DictReader(_pf)
                for _r in _pr:
                    _ps_rows += 1
                    try:
                        _v = int(float(_r.get("veh_id", 0) or 0))
                        if _v > 0:
                            _ps_uniq_bus.add(_v)
                    except Exception:
                        pass
                    try:
                        _j = int(float(_r.get("junction_id", -1) or -1))
                        if _j > 0:
                            _ps_uniq_jct.add(_j)
                    except Exception:
                        pass
                    _sc = str(_r.get("scope", "") or "")
                    if _sc:
                        _ps_scope[_sc] = int(_ps_scope.get(_sc, 0)) + 1
        _scope_text = ", ".join(
            f"{_k}:{_ps_scope[_k]}" for _k in sorted(_ps_scope.keys())
        ) if _ps_scope else "none"
        log_to_file(
            f"[PRESENCE_SNAPSHOT DIAG] CSV_path={_PRESENCE_SNAPSHOT_CSV} | "
            f"exists={_ps_exists} | rows={_ps_rows} | "
            f"unique_buses={len(_ps_uniq_bus)} | unique_jcts={len(_ps_uniq_jct)} | "
            f"scope={_scope_text}",
            force=True,
        )
    except Exception as _ps_e:
        log_to_file(f"[PRESENCE_SNAPSHOT DIAG] error: {_ps_e}", force=True)

    # ── Corridor wave/coordinator event CSV ──────────────────────────────────
    # ── Global bus focus history CSV ──────────────────────────────────────────
    # Flush any still-active focus so the final event is not lost.
    if _focus_bus_id > 0:
        try:
            _t_now = float(AKIGetCurrentSimulationTime())
        except Exception:
            _t_now = float(AKIGetSimulationTime()) if 'AKIGetSimulationTime' in globals() else 0.0
        _release_focus(_t_now, "finish_flush")

    if _focus_history:
        try:

            _focus_csv = _DET_CSV.replace("detection_points_", "focus_history_")
            with open(_focus_csv, "w", newline="", encoding="utf-8") as _ff:
                _fw = csv.writer(_ff)
                _fw.writerow(["start_t", "end_t", "veh_id", "jct_id",
                              "outcome", "held_s"])
                for _fh in _focus_history:
                    _fw.writerow([
                        f"{_fh[0]:.1f}", f"{_fh[1]:.1f}",
                        _fh[2], _fh[3], _fh[4],
                        f"{_fh[1] - _fh[0]:.1f}",
                    ])
            log_to_file(
                f"[BUS_FOCUS] history CSV written: {_focus_csv} "
                f"({len(_focus_history)} events)", force=True)
        except Exception as _fe:
            log_to_file(f"[BUS_FOCUS] history CSV error: {_fe}")

    if _wave_events:
        try:
            with open(_WAVE_EVENTS_CSV, "w", newline="", encoding="utf-8") as _wf:
                _base_fields = [
                    "sim_time_s", "group", "event",
                    "source_jct", "target_jct", "veh_id",
                    "eta_s", "lead_s", "note",
                ]
                _extra_fields = sorted({
                    _k for _row in _wave_events for _k in _row.keys()
                    if _k not in _base_fields
                })
                _w = csv.DictWriter(_wf, fieldnames=_base_fields + _extra_fields)
                _w.writeheader()
                _w.writerows(_wave_events)
            log_to_file(
                f"[FINISH] corridor wave events written: {_WAVE_EVENTS_CSV} "
                f"({len(_wave_events)} rows)",
            )
        except Exception as _we:
            log_to_file(f"[FINISH] corridor wave event write error: {_we}", force=True)

    # ── Coordination diagnostics plot (shockwave/Kalman inputs by junction) ──
    try:
        import importlib
        import plot_coord_diagnostics as _pcd
        importlib.reload(_pcd)
        _pcd.run(wave_csv=_WAVE_EVENTS_CSV)
        log_to_file("[COORD DIAG] Shockwave/Kalman diagnostics plot written")
    except ModuleNotFoundError as _cde:
        log_to_file(f"[COORD DIAG] Optional plot skipped: {_cde}", force=True)
    except Exception as _cde:
        import traceback
        log_to_file(f"[COORD DIAG] Plot failed: {_cde}\n{traceback.format_exc()}", force=True)

    # Dump the bus_sg and tsp_mode of every GB controller so we can see if
    # detection is even plausible
    for _iid, _ctrl in controllers.items():
        _gb = getattr(_ctrl, 'gb', None)
        if _gb is not None:
            log_to_file(
                f"[MARK DIAG] jct={_iid} "
                f"bus_sg={getattr(_gb,'bus_sg',None)} "
                f"tsp_mode={getattr(_gb,'tsp_mode','?')} "
                f"bus_type_pos={getattr(_gb,'bus_type_pos','?')} "
                f"bus_det={getattr(_gb,'bus_det',[])} "
                f"incoming_secs={getattr(_gb,'incoming_sections',[])} "
                f"jxy_cache={getattr(_gb,'_junction_xy_cache',None)}",
            )

    # ── Write junction centroids CSV ──────────────────────────────────────────
    # Collected from every controller's cached XY (IntersectionController and
    # GroupBasedController both store _junction_xy / _junction_xy_cache).
    # The plot script reads this to draw intersection markers as a reference frame.
    if MARK_DETECTION_POINTS:
        try:
            with open(_JUNC_CSV, "w", newline="", encoding="utf-8") as _jf:
                _jw = csv.writer(_jf)
                _jw.writerow(["junction_id", "x", "y", "cycle_time_s", "bus_phase", "bus_phase_duration_s"])
                for _jiid, _jctrl in controllers.items():
                    # Try cached value first; if not set, call _get_junction_xy()
                    # to resolve it now (the lazy cache may not have fired if no
                    # buses were detected at this junction this run).
                    _jxy = getattr(_jctrl, '_junction_xy', None)
                    if _jxy is None and hasattr(_jctrl, '_get_junction_xy'):
                        try:
                            _jxy = _jctrl._get_junction_xy()
                        except Exception:
                            pass
                    # GroupBasedController caches in gb._junction_xy_cache
                    if _jxy is None:
                        _gb = getattr(_jctrl, 'gb', None)
                        if _gb is not None:
                            _jxy = getattr(_gb, '_junction_xy_cache', None)
                            if _jxy is None and hasattr(_gb, '_get_junction_xy'):
                                try:
                                    _jxy = _gb._get_junction_xy()
                                except Exception:
                                    pass
                    if _jxy is not None:
                        _ctrl_cfg = getattr(_jctrl, 'config', {}) or {}
                        _cycle_t  = float(_ctrl_cfg.get('CycleTime', _ctrl_cfg.get('cycle_length', 0)) or 0)
                        if _cycle_t <= 0:
                            _cycle_t = float(INTERSECTIONS_CONFIG.get(_jiid, {}).get('CycleTime', 0) or 0)
                        # If still zero, compute from the actual Aimsun signal plan
                        if _cycle_t <= 0:
                            _pl = getattr(_jctrl, 'phase_list', [])
                            _noms = getattr(_jctrl, '_nominal_phase_durations', {})
                            if _pl:
                                _cycle_t = sum(
                                    float(_noms.get(_ph, GetPhaseDuration(_jctrl.id, _ph, 0.0) or 15.0))
                                    for _ph in _pl)
                            if _cycle_t <= 0:
                                _cycle_t = 135.0
                        # Prefer runtime-discovered values over static config.
                        # The controller may have auto-detected BusPhase from the
                        # Aimsun model even when INTERSECTIONS_CONFIG has no entry.
                        _bus_ph = int(getattr(_jctrl, 'BusPhase', -1) or -1)
                        if _bus_ph < 0:
                            _bus_ph = int(_ctrl_cfg.get('BusPhase', -1) or -1)
                        _bus_dur = float(getattr(_jctrl, 'BusPhaseDuration', 0) or 0)
                        if _bus_dur <= 0:
                            _bus_dur = float(_ctrl_cfg.get('BusPhaseDuration', 0) or 0)
                        _ph_durs = _ctrl_cfg.get('_nominal_phase_durations', None)
                        if _ph_durs is None:
                            _ph_durs = getattr(_jctrl, '_nominal_phase_durations', {}) or {}
                        if _bus_dur <= 0 and _ph_durs:
                            _bus_dur = float(_ph_durs.get(_bus_ph, 0) or 0)
                        _jw.writerow([_jiid, f"{_jxy[0]:.3f}", f"{_jxy[1]:.3f}",
                                      f"{_cycle_t:.1f}", _bus_ph, f"{_bus_dur:.1f}"])
            log_to_file(f"[MARK] Junction centroids written: {_JUNC_CSV}")
        except Exception as _je:
            log_to_file(f"[MARK] Junction centroids write failed: {_je}", force=True)

    # ── Plot detection points to PNG + HTML map (post-simulation) ─────────────
    if MARK_DETECTION_POINTS:
        if not os.path.isfile(_DET_CSV):
            log_to_file("[MARK] Detection plot skipped — no CSV (no buses detected?)")
        else:
            _script_dir = _CORRIDOR_DIR
            if _script_dir not in sys.path:
                sys.path.insert(0, _script_dir)
            try:
                import importlib
                import plot_detections as _pd
                importlib.reload(_pd)
                _junc_csv_arg = _JUNC_CSV if os.path.isfile(_JUNC_CSV) else None
                _pd.run(csv_path=_DET_CSV, junc_csv=_junc_csv_arg)
                log_to_file(f"[MARK] Detection plot written alongside {_DET_CSV}")
            except Exception as _pe:
                import traceback
                log_to_file(f"[MARK] Detection plot failed: {_pe}\n{traceback.format_exc()}", force=True)

            # ── Green-wave time-space dashboard ───────────────────────────────
            try:
                import importlib
                import plot_green_wave as _pgw
                importlib.reload(_pgw)
                _junc_csv_arg = _JUNC_CSV if os.path.isfile(_JUNC_CSV) else None
                _pgw.run(csv_path=_DET_CSV, junc_csv=_junc_csv_arg)
                log_to_file("[GREEN WAVE] Green-wave dashboard written")
            except Exception as _gwe:
                import traceback
                log_to_file(
                    f"[GREEN WAVE] Plot failed: {_gwe}\n{traceback.format_exc()}",
                    force=True
                )

            # ── Per-bus detail plots with missed-green diagnostics ─────────────
            try:
                import importlib
                import plot_bus_detail as _pbd
                importlib.reload(_pbd)
                _junc_csv_arg = _JUNC_CSV if os.path.isfile(_JUNC_CSV) else None
                _pbd.run(csv_path=_DET_CSV, junc_csv=_junc_csv_arg)
                log_to_file("[BUS DETAIL] Per-bus plots written")
            except Exception as _bde:
                import traceback
                log_to_file(
                    f"[BUS DETAIL] Plot failed: {_bde}\n{traceback.format_exc()}",
                    force=True
                )

            # ── Space-time green-wave diagram ─────────────────────────────────
            try:
                import importlib
                import plot_spacetime_wave as _pst
                importlib.reload(_pst)
                _junc_csv_arg = _JUNC_CSV if os.path.isfile(_JUNC_CSV) else None
                _pst.run(csv_path=_DET_CSV, junc_csv=_junc_csv_arg)
                log_to_file("[SPACETIME] Space-time diagram written")
            except Exception as _ste:
                import traceback
                log_to_file(
                    f"[SPACETIME] Plot failed: {_ste}\n{traceback.format_exc()}",
                    force=True
                )

            # ── Shockwave / queue-length dashboard ───────────────────────────
            try:
                import importlib
                import plot_shockwave as _psw
                importlib.reload(_psw)
                _junc_csv_arg = _JUNC_CSV if os.path.isfile(_JUNC_CSV) else None
                _wave_csv_arg = _WAVE_EVENTS_CSV if os.path.isfile(_WAVE_EVENTS_CSV) else None
                _psw.run(det_csv=_DET_CSV, junc_csv=_junc_csv_arg,
                         wave_csv=_wave_csv_arg)
                log_to_file("[SHOCKWAVE] Shockwave dashboard written")
            except Exception as _psw_e:
                import traceback
                log_to_file(
                    f"[SHOCKWAVE] Plot failed: {_psw_e}\n{traceback.format_exc()}",
                    force=True
                )

            # ── TSP objective trace dashboard ─────────────────────────────────
            try:
                import importlib
                import plot_tsp_objective_trace as _ptot
                importlib.reload(_ptot)
                _obj_trace_arg = (
                    _OBJECTIVE_TRACE_CSV if os.path.isfile(_OBJECTIVE_TRACE_CSV) else None
                )
                _obj_out = os.path.join(
                    _CORRIDOR_DIR, "tsp_objective_trace.html"
                )
                if _obj_trace_arg:
                    rows_ot = _ptot._load_objective_csv(_obj_trace_arg)
                    _ptot._build_html(rows_ot, _obj_trace_arg, _obj_out)
                    log_to_file(
                        f"[OBJ TRACE] Objective trace dashboard written ({len(rows_ot)} rows)",
                    )
                else:
                    log_to_file("[OBJ TRACE] No objective_trace CSV found — skipping")
            except Exception as _otot_e:
                import traceback
                log_to_file(
                    f"[OBJ TRACE] Dashboard failed: {_otot_e}\n{traceback.format_exc()}",
                    force=True
                )

            # ── Queue monitor dashboard ───────────────────────────────────────
            try:
                import importlib
                import plot_queue_monitor as _pqm
                importlib.reload(_pqm)
                _queue_csv_arg = _QUEUE_SNAPSHOT_CSV if os.path.isfile(_QUEUE_SNAPSHOT_CSV) else None
                _pqm.run(queue_csv=_queue_csv_arg, junc_csv=_JUNC_CSV)
                log_to_file("[QUEUE MON] Queue monitor dashboard written")
            except Exception as _pqm_e:
                import traceback
                log_to_file(
                    f"[QUEUE MON] Plot failed: {_pqm_e}\n{traceback.format_exc()}",
                    force=True
                )

            # ── HTML comparison dashboard (updates after every run) ────────────
            try:
                import importlib
                import generate_dashboard as _gd
                importlib.reload(_gd)
                # Use whichever results CSV THIS run's launcher actually wrote
                # to (batch_runner.py's full-sweep batch_results.csv, or a
                # GUI/studio-driven batch_results_gui.csv) -- written by
                # write_run_config() as RESULTS_CSV_NAME. Without this, the
                # dashboard always rebuilt from the main batch_results.csv
                # regardless of which run actually just happened, showing
                # every historical experiment ever accumulated there instead
                # of just the run(s) the user asked for.
                try:
                    _rc_path = os.path.join(_CORRIDOR_DIR, "run_config.py")
                    _rc_ns = {}
                    with open(_rc_path, "r", encoding="utf-8") as _rc_f:
                        exec(_rc_f.read(), _rc_ns)
                    _results_csv_name = str(_rc_ns.get("RESULTS_CSV_NAME", "batch_results.csv"))
                except Exception:
                    _results_csv_name = "batch_results.csv"
                _batch_csv = os.path.join(_CORRIDOR_DIR, _results_csv_name)
                _dash_dir = _CORRIDOR_DIR
                # Suffix the output HTML to match the results CSV (e.g.
                # batch_results_gui.csv -> tsp_dashboard_gui.html) so a
                # GUI/studio test run never clobbers the main sweep's
                # dashboard (or vice versa) -- each launcher gets its own
                # persistent dashboard reflecting only its own runs. The
                # plain batch_results.csv case keeps the original filenames
                # for backward compatibility with existing bookmarks/workflows.
                _dash_suffix = ""
                if _results_csv_name != "batch_results.csv":
                    _dash_suffix = "_" + os.path.splitext(_results_csv_name)[0].removeprefix("batch_results").lstrip("_")
                _tsp_dash_name = f"tsp_dashboard{_dash_suffix}.html"
                _plots_dash_name = f"plots_dashboard{_dash_suffix}.html"
                _gd.generate(
                    batch_csv=_batch_csv if os.path.isfile(_batch_csv) else None,
                    out_html=os.path.join(_dash_dir, _tsp_dash_name),
                    log_dir=os.path.join(
                        _CORRIDOR_DIR, "logs")
                )
                # Backward-compatible alias: many workflows still open
                # plots_dashboard.html directly.
                _gd.generate(
                    batch_csv=_batch_csv if os.path.isfile(_batch_csv) else None,
                    out_html=os.path.join(_dash_dir, _plots_dash_name),
                    log_dir=os.path.join(_dash_dir, "logs")
                )
                log_to_file(f"[DASHBOARD] HTML dashboards written: {_tsp_dash_name} + {_plots_dash_name} (source: {_results_csv_name})")
            except Exception as _dbe:
                import traceback
                log_to_file(
                    f"[DASHBOARD] Generation failed: {_dbe}\n{traceback.format_exc()}",
                    force=True
                )

    # ── Aimsun canvas overlay — GKAnnotation markers in the network view ────────
    # Creates persistent markers visible in the Aimsun network editor.
    # Independent of the PNG/HTML outputs — runs even if those fail.
    if MARK_DETECTION_POINTS and _geojson_features:
        _overlay_detections_on_aimsun_map()
    elif OVERLAY_DETECTIONS_ON_MAP and not _geojson_features:
        log_to_file(
            f"[MAP] No detections collected — GeoJSON at {_DET_GEOJSON} for "
            "manual import via File > Import in Aimsun",
            force=True
        )

    return 0


