def AAPIEnterVehicle(idveh, idsection):
    # PT-frequency scaler (Plan B). This callback fires for EVERY vehicle
    # entering EVERY section, so it must be near-free: one dict lookup in the
    # common case. Heavy work and vehicle removal are DEFERRED to PostManage
    # (AKIRemoveVehicle inside this callback is kernel-reentrant = crash).
    try:
        m = _pt_inj.MANAGER
        if not m.armed:
            _pt_inj_lazy_init()
            m = _pt_inj.MANAGER
        _schedule_line_registry()
        cand = m.sec_to_lines.get(int(idsection))
        if not cand:
            cand = _SCHED_SEC_TO_LINES.get(int(idsection))
        if not cand:
            return 0                      # not a PT line entry section
        now = float(AKIGetCurrentSimulationTime())
        lid = min(cand)
        if m.calibrating:
            # Every registered section now maps to the whole line, so AAPIEnter
            # fires for CARS on those sections too.  Record only vehicles that
            # genuinely follow the line (the authoritative "is a bus" test that
            # works even when vehicle-type-name resolution fails, as it did on
            # KG: VEH SCAN showed only SWIG pointer reprs).
            _is_pt = False
            try:
                _nv = int(AKIGetNbVehiclesFollowingPTLine(int(lid)))
                for _vi in range(_nv):
                    try:
                        if int(AKIGetVehicleFollowingPTLine(int(lid), _vi)) == int(idveh):
                            _is_pt = True
                            break
                    except Exception:
                        continue
            except Exception:
                _is_pt = False
            if not _is_pt:
                return 0
            m.on_enter(idsection, now, True, veh_id=int(idveh))
            m.natural_count += 1
            return 0
        if not m.suppressing:
            _record_schedule_entry(idveh, cand, now)
            return 0                      # injection mode has no removal work
        # ── Is this vehicle a bus? ────────────────────────────────────────────
        # The type-position test is preferred because it is O(1), but it is NOT
        # reliable: on a model whose bus-type object does not resolve,
        # stats._bus_pos is the not-found sentinel (observed -4008) and the old
        # `busp > 0 and vtype == busp` guard silently rejected EVERY bus, so
        # BUSx0.5 removed nothing and reported the unsuppressed bus count with no
        # error. When the position is unresolved we therefore fall back to the
        # authoritative PT-line membership test -- the same test the calibration
        # branch above already uses, precisely because name/type resolution fails
        # on this corridor.
        n = int(AKIVehStateGetNbVehiclesSection(int(idsection), False) or 0)
        vtype = -1
        for i in range(n):
            try:
                sinf = AKIVehGetVehicleStaticInfSection(int(idsection), i)
                if int(getattr(sinf, 'idVeh', -1) or -1) == int(idveh):
                    vtype = int(getattr(sinf, 'type', -1) or -1)
                    break
            except Exception:
                continue
        busp = getattr(stats, '_bus_pos', -1)
        is_bus = bool(busp) and busp > 0 and vtype == busp
        if not is_bus:
            if not (busp and busp > 0):
                if time_now := float(AKIGetCurrentSimulationTime()):
                    if not getattr(m, '_warned_bad_type', False):
                        m._warned_bad_type = True
                        log_to_file(f"[PT-INJ] WARNING: bus type position unresolved "
                                    f"(stats._bus_pos={busp!r}) -- falling back to "
                                    f"PT-line membership for suppression. Demand "
                                    f"SCALING <1.0 will still work, but confirm the "
                                    f"bus count halves before trusting the sweep.",
                                    force=True)
            try:
                _nv = int(AKIGetNbVehiclesFollowingPTLine(int(lid)))
                for _vi in range(_nv):
                    try:
                        if int(AKIGetVehicleFollowingPTLine(int(lid), _vi)) == int(idveh):
                            is_bus = True
                            break
                    except Exception:
                        continue
            except Exception:
                pass
        if not is_bus:
            return 0
        m.set_bus_pos(busp if (busp and busp > 0) else m.bus_pos)

        if m.suppressing:
            if m.should_remove(lid):
                m.queue_removal(idsection, idveh, lid)
                return 0
            _record_schedule_entry(idveh, cand, now)
            m.note_natural(lid, now)
            return 0

        if m.calibrating:
            m.note_natural(lid, now)
        return 0
    except Exception:
        pass
    return 0


def _pt_inj_process_removals():
    """Execute queued suppressions from PostManage context (safe for the kernel)."""
    m = _pt_inj.MANAGER
    if not m.armed:
        return                          # disarmed: nothing was ever queued
    if not hasattr(m, 'pop_pending_removals'):
        return                          # stale module mix -- skip, never crash
    for sec_id, veh_id, _lid in m.pop_pending_removals():
        try:
            n = int(AKIVehStateGetNbVehiclesSection(sec_id, False) or 0)
            idx = -1
            for i in range(n):
                try:
                    inf = AKIVehStateGetVehicleInfSection(sec_id, i)
                    if int(getattr(inf, 'idVeh', -1) or -1) == int(veh_id):
                        idx = i
                        break
                except Exception:
                    continue
            if idx < 0:
                continue                  # already left / removed elsewhere
            AKIRemoveVehicle(int(sec_id), idx)
            m.note_removed()
        except Exception as e:
            _PT_INJ_ERR[0] += 1
            if _PT_INJ_ERR[0] <= 5:
                log_to_file(f"[PT-INJ] removal failed sec={sec_id} veh={veh_id}: {e!r}",
                            )


